//! Names the one database `AppContext::db` holds, as `cfg(axa_db = "...")`, so the
//! code says which it is in one word, and which database libraries are built at all, as
//! `cfg(has_sqlx)`, `cfg(has_seaorm)`, `cfg(has_diesel)`, and `cfg(has_toasty)`.
//!
//! Several database features may be on at once, as `--all-features` turns on every one.
//! Postgres wins, then MySQL, then SQLite, and for each, sqlx wins, because it is not an
//! ORM, then SeaORM, Diesel, and Toasty.

const DATABASES: [&str; 3] = ["postgres", "mysql", "sqlite"];
const LIBRARIES: [&str; 4] = ["sqlx", "seaorm", "diesel", "toasty"];

fn main() {
    let on = |feature: &str| {
        let name = feature.to_ascii_uppercase().replace('-', "_");
        std::env::var_os(format!("CARGO_FEATURE_{name}")).is_some()
    };
    let mut names = vec!["none".to_string()];
    let mut db = "none".to_string();
    for database in DATABASES {
        for library in LIBRARIES {
            let name = format!("{database}_{library}");
            if db == "none" && on(&format!("{database}-{library}")) {
                db.clone_from(&name);
            }
            names.push(name);
        }
    }
    let values: Vec<String> = names.iter().map(|name| format!("\"{name}\"")).collect();
    println!(
        "cargo::rustc-check-cfg=cfg(axa_db, values({}))",
        values.join(", ")
    );
    println!("cargo::rustc-cfg=axa_db=\"{db}\"");
    // A library is built when any database feature on it is. sqlx is also built for the
    // queue, the outbox, and idempotency keys, and for SeaORM, whose errors are read as
    // sqlx's.
    for library in LIBRARIES {
        let mut built = DATABASES
            .iter()
            .any(|database| on(&format!("{database}-{library}")));
        if library == "sqlx" {
            built |= ["queue", "outbox", "idempotency"]
                .iter()
                .any(|feature| on(feature))
                || DATABASES
                    .iter()
                    .any(|database| on(&format!("{database}-seaorm")));
        }
        println!("cargo::rustc-check-cfg=cfg(has_{library})");
        if built {
            println!("cargo::rustc-cfg=has_{library}");
        }
    }
    // Which of sqlx's drivers are built, so that an error can be read as its own
    // database's: Postgres for the queue, the outbox, and idempotency keys, and each
    // database for its sqlx and SeaORM features.
    for database in DATABASES {
        let mut built = ["sqlx", "seaorm"]
            .iter()
            .any(|library| on(&format!("{database}-{library}")));
        if database == "postgres" {
            built |= ["queue", "outbox", "idempotency"]
                .iter()
                .any(|feature| on(feature));
        }
        println!("cargo::rustc-check-cfg=cfg(has_sqlx_{database})");
        if built {
            println!("cargo::rustc-cfg=has_sqlx_{database}");
        }
    }
    println!("cargo::rerun-if-changed=build.rs");
}

//! Header-based API version negotiation.
//!
//! URLs carry no version. A client asks for one with an `Accepts-version`
//! header, and every `/api` response says which version served it.
//!
//! | Request | Result |
//! |---|---|
//! | No header, or an empty one | The current version |
//! | A supported version, or its bare major such as `1` | That version |
//! | Anything else | `406 Not Acceptable`, as an RFC 9457 problem naming what is supported |
//!
//! ```
//! use axa_accepts_version_negotiation::resolve_version;
//!
//! assert_eq!(resolve_version(None), Ok("1.0"));
//! assert_eq!(resolve_version(Some("1")), Ok("1.0"));
//! assert!(resolve_version(Some("9.9")).is_err());
//! ```

use axa_problem::Problem;
use axum::{
    extract::{Request, State},
    http::{HeaderName, HeaderValue, StatusCode},
    middleware::Next,
    response::{IntoResponse, Response},
};

/// The request and response header.
pub const VERSION_HEADER: &str = "accepts-version";

/// The version served when a request names none.
pub const CURRENT_API_VERSION: &str = "1.0";

/// Every version served.
pub const SUPPORTED_API_VERSIONS: &[&str] = &["1.0"];

/// The versions a service serves, for when it serves more than `1.0`.
///
/// ```
/// use axa_accepts_version_negotiation::ApiVersions;
///
/// let versions = ApiVersions::new("2.0", &["2.0", "1.0"]);
/// assert_eq!(versions.resolve(None), Ok("2.0"));
/// assert_eq!(versions.resolve(Some("1")), Ok("1.0"));
/// assert!(versions.resolve(Some("3")).is_err());
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ApiVersions {
    current: &'static str,
    supported: &'static [&'static str],
}

impl Default for ApiVersions {
    fn default() -> Self {
        Self {
            current: CURRENT_API_VERSION,
            supported: SUPPORTED_API_VERSIONS,
        }
    }
}

impl ApiVersions {
    /// Serve `supported`, with `current` for a request that names none. A bare major
    /// means the first version listed with that major, so list the newest first.
    ///
    /// # Panics
    ///
    /// If `supported` does not hold `current`. This is fixed in code, so it is a
    /// mistake to find at boot rather than on a request.
    #[must_use]
    pub fn new(current: &'static str, supported: &'static [&'static str]) -> Self {
        assert!(
            supported.contains(&current),
            "the current API version must be supported"
        );
        Self { current, supported }
    }

    /// Resolve a requested version to a supported one.
    ///
    /// # Errors
    ///
    /// Returns the trimmed, lowercased request when no supported version matches.
    pub fn resolve(&self, requested: Option<&str>) -> Result<&'static str, String> {
        let Some(raw) = requested else {
            return Ok(self.current);
        };
        let want = raw.trim().to_ascii_lowercase();
        if want.is_empty() {
            return Ok(self.current);
        }
        self.supported
            .iter()
            .copied()
            .find(|&version| {
                version.eq_ignore_ascii_case(&want)
                    || version
                        .split_once('.')
                        .is_some_and(|(major, _)| major == want)
            })
            .ok_or(want)
    }
}

/// Resolve a requested version to a supported one, of the default versions.
///
/// # Errors
///
/// Returns the trimmed, lowercased request when no supported version matches.
pub fn resolve_version(requested: Option<&str>) -> Result<&'static str, String> {
    ApiVersions::default().resolve(requested)
}

/// Whether `path` is under the versioned `/api` surface. FHIR, health, and
/// documentation routes are not.
#[must_use]
pub fn is_versioned_path(path: &str) -> bool {
    path == "/api" || path.starts_with("/api/")
}

/// Middleware that negotiates the default versions for `/api` paths.
pub async fn require_version_mw(req: Request, next: Next) -> Response {
    negotiate(ApiVersions::default(), req, next).await
}

/// [`require_version_mw`] for a service's own versions, as state.
pub async fn negotiate_versions(
    State(versions): State<ApiVersions>,
    req: Request,
    next: Next,
) -> Response {
    negotiate(versions, req, next).await
}

async fn negotiate(versions: ApiVersions, req: Request, next: Next) -> Response {
    if !is_versioned_path(req.uri().path()) {
        return next.run(req).await;
    }
    let requested = req
        .headers()
        .get(VERSION_HEADER)
        .and_then(|value| value.to_str().ok())
        .map(str::to_owned);
    match versions.resolve(requested.as_deref()) {
        Ok(resolved) => {
            let mut response = next.run(req).await;
            response.headers_mut().insert(
                HeaderName::from_static(VERSION_HEADER),
                HeaderValue::from_static(resolved),
            );
            response
        }
        Err(bad) => Problem::new(StatusCode::NOT_ACCEPTABLE)
            .with_extension("code", "unsupported_api_version".into())
            .with_extension("requested", bad.into())
            .with_extension("supported", serde_json::json!(versions.supported))
            .into_response(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::{Router, body::Body, http, middleware::from_fn, routing::get};
    use tower::ServiceExt;

    #[tokio::test]
    async fn a_service_can_serve_its_own_versions() {
        let versions = ApiVersions::new("2.0", &["2.0", "1.0"]);
        let app = Router::new()
            .route("/api/things", get(|| async { "ok" }))
            .layer(axum::middleware::from_fn_with_state(
                versions,
                negotiate_versions,
            ));
        let call = |version: &'static str| {
            let app = app.clone();
            async move {
                let request = http::Request::get("/api/things").header(VERSION_HEADER, version);
                app.oneshot(request.body(Body::empty()).unwrap())
                    .await
                    .unwrap()
            }
        };
        assert_eq!(call("1").await.headers()[VERSION_HEADER], "1.0");
        assert_eq!(call("2.0").await.headers()[VERSION_HEADER], "2.0");
        assert_eq!(call("3").await.status(), http::StatusCode::NOT_ACCEPTABLE);
    }

    #[test]
    #[should_panic(expected = "must be supported")]
    fn a_current_version_that_is_not_supported_is_a_mistake() {
        let _ = ApiVersions::new("2.0", &["1.0"]);
    }

    fn app() -> Router {
        Router::new()
            .route("/api/things", get(|| async { "ok" }))
            .route("/fhir/metadata", get(|| async { "ok" }))
            .layer(from_fn(require_version_mw))
    }

    async fn call(path: &str, version: Option<&str>) -> Response {
        let mut request = http::Request::builder().uri(path);
        if let Some(version) = version {
            request = request.header(VERSION_HEADER, version);
        }
        app()
            .oneshot(request.body(Body::empty()).unwrap())
            .await
            .unwrap()
    }

    #[test]
    fn no_header_means_the_current_version() {
        assert_eq!(resolve_version(None), Ok(CURRENT_API_VERSION));
        assert_eq!(resolve_version(Some("   ")), Ok(CURRENT_API_VERSION));
    }

    #[test]
    fn a_bare_major_is_an_alias() {
        assert_eq!(resolve_version(Some(" 1 ")), Ok("1.0"));
    }

    #[test]
    fn an_unsupported_version_is_returned_for_the_error() {
        assert_eq!(resolve_version(Some(" 2.0 ")), Err("2.0".to_string()));
    }

    #[test]
    fn only_api_paths_are_versioned() {
        assert!(is_versioned_path("/api"));
        assert!(is_versioned_path("/api/things"));
        assert!(!is_versioned_path("/apiary"));
        assert!(!is_versioned_path("/fhir/metadata"));
    }

    #[tokio::test]
    async fn the_resolved_version_is_echoed() {
        let response = call("/api/things", None).await;
        assert_eq!(response.headers()[VERSION_HEADER], "1.0");
    }

    #[tokio::test]
    async fn an_unsupported_version_is_a_406() {
        let response = call("/api/things", Some("9.9")).await;
        assert_eq!(response.status(), StatusCode::NOT_ACCEPTABLE);
        assert_eq!(
            response.headers()[http::header::CONTENT_TYPE],
            axa_problem::PROBLEM_JSON
        );
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        assert_eq!(
            bytes,
            r#"{"type":"about:blank","title":"Not Acceptable","status":406,"code":"unsupported_api_version","requested":"9.9","supported":["1.0"]}"#
        );
    }

    #[tokio::test]
    async fn paths_outside_api_ignore_the_header() {
        let response = call("/fhir/metadata", Some("9.9")).await;
        assert_eq!(response.status(), StatusCode::OK);
        assert!(!response.headers().contains_key(VERSION_HEADER));
    }
}

//! Opaque API tokens: a prefix, an id, and a secret kept only as its SHA-256 hash, with
//! scopes, an expiry, and the time of last use.
//!
//! A token reads `crm_<id>_<secret>`. The prefix names the service, so a secret
//! scanner can find a leaked one. The id is the row's key. The secret, 62 hex
//! digits holding 244 random bits, is shown once, when the token is issued, and only its hash is stored, so
//! a copy of the table lets no one in.
//!
//! ```
//! use std::time::{Duration, SystemTime};
//! use axa_api_tokens::{Prefix, Record, Scope, issue, parse_bearer};
//!
//! let prefix = Prefix::new("crm").unwrap();
//! let issued = issue(&prefix);
//! // Show `issued.token()` to its owner once; store the rest.
//! let now = SystemTime::now();
//! let record = Record {
//!     id: issued.id().to_string(),
//!     hash: issued.hash().to_string(),
//!     scopes: vec![Scope::new("contacts:read").unwrap()],
//!     expires_at: Some(now + Duration::from_hours(24 * 90)),
//!     revoked: false,
//!     last_used_at: None,
//! };
//!
//! // On a request: parse, find the record by id, then verify.
//! let header = format!("Bearer {}", issued.token());
//! let presented = parse_bearer(&header, &prefix).unwrap();
//! assert_eq!(presented.id(), record.id);
//! let verified = record.verify(&presented, now).unwrap();
//! assert!(verified.allows("contacts:read"));
//! assert!(!verified.allows("contacts:write"));
//! ```
//!
//! [`Verified::record_use`] says when to write `last_used_at`, at most once a minute
//! per token, so a busy token does not write on every request.

use std::{
    fmt,
    time::{Duration, SystemTime},
};

use sha2::{Digest, Sha256};
use uuid::Uuid;

/// The shortest gap between two writes of a token's last use.
pub const USE_RECORD_INTERVAL: Duration = Duration::from_mins(1);

/// Why a token or a part of one was refused.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum Error {
    /// A prefix that is not 2 to 16 lowercase ASCII letters and digits, starting with a
    /// letter.
    #[error("a token prefix must be 2 to 16 lowercase letters and digits, starting with a letter")]
    BadPrefix,
    /// A scope that is not 1 to 64 lowercase ASCII letters, digits, `:`, `.`, `_`, or `-`.
    #[error("a scope must be 1 to 64 lowercase letters, digits, or : . _ -")]
    BadScope,
}

/// Why a presented token was refused. Tell the caller only that it was, with a `401`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum Refused {
    /// The token is not this record's.
    #[error("the token does not match")]
    Mismatch,
    /// The record was revoked.
    #[error("the token was revoked")]
    Revoked,
    /// The record has expired.
    #[error("the token has expired")]
    Expired,
}

/// The service's part of every token, such as `crm`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Prefix(String);

impl Prefix {
    /// A prefix of 2 to 16 lowercase ASCII letters and digits, starting with a letter.
    ///
    /// # Errors
    ///
    /// [`Error::BadPrefix`] for anything else.
    pub fn new(prefix: &str) -> Result<Self, Error> {
        let fits = (2..=16).contains(&prefix.len())
            && prefix.starts_with(|c: char| c.is_ascii_lowercase())
            && prefix
                .bytes()
                .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit());
        if fits {
            Ok(Self(prefix.to_string()))
        } else {
            Err(Error::BadPrefix)
        }
    }

    /// The prefix.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// One thing a token may do, such as `contacts:read`.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Scope(String);

impl Scope {
    /// A scope of 1 to 64 lowercase ASCII letters, digits, `:`, `.`, `_`, or `-`.
    ///
    /// # Errors
    ///
    /// [`Error::BadScope`] for anything else.
    pub fn new(scope: &str) -> Result<Self, Error> {
        let fits = (1..=64).contains(&scope.len())
            && scope
                .bytes()
                .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b":._-".contains(&b));
        if fits {
            Ok(Self(scope.to_string()))
        } else {
            Err(Error::BadScope)
        }
    }

    /// The scope.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// A token just issued: the whole token to show its owner once, and the id and hash to
/// store.
pub struct Issued {
    token: String,
    id: String,
    hash: String,
}

impl fmt::Debug for Issued {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // The id and hash may be shown, and the token never.
        f.debug_struct("Issued")
            .field("id", &self.id)
            .field("hash", &self.hash)
            .finish_non_exhaustive()
    }
}

impl Issued {
    /// The whole token, to show its owner once. Never store or log it.
    #[must_use]
    pub fn token(&self) -> &str {
        &self.token
    }

    /// The id, the record's key.
    #[must_use]
    pub fn id(&self) -> &str {
        &self.id
    }

    /// The SHA-256 hash of the secret, as 64 lowercase hex digits, to store.
    #[must_use]
    pub fn hash(&self) -> &str {
        &self.hash
    }
}

/// The hex digits of a random v4 uuid, its fixed version and variant digits left out.
fn random_hex() -> String {
    let hex = Uuid::new_v4().simple().to_string();
    // Digit 12 is the version, always `4`, and digit 16 holds the variant bits.
    hex.char_indices()
        .filter(|(index, _)| *index != 12)
        .map(|(_, digit)| digit)
        .collect()
}

const HEX_DIGITS: &[u8; 16] = b"0123456789abcdef";

fn hash_hex(secret: &str) -> String {
    let digest = Sha256::digest(secret.as_bytes());
    let mut hex = String::with_capacity(digest.len() * 2);
    for byte in digest {
        hex.push(char::from(HEX_DIGITS[usize::from(byte >> 4)]));
        hex.push(char::from(HEX_DIGITS[usize::from(byte & 0xf)]));
    }
    hex
}

/// Issue a new token under `prefix`.
#[must_use]
pub fn issue(prefix: &Prefix) -> Issued {
    let id = Uuid::new_v4().simple().to_string();
    let secret = format!("{}{}", random_hex(), random_hex());
    let hash = hash_hex(&secret);
    Issued {
        token: format!("{}_{id}_{secret}", prefix.as_str()),
        id,
        hash,
    }
}

/// A token sent by a caller, split, and not yet checked against its record.
pub struct Presented {
    id: String,
    secret: String,
}

impl fmt::Debug for Presented {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Presented")
            .field("id", &self.id)
            .finish_non_exhaustive()
    }
}

impl Presented {
    /// The id, to find the record by.
    #[must_use]
    pub fn id(&self) -> &str {
        &self.id
    }
}

/// Split `token` into its id and secret, or `None` when it is not a token under
/// `prefix`: three parts, the id 32 hex digits and the secret 62.
#[must_use]
pub fn parse(token: &str, prefix: &Prefix) -> Option<Presented> {
    let rest = token.strip_prefix(prefix.as_str())?.strip_prefix('_')?;
    let (id, secret) = rest.split_once('_')?;
    let hex = |text: &str, length: usize| {
        text.len() == length
            && text
                .bytes()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
    };
    (hex(id, 32) && hex(secret, 62)).then(|| Presented {
        id: id.to_string(),
        secret: secret.to_string(),
    })
}

/// [`parse`] the token in an `authorization` header value, `Bearer <token>`, its
/// scheme in any case.
#[must_use]
pub fn parse_bearer(authorization: &str, prefix: &Prefix) -> Option<Presented> {
    let (scheme, token) = authorization.split_once(' ')?;
    if !scheme.eq_ignore_ascii_case("bearer") {
        return None;
    }
    parse(token.trim_start_matches(' '), prefix)
}

/// What a service keeps of one token, in its own table.
#[derive(Debug, Clone)]
pub struct Record {
    /// The id, from [`Issued::id`].
    pub id: String,
    /// The hash, from [`Issued::hash`].
    pub hash: String,
    /// What the token may do.
    pub scopes: Vec<Scope>,
    /// When it stops working, if ever.
    pub expires_at: Option<SystemTime>,
    /// Whether it was revoked.
    pub revoked: bool,
    /// When it was last used, if it has been.
    pub last_used_at: Option<SystemTime>,
}

/// Compare in time that depends only on the length of `expected`.
fn same_bytes(expected: &[u8], sent: &[u8]) -> bool {
    let mut difference = u8::from(expected.len() != sent.len());
    for (index, byte) in expected.iter().enumerate() {
        difference |= byte ^ sent.get(index).copied().unwrap_or(0);
    }
    difference == 0
}

impl Record {
    /// Check `presented` against this record at `now`: the secret's hash, compared in
    /// constant time, then revocation, then expiry.
    ///
    /// # Errors
    ///
    /// [`Refused`] says why, for the service's own log. Answer every one with the same
    /// `401`.
    pub fn verify(&self, presented: &Presented, now: SystemTime) -> Result<Verified, Refused> {
        let matches = same_bytes(self.hash.as_bytes(), hash_hex(&presented.secret).as_bytes())
            & same_bytes(self.id.as_bytes(), presented.id.as_bytes());
        if !matches {
            return Err(Refused::Mismatch);
        }
        if self.revoked {
            return Err(Refused::Revoked);
        }
        if self.expires_at.is_some_and(|at| at <= now) {
            return Err(Refused::Expired);
        }
        let record_use = self.last_used_at.is_none_or(|at| {
            now.duration_since(at)
                .is_ok_and(|since| since >= USE_RECORD_INTERVAL)
        });
        Ok(Verified {
            id: self.id.clone(),
            scopes: self.scopes.clone(),
            record_use,
        })
    }
}

/// A token that passed, with what it may do.
#[derive(Debug, Clone)]
pub struct Verified {
    id: String,
    scopes: Vec<Scope>,
    record_use: bool,
}

impl Verified {
    /// The token's id.
    #[must_use]
    pub fn id(&self) -> &str {
        &self.id
    }

    /// Whether the token may do `scope`.
    #[must_use]
    pub fn allows(&self, scope: &str) -> bool {
        self.scopes.iter().any(|held| held.as_str() == scope)
    }

    /// Whether to write `last_used_at` now: when it was never used, or last recorded
    /// [`USE_RECORD_INTERVAL`] ago or more.
    #[must_use]
    pub const fn record_use(&self) -> bool {
        self.record_use
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn prefix() -> Prefix {
        Prefix::new("crm").unwrap()
    }

    fn record(issued: &Issued) -> Record {
        Record {
            id: issued.id().to_string(),
            hash: issued.hash().to_string(),
            scopes: vec![Scope::new("contacts:read").unwrap()],
            expires_at: None,
            revoked: false,
            last_used_at: None,
        }
    }

    #[test]
    fn an_issued_token_has_the_prefix_and_only_its_hash_is_kept() {
        let issued = issue(&prefix());
        let token = issued.token();
        assert!(token.starts_with("crm_"), "{token}");
        assert_eq!(token.len(), "crm_".len() + 32 + 1 + 62);
        let secret = token.rsplit('_').next().unwrap();
        assert_eq!(issued.hash(), hash_hex(secret));
        assert_eq!(issued.hash().len(), 64);
        assert!(!issued.hash().contains(secret));
        let shown = format!("{issued:?}");
        assert!(!shown.contains(secret), "{shown}");
        let other = issue(&prefix());
        assert_ne!(other.token(), issued.token());
        assert_ne!(other.id(), issued.id());
    }

    #[test]
    fn a_token_verifies_against_its_own_record_only() {
        let issued = issue(&prefix());
        let presented = parse(issued.token(), &prefix()).unwrap();
        let verified = record(&issued)
            .verify(&presented, SystemTime::now())
            .unwrap();
        assert_eq!(verified.id(), issued.id());
        assert!(verified.allows("contacts:read"));
        assert!(!verified.allows("contacts:write"));
        let other = issue(&prefix());
        assert_eq!(
            record(&other)
                .verify(&presented, SystemTime::now())
                .unwrap_err(),
            Refused::Mismatch
        );
        // A secret changed in its last digit.
        let mut changed = issued.token().to_string();
        let last = changed.pop().unwrap();
        changed.push(if last == '0' { '1' } else { '0' });
        let presented = parse(&changed, &prefix()).unwrap();
        assert_eq!(
            record(&issued)
                .verify(&presented, SystemTime::now())
                .unwrap_err(),
            Refused::Mismatch
        );
    }

    #[test]
    fn a_revoked_or_expired_token_is_refused() {
        let issued = issue(&prefix());
        let presented = parse(issued.token(), &prefix()).unwrap();
        let now = SystemTime::now();
        let revoked = Record {
            revoked: true,
            ..record(&issued)
        };
        assert_eq!(
            revoked.verify(&presented, now).unwrap_err(),
            Refused::Revoked
        );
        let expired = Record {
            expires_at: Some(now),
            ..record(&issued)
        };
        assert_eq!(
            expired.verify(&presented, now).unwrap_err(),
            Refused::Expired
        );
        let later = Record {
            expires_at: Some(now + Duration::from_secs(1)),
            ..record(&issued)
        };
        assert!(later.verify(&presented, now).is_ok());
    }

    #[test]
    fn last_use_is_recorded_at_most_once_a_minute() {
        let issued = issue(&prefix());
        let presented = parse(issued.token(), &prefix()).unwrap();
        let now = SystemTime::now();
        assert!(
            record(&issued)
                .verify(&presented, now)
                .unwrap()
                .record_use()
        );
        let recent = Record {
            last_used_at: Some(now - Duration::from_secs(30)),
            ..record(&issued)
        };
        assert!(!recent.verify(&presented, now).unwrap().record_use());
        let older = Record {
            last_used_at: Some(now - USE_RECORD_INTERVAL),
            ..record(&issued)
        };
        assert!(older.verify(&presented, now).unwrap().record_use());
    }

    #[test]
    fn only_a_well_formed_token_under_the_prefix_parses() {
        let issued = issue(&prefix());
        let token = issued.token();
        assert!(parse(token, &prefix()).is_some());
        assert!(parse_bearer(&format!("Bearer {token}"), &prefix()).is_some());
        assert!(parse_bearer(&format!("bearer  {token}"), &prefix()).is_some());
        assert!(parse_bearer(&format!("Basic {token}"), &prefix()).is_none());
        assert!(parse(token, &Prefix::new("ppm").unwrap()).is_none());
        for bad in [
            String::new(),
            "crm_".to_string(),
            token.to_uppercase(),
            format!("{token}0"),
            token[..token.len() - 1].to_string(),
            token.replacen('_', "-", 1),
            format!("{token}_x"),
        ] {
            assert!(parse(&bad, &prefix()).is_none(), "{bad}");
        }
    }

    #[test]
    fn prefixes_and_scopes_are_short_codes() {
        for good in ["crm", "ab", "wpm2", "abcdefghijklmnop"] {
            assert!(Prefix::new(good).is_ok(), "{good}");
        }
        for bad in ["", "c", "Crm", "2crm", "crm_", "abcdefghijklmnopq"] {
            assert_eq!(Prefix::new(bad), Err(Error::BadPrefix), "{bad}");
        }
        for good in ["contacts:read", "jobs.run", "a", "x-y_z"] {
            assert!(Scope::new(good).is_ok(), "{good}");
        }
        for bad in ["", "Contacts", "a b", "a\n", &"x".repeat(65)] {
            assert_eq!(Scope::new(bad), Err(Error::BadScope), "{bad}");
        }
    }

    #[test]
    fn a_secret_has_the_randomness_of_two_uuids() {
        let hex = random_hex();
        assert_eq!(hex.len(), 31);
        assert!(hex.bytes().all(|b| b.is_ascii_hexdigit()));
    }
}

//! Signed cursor pagination with no total, and `LIKE` escaping.
//!
//! A collection read takes `?limit=` and an opaque `?cursor=`. When more rows
//! follow, the response carries `Link: <...>; rel="next"`, and the last page
//! carries none. The body is a bare JSON array, and there is no total, because a
//! total would count rows the caller's record policy hides.
//!
//! A cursor is signed with the service's [`CursorKey`], over its position and the
//! query it belongs to: the path and every query parameter but `cursor` and
//! `limit`. So a caller cannot make one up, edit one, or carry one to another
//! list or filter, and may change `limit` between pages. A bad cursor or a bad
//! limit is a [`PageError`], which is the caller's to fix and answers `422`.
//!
//! The position is an offset. A row added or removed between two fetches can make
//! a later page skip or repeat one row, so order every list by something that
//! ends in a unique column, such as `ORDER BY created_at, id`, so that the order
//! itself is stable.

use std::fmt;

use axum::{
    Json,
    http::{HeaderValue, StatusCode, Uri, header::LINK},
    response::{IntoResponse, Response},
};
use base64::{Engine, engine::general_purpose::URL_SAFE_NO_PAD};
use hmac::{Hmac, KeyInit, Mac};
use serde::Serialize;
use sha2::{Digest, Sha256};

/// The shortest secret [`CursorKey::new`] accepts, in bytes.
pub const MIN_KEY_LEN: usize = 32;

/// The first byte of every cursor, so the format can change.
const VERSION: u8 = 1;
const POSITION_LEN: usize = 8;
const TAG_LEN: usize = 32;
const CURSOR_LEN: usize = 1 + POSITION_LEN + TAG_LEN;

/// The service's secret for signing cursors. Its `Debug` never shows the key.
#[derive(Clone)]
pub struct CursorKey {
    mac: Hmac<Sha256>,
}

impl fmt::Debug for CursorKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("CursorKey(..)")
    }
}

/// A secret shorter than [`MIN_KEY_LEN`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct KeyTooShort {
    /// The length given, in bytes.
    pub len: usize,
}

impl fmt::Display for KeyTooShort {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "a cursor key needs at least {MIN_KEY_LEN} bytes, and this has {}",
            self.len
        )
    }
}

impl std::error::Error for KeyTooShort {}

impl CursorKey {
    /// A key from `secret`, which must be at least [`MIN_KEY_LEN`] bytes. Keep it
    /// as secret as a session key: anyone holding it can make cursors.
    ///
    /// # Errors
    ///
    /// [`KeyTooShort`] when `secret` is shorter than [`MIN_KEY_LEN`].
    pub fn new(secret: &[u8]) -> Result<Self, KeyTooShort> {
        if secret.len() < MIN_KEY_LEN {
            return Err(KeyTooShort { len: secret.len() });
        }
        let mac = Hmac::<Sha256>::new_from_slice(secret)
            .map_err(|_| KeyTooShort { len: secret.len() })?;
        Ok(Self { mac })
    }

    fn tag(&self, position: u64, query: &[u8; 32]) -> Hmac<Sha256> {
        let mut mac = self.mac.clone();
        mac.update(&[VERSION]);
        mac.update(&position.to_be_bytes());
        mac.update(query);
        mac
    }

    fn encode(&self, position: u64, query: &[u8; 32]) -> String {
        let mut bytes = Vec::with_capacity(CURSOR_LEN);
        bytes.push(VERSION);
        bytes.extend_from_slice(&position.to_be_bytes());
        bytes.extend_from_slice(&self.tag(position, query).finalize().into_bytes());
        URL_SAFE_NO_PAD.encode(bytes)
    }

    fn decode(&self, cursor: &str, query: &[u8; 32]) -> Option<u64> {
        let bytes = URL_SAFE_NO_PAD.decode(cursor).ok()?;
        if bytes.len() != CURSOR_LEN || bytes[0] != VERSION {
            return None;
        }
        let position = u64::from_be_bytes(bytes[1..=POSITION_LEN].try_into().ok()?);
        // Constant time, so a caller cannot learn the tag a byte at a time.
        self.tag(position, query)
            .verify_slice(&bytes[1 + POSITION_LEN..])
            .ok()?;
        Some(position)
    }
}

/// The page sizes of one endpoint.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CursorLimits {
    /// The limit when none is given.
    pub default_limit: u64,
    /// The largest limit accepted. A larger one is refused, not clamped.
    pub max_limit: u64,
}

/// Why a page request was refused. Each is the caller's to fix, so each answers
/// `422`, and none quotes what the caller sent.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum PageError {
    /// A limit that is zero, not a number, given twice, or above the maximum.
    BadLimit {
        /// The largest limit accepted.
        max_limit: u64,
    },
    /// A cursor that is malformed, carries a bad signature, is given twice, or
    /// belongs to another query.
    BadCursor,
}

impl PageError {
    /// The status to answer with, which is always `422`.
    #[must_use]
    pub const fn status(&self) -> StatusCode {
        StatusCode::UNPROCESSABLE_ENTITY
    }
}

impl fmt::Display for PageError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::BadLimit { max_limit } => {
                write!(f, "limit must be a whole number from 1 to {max_limit}")
            }
            Self::BadCursor => f.write_str("cursor is not valid"),
        }
    }
}

impl std::error::Error for PageError {}

/// One page of a list, read from the request's URI and checked.
///
/// ```
/// use axa_cursor_pagination::{CursorKey, CursorLimits, CursorPage};
///
/// let key = CursorKey::new(&[7; 32]).unwrap();
/// let limits = CursorLimits { default_limit: 50, max_limit: 200 };
/// let uri = "/things?status=open&limit=2".parse().unwrap();
/// let page = CursorPage::new(&key, limits, &uri).unwrap();
/// assert_eq!(page.bounds(), (3, 0)); // one more row than asked, to see if more follow
///
/// let response = page.respond(vec!["a", "b", "c"]);
/// let link = response.headers()["link"].to_str().unwrap();
/// assert!(link.starts_with("</things?status=open&limit=2&cursor="));
/// assert!(link.ends_with(r#">; rel="next""#));
/// ```
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CursorPage {
    limit: u64,
    offset: u64,
    next: String,
}

/// The query a cursor belongs to: the path and the parameters other than
/// `cursor` and `limit`, sorted so that their order does not matter, and the context,
/// if any. An empty context adds nothing, so the cursors [`CursorPage::new`] makes are
/// those it made before contexts were added. A context is marked by a byte no query
/// part can hold, and its length, so no context reads as another or as a filter.
fn query_hash(path: &str, kept: &[&str], context: &str) -> [u8; 32] {
    let mut sorted = kept.to_vec();
    sorted.sort_unstable();
    let mut hash = Sha256::new();
    hash.update(path.as_bytes());
    for part in sorted {
        hash.update([0]);
        hash.update(part.as_bytes());
    }
    if !context.is_empty() {
        hash.update([1]);
        hash.update((context.len() as u64).to_be_bytes());
        hash.update(context.as_bytes());
    }
    hash.finalize().into()
}

fn name(part: &str) -> &str {
    part.split_once('=').map_or(part, |(name, _)| name)
}

fn value(part: &str) -> &str {
    part.split_once('=').map_or("", |(_, value)| value)
}

impl CursorPage {
    /// Read `limit` and `cursor` from `uri`, the request's URI.
    ///
    /// # Errors
    ///
    /// [`PageError::BadLimit`] for a limit that is zero, not a number, above
    /// `limits.max_limit`, or given twice. [`PageError::BadCursor`] for a cursor
    /// that this key did not sign for this path and these filters.
    pub fn new(key: &CursorKey, limits: CursorLimits, uri: &Uri) -> Result<Self, PageError> {
        Self::new_in(key, limits, uri, "")
    }

    /// As [`CursorPage::new`], with cursors that hold only in `context`, such as the
    /// caller's tenant. A cursor made in one context is a [`PageError::BadCursor`] in
    /// any other, so a cursor carried from one tenant to another is refused even where
    /// a query forgets to filter by tenant. An empty context is as [`CursorPage::new`].
    ///
    /// ```
    /// use axa_cursor_pagination::{CursorKey, CursorLimits, CursorPage, PageError};
    ///
    /// let key = CursorKey::new(&[7; 32]).unwrap();
    /// let limits = CursorLimits { default_limit: 50, max_limit: 200 };
    /// let first = CursorPage::new_in(&key, limits, &"/todos?limit=1".parse().unwrap(), "acme").unwrap();
    /// let link = first.next_link().unwrap();
    /// let next = link.to_str().unwrap().trim_start_matches('<').split('>').next().unwrap();
    /// let uri = next.parse().unwrap();
    /// assert!(CursorPage::new_in(&key, limits, &uri, "acme").is_ok());
    /// assert_eq!(CursorPage::new_in(&key, limits, &uri, "globex"), Err(PageError::BadCursor));
    /// ```
    ///
    /// # Errors
    ///
    /// As [`CursorPage::new`], and [`PageError::BadCursor`] for a cursor signed for
    /// another context.
    pub fn new_in(
        key: &CursorKey,
        limits: CursorLimits,
        uri: &Uri,
        context: &str,
    ) -> Result<Self, PageError> {
        let parts: Vec<&str> = uri
            .query()
            .unwrap_or("")
            .split('&')
            .filter(|part| !part.is_empty())
            .collect();
        let named = |wanted: &str| -> Vec<&str> {
            parts
                .iter()
                .filter(|part| name(part) == wanted)
                .map(|part| value(part))
                .collect()
        };
        let bad_limit = PageError::BadLimit {
            max_limit: limits.max_limit,
        };
        let limit = match named("limit").as_slice() {
            [] => limits.default_limit,
            [raw] => raw
                .parse::<u64>()
                .ok()
                .filter(|limit| (1..=limits.max_limit).contains(limit))
                .ok_or(bad_limit)?,
            _ => return Err(bad_limit),
        };
        let kept: Vec<&str> = parts
            .iter()
            .copied()
            .filter(|part| !matches!(name(part), "cursor" | "limit"))
            .collect();
        let query = query_hash(uri.path(), &kept, context);
        let offset = match named("cursor").as_slice() {
            [] => 0,
            [cursor] => key.decode(cursor, &query).ok_or(PageError::BadCursor)?,
            _ => return Err(PageError::BadCursor),
        };

        let next_cursor = key.encode(offset.saturating_add(limit), &query);
        let mut next_query: Vec<&str> = parts
            .iter()
            .copied()
            .filter(|part| name(part) != "cursor")
            .collect();
        let cursor_part = format!("cursor={next_cursor}");
        next_query.push(&cursor_part);
        let next = format!("<{}?{}>; rel=\"next\"", uri.path(), next_query.join("&"));
        Ok(Self {
            limit,
            offset,
            next,
        })
    }

    /// Rows to return.
    #[must_use]
    pub const fn limit(&self) -> u64 {
        self.limit
    }

    /// Rows to skip.
    #[must_use]
    pub const fn offset(&self) -> u64 {
        self.offset
    }

    /// `LIMIT` and `OFFSET` as Postgres takes them, which is as signed numbers.
    /// The limit is one more than the page, so that [`CursorPage::split`] can tell
    /// whether more rows follow. A value too large for `i64` saturates, so an offset
    /// past every row is an empty page, not a failed query.
    #[must_use]
    pub fn bounds(&self) -> (i64, i64) {
        (
            i64::try_from(self.limit.saturating_add(1)).unwrap_or(i64::MAX),
            i64::try_from(self.offset).unwrap_or(i64::MAX),
        )
    }

    /// Drop the extra row [`CursorPage::bounds`] asked for. The flag says whether
    /// more rows follow.
    #[must_use]
    pub fn split<T>(&self, mut rows: Vec<T>) -> (Vec<T>, bool) {
        let keep = usize::try_from(self.limit).unwrap_or(usize::MAX);
        let more = rows.len() > keep;
        rows.truncate(keep);
        (rows, more)
    }

    /// The `Link` header for the next page.
    #[must_use]
    pub fn next_link(&self) -> Option<HeaderValue> {
        HeaderValue::from_str(&self.next).ok()
    }

    /// `rows`, fetched with [`CursorPage::bounds`], as a bare JSON array, with
    /// `Link: rel="next"` when more rows follow. There is no total.
    #[must_use]
    pub fn respond<T: Serialize>(&self, rows: Vec<T>) -> Response {
        let (rows, more) = self.split(rows);
        let mut response = Json(rows).into_response();
        if more && let Some(link) = self.next_link() {
            response.headers_mut().insert(LINK, link);
        }
        response
    }
}

/// Escape `%`, `_`, and `\` so user text matches literally in a `LIKE`
/// pattern. Bind the result as a parameter with `ESCAPE '\'`.
///
/// ```
/// assert_eq!(axa_cursor_pagination::escape_like("100%_a"), r"100\%\_a");
/// ```
#[must_use]
pub fn escape_like(text: &str) -> String {
    // Backslash first, so the escapes added below are not escaped again.
    text.replace('\\', "\\\\")
        .replace('%', "\\%")
        .replace('_', "\\_")
}

#[cfg(test)]
mod tests {
    use super::*;

    const LIMITS: CursorLimits = CursorLimits {
        default_limit: 10,
        max_limit: 50,
    };

    fn key() -> CursorKey {
        CursorKey::new(b"a service secret of thirty-two b").unwrap()
    }

    fn page(uri: &str) -> Result<CursorPage, PageError> {
        CursorPage::new(&key(), LIMITS, &uri.parse().unwrap())
    }

    /// The cursor in a page's next link.
    fn next_cursor(page: &CursorPage) -> String {
        let link = page.next.clone();
        let start = link.find("cursor=").unwrap() + "cursor=".len();
        let end = link[start..].find(['&', '>']).unwrap() + start;
        link[start..end].to_string()
    }

    #[test]
    fn a_cursor_made_in_one_context_is_refused_in_another() {
        let in_context = |uri: &str, context: &str| {
            CursorPage::new_in(&key(), LIMITS, &uri.parse().unwrap(), context)
        };
        let first = in_context("/todos?status=open", "acme").unwrap();
        let next = format!("/todos?status=open&cursor={}", next_cursor(&first));
        assert_eq!(in_context(&next, "acme").unwrap().offset(), 10);
        for other in ["globex", "acme ", "acm", ""] {
            assert_eq!(
                in_context(&next, other),
                Err(PageError::BadCursor),
                "{other:?}"
            );
        }
        assert_eq!(page(&next), Err(PageError::BadCursor));

        // No context is the cursor `new` has always made, so old cursors still hold.
        let plain = page("/todos?status=open").unwrap();
        let next = format!("/todos?status=open&cursor={}", next_cursor(&plain));
        assert_eq!(in_context(&next, "").unwrap().offset(), 10);
        assert_eq!(in_context(&next, "acme"), Err(PageError::BadCursor));
        // The cursor `new` makes for a fixed key and query, worked out apart from this
        // code as the crate made it before contexts were added.
        assert_eq!(
            next_cursor(&page("/things").unwrap()),
            "AQAAAAAAAAAKZZFSvWeCDy_beDgOauJnX_EjAV2tWtfGim0KJozjf_I"
        );
    }

    #[test]
    fn a_missing_limit_uses_the_default_and_the_first_page_starts_at_zero() {
        let page = page("/things").unwrap();
        assert_eq!((page.limit(), page.offset()), (10, 0));
    }

    #[test]
    fn there_is_no_offset_parameter() {
        // PAG-7: `?offset=` is only a filter like any other, so it moves nothing,
        // and a cursor made without it does not fit a query that has it.
        let page = page("/things?offset=40").unwrap();
        assert_eq!(page.offset(), 0);
    }

    #[test]
    fn a_response_carries_no_total() {
        // PAG-7 and PAG-10.
        let response = page("/things?limit=2").unwrap().respond(vec![1, 2, 3]);
        for header in ["x-total-count", "x-limit", "x-offset"] {
            assert!(response.headers().get(header).is_none(), "{header}");
        }
    }

    #[test]
    fn the_next_page_is_a_link_and_the_last_page_has_none() {
        // PAG-8.
        let page = page("/things?status=open&limit=2").unwrap();
        let more = page.respond(vec![1, 2, 3]);
        assert_eq!(more.status(), StatusCode::OK);
        let link = more.headers()[LINK].to_str().unwrap();
        assert_eq!(
            link,
            format!(
                "</things?status=open&limit=2&cursor={}>; rel=\"next\"",
                next_cursor(&page)
            )
        );
        let last = page.respond(vec![1, 2]);
        assert!(last.headers().get(LINK).is_none());
    }

    #[test]
    fn a_body_is_a_bare_json_array_of_the_page() {
        let response = page("/things?limit=2")
            .unwrap()
            .respond(vec!["a", "b", "c"]);
        assert_eq!(response.headers()["content-type"], "application/json");
        let (rows, more) = page("/things?limit=2").unwrap().split(vec!["a", "b", "c"]);
        assert_eq!((rows, more), (vec!["a", "b"], true));
    }

    #[test]
    fn a_cursor_round_trips_to_the_next_page() {
        let first = page("/things?status=open&limit=2").unwrap();
        let cursor = next_cursor(&first);
        let second = page(&format!("/things?status=open&limit=2&cursor={cursor}")).unwrap();
        assert_eq!(second.offset(), 2);
        let third = page(&format!(
            "/things?status=open&limit=2&cursor={}",
            next_cursor(&second)
        ))
        .unwrap();
        assert_eq!(third.offset(), 4);
    }

    #[test]
    fn the_filters_may_come_in_any_order_and_the_limit_may_change() {
        let cursor = next_cursor(&page("/things?a=1&b=2&limit=2").unwrap());
        let later = page(&format!("/things?limit=5&b=2&cursor={cursor}&a=1")).unwrap();
        assert_eq!((later.offset(), later.limit()), (2, 5));
    }

    #[test]
    fn a_bad_limit_is_refused_not_clamped() {
        // PAG-9.
        for limit in ["0", "51", "many", "-1", "", "1.5", "99999999999999999999"] {
            let error = page(&format!("/things?limit={limit}")).unwrap_err();
            assert_eq!(error, PageError::BadLimit { max_limit: 50 }, "{limit}");
            assert_eq!(error.status(), StatusCode::UNPROCESSABLE_ENTITY);
        }
        assert!(page("/things?limit=2&limit=3").is_err());
        assert_eq!(page("/things?limit=50").unwrap().limit(), 50);
        assert_eq!(page("/things?limit=1").unwrap().limit(), 1);
    }

    #[test]
    fn a_made_up_cursor_is_refused() {
        // PAG-11.
        let forged = URL_SAFE_NO_PAD.encode([VERSION; CURSOR_LEN]);
        for cursor in ["junk", "", "AAAA", forged.as_str()] {
            let error = page(&format!("/things?cursor={cursor}")).unwrap_err();
            assert_eq!(error, PageError::BadCursor, "{cursor}");
            assert_eq!(error.status(), StatusCode::UNPROCESSABLE_ENTITY);
        }
    }

    #[test]
    fn an_edited_cursor_is_refused() {
        let cursor = next_cursor(&page("/things?limit=2").unwrap());
        let mut bytes = URL_SAFE_NO_PAD.decode(&cursor).unwrap();
        bytes[POSITION_LEN] ^= 1; // the position's last byte: offset 2 becomes 3
        let edited = URL_SAFE_NO_PAD.encode(&bytes);
        assert_eq!(
            page(&format!("/things?cursor={edited}")).unwrap_err(),
            PageError::BadCursor
        );
        let mut bytes = URL_SAFE_NO_PAD.decode(&cursor).unwrap();
        bytes[0] = 2; // another version
        let other = URL_SAFE_NO_PAD.encode(&bytes);
        assert!(page(&format!("/things?cursor={other}")).is_err());
        assert!(page(&format!("/things?cursor={cursor}&cursor={cursor}")).is_err());
        assert!(page(&format!("/things?cursor={cursor}")).is_ok());
    }

    #[test]
    fn a_cursor_from_another_query_is_refused() {
        let cursor = next_cursor(&page("/things?status=open&limit=2").unwrap());
        for uri in [
            format!("/other?status=open&cursor={cursor}"),
            format!("/things?status=closed&cursor={cursor}"),
            format!("/things?cursor={cursor}"),
            format!("/things?status=open&extra=1&cursor={cursor}"),
        ] {
            assert_eq!(page(&uri).unwrap_err(), PageError::BadCursor, "{uri}");
        }
    }

    #[test]
    fn a_cursor_signed_by_another_key_is_refused() {
        let other = CursorKey::new(&[9; 32]).unwrap();
        let theirs = CursorPage::new(&other, LIMITS, &"/things?limit=2".parse().unwrap()).unwrap();
        let cursor = next_cursor(&theirs);
        assert_eq!(
            page(&format!("/things?cursor={cursor}")).unwrap_err(),
            PageError::BadCursor
        );
    }

    #[test]
    fn a_short_key_is_refused_and_a_key_is_never_shown() {
        assert_eq!(
            CursorKey::new(&[1; 31]).unwrap_err(),
            KeyTooShort { len: 31 }
        );
        assert!(CursorKey::new(&[]).is_err());
        let shown = format!("{:?}", key());
        assert_eq!(shown, "CursorKey(..)");
        assert!(!shown.contains("secret"));
    }

    #[test]
    fn an_error_quotes_nothing_the_caller_sent() {
        let error = page("/things?limit=secret").unwrap_err();
        assert!(!error.to_string().contains("secret"));
        let error = page("/things?cursor=secret").unwrap_err();
        assert!(!error.to_string().contains("secret"));
    }

    #[test]
    fn like_wildcards_are_neutralised() {
        assert_eq!(escape_like("smith"), "smith");
        assert_eq!(escape_like("100%"), r"100\%");
        assert_eq!(escape_like("a_b"), r"a\_b");
    }

    #[test]
    fn backslash_is_escaped_first() {
        assert_eq!(escape_like(r"a\%"), r"a\\\%");
    }

    #[test]
    fn bounds_fetch_one_more_row_and_saturate() {
        let page = page("/things?limit=2").unwrap();
        assert_eq!(page.bounds(), (3, 0));
        let far = CursorPage {
            limit: u64::MAX,
            offset: u64::MAX,
            next: String::new(),
        };
        assert_eq!(far.bounds(), (i64::MAX, i64::MAX));
        assert_eq!(far.split(vec![1]), (vec![1], false));
    }
}

/// Properties over generated input: a cursor holds for its own query only, a walk
/// through pages lands where the limits say, nothing a caller sends panics, and
/// escaped text holds no live wildcard.
#[cfg(test)]
mod properties {
    use proptest::prelude::*;

    use super::*;

    const LIMITS: CursorLimits = CursorLimits {
        default_limit: 10,
        max_limit: 100,
    };

    fn key(seed: u8) -> CursorKey {
        CursorKey::new(&[seed; 32]).unwrap()
    }

    /// The URI in a page's `Link: rel="next"`.
    fn next_uri(page: &CursorPage) -> Uri {
        let link = page.next_link().unwrap();
        let link = link.to_str().unwrap();
        link.trim_start_matches('<')
            .split('>')
            .next()
            .unwrap()
            .parse()
            .unwrap()
    }

    fn filters() -> impl Strategy<Value = Vec<String>> {
        prop::collection::vec("[a-z]{1,6}=[a-z0-9]{0,6}", 0..4).prop_filter(
            "no limit or cursor filter",
            |parts| {
                parts
                    .iter()
                    .all(|part| !part.starts_with("limit=") && !part.starts_with("cursor="))
            },
        )
    }

    fn uri(path: &str, filters: &[String], limit: u64) -> Uri {
        let mut parts = filters.to_vec();
        parts.push(format!("limit={limit}"));
        format!("{path}?{}", parts.join("&")).parse().unwrap()
    }

    proptest! {
        #[test]
        fn following_next_links_steps_by_the_limit(
            filters in filters(),
            limit in 1..=LIMITS.max_limit,
            steps in 0..12_u64,
        ) {
            let key = key(7);
            let mut page = CursorPage::new(&key, LIMITS, &uri("/things", &filters, limit)).unwrap();
            for _ in 0..steps {
                page = CursorPage::new(&key, LIMITS, &next_uri(&page)).unwrap();
            }
            prop_assert_eq!(page.limit(), limit);
            prop_assert_eq!(page.offset(), steps * limit);
        }

        #[test]
        fn a_cursor_is_refused_by_another_key_context_path_or_filter(
            filters in filters(),
            limit in 1..=LIMITS.max_limit,
            context in "[a-z]{1,8}",
            other in "[a-z]{1,8}",
        ) {
            prop_assume!(context != other);
            let first = CursorPage::new_in(&key(7), LIMITS, &uri("/things", &filters, limit), &context).unwrap();
            let next = next_uri(&first);
            prop_assert!(CursorPage::new_in(&key(7), LIMITS, &next, &context).is_ok());
            prop_assert_eq!(CursorPage::new_in(&key(8), LIMITS, &next, &context), Err(PageError::BadCursor));
            prop_assert_eq!(CursorPage::new_in(&key(7), LIMITS, &next, &other), Err(PageError::BadCursor));

            let query = next.query().unwrap();
            let moved: Uri = format!("/other?{query}").parse().unwrap();
            prop_assert_eq!(CursorPage::new_in(&key(7), LIMITS, &moved, &context), Err(PageError::BadCursor));
            let filtered: Uri = format!("/things?{query}&zzz=1").parse().unwrap();
            prop_assert_eq!(CursorPage::new_in(&key(7), LIMITS, &filtered, &context), Err(PageError::BadCursor));
        }

        #[test]
        fn the_order_of_filters_does_not_change_a_cursor(
            filters in filters(),
            limit in 1..=LIMITS.max_limit,
        ) {
            let first = CursorPage::new(&key(7), LIMITS, &uri("/things", &filters, limit)).unwrap();
            let next = next_uri(&first);
            let mut parts: Vec<&str> = next.query().unwrap().split('&').collect();
            parts.reverse();
            let reordered: Uri = format!("/things?{}", parts.join("&")).parse().unwrap();
            prop_assert_eq!(
                CursorPage::new(&key(7), LIMITS, &reordered).map(|page| page.offset()),
                Ok(limit)
            );
        }

        #[test]
        fn any_query_a_caller_sends_is_a_page_or_a_refusal(query in "[ -~]{0,80}") {
            let Ok(uri) = format!("/things?{query}").parse::<Uri>() else {
                return Ok(());
            };
            match CursorPage::new(&key(7), LIMITS, &uri) {
                Ok(page) => {
                    prop_assert!((1..=LIMITS.max_limit).contains(&page.limit()));
                    prop_assert!(page.offset() == 0 || query.contains("cursor="));
                }
                Err(error) => prop_assert_eq!(error.status(), StatusCode::UNPROCESSABLE_ENTITY),
            }
        }

        #[test]
        fn split_keeps_at_most_the_limit_and_says_whether_more_follow(
            limit in 1..=LIMITS.max_limit,
            rows in 0..250_usize,
        ) {
            let page = CursorPage::new(&key(7), LIMITS, &uri("/things", &[], limit)).unwrap();
            let (kept, more) = page.split((0..rows).collect::<Vec<_>>());
            let limit = usize::try_from(limit).unwrap();
            prop_assert_eq!(kept.len(), rows.min(limit));
            prop_assert_eq!(more, rows > limit);
        }

        #[test]
        fn escaped_text_has_no_live_wildcard_and_unescapes_to_itself(text in "\\PC{0,40}") {
            let escaped = escape_like(&text);
            let mut unescaped = String::new();
            let mut chars = escaped.chars();
            while let Some(c) = chars.next() {
                match c {
                    '\\' => {
                        let escaped_char = chars.next();
                        prop_assert!(matches!(escaped_char, Some('\\' | '%' | '_')));
                        unescaped.extend(escaped_char);
                    }
                    '%' | '_' => prop_assert!(false, "a live wildcard in {escaped:?}"),
                    c => unescaped.push(c),
                }
            }
            prop_assert_eq!(unescaped, text);
        }
    }

    #[test]
    fn each_error_says_what_to_fix_without_quoting_the_request() {
        assert_eq!(
            PageError::BadLimit { max_limit: 100 }.to_string(),
            "limit must be a whole number from 1 to 100"
        );
        assert_eq!(PageError::BadCursor.to_string(), "cursor is not valid");
        let short = CursorKey::new(&[7; 8]).unwrap_err().to_string();
        assert!(short.contains("32"), "{short}");
    }
}

//! Which environment a service runs in.
//!
//! `axa` re-exports this crate as `axa::environment`. It has no dependencies,
//! so a migration crate can use it without depending on `axa`, and a safety
//! guard cannot drift from the service's own order of lookup.
//!
//! ```
//! use axa_environment::Environment;
//!
//! // `name` gives what is set, and `from_env` what that means.
//! let guarded = Environment::from_env().is_production_like();
//! # let _ = (guarded, Environment::name());
//! ```
//!
//! With nothing set, a debug build is development and a release build is
//! production, so a release binary started with no variables gets the strict
//! rules. The build profile is read from `cfg!(debug_assertions)`, so a release
//! profile that turns debug assertions on is treated as a debug build.

use std::fmt;

/// The variables that name the environment, in the order they are read.
pub const VARIABLES: [&str; 1] = ["APP_ENV"];

/// The environment, taken from `APP_ENV`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Environment {
    /// Local development; the default for a debug build.
    Development,
    /// Automated tests.
    Test,
    /// A real deployment; the default for a release build.
    Production,
    /// Any other named environment. Treated as production for defaults.
    Other(String),
}

impl Environment {
    /// Parse a name. Accepts the short forms `dev`, `prod`. A blank name is
    /// the same as no name: see [`Environment::resolve`].
    #[must_use]
    pub fn parse(name: &str) -> Self {
        Self::resolve(Some(name), cfg!(debug_assertions))
    }

    /// The environment for `name`, as a pure function of its arguments.
    /// `debug` says whether this is a debug build. With no name, or a blank
    /// one, a debug build is development and any other build is production.
    ///
    /// # Examples
    ///
    /// ```
    /// use axa_environment::Environment;
    ///
    /// assert_eq!(Environment::resolve(None, true), Environment::Development);
    /// assert_eq!(Environment::resolve(None, false), Environment::Production);
    /// assert_eq!(Environment::resolve(Some("test"), false), Environment::Test);
    /// ```
    #[must_use]
    pub fn resolve(name: Option<&str>, debug: bool) -> Self {
        let name = name.unwrap_or_default().trim().to_ascii_lowercase();
        match (name.as_str(), debug) {
            ("development" | "dev", _) | ("", true) => Self::Development,
            ("test", _) => Self::Test,
            ("production" | "prod", _) | ("", false) => Self::Production,
            (other, _) => Self::Other(other.to_string()),
        }
    }

    /// The name set in the process environment, read as
    /// [`Environment::name_from`] reads it.
    #[must_use]
    pub fn name() -> Option<String> {
        Self::name_from(|variable| std::env::var(variable).ok())
    }

    /// The first non-blank name among [`VARIABLES`], read through `lookup`.
    ///
    /// # Examples
    ///
    /// ```
    /// use axa_environment::Environment;
    ///
    /// let name = Environment::name_from(|variable| {
    ///     (variable == "APP_ENV").then(|| "staging".to_string())
    /// });
    /// assert_eq!(name.as_deref(), Some("staging"));
    /// ```
    #[must_use]
    pub fn name_from(lookup: impl Fn(&str) -> Option<String>) -> Option<String> {
        VARIABLES
            .iter()
            .find_map(|variable| lookup(variable).filter(|name| !name.trim().is_empty()))
    }

    /// Read the environment from `APP_ENV`.
    #[must_use]
    pub fn from_env() -> Self {
        Self::resolve(Self::name().as_deref(), cfg!(debug_assertions))
    }

    /// True for anything that is not development or test, so an unknown
    /// name gets the stricter behaviour.
    #[must_use]
    pub fn is_production_like(&self) -> bool {
        !matches!(self, Self::Development | Self::Test)
    }

    /// Whether a command that destroys data, such as `db down`, `db reset`, or
    /// `db truncate`, may run: only in development or test, and only when
    /// `confirmed` is `"true"`, so that running one takes a choice as well as a
    /// typed command.
    ///
    /// `axa::cli::parse` applies this before a service runs anything. Call it
    /// yourself for a destructive path that does not come through there.
    #[must_use]
    pub fn may_destroy_data(&self, confirmed: Option<&str>) -> bool {
        !self.is_production_like() && confirmed == Some("true")
    }
}

impl fmt::Display for Environment {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Development => "development",
            Self::Test => "test",
            Self::Production => "production",
            Self::Other(name) => name,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn lookup(pairs: &[(&'static str, &'static str)]) -> impl Fn(&str) -> Option<String> {
        let pairs = pairs.to_vec();
        move |variable| {
            pairs
                .iter()
                .find(|(name, _)| *name == variable)
                .map(|(_, value)| (*value).to_string())
        }
    }

    #[test]
    fn parses_names_and_short_forms() {
        assert_eq!(Environment::parse("prod"), Environment::Production);
        assert_eq!(Environment::parse("DEV"), Environment::Development);
        assert_eq!(Environment::parse("test"), Environment::Test);
    }

    #[test]
    fn names_round_trip() {
        for name in ["development", "test", "production", "staging"] {
            assert_eq!(Environment::parse(name).to_string(), name);
        }
    }

    #[test]
    fn unknown_environment_is_production_like() {
        assert!(Environment::parse("staging").is_production_like());
        assert!(!Environment::Test.is_production_like());
    }

    #[test]
    fn only_app_env_names_the_environment() {
        let set = lookup(&[("APP_ENV", "production"), ("RUST_ENV", "development")]);
        assert_eq!(Environment::name_from(set).as_deref(), Some("production"));
        let other = lookup(&[("RUST_ENV", "test")]);
        assert_eq!(Environment::name_from(other), None);
        assert_eq!(Environment::name_from(lookup(&[])), None);
    }

    #[test]
    fn a_blank_name_counts_as_unset() {
        assert_eq!(Environment::name_from(lookup(&[("APP_ENV", "  ")])), None);
        assert_eq!(Environment::name_from(lookup(&[("APP_ENV", "")])), None);
    }

    #[test]
    fn a_debug_build_with_no_name_is_development() {
        assert_eq!(Environment::resolve(None, true), Environment::Development);
        assert_eq!(
            Environment::resolve(Some("  "), true),
            Environment::Development
        );
    }

    #[test]
    fn a_release_build_with_no_name_is_production() {
        assert_eq!(Environment::resolve(None, false), Environment::Production);
        assert_eq!(
            Environment::resolve(Some("  "), false),
            Environment::Production
        );
        assert!(Environment::resolve(None, false).is_production_like());
    }

    #[test]
    fn a_name_means_the_same_in_every_build() {
        for debug in [true, false] {
            assert_eq!(
                Environment::resolve(Some("dev"), debug),
                Environment::Development
            );
            assert_eq!(Environment::resolve(Some("test"), debug), Environment::Test);
            assert_eq!(
                Environment::resolve(Some("staging"), debug),
                Environment::Other("staging".to_string())
            );
        }
    }

    #[test]
    fn this_crate_has_no_dependencies() {
        let manifest = include_str!("../Cargo.toml");
        assert!(!manifest.contains("dependencies]"), "{manifest}");
    }

    #[test]
    fn data_is_destroyed_only_in_development_or_test_and_only_when_confirmed() {
        for environment in [Environment::Development, Environment::Test] {
            assert!(environment.may_destroy_data(Some("true")));
            assert!(!environment.may_destroy_data(None));
            assert!(!environment.may_destroy_data(Some("yes")));
        }
        for environment in [
            Environment::Production,
            Environment::Other("staging".to_string()),
            Environment::Other("Test ".to_string()),
        ] {
            assert!(!environment.may_destroy_data(Some("true")));
        }
    }

    /// CI runs this in a release build as well, where it is the one test that proves
    /// the build is read: a release binary given no name is production.
    #[test]
    fn with_no_name_this_build_decides() {
        let expected = if cfg!(debug_assertions) {
            Environment::Development
        } else {
            Environment::Production
        };
        assert_eq!(Environment::parse(""), expected);
        assert_eq!(Environment::parse("  "), expected);
        assert_eq!(Environment::resolve(None, cfg!(debug_assertions)), expected);
    }

    #[test]
    fn parsing_a_blank_name_follows_the_build() {
        assert_eq!(
            Environment::parse(" "),
            Environment::resolve(None, cfg!(debug_assertions))
        );
    }
}

//! An outbound HTTP client that will not be turned on the network it runs in.
//!
//! A service that fetches a URL someone else chose, such as a webhook receiver, an
//! avatar, or a link preview, can be made to fetch `http://169.254.169.254/` and hand
//! back the cloud's credentials, or to reach a database or admin page that trusts the
//! private network. This is server-side request forgery. [`Client`] refuses any address
//! that is not public: private, loopback, link-local and so the metadata service,
//! carrier-grade NAT, documentation, multicast, and reserved ranges, IPv4 inside IPv6
//! included.
//!
//! ```no_run
//! # async fn fetch() -> Result<(), Box<dyn std::error::Error>> {
//! let client = axa_http_client::Client::builder().https_only(true).build()?;
//! let response = client.get("https://example.com/hook")?.send().await?;
//! let body = axa_http_client::bytes_limited(response, 1_000_000).await?;
//! # let _ = body;
//! # Ok(())
//! # }
//! ```
//!
//! It checks where it connects, not only what the URL says:
//!
//! - A host name is looked up by the client's own resolver, which drops every address
//!   that is not allowed and fails when none is left. The connection goes only to the
//!   addresses it kept, so a name that answers differently a moment later, as in DNS
//!   rebinding, changes nothing.
//! - An address written in the URL, in any form the URL standard reads, such as
//!   `http://2130706433/` or `http://[::ffff:127.0.0.1]/`, is checked before sending.
//! - Every redirect is checked the same way, and one from `https` to `http` is refused.
//! - No proxy is used, as one from the environment would make the connection for it.
//!
//! [`Builder::allow_hosts`] limits where it may go at all, and [`Builder::allow_nets`]
//! lets it reach private ranges a service does mean to reach.
//!
//! TLS is rustls on ring, which [`Builder::build`] installs as the process's provider
//! unless the service installed one first. Certificates are checked against the
//! system's trust store, so a container image needs its CA certificates.

use std::{
    fmt,
    net::{IpAddr, Ipv4Addr, Ipv6Addr, SocketAddr},
    sync::Arc,
    time::Duration,
};

use bytes::{Bytes, BytesMut};
pub use reqwest;
use reqwest::{
    Method, RequestBuilder, Url,
    dns::{Addrs, Name, Resolve, Resolving},
    redirect,
};

/// The most redirects followed, unless the builder says otherwise.
pub const DEFAULT_MAX_REDIRECTS: usize = 5;

/// How long to wait for a connection, unless the builder says otherwise.
pub const DEFAULT_CONNECT_TIMEOUT: Duration = Duration::from_secs(5);

/// How long a whole request may take, unless the builder says otherwise.
pub const DEFAULT_TIMEOUT: Duration = Duration::from_secs(30);

/// Why a request was refused before anything was sent to where it pointed.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum Refused {
    /// The URL does not parse, or has no host.
    Url,
    /// The scheme is not `https`, or `http` where that is allowed.
    Scheme,
    /// The host is not one [`Builder::allow_hosts`] lists.
    Host,
    /// The address is not public, and no [`Builder::allow_nets`] range holds it.
    Address(IpAddr),
    /// No address the host name has is allowed, or it has none.
    NoAddress,
    /// A redirect from `https` to `http`.
    Downgrade,
    /// More redirects than the builder allows.
    TooManyRedirects,
}

impl fmt::Display for Refused {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Url => f.write_str("the URL is not one with a host"),
            Self::Scheme => f.write_str("the URL's scheme is not allowed"),
            Self::Host => f.write_str("the URL's host is not on the allow-list"),
            Self::Address(address) => write!(f, "{address} is not a public address"),
            Self::NoAddress => f.write_str("the host has no address that may be reached"),
            Self::Downgrade => f.write_str("a redirect from https to http"),
            Self::TooManyRedirects => f.write_str("too many redirects"),
        }
    }
}

impl std::error::Error for Refused {}

/// The refusal inside `error`, from a request this crate's [`Client`] refused while it
/// ran: a host name with no allowed address, or a redirect.
#[must_use]
pub fn refusal<'a>(error: &'a (dyn std::error::Error + 'static)) -> Option<&'a Refused> {
    let mut source = Some(error);
    while let Some(error) = source {
        if let Some(refused) = error.downcast_ref::<Refused>() {
            return Some(refused);
        }
        source = error.source();
    }
    None
}

/// An address range, as `10.0.0.0/8` or `fd00::/8`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Net {
    address: IpAddr,
    prefix: u8,
}

impl Net {
    /// The range of `address` and the `prefix` bits after it, or `None` when the prefix
    /// is longer than the address.
    #[must_use]
    pub fn new(address: IpAddr, prefix: u8) -> Option<Self> {
        let bits = if address.is_ipv4() { 32 } else { 128 };
        (prefix <= bits).then_some(Self { address, prefix })
    }

    /// Whether `address` is in the range. An IPv4 address inside IPv6 counts as IPv4.
    #[must_use]
    pub fn contains(&self, address: IpAddr) -> bool {
        match (self.address, canonical(address)) {
            (IpAddr::V4(net), IpAddr::V4(address)) => {
                let mask = u32::MAX
                    .checked_shl(32 - u32::from(self.prefix))
                    .unwrap_or(0);
                u32::from(net) & mask == u32::from(address) & mask
            }
            (IpAddr::V6(net), IpAddr::V6(address)) => {
                let mask = u128::MAX
                    .checked_shl(128 - u32::from(self.prefix))
                    .unwrap_or(0);
                u128::from(net) & mask == u128::from(address) & mask
            }
            _ => false,
        }
    }
}

/// Why a range did not parse.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct NetError;

impl fmt::Display for NetError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("an address range is an address, or an address, `/`, and a prefix length")
    }
}

impl std::error::Error for NetError {}

impl std::str::FromStr for Net {
    type Err = NetError;

    fn from_str(text: &str) -> Result<Self, NetError> {
        let (address, prefix) = match text.trim().split_once('/') {
            Some((address, prefix)) => (address, Some(prefix)),
            None => (text.trim(), None),
        };
        let address: IpAddr = address.parse().map_err(|_| NetError)?;
        let prefix = match prefix {
            Some(prefix) => prefix.parse().map_err(|_| NetError)?,
            None if address.is_ipv4() => 32,
            None => 128,
        };
        Self::new(address, prefix).ok_or(NetError)
    }
}

/// `address`, as IPv4 when it is IPv4 written as IPv6.
fn canonical(address: IpAddr) -> IpAddr {
    match address {
        IpAddr::V6(v6) => v6.to_ipv4_mapped().map_or(IpAddr::V6(v6), IpAddr::V4),
        v4 @ IpAddr::V4(_) => v4,
    }
}

/// Whether `address` is one anybody on the internet could reach: none of the ranges
/// IANA keeps for private, loopback, link-local, shared, documentation, benchmarking,
/// multicast, or future use.
#[must_use]
pub fn is_public(address: IpAddr) -> bool {
    match canonical(address) {
        IpAddr::V4(v4) => is_public_v4(v4),
        IpAddr::V6(v6) => is_public_v6(v6),
    }
}

fn is_public_v4(address: Ipv4Addr) -> bool {
    let [a, b, c, _] = address.octets();
    !(a == 0                                    // "this network", 0.0.0.0/8
        || a == 10                              // private
        || (a == 100 && (64..128).contains(&b)) // carrier-grade NAT, 100.64.0.0/10
        || a == 127                             // loopback
        || (a == 169 && b == 254)               // link-local, and the metadata service
        || (a == 172 && (16..32).contains(&b))  // private
        || (a == 192 && b == 0 && c == 0)       // IETF protocol assignments
        || (a == 192 && b == 0 && c == 2)       // documentation
        || (a == 192 && b == 88 && c == 99)     // 6to4 relay anycast
        || (a == 192 && b == 168)               // private
        || (a == 198 && (b == 18 || b == 19))   // benchmarking
        || (a == 198 && b == 51 && c == 100)    // documentation
        || (a == 203 && b == 0 && c == 113)     // documentation
        || a >= 224) // multicast, reserved, and broadcast
}

fn is_public_v6(address: Ipv6Addr) -> bool {
    let segments = address.segments();
    // Only 2000::/3 is global unicast. Everything else is loopback, unspecified,
    // IPv4-compatible, link-local, unique local, multicast, or not yet assigned.
    if segments[0] & 0xe000 != 0x2000 {
        // NAT64, 64:ff9b::/96, reaches the IPv4 address in its last 32 bits.
        if segments[..6] == [0x64, 0xff9b, 0, 0, 0, 0] {
            let [.., high, low] = segments;
            return is_public_v4(Ipv4Addr::from((u32::from(high) << 16) | u32::from(low)));
        }
        return false;
    }
    match segments[0] {
        // IETF protocol assignments and Teredo, 2001::/23, which can hide any IPv4
        // address, and documentation, 2001:db8::/32.
        0x2001 => segments[1] >= 0x0200 && segments[1] != 0x0db8,
        // 6to4, 2002::/16, reaches the IPv4 address in its next 32 bits.
        0x2002 => is_public_v4(Ipv4Addr::from(
            (u32::from(segments[1]) << 16) | u32::from(segments[2]),
        )),
        // Documentation, 3fff::/20.
        0x3fff => segments[1] >= 0x1000,
        _ => true,
    }
}

/// What may be reached.
#[derive(Debug)]
struct Policy {
    hosts: Option<Vec<String>>,
    nets: Vec<Net>,
    https_only: bool,
    max_redirects: usize,
}

impl Policy {
    fn permits(&self, address: IpAddr) -> bool {
        is_public(address) || self.nets.iter().any(|net| net.contains(address))
    }

    fn host_listed(&self, host: &str) -> bool {
        let Some(hosts) = &self.hosts else {
            return true;
        };
        let host = host.trim_end_matches('.').to_ascii_lowercase();
        hosts.iter().any(|listed| match listed.strip_prefix("*.") {
            Some(suffix) => host
                .strip_suffix(suffix)
                .is_some_and(|rest| rest.ends_with('.') && rest.len() > 1),
            None => *listed == host,
        })
    }

    /// Check what a URL says, before it is sent to or redirected to.
    fn check(&self, url: &Url) -> Result<(), Refused> {
        match url.scheme() {
            "https" => {}
            "http" if !self.https_only => {}
            _ => return Err(Refused::Scheme),
        }
        let host = url
            .host_str()
            .filter(|host| !host.is_empty())
            .ok_or(Refused::Url)?;
        if !self.host_listed(host.trim_start_matches('[').trim_end_matches(']')) {
            return Err(Refused::Host);
        }
        // The URL parser writes an address in its one standard form, whatever form it
        // was given in, so this reads every address a URL can hold.
        let address = match host
            .strip_prefix('[')
            .and_then(|host| host.strip_suffix(']'))
        {
            Some(v6) => v6.parse::<Ipv6Addr>().ok().map(IpAddr::V6),
            None => host.parse::<Ipv4Addr>().ok().map(IpAddr::V4),
        };
        match address {
            Some(address) if !self.permits(address) => Err(Refused::Address(address)),
            _ => Ok(()),
        }
    }
}

impl Policy {
    /// Why a redirect to `url`, after asking for each of `previous` in turn, is
    /// refused, or `None` when it may be followed.
    fn redirect_refusal(&self, url: &Url, previous: &[Url]) -> Option<Refused> {
        // `previous` holds every URL asked for so far, the first among them.
        if previous.len() > self.max_redirects {
            return Some(Refused::TooManyRedirects);
        }
        let from_https = previous.last().is_some_and(|last| last.scheme() == "https");
        if from_https && url.scheme() == "http" {
            return Some(Refused::Downgrade);
        }
        self.check(url).err()
    }
}

/// Looks host names up, and keeps only the addresses the policy allows.
struct Resolver(Arc<Policy>);

impl Resolve for Resolver {
    fn resolve(&self, name: Name) -> Resolving {
        let policy = self.0.clone();
        Box::pin(async move {
            let found = tokio::net::lookup_host((name.as_str(), 0)).await?;
            let kept: Vec<SocketAddr> = found
                .filter(|address| policy.permits(address.ip()))
                .collect();
            if kept.is_empty() {
                return Err(Box::new(Refused::NoAddress) as _);
            }
            Ok(Box::new(kept.into_iter()) as Addrs)
        })
    }
}

/// Builds a [`Client`].
#[derive(Debug)]
pub struct Builder {
    hosts: Option<Vec<String>>,
    nets: Vec<Net>,
    https_only: bool,
    max_redirects: usize,
    connect_timeout: Duration,
    timeout: Duration,
    user_agent: Option<String>,
}

impl Builder {
    /// Reach only these hosts: a name, lower case, or `*.` and a name for any name
    /// under it but not the name itself. An address in the URL must be listed as it
    /// is written there, without brackets. Every address is still checked.
    #[must_use]
    pub fn allow_hosts<S: Into<String>>(mut self, hosts: impl IntoIterator<Item = S>) -> Self {
        let hosts = hosts
            .into_iter()
            .map(|host| host.into().trim_end_matches('.').to_ascii_lowercase());
        self.hosts = Some(hosts.collect());
        self
    }

    /// Let these ranges be reached although they are not public, as for a service on
    /// the private network the caller means to reach. The metadata service is in
    /// `169.254.0.0/16`: never list a range that holds it unless that is meant.
    #[must_use]
    pub fn allow_nets(mut self, nets: impl IntoIterator<Item = Net>) -> Self {
        self.nets.extend(nets);
        self
    }

    /// Refuse `http`, as a production service should. Off by default.
    #[must_use]
    pub fn https_only(mut self, https_only: bool) -> Self {
        self.https_only = https_only;
        self
    }

    /// Follow at most this many redirects, 5 by default. 0 follows none, and hands
    /// back the redirect as the response.
    #[must_use]
    pub fn max_redirects(mut self, max_redirects: usize) -> Self {
        self.max_redirects = max_redirects;
        self
    }

    /// How long to wait for a connection, 5 seconds by default.
    #[must_use]
    pub fn connect_timeout(mut self, timeout: Duration) -> Self {
        self.connect_timeout = timeout;
        self
    }

    /// How long a whole request may take, 30 seconds by default.
    #[must_use]
    pub fn timeout(mut self, timeout: Duration) -> Self {
        self.timeout = timeout;
        self
    }

    /// The `user-agent` to send.
    #[must_use]
    pub fn user_agent(mut self, user_agent: impl Into<String>) -> Self {
        self.user_agent = Some(user_agent.into());
        self
    }

    /// The client.
    ///
    /// # Errors
    ///
    /// Fails when `reqwest` cannot build its client, as when TLS cannot start.
    pub fn build(self) -> Result<Client, reqwest::Error> {
        let policy = Arc::new(Policy {
            hosts: self.hosts,
            nets: self.nets,
            https_only: self.https_only,
            max_redirects: self.max_redirects,
        });
        let redirects = policy.clone();
        let redirect = redirect::Policy::custom(move |attempt| {
            if redirects.max_redirects == 0 {
                return attempt.stop();
            }
            match redirects.redirect_refusal(attempt.url(), attempt.previous()) {
                Some(refused) => attempt.error(refused),
                None => attempt.follow(),
            }
        });
        // reqwest takes the process's rustls provider and has none of its own. Ring,
        // unless the service installed another first, which `install_default` keeps.
        let _ = rustls::crypto::ring::default_provider().install_default();
        let mut inner = reqwest::Client::builder()
            .no_proxy()
            .dns_resolver(Arc::new(Resolver(policy.clone())))
            .redirect(redirect)
            .https_only(policy.https_only)
            .connect_timeout(self.connect_timeout)
            .timeout(self.timeout);
        if let Some(user_agent) = self.user_agent {
            inner = inner.user_agent(user_agent);
        }
        Ok(Client {
            inner: inner.build()?,
            policy,
        })
    }
}

/// An HTTP client that reaches only public addresses, and the ones its builder allows.
/// Cloning it is cheap, and clones share connections.
#[derive(Debug, Clone)]
pub struct Client {
    inner: reqwest::Client,
    policy: Arc<Policy>,
}

impl Client {
    /// A builder with the defaults: any public host, `http` and `https`, 5 redirects,
    /// a 5-second connect timeout, and 30 seconds in all.
    #[must_use]
    pub fn builder() -> Builder {
        Builder {
            hosts: None,
            nets: Vec::new(),
            https_only: false,
            max_redirects: DEFAULT_MAX_REDIRECTS,
            connect_timeout: DEFAULT_CONNECT_TIMEOUT,
            timeout: DEFAULT_TIMEOUT,
            user_agent: None,
        }
    }

    /// A request with `method` to `url`, once the URL is checked. A host name is
    /// checked again when it is looked up, and a refusal then is an error from `send`
    /// that [`refusal`] finds.
    ///
    /// # Errors
    ///
    /// Refuses a URL that does not parse or has no host, a scheme that is not allowed,
    /// a host the allow-list does not hold, and an address that is not allowed.
    pub fn request(&self, method: Method, url: &str) -> Result<RequestBuilder, Refused> {
        let url = Url::parse(url).map_err(|_| Refused::Url)?;
        self.policy.check(&url)?;
        Ok(self.inner.request(method, url))
    }

    /// A `GET` of `url`. See [`Client::request`].
    ///
    /// # Errors
    ///
    /// As [`Client::request`].
    pub fn get(&self, url: &str) -> Result<RequestBuilder, Refused> {
        self.request(Method::GET, url)
    }

    /// A `POST` to `url`. See [`Client::request`].
    ///
    /// # Errors
    ///
    /// As [`Client::request`].
    pub fn post(&self, url: &str) -> Result<RequestBuilder, Refused> {
        self.request(Method::POST, url)
    }
}

/// Why a body was not read whole.
#[derive(Debug)]
#[non_exhaustive]
pub enum BodyError {
    /// It is longer than the limit.
    TooLarge,
    /// It could not be read.
    Read(reqwest::Error),
}

impl fmt::Display for BodyError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::TooLarge => f.write_str("the response body is longer than its limit"),
            Self::Read(error) => write!(f, "the response body could not be read: {error}"),
        }
    }
}

impl std::error::Error for BodyError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::TooLarge => None,
            Self::Read(error) => Some(error),
        }
    }
}

/// The body of `response`, refused once it passes `limit` bytes, which it counts as
/// they arrive, whatever `content-length` says.
///
/// # Errors
///
/// Fails when the body is longer than `limit`, or cannot be read.
pub async fn bytes_limited(
    mut response: reqwest::Response,
    limit: usize,
) -> Result<Bytes, BodyError> {
    if response
        .content_length()
        .is_some_and(|length| length > limit as u64)
    {
        return Err(BodyError::TooLarge);
    }
    let mut body = BytesMut::new();
    while let Some(chunk) = response.chunk().await.map_err(BodyError::Read)? {
        if body.len() + chunk.len() > limit {
            return Err(BodyError::TooLarge);
        }
        body.extend_from_slice(&chunk);
    }
    Ok(body.freeze())
}

