//! A small condition builder.
//!
//! It has the shape of Loco's, so code using it moves across unchanged. New
//! code can use `SeaORM` directly, which is just as short:
//! `Column::Email.eq(email)`.
//!
//! ```
//! use axa_mysql_seaorm::query::condition;
//! # use axa_mysql_seaorm::sea_orm::{self, entity::prelude::*};
//! # mod users {
//! #     use axa_mysql_seaorm::sea_orm::{self, entity::prelude::*};
//! #     #[derive(Clone, Debug, PartialEq, DeriveEntityModel)]
//! #     #[sea_orm(table_name = "users")]
//! #     pub struct Model {
//! #         #[sea_orm(primary_key)]
//! #         pub id: i32,
//! #         pub email: String,
//! #     }
//! #     #[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
//! #     pub enum Relation {}
//! #     impl ActiveModelBehavior for ActiveModel {}
//! # }
//! let filter = condition().eq(users::Column::Email, "a@example.org").build();
//! ```

use sea_orm::{ColumnTrait, Condition, Value};

/// A set of conditions, all of which must hold.
#[derive(Debug, Clone)]
pub struct ConditionBuilder {
    condition: Condition,
}

/// Start an empty condition.
#[must_use]
pub fn condition() -> ConditionBuilder {
    ConditionBuilder {
        condition: Condition::all(),
    }
}

impl ConditionBuilder {
    /// Add a column equality.
    #[must_use]
    pub fn eq<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.eq(value))
    }

    /// Add a column inequality.
    #[must_use]
    pub fn ne<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.ne(value))
    }

    /// Add a "greater than" comparison.
    #[must_use]
    pub fn gt<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.gt(value))
    }

    /// Add a "greater than or equal" comparison.
    #[must_use]
    pub fn gte<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.gte(value))
    }

    /// Add a "less than" comparison.
    #[must_use]
    pub fn lt<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.lt(value))
    }

    /// Add a "less than or equal" comparison.
    #[must_use]
    pub fn lte<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.lte(value))
    }

    /// Require a column to be null.
    #[must_use]
    pub fn is_null<T: ColumnTrait>(self, col: T) -> Self {
        self.with(col.is_null())
    }

    /// Require a column not to be null.
    #[must_use]
    pub fn is_not_null<T: ColumnTrait>(self, col: T) -> Self {
        self.with(col.is_not_null())
    }

    /// Require a column to be one of `values`.
    #[must_use]
    pub fn is_in<T, V, I>(self, col: T, values: I) -> Self
    where
        T: ColumnTrait,
        V: Into<Value>,
        I: IntoIterator<Item = V>,
    {
        self.with(col.is_in(values))
    }

    /// Require a column to contain `text`. `%` and `_` in `text` act as `LIKE`
    /// wildcards, so escape text that came from a user.
    #[must_use]
    pub fn contains<T: ColumnTrait>(self, col: T, text: &str) -> Self {
        self.with(col.contains(text))
    }

    /// Add any `SeaORM` condition, for what this builder does not cover.
    #[must_use]
    pub fn with(mut self, condition: impl sea_orm::sea_query::IntoCondition) -> Self {
        self.condition = self.condition.add(condition.into_condition());
        self
    }

    /// Finish.
    #[must_use]
    pub fn build(&self) -> Condition {
        self.condition.clone()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use sea_orm::{DbBackend, QueryFilter, QueryTrait, entity::prelude::*};

    mod users {
        use sea_orm::entity::prelude::*;

        #[derive(Clone, Debug, PartialEq, DeriveEntityModel)]
        #[sea_orm(table_name = "users")]
        pub struct Model {
            #[sea_orm(primary_key)]
            pub id: i32,
            pub email: String,
            pub age: i32,
            pub deleted_at: Option<DateTimeWithTimeZone>,
        }

        #[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
        pub enum Relation {}

        impl ActiveModelBehavior for ActiveModel {}
    }

    use users::{Column, Entity};

    fn sql(builder: &ConditionBuilder) -> String {
        Entity::find()
            .filter(builder.build())
            .build(DbBackend::MySql)
            .to_string()
    }

    #[test]
    fn eq_and_ne_compare_values() {
        assert!(sql(&condition().eq(Column::Email, "a")).contains("`email` = 'a'"));
        assert!(sql(&condition().ne(Column::Email, "a")).contains("`email` <> 'a'"));
    }

    #[test]
    fn ordering_comparisons_use_their_operators() {
        assert!(sql(&condition().gt(Column::Age, 1)).contains("`age` > 1"));
        assert!(sql(&condition().gte(Column::Age, 1)).contains("`age` >= 1"));
        assert!(sql(&condition().lt(Column::Age, 1)).contains("`age` < 1"));
        assert!(sql(&condition().lte(Column::Age, 1)).contains("`age` <= 1"));
    }

    #[test]
    fn null_checks_use_is_null() {
        assert!(sql(&condition().is_null(Column::DeletedAt)).contains("IS NULL"));
        assert!(sql(&condition().is_not_null(Column::DeletedAt)).contains("IS NOT NULL"));
    }

    #[test]
    fn membership_lists_every_value() {
        assert!(sql(&condition().is_in(Column::Age, [1, 2])).contains("IN (1, 2)"));
    }

    #[test]
    fn contains_wraps_the_text_in_wildcards() {
        assert!(sql(&condition().contains(Column::Email, "ab")).contains("LIKE '%ab%'"));
    }

    #[test]
    fn several_conditions_must_all_hold() {
        let text = sql(&condition().eq(Column::Email, "a").gt(Column::Age, 1));
        assert!(text.contains(" AND "), "{text}");
    }

    #[test]
    fn an_empty_condition_filters_nothing() {
        // Rendered as `WHERE TRUE`, which matches every row.
        assert!(sql(&condition()).ends_with("WHERE TRUE"));
    }

    #[test]
    fn with_accepts_a_seaorm_condition() {
        let text = sql(&condition().with(Column::Email.eq("a")));
        assert!(text.contains("`email` = 'a'"), "{text}");
    }
}

//! Migration helpers over `sea-orm-migration`.
//!
//! [`create_table`] adds `created_at` and `updated_at` with a
//! `CURRENT_TIMESTAMP` default, and table names are pluralised, so migrations written against
//! these helpers produce the schema they always have.

use heck::ToSnakeCase;
use sea_orm::DbErr;
use sea_orm_migration::{
    prelude::*,
    schema::{
        big_integer, big_integer_null, big_pk_auto, boolean, boolean_null, date, date_null,
        date_time, date_time_null, double, double_null, integer, integer_null, pk_uuid, string,
        string_null, string_uniq, text, text_null, uuid, uuid_null, uuid_uniq,
    },
    sea_query::{ForeignKeyAction, Table},
};

/// A column type.
#[derive(Debug, Clone, PartialEq)]
#[non_exhaustive]
pub enum ColType {
    /// 64-bit auto-increment primary key.
    PkAuto,
    /// UUID primary key.
    PkUuid,
    /// Required string.
    String,
    /// Optional string.
    StringNull,
    /// Required unique string.
    StringUniq,
    /// Required text.
    Text,
    /// Optional text.
    TextNull,
    /// Required 32-bit integer.
    Integer,
    /// Optional 32-bit integer.
    IntegerNull,
    /// Required 64-bit integer.
    BigInteger,
    /// Optional 64-bit integer.
    BigIntegerNull,
    /// Required double.
    Double,
    /// Optional double.
    DoubleNull,
    /// Required boolean.
    Boolean,
    /// Optional boolean.
    BooleanNull,
    /// Required boolean with a default.
    BooleanWithDefault(bool),
    /// Required date.
    Date,
    /// Optional date.
    DateNull,
    /// Required timestamp, a MySQL `DATETIME` in UTC.
    TimestampWithTimeZone,
    /// Optional timestamp, a MySQL `DATETIME` in UTC.
    TimestampWithTimeZoneNull,
    /// Required UUID.
    Uuid,
    /// Optional UUID.
    UuidNull,
    /// Required unique UUID.
    UuidUniq,
    /// Required JSONB.
    JsonBinary,
    /// Optional JSONB.
    JsonBinaryNull,
}

impl ColType {
    fn to_def(&self, name: Alias) -> ColumnDef {
        match self {
            Self::PkAuto => big_pk_auto(name),
            Self::PkUuid => pk_uuid(name),
            Self::String => string(name),
            Self::StringNull => string_null(name),
            Self::StringUniq => string_uniq(name),
            Self::Text => text(name),
            Self::TextNull => text_null(name),
            Self::Integer => integer(name),
            Self::IntegerNull => integer_null(name),
            Self::BigInteger => big_integer(name),
            Self::BigIntegerNull => big_integer_null(name),
            Self::Double => double(name),
            Self::DoubleNull => double_null(name),
            Self::Boolean => boolean(name),
            Self::BooleanNull => boolean_null(name),
            Self::BooleanWithDefault(value) => boolean(name).default(*value).take(),
            Self::Date => date(name),
            Self::DateNull => date_null(name),
            Self::TimestampWithTimeZone => date_time(name),
            Self::TimestampWithTimeZoneNull => date_time_null(name),
            Self::Uuid => uuid(name),
            Self::UuidNull => uuid_null(name),
            Self::UuidUniq => uuid_uniq(name),
            Self::JsonBinary => ColumnDef::new(name).json_binary().not_null().take(),
            Self::JsonBinaryNull => ColumnDef::new(name).json_binary().null().take(),
        }
    }
}

fn normalize_table(table: &str) -> std::string::String {
    cruet::to_plural(table).to_snake_case()
}

fn reference_id(table: &str) -> std::string::String {
    format!("{}_id", cruet::to_singular(table).to_snake_case())
}

/// Create a table with `created_at` and `updated_at`.
///
/// `refs` lists `(parent_table, column)`. An empty column means
/// `<parent>_id`, and a `?` suffix on the parent makes the reference
/// optional.
///
/// # Errors
///
/// Propagates the database error.
pub async fn create_table(
    m: &SchemaManager<'_>,
    table: &str,
    cols: &[(&str, ColType)],
    refs: &[(&str, &str)],
) -> Result<(), DbErr> {
    let table = normalize_table(table);
    let mut stmt = Table::create()
        .table(Alias::new(&table))
        .if_not_exists()
        .take();
    stmt.col(date_time(Alias::new("created_at")).default(Expr::current_timestamp()));
    stmt.col(date_time(Alias::new("updated_at")).default(Expr::current_timestamp()));
    for (name, col) in cols {
        stmt.col(col.to_def(Alias::new(*name)));
    }
    for (parent, column) in refs {
        let (parent, nullable) = parent.strip_suffix('?').map_or_else(
            || (normalize_table(parent), false),
            |stripped| (normalize_table(stripped), true),
        );
        let column = if column.is_empty() {
            reference_id(&parent)
        } else {
            (*column).to_string()
        };
        if !cols.iter().any(|(name, _)| *name == column) {
            let col = if nullable {
                ColType::BigIntegerNull
            } else {
                ColType::BigInteger
            };
            stmt.col(col.to_def(Alias::new(&column)));
        }
        let mut fk = ForeignKey::create();
        fk.name(format!("fk-{table}-{column}-to-{parent}"));
        fk.from(Alias::new(&table), Alias::new(&column));
        fk.to(Alias::new(parent), Alias::new("id"));
        if nullable {
            fk.on_delete(ForeignKeyAction::SetNull);
            fk.on_update(ForeignKeyAction::NoAction);
        } else {
            fk.on_delete(ForeignKeyAction::Cascade);
            fk.on_update(ForeignKeyAction::Cascade);
        }
        stmt.foreign_key(&mut fk);
    }
    m.create_table(stmt).await
}

/// Drop a table.
///
/// # Errors
///
/// Propagates the database error.
pub async fn drop_table(m: &SchemaManager<'_>, table: &str) -> Result<(), DbErr> {
    m.drop_table(
        Table::drop()
            .table(Alias::new(normalize_table(table)))
            .to_owned(),
    )
    .await
}

/// Add a column.
///
/// # Errors
///
/// Propagates the database error.
pub async fn add_column(
    m: &SchemaManager<'_>,
    table: &str,
    name: &str,
    col: ColType,
) -> Result<(), DbErr> {
    m.alter_table(
        Table::alter()
            .table(Alias::new(normalize_table(table)))
            .add_column(col.to_def(Alias::new(name)))
            .to_owned(),
    )
    .await
}

/// Remove a column.
///
/// # Errors
///
/// Propagates the database error.
pub async fn remove_column(m: &SchemaManager<'_>, table: &str, name: &str) -> Result<(), DbErr> {
    m.alter_table(
        Table::alter()
            .table(Alias::new(normalize_table(table)))
            .drop_column(Alias::new(name))
            .to_owned(),
    )
    .await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_names_are_pluralised_snake_case() {
        assert_eq!(normalize_table("user"), "users");
        assert_eq!(normalize_table("users"), "users");
        assert_eq!(normalize_table("CarePathway"), "care_pathways");
    }

    #[test]
    fn reference_columns_are_singular() {
        assert_eq!(reference_id("users"), "user_id");
    }
}

//! `MySQL` pooling, migrations, and test resets over sqlx.
//!
//! This crate holds the operations every service repeats. It does not wrap
//! queries: a service writes its own SQL with `sqlx::query!`, so a reviewer
//! reads exactly what runs.
//!
//! It has the same shape as `axa-postgres-sqlx` and the other database crates:
//! a [`Pool`], a [`PoolConfig`], [`connect`], [`ping`], [`migrate`],
//! [`revert`], [`pending`], [`truncate`], [`dangerously_recreate`],
//! [`is_unique_violation`], and [`quote_identifier`], with [`status`] and
//! [`Db`] besides.
//!
//! What differs for `MySQL`:
//!
//! - URLs are `mysql://user:password@host:port/database`. TLS is asked for
//!   with the query parameter `ssl-mode`, one of `DISABLED`, `PREFERRED` (the
//!   default), `REQUIRED`, `VERIFY_CA`, or `VERIFY_IDENTITY`, as in
//!   `mysql://app@db/app?ssl-mode=VERIFY_IDENTITY`.
//! - [`quote_identifier`] quotes with backticks.
//! - `MySQL` commits each DDL statement as it runs, so a migration is not
//!   atomic. If a migration fails after a statement that changed the schema,
//!   that change stays, and sqlx has already recorded the migration as not
//!   successful. [`migrate`] then fails with [`MigrateError::Dirty`] until the
//!   database is put right by hand, or recreated in a test. Keep each
//!   migration to one schema change where you can.
//! - [`truncate`] empties each table with foreign key checks off, because
//!   `MySQL` has no `TRUNCATE ... CASCADE`. Rows in other tables that point at
//!   an emptied table are left as they are, so empty those tables too.
//! - [`dangerously_recreate`] drops every table and view in `DATABASE()`, with
//!   foreign key checks off, then migrates.
//!
//! ```no_run
//! use axa_mysql_sqlx::{PoolConfig, connect, migrate, sqlx};
//!
//! static MIGRATOR: sqlx::migrate::Migrator = sqlx::migrate::Migrator::DEFAULT;
//!
//! # async fn run() -> Result<(), Box<dyn std::error::Error>> {
//! let pool = connect(&PoolConfig::new("mysql://app@localhost:3306/app")).await?;
//! migrate(&pool, &MIGRATOR).await?;
//! # Ok(())
//! # }
//! ```

use std::{
    ops::{Deref, DerefMut},
    time::Duration,
};

pub use sqlx;
use sqlx::{
    AssertSqlSafe, MySql, MySqlConnection, MySqlPool, Row,
    migrate::{MigrateError, Migrator},
    mysql::MySqlPoolOptions,
    pool::PoolConnection,
};

/// The handle a service holds: the pool.
pub type Pool = MySqlPool;

/// What this crate's connection and query functions return on failure.
pub type Error = sqlx::Error;

/// Pool settings.
#[derive(Clone, PartialEq, Eq)]
pub struct PoolConfig {
    /// Connection string, such as `mysql://user:password@host:3306/app`.
    pub uri: String,
    /// Connections kept open.
    pub min_connections: u32,
    /// Largest number of connections.
    pub max_connections: u32,
    /// How long to wait for a connection, in milliseconds.
    pub connect_timeout_ms: u64,
    /// How long an idle connection stays open, in milliseconds.
    pub idle_timeout_ms: u64,
    /// `MySQL`'s `max_execution_time` on every connection, in milliseconds, which
    /// stops a read-only `SELECT` that runs longer, and no other statement. `0` sets
    /// none.
    pub statement_timeout_ms: u64,
    /// Make every transaction read-only, with `transaction_read_only`, as for a read
    /// replica or a reporting service, so that a write is refused by the database.
    pub read_only: bool,
}

impl std::fmt::Debug for PoolConfig {
    /// Leaves the connection string out, because it can carry a password.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PoolConfig")
            .field("min_connections", &self.min_connections)
            .field("max_connections", &self.max_connections)
            .field("connect_timeout_ms", &self.connect_timeout_ms)
            .field("idle_timeout_ms", &self.idle_timeout_ms)
            .field("statement_timeout_ms", &self.statement_timeout_ms)
            .field("read_only", &self.read_only)
            .finish_non_exhaustive()
    }
}

impl PoolConfig {
    /// Settings for `uri` with a small pool.
    #[must_use]
    pub fn new(uri: impl Into<String>) -> Self {
        Self {
            uri: uri.into(),
            min_connections: 1,
            max_connections: 10,
            connect_timeout_ms: 5_000,
            idle_timeout_ms: 600_000,
            statement_timeout_ms: 0,
            read_only: false,
        }
    }

    /// The sqlx options these settings describe, with the session settings set on
    /// each connection as it opens.
    #[must_use]
    pub fn options(&self) -> MySqlPoolOptions {
        let setup = self.session_statement();
        MySqlPoolOptions::new()
            .min_connections(self.min_connections)
            .max_connections(self.max_connections)
            .acquire_timeout(Duration::from_millis(self.connect_timeout_ms))
            .idle_timeout(Duration::from_millis(self.idle_timeout_ms))
            .after_connect(move |connection, _meta| {
                let setup = setup.clone();
                Box::pin(async move {
                    if let Some(setup) = setup {
                        sqlx::raw_sql(AssertSqlSafe(setup))
                            .execute(connection)
                            .await?;
                    }
                    Ok(())
                })
            })
    }

    /// The one statement that sets the session settings on a new connection, or
    /// `None` when there are none to set.
    #[must_use]
    pub fn session_statement(&self) -> Option<String> {
        session_statement(self.statement_timeout_ms, self.read_only)
    }
}

/// `SET SESSION` for each session setting asked for, as one statement, or `None`.
/// The values are a number and a fixed word, so nothing a caller sends reaches it.
fn session_statement(statement_timeout_ms: u64, read_only: bool) -> Option<String> {
    let mut settings = Vec::new();
    if statement_timeout_ms > 0 {
        settings.push(format!(
            "SESSION max_execution_time = {statement_timeout_ms}"
        ));
    }
    if read_only {
        settings.push("SESSION transaction_read_only = ON".to_string());
    }
    (!settings.is_empty()).then(|| format!("SET {}", settings.join(", ")))
}

/// Open a pool and prove it works with one connection.
///
/// # Errors
///
/// Fails when the database cannot be reached, or the URL is not a `MySQL`
/// one, such as an unknown `ssl-mode`.
pub async fn connect(config: &PoolConfig) -> Result<MySqlPool, sqlx::Error> {
    config.options().connect(&config.uri).await
}

/// Check that the database answers.
///
/// # Errors
///
/// Fails when it does not.
pub async fn ping(pool: &MySqlPool) -> Result<(), sqlx::Error> {
    sqlx::query("SELECT 1").execute(pool).await?;
    Ok(())
}

/// Where a function gets its connection: the pool, or a connection the caller
/// holds, usually an open transaction, so one function serves both.
///
/// `impl sqlx::Acquire` says the same, but its associated types stop the future
/// being `Send`, which Axum handlers and `tokio::spawn` need.
///
/// ```no_run
/// use axa_mysql_sqlx::{Db, sqlx};
///
/// async fn count(db: impl Into<Db<'_>>) -> Result<i64, sqlx::Error> {
///     let mut conn = db.into().acquire().await?;
///     sqlx::query_scalar("SELECT count(*) FROM items")
///         .fetch_one(&mut *conn)
///         .await
/// }
/// ```
pub enum Db<'a> {
    /// Take a connection from the pool for the length of the call.
    Pool(&'a MySqlPool),
    /// Use the caller's connection.
    Conn(&'a mut MySqlConnection),
}

impl<'a> From<&'a MySqlPool> for Db<'a> {
    fn from(pool: &'a MySqlPool) -> Self {
        Self::Pool(pool)
    }
}

impl<'a> From<&'a mut MySqlConnection> for Db<'a> {
    fn from(conn: &'a mut MySqlConnection) -> Self {
        Self::Conn(conn)
    }
}

impl<'a> Db<'a> {
    /// The connection to use.
    ///
    /// # Errors
    ///
    /// Fails when the pool has none to give.
    pub async fn acquire(self) -> Result<Conn<'a>, sqlx::Error> {
        match self {
            Self::Pool(pool) => Ok(Conn::Pooled(pool.acquire().await?)),
            Self::Conn(conn) => Ok(Conn::Borrowed(conn)),
        }
    }
}

/// A connection for the length of one call. It derefs to [`MySqlConnection`].
pub enum Conn<'a> {
    /// Taken from the pool, and given back when dropped.
    Pooled(PoolConnection<MySql>),
    /// The caller's.
    Borrowed(&'a mut MySqlConnection),
}

impl Deref for Conn<'_> {
    type Target = MySqlConnection;

    fn deref(&self) -> &MySqlConnection {
        match self {
            Self::Pooled(conn) => conn,
            Self::Borrowed(conn) => conn,
        }
    }
}

impl DerefMut for Conn<'_> {
    fn deref_mut(&mut self) -> &mut MySqlConnection {
        match self {
            Self::Pooled(conn) => conn,
            Self::Borrowed(conn) => conn,
        }
    }
}

/// Whether an error is a violated unique constraint, which a service usually
/// reports as `409` rather than `500`. This is `MySQL`'s duplicate key errors,
/// such as `1062` (`ER_DUP_ENTRY`).
#[must_use]
pub fn is_unique_violation(error: &sqlx::Error) -> bool {
    error
        .as_database_error()
        .is_some_and(sqlx::error::DatabaseError::is_unique_violation)
}

/// Quote a table name for use in SQL, with backticks.
///
/// Identifiers cannot be bound as parameters, so this is the one place names
/// reach SQL as text. Only lowercase ASCII letters, digits, and underscores
/// are accepted, starting with a letter or underscore. That is stricter than
/// `MySQL`, and it leaves nothing for an attacker to work with.
///
/// ```
/// assert_eq!(axa_mysql_sqlx::quote_identifier("users").as_deref(), Some("`users`"));
/// assert_eq!(axa_mysql_sqlx::quote_identifier("users; DROP TABLE x"), None);
/// ```
#[must_use]
pub fn quote_identifier(name: &str) -> Option<String> {
    let mut chars = name.chars();
    let first = chars.next()?;
    let valid = (first.is_ascii_lowercase() || first == '_')
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    valid.then(|| format!("`{name}`"))
}

/// Quote every name, failing on the first one [`quote_identifier`] refuses.
fn quote_all<S: AsRef<str>>(names: &[S]) -> Result<Vec<String>, sqlx::Error> {
    names
        .iter()
        .map(|name| {
            quote_identifier(name.as_ref()).ok_or_else(|| {
                sqlx::Error::Protocol(format!("invalid identifier: {}", name.as_ref()))
            })
        })
        .collect()
}

/// Run `statements` in order on one connection with foreign key checks off,
/// then turn them back on, whether or not a statement failed. A connection
/// whose checks could not be turned back on is closed rather than returned to
/// the pool.
async fn without_foreign_key_checks(
    pool: &MySqlPool,
    statements: Vec<String>,
) -> Result<(), sqlx::Error> {
    let mut conn = pool.acquire().await?;
    sqlx::query("SET FOREIGN_KEY_CHECKS = 0")
        .execute(&mut *conn)
        .await?;
    let mut result = Ok(());
    for sql in statements {
        if let Err(error) = sqlx::query(AssertSqlSafe(sql)).execute(&mut *conn).await {
            result = Err(error);
            break;
        }
    }
    if let Err(error) = sqlx::query("SET FOREIGN_KEY_CHECKS = 1")
        .execute(&mut *conn)
        .await
    {
        drop(conn.detach());
        return result.and(Err(error));
    }
    result
}

/// Apply pending migrations. Sqlx holds a `GET_LOCK` lock while it does, so
/// services booting together take turns.
///
/// `MySQL` commits each DDL statement as it runs, so a migration that fails
/// partway leaves the statements before the failure applied, and the next call
/// fails with [`MigrateError::Dirty`].
///
/// # Errors
///
/// Fails when a migration fails, an applied one no longer matches, or one was
/// left dirty.
pub async fn migrate(pool: &MySqlPool, migrator: &Migrator) -> Result<(), MigrateError> {
    migrator.run(pool).await
}

/// The newest applied versions, newest first. Empty on a database that has
/// never been migrated.
async fn applied_versions(pool: &MySqlPool) -> Result<Vec<i64>, sqlx::Error> {
    let found: i64 = sqlx::query(
        "SELECT count(*) AS found FROM information_schema.tables
         WHERE table_schema = DATABASE() AND table_name = '_sqlx_migrations'",
    )
    .fetch_one(pool)
    .await?
    .try_get("found")?;
    if found == 0 {
        return Ok(Vec::new());
    }
    let rows =
        sqlx::query("SELECT version FROM _sqlx_migrations WHERE success ORDER BY version DESC")
            .fetch_all(pool)
            .await?;
    rows.iter().map(|row| row.try_get("version")).collect()
}

/// Revert the newest `steps` migrations. Each needs a `.down.sql` file.
///
/// # Errors
///
/// Fails on a database error or a failed down migration.
pub async fn revert(pool: &MySqlPool, migrator: &Migrator, steps: u32) -> Result<(), MigrateError> {
    let applied = applied_versions(pool).await?;
    let steps = usize::try_from(steps).unwrap_or(usize::MAX);
    // `undo` reverts everything newer than its target, so the target is the
    // version just past the last one to revert, or 0 to revert them all.
    let target = applied.get(steps).copied().unwrap_or(0);
    migrator.undo(pool, target).await
}

/// One migration and whether it has run.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MigrationStatus {
    /// Its version.
    pub version: i64,
    /// Its description.
    pub description: String,
    /// Whether it has been applied. A migration left dirty by a failure is
    /// not.
    pub applied: bool,
}

/// Every migration in `migrator`, oldest first, with whether it has run.
///
/// # Errors
///
/// Fails on a database error.
pub async fn status(
    pool: &MySqlPool,
    migrator: &Migrator,
) -> Result<Vec<MigrationStatus>, sqlx::Error> {
    let applied = applied_versions(pool).await?;
    Ok(migrator
        .iter()
        .filter(|migration| !migration.migration_type.is_down_migration())
        .map(|migration| MigrationStatus {
            version: migration.version,
            description: migration.description.to_string(),
            applied: applied.contains(&migration.version),
        })
        .collect())
}

/// The names of the migrations in `migrator` not yet applied, in order, each as
/// `version_description`.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending(pool: &MySqlPool, migrator: &Migrator) -> Result<Vec<String>, sqlx::Error> {
    Ok(status(pool, migrator)
        .await?
        .into_iter()
        .filter(|migration| !migration.applied)
        .map(|migration| format!("{}_{}", migration.version, migration.description))
        .collect())
}

/// Empty `tables`, restarting their `AUTO_INCREMENT` counters. Each name goes
/// through [`quote_identifier`], and all are checked before anything is
/// emptied.
///
/// Each table is emptied with `TRUNCATE TABLE` on one connection with foreign
/// key checks off, so a table another references can be emptied. `MySQL` has
/// no `CASCADE` here: rows in other tables that point at an emptied table are
/// left as they are, so name those tables too. Each `TRUNCATE` commits as it
/// runs, so a failure partway leaves the tables before it empty.
///
/// # Errors
///
/// Fails on an invalid name or a database error.
pub async fn truncate<S: AsRef<str>>(pool: &MySqlPool, tables: &[S]) -> Result<(), sqlx::Error> {
    if tables.is_empty() {
        return Ok(());
    }
    let statements = quote_all(tables)?
        .into_iter()
        .map(|table| format!("TRUNCATE TABLE {table}"))
        .collect();
    without_foreign_key_checks(pool, statements).await
}

/// Drop every table and view in the connection's database, `DATABASE()`,
/// then migrate from nothing. This gives each test an empty schema, whatever
/// tables it touched.
///
/// **This destroys all data.** It exists for tests, and a service must never
/// reach it outside the `test` environment.
///
/// Tables are dropped with foreign key checks off, so their order does not
/// matter. Stored procedures, functions, and events are left in place, so a
/// migration that creates one should drop it first with `DROP ... IF EXISTS`.
///
/// # Errors
///
/// Fails when the URL names no database, on a database error, or on a name
/// [`quote_identifier`] refuses, before anything is dropped.
pub async fn dangerously_recreate(
    pool: &MySqlPool,
    migrator: &Migrator,
) -> Result<(), MigrateError> {
    let database: Option<String> = sqlx::query("SELECT DATABASE() AS name")
        .fetch_one(pool)
        .await?
        .try_get("name")?;
    if database.is_none() {
        return Err(sqlx::Error::Protocol("no database selected".to_owned()).into());
    }
    let rows = sqlx::query(
        "SELECT CAST(table_name AS CHAR) AS name, CAST(table_type AS CHAR) AS kind
         FROM information_schema.tables WHERE table_schema = DATABASE()",
    )
    .fetch_all(pool)
    .await?;
    let mut tables = Vec::new();
    let mut views = Vec::new();
    for row in &rows {
        let name: String = row.try_get("name")?;
        let kind: String = row.try_get("kind")?;
        if kind == "VIEW" {
            views.push(name);
        } else {
            tables.push(name);
        }
    }
    let mut statements = Vec::new();
    if !views.is_empty() {
        statements.push(format!("DROP VIEW {}", quote_all(&views)?.join(", ")));
    }
    if !tables.is_empty() {
        statements.push(format!("DROP TABLE {}", quote_all(&tables)?.join(", ")));
    }
    if !statements.is_empty() {
        without_foreign_key_checks(pool, statements).await?;
    }
    migrate(pool, migrator).await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn debug_text_leaves_out_the_connection_string() {
        let text = format!("{:?}", PoolConfig::new("mysql://me:hunter2@db/app"));
        assert!(!text.contains("hunter2"), "{text}");
        assert!(text.contains("max_connections"), "{text}");
    }

    #[test]
    fn identifiers_are_quoted_with_backticks() {
        assert_eq!(quote_identifier("users").as_deref(), Some("`users`"));
        assert_eq!(quote_identifier("_a1").as_deref(), Some("`_a1`"));
    }

    #[test]
    fn unsafe_identifiers_are_refused() {
        for name in [
            "", "1users", "Users", "a b", "a\"b", "a`b", "a;b", "a.b", "users--", "é",
        ] {
            assert_eq!(quote_identifier(name), None, "{name:?}");
        }
    }

    #[test]
    fn quote_all_fails_on_any_bad_name() {
        assert!(quote_all(&["good", "also_good"]).is_ok());
        assert!(quote_all(&["good", "bad name"]).is_err());
    }

    #[test]
    fn pool_settings_reach_the_options() {
        let config = PoolConfig {
            min_connections: 2,
            max_connections: 7,
            connect_timeout_ms: 1_500,
            idle_timeout_ms: 9_000,
            ..PoolConfig::new("mysql://x")
        };
        let options = config.options();
        assert_eq!(options.get_min_connections(), 2);
        assert_eq!(options.get_max_connections(), 7);
        assert_eq!(options.get_acquire_timeout(), Duration::from_millis(1_500));
        assert_eq!(options.get_idle_timeout(), Some(Duration::from_secs(9)));
    }

    #[test]
    fn session_settings_become_one_set_statement() {
        assert_eq!(session_statement(0, false), None);
        assert_eq!(
            session_statement(5000, false).as_deref(),
            Some("SET SESSION max_execution_time = 5000")
        );
        assert_eq!(
            session_statement(0, true).as_deref(),
            Some("SET SESSION transaction_read_only = ON")
        );
        assert_eq!(
            session_statement(5000, true).as_deref(),
            Some("SET SESSION max_execution_time = 5000, SESSION transaction_read_only = ON")
        );
    }

    #[test]
    fn errors_that_are_not_from_the_database_are_not_unique_violations() {
        assert!(!is_unique_violation(&sqlx::Error::RowNotFound));
    }

    #[test]
    fn ssl_mode_is_read_from_the_url() {
        use sqlx::mysql::{MySqlConnectOptions, MySqlSslMode};
        for (mode, expected) in [
            ("DISABLED", MySqlSslMode::Disabled),
            ("PREFERRED", MySqlSslMode::Preferred),
            ("REQUIRED", MySqlSslMode::Required),
            ("VERIFY_CA", MySqlSslMode::VerifyCa),
            ("VERIFY_IDENTITY", MySqlSslMode::VerifyIdentity),
        ] {
            let url = format!("mysql://me@db:3306/app?ssl-mode={mode}");
            let options: MySqlConnectOptions = url.parse().unwrap();
            assert_eq!(
                format!("{:?}", options.get_ssl_mode()),
                format!("{expected:?}"),
                "{mode}"
            );
        }
        assert!(
            "mysql://me@db/app?ssl-mode=SOMETIMES"
                .parse::<MySqlConnectOptions>()
                .is_err()
        );
    }
}

/// `quote_identifier` over generated names: it quotes exactly the names of lowercase
/// letters, digits, and underscores that start with a letter or underscore, and nothing
/// else, so no name it passes can end the identifier or start another statement.
#[cfg(test)]
mod properties {
    use proptest::prelude::*;

    use super::quote_identifier;

    proptest! {
        #[test]
        fn a_safe_name_is_quoted_as_it_is(name in "[a-z_][a-z0-9_]{0,62}") {
            prop_assert_eq!(quote_identifier(&name), Some(format!("`{name}`")));
        }

        #[test]
        fn any_other_name_is_refused(name in "\\PC{0,40}") {
            let safe = name.chars().next().is_some_and(|c| c.is_ascii_lowercase() || c == '_')
                && name.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
            prop_assert_eq!(quote_identifier(&name).is_some(), safe);
            if let Some(quoted) = quote_identifier(&name) {
                prop_assert_eq!(quoted.matches('`').count(), 2);
            }
        }
    }
}

//! Toasty connections, migrations, and test resets for Axum services, on MySQL.
//!
//! This crate has the same shape as `axa-postgres-toasty` and the other Axa database
//! crates: a [`Pool`], a [`PoolConfig`], [`connect`], [`ping`], [`migrate`],
//! [`pending`], [`truncate`], [`dangerously_recreate`], [`is_unique_violation`], and
//! [`quote_identifier`]. `axa`'s `mysql-toasty` feature re-exports it as
//! `axa::mysql_toasty`, and makes [`Pool`] the service's `AppContext::db` when no other
//! database feature is on.
//!
//! ```no_run
//! # async fn example() -> toasty::Result<()> {
//! #[derive(Debug, toasty::Model)]
//! struct User {
//!     #[key]
//!     #[auto]
//!     id: u64,
//!     name: String,
//! }
//!
//! let config = axa_mysql_toasty::PoolConfig::new("mysql://app:secret@localhost:3306/app");
//! let db = axa_mysql_toasty::connect(&config, toasty::models!(User)).await?;
//! axa_mysql_toasty::ping(&db).await?;
//! # Ok(())
//! # }
//! ```
//!
//! What differs from Postgres:
//!
//! - URLs are `mysql://user:password@host:port/database`, and must name a database.
//!   Toasty's MySQL driver reads them with `sqlx`, so TLS is asked for with `sqlx`'s
//!   `ssl-mode` query parameter (`DISABLED`, `PREFERRED`, `REQUIRED`, `VERIFY_CA`, or
//!   `VERIFY_IDENTITY`), as with every Axa MySQL crate.
//! - [`quote_identifier`] uses backticks.
//! - [`truncate`] empties each table on one connection with foreign key checks off,
//!   then turns them back on. `TRUNCATE` restarts each table's `AUTO_INCREMENT`.
//! - [`dangerously_recreate`] drops every table in `DATABASE()`, with foreign key
//!   checks off, then migrates.
//! - MySQL commits each DDL statement as it goes, so a migration that fails part way
//!   leaves the statements before the failure applied, though Toasty does not record
//!   the migration as applied.
//! - [`error_number`] and [`sql_state`] read the MySQL error number and `SQLSTATE`
//!   from the `sqlx` error that Toasty's driver wraps. Toasty's driver turns a deadlock
//!   (1213) and a write in a read-only transaction (1792) into Toasty's own kinds of
//!   error, keeping only the message, so for those two neither is known.
//!
//! Toasty migrations go forward only: a [`MigrationSet`] has no down steps, so there
//! is no `revert`. Generate migrations with `toasty-cli`, embed them with
//! [`toasty::embed_migrations!`], and apply them with [`migrate`].

use std::{borrow::Cow, future::Future, pin::Pin, sync::Arc, time::Duration};

use sqlx::mysql::MySqlDatabaseError;
pub use toasty;
use toasty::{
    Db, ModelSet,
    db::{Capability, ConnectContext, Driver},
    migration::MigrationSet,
};
use toasty_core::{
    driver::{
        Connection, ExecResponse, Operation,
        operation::{RawSql, RawSqlRet},
    },
    schema::{
        Schema,
        db::{AppliedMigration, Migration},
        diff,
    },
    stmt::{Type, Value},
};

/// The handle a service holds: Toasty's [`Db`], which owns a connection pool.
pub type Pool = Db;

/// What this crate's functions return on failure.
pub type Error = toasty::Error;

/// The pool's settings. The URL is left out of its `Debug` text, as it may hold a
/// password.
#[derive(Clone, PartialEq, Eq)]
pub struct PoolConfig {
    /// The connection URL, such as `mysql://user:password@host:3306/database`.
    pub uri: String,
    /// The most connections the pool opens.
    pub max_connections: u32,
    /// How long to wait to open a connection, or for a free one, in milliseconds.
    pub connect_timeout_ms: u64,
    /// How long a connection may sit unused before it is closed, in milliseconds.
    pub idle_timeout_ms: u64,
    /// `MySQL`'s `max_execution_time` on every connection, in milliseconds, which
    /// stops a read-only `SELECT` that runs longer, and no other statement. `0` sets
    /// none.
    pub statement_timeout_ms: u64,
    /// Make every transaction read-only, with `transaction_read_only`, as for a read
    /// replica or a reporting service, so that a write is refused by the database.
    pub read_only: bool,
}

impl std::fmt::Debug for PoolConfig {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PoolConfig")
            .field("max_connections", &self.max_connections)
            .field("connect_timeout_ms", &self.connect_timeout_ms)
            .field("idle_timeout_ms", &self.idle_timeout_ms)
            .field("statement_timeout_ms", &self.statement_timeout_ms)
            .field("read_only", &self.read_only)
            .finish_non_exhaustive()
    }
}

impl PoolConfig {
    /// Settings for `uri`, with the same defaults as the other Axa database crates:
    /// ten connections, a five-second wait, and ten minutes idle.
    #[must_use]
    pub fn new(uri: impl Into<String>) -> Self {
        Self {
            uri: uri.into(),
            max_connections: 10,
            connect_timeout_ms: 5_000,
            idle_timeout_ms: 600_000,
            statement_timeout_ms: 0,
            read_only: false,
        }
    }

    /// The one statement that sets the session settings on a new connection, or
    /// `None` when there are none to set.
    #[must_use]
    pub fn session_statement(&self) -> Option<String> {
        session_statement(self.statement_timeout_ms, self.read_only)
    }

    /// A Toasty builder with these settings and `models`, ready to connect.
    #[must_use]
    pub fn builder(&self, models: ModelSet) -> toasty::db::Builder {
        let wait = Some(Duration::from_millis(self.connect_timeout_ms));
        let mut builder = Db::builder();
        builder
            .models(models)
            .max_pool_size(usize::try_from(self.max_connections).unwrap_or(usize::MAX))
            .pool_wait_timeout(wait)
            .pool_create_timeout(wait)
            .pool_max_connection_idle_time(Some(Duration::from_millis(self.idle_timeout_ms)));
        builder
    }
}

/// Connect to the database for `models`, and check that it answers.
///
/// # Errors
///
/// Fails when the URL is not one Toasty reads, or the database cannot be reached.
pub async fn connect(config: &PoolConfig, models: ModelSet) -> Result<Pool, Error> {
    let builder = &mut config.builder(models);
    let db = match config.session_statement() {
        Some(setup) => {
            let driver = toasty::db::Connect::new(&config.uri).await?;
            builder
                .build(Setting {
                    driver,
                    setup: setup.into(),
                })
                .await?
        }
        None => builder.connect(&config.uri).await?,
    };
    ping(&db).await?;
    Ok(db)
}

/// `SET SESSION` for each session setting asked for, as one statement, or `None`.
/// The values are a number and a fixed word, so nothing a caller sends reaches it.
fn session_statement(statement_timeout_ms: u64, read_only: bool) -> Option<String> {
    let mut settings = Vec::new();
    if statement_timeout_ms > 0 {
        settings.push(format!(
            "SESSION max_execution_time = {statement_timeout_ms}"
        ));
    }
    if read_only {
        settings.push("SESSION transaction_read_only = ON".to_string());
    }
    (!settings.is_empty()).then(|| format!("SET {}", settings.join(", ")))
}

/// A future a driver returns, as `async_trait` writes it.
type Boxed<'a, T> = Pin<Box<dyn Future<Output = toasty::Result<T>> + Send + 'a>>;

/// Toasty's driver, with the session settings set on each connection before its
/// first operation. Toasty's `MySQL` driver has no hook of its own for it.
#[derive(Debug)]
struct Setting {
    driver: toasty::db::Connect,
    setup: Arc<str>,
}

/// A connection, and the settings it has still to set, if any.
#[derive(Debug)]
struct SettingConnection {
    inner: Box<dyn Connection>,
    setup: Option<Arc<str>>,
}

impl Driver for Setting {
    fn url(&self) -> Cow<'_, str> {
        self.driver.url()
    }

    fn capability(&self) -> &'static Capability {
        self.driver.capability()
    }

    fn connect<'a, 'b, 'c>(&'a self, cx: &'b ConnectContext) -> Boxed<'c, Box<dyn Connection>>
    where
        'a: 'c,
        'b: 'c,
        Self: 'c,
    {
        Box::pin(async move {
            let inner = self.driver.connect(cx).await?;
            Ok(Box::new(SettingConnection {
                inner,
                setup: Some(self.setup.clone()),
            }) as Box<dyn Connection>)
        })
    }

    fn max_connections(&self) -> Option<usize> {
        self.driver.max_connections()
    }

    fn generate_migration(&self, schema_diff: &diff::Schema<'_>) -> Migration {
        self.driver.generate_migration(schema_diff)
    }

    fn reset_db<'a, 'c>(&'a self) -> Boxed<'c, ()>
    where
        'a: 'c,
        Self: 'c,
    {
        self.driver.reset_db()
    }
}

impl Connection for SettingConnection {
    fn exec<'a, 'b, 'c>(
        &'a mut self,
        schema: &'b Arc<Schema>,
        plan: Operation,
    ) -> Boxed<'c, ExecResponse>
    where
        'a: 'c,
        'b: 'c,
        Self: 'c,
    {
        Box::pin(async move {
            // Kept until it succeeds, so a connection never runs a query without it.
            if let Some(setup) = &self.setup {
                let set = RawSql {
                    sql: setup.to_string(),
                    params: Vec::new(),
                    ret: RawSqlRet::None,
                };
                self.inner.exec(schema, set.into()).await?;
                self.setup = None;
            }
            self.inner.exec(schema, plan).await
        })
    }

    fn is_valid(&self) -> bool {
        self.inner.is_valid()
    }

    fn ping<'a, 'c>(&'a mut self) -> Boxed<'c, ()>
    where
        'a: 'c,
        Self: 'c,
    {
        self.inner.ping()
    }

    fn push_schema<'a, 'b, 'c>(&'a mut self, schema: &'b Schema) -> Boxed<'c, ()>
    where
        'a: 'c,
        'b: 'c,
        Self: 'c,
    {
        self.inner.push_schema(schema)
    }

    fn applied_migrations<'a, 'c>(&'a mut self) -> Boxed<'c, Vec<AppliedMigration>>
    where
        'a: 'c,
        Self: 'c,
    {
        self.inner.applied_migrations()
    }

    fn apply_migration<'a, 'b, 'm, 'c>(
        &'a mut self,
        id: u64,
        name: &'b str,
        migration: &'m Migration,
    ) -> Boxed<'c, ()>
    where
        'a: 'c,
        'b: 'c,
        'm: 'c,
        Self: 'c,
    {
        self.inner.apply_migration(id, name, migration)
    }
}

/// Check the database connection.
///
/// # Errors
///
/// Fails when the database does not answer.
pub async fn ping(pool: &Pool) -> Result<(), Error> {
    let mut db = pool.clone();
    toasty::sql::query("SELECT 1").exec(&mut db).await?;
    Ok(())
}

/// Apply every migration in `migrations` not yet applied, in order, returning how
/// many were applied.
///
/// # Errors
///
/// Fails on a database error, and then no later migration is tried.
pub async fn migrate(pool: &Pool, migrations: &MigrationSet) -> Result<usize, Error> {
    Ok(migrations.apply(pool).await?.applied())
}

/// The ids Toasty has recorded as applied, from its `__toasty_migrations` table.
async fn applied_ids(pool: &Pool) -> Result<Vec<u64>, Error> {
    let mut db = pool.clone();
    let found = toasty::sql::query(
        "SELECT CAST(COUNT(*) AS SIGNED) FROM information_schema.tables
         WHERE table_schema = DATABASE() AND table_name = '__toasty_migrations'",
    )
    .column_types([Type::I64])
    .exec(&mut db)
    .await?;
    let found = match first_field(&found) {
        Some(Value::I64(count)) => *count,
        _ => 0,
    };
    if found == 0 {
        return Ok(Vec::new());
    }
    let rows = toasty::sql::query("SELECT id FROM __toasty_migrations")
        .column_types([Type::U64])
        .exec(&mut db)
        .await?;
    Ok(rows
        .iter()
        .filter_map(|row| match first_field(std::slice::from_ref(row)) {
            Some(Value::U64(id)) => Some(*id),
            _ => None,
        })
        .collect())
}

/// The first column of the first row.
fn first_field(rows: &[Value]) -> Option<&Value> {
    match rows.first()? {
        Value::Record(record) => record.fields.first(),
        _ => None,
    }
}

/// The names of the migrations in `migrations` not yet applied, in order.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending(pool: &Pool, migrations: &MigrationSet) -> Result<Vec<String>, Error> {
    let applied = applied_ids(pool).await?;
    Ok(migrations
        .migrations()
        .iter()
        .filter(|migration| !applied.contains(&migration.id()))
        .map(|migration| migration.name().to_string())
        .collect())
}

/// The MySQL error the database answered with, when `error` came from it. Toasty
/// names only a few kinds of database error itself, so this is read from the `sqlx`
/// error that Toasty's MySQL driver wraps.
fn mysql_error(error: &Error) -> Option<&MySqlDatabaseError> {
    let mut source: Option<&(dyn std::error::Error + 'static)> = Some(error);
    while let Some(current) = source {
        if let Some(sqlx) = current.downcast_ref::<sqlx::Error>() {
            return sqlx
                .as_database_error()?
                .try_downcast_ref::<MySqlDatabaseError>();
        }
        if let Some(mysql) = current.downcast_ref::<MySqlDatabaseError>() {
            return Some(mysql);
        }
        source = current.source();
    }
    None
}

/// The MySQL error number the database answered with, such as `1062` for a
/// duplicate entry, when `error` came from the database. `None` for a deadlock
/// (1213) or a write in a read-only transaction (1792), which Toasty's driver turns
/// into its own kinds of error without the number.
#[must_use]
pub fn error_number(error: &Error) -> Option<u16> {
    mysql_error(error).map(MySqlDatabaseError::number)
}

/// The `SQLSTATE` code MySQL answered with, such as `23000` for an integrity
/// constraint violation, when `error` came from the database and MySQL sent one.
/// MySQL's `SQLSTATE` is a broad class, so [`error_number`] says more.
#[must_use]
pub fn sql_state(error: &Error) -> Option<&str> {
    mysql_error(error)?.code()
}

/// Whether `error` is the database refusing a duplicate under a unique constraint:
/// one of MySQL's duplicate-key error numbers (1022, 1062, 1169, 1586, or 1859), as
/// `sqlx` classes them.
#[must_use]
pub fn is_unique_violation(error: &Error) -> bool {
    mysql_error(error).is_some_and(|mysql| {
        sqlx::error::DatabaseError::kind(mysql) == sqlx::error::ErrorKind::UniqueViolation
    })
}

/// `name` in backticks, when it is a plain lower-case identifier: a letter or `_`,
/// then letters, digits, and `_`. Anything else is refused, so it cannot carry SQL.
#[must_use]
pub fn quote_identifier(name: &str) -> Option<String> {
    let mut chars = name.chars();
    let first = chars.next()?;
    let valid = (first.is_ascii_lowercase() || first == '_')
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    valid.then(|| format!("`{name}`"))
}

fn quote_all<S: AsRef<str>>(names: &[S]) -> Result<Vec<String>, Error> {
    names
        .iter()
        .map(|name| {
            quote_identifier(name.as_ref()).ok_or_else(|| {
                toasty::Error::invalid_statement(format!("invalid identifier: {}", name.as_ref()))
            })
        })
        .collect()
}

/// Run `statements` on one connection with foreign key checks off, and turn them
/// back on afterwards, whether or not a statement failed.
async fn without_foreign_key_checks(pool: &Pool, statements: &[String]) -> Result<(), Error> {
    let mut conn = pool.connection().await?;
    toasty::sql::statement("SET FOREIGN_KEY_CHECKS = 0")
        .exec(&mut conn)
        .await?;
    let mut outcome = Ok(());
    for statement in statements {
        if let Err(error) = toasty::sql::statement(statement.as_str())
            .exec(&mut conn)
            .await
        {
            outcome = Err(error);
            break;
        }
    }
    let restored = toasty::sql::statement("SET FOREIGN_KEY_CHECKS = 1")
        .exec(&mut conn)
        .await;
    outcome?;
    restored?;
    Ok(())
}

/// Empty `tables` and restart their `AUTO_INCREMENT`, for a test, with foreign key
/// checks off on one connection, and back on afterwards. Every name must be a plain
/// lower-case identifier.
///
/// # Errors
///
/// Fails on a database error, or a name that is not a plain identifier, before
/// anything is emptied.
pub async fn truncate<S: AsRef<str>>(pool: &Pool, tables: &[S]) -> Result<(), Error> {
    if tables.is_empty() {
        return Ok(());
    }
    let statements: Vec<String> = quote_all(tables)?
        .into_iter()
        .map(|table| format!("TRUNCATE TABLE {table}"))
        .collect();
    without_foreign_key_checks(pool, &statements).await
}

/// Drop every table in the connection's database, `DATABASE()`, Toasty's record of
/// migrations among them, with foreign key checks off, then apply `migrations` from
/// the start. This destroys data: `axa::cli` allows it only in development and
/// test, and only when confirmed.
///
/// # Errors
///
/// Fails on a database error, or a table whose name is not a plain identifier,
/// before anything is dropped.
pub async fn dangerously_recreate(pool: &Pool, migrations: &MigrationSet) -> Result<(), Error> {
    let mut db = pool.clone();
    let rows = toasty::sql::query(
        "SELECT CAST(table_name AS CHAR) FROM information_schema.tables
         WHERE table_schema = DATABASE() AND table_type = 'BASE TABLE'",
    )
    .column_types([Type::String])
    .exec(&mut db)
    .await?;
    let tables: Vec<String> = rows
        .iter()
        .filter_map(|row| match first_field(std::slice::from_ref(row)) {
            Some(Value::String(name)) => Some(name.clone()),
            _ => None,
        })
        .collect();
    if !tables.is_empty() {
        let names = quote_all(&tables)?.join(", ");
        without_foreign_key_checks(pool, &[format!("DROP TABLE {names}")]).await?;
    }
    migrate(pool, migrations).await?;
    Ok(())
}

