//! The caller's tenant, read from the verified token and from nowhere else.
//!
//! A service that many tenants share keeps them apart by the tenant each request runs
//! in. Taking that from a header, a path, a host, or a body would let any caller name
//! any tenant, so [`Tenant`] reads only what the guard verified and the policy allowed.

use std::{fmt, sync::Arc};

use authentication_verifier::Claims;
use axa_problem::Problem;
use axum::{
    extract::{FromRequestParts, Request, State},
    http::{Extensions, StatusCode, request::Parts},
    middleware::Next,
    response::{IntoResponse, Response},
};

use crate::{Allowed, Guard, invalid_token};

/// The attribute in a token's `attrs` that names the tenant, unless
/// [`GuardConfig::tenant_attribute`](crate::GuardConfig::tenant_attribute) names another.
pub const DEFAULT_TENANT_ATTRIBUTE: &str = "tenant";

/// The longest tenant id, which a DNS label also allows.
pub const MAX_TENANT_ID_LEN: usize = 63;

/// The tenant a verified, allowed caller belongs to.
///
/// As a handler argument, it refuses a request with no verified caller as `401`, and a
/// caller whose token names no tenant, more than one, or one that is not a tenant id as
/// `403`, code `no_tenant`, before the handler runs:
///
/// ```
/// use axa_paseto_auth::Tenant;
///
/// async fn list(tenant: Tenant) -> String {
///     format!("the todos of {tenant}")
/// }
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Tenant(String);

impl Tenant {
    /// The one tenant `claims` name under `attribute`, if it is a tenant id.
    #[must_use]
    pub fn from_claims(claims: &Claims, attribute: &str) -> Option<Self> {
        match claims.attrs.get(attribute).map(Vec::as_slice) {
            Some([id]) if is_tenant_id(id) => Some(Self(id.clone())),
            _ => None,
        }
    }

    /// The tenant of the caller the guard verified and allowed, read from a request's
    /// extensions as the extractor reads it, but writing no audit line: for code that
    /// runs inside the guard before the handler, such as the key of a limit per tenant.
    ///
    /// # Errors
    ///
    /// As the extractor: [`TenantRejection::Unauthenticated`] when no caller was
    /// verified and allowed, and [`TenantRejection::NoTenant`] when the caller's token
    /// names no tenant, more than one, or one that is not a tenant id.
    pub fn from_extensions(extensions: &Extensions) -> Result<Self, TenantRejection> {
        // Only what the guard allowed. With no guard there is nothing here, and this
        // fails closed.
        let allowed = extensions
            .get::<Allowed>()
            .ok_or(TenantRejection::Unauthenticated)?;
        let attribute = extensions
            .get::<Arc<Guard>>()
            .map_or(DEFAULT_TENANT_ATTRIBUTE, |guard| {
                guard.config().tenant_attribute.as_str()
            });
        Self::from_claims(&allowed.claims, attribute).ok_or(TenantRejection::NoTenant)
    }

    /// The tenant id, to bind in a query or a key.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for Tenant {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl AsRef<str> for Tenant {
    fn as_ref(&self) -> &str {
        &self.0
    }
}

/// Whether `id` is a tenant id: lower-case ASCII letters, digits, and hyphens, not
/// starting or ending with a hyphen, from 1 to 63 characters, as a DNS label is. So it
/// is safe in a key, a log line, a subdomain, or a Postgres setting.
#[must_use]
pub fn is_tenant_id(id: &str) -> bool {
    (1..=MAX_TENANT_ID_LEN).contains(&id.len())
        && !id.starts_with('-')
        && !id.ends_with('-')
        && id
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
}

/// Why a request has no [`Tenant`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TenantRejection {
    /// No caller was verified and allowed: no guard, a public path, or enforcement off.
    /// A `401`, with `WWW-Authenticate: Bearer`.
    Unauthenticated,
    /// The caller's token names no tenant, more than one, or one that is not a tenant
    /// id. A `403`, code `no_tenant`.
    NoTenant,
}

impl IntoResponse for TenantRejection {
    fn into_response(self) -> Response {
        match self {
            Self::Unauthenticated => invalid_token().into_response(),
            Self::NoTenant => Problem::new(StatusCode::FORBIDDEN)
                .with_detail("forbidden")
                .with_extension("code", "no_tenant".into())
                .into_response(),
        }
    }
}

impl<S: Send + Sync> FromRequestParts<S> for Tenant {
    type Rejection = TenantRejection;

    fn from_request_parts(
        parts: &mut Parts,
        _state: &S,
    ) -> impl Future<Output = Result<Self, Self::Rejection>> + Send {
        std::future::ready(tenant_of(parts))
    }
}

fn tenant_of(parts: &Parts) -> Result<Tenant, TenantRejection> {
    let tenant = Tenant::from_extensions(&parts.extensions);
    if tenant == Err(TenantRejection::NoTenant)
        && let Some(allowed) = parts.extensions.get::<Allowed>()
    {
        // An audit line, as the guard writes for its own refusals. The subject is the
        // caller's id, and the attribute's values are not written, as they came from
        // the token.
        tracing::warn!(
            status = 403,
            subject = allowed.claims.sub.as_str(),
            reason = "no_tenant",
            "auth_refused",
        );
    }
    tenant
}

/// The check [`refuse_suspended`] asks of each verified tenant: `true` when the tenant
/// is suspended. The service passes it in, as suspension belongs to the service that
/// issues tokens, while a token already issued lives until it expires.
///
/// The check runs on every request, so it should answer from memory, such as a set
/// the service keeps fresh from its issuer's events or by polling, and never wait on
/// the network.
///
/// ```
/// use std::{collections::HashSet, sync::{Arc, RwLock}};
///
/// use axa_paseto_auth::SuspendedCheck;
///
/// let suspended: Arc<RwLock<HashSet<String>>> = Arc::default();
/// let list = Arc::clone(&suspended);
/// let check = SuspendedCheck::new(move |tenant| {
///     // A poisoned lock fails closed: every tenant is refused until it is fixed.
///     list.read().map_or(true, |list| list.contains(tenant.as_str()))
/// });
/// suspended.write().unwrap().insert("acme".to_string());
/// ```
#[derive(Clone)]
pub struct SuspendedCheck(Arc<dyn Fn(&Tenant) -> bool + Send + Sync>);

impl SuspendedCheck {
    /// A check that calls `is_suspended` for each verified tenant.
    pub fn new(is_suspended: impl Fn(&Tenant) -> bool + Send + Sync + 'static) -> Self {
        Self(Arc::new(is_suspended))
    }

    /// Whether `tenant` is suspended.
    #[must_use]
    pub fn is_suspended(&self, tenant: &Tenant) -> bool {
        (self.0)(tenant)
    }
}

impl fmt::Debug for SuspendedCheck {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("SuspendedCheck").finish_non_exhaustive()
    }
}

/// Middleware refusing a caller whose tenant [`SuspendedCheck`] says is suspended, as
/// `403`, code `tenant_suspended`, with an audit line naming the subject and tenant.
/// Add it inside the guard, as the tenant is known only once the guard has verified
/// the token:
///
/// ```ignore
/// routes
///     .layer(from_fn_with_state(check, axa_paseto_auth::refuse_suspended))
///     .layer(from_fn_with_state(Arc::new(guard), axa_paseto_auth::middleware))
/// ```
///
/// A request with no tenant, as on a public path, passes on, for the handler's
/// [`Tenant`] to refuse as it would.
pub async fn refuse_suspended(
    State(check): State<SuspendedCheck>,
    request: Request,
    next: Next,
) -> Response {
    if let Ok(tenant) = Tenant::from_extensions(request.extensions())
        && check.is_suspended(&tenant)
    {
        let subject = request
            .extensions()
            .get::<Allowed>()
            .map(|allowed| allowed.claims.sub.clone());
        tracing::warn!(
            status = 403,
            subject = subject.as_deref(),
            tenant = tenant.as_str(),
            reason = "tenant_suspended",
            "auth_refused",
        );
        return Problem::new(StatusCode::FORBIDDEN)
            .with_detail("forbidden")
            .with_extension("code", "tenant_suspended".into())
            .into_response();
    }
    next.run(request).await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_tenant_reads_as_its_id_every_way() {
        let tenant = Tenant("acme".to_string());
        assert_eq!(tenant.as_ref(), "acme");
        assert_eq!(tenant.as_str(), "acme");
        assert_eq!(tenant.to_string(), "acme");
    }

    #[test]
    fn a_suspended_check_shows_nothing_of_its_closure() {
        let check = SuspendedCheck::new(|_| false);
        assert_eq!(format!("{check:?}"), "SuspendedCheck { .. }");
    }
}

//! Diesel pooling, migrations, and test resets, in pure Rust.
//!
//! This uses `diesel-async`, so there is no `libpq` to link and no C in the
//! database path. It holds the operations every service repeats, and a service
//! writes its own queries with Diesel as usual.
//!
//! ```ignore
//! use axa_postgres_diesel::{PoolConfig, connect, migrate};
//! use diesel_migrations::{EmbeddedMigrations, embed_migrations};
//!
//! const MIGRATIONS: EmbeddedMigrations = embed_migrations!();
//!
//! let pool = connect(&PoolConfig::new("postgres://localhost/app")).await?;
//! migrate(&pool, MIGRATIONS).await?;
//! ```
//!
//! # TLS
//!
//! Connections negotiate TLS with `Rustls`, trusting the standard web roots.
//! The connection string's `sslmode` decides how strict that is, and in
//! production it should say `sslmode=require`, because the `prefer` default
//! falls back to plain text when a server offers no TLS.
//!
//! A database behind a private certificate authority needs a custom connection
//! setup, which [`pool_with_tls`] accepts.

use std::{
    sync::{
        Arc, OnceLock,
        atomic::{AtomicU64, Ordering},
    },
    time::{Duration, Instant},
};

use deadpool::Runtime;
pub use diesel;
use diesel::{
    ConnectionError, ConnectionResult, QueryableByName,
    migration::MigrationSource,
    pg::Pg,
    result::{DatabaseErrorKind, Error as QueryError},
    sql_types::{Bool, Text},
};
pub use diesel_async;
use diesel_async::{
    AsyncConnection, AsyncMigrationHarness, AsyncPgConnection, RunQueryDsl, TransactionManager,
    pooled_connection::{
        AsyncDieselConnectionManager, ManagerConfig,
        deadpool::{BuildError, Hook, HookError, Object, Pool as DeadPool, PoolError},
    },
};
pub use diesel_migrations;
use diesel_migrations::MigrationHarness;
use tokio_postgres_rustls::MakeRustlsConnect;

/// A connection pool.
pub type Pool = DeadPool<AsyncPgConnection>;

/// A pooled connection.
pub type Connection = Object<AsyncPgConnection>;

/// A failure in this crate.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// The pool could not be built.
    #[error(transparent)]
    Build(#[from] BuildError),
    /// No connection could be had.
    #[error(transparent)]
    Pool(#[from] PoolError),
    /// A query failed.
    #[error(transparent)]
    Query(#[from] QueryError),
    /// A migration failed.
    #[error("migration failed: {0}")]
    Migration(String),
    /// A table or type name was refused by [`quote_identifier`].
    #[error("invalid identifier: {0}")]
    InvalidIdentifier(String),
}

/// Pool settings. The connection string is left out of the `Debug` text, as it may
/// hold a password.
#[derive(Clone, PartialEq, Eq)]
pub struct PoolConfig {
    /// Connection string.
    pub uri: String,
    /// Largest number of connections.
    pub max_connections: usize,
    /// How long a caller waits for a connection, whether a free one or a new one,
    /// before it gets an error.
    pub wait_timeout: Duration,
    /// Postgres's `statement_timeout` on every connection, in milliseconds. `0` sets
    /// none.
    pub statement_timeout_ms: u64,
    /// Postgres's `application_name` on every connection, so `pg_stat_activity` says
    /// which service a query came from. Empty sets none.
    pub application_name: String,
    /// Open every transaction read-only, as for a read replica or a reporting
    /// service, so that a write is refused by the database.
    pub read_only: bool,
}

impl std::fmt::Debug for PoolConfig {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PoolConfig")
            .field("max_connections", &self.max_connections)
            .field("wait_timeout", &self.wait_timeout)
            .field("statement_timeout_ms", &self.statement_timeout_ms)
            .field("application_name", &self.application_name)
            .field("read_only", &self.read_only)
            .finish_non_exhaustive()
    }
}

impl PoolConfig {
    /// Settings for `uri` with a small pool.
    #[must_use]
    pub fn new(uri: impl Into<String>) -> Self {
        Self {
            uri: uri.into(),
            max_connections: 10,
            wait_timeout: Duration::from_secs(5),
            statement_timeout_ms: 0,
            application_name: String::new(),
            read_only: false,
        }
    }
}

/// TLS settings trusting the standard web roots, as [`connect`] uses. Pass them to
/// [`pool_with_tls`] to build a pool that connects only when first used.
///
/// # Errors
///
/// Fails when `rustls` refuses the protocol versions, which it does not for its own
/// defaults.
pub fn web_tls() -> Result<rustls::ClientConfig, rustls::Error> {
    let roots = rustls::RootCertStore {
        roots: webpki_roots::TLS_SERVER_ROOTS.to_vec(),
    };
    Ok(rustls::ClientConfig::builder_with_provider(Arc::new(
        rustls::crypto::ring::default_provider(),
    ))
    .with_safe_default_protocol_versions()?
    .with_root_certificates(roots)
    .with_no_client_auth())
}

/// Open one connection using `tls`.
async fn establish(uri: String, tls: rustls::ClientConfig) -> ConnectionResult<AsyncPgConnection> {
    let (client, connection) = tokio_postgres::connect(&uri, MakeRustlsConnect::new(tls))
        .await
        .map_err(|error| ConnectionError::BadConnection(error.to_string()))?;
    AsyncPgConnection::try_from_client_and_connection(client, connection).await
}

impl PoolConfig {
    /// The connection string with the session settings added, as every connection
    /// [`connect`] opens uses.
    ///
    /// # Errors
    ///
    /// When the URL sets `options` already and a statement timeout or read-only mode
    /// is set here too, or when the application name is not one Postgres keeps as it
    /// is.
    pub fn connection_uri(&self) -> Result<String, Error> {
        session_uri(
            &self.uri,
            self.statement_timeout_ms,
            &self.application_name,
            self.read_only,
        )
        .map_err(|problem| Error::Query(QueryError::QueryBuilderError(problem.into())))
    }
}

/// `uri` with each session setting added as a libpq connection parameter, so that
/// every connection the pool opens starts with them, at no extra round trip:
/// `statement_timeout` and `default_transaction_read_only` in `options`, and
/// `application_name`.
///
/// An `application_name` the URL already names is kept. `options` the URL already
/// names, with a setting here to add, is refused, rather than either one silently
/// replacing the other.
fn session_uri(
    uri: &str,
    statement_timeout_ms: u64,
    application_name: &str,
    read_only: bool,
) -> Result<String, String> {
    let mut options = Vec::new();
    if statement_timeout_ms > 0 {
        options.push(format!("-c statement_timeout={statement_timeout_ms}"));
    }
    if read_only {
        options.push("-c default_transaction_read_only=on".to_string());
    }
    let mut params = Vec::new();
    if !options.is_empty() {
        if has_param(uri, "options") {
            return Err(
                "the connection URL sets options already: set the statement timeout and \
                 read-only mode there, or here, not both"
                    .to_string(),
            );
        }
        params.push(("options", options.join(" ")));
    }
    if !application_name.is_empty() && !has_param(uri, "application_name") {
        if !is_application_name(application_name) {
            return Err(
                "an application name is ASCII letters, digits, `_`, `.`, and `-`, at most 63"
                    .to_string(),
            );
        }
        params.push(("application_name", application_name.to_string()));
    }
    if params.is_empty() {
        return Ok(uri.to_string());
    }
    let separator = if uri.contains('?') { '&' } else { '?' };
    let query: Vec<String> = params
        .iter()
        .map(|(name, value)| format!("{name}={}", percent_encode(value)))
        .collect();
    Ok(format!("{uri}{separator}{}", query.join("&")))
}

/// Whether the query of `uri` names `name`.
fn has_param(uri: &str, name: &str) -> bool {
    uri.split_once('?').is_some_and(|(_, query)| {
        query
            .split('&')
            .any(|pair| pair.split('=').next() == Some(name))
    })
}

/// Whether `name` is an application name Postgres keeps as it is: ASCII letters,
/// digits, `_`, `.`, and `-`, from 1 to 63 bytes.
fn is_application_name(name: &str) -> bool {
    (1..=63).contains(&name.len())
        && name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'.' | b'-'))
}

/// `value` with every byte but the unreserved ones percent-encoded.
fn percent_encode(value: &str) -> String {
    use std::fmt::Write as _;
    let mut encoded = String::new();
    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            encoded.push(char::from(byte));
        } else {
            let _ = write!(encoded, "%{byte:02X}");
        }
    }
    encoded
}

/// Build a pool using `tls`, without connecting yet.
///
/// # Errors
///
/// Fails when the pool's settings are invalid.
pub fn pool_with_tls(config: &PoolConfig, tls: rustls::ClientConfig) -> Result<Pool, Error> {
    let mut setup = ManagerConfig::default();
    setup.custom_setup = Box::new(move |uri| {
        let uri = uri.to_string();
        let tls = tls.clone();
        Box::pin(establish(uri, tls))
    });
    let manager = AsyncDieselConnectionManager::new_with_config(config.connection_uri()?, setup);
    // With no limit, a caller waits for ever behind a pool that is all in use.
    Ok(Pool::builder(manager)
        .max_size(config.max_connections)
        .wait_timeout(Some(config.wait_timeout))
        .create_timeout(Some(config.wait_timeout))
        .runtime(Runtime::Tokio1)
        // Retire a connection whose cached statements a migration has made stale.
        .pre_recycle(Hook::sync_fn(|_connection, metrics| {
            if opened_before_last_stale_plan(metrics.created) {
                Err(HookError::message("opened before a stale plan"))
            } else {
                Ok(())
            }
        }))
        .build()?)
}

/// When this process first needed a clock for stale plans.
static EPOCH: OnceLock<Instant> = OnceLock::new();

/// Nanoseconds after [`EPOCH`] that a stale plan was last seen, plus one, or `0` for
/// never.
static LAST_STALE_PLAN: AtomicU64 = AtomicU64::new(0);

fn epoch() -> Instant {
    *EPOCH.get_or_init(Instant::now)
}

/// Whether `error` is Postgres refusing a statement this connection prepared before a
/// migration changed what it returns: "cached plan must not change result type",
/// under SQLSTATE `0A000`, which Diesel does not pass on. Each pooled connection that
/// cached the statement fails so once, and a fresh connection does not.
#[must_use]
pub fn is_stale_plan(error: &QueryError) -> bool {
    matches!(
        error,
        QueryError::DatabaseError(DatabaseErrorKind::Unknown, info)
            if info.message().contains("cached plan must not change result type")
    )
}

/// Record `error` if it is a stale plan, so that every connection opened before now is
/// retired when next taken from the pool, from every pool [`connect`] or
/// [`pool_with_tls`] built in this process, and the next attempt runs on a fresh one.
/// Returns whether it was. `axa::Error` calls this for every Diesel error it answers,
/// so a service that turns Diesel errors into it needs nothing more.
pub fn note_stale_plan(error: &QueryError) -> bool {
    if !is_stale_plan(error) {
        return false;
    }
    let since = u64::try_from(epoch().elapsed().as_nanos()).unwrap_or(u64::MAX - 1);
    LAST_STALE_PLAN.fetch_max(since.saturating_add(1), Ordering::SeqCst);
    true
}

/// Whether a connection opened at `created` was opened at or before the last stale
/// plan.
fn opened_before_last_stale_plan(created: Instant) -> bool {
    opened_before(
        AtomicU64::load(&LAST_STALE_PLAN, Ordering::SeqCst),
        created.saturating_duration_since(epoch()),
    )
}

/// Whether a connection opened at `opened` since [`EPOCH`] was opened at or before
/// `last`, as [`LAST_STALE_PLAN`] holds it. One opened before the epoch counts as
/// opened at it.
fn opened_before(last: u64, opened: Duration) -> bool {
    if last == 0 {
        return false;
    }
    opened <= Duration::from_nanos(last - 1)
}

/// Open a pool and prove it works with one connection.
///
/// # Errors
///
/// Fails when the database cannot be reached.
pub async fn connect(config: &PoolConfig) -> Result<Pool, Error> {
    let tls =
        web_tls().map_err(|error| Error::Query(QueryError::QueryBuilderError(Box::new(error))))?;
    let pool = pool_with_tls(config, tls)?;
    ping(&pool).await?;
    Ok(pool)
}

/// Check that the database answers.
///
/// # Errors
///
/// Fails when it does not.
pub async fn ping(pool: &Pool) -> Result<(), Error> {
    let mut connection = pool.get().await?;
    diesel::sql_query("SELECT 1")
        .execute(&mut connection)
        .await?;
    Ok(())
}

/// Whether an error is a violated unique constraint, which a service usually
/// reports as `409` rather than `500`.
#[must_use]
pub fn is_unique_violation(error: &QueryError) -> bool {
    matches!(
        error,
        QueryError::DatabaseError(DatabaseErrorKind::UniqueViolation, _)
    )
}

/// Quote a table or type name for use in SQL.
///
/// Identifiers cannot be bound as parameters, so this is the one place names
/// reach SQL as text. Only lowercase ASCII letters, digits, and underscores
/// are accepted, starting with a letter or underscore.
///
/// ```
/// assert_eq!(axa_postgres_diesel::quote_identifier("users").as_deref(), Some("\"users\""));
/// assert_eq!(axa_postgres_diesel::quote_identifier("users; DROP TABLE x"), None);
/// ```
#[must_use]
pub fn quote_identifier(name: &str) -> Option<String> {
    let mut chars = name.chars();
    let first = chars.next()?;
    let valid = (first.is_ascii_lowercase() || first == '_')
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    valid.then(|| format!("\"{name}\""))
}

/// Quote every name, failing on the first one [`quote_identifier`] refuses.
fn quote_all<S: AsRef<str>>(names: &[S]) -> Result<Vec<String>, Error> {
    names
        .iter()
        .map(|name| {
            quote_identifier(name.as_ref())
                .ok_or_else(|| Error::InvalidIdentifier(name.as_ref().to_string()))
        })
        .collect()
}

/// Run `work` on a migration harness. The harness blocks, so it gets a blocking
/// thread rather than stalling the runtime.
async fn with_harness<T, F>(pool: &Pool, work: F) -> Result<T, Error>
where
    T: Send + 'static,
    F: FnOnce(&mut AsyncMigrationHarness<Connection>) -> Result<T, String> + Send + 'static,
{
    let connection = pool.get().await?;
    tokio::task::spawn_blocking(move || work(&mut AsyncMigrationHarness::new(connection)))
        .await
        .map_err(|error| Error::Migration(error.to_string()))?
        .map_err(Error::Migration)
}

/// Apply pending migrations, returning how many ran.
///
/// # Errors
///
/// Fails when a migration fails.
pub async fn migrate<M>(pool: &Pool, migrations: M) -> Result<usize, Error>
where
    M: MigrationSource<Pg> + Send + 'static,
{
    with_harness(pool, move |harness| {
        harness
            .run_pending_migrations(migrations)
            .map(|applied| applied.len())
            .map_err(|error| error.to_string())
    })
    .await
}

/// Revert the newest `steps` migrations, returning how many were reverted.
///
/// # Errors
///
/// Fails when a down migration fails.
pub async fn revert<M>(pool: &Pool, migrations: M, steps: usize) -> Result<usize, Error>
where
    M: MigrationSource<Pg> + Clone + Send + 'static,
{
    with_harness(pool, move |harness| {
        let mut reverted = 0;
        while reverted < steps {
            let applied = harness
                .applied_migrations()
                .map_err(|error| error.to_string())?;
            if applied.is_empty() {
                break;
            }
            harness
                .revert_last_migration(migrations.clone())
                .map_err(|error| error.to_string())?;
            reverted += 1;
        }
        Ok(reverted)
    })
    .await
}

/// The names of migrations that have not run.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending<M>(pool: &Pool, migrations: M) -> Result<Vec<String>, Error>
where
    M: MigrationSource<Pg> + Send + 'static,
{
    with_harness(pool, move |harness| {
        let pending = harness
            .pending_migrations(migrations)
            .map_err(|error| error.to_string())?;
        Ok(pending
            .iter()
            .map(|migration| migration.name().to_string())
            .collect())
    })
    .await
}

/// Empty `tables`, restarting their sequences. Each name goes through
/// [`quote_identifier`].
///
/// # Errors
///
/// Fails on an invalid name or a database error.
pub async fn truncate<S: AsRef<str>>(pool: &Pool, tables: &[S]) -> Result<(), Error> {
    if tables.is_empty() {
        return Ok(());
    }
    let tables = quote_all(tables)?.join(", ");
    let mut connection = pool.get().await?;
    diesel::sql_query(format!("TRUNCATE {tables} RESTART IDENTITY CASCADE"))
        .execute(&mut connection)
        .await?;
    Ok(())
}

/// Whether `name` is a custom setting a service may set for row-level security: two or
/// more parts of lower-case ASCII letters, digits, and underscores, joined by dots, such
/// as `app.tenant`. A name with no dot is Postgres's own, such as `role` or
/// `search_path`, which this never sets.
///
/// ```
/// assert!(axa_postgres_diesel::is_custom_setting("app.tenant"));
/// assert!(!axa_postgres_diesel::is_custom_setting("search_path"));
/// ```
#[must_use]
pub fn is_custom_setting(name: &str) -> bool {
    let parts: Vec<&str> = name.split('.').collect();
    name.len() <= 63
        && parts.len() >= 2
        && parts.iter().all(|part| {
            part.chars()
                .next()
                .is_some_and(|first| first.is_ascii_lowercase() || first == '_')
                && part
                    .chars()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
        })
}

/// Set each `(name, value)` for the rest of the open transaction only, such as
/// `("app.tenant", tenant.as_str())` for a row-level security policy that reads
/// `current_setting('app.tenant', true)`. Call it first inside the service's own
/// transaction, so every query after it on `connection` sees the setting:
///
/// ```no_run
/// # use axa_postgres_diesel::diesel_async::{AsyncConnection, AsyncPgConnection};
/// # async fn example(connection: &mut AsyncPgConnection) -> Result<(), diesel::result::Error> {
/// connection
///     .transaction(async |connection| {
///         axa_postgres_diesel::set_local(connection, &[("app.tenant", "acme")]).await?;
///         // The tenant's queries, on `connection`.
///         Ok::<_, diesel::result::Error>(())
///     })
///     .await
/// # }
/// ```
///
/// Each pair is set with `set_config($1, $2, true)`: bound, never formatted into the
/// SQL, and gone when the transaction commits or rolls back, so a pooled connection
/// never carries one request's tenant into the next.
///
/// A policy sees nothing unless the role the service connects as is subject to it: not
/// a superuser, without `BYPASSRLS`, and, if it owns the table, with
/// `FORCE ROW LEVEL SECURITY` on it. [`row_security`] checks.
///
/// # Errors
///
/// [`QueryError::NotInTransaction`] with no transaction open, as the setting would then
/// last for one statement only. [`QueryError::QueryBuilderError`] for a name
/// [`is_custom_setting`] refuses. Both come before anything is sent. Then any error from
/// setting a value.
pub async fn set_local(
    connection: &mut AsyncPgConnection,
    settings: &[(&str, &str)],
) -> Result<(), QueryError> {
    let depth =
        <AsyncPgConnection as AsyncConnection>::TransactionManager::transaction_manager_status_mut(
            connection,
        )
        .transaction_depth()?;
    if depth.is_none() {
        return Err(QueryError::NotInTransaction);
    }
    if let Some((name, _)) = settings.iter().find(|(name, _)| !is_custom_setting(name)) {
        return Err(QueryError::QueryBuilderError(
            format!("not a custom setting: {name}").into(),
        ));
    }
    for (name, value) in settings {
        diesel::sql_query("SELECT set_config($1, $2, true)")
            .bind::<Text, _>(*name)
            .bind::<Text, _>(*value)
            .execute(connection)
            .await?;
    }
    Ok(())
}

/// Whether row-level security can keep rows apart for the role a pool connects as.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RowSecurity {
    /// The role the pool connects as.
    pub role: String,
    /// Whether that role skips every policy: a superuser, or a role with `BYPASSRLS`.
    pub bypasses: bool,
    /// The tables asked about that do not exist, have no row-level security, or lack
    /// `FORCE ROW LEVEL SECURITY`, so that their owner skips the policies.
    pub unprotected: Vec<String>,
}

impl RowSecurity {
    /// Whether the policies on every table asked about apply to the role.
    #[must_use]
    pub fn holds(&self) -> bool {
        !self.bypasses && self.unprotected.is_empty()
    }
}

/// The current role, and whether it skips every policy.
#[derive(QueryableByName)]
struct Role {
    #[diesel(sql_type = Text)]
    role: String,
    #[diesel(sql_type = Bool)]
    bypasses: bool,
}

/// Whether a table has row-level security enabled and forced.
#[derive(QueryableByName)]
struct Forced {
    #[diesel(sql_type = Bool)]
    forced: bool,
}

/// Ask Postgres whether row-level security can apply to `pool`'s role, and whether
/// each of `tables`, such as `todos` or `app.todos`, has it enabled and forced. Call it
/// at boot, after migrating, and refuse to serve when it does not hold.
///
/// # Errors
///
/// Any error from getting a connection or from the queries.
pub async fn row_security<S: AsRef<str>>(pool: &Pool, tables: &[S]) -> Result<RowSecurity, Error> {
    let mut connection = pool.get().await?;
    let role: Role = diesel::sql_query(
        "SELECT current_user::text AS role, rolsuper OR rolbypassrls AS bypasses
         FROM pg_roles WHERE rolname = current_user",
    )
    .get_result(&mut connection)
    .await?;
    let mut unprotected = Vec::new();
    for table in tables {
        let table = table.as_ref();
        let forced: Vec<Forced> = diesel::sql_query(
            "SELECT relrowsecurity AND relforcerowsecurity AS forced FROM pg_class
             WHERE oid = to_regclass($1)",
        )
        .bind::<Text, _>(table)
        .load(&mut connection)
        .await?;
        if !<[Forced]>::first(&forced).is_some_and(|row| row.forced) {
            unprotected.push(table.to_string());
        }
    }
    Ok(RowSecurity {
        role: role.role,
        bypasses: role.bypasses,
        unprotected,
    })
}

/// One name from a catalog query.
#[derive(QueryableByName)]
struct Name {
    #[diesel(sql_type = Text)]
    name: String,
}

/// Drop every table and enum type in `public`, then migrate from nothing.
/// This gives each test an empty schema, whatever tables it touched.
///
/// **This destroys all data.** It exists for tests, and a service must never
/// reach it outside the `test` environment.
///
/// It drops tables and types by name rather than dropping the schema, which
/// would also remove extensions such as `citext`.
///
/// # Errors
///
/// Fails on a database error, a failed migration, or a name
/// [`quote_identifier`] refuses.
pub async fn dangerously_recreate<M>(pool: &Pool, migrations: M) -> Result<(), Error>
where
    M: MigrationSource<Pg> + Send + 'static,
{
    let mut connection = pool.get().await?;
    let tables: Vec<Name> = diesel::sql_query(
        "SELECT tablename::text AS name FROM pg_tables WHERE schemaname = 'public'",
    )
    .load(&mut connection)
    .await?;
    // Types owned by an extension (`deptype = 'e'`) belong to that extension.
    let types: Vec<Name> = diesel::sql_query(
        "SELECT t.typname::text AS name FROM pg_type t
         JOIN pg_namespace n ON n.oid = t.typnamespace
         WHERE t.typtype = 'e' AND n.nspname = 'public'
           AND NOT EXISTS (
               SELECT 1 FROM pg_depend d WHERE d.objid = t.oid AND d.deptype = 'e'
           )",
    )
    .load(&mut connection)
    .await?;
    let table_names: Vec<&str> = tables.iter().map(|table| table.name.as_str()).collect();
    if !table_names.is_empty() {
        let names = quote_all(&table_names)?.join(", ");
        diesel::sql_query(format!("DROP TABLE {names} CASCADE"))
            .execute(&mut connection)
            .await?;
    }
    let type_names: Vec<&str> = types.iter().map(|name| name.name.as_str()).collect();
    for name in quote_all(&type_names)? {
        diesel::sql_query(format!("DROP TYPE {name} CASCADE"))
            .execute(&mut connection)
            .await?;
    }
    drop(connection);
    migrate(pool, migrations).await?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn session_settings_become_connection_parameters() {
        let base = "postgres://app@db/app";
        assert_eq!(session_uri(base, 0, "", false).unwrap(), base);
        assert_eq!(
            session_uri(base, 5000, "orders", true).unwrap(),
            "postgres://app@db/app?options=-c%20statement_timeout%3D5000%20-c%20\
             default_transaction_read_only%3Don&application_name=orders"
        );
        assert_eq!(
            session_uri("postgres://db/app?sslmode=require", 0, "orders", false).unwrap(),
            "postgres://db/app?sslmode=require&application_name=orders"
        );
    }

    #[test]
    fn a_connection_is_retired_only_if_opened_by_the_last_stale_plan() {
        let second = Duration::from_secs(1);
        // Never a stale plan: nothing is retired.
        assert!(!opened_before(0, second));
        // A stale plan at 5s: a connection opened at 0s, 1s, or 5s goes, one at 6s
        // stays.
        let at_five = 5_000_000_000 + 1;
        assert!(opened_before(at_five, Duration::ZERO));
        assert!(opened_before(at_five, second));
        assert!(opened_before(at_five, 5 * second));
        assert!(!opened_before(at_five, 6 * second));
    }

    #[test]
    fn a_url_that_sets_them_already_is_kept_or_refused() {
        // Its own application name wins.
        let named = "postgres://db/app?application_name=mine";
        assert_eq!(session_uri(named, 0, "orders", false).unwrap(), named);
        // Its own options and a setting here would replace one another, so neither does.
        let with_options = "postgres://db/app?options=-c%20work_mem%3D64MB";
        assert!(session_uri(with_options, 5000, "", false).is_err());
        assert!(session_uri(with_options, 0, "", true).is_err());
        assert_eq!(
            session_uri(with_options, 0, "", false).unwrap(),
            with_options
        );
        for name in ["has space", "a&b=c", "é", &"a".repeat(64)] {
            assert!(
                session_uri("postgres://db/app", 0, name, false).is_err(),
                "{name}"
            );
        }
    }

    #[test]
    fn debug_text_leaves_out_the_connection_string() {
        let text = format!("{:?}", PoolConfig::new("postgres://me:hunter2@db/app"));
        assert!(!text.contains("hunter2"), "{text}");
        assert!(text.contains("max_connections"), "{text}");
    }

    #[test]
    fn identifiers_are_quoted() {
        assert_eq!(quote_identifier("users").as_deref(), Some("\"users\""));
    }

    #[test]
    fn unsafe_identifiers_are_refused() {
        for name in [
            "", "1users", "Users", "a b", "a\"b", "a;b", "a.b", "users--",
        ] {
            assert_eq!(quote_identifier(name), None, "{name:?}");
        }
    }

    #[test]
    fn quote_all_fails_on_any_bad_name() {
        assert!(quote_all(&["good"]).is_ok());
        assert!(matches!(
            quote_all(&["good", "bad name"]),
            Err(Error::InvalidIdentifier(name)) if name == "bad name"
        ));
    }

    #[test]
    fn errors_that_are_not_from_the_database_are_not_unique_violations() {
        assert!(!is_unique_violation(&QueryError::NotFound));
    }

    #[test]
    fn tls_settings_build() {
        assert!(web_tls().is_ok());
    }
}

//! A Postgres job queue, worker pool, and recurring schedules.
//!
//! Jobs live in one `axa_queue` table. Each job loop claims the ready job with the
//! highest priority, oldest first, in a single statement using `FOR UPDATE SKIP
//! LOCKED`, so two loops can never claim the same row and no broker is needed.
//!
//! A job queued is announced with `NOTIFY axa_queue` when its transaction commits,
//! and [`Queue::run`] listens on one connection of its pool, so an idle loop starts
//! a job at once rather than at its next poll. Polling every
//! [`QueueOptions::poll_interval`] stays, for a job whose time comes, and for any
//! notice lost while the listener reconnects.
//!
//! ```no_run
//! use std::time::Duration;
//! use axa_postgres_job_queue::{NewJob, Queue, QueueOptions, Schedule};
//! use tokio::sync::watch;
//!
//! # async fn example(uri: &str) -> axa_postgres_job_queue::Result<()> {
//! let mut queue = Queue::connect(uri, QueueOptions::default()).await?;
//! queue.handle("Report", |args| async move {
//!     let id = args["id"].as_i64().ok_or("no id")?;
//!     println!("report {id}");
//!     Ok::<(), &str>(())
//! });
//! queue.limit("Report", 1); // at most one at a time in this process
//! queue.schedule(Schedule::every(
//!     "nightly-report",
//!     Duration::from_hours(24),
//!     NewJob::new("Report", serde_json::json!({ "id": 0 })),
//! ));
//!
//! let id = queue
//!     .enqueue_job(&NewJob::new("Report", serde_json::json!({ "id": 7 })).run_in(Duration::from_mins(5)))
//!     .await?;
//! let queue = std::sync::Arc::new(queue);
//! let (stop, stopped) = watch::channel(false);
//! let jobs = tokio::spawn(queue.clone().run(stopped));
//! // ... serve until told to stop, then:
//! let _ = stop.send(true);
//! let _ = jobs.await;
//! # let _ = id;
//! # Ok(())
//! # }
//! ```
//!
//! A job moves from `queued` to `running` to `completed` or `failed`, with the
//! failure text kept on the row. A queued job can be `cancelled`.
//!
//! # A person's acts
//!
//! A job row is state: it changes as the job runs, and retention deletes it. What a
//! person does to a job is a record. [`cancel()`] stops a queued job, and [`retry()`]
//! queues a failed one again or releases one from review. Each takes the caller's
//! transaction and a `by` and `reason`, and appends the act to `axa_job_acts` in the
//! same statement as the change, so the act, the change, and the service's own audit
//! row commit together or not at all. There is no form that takes a pool. An act that
//! does not apply, such as cancelling a running job, changes nothing and writes no
//! act.
//!
//! ```no_run
//! # async fn example(queue: &axa_postgres_job_queue::Queue, id: uuid::Uuid) -> axa_postgres_job_queue::Result<()> {
//! let mut transaction = queue.pool().begin().await?;
//! let cancelled = axa_postgres_job_queue::cancel(&mut transaction, id, "ops:alice", "customer_asked").await?;
//! // ... write the service's own audit row on the same transaction ...
//! transaction.commit().await?;
//! # let _ = cancelled;
//! # Ok(())
//! # }
//! ```
//!
//! `by` and `reason` are codes, not content: at most [`MAX_REASON_CHARS`] characters
//! with no line breaks, and the table refuses anything else. `axa_job_acts` is only
//! ever inserted into, and its triggers refuse `UPDATE`, `DELETE`, and `TRUNCATE`,
//! whoever sends them. An act names its job by id, with no foreign key, so it outlives
//! the job's row. [`Queue::acts`] reads a job's acts.
//!
//! # Attempts
//!
//! A job gets [`QueueOptions::max_attempts`] tries, unless it was queued with its
//! own limit. The default is one, because a retry repeats the job's work, and only
//! its author knows that is safe. Each retry waits about twice as long as the last,
//! starting from [`QueueOptions::retry_backoff`], spread at random over the upper
//! half of that wait so jobs that failed together do not all come back at once. A
//! handler that knows better, such as from a receiver's `Retry-After`, returns
//! [`RetryAfter`] as its error. A job that panics counts as failed, and its loop
//! carries on.
//!
//! # Lost jobs
//!
//! A running job reports in every [`QueueOptions::heartbeat_interval`], so a job
//! may run for as long as it needs. One not heard from for
//! [`QueueOptions::stale_minutes`] is assumed lost with its worker. If it has
//! attempts left it is queued again, and otherwise it is marked failed, so a crash
//! can never loop for ever. Each claim is identified by its attempt, so a run that
//! was given up on cannot then overwrite the result of its replacement.
//!
//! # How many at once
//!
//! A process runs [`QueueOptions::workers`] job loops, so at most that many jobs at
//! once. [`Queue::limit`] caps one job type below that, in this process. A limit is
//! per process and not across replicas: three processes with a limit of one may run
//! three. Work that must never overlap anywhere needs a lock of its own.
//!
//! # When a job runs
//!
//! [`NewJob::run_in`] and [`NewJob::run_at`] delay a job, and [`NewJob::priority`]
//! puts it ahead of others that are ready. Delay is measured on the database's
//! clock. A delayed job is claimed only once it is due, and then about as soon as a
//! loop next polls.
//!
//! # Schedules
//!
//! A [`Schedule`] queues a job every interval. Each due time becomes one ordinary
//! job, so its retries, status, limit, and recovery are the queue's. The schedule's
//! row in `axa_schedule` is locked while its job is queued, in the same
//! transaction, so across any number of replicas each due time is queued once.
//!
//! - **No drift.** The next time is counted from when the last was due, not from
//!   when it ran.
//! - **Missed times run once.** After every process was down, one job is queued,
//!   and the schedule keeps its place: the next time is still a whole number of
//!   intervals from the first.
//! - **No stacking.** When the schedule's last job is still queued or running at a
//!   due time, that time is skipped.
//! - **The first time** is [`Schedule::first_at`], or as soon as the row is made.
//!   It applies only when the row is made, so a schedule every 24 hours first due
//!   at 02:00 runs at 02:00 each day, on the database's clock in UTC.
//!
//! [`Schedule::cron`] queues a job at the times a cron pattern names, such as
//! `"0 2 * * *"` for 02:00 each day, in UTC on the database's clock. Its due times
//! are the pattern's, so the same three rules hold: each due time is queued once, times
//! missed while every process was down queue one job and the next time is the
//! pattern's next after now, and a due time is skipped while the last job is queued or
//! running. Its first time is the pattern's next after the row is made, and a changed
//! pattern takes its next time from the new pattern.
//!
//! [`Queue::run`] ticks the schedules on every poll, and a service with no job
//! loops can call [`Queue::tick_schedules`] itself. A schedule's job type must be
//! handled by some worker, or its jobs wait. A schedule removed from code leaves a
//! row that nothing reads.
//!
//! # One job at a time per key
//!
//! [`NewJob::unique`] names a key, such as `"sync:42"`, and while a job of the same
//! name, tenant, and key is queued or running, queuing another adds nothing and
//! answers the id of the one there. The first job's arguments, priority, and time
//! stand. Once it completes, fails, is cancelled, or goes to review, the key is free
//! again. The table holds to this with a unique index, so it holds across
//! replicas and for a job queued in a transaction that has not yet committed: a
//! second enqueue of the key waits for that transaction, and then either finds its
//! job or queues its own. [`retry()`] leaves a failed job alone while another of its
//! key is queued or running.
//!
//! # Queuing inside a transaction
//!
//! [`enqueue_on`] takes the caller's transaction, so a job and the record it is
//! about commit together or not at all. [`Queue::enqueue`] uses its own
//! connection, so a job queued that way can outlive a rollback.
//!
//! # Personal data
//!
//! The `args` column is plain JSONB, and finished rows are deleted after
//! [`QueueOptions::retention_days`], so a job table does not become a second copy
//! of the data. Prefer an id to a snapshot, and never put a secret in arguments.
//! [`JobInfo`] leaves the arguments out. Its error text is whatever the job's
//! error said, so it is for operators, and is not to be sent to a client. An act
//! keeps no arguments either, and nothing logs its `by` or `reason`.

use std::{
    collections::{HashMap, HashSet},
    fmt,
    future::Future,
    pin::Pin,
    sync::Arc,
    time::Duration,
};

use sqlx::{
    PgConnection, PgExecutor, PgPool, Postgres, Row, Transaction,
    postgres::{PgPoolOptions, PgRow},
};
use tokio::sync::{Notify, OwnedSemaphorePermit, Semaphore, watch};
use uuid::Uuid;

/// An instant, in UTC: every time the queue keeps or takes. Re-exported from `jiff`, so
/// a service needs no dependency of its own to name one.
pub use jiff::Timestamp;

/// What this crate's functions return.
pub type Result<T, E = Error> = std::result::Result<T, E>;

/// What went wrong.
#[derive(Debug)]
#[non_exhaustive]
pub enum Error {
    /// The database refused or could not be reached.
    Database(sqlx::Error),
    /// A job's arguments could not be encoded.
    Encode(serde_json::Error),
    /// A job failed, or the queue met something it cannot read.
    Job(String),
    /// Who or why, given for a person's act, or a job's unique key, is empty,
    /// longer than [`MAX_REASON_CHARS`], or has a line break.
    NotACode {
        /// Which it was: `by`, `reason`, or `unique key`.
        what: &'static str,
    },
    /// A job's tenant is not a tenant id: see [`is_tenant_id`].
    NotATenant,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Database(error) => error.fmt(f),
            Self::Encode(error) => error.fmt(f),
            Self::Job(text) => write!(f, "worker error: {text}"),
            Self::NotACode { what } => write!(
                f,
                "`{what}` must be 1 to {MAX_REASON_CHARS} characters with no line breaks"
            ),
            Self::NotATenant => f.write_str(
                "a job's tenant must be 1 to 63 lower-case letters, digits, and hyphens, \
                 not starting or ending with a hyphen",
            ),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Database(error) => Some(error),
            Self::Encode(error) => Some(error),
            Self::Job(_) | Self::NotACode { .. } | Self::NotATenant => None,
        }
    }
}

impl From<sqlx::Error> for Error {
    fn from(error: sqlx::Error) -> Self {
        Self::Database(error)
    }
}

impl From<serde_json::Error> for Error {
    fn from(error: serde_json::Error) -> Self {
        Self::Encode(error)
    }
}

type JobFuture = Pin<Box<dyn Future<Output = Result<(), Failure>> + Send>>;
type Handler = Arc<dyn Fn(Option<String>, serde_json::Value) -> JobFuture + Send + Sync>;

const SETUP: &str = "CREATE TABLE IF NOT EXISTS axa_queue (
    id UUID PRIMARY KEY,
    name TEXT NOT NULL,
    args JSONB NOT NULL,
    status TEXT NOT NULL DEFAULT 'queued',
    error TEXT,
    run_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
)";
const SETUP_INDEX: &str =
    "CREATE INDEX IF NOT EXISTS axa_queue_ready ON axa_queue (run_at) WHERE status = 'queued'";
/// Tables created by Axa 0.1.0 have no `attempts` column.
const SETUP_ATTEMPTS: &str =
    "ALTER TABLE axa_queue ADD COLUMN IF NOT EXISTS attempts INTEGER NOT NULL DEFAULT 0";
/// A job's own limit on tries, when it has one.
const SETUP_MAX_ATTEMPTS: &str =
    "ALTER TABLE axa_queue ADD COLUMN IF NOT EXISTS max_attempts INTEGER";
/// Higher runs first. Tables created before axa-postgres-job-queue have none.
const SETUP_PRIORITY: &str =
    "ALTER TABLE axa_queue ADD COLUMN IF NOT EXISTS priority SMALLINT NOT NULL DEFAULT 0";
/// A job's own time limit, when it has one.
const SETUP_TIMEOUT: &str = "ALTER TABLE axa_queue ADD COLUMN IF NOT EXISTS timeout_ms BIGINT";
/// The tenant a job runs for, when it has one, as an auth crate's `Tenant` names it.
const SETUP_TENANT: &str = "ALTER TABLE axa_queue ADD COLUMN IF NOT EXISTS tenant TEXT
    CONSTRAINT axa_queue_tenant_id CHECK (tenant ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$')";
/// The key a job is unique by while it is queued or running, when it has one.
const SETUP_UNIQUE_KEY: &str = "ALTER TABLE axa_queue ADD COLUMN IF NOT EXISTS unique_key TEXT
    CONSTRAINT axa_queue_unique_key_code
    CHECK (length(unique_key) BETWEEN 1 AND 200 AND unique_key !~ '[[:cntrl:]]')";
/// At most one job queued or running per name, tenant, and key.
const SETUP_UNIQUE_INDEX: &str = "CREATE UNIQUE INDEX IF NOT EXISTS axa_queue_unique
    ON axa_queue (name, (COALESCE(tenant, '')), unique_key)
    WHERE unique_key IS NOT NULL AND status IN ('queued', 'running')";
const SETUP_CLAIM_INDEX: &str = "CREATE INDEX IF NOT EXISTS axa_queue_claim
    ON axa_queue (priority DESC, run_at) WHERE status = 'queued'";
const SETUP_SCHEDULE: &str = "CREATE TABLE IF NOT EXISTS axa_schedule (
    name TEXT PRIMARY KEY,
    due_at TIMESTAMPTZ NOT NULL,
    last_job UUID,
    interval_ms BIGINT,
    seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    archived_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
)";
/// A person's acts on jobs. This table is a record (P-7): it is only ever inserted
/// into, and its triggers refuse every change. A job row is state, and retention
/// deletes it, so an act names its job by id with no foreign key, and keeps the job's
/// name and attempts as they were when the act was done.
/// A schedule's cron pattern, when it has one instead of an interval.
