/// The longest `by` or `reason` kept on an act, in characters.
pub const MAX_REASON_CHARS: usize = 200;

/// The shortest gap between heartbeats, so a zero setting cannot spin.
const MIN_HEARTBEAT: Duration = Duration::from_millis(20);

/// The longest wait between attempts.
const MAX_BACKOFF: Duration = Duration::from_hours(1);

/// The longest error text kept on a row.
const MAX_ERROR: usize = 1024;

/// How long to wait before the attempt after `attempts`, doubling each time.
#[must_use]
pub fn backoff(base: Duration, attempts: i32) -> Duration {
    let doublings = u32::try_from(attempts.saturating_sub(1))
        .unwrap_or(0)
        .min(16);
    base.saturating_mul(1 << doublings).min(MAX_BACKOFF)
}

/// The shortest delay a job may choose with [`RetryAfter`].
pub const MIN_RETRY_AFTER: Duration = Duration::from_secs(1);

/// A job's error that also says when to try it again, such as a receiver's
/// `Retry-After`. Return it as a handler's error: the next attempt waits `delay`,
/// held between [`MIN_RETRY_AFTER`] and an hour, rather than the backoff. It still
/// counts as an attempt, so a job out of attempts fails as any other.
#[derive(Debug, Clone)]
pub struct RetryAfter {
    delay: Duration,
    reason: String,
}

impl RetryAfter {
    /// Try again after `delay`, keeping `reason` as the job's error.
    #[must_use]
    pub fn new(delay: Duration, reason: impl Into<String>) -> Self {
        Self {
            delay,
            reason: reason.into(),
        }
    }

    /// The delay the job asked for, before it is held to its limits.
    #[must_use]
    pub const fn delay(&self) -> Duration {
        self.delay
    }
}

impl fmt::Display for RetryAfter {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.reason)
    }
}

impl std::error::Error for RetryAfter {}

/// How a run failed: the text kept on the row, and any delay the job chose.
struct Failure {
    text: String,
    retry_in: Option<Duration>,
}

impl Failure {
    fn from_error<E: fmt::Display + 'static>(error: E) -> Self {
        let any = &error as &dyn std::any::Any;
        // A handler's own error, or one boxed, as `axa`'s workers hand theirs on.
        let retry_in = any
            .downcast_ref::<RetryAfter>()
            .or_else(|| {
                any.downcast_ref::<Box<dyn std::error::Error + Send + Sync>>()
                    .and_then(|boxed| boxed.downcast_ref::<RetryAfter>())
            })
            .map(RetryAfter::delay);
        Self {
            text: error.to_string(),
            retry_in,
        }
    }
}

impl From<String> for Failure {
    fn from(text: String) -> Self {
        Self {
            text,
            retry_in: None,
        }
    }
}

impl fmt::Display for Failure {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

/// Spread `wait` over its upper half at random, so jobs that failed together do
/// not all try again at once.
#[must_use]
pub fn jittered(wait: Duration) -> Duration {
    let random = Uuid::new_v4().as_u128();
    #[allow(clippy::cast_precision_loss)]
    let fraction = (random % 1_000_000) as f64 / 1_000_000.0;
    wait.mul_f64(0.5 + fraction / 2.0)
}

/// How long to wait before the attempt after `attempts`: the delay a job chose,
/// held between [`MIN_RETRY_AFTER`] and an hour, or else the doubling backoff
/// from `base`, jittered.
#[must_use]
pub fn retry_wait(base: Duration, attempts: i32, chosen: Option<Duration>) -> Duration {
    match chosen {
        Some(delay) => delay.clamp(MIN_RETRY_AFTER, MAX_BACKOFF),
        None => jittered(backoff(base, attempts)),
    }
}

/// Cut `text` to at most [`MAX_ERROR`] bytes, on a character boundary.
fn cut(mut text: String) -> String {
    if text.len() > MAX_ERROR {
        let mut end = MAX_ERROR;
        while !text.is_char_boundary(end) {
            end -= 1;
        }
        text.truncate(end);
    }
    text
}

fn millis(duration: Duration) -> i64 {
    i64::try_from(duration.as_millis()).unwrap_or(i64::MAX)
}

fn from_millis(millis: i64) -> Duration {
    Duration::from_millis(u64::try_from(millis).unwrap_or(0))
}

/// When a new job may first run.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum When {
    Now,
    At(Timestamp),
    In(Duration),
}

/// A job to queue: its type, its arguments, and when and how it runs.
#[derive(Clone)]
pub struct NewJob {
    name: String,
    args: serde_json::Value,
    max_attempts: Option<i32>,
    priority: i16,
    when: When,
    timeout: Option<Duration>,
    tenant: Option<String>,
    unique_key: Option<String>,
}

impl fmt::Debug for NewJob {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("NewJob")
            .field("name", &self.name)
            .field("max_attempts", &self.max_attempts)
            .field("priority", &self.priority)
            .field("when", &self.when)
            .field("timeout", &self.timeout)
            .field("tenant", &self.tenant)
            .field("unique_key", &self.unique_key)
            .finish_non_exhaustive()
    }
}

impl NewJob {
    /// A job for the handler named `name`, ready now, with the queue's limit on
    /// tries and priority zero.
    pub fn new(name: impl Into<String>, args: serde_json::Value) -> Self {
        Self {
            name: name.into(),
            args,
            max_attempts: None,
            priority: 0,
            when: When::Now,
            timeout: None,
            tenant: None,
            unique_key: None,
        }
    }

    /// Queue this job only if no job of its name, tenant, and `key` is queued or
    /// running: otherwise queuing it adds nothing and answers the id of the one
    /// there, whose arguments, priority, and time stand. The key is a code, at most
    /// [`MAX_REASON_CHARS`] characters with no line breaks, such as `"sync:42"`, and
    /// is kept on the job's row, so it holds no secret or personal data. Enqueuing
    /// refuses any other key with [`Error::NotACode`].
    #[must_use]
    pub fn unique(mut self, key: impl Into<String>) -> Self {
        self.unique_key = Some(key.into());
        self
    }

    /// Run this job for `tenant`, the id an auth crate's `Tenant` gives, which its
    /// handler receives beside the arguments, so that it can open its own tenant
    /// transaction. Only a handler registered with [`Queue::handle_with_tenant`] runs
    /// it. Enqueuing refuses an id that is not a tenant id, with
    /// [`Error::NotATenant`].
    #[must_use]
    pub fn tenant(mut self, tenant: impl Into<String>) -> Self {
        self.tenant = Some(tenant.into());
        self
    }

    /// Stop a run of this job past `limit`, and count it as failed with the reason.
    /// A job has no time limit unless it is given one.
    #[must_use]
    pub const fn timeout(mut self, limit: Duration) -> Self {
        self.timeout = Some(limit);
        self
    }

    /// Tries this job gets, including the first, or the queue's when `None`.
    #[must_use]
    pub const fn max_attempts(mut self, max_attempts: Option<i32>) -> Self {
        self.max_attempts = max_attempts;
        self
    }

    /// Run ahead of ready jobs with a lower priority. Zero by default, and may be
    /// negative.
    #[must_use]
    pub const fn priority(mut self, priority: i16) -> Self {
        self.priority = priority;
        self
    }

    /// Run no sooner than `delay` from now, on the database's clock.
    #[must_use]
    pub const fn run_in(mut self, delay: Duration) -> Self {
        self.when = When::In(delay);
        self
    }

    /// Run no sooner than `at`.
    #[must_use]
    pub const fn run_at(mut self, at: Timestamp) -> Self {
        self.when = When::At(at);
        self
    }

    /// The handler this job is for.
    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }

    /// The tenant this job runs for, if any.
    #[must_use]
    pub fn tenant_id(&self) -> Option<&str> {
        self.tenant.as_deref()
    }

    /// The key this job is unique by, if any.
    #[must_use]
    pub fn unique_key(&self) -> Option<&str> {
        self.unique_key.as_deref()
    }
}

/// The longest tenant id, which a DNS label also allows.
pub const MAX_TENANT_ID_LEN: usize = 63;

/// Whether `id` is a tenant id: lower-case ASCII letters, digits, and hyphens, not
/// starting or ending with a hyphen, from 1 to 63 characters, as a DNS label is, and as
/// the auth crates' `Tenant` holds. The table's check holds to the same rule.
#[must_use]
pub fn is_tenant_id(id: &str) -> bool {
    (1..=MAX_TENANT_ID_LEN).contains(&id.len())
        && !id.starts_with('-')
        && !id.ends_with('-')
        && id
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
}

/// Add `job` on `executor`, usually the caller's transaction, and return its id.
/// The job then commits or rolls back with the transaction. A job with a
/// [`NewJob::unique`] key that is already queued or running adds nothing, and the id
/// is that job's.
///
/// # Errors
///
/// Fails on a database error, with [`Error::NotATenant`] for a tenant that is not a
/// tenant id, and with [`Error::NotACode`] for a key that is not a code, before
/// anything is written.
pub async fn enqueue_on<'e, E: PgExecutor<'e>>(executor: E, job: &NewJob) -> Result<Uuid> {
    if job
        .tenant
        .as_deref()
        .is_some_and(|tenant| !is_tenant_id(tenant))
    {
        return Err(Error::NotATenant);
    }
    if let Some(key) = job.unique_key.as_deref() {
        check_code(key, "unique key")?;
    }
    let id = Uuid::new_v4();
    let (at, delay) = match job.when {
        When::Now => (None, 0.0),
        When::At(at) => (Some(at), 0.0),
        When::In(delay) => (None, delay.as_secs_f64()),
    };
    let query = sqlx::query(if job.unique_key.is_some() {
        ENQUEUE_UNIQUE
    } else {
        ENQUEUE
    })
    .bind(id)
    .bind(&job.name)
    .bind(&job.args)
    .bind(job.max_attempts)
    .bind(job.priority)
    .bind(at.map(jiff_sqlx::Timestamp::from))
    .bind(delay)
    .bind(job.timeout.map(millis))
    .bind(job.tenant.as_deref());
    if let Some(key) = job.unique_key.as_deref() {
        Ok(query.bind(key).fetch_one(executor).await?.try_get("id")?)
    } else {
        query.execute(executor).await?;
        Ok(id)
    }
}

/// Add every job in `jobs` on `connection`, returning their ids in order. On a
/// transaction they commit or roll back together; [`Queue::enqueue_all`] opens one.
///
/// # Errors
///
/// Fails on a database error, after which a transaction must be rolled back.
pub async fn enqueue_all_on(connection: &mut PgConnection, jobs: &[NewJob]) -> Result<Vec<Uuid>> {
    let mut ids = Vec::with_capacity(jobs.len());
    for job in jobs {
        ids.push(enqueue_on(&mut *connection, job).await?);
    }
    Ok(ids)
}

/// Refuse who or why for a person's act unless it is a code.
fn check_code(text: &str, what: &'static str) -> Result<()> {
    if text.is_empty()
        || text.chars().count() > MAX_REASON_CHARS
        || text.chars().any(char::is_control)
    {
        Err(Error::NotACode { what })
    } else {
        Ok(())
    }
}

/// Cancel the job `id` if it is still queued, as an act of `by`, for `reason`, kept in
/// `axa_job_acts` in the caller's transaction, so that the caller's own audit row
/// commits with it. Answers whether it was cancelled. A job already claimed runs on:
/// cancelling cannot stop work in progress. A job in any other state, or no such job,
/// changes nothing and writes no act.
///
/// The job's row stays locked until the transaction ends, so keep it short.
///
/// # Errors
///
/// Fails on a database error, and with [`Error::NotACode`] when `by` or `reason` is
/// empty, longer than [`MAX_REASON_CHARS`], or has a line break, before anything is
/// written.
pub async fn cancel(
    transaction: &mut Transaction<'_, Postgres>,
    id: Uuid,
    by: &str,
    reason: &str,
) -> Result<bool> {
    act(transaction, CANCEL, id, by, reason).await
}

/// Queue the job `id` again, now, for one more try, if it failed or waits for review,
/// as an act of `by`, for `reason`, kept in `axa_job_acts` in the caller's
/// transaction. The act is [`ActKind::Retried`] for a failed job and
/// [`ActKind::Released`] for one in review. Answers whether it was queued again. A job
/// in any other state, or no such job, changes nothing and writes no act. Its last
/// error stays until it next runs.
///
/// # Errors
///
/// Fails on a database error, and with [`Error::NotACode`] when `by` or `reason` is
/// empty, longer than [`MAX_REASON_CHARS`], or has a line break, before anything is
/// written.
pub async fn retry(
    transaction: &mut Transaction<'_, Postgres>,
    id: Uuid,
    by: &str,
    reason: &str,
) -> Result<bool> {
    act(transaction, RETRY_FAILED, id, by, reason).await
}

/// Run one act's statement, which changes the job and keeps the act together.
async fn act(
    transaction: &mut Transaction<'_, Postgres>,
    statement: &'static str,
    id: Uuid,
    by: &str,
    reason: &str,
) -> Result<bool> {
    check_code(by, "by")?;
    check_code(reason, "reason")?;
    let kept = sqlx::query(statement)
        .bind(id)
        .bind(by)
        .bind(reason)
        .execute(&mut **transaction)
        .await?
        .rows_affected();
    Ok(kept == 1)
}

/// What a person did to a job.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum ActKind {
    /// Cancelled it while it was queued.
    Cancelled,
    /// Queued it again after it failed.
    Retried,
    /// Released it from review, to run again.
    Released,
}

impl ActKind {
    fn parse(text: &str) -> Result<Self> {
        match text {
            "cancelled" => Ok(Self::Cancelled),
            "retried" => Ok(Self::Retried),
            "released" => Ok(Self::Released),
            _ => Err(Error::Job("an act with an unknown kind".to_string())),
        }
    }
}

/// One act of a person on a job, as `axa_job_acts` keeps it. It outlives the job's
/// row, which retention deletes.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Act {
    /// The act's row. It rises with each act.
    pub id: i64,
    /// The job it was done to.
    pub job_id: Uuid,
    /// The handler that job is for.
    pub job_name: String,
    /// What was done.
    pub kind: ActKind,
    /// The job's runs so far when it was done.
    pub attempts: i32,
    /// Who did it, as the service named them.
    pub by: String,
    /// Why, as a short code.
    pub reason: String,
    /// When, on the database's clock.
    pub at: Timestamp,
}

/// Where a job is.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JobState {
    /// Waiting to be claimed, now or at its time.
    Queued,
    /// Claimed by a job loop.
    Running,
    /// Finished.
    Completed,
    /// Out of tries, or given up on.
    Failed,
    /// Cancelled before it ran.
    Cancelled,
    /// Its run lost its claim and was stopped, so it may have run in part or
    /// twice. It is never retried by itself: a person looks, and calls
    /// [`retry()`] to release it.
    NeedsReview,
}

impl JobState {
    fn parse(text: &str) -> Result<Self> {
        match text {
            "queued" => Ok(Self::Queued),
            "running" => Ok(Self::Running),
            "completed" => Ok(Self::Completed),
            "failed" => Ok(Self::Failed),
            "cancelled" => Ok(Self::Cancelled),
            "needs_review" => Ok(Self::NeedsReview),
            _ => Err(Error::Job("a job row with an unknown status".to_string())),
        }
    }
}

/// What the queue knows of one job. Its arguments are left out.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct JobInfo {
    /// The job's id.
    pub id: Uuid,
    /// The handler it is for.
    pub name: String,
    /// Where it is.
    pub state: JobState,
    /// Runs so far, including one in progress.
    pub attempts: i32,
    /// Its own limit on tries, or `None` for the queue's.
    pub max_attempts: Option<i32>,
    /// Its priority.
    pub priority: i16,
    /// Its time limit, if it was given one.
    pub timeout: Option<Duration>,
    /// The tenant it runs for, if any.
    pub tenant: Option<String>,
    /// The key it is unique by while queued or running, if any.
    pub unique_key: Option<String>,
    /// The text of its last failure. For operators only: it is whatever the job's
    /// error said.
    pub error: Option<String>,
    /// When it may run next, or last could.
    pub run_at: Timestamp,
    /// When its latest run started.
    pub started_at: Option<Timestamp>,
    /// When it was queued.
    pub created_at: Timestamp,
    /// When its row last changed.
    pub updated_at: Timestamp,
}

/// How many jobs are in each state, for metrics.
#[derive(Debug, Clone, Copy, Default, PartialEq)]
#[non_exhaustive]
pub struct Counts {
    /// Queued and due.
    pub ready: i64,
    /// Queued for a later time.
    pub waiting: i64,
    /// Claimed and running.
    pub running: i64,
    /// Finished, and not yet deleted by retention.
    pub completed: i64,
    /// Failed, and not yet deleted by retention.
    pub failed: i64,
    /// Cancelled, and not yet deleted by retention.
    pub cancelled: i64,
    /// Stopped after losing their claim, waiting for a person. Never deleted by
    /// retention.
    pub needs_review: i64,
    /// Seconds the oldest ready job has waited, or zero. A rising value means jobs
    /// are not being run.
    pub oldest_ready_seconds: f64,
}

/// A job queued every interval, or at the times a cron pattern names. See
/// [Schedules](crate#schedules).
#[derive(Clone)]
pub struct Schedule {
    name: String,
    times: Times,
    first: Option<Timestamp>,
    job: NewJob,
}

/// When a schedule is due.
#[derive(Clone)]
enum Times {
    Every(Duration),
    /// The parsed pattern, and the pattern as written, which `croner` would rewrite.
    Cron(Box<croner::Cron>, String),
}

impl Times {
    fn interval(&self) -> Option<Duration> {
        match self {
            Self::Every(interval) => Some(*interval),
            Self::Cron(..) => None,
        }
    }

    fn pattern(&self) -> Option<&str> {
        match self {
            Self::Every(_) => None,
            Self::Cron(_, pattern) => Some(pattern),
        }
    }
}

/// The time after `now` a cron pattern names, in UTC.
fn next_after(cron: &croner::Cron, now: Timestamp) -> Result<Timestamp> {
    cron.find_next_occurrence(&InUtc(now), false)
        .map(|next| next.0)
        .map_err(|error| Error::Job(format!("the cron pattern has no next time: {error}")))
}

/// An instant as `croner` reads it, on a wall clock in UTC, which has no daylight
/// saving, so every wall clock time is one instant. `croner`'s own `jiff` support is for
/// an older `jiff`, so the crate gives it this one time zone itself.
#[derive(Clone, Copy)]
struct InUtc(Timestamp);

impl croner::CronDateTime for InUtc {
    fn to_civil(&self) -> croner::CivilDateTime {
        let time = jiff::tz::TimeZone::UTC.to_datetime(self.0);
        croner::CivilDateTime::new(
            croner::CivilDate::from_parts_unchecked(
                i32::from(time.year()),
                time.month().unsigned_abs().into(),
                time.day().unsigned_abs().into(),
            ),
            croner::CivilTime::from_parts_unchecked(
                time.hour().unsigned_abs().into(),
                time.minute().unsigned_abs().into(),
                time.second().unsigned_abs().into(),
            ),
        )
    }

    fn civil_weekday(&self) -> croner::Weekday {
        let day = jiff::tz::TimeZone::UTC
            .to_datetime(self.0)
            .weekday()
            .to_sunday_zero_offset();
        croner::Weekday::from_days_from_sunday(day.unsigned_abs().into())
    }

    fn resolve_civil(
        &self,
        civil: croner::CivilDateTime,
    ) -> Result<croner::Resolution<Self>, croner::errors::CronError> {
        let part =
            |value: u32| i8::try_from(value).map_err(|_| croner::errors::CronError::InvalidDate);
        let year =
            i16::try_from(civil.year()).map_err(|_| croner::errors::CronError::InvalidDate)?;
        let time = jiff::civil::DateTime::new(
            year,
            part(civil.month())?,
            part(civil.day())?,
            part(civil.hour())?,
            part(civil.minute())?,
            part(civil.second())?,
            0,
        )
        .and_then(|time| jiff::tz::TimeZone::UTC.to_timestamp(time))
        .map_err(|_| croner::errors::CronError::InvalidDate)?;
        Ok(croner::Resolution::Single(Self(time)))
    }

    fn checked_add_seconds(&self, seconds: i64) -> Option<Self> {
        self.0
            .checked_add(jiff::SignedDuration::from_secs(seconds))
            .ok()
            .map(Self)
    }

    fn cmp_instant(&self, other: &Self) -> std::cmp::Ordering {
        self.0.cmp(&other.0)
    }
}

/// A time column of `row`.
fn time(row: &PgRow, column: &str) -> Result<Timestamp> {
    Ok(row.try_get::<jiff_sqlx::Timestamp, _>(column)?.to_jiff())
}

/// A time column of `row` that may be `NULL`.
fn time_or_none(row: &PgRow, column: &str) -> Result<Option<Timestamp>> {
    Ok(row
        .try_get::<Option<jiff_sqlx::Timestamp>, _>(column)?
        .map(jiff_sqlx::Timestamp::to_jiff))
}

impl fmt::Debug for Schedule {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Schedule")
            .field("name", &self.name)
            .field("interval", &self.times.interval())
            .field("cron", &self.times.pattern())
            .field("first", &self.first)
            .field("job", &self.job)
            .finish()
    }
}

impl Schedule {
    /// Queue `job` every `interval`, under the schedule name `name`. The name keys
    /// its row, so keep it stable across releases. A delay set on `job` is ignored.
    ///
    /// # Panics
    ///
    /// When the name is empty or over 200 characters, or the interval is under a
    /// second, as Axum panics on a bad route: these are mistakes in code, found at
    /// boot.
    pub fn every(name: impl Into<String>, interval: Duration, job: NewJob) -> Self {
        let name = checked_name(name.into());
        assert!(
            interval >= Duration::from_secs(1),
            "the schedule {name} needs an interval of at least a second"
        );
        Self {
            name,
            times: Times::Every(interval),
            first: None,
            job: NewJob {
                when: When::Now,
                ..job
            },
        }
    }

    /// Queue `job` at each time the cron `pattern` names, in UTC on the database's
    /// clock, under the schedule name `name`. The pattern has five fields, minute to
    /// day of week, or six with seconds first, as `croner` reads them: `"0 2 * * *"` is
    /// 02:00 each day, and `"0 9 * * MON-FRI"` 09:00 each weekday. A delay set on `job`
    /// is ignored. The first time is the pattern's next after the row is made.
    ///
    /// # Panics
    ///
    /// When the name is empty or over 200 characters, or the pattern does not parse
    /// or names no time to come, as Axum panics on a bad route: these are mistakes in
    /// code, found at boot.
    pub fn cron(name: impl Into<String>, pattern: &str, job: NewJob) -> Self {
        let name = checked_name(name.into());
        let cron: croner::Cron = pattern
            .parse()
            .unwrap_or_else(|error| panic!("the schedule {name} has a bad cron pattern: {error}"));
        assert!(
            next_after(&cron, Timestamp::now()).is_ok(),
            "the cron pattern of the schedule {name} names no time to come"
        );
        Self {
            name,
            times: Times::Cron(Box::new(cron), pattern.to_string()),
            first: None,
            job: NewJob {
                when: When::Now,
                ..job
            },
        }
    }

    /// The first due time, used only when the schedule's row is made. With an
    /// interval of 24 hours and a first time at 02:00 UTC, the job runs at 02:00
    /// each day. Without one, the first is as soon as the row is made. A cron
    /// schedule's first time is its pattern's, and it ignores this.
    #[must_use]
    pub const fn first_at(mut self, first: Timestamp) -> Self {
        self.first = Some(first);
        self
    }

    /// The schedule's interval, or `None` for a cron schedule.
    #[must_use]
    pub fn interval(&self) -> Option<Duration> {
        self.times.interval()
    }

    /// The schedule's cron pattern, or `None` for one every interval.
    #[must_use]
    pub fn cron_pattern(&self) -> Option<&str> {
        self.times.pattern()
    }

    /// The schedule's name.
    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }
}

/// Refuse a schedule name that is empty or over 200 characters.
fn checked_name(name: String) -> String {
    assert!(
        !name.is_empty() && name.len() <= 200,
        "a schedule name must be 1 to 200 characters"
    );
    name
}

/// What the table holds of one schedule.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct ScheduleInfo {
    /// Its name.
    pub name: String,
    /// Its interval, as the code last had it, or `None` for a cron schedule.
    pub interval: Option<Duration>,
    /// Its cron pattern, as the code last had it, or `None` for one every interval.
    pub cron: Option<String>,
    /// When it is next due.
    pub due_at: Timestamp,
    /// The last job it queued.
    pub last_job: Option<Uuid>,
    /// That job's state, unless retention deleted it.
    pub last_state: Option<JobState>,
    /// That job's last failure text. For operators only.
    pub last_error: Option<String>,
    /// When a live process last had it in code, to within a minute.
    pub seen_at: Timestamp,
    /// When it was archived, as no live process had it in code. An archived
    /// schedule queues nothing, and a schedule of that name in code restores it.
    pub archived_at: Option<Timestamp>,
    /// When its row was made.
    pub created_at: Timestamp,
}

/// Queue tuning.
#[derive(Debug, Clone)]
pub struct QueueOptions {
    /// Concurrent job loops, so the most jobs this process runs at once.
    pub workers: usize,
    /// Sleep between polls of an empty queue, and between schedule ticks.
    pub poll_interval: Duration,
    /// A running job not heard from for this many minutes is assumed lost with
    /// its worker.
    pub stale_minutes: i32,
    /// How often a running job reports in. Keep it well under `stale_minutes`.
    pub heartbeat_interval: Duration,
    /// Tries a job gets, including the first, unless it has its own limit. One
    /// means no retries.
    pub max_attempts: i32,
    /// The wait before the first retry.
    pub retry_backoff: Duration,
    /// Days to keep finished and cancelled rows.
    pub retention_days: i32,
    /// How often to recover stale jobs and delete old rows.
    pub maintenance_interval: Duration,
}

impl Default for QueueOptions {
    fn default() -> Self {
        Self {
            workers: 2,
            poll_interval: Duration::from_secs(1),
            stale_minutes: 60,
            heartbeat_interval: Duration::from_mins(1),
            max_attempts: 1,
            retry_backoff: Duration::from_secs(30),
            retention_days: 7,
            maintenance_interval: Duration::from_mins(5),
        }
    }
}

/// A Postgres-backed job queue.
pub struct Queue {
    pool: PgPool,
    handlers: HashMap<String, Handler>,
    limits: HashMap<String, Arc<Semaphore>>,
    schedules: Vec<Schedule>,
    options: QueueOptions,
}

impl fmt::Debug for Queue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Queue")
            .field("handlers", &self.handlers.len())
            .field("limits", &self.limits.len())
            .field("schedules", &self.schedules.len())
            .field("options", &self.options)
            .finish_non_exhaustive()
    }
}

/// A claimed job, as `run_one` holds it.
struct Claimed {
    id: Uuid,
    name: String,
    args: serde_json::Value,
    attempts: i32,
    limit: i32,
    timeout: Option<Duration>,
    tenant: Option<String>,
}

/// How a run ended.
enum Outcome {
    /// The job answered, or failed, timed out, or panicked, with this text.
    Done(Result<(), Failure>),
    /// The run lost its claim and was stopped, for this reason.
    Lost(String),
}

impl Queue {
    /// A queue on `pool`, checking and changing nothing. Call [`Queue::check`] at
    /// boot. Give the pool at least `workers + 2` connections.
    #[must_use]
    pub fn from_pool(pool: PgPool, options: QueueOptions) -> Self {
        Self {
            pool,
            handlers: HashMap::new(),
            limits: HashMap::new(),
            schedules: Vec::new(),
            options,
        }
    }

    /// Open a pool sized for the job loops, without touching the schema.
    async fn open(uri: &str, options: QueueOptions) -> Result<Self> {
        let loops = u32::try_from(options.workers).unwrap_or(u32::MAX);
        let pool = PgPoolOptions::new()
            // The loops, housekeeping, schedules, and the listener.
            .max_connections(loops.saturating_add(3))
            .connect(uri)
            .await?;
        Ok(Self::from_pool(pool, options))
    }

    /// Connect to tables that a migration made, and change no schema, for a database
    /// role that may not. A migration runs [`SETUP_STATEMENTS`].
    ///
    /// # Errors
    ///
    /// Fails when the database cannot be reached, a table is missing or out of date,
    /// or a trigger of `axa_job_acts` is missing or not set to fire always, so a
    /// service finds out at boot rather than at its first job. There is no way to run
    /// without the triggers.
    pub async fn connect_existing(uri: &str, options: QueueOptions) -> Result<Self> {
        let queue = Self::open(uri, options).await?;
        queue.check().await?;
        Ok(queue)
    }

    /// Connect and create the tables if needed, which runs DDL at boot. Use
    /// [`Queue::connect_existing`] where a service's role may not.
    ///
    /// # Errors
    ///
    /// Fails when the database cannot be reached or the tables not created.
    pub async fn connect(uri: &str, options: QueueOptions) -> Result<Self> {
        let queue = Self::open(uri, options).await?;
        // `CREATE ... IF NOT EXISTS` is not safe against itself: two services
        // booting together can both pass the check and one then fails on a
        // catalog constraint. The lock makes setup run one at a time, and
        // ends with the transaction.
        let mut setup = queue.pool.begin().await?;
        sqlx::query("SELECT pg_advisory_xact_lock($1)")
            .bind(SETUP_LOCK)
            .execute(&mut *setup)
            .await?;
        for statement in SETUP_STATEMENTS {
            sqlx::query(statement).execute(&mut *setup).await?;
        }
        setup.commit().await?;
        Ok(queue)
    }

    /// Check that the tables exist and are up to date, and that the triggers of
    /// `axa_job_acts` are there and set to fire always.
    ///
    /// # Errors
    ///
    /// Fails when the database cannot be reached, a table is missing or out of date,
    /// or a trigger is missing or turned off.
    pub async fn check(&self) -> Result<()> {
        sqlx::query(
            "SELECT attempts, max_attempts, priority, timeout_ms, tenant, unique_key FROM axa_queue LIMIT 0",
        )
        .execute(&self.pool)
        .await?;
        sqlx::query(
            "SELECT name, due_at, last_job, interval_ms, cron, seen_at, archived_at FROM axa_schedule LIMIT 0",
        )
            .execute(&self.pool)
            .await?;
        sqlx::query(
            "SELECT id, job_id, job_name, act, attempts, by, reason, at FROM axa_job_acts LIMIT 0",
        )
        .execute(&self.pool)
        .await?;
        let mut missing: Vec<String> = sqlx::query_scalar(MISSING_TRIGGERS)
            .bind(ACTS_TRIGGERS.to_vec())
            .fetch_all(&self.pool)
            .await?;
        let unique_index: bool =
            sqlx::query_scalar("SELECT to_regclass('axa_queue_unique') IS NOT NULL")
                .fetch_one(&self.pool)
                .await?;
        if !unique_index {
            missing.push("axa_queue_unique".to_string());
        }
        if missing.is_empty() {
            Ok(())
        } else {
            Err(Error::Database(sqlx::Error::Configuration(
                format!(
                    "the job queue is missing, or has turned off, {}: run SETUP_STATEMENTS",
                    missing.join(", ")
                )
                .into(),
            )))
        }
    }

    /// The pool, for a service's own queries or [`enqueue_on`] outside a
    /// transaction.
    #[must_use]
    pub const fn pool(&self) -> &PgPool {
        &self.pool
    }

    /// The options this queue runs with.
    #[must_use]
    pub const fn options(&self) -> &QueueOptions {
        &self.options
    }

    /// Run `handler` for jobs named `name`. Its error text is kept on the job's
    /// row. Registering a name again replaces its handler.
    ///
    /// A job queued for a tenant, with [`NewJob::tenant`], is failed rather than run
    /// here, as this handler would run it with no tenant: register a handler that
    /// takes one with [`Queue::handle_with_tenant`].
    pub fn handle<F, Fut, E>(&mut self, name: impl Into<String>, handler: F)
    where
        F: Fn(serde_json::Value) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = std::result::Result<(), E>> + Send + 'static,
        E: fmt::Display + 'static,
    {
        let handler = Arc::new(handler);
        let run: Handler = Arc::new(move |tenant, args| {
            if tenant.is_some() {
                return Box::pin(std::future::ready(Err(NO_TENANT_HANDLER
                    .to_string()
                    .into())));
            }
            let job = handler(args);
            Box::pin(async move { job.await.map_err(Failure::from_error) })
        });
        self.handlers.insert(name.into(), run);
    }

    /// Run `handler` for jobs named `name`, handing it the job's tenant, or `None` for
    /// a job queued with none, beside its arguments, so that it can open its own
    /// tenant transaction. Claiming stays fair across jobs, not tenants. Registering a
    /// name again replaces its handler.
    pub fn handle_with_tenant<F, Fut, E>(&mut self, name: impl Into<String>, handler: F)
    where
        F: Fn(Option<String>, serde_json::Value) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = std::result::Result<(), E>> + Send + 'static,
        E: fmt::Display + 'static,
    {
        let handler = Arc::new(handler);
        let run: Handler = Arc::new(move |tenant, args| {
            let job = handler(tenant, args);
            Box::pin(async move { job.await.map_err(Failure::from_error) })
        });
        self.handlers.insert(name.into(), run);
    }

    /// Run at most `jobs` jobs named `name` at once in this process, and at least
    /// one. Other jobs keep the remaining loops busy.
    pub fn limit(&mut self, name: impl Into<String>, jobs: usize) {
        self.limits
            .insert(name.into(), Arc::new(Semaphore::new(jobs.max(1))));
    }

    /// Queue a job on every due time of `schedule`.
    ///
    /// # Panics
    ///
    /// When a schedule of that name was added already.
    pub fn schedule(&mut self, schedule: Schedule) {
        assert!(
            self.schedules.iter().all(|s| s.name != schedule.name),
            "the schedule {} was added twice",
            schedule.name
        );
        self.schedules.push(schedule);
    }

    /// Add a job and return its id.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn enqueue(&self, name: &str, args: serde_json::Value) -> Result<Uuid> {
        enqueue_on(&self.pool, &NewJob::new(name, args)).await
    }

    /// Add a job with its own limit on tries, or the queue's when `None`.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn enqueue_limited(
        &self,
        name: &str,
        args: serde_json::Value,
        max_attempts: Option<i32>,
    ) -> Result<Uuid> {
        enqueue_on(
            &self.pool,
            &NewJob::new(name, args).max_attempts(max_attempts),
        )
        .await
    }

    /// Add `job` and return its id.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn enqueue_job(&self, job: &NewJob) -> Result<Uuid> {
        enqueue_on(&self.pool, job).await
    }

    /// Add every job in `jobs` in one transaction, so all are queued or none.
    ///
    /// # Errors
    ///
    /// Fails on a database error, and then none was queued.
    pub async fn enqueue_all(&self, jobs: &[NewJob]) -> Result<Vec<Uuid>> {
        let mut transaction = self.pool.begin().await?;
        let ids = enqueue_all_on(&mut transaction, jobs).await?;
        transaction.commit().await?;
        Ok(ids)
    }

    /// What the queue knows of the job `id`, or `None` when there is no such job,
    /// as after retention deleted it.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn job(&self, id: Uuid) -> Result<Option<JobInfo>> {
        let Some(row) = sqlx::query(STATUS)
            .bind(id)
            .fetch_optional(&self.pool)
            .await?
        else {
            return Ok(None);
        };
        Ok(Some(JobInfo {
            id: row.try_get("id")?,
            name: row.try_get("name")?,
            state: JobState::parse(row.try_get::<&str, _>("status")?)?,
            attempts: row.try_get("attempts")?,
            max_attempts: row.try_get("max_attempts")?,
            priority: row.try_get("priority")?,
            timeout: row
                .try_get::<Option<i64>, _>("timeout_ms")?
                .map(from_millis),
            tenant: row.try_get("tenant")?,
            unique_key: row.try_get("unique_key")?,
            error: row.try_get("error")?,
            run_at: time(&row, "run_at")?,
            started_at: time_or_none(&row, "started_at")?,
            created_at: time(&row, "created_at")?,
            updated_at: time(&row, "updated_at")?,
        }))
    }

    /// Every act a person did to the job `id`, oldest first, for a service's own
    /// review screens. Acts are kept after retention deletes the job's row. A person
    /// acts with [`cancel()`] and [`retry()`], in the caller's transaction.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn acts(&self, id: Uuid) -> Result<Vec<Act>> {
        let rows = sqlx::query(ACTS).bind(id).fetch_all(&self.pool).await?;
        rows.iter()
            .map(|row| {
                Ok(Act {
                    id: row.try_get("id")?,
                    job_id: row.try_get("job_id")?,
                    job_name: row.try_get("job_name")?,
                    kind: ActKind::parse(row.try_get::<&str, _>("act")?)?,
                    attempts: row.try_get("attempts")?,
                    by: row.try_get("by")?,
                    reason: row.try_get("reason")?,
                    at: time(row, "at")?,
                })
            })
            .collect()
    }

    /// How many jobs are in each state.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn counts(&self) -> Result<Counts> {
        let row = sqlx::query(COUNTS).fetch_one(&self.pool).await?;
        Ok(Counts {
            ready: row.try_get("ready")?,
            waiting: row.try_get("waiting")?,
            running: row.try_get("running")?,
            completed: row.try_get("completed")?,
            failed: row.try_get("failed")?,
            cancelled: row.try_get("cancelled")?,
            needs_review: row.try_get("needs_review")?,
            oldest_ready_seconds: row.try_get::<Option<f64>, _>("oldest")?.unwrap_or(0.0),
        })
    }

    /// Check the database connection.
    ///
    /// # Errors
    ///
    /// Fails when the database does not answer.
    pub async fn ping(&self) -> Result<()> {
        sqlx::query("SELECT 1").execute(&self.pool).await?;
        Ok(())
    }

    /// Recover jobs abandoned by a worker that died: queue again those with
    /// attempts left and fail the rest, returning how many were queued again.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn requeue_stale(&self) -> Result<u64> {
        sqlx::query(FAIL_STALE)
            .bind(self.options.stale_minutes)
            .bind(self.options.max_attempts)
            .execute(&self.pool)
            .await?;
        let result = sqlx::query(REQUEUE_STALE)
            .bind(self.options.stale_minutes)
            .bind(self.options.max_attempts)
            .execute(&self.pool)
            .await?;
        Ok(result.rows_affected())
    }

    /// Delete finished and cancelled rows older than the retention period,
    /// returning how many went.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn purge_finished(&self) -> Result<u64> {
        let result = sqlx::query(PURGE)
            .bind(self.options.retention_days)
            .execute(&self.pool)
            .await?;
        Ok(result.rows_affected())
    }

    /// Queue a job for each schedule that is due, returning how many were queued.
    /// [`Queue::run`] calls this on every poll. Any number of processes may call it
    /// at once: each due time is queued once.
    ///
    /// # Errors
    ///
    /// Fails on a database error, which leaves that schedule due for the next tick.
    pub async fn tick_schedules(&self) -> Result<usize> {
        let mut queued = 0;
        for schedule in &self.schedules {
            if self.tick(schedule).await? {
                queued += 1;
            }
        }
        Ok(queued)
    }

    /// One schedule's tick, returning whether it queued a job.
    async fn tick(&self, schedule: &Schedule) -> Result<bool> {
        // Outside the transaction: an upsert locks the row it meets, and replicas
        // would then wait on each other instead of skipping.
        let first = match &schedule.times {
            Times::Every(_) => schedule.first,
            Times::Cron(cron, _) => {
                let now: jiff_sqlx::Timestamp = sqlx::query_scalar("SELECT now()")
                    .fetch_one(&self.pool)
                    .await?;
                Some(next_after(cron, now.to_jiff())?)
            }
        };
        sqlx::query(SCHEDULE_CREATE)
            .bind(&schedule.name)
            .bind(first.map(jiff_sqlx::Timestamp::from))
            .bind(schedule.times.interval().map(millis))
            .bind(schedule.times.pattern())
            .execute(&self.pool)
            .await?;
        let mut transaction = self.pool.begin().await?;
        // Another process holding the row is queuing this time already.
        let Some(row) = sqlx::query(SCHEDULE_LOCK)
            .bind(&schedule.name)
            .fetch_optional(&mut *transaction)
            .await?
        else {
            return Ok(false);
        };
        if !row.try_get::<bool, _>("due")? {
            transaction.commit().await?;
            return Ok(false);
        }
        let busy = match row.try_get::<Option<Uuid>, _>("last_job")? {
            Some(last) => {
                sqlx::query_scalar::<_, bool>(SCHEDULE_BUSY)
                    .bind(last)
                    .fetch_one(&mut *transaction)
                    .await?
            }
            None => false,
        };
        let job = if busy {
            tracing::info!(schedule = %schedule.name, "schedule skipped, its last job has not finished");
            None
        } else {
            Some(enqueue_on(&mut *transaction, &schedule.job).await?)
        };
        match &schedule.times {
            Times::Every(interval) => {
                sqlx::query(SCHEDULE_ADVANCE)
                    .bind(&schedule.name)
                    .bind(interval.as_secs_f64())
                    .bind(job)
                    .execute(&mut *transaction)
                    .await?;
            }
            Times::Cron(cron, _) => {
                sqlx::query(SCHEDULE_ADVANCE_TO)
                    .bind(&schedule.name)
                    .bind(jiff_sqlx::Timestamp::from(next_after(
                        cron,
                        time(&row, "now")?,
                    )?))
                    .bind(job)
                    .execute(&mut *transaction)
                    .await?;
            }
        }
        transaction.commit().await?;
        if job.is_some() {
            tracing::debug!(schedule = %schedule.name, "schedule queued its job");
        }
        Ok(job.is_some())
    }

    /// Archive the schedules that no live process has in code, returning how many
    /// were archived. Rows are kept, for audit. Housekeeping runs this.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn archive_schedules(&self) -> Result<u64> {
        let names: Vec<&str> = self.schedules.iter().map(|s| s.name.as_str()).collect();
        let result = sqlx::query(SCHEDULE_ARCHIVE)
            .bind(&names)
            .bind(self.options.stale_minutes)
            .execute(&self.pool)
            .await?;
        Ok(result.rows_affected())
    }

    /// Every schedule the table holds, archived or not, with its last job's state.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn schedules(&self) -> Result<Vec<ScheduleInfo>> {
        let rows = sqlx::query(SCHEDULES).fetch_all(&self.pool).await?;
        rows.iter()
            .map(|row| {
                Ok(ScheduleInfo {
                    name: row.try_get("name")?,
                    interval: row
                        .try_get::<Option<i64>, _>("interval_ms")?
                        .map(from_millis),
                    cron: row.try_get("cron")?,
                    due_at: time(row, "due_at")?,
                    last_job: row.try_get("last_job")?,
                    last_state: row
                        .try_get::<Option<&str>, _>("last_status")?
                        .map(JobState::parse)
                        .transpose()?,
                    last_error: row.try_get("last_error")?,
                    seen_at: time(row, "seen_at")?,
                    archived_at: time_or_none(row, "archived_at")?,
                    created_at: time(row, "created_at")?,
                })
            })
            .collect()
    }

    /// One round of housekeeping. Failures are logged, because the next round
    /// can try again.
    async fn maintain(&self) {
        match self.archive_schedules().await {
            Ok(0) => {}
            Ok(archived) => tracing::info!(archived, "archived schedules no longer in code"),
            Err(error) => tracing::error!(%error, "could not archive schedules"),
        }
        if let Err(error) = self.requeue_stale().await {
            tracing::error!(%error, "could not recover stale jobs");
        }
        if let Err(error) = self.purge_finished().await {
            tracing::error!(%error, "could not delete old jobs");
        }
    }

    /// Run `job` to its end in its own task, reporting in as it goes, so a panic
    /// stops only the job. The job is stopped when its time limit passes, when its
    /// claim is found taken, or when this future is dropped.
    async fn supervise(&self, job: JobFuture, claim: &Claimed) -> Outcome {
        let mut job = AbortOnDrop(tokio::spawn(job));
        let every = self.options.heartbeat_interval.max(MIN_HEARTBEAT);
        // Not heard from for this long, a run is taken for lost by any worker.
        let stale =
            Duration::from_secs(u64::try_from(self.options.stale_minutes).unwrap_or(0) * 60);
        // This worker stops the job before then, two heartbeats early, and at half the
        // time at the latest, so that it has stopped before another can take it.
        let give_up = stale.saturating_sub(every * 2).max(stale / 2);
        let mut last_heard = tokio::time::Instant::now();
        // A heartbeat is given at most `every` to answer, and runs beside the job, so
        // a database that hangs holds up neither the job's time limit nor giving up.
        let beat = || {
            tokio::time::timeout(
                every,
                sqlx::query(HEARTBEAT)
                    .bind(claim.id)
                    .bind(claim.attempts)
                    .execute(&self.pool),
            )
        };
        let mut beating = None;
        let mut next_beat = tokio::time::Instant::now() + every;
        let mut failing = false;
        let limit = claim
            .timeout
            .map(|timeout| tokio::time::Instant::now() + timeout);
        let deadline = async {
            match limit {
                Some(at) => tokio::time::sleep_until(at).await,
                None => std::future::pending().await,
            }
        };
        tokio::pin!(deadline);
        loop {
            tokio::select! {
                finished = &mut job.0 => {
                    return Outcome::Done(finished.unwrap_or_else(|_| {
                        Err(Error::Job("the job panicked".to_string()).to_string().into())
                    }));
                }
                () = &mut deadline => {
                    let limit = claim.timeout.unwrap_or_default();
                    return Outcome::Done(Err(
                        Error::Job(format!("timed out after {}s", limit.as_secs_f64())).to_string().into(),
                    ));
                }
                () = tokio::time::sleep_until(last_heard + give_up), if failing => {
                    return Outcome::Lost(format!(
                        "it could not report in for {}s, near the {} minutes after which another worker may take it",
                        give_up.as_secs(),
                        self.options.stale_minutes
                    ));
                }
                () = tokio::time::sleep_until(next_beat), if beating.is_none() => {
                    beating = Some(Box::pin(beat()));
                }
                answer = async {
                    match beating.as_mut() {
                        Some(beat) => beat.await,
                        None => std::future::pending().await,
                    }
                }, if beating.is_some() => {
                    beating = None;
                    next_beat = tokio::time::Instant::now() + every;
                    match answer {
                        Ok(Ok(done)) if done.rows_affected() == 1 => {
                            last_heard = tokio::time::Instant::now();
                            failing = false;
                        }
                        Ok(Ok(_)) => return Outcome::Lost("another worker or recovery took its claim".to_string()),
                        Ok(Err(error)) => {
                            tracing::warn!(id = %claim.id, %error, "job heartbeat failed");
                            failing = true;
                        }
                        Err(_) => {
                            tracing::warn!(id = %claim.id, "job heartbeat did not answer in time");
                            failing = true;
                        }
                    }
                }
            }
        }
    }

    /// Mark a run's job for review, trying until the database answers, as the
    /// run must not be taken for a crash and retried.
    async fn mark_lost(&self, claim: &Claimed, reason: &str) {
        let text = Error::Job(format!("stopped: {reason}")).to_string();
        let every = self.options.heartbeat_interval.max(MIN_HEARTBEAT);
        loop {
            match sqlx::query(MARK_LOST)
                .bind(claim.id)
                .bind(&text)
                .execute(&self.pool)
                .await
            {
                Ok(_) => return,
                Err(error) => {
                    tracing::error!(id = %claim.id, %error, "could not mark a lost job for review");
                    tokio::time::sleep(every).await;
                }
            }
        }
    }

    /// The job names this loop may claim now, holding a place under each limit
    /// that has one free. The places not used are given back when dropped.
    fn claimable(&self) -> (Vec<String>, HashMap<String, OwnedSemaphorePermit>) {
        let mut places = HashMap::new();
        let mut names = Vec::new();
        for name in self.handlers.keys() {
            match self.limits.get(name) {
                None => names.push(name.clone()),
                Some(limit) => {
                    if let Ok(place) = limit.clone().try_acquire_owned() {
                        places.insert(name.clone(), place);
                        names.push(name.clone());
                    }
                }
            }
        }
        (names, places)
    }

    async fn claim(&self, names: &[String]) -> Result<Option<Claimed>> {
        let Some(row) = sqlx::query(CLAIM)
            .bind(names)
            .fetch_optional(&self.pool)
            .await?
        else {
            return Ok(None);
        };
        Ok(Some(Claimed {
            id: row.try_get("id")?,
            name: row.try_get("name")?,
            args: row.try_get("args")?,
            attempts: row.try_get("attempts")?,
            limit: row
                .try_get::<Option<i32>, _>("max_attempts")?
                .unwrap_or(self.options.max_attempts),
            timeout: row
                .try_get::<Option<i64>, _>("timeout_ms")?
                .map(from_millis),
            tenant: row.try_get("tenant")?,
        }))
    }

    /// Claim and run one job, returning whether there was one. A job's own
    /// failure is recorded on its row, not returned.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn run_one(&self) -> Result<bool> {
        let (names, mut places) = self.claimable();
        if names.is_empty() {
            return Ok(false);
        }
        let Some(job) = self.claim(&names).await? else {
            return Ok(false);
        };
        // Keep only the place this job takes.
        let _place = places.remove(&job.name);
        drop(places);
        let outcome = match self.handlers.get(&job.name) {
            Some(handler) => {
                let run = handler(job.tenant.clone(), job.args.clone());
                self.supervise(run, &job).await
            }
            None => Outcome::Done(Err(Error::Job(format!("no handler for job {}", job.name))
                .to_string()
                .into())),
        };
        let (id, name, attempts) = (job.id, job.name.as_str(), job.attempts);
        let finished = match outcome {
            Outcome::Lost(reason) => {
                tracing::error!(job = %name, %id, attempts, %reason, "job stopped, it lost its claim");
                self.mark_lost(&job, &reason).await;
                return Ok(true);
            }
            Outcome::Done(Ok(())) => {
                sqlx::query(FINISH)
                    .bind(id)
                    .bind(attempts)
                    .bind("completed")
                    .bind(None::<String>)
                    .execute(&self.pool)
                    .await?
            }
            Outcome::Done(Err(error)) if attempts < job.limit => {
                tracing::warn!(job = %name, %id, attempts, %error, "job failed, will retry");
                let wait = retry_wait(self.options.retry_backoff, attempts, error.retry_in);
                sqlx::query(RETRY)
                    .bind(id)
                    .bind(attempts)
                    .bind(cut(error.text))
                    .bind(wait.as_secs_f64())
                    .execute(&self.pool)
                    .await?
            }
            Outcome::Done(Err(error)) => {
                tracing::error!(job = %name, %id, attempts, %error, "job failed");
                sqlx::query(FINISH)
                    .bind(id)
                    .bind(attempts)
                    .bind("failed")
                    .bind(cut(error.text))
                    .execute(&self.pool)
                    .await?
            }
        };
        if finished.rows_affected() == 0 {
            // It ran to its end, but its claim had been taken, so the job may be
            // running again elsewhere.
            tracing::error!(job = %name, %id, "job finished after losing its claim");
            self.mark_lost(
                &job,
                "it finished after another worker or recovery took its claim",
            )
            .await;
        }
        Ok(true)
    }

    /// Run job loops, housekeeping, and schedules until `shutdown` changes to
    /// `true`. Jobs in progress finish first, so a caller that must stop by a
    /// time limit drops this future at it, which aborts those jobs and leaves them
    /// for stale recovery. Housekeeping runs straight away, to recover anything a
    /// previous process left behind, and then on a timer.
    pub async fn run(self: Arc<Self>, shutdown: watch::Receiver<bool>) {
        let mut loops = Vec::new();
        loops.push(AbortOnDrop(tokio::spawn(every_until(
            shutdown.clone(),
            self.options.maintenance_interval,
            {
                let queue = self.clone();
                move || {
                    let queue = queue.clone();
                    async move { queue.maintain().await }
                }
            },
        ))));
        if !self.schedules.is_empty() {
            let queue = self.clone();
            loops.push(AbortOnDrop(tokio::spawn(every_until(
                shutdown.clone(),
                self.options.poll_interval,
                move || {
                    let queue = queue.clone();
                    async move {
                        if let Err(error) = queue.tick_schedules().await {
                            tracing::error!(%error, "could not queue scheduled jobs");
                        }
                    }
                },
            ))));
        }
        let wake = Arc::new(Notify::new());
        loops.push(AbortOnDrop(tokio::spawn(listen(
            self.pool.clone(),
            wake.clone(),
            self.options.poll_interval,
            shutdown.clone(),
        ))));
        for _ in 0..self.options.workers.max(1) {
            let queue = self.clone();
            let wake = wake.clone();
            let mut shutdown = shutdown.clone();
            loops.push(AbortOnDrop(tokio::spawn(async move {
                while !*shutdown.borrow() {
                    let round = async {
                        queue.run_one().await.unwrap_or_else(|error| {
                            tracing::error!(%error, "job queue error");
                            false
                        })
                    };
                    work_or_wait(&wake, queue.options.poll_interval, &mut shutdown, round).await;
                }
            })));
        }
        for job_loop in &mut loops {
            let _ = (&mut job_loop.0).await;
        }
    }

    /// The names of the job types this queue handles.
    #[must_use]
    pub fn handled(&self) -> HashSet<&str> {
        self.handlers.keys().map(String::as_str).collect()
    }
}

/// Run `round`, and when it found no work, wait for `poll`, a wake, or shutdown. The
/// wait is listened for before `round` starts, so a notice that comes while `round`
/// looks, after it found nothing, still wakes the loop rather than being lost.
async fn work_or_wait(
    wake: &Notify,
    poll: Duration,
    shutdown: &mut watch::Receiver<bool>,
    round: impl Future<Output = bool>,
) {
    let woken = wake.notified();
    tokio::pin!(woken);
    woken.as_mut().enable();
    if !round.await {
        tokio::select! {
            () = tokio::time::sleep(poll) => {},
            () = woken => {},
            _ = shutdown.changed() => {},
        }
    }
}

/// Wake the idle job loops at each notice on [`NOTIFY_CHANNEL`], until `shutdown`.
/// A listener that fails is opened again after `gap`, the loops polling meanwhile.
async fn listen(
    pool: PgPool,
    wake: Arc<Notify>,
    gap: Duration,
    mut shutdown: watch::Receiver<bool>,
) {
    while !*shutdown.borrow() {
        match sqlx::postgres::PgListener::connect_with(&pool).await {
            Ok(mut listener) => match listener.listen(NOTIFY_CHANNEL).await {
                Ok(()) => loop {
                    tokio::select! {
                        notice = listener.try_recv() => match notice {
                            // A notice, or a dropped connection, which the next call opens again:
                            // a notice sent meanwhile is lost, so wake the loops to look.
                            Ok(_) => wake.notify_waiters(),
                            Err(error) => {
                                tracing::warn!(%error, "job queue listener failed, polling");
                                break;
                            }
                        },
                        _ = shutdown.changed() => return,
                    }
                },
                Err(error) => tracing::warn!(%error, "job queue could not listen, polling"),
            },
            Err(error) => tracing::warn!(%error, "job queue could not listen, polling"),
        }
        tokio::select! {
            () = tokio::time::sleep(gap) => {},
            _ = shutdown.changed() => {},
        }
    }
}

/// Run `round` now and then every `gap`, until `shutdown` is `true`.
async fn every_until<F, Fut>(mut shutdown: watch::Receiver<bool>, gap: Duration, round: F)
where
    F: Fn() -> Fut,
    Fut: Future<Output = ()>,
{
    while !*shutdown.borrow() {
        round().await;
        tokio::select! {
            () = tokio::time::sleep(gap) => {},
            _ = shutdown.changed() => {},
        }
    }
}

/// A task that is aborted when its handle is dropped, so that dropping
/// [`Queue::run`] stops its loops and their jobs instead of leaving them running.
struct AbortOnDrop<T>(tokio::task::JoinHandle<T>);

impl<T> Drop for AbortOnDrop<T> {
    fn drop(&mut self) {
        self.0.abort();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn a_wake_during_a_round_that_found_nothing_is_not_lost() {
        let wake = Notify::new();
        let (_stop, mut shutdown) = watch::channel(false);
        // The notice comes while the round looks, before the loop would wait.
        let round = async {
            wake.notify_waiters();
            false
        };
        let waited = tokio::time::timeout(
            Duration::from_secs(5),
            work_or_wait(&wake, Duration::from_hours(1), &mut shutdown, round),
        )
        .await;
        assert!(
            waited.is_ok(),
            "the wake was lost and the loop waited for its poll"
        );
    }

    #[test]
    fn each_retry_waits_twice_as_long_up_to_a_limit() {
        let base = Duration::from_secs(30);
        assert_eq!(backoff(base, 1), base);
        assert_eq!(backoff(base, 2), base * 2);
        assert_eq!(backoff(base, 3), base * 4);
        assert_eq!(backoff(base, 1_000), MAX_BACKOFF);
    }

    #[test]
    fn a_retry_waits_a_jittered_backoff_or_the_delay_the_job_chose() {
        let base = Duration::from_secs(30);
        for _ in 0..200 {
            let wait = retry_wait(base, 2, None);
            assert!(wait >= base && wait <= base * 2, "{wait:?}");
        }
        let waits: HashSet<_> = (0..20).map(|_| retry_wait(base, 1, None)).collect();
        assert!(waits.len() > 1, "the waits are spread");
        assert_eq!(retry_wait(Duration::ZERO, 3, None), Duration::ZERO);
        let chosen = Some(Duration::from_secs(90));
        assert_eq!(retry_wait(base, 1, chosen), Duration::from_secs(90));
        assert_eq!(retry_wait(base, 1, Some(Duration::ZERO)), MIN_RETRY_AFTER);
        assert_eq!(
            retry_wait(base, 1, Some(Duration::from_hours(9))),
            MAX_BACKOFF
        );
    }

    #[test]
    fn a_retry_after_error_carries_its_delay_and_others_none() {
        let chosen = Failure::from_error(RetryAfter::new(Duration::from_secs(7), "busy"));
        assert_eq!(
            (chosen.text.as_str(), chosen.retry_in),
            ("busy", Some(Duration::from_secs(7)))
        );
        let boxed: Box<dyn std::error::Error + Send + Sync> =
            Box::new(RetryAfter::new(Duration::from_secs(8), "boxed"));
        assert_eq!(
            Failure::from_error(boxed).retry_in,
            Some(Duration::from_secs(8))
        );
        let plain = Failure::from_error("broken".to_string());
        assert_eq!((plain.text.as_str(), plain.retry_in), ("broken", None));
    }

    #[test]
    fn the_debug_text_leaves_out_arguments() {
        let job = NewJob::new("Report", serde_json::json!({ "nhs": "943 476 5919" }));
        let schedule = Schedule::every("nightly", Duration::from_hours(1), job.clone());
        let cron = Schedule::cron("at-two", "0 2 * * *", job.clone());
        for text in [
            format!("{job:?}"),
            format!("{schedule:?}"),
            format!("{cron:?}"),
        ] {
            assert!(text.contains("Report"), "{text}");
            assert!(!text.contains("943"), "{text}");
        }
    }

    #[test]
    fn a_by_or_reason_that_is_not_a_code_is_refused() {
        assert!(check_code("ops:alice", "by").is_ok());
        assert!(check_code(&"é".repeat(MAX_REASON_CHARS), "reason").is_ok());
        for bad in [
            String::new(),
            "é".repeat(MAX_REASON_CHARS + 1),
            "two\nlines".to_string(),
            "a\ttab".to_string(),
        ] {
            let error = check_code(&bad, "reason").unwrap_err();
            assert!(matches!(error, Error::NotACode { what: "reason" }));
            assert!(!error.to_string().contains("lines"), "the text is left out");
        }
    }

    #[test]
    fn a_long_error_is_cut_on_a_character_boundary() {
        let text = "é".repeat(MAX_ERROR);
        let kept = cut(text);
        assert!(kept.len() <= MAX_ERROR);
        assert!(kept.chars().all(|c| c == 'é'));
        assert_eq!(cut("short".to_string()), "short");
    }

    #[test]
    #[should_panic(expected = "at least a second")]
    fn a_schedule_under_a_second_is_refused_at_boot() {
        let _ = Schedule::every(
            "fast",
            Duration::from_millis(10),
            NewJob::new("J", serde_json::Value::Null),
        );
    }

    #[test]
    #[should_panic(expected = "bad cron pattern")]
    fn a_bad_cron_pattern_is_refused_at_boot() {
        let _ = Schedule::cron(
            "bad",
            "61 * * * *",
            NewJob::new("J", serde_json::Value::Null),
        );
    }

    #[test]
    fn a_cron_schedule_names_its_next_times_in_utc() {
        let schedule = Schedule::cron(
            "weekdays",
            "0 9 * * MON-FRI",
            NewJob::new("J", serde_json::Value::Null),
        );
        assert_eq!(schedule.cron_pattern(), Some("0 9 * * MON-FRI"));
        assert_eq!(schedule.interval(), None);
        let Times::Cron(cron, _) = &schedule.times else {
            panic!("a cron schedule")
        };
        // Friday 2026-11-13 09:00 UTC is due, so the next after it is Monday's.
        let friday: Timestamp = "2026-11-13T09:00:00Z".parse().unwrap();
        let monday: Timestamp = "2026-11-16T09:00:00Z".parse().unwrap();
        assert_eq!(next_after(cron, friday).unwrap(), monday);
        assert_eq!(
            Schedule::every(
                "e",
                Duration::from_secs(5),
                NewJob::new("J", serde_json::Value::Null)
            )
            .interval(),
            Some(Duration::from_secs(5))
        );
    }

    #[test]
    fn a_cron_schedule_counts_in_utc_across_a_month_end_and_a_clock_change() {
        let next = |pattern: &str, after: &str| {
            let cron: croner::Cron = pattern.parse().unwrap();
            next_after(&cron, after.parse().unwrap())
                .unwrap()
                .to_string()
        };
        // The 31st skips a month of 30 days, and the year end is an ordinary midnight.
        assert_eq!(
            next("0 0 31 * *", "2026-11-15T00:00:00Z"),
            "2026-12-31T00:00:00Z"
        );
        assert_eq!(
            next("30 23 * * *", "2026-12-31T23:30:00Z"),
            "2027-01-01T23:30:00Z"
        );
        assert_eq!(
            next("0 12 29 2 *", "2026-03-01T00:00:00Z"),
            "2028-02-29T12:00:00Z"
        );
        // Clocks in Europe go forward at 01:00 UTC on 2026-03-29 and back at 01:00 UTC
        // on 2026-10-25, and in the US back on 2026-11-01. UTC has no such change, so
        // 01:30 comes once each day, 24 hours apart.
        assert_eq!(
            next("30 1 * * *", "2026-03-28T01:30:00Z"),
            "2026-03-29T01:30:00Z"
        );
        assert_eq!(
            next("30 1 * * *", "2026-10-25T01:30:00Z"),
            "2026-10-26T01:30:00Z"
        );
        assert_eq!(
            next("0 6 * * *", "2026-11-01T06:00:00Z"),
            "2026-11-02T06:00:00Z"
        );
        // A time part way through a second goes on to the next whole one.
        assert_eq!(
            next("* * * * * *", "2026-11-15T00:00:00.5Z"),
            "2026-11-15T00:00:01Z"
        );
    }

    #[test]
    #[should_panic(expected = "1 to 200 characters")]
    fn a_schedule_with_no_name_is_refused_at_boot() {
        let _ = Schedule::every(
            "",
            Duration::from_secs(1),
            NewJob::new("J", serde_json::Value::Null),
        );
    }

    #[tokio::test]
    #[should_panic(expected = "added twice")]
    async fn a_schedule_added_twice_is_refused_at_boot() {
        let pool = PgPoolOptions::new()
            .connect_lazy("postgres://u@localhost/none")
            .unwrap();
        let mut queue = Queue::from_pool(pool, QueueOptions::default());
        let job = NewJob::new("J", serde_json::Value::Null);
        queue.schedule(Schedule::every("a", Duration::from_secs(5), job.clone()));
        queue.schedule(Schedule::every("a", Duration::from_secs(9), job));
    }

    #[test]
    fn a_schedule_ignores_a_delay_on_its_job() {
        let job = NewJob::new("J", serde_json::Value::Null).run_in(Duration::from_hours(1));
        let schedule = Schedule::every("s", Duration::from_secs(5), job);
        assert_eq!(schedule.job.when, When::Now);
    }
}

//! `SeaORM` connections, migrations, schema helpers, and test resets.
//!
//! This crate has the same shape as `axa-postgres-sqlx`, `axa-postgres-diesel`, and `axa-postgres-toasty`: a
//! [`Pool`], a [`PoolConfig`], [`connect`], [`ping`], [`migrate`], [`revert`],
//! [`pending`], [`truncate`], [`dangerously_recreate`], [`is_unique_violation`], and
//! [`quote_identifier`]. The migration functions take the service's `Migrator` as a
//! type, as `sea-orm-migration` does.
//!
//! It also makes leaving Loco easy. A project keeps `SeaORM` and most of its code,
//! because the helpers Loco provided keep their names and behaviour:
//!
//! | Loco | Here |
//! |---|---|
//! | `loco_rs::model::{ModelError, ModelResult}` | `axa::model`, for every database |
//! | `loco_rs::model::query::condition()` | [`query::condition`] |
//! | `loco_rs::schema` | [`schema`] |
//! | `loco_rs::validation::Validatable` | `axa::validation`, for every database |
//! | `loco_rs::db::truncate_table` | [`truncate_table`] |
//!
//! ```no_run
//! use axa_postgres_seaorm::{PoolConfig, connect};
//!
//! # async fn run() -> Result<(), axa_postgres_seaorm::sea_orm::DbErr> {
//! let db = connect(&PoolConfig::new("postgres://localhost/app")).await?;
//! # Ok(())
//! # }
//! ```

use std::sync::OnceLock;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};

pub use sea_orm;
use sea_orm::{
    ConnectOptions, ConnectionTrait, Database, DatabaseConnection, DatabaseTransaction, DbBackend,
    DbErr, EntityTrait, SqlErr, Statement, TransactionTrait,
};
pub use sea_orm_migration;
use sea_orm_migration::MigratorTrait;

pub mod query;
pub mod schema;

/// The handle a service holds: `SeaORM`'s connection, which owns a pool.
pub type Pool = DatabaseConnection;

/// What this crate's functions return on failure.
pub type Error = DbErr;

/// Pool settings.
#[derive(Clone, PartialEq, Eq)]
pub struct PoolConfig {
    /// Connection string.
    pub uri: String,
    /// Connections kept open.
    pub min_connections: u32,
    /// Largest number of connections.
    pub max_connections: u32,
    /// How long to wait for a connection, in milliseconds.
    pub connect_timeout_ms: u64,
    /// How long an idle connection stays open, in milliseconds.
    pub idle_timeout_ms: u64,
    /// Log every statement.
    pub enable_logging: bool,
    /// Postgres's `statement_timeout` on every connection, in milliseconds. `0` sets
    /// none.
    pub statement_timeout_ms: u64,
    /// Postgres's `application_name` on every connection, so `pg_stat_activity` says
    /// which service a query came from. Empty sets none.
    pub application_name: String,
    /// Open every transaction read-only, as for a read replica or a reporting
    /// service, so that a write is refused by the database.
    pub read_only: bool,
}

impl std::fmt::Debug for PoolConfig {
    /// Leaves the connection string out, because it can carry a password.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PoolConfig")
            .field("min_connections", &self.min_connections)
            .field("max_connections", &self.max_connections)
            .field("connect_timeout_ms", &self.connect_timeout_ms)
            .field("idle_timeout_ms", &self.idle_timeout_ms)
            .field("enable_logging", &self.enable_logging)
            .field("statement_timeout_ms", &self.statement_timeout_ms)
            .field("application_name", &self.application_name)
            .field("read_only", &self.read_only)
            .finish_non_exhaustive()
    }
}

impl PoolConfig {
    /// Settings for `uri` with a small pool.
    #[must_use]
    pub fn new(uri: impl Into<String>) -> Self {
        Self {
            uri: uri.into(),
            min_connections: 1,
            max_connections: 10,
            connect_timeout_ms: 5_000,
            idle_timeout_ms: 600_000,
            enable_logging: false,
            statement_timeout_ms: 0,
            application_name: String::new(),
            read_only: false,
        }
    }

    /// The `SeaORM` options these settings describe.
    #[must_use]
    pub fn options(&self) -> ConnectOptions {
        self.options_for(self.uri.clone())
    }

    /// These settings, connecting to `uri`.
    fn options_for(&self, uri: String) -> ConnectOptions {
        let mut options = ConnectOptions::new(uri);
        options
            .min_connections(self.min_connections)
            .max_connections(self.max_connections)
            .connect_timeout(Duration::from_millis(self.connect_timeout_ms))
            .idle_timeout(Duration::from_millis(self.idle_timeout_ms))
            .sqlx_logging(self.enable_logging)
            // Retire a connection whose cached statements a migration has made stale.
            .map_sqlx_postgres_before_acquire(|_connection, meta| {
                Box::pin(async move { Ok(!opened_before_last_stale_plan(meta.age)) })
            });
        options
    }
}

/// When this process first needed a clock for stale plans.
static EPOCH: OnceLock<Instant> = OnceLock::new();

/// Nanoseconds after [`EPOCH`] that a stale plan was last seen, plus one, or `0` for
/// never.
static LAST_STALE_PLAN: AtomicU64 = AtomicU64::new(0);

fn epoch() -> Instant {
    *EPOCH.get_or_init(Instant::now)
}

/// The sqlx error under a `SeaORM` error, when there is one.
fn sqlx_error(error: &DbErr) -> Option<&sea_orm::sqlx::Error> {
    use sea_orm::RuntimeErr;
    match error {
        DbErr::Exec(RuntimeErr::SqlxError(error)) | DbErr::Query(RuntimeErr::SqlxError(error)) => {
            Some(error.as_ref())
        }
        _ => None,
    }
}

/// Whether `error` is Postgres refusing a statement this connection prepared before a
/// migration changed what it returns: SQLSTATE `0A000` with "cached plan must not
/// change result type". Each pooled connection that cached the statement fails so
/// once, and a fresh connection does not.
#[must_use]
pub fn is_stale_plan(error: &DbErr) -> bool {
    sqlx_error(error)
        .and_then(sea_orm::sqlx::Error::as_database_error)
        .is_some_and(|error| {
            error.code().as_deref() == Some("0A000")
                && error
                    .message()
                    .contains("cached plan must not change result type")
        })
}

/// Record `error` if it is a stale plan, so that every connection opened before now is
/// retired when next acquired, from every pool [`connect`] opened in this process, and
/// the next attempt runs on a fresh one. Returns whether it was. `axa::Error` calls
/// this for every `SeaORM` error it answers, so a service that turns `SeaORM` errors
/// into it needs nothing more.
pub fn note_stale_plan(error: &DbErr) -> bool {
    if !is_stale_plan(error) {
        return false;
    }
    let since = u64::try_from(epoch().elapsed().as_nanos()).unwrap_or(u64::MAX - 1);
    LAST_STALE_PLAN.fetch_max(since.saturating_add(1), Ordering::SeqCst);
    true
}

/// Whether a connection `age` old was opened at or before the last stale plan.
fn opened_before_last_stale_plan(age: Duration) -> bool {
    opened_before(
        LAST_STALE_PLAN.load(Ordering::SeqCst),
        epoch().elapsed(),
        age,
    )
}

/// Whether a connection `age` old at `now`, both since [`EPOCH`], was opened at or
/// before `last`, as [`LAST_STALE_PLAN`] holds it.
fn opened_before(last: u64, now: Duration, age: Duration) -> bool {
    if last == 0 {
        return false;
    }
    now.saturating_sub(age) <= Duration::from_nanos(last - 1)
}

impl PoolConfig {
    /// The connection string with the session settings added, as every connection
    /// [`connect`] opens uses.
    ///
    /// # Errors
    ///
    /// When the URL sets `options` already and a statement timeout or read-only mode
    /// is set here too, or when the application name is not one Postgres keeps as it
    /// is.
    pub fn connection_uri(&self) -> Result<String, DbErr> {
        session_uri(
            &self.uri,
            self.statement_timeout_ms,
            &self.application_name,
            self.read_only,
        )
        .map_err(DbErr::Custom)
    }
}

/// `uri` with each session setting added as a libpq connection parameter, so that
/// every connection the pool opens starts with them, at no extra round trip:
/// `statement_timeout` and `default_transaction_read_only` in `options`, and
/// `application_name`.
///
/// An `application_name` the URL already names is kept. `options` the URL already
/// names, with a setting here to add, is refused, rather than either one silently
/// replacing the other.
fn session_uri(
    uri: &str,
    statement_timeout_ms: u64,
    application_name: &str,
    read_only: bool,
) -> Result<String, String> {
    let mut options = Vec::new();
    if statement_timeout_ms > 0 {
        options.push(format!("-c statement_timeout={statement_timeout_ms}"));
    }
    if read_only {
        options.push("-c default_transaction_read_only=on".to_string());
    }
    let mut params = Vec::new();
    if !options.is_empty() {
        if has_param(uri, "options") {
            return Err(
                "the connection URL sets options already: set the statement timeout and \
                 read-only mode there, or here, not both"
                    .to_string(),
            );
        }
        params.push(("options", options.join(" ")));
    }
    if !application_name.is_empty() && !has_param(uri, "application_name") {
        if !is_application_name(application_name) {
            return Err(
                "an application name is ASCII letters, digits, `_`, `.`, and `-`, at most 63"
                    .to_string(),
            );
        }
        params.push(("application_name", application_name.to_string()));
    }
    if params.is_empty() {
        return Ok(uri.to_string());
    }
    let separator = if uri.contains('?') { '&' } else { '?' };
    let query: Vec<String> = params
        .iter()
        .map(|(name, value)| format!("{name}={}", percent_encode(value)))
        .collect();
    Ok(format!("{uri}{separator}{}", query.join("&")))
}

/// Whether the query of `uri` names `name`.
fn has_param(uri: &str, name: &str) -> bool {
    uri.split_once('?').is_some_and(|(_, query)| {
        query
            .split('&')
            .any(|pair| pair.split('=').next() == Some(name))
    })
}

/// Whether `name` is an application name Postgres keeps as it is: ASCII letters,
/// digits, `_`, `.`, and `-`, from 1 to 63 bytes.
fn is_application_name(name: &str) -> bool {
    (1..=63).contains(&name.len())
        && name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'.' | b'-'))
}

/// `value` with every byte but the unreserved ones percent-encoded.
fn percent_encode(value: &str) -> String {
    use std::fmt::Write as _;
    let mut encoded = String::new();
    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            encoded.push(char::from(byte));
        } else {
            let _ = write!(encoded, "%{byte:02X}");
        }
    }
    encoded
}

/// Open a pool.
///
/// # Errors
///
/// Fails when the database cannot be reached.
pub async fn connect(config: &PoolConfig) -> Result<DatabaseConnection, DbErr> {
    Database::connect(config.options_for(config.connection_uri()?)).await
}

/// Delete every row of one entity's table. Rows in other tables are left
/// alone, so a test that needs a truly empty database should use
/// `Migrator::fresh` instead.
///
/// # Errors
///
/// Propagates the database error.
pub async fn truncate_table<T: EntityTrait>(
    db: &DatabaseConnection,
    _entity: T,
) -> Result<(), DbErr> {
    T::delete_many().exec(db).await?;
    Ok(())
}

/// Check the database connection.
///
/// # Errors
///
/// Fails when the database does not answer.
pub async fn ping(pool: &Pool) -> Result<(), DbErr> {
    pool.ping().await
}

/// Apply every pending migration of `M`.
///
/// # Errors
///
/// Fails on a database error, and then no later migration is tried.
pub async fn migrate<M: MigratorTrait>(pool: &Pool) -> Result<(), DbErr> {
    M::up(pool, None).await
}

/// Revert the last `steps` applied migrations of `M`, newest first.
///
/// # Errors
///
/// Fails on a database error.
pub async fn revert<M: MigratorTrait>(pool: &Pool, steps: u32) -> Result<(), DbErr> {
    M::down(pool, Some(steps)).await
}

/// The names of the migrations of `M` not yet applied, in order.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending<M: MigratorTrait>(pool: &Pool) -> Result<Vec<String>, DbErr> {
    Ok(M::get_pending_migrations(pool)
        .await?
        .iter()
        .map(|migration| migration.name().to_string())
        .collect())
}

/// Drop every table, then apply every migration of `M` from the start, as
/// `Migrator::fresh` does. This destroys data: `axa::cli` allows it only in
/// development and test, and only when confirmed.
///
/// # Errors
///
/// Fails on a database error.
pub async fn dangerously_recreate<M: MigratorTrait>(pool: &Pool) -> Result<(), DbErr> {
    M::fresh(pool).await
}

/// Whether `error` is the database refusing a duplicate under a unique constraint.
#[must_use]
pub fn is_unique_violation(error: &DbErr) -> bool {
    matches!(error.sql_err(), Some(SqlErr::UniqueConstraintViolation(_)))
}

/// `name` in double quotes, when it is a plain lower-case identifier: a letter or
/// `_`, then letters, digits, and `_`. Anything else is refused, so it cannot carry
/// SQL.
#[must_use]
pub fn quote_identifier(name: &str) -> Option<String> {
    let mut chars = name.chars();
    let first = chars.next()?;
    let valid = (first.is_ascii_lowercase() || first == '_')
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    valid.then(|| format!("\"{name}\""))
}

/// Whether `name` is a custom setting a service may set for row-level security: two or
/// more parts of lower-case ASCII letters, digits, and underscores, joined by dots, such
/// as `app.tenant`. A name with no dot is Postgres's own, such as `role` or
/// `search_path`, which this never sets.
///
/// ```
/// assert!(axa_postgres_seaorm::is_custom_setting("app.tenant"));
/// assert!(!axa_postgres_seaorm::is_custom_setting("search_path"));
/// ```
#[must_use]
pub fn is_custom_setting(name: &str) -> bool {
    let parts: Vec<&str> = name.split('.').collect();
    name.len() <= 63
        && parts.len() >= 2
        && parts.iter().all(|part| {
            part.chars()
                .next()
                .is_some_and(|first| first.is_ascii_lowercase() || first == '_')
                && part
                    .chars()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
        })
}

/// Open a transaction with each `(name, value)` set for its length only, such as
/// `("app.tenant", tenant.as_str())` for a row-level security policy that reads
/// `current_setting('app.tenant', true)`.
///
/// Each pair is set with `set_config($1, $2, true)`: bound, never formatted into the
/// SQL, and gone when the transaction commits or rolls back, so a pooled connection
/// never carries one request's tenant into the next. Run every query that needs the
/// setting on the transaction this returns.
///
/// A policy sees nothing unless the role the service connects as is subject to it: not
/// a superuser, without `BYPASSRLS`, and, if it owns the table, with
/// `FORCE ROW LEVEL SECURITY` on it. [`row_security`] checks.
///
/// # Errors
///
/// [`DbErr::Custom`] for a name [`is_custom_setting`] refuses, before anything is
/// sent, and any error from beginning the transaction or setting a value.
pub async fn begin_with(
    pool: &Pool,
    settings: &[(&str, &str)],
) -> Result<DatabaseTransaction, DbErr> {
    if let Some((name, _)) = settings.iter().find(|(name, _)| !is_custom_setting(name)) {
        return Err(DbErr::Custom(format!("not a custom setting: {name}")));
    }
    let tx = pool.begin().await?;
    for (name, value) in settings {
        tx.execute_raw(Statement::from_sql_and_values(
            DbBackend::Postgres,
            "SELECT set_config($1, $2, true)",
            [(*name).into(), (*value).into()],
        ))
        .await?;
    }
    Ok(tx)
}

/// Whether row-level security can keep rows apart for the role a pool connects as.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RowSecurity {
    /// The role the pool connects as.
    pub role: String,
    /// Whether that role skips every policy: a superuser, or a role with `BYPASSRLS`.
    pub bypasses: bool,
    /// The tables asked about that do not exist, have no row-level security, or lack
    /// `FORCE ROW LEVEL SECURITY`, so that their owner skips the policies.
    pub unprotected: Vec<String>,
}

impl RowSecurity {
    /// Whether the policies on every table asked about apply to the role.
    #[must_use]
    pub fn holds(&self) -> bool {
        !self.bypasses && self.unprotected.is_empty()
    }
}

/// Ask Postgres whether row-level security can apply to `pool`'s role, and whether
/// each of `tables`, such as `todos` or `app.todos`, has it enabled and forced. Call it
/// at boot, after migrating, and refuse to serve when it does not hold.
///
/// # Errors
///
/// Any error from the queries.
pub async fn row_security<S: AsRef<str>>(pool: &Pool, tables: &[S]) -> Result<RowSecurity, DbErr> {
    let role = pool
        .query_one_raw(Statement::from_string(
            DbBackend::Postgres,
            "SELECT current_user::text AS role, rolsuper OR rolbypassrls AS bypasses
             FROM pg_roles WHERE rolname = current_user",
        ))
        .await?
        .ok_or_else(|| DbErr::Custom("no row for the current role".to_string()))?;
    let mut unprotected = Vec::new();
    for table in tables {
        let table = table.as_ref();
        let forced = pool
            .query_one_raw(Statement::from_sql_and_values(
                DbBackend::Postgres,
                "SELECT relrowsecurity AND relforcerowsecurity AS forced FROM pg_class
                 WHERE oid = to_regclass($1)",
                [table.into()],
            ))
            .await?
            .map(|row| row.try_get::<bool>("", "forced"))
            .transpose()?;
        if forced != Some(true) {
            unprotected.push(table.to_string());
        }
    }
    Ok(RowSecurity {
        role: role.try_get("", "role")?,
        bypasses: role.try_get("", "bypasses")?,
        unprotected,
    })
}

/// Empty `tables` and restart their identities, for a test. Every name must be a
/// plain lower-case identifier. [`truncate_table`] empties one entity's table.
///
/// # Errors
///
/// Fails on a database error, or a name that is not a plain identifier, before
/// anything is emptied.
pub async fn truncate<S: AsRef<str>>(pool: &Pool, tables: &[S]) -> Result<(), DbErr> {
    if tables.is_empty() {
        return Ok(());
    }
    let tables = tables
        .iter()
        .map(|name| {
            quote_identifier(name.as_ref())
                .ok_or_else(|| DbErr::Custom(format!("invalid identifier: {}", name.as_ref())))
        })
        .collect::<Result<Vec<_>, _>>()?
        .join(", ");
    pool.execute_unprepared(&format!("TRUNCATE {tables} RESTART IDENTITY CASCADE"))
        .await?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn session_settings_become_connection_parameters() {
        let base = "postgres://app@db/app";
        assert_eq!(session_uri(base, 0, "", false).unwrap(), base);
        assert_eq!(
            session_uri(base, 5000, "orders", true).unwrap(),
            "postgres://app@db/app?options=-c%20statement_timeout%3D5000%20-c%20\
             default_transaction_read_only%3Don&application_name=orders"
        );
        assert_eq!(
            session_uri("postgres://db/app?sslmode=require", 0, "orders", false).unwrap(),
            "postgres://db/app?sslmode=require&application_name=orders"
        );
    }

    #[test]
    fn a_connection_is_retired_only_if_opened_by_the_last_stale_plan() {
        let second = Duration::from_secs(1);
        // Never a stale plan: nothing is retired.
        assert!(!opened_before(0, 10 * second, 9 * second));
        // A stale plan at 5s: a connection opened at 1s or 5s goes, one at 6s stays.
        let at_five = 5_000_000_000 + 1;
        assert!(opened_before(at_five, 10 * second, 9 * second));
        assert!(opened_before(at_five, 10 * second, 5 * second));
        assert!(!opened_before(at_five, 10 * second, 4 * second));
        // An age past the epoch is opened before anything.
        assert!(opened_before(at_five, second, 9 * second));
    }

    #[test]
    fn a_url_that_sets_them_already_is_kept_or_refused() {
        // Its own application name wins.
        let named = "postgres://db/app?application_name=mine";
        assert_eq!(session_uri(named, 0, "orders", false).unwrap(), named);
        // Its own options and a setting here would replace one another, so neither does.
        let with_options = "postgres://db/app?options=-c%20work_mem%3D64MB";
        assert!(session_uri(with_options, 5000, "", false).is_err());
        assert!(session_uri(with_options, 0, "", true).is_err());
        assert_eq!(
            session_uri(with_options, 0, "", false).unwrap(),
            with_options
        );
        for name in ["has space", "a&b=c", "é", &"a".repeat(64)] {
            assert!(
                session_uri("postgres://db/app", 0, name, false).is_err(),
                "{name}"
            );
        }
    }

    #[test]
    fn identifiers_are_quoted_and_unsafe_ones_refused() {
        assert_eq!(quote_identifier("users").as_deref(), Some("\"users\""));
        for name in ["", "1users", "Users", "a b", "a\"b", "a;b", "a.b"] {
            assert_eq!(quote_identifier(name), None, "{name:?}");
        }
    }

    #[test]
    fn errors_that_are_not_from_the_database_are_not_unique_violations() {
        assert!(!is_unique_violation(&DbErr::Custom("nothing".to_string())));
    }

    #[test]
    fn debug_text_leaves_out_the_connection_string() {
        let text = format!("{:?}", PoolConfig::new("postgres://me:hunter2@db/app"));
        assert!(!text.contains("hunter2"), "{text}");
        assert!(text.contains("max_connections"), "{text}");
    }

    #[test]
    fn the_default_timeouts_suit_a_real_database() {
        let config = PoolConfig::new("postgres://x");
        assert_eq!(config.connect_timeout_ms, 5_000);
        assert_eq!(config.idle_timeout_ms, 600_000);
    }

    #[test]
    fn pool_settings_reach_the_options() {
        let config = PoolConfig {
            min_connections: 2,
            max_connections: 7,
            connect_timeout_ms: 1_500,
            idle_timeout_ms: 9_500,
            ..PoolConfig::new("postgres://x")
        };
        let options = config.options();
        assert_eq!(options.get_min_connections(), Some(2));
        assert_eq!(options.get_max_connections(), Some(7));
        assert_eq!(
            options.get_connect_timeout(),
            Some(Duration::from_millis(1_500))
        );
        assert_eq!(
            options.get_idle_timeout(),
            Some(Some(Duration::from_millis(9_500)))
        );
    }
}

//! A small condition builder.
//!
//! It has the shape of Loco's, so code using it moves across unchanged. New
//! code can use `SeaORM` directly, which is just as short:
//! `Column::Email.eq(email)`.
//!
//! ```
//! use axa_postgres_seaorm::query::condition;
//! # use axa_postgres_seaorm::sea_orm::{self, entity::prelude::*};
//! # mod users {
//! #     use axa_postgres_seaorm::sea_orm::{self, entity::prelude::*};
//! #     #[derive(Clone, Debug, PartialEq, DeriveEntityModel)]
//! #     #[sea_orm(table_name = "users")]
//! #     pub struct Model {
//! #         #[sea_orm(primary_key)]
//! #         pub id: i32,
//! #         pub email: String,
//! #     }
//! #     #[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
//! #     pub enum Relation {}
//! #     impl ActiveModelBehavior for ActiveModel {}
//! # }
//! let filter = condition().eq(users::Column::Email, "a@example.org").build();
//! ```

use sea_orm::{ColumnTrait, Condition, Value};

/// A set of conditions, all of which must hold.
#[derive(Debug, Clone)]
pub struct ConditionBuilder {
    condition: Condition,
}

/// Start an empty condition.
#[must_use]
pub fn condition() -> ConditionBuilder {
    ConditionBuilder {
        condition: Condition::all(),
    }
}

impl ConditionBuilder {
    /// Add a column equality.
    #[must_use]
    pub fn eq<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.eq(value))
    }

    /// Add a column inequality.
    #[must_use]
    pub fn ne<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.ne(value))
    }

    /// Add a "greater than" comparison.
    #[must_use]
    pub fn gt<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.gt(value))
    }

    /// Add a "greater than or equal" comparison.
    #[must_use]
    pub fn gte<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.gte(value))
    }

    /// Add a "less than" comparison.
    #[must_use]
    pub fn lt<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.lt(value))
    }

    /// Add a "less than or equal" comparison.
    #[must_use]
    pub fn lte<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.lte(value))
    }

    /// Require a column to be null.
    #[must_use]
    pub fn is_null<T: ColumnTrait>(self, col: T) -> Self {
        self.with(col.is_null())
    }

    /// Require a column not to be null.
    #[must_use]
    pub fn is_not_null<T: ColumnTrait>(self, col: T) -> Self {
        self.with(col.is_not_null())
    }

    /// Require a column to be one of `values`.
    #[must_use]
    pub fn is_in<T, V, I>(self, col: T, values: I) -> Self
    where
        T: ColumnTrait,
        V: Into<Value>,
        I: IntoIterator<Item = V>,
    {
        self.with(col.is_in(values))
    }

    /// Require a column to contain `text`. `%` and `_` in `text` act as `LIKE`
    /// wildcards, so escape text that came from a user.
    #[must_use]
    pub fn contains<T: ColumnTrait>(self, col: T, text: &str) -> Self {
        self.with(col.contains(text))
    }

    /// Add any `SeaORM` condition, for what this builder does not cover.
    #[must_use]
    pub fn with(mut self, condition: impl sea_orm::sea_query::IntoCondition) -> Self {
        self.condition = self.condition.add(condition.into_condition());
        self
    }

    /// Finish.
    #[must_use]
    pub fn build(&self) -> Condition {
        self.condition.clone()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use sea_orm::{DbBackend, QueryFilter, QueryTrait, entity::prelude::*};

    mod users {
        use sea_orm::entity::prelude::*;

        #[derive(Clone, Debug, PartialEq, DeriveEntityModel)]
        #[sea_orm(table_name = "users")]
        pub struct Model {
            #[sea_orm(primary_key)]
            pub id: i32,
            pub email: String,
            pub age: i32,
            pub deleted_at: Option<DateTimeWithTimeZone>,
        }

        #[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
        pub enum Relation {}

        impl ActiveModelBehavior for ActiveModel {}
    }

    use users::{Column, Entity};

    fn sql(builder: &ConditionBuilder) -> String {
        Entity::find()
            .filter(builder.build())
            .build(DbBackend::Postgres)
            .to_string()
    }

    #[test]
    fn eq_and_ne_compare_values() {
        assert!(sql(&condition().eq(Column::Email, "a")).contains(r#""email" = 'a'"#));
        assert!(sql(&condition().ne(Column::Email, "a")).contains(r#""email" <> 'a'"#));
    }

    #[test]
    fn ordering_comparisons_use_their_operators() {
        assert!(sql(&condition().gt(Column::Age, 1)).contains(r#""age" > 1"#));
        assert!(sql(&condition().gte(Column::Age, 1)).contains(r#""age" >= 1"#));
        assert!(sql(&condition().lt(Column::Age, 1)).contains(r#""age" < 1"#));
        assert!(sql(&condition().lte(Column::Age, 1)).contains(r#""age" <= 1"#));
    }

    #[test]
    fn null_checks_use_is_null() {
        assert!(sql(&condition().is_null(Column::DeletedAt)).contains("IS NULL"));
        assert!(sql(&condition().is_not_null(Column::DeletedAt)).contains("IS NOT NULL"));
    }

    #[test]
    fn membership_lists_every_value() {
        assert!(sql(&condition().is_in(Column::Age, [1, 2])).contains("IN (1, 2)"));
    }

    #[test]
    fn contains_wraps_the_text_in_wildcards() {
        assert!(sql(&condition().contains(Column::Email, "ab")).contains("LIKE '%ab%'"));
    }

    #[test]
    fn several_conditions_must_all_hold() {
        let text = sql(&condition().eq(Column::Email, "a").gt(Column::Age, 1));
        assert!(text.contains(" AND "), "{text}");
    }

    #[test]
    fn an_empty_condition_filters_nothing() {
        // Rendered as `WHERE TRUE`, which matches every row.
        assert!(sql(&condition()).ends_with("WHERE TRUE"));
    }

    #[test]
    fn with_accepts_a_seaorm_condition() {
        let text = sql(&condition().with(Column::Email.eq("a")));
        assert!(text.contains(r#""email" = 'a'"#), "{text}");
    }
}

//! Migration helpers over `sea-orm-migration`.
//!
//! [`create_table`] adds `created_at` and `updated_at` with a `now()`
//! default, and table names are pluralised, so migrations written against
//! these helpers produce the schema they always have.

use heck::ToSnakeCase;
use sea_orm::DbErr;
use sea_orm_migration::{
    prelude::*,
    schema::{
        big_integer, big_integer_null, big_pk_auto, boolean, boolean_null, date, date_null, double,
        double_null, integer, integer_null, pk_uuid, string, string_null, string_uniq, text,
        text_null, timestamp_with_time_zone, timestamp_with_time_zone_null, uuid, uuid_null,
        uuid_uniq,
    },
    sea_query::{ForeignKeyAction, Table},
};

/// A column type.
#[derive(Debug, Clone, PartialEq)]
#[non_exhaustive]
pub enum ColType {
    /// 64-bit auto-increment primary key.
    PkAuto,
    /// UUID primary key.
    PkUuid,
    /// Required string.
    String,
    /// Optional string.
    StringNull,
    /// Required unique string.
    StringUniq,
    /// Required text.
    Text,
    /// Optional text.
    TextNull,
    /// Required 32-bit integer.
    Integer,
    /// Optional 32-bit integer.
    IntegerNull,
    /// Required 64-bit integer.
    BigInteger,
    /// Optional 64-bit integer.
    BigIntegerNull,
    /// Required double.
    Double,
    /// Optional double.
    DoubleNull,
    /// Required boolean.
    Boolean,
    /// Optional boolean.
    BooleanNull,
    /// Required boolean with a default.
    BooleanWithDefault(bool),
    /// Required date.
    Date,
    /// Optional date.
    DateNull,
    /// Required timestamp with time zone.
    TimestampWithTimeZone,
    /// Optional timestamp with time zone.
    TimestampWithTimeZoneNull,
    /// Required UUID.
    Uuid,
    /// Optional UUID.
    UuidNull,
    /// Required unique UUID.
    UuidUniq,
    /// Required JSONB.
    JsonBinary,
    /// Optional JSONB.
    JsonBinaryNull,
}

impl ColType {
    fn to_def(&self, name: Alias) -> ColumnDef {
        match self {
            Self::PkAuto => big_pk_auto(name),
            Self::PkUuid => pk_uuid(name),
            Self::String => string(name),
            Self::StringNull => string_null(name),
            Self::StringUniq => string_uniq(name),
            Self::Text => text(name),
            Self::TextNull => text_null(name),
            Self::Integer => integer(name),
            Self::IntegerNull => integer_null(name),
            Self::BigInteger => big_integer(name),
            Self::BigIntegerNull => big_integer_null(name),
            Self::Double => double(name),
            Self::DoubleNull => double_null(name),
            Self::Boolean => boolean(name),
            Self::BooleanNull => boolean_null(name),
            Self::BooleanWithDefault(value) => boolean(name).default(*value).take(),
            Self::Date => date(name),
            Self::DateNull => date_null(name),
            Self::TimestampWithTimeZone => timestamp_with_time_zone(name),
            Self::TimestampWithTimeZoneNull => timestamp_with_time_zone_null(name),
            Self::Uuid => uuid(name),
            Self::UuidNull => uuid_null(name),
            Self::UuidUniq => uuid_uniq(name),
            Self::JsonBinary => ColumnDef::new(name).json_binary().not_null().take(),
            Self::JsonBinaryNull => ColumnDef::new(name).json_binary().null().take(),
        }
    }
}

fn normalize_table(table: &str) -> std::string::String {
    cruet::to_plural(table).to_snake_case()
}

fn reference_id(table: &str) -> std::string::String {
    format!("{}_id", cruet::to_singular(table).to_snake_case())
}

/// Create a table with `created_at` and `updated_at`.
///
/// `refs` lists `(parent_table, column)`. An empty column means
/// `<parent>_id`, and a `?` suffix on the parent makes the reference
/// optional.
///
/// # Errors
///
/// Propagates the database error.
pub async fn create_table(
    m: &SchemaManager<'_>,
    table: &str,
    cols: &[(&str, ColType)],
    refs: &[(&str, &str)],
) -> Result<(), DbErr> {
    let table = normalize_table(table);
    let mut stmt = Table::create()
        .table(Alias::new(&table))
        .if_not_exists()
        .take();
    stmt.col(timestamp_with_time_zone(Alias::new("created_at")).default(Expr::current_timestamp()));
    stmt.col(timestamp_with_time_zone(Alias::new("updated_at")).default(Expr::current_timestamp()));
    for (name, col) in cols {
        stmt.col(col.to_def(Alias::new(*name)));
    }
    for (parent, column) in refs {
        let (parent, nullable) = parent.strip_suffix('?').map_or_else(
            || (normalize_table(parent), false),
            |stripped| (normalize_table(stripped), true),
        );
        let column = if column.is_empty() {
            reference_id(&parent)
        } else {
            (*column).to_string()
        };
        if !cols.iter().any(|(name, _)| *name == column) {
            let col = if nullable {
                ColType::BigIntegerNull
            } else {
                ColType::BigInteger
            };
            stmt.col(col.to_def(Alias::new(&column)));
        }
        let mut fk = ForeignKey::create();
        fk.name(format!("fk-{table}-{column}-to-{parent}"));
        fk.from(Alias::new(&table), Alias::new(&column));
        fk.to(Alias::new(parent), Alias::new("id"));
        if nullable {
            fk.on_delete(ForeignKeyAction::SetNull);
            fk.on_update(ForeignKeyAction::NoAction);
        } else {
            fk.on_delete(ForeignKeyAction::Cascade);
            fk.on_update(ForeignKeyAction::Cascade);
        }
        stmt.foreign_key(&mut fk);
    }
    m.create_table(stmt).await
}

/// Drop a table.
///
/// # Errors
///
/// Propagates the database error.
pub async fn drop_table(m: &SchemaManager<'_>, table: &str) -> Result<(), DbErr> {
    m.drop_table(
        Table::drop()
            .table(Alias::new(normalize_table(table)))
            .to_owned(),
    )
    .await
}

/// Add a column.
///
/// # Errors
///
/// Propagates the database error.
pub async fn add_column(
    m: &SchemaManager<'_>,
    table: &str,
    name: &str,
    col: ColType,
) -> Result<(), DbErr> {
    m.alter_table(
        Table::alter()
            .table(Alias::new(normalize_table(table)))
            .add_column(col.to_def(Alias::new(name)))
            .to_owned(),
    )
    .await
}

/// Remove a column.
///
/// # Errors
///
/// Propagates the database error.
pub async fn remove_column(m: &SchemaManager<'_>, table: &str, name: &str) -> Result<(), DbErr> {
    m.alter_table(
        Table::alter()
            .table(Alias::new(normalize_table(table)))
            .drop_column(Alias::new(name))
            .to_owned(),
    )
    .await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_names_are_pluralised_snake_case() {
        assert_eq!(normalize_table("user"), "users");
        assert_eq!(normalize_table("users"), "users");
        assert_eq!(normalize_table("CarePathway"), "care_pathways");
    }

    #[test]
    fn reference_columns_are_singular() {
        assert_eq!(reference_id("users"), "user_id");
    }
}

//! `PostgreSQL` pooling, migrations, and test resets over sqlx.
//!
//! This crate holds the operations every service repeats. It does not wrap
//! queries: a service writes its own SQL with `sqlx::query!`, so a reviewer
//! reads exactly what runs.
//!
//! It has the same shape as `axa-postgres-seaorm`, `axa-postgres-diesel`, and `axa-postgres-toasty`: a [`Pool`],
//! a [`PoolConfig`], [`connect`], [`ping`], [`migrate`], [`revert`], [`pending`],
//! [`truncate`], [`dangerously_recreate`], [`is_unique_violation`], and
//! [`quote_identifier`], with [`status`] besides.
//!
//! ```no_run
//! use axa_postgres_sqlx::{PoolConfig, connect, migrate, sqlx};
//!
//! static MIGRATOR: sqlx::migrate::Migrator = sqlx::migrate::Migrator::DEFAULT;
//!
//! # async fn run() -> Result<(), Box<dyn std::error::Error>> {
//! let pool = connect(&PoolConfig::new("postgres://localhost/app")).await?;
//! migrate(&pool, &MIGRATOR).await?;
//! # Ok(())
//! # }
//! ```

use std::{
    ops::{Deref, DerefMut},
    sync::{
        OnceLock,
        atomic::{AtomicU64, Ordering},
    },
    time::{Duration, Instant},
};

pub use sqlx;
use sqlx::{
    AssertSqlSafe, PgConnection, PgPool, Postgres, Row,
    migrate::{MigrateError, Migrator},
    pool::PoolConnection,
    postgres::PgPoolOptions,
};

/// The handle a service holds: the pool.
pub type Pool = PgPool;

/// What this crate's connection and query functions return on failure.
pub type Error = sqlx::Error;

/// Pool settings.
#[derive(Clone, PartialEq, Eq)]
pub struct PoolConfig {
    /// Connection string.
    pub uri: String,
    /// Connections kept open.
    pub min_connections: u32,
    /// Largest number of connections.
    pub max_connections: u32,
    /// How long to wait for a connection, in milliseconds.
    pub connect_timeout_ms: u64,
    /// How long an idle connection stays open, in milliseconds.
    pub idle_timeout_ms: u64,
    /// Postgres's `statement_timeout` on every connection, in milliseconds. `0` sets
    /// none.
    pub statement_timeout_ms: u64,
    /// Postgres's `application_name` on every connection, so `pg_stat_activity` says
    /// which service a query came from. Empty sets none.
    pub application_name: String,
    /// Open every transaction read-only, as for a read replica or a reporting
    /// service, so that a write is refused by the database.
    pub read_only: bool,
}

impl std::fmt::Debug for PoolConfig {
    /// Leaves the connection string out, because it can carry a password.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PoolConfig")
            .field("min_connections", &self.min_connections)
            .field("max_connections", &self.max_connections)
            .field("connect_timeout_ms", &self.connect_timeout_ms)
            .field("idle_timeout_ms", &self.idle_timeout_ms)
            .field("statement_timeout_ms", &self.statement_timeout_ms)
            .field("application_name", &self.application_name)
            .field("read_only", &self.read_only)
            .finish_non_exhaustive()
    }
}

impl PoolConfig {
    /// Settings for `uri` with a small pool.
    #[must_use]
    pub fn new(uri: impl Into<String>) -> Self {
        Self {
            uri: uri.into(),
            min_connections: 1,
            max_connections: 10,
            connect_timeout_ms: 5_000,
            idle_timeout_ms: 600_000,
            statement_timeout_ms: 0,
            application_name: String::new(),
            read_only: false,
        }
    }

    /// The sqlx options these settings describe.
    #[must_use]
    pub fn options(&self) -> PgPoolOptions {
        PgPoolOptions::new()
            .min_connections(self.min_connections)
            .max_connections(self.max_connections)
            .acquire_timeout(Duration::from_millis(self.connect_timeout_ms))
            .idle_timeout(Duration::from_millis(self.idle_timeout_ms))
            // Retire a connection whose cached statements a migration has made stale.
            .before_acquire(|_connection, meta| {
                Box::pin(async move { Ok(!opened_before_last_stale_plan(meta.age)) })
            })
    }
}

/// When this process first needed a clock for stale plans.
static EPOCH: OnceLock<Instant> = OnceLock::new();

/// Nanoseconds after [`EPOCH`] that a stale plan was last seen, plus one, or `0` for
/// never.
static LAST_STALE_PLAN: AtomicU64 = AtomicU64::new(0);

fn epoch() -> Instant {
    *EPOCH.get_or_init(Instant::now)
}

/// Whether `error` is Postgres refusing a statement this connection prepared before a
/// migration changed what it returns: SQLSTATE `0A000` with "cached plan must not
/// change result type". Each pooled connection that cached the statement fails so
/// once, and a fresh connection does not.
#[must_use]
pub fn is_stale_plan(error: &sqlx::Error) -> bool {
    error.as_database_error().is_some_and(|error| {
        error.code().as_deref() == Some("0A000")
            && error
                .message()
                .contains("cached plan must not change result type")
    })
}

/// Record `error` if it is a stale plan, so that every connection opened before now is
/// retired when next acquired, from every pool [`connect`] opened in this process, and
/// the next attempt runs on a fresh one. Returns whether it was. `axa::Error` calls
/// this for every sqlx error it answers, so a service that turns sqlx errors into it
/// needs nothing more.
pub fn note_stale_plan(error: &sqlx::Error) -> bool {
    if !is_stale_plan(error) {
        return false;
    }
    let since = u64::try_from(epoch().elapsed().as_nanos()).unwrap_or(u64::MAX - 1);
    LAST_STALE_PLAN.fetch_max(since.saturating_add(1), Ordering::SeqCst);
    true
}

/// Whether a connection `age` old was opened at or before the last stale plan.
fn opened_before_last_stale_plan(age: Duration) -> bool {
    opened_before(
        LAST_STALE_PLAN.load(Ordering::SeqCst),
        epoch().elapsed(),
        age,
    )
}

/// Whether a connection `age` old at `now`, both since [`EPOCH`], was opened at or
/// before `last`, as [`LAST_STALE_PLAN`] holds it.
fn opened_before(last: u64, now: Duration, age: Duration) -> bool {
    if last == 0 {
        return false;
    }
    now.saturating_sub(age) <= Duration::from_nanos(last - 1)
}

impl PoolConfig {
    /// The connection string with the session settings added, as every connection
    /// [`connect`] opens uses.
    ///
    /// # Errors
    ///
    /// [`sqlx::Error::Configuration`] when the URL sets `options` already and a
    /// statement timeout or read-only mode is set here too, or when the application
    /// name is not one Postgres keeps as it is.
    pub fn connection_uri(&self) -> Result<String, sqlx::Error> {
        session_uri(
            &self.uri,
            self.statement_timeout_ms,
            &self.application_name,
            self.read_only,
        )
        .map_err(|problem| sqlx::Error::Configuration(problem.into()))
    }
}

/// `uri` with each session setting added as a libpq connection parameter, so that
/// every connection the pool opens starts with them, at no extra round trip:
/// `statement_timeout` and `default_transaction_read_only` in `options`, and
/// `application_name`.
///
/// An `application_name` the URL already names is kept. `options` the URL already
/// names, with a setting here to add, is refused, rather than either one silently
/// replacing the other.
fn session_uri(
    uri: &str,
    statement_timeout_ms: u64,
    application_name: &str,
    read_only: bool,
) -> Result<String, String> {
    let mut options = Vec::new();
    if statement_timeout_ms > 0 {
        options.push(format!("-c statement_timeout={statement_timeout_ms}"));
    }
    if read_only {
        options.push("-c default_transaction_read_only=on".to_string());
    }
    let mut params = Vec::new();
    if !options.is_empty() {
        if has_param(uri, "options") {
            return Err(
                "the connection URL sets options already: set the statement timeout and \
                 read-only mode there, or here, not both"
                    .to_string(),
            );
        }
        params.push(("options", options.join(" ")));
    }
    if !application_name.is_empty() && !has_param(uri, "application_name") {
        if !is_application_name(application_name) {
            return Err(
                "an application name is ASCII letters, digits, `_`, `.`, and `-`, at most 63"
                    .to_string(),
            );
        }
        params.push(("application_name", application_name.to_string()));
    }
    if params.is_empty() {
        return Ok(uri.to_string());
    }
    let separator = if uri.contains('?') { '&' } else { '?' };
    let query: Vec<String> = params
        .iter()
        .map(|(name, value)| format!("{name}={}", percent_encode(value)))
        .collect();
    Ok(format!("{uri}{separator}{}", query.join("&")))
}

/// Whether the query of `uri` names `name`.
fn has_param(uri: &str, name: &str) -> bool {
    uri.split_once('?').is_some_and(|(_, query)| {
        query
            .split('&')
            .any(|pair| pair.split('=').next() == Some(name))
    })
}

/// Whether `name` is an application name Postgres keeps as it is: ASCII letters,
/// digits, `_`, `.`, and `-`, from 1 to 63 bytes.
fn is_application_name(name: &str) -> bool {
    (1..=63).contains(&name.len())
        && name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'.' | b'-'))
}

/// `value` with every byte but the unreserved ones percent-encoded.
fn percent_encode(value: &str) -> String {
    use std::fmt::Write as _;
    let mut encoded = String::new();
    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            encoded.push(char::from(byte));
        } else {
            let _ = write!(encoded, "%{byte:02X}");
        }
    }
    encoded
}

/// Open a pool and prove it works with one connection, with the session settings on
/// every connection.
///
/// # Errors
///
/// Fails when the settings are refused, as [`PoolConfig::connection_uri`] says, or the
/// database cannot be reached.
pub async fn connect(config: &PoolConfig) -> Result<PgPool, sqlx::Error> {
    config.options().connect(&config.connection_uri()?).await
}

/// Check that the database answers.
///
/// # Errors
///
/// Fails when it does not.
pub async fn ping(pool: &PgPool) -> Result<(), sqlx::Error> {
    sqlx::query("SELECT 1").execute(pool).await?;
    Ok(())
}

/// Where a function gets its connection: the pool, or a connection the caller
/// holds, usually an open transaction, so one function serves both.
///
/// `impl sqlx::Acquire` says the same, but its associated types stop the future
/// being `Send`, which Axum handlers and `tokio::spawn` need.
///
/// ```no_run
/// use axa_postgres_sqlx::{Db, sqlx};
///
/// async fn count(db: impl Into<Db<'_>>) -> Result<i64, sqlx::Error> {
///     let mut conn = db.into().acquire().await?;
///     sqlx::query_scalar("SELECT count(*) FROM items")
///         .fetch_one(&mut *conn)
///         .await
/// }
/// ```
pub enum Db<'a> {
    /// Take a connection from the pool for the length of the call.
    Pool(&'a PgPool),
    /// Use the caller's connection.
    Conn(&'a mut PgConnection),
}

impl<'a> From<&'a PgPool> for Db<'a> {
    fn from(pool: &'a PgPool) -> Self {
        Self::Pool(pool)
    }
}

impl<'a> From<&'a mut PgConnection> for Db<'a> {
    fn from(conn: &'a mut PgConnection) -> Self {
        Self::Conn(conn)
    }
}

impl<'a> Db<'a> {
    /// The connection to use.
    ///
    /// # Errors
    ///
    /// Fails when the pool has none to give.
    pub async fn acquire(self) -> Result<Conn<'a>, sqlx::Error> {
        match self {
            Self::Pool(pool) => Ok(Conn::Pooled(pool.acquire().await?)),
            Self::Conn(conn) => Ok(Conn::Borrowed(conn)),
        }
    }
}

/// A connection for the length of one call. It derefs to [`PgConnection`].
pub enum Conn<'a> {
    /// Taken from the pool, and given back when dropped.
    Pooled(PoolConnection<Postgres>),
    /// The caller's.
    Borrowed(&'a mut PgConnection),
}

impl Deref for Conn<'_> {
    type Target = PgConnection;

    fn deref(&self) -> &PgConnection {
        match self {
            Self::Pooled(conn) => conn,
            Self::Borrowed(conn) => conn,
        }
    }
}

impl DerefMut for Conn<'_> {
    fn deref_mut(&mut self) -> &mut PgConnection {
        match self {
            Self::Pooled(conn) => conn,
            Self::Borrowed(conn) => conn,
        }
    }
}

/// Whether an error is a violated unique constraint, which a service usually
/// reports as `409` rather than `500`.
#[must_use]
pub fn is_unique_violation(error: &sqlx::Error) -> bool {
    error
        .as_database_error()
        .is_some_and(sqlx::error::DatabaseError::is_unique_violation)
}

/// Quote a table or type name for use in SQL.
///
/// Identifiers cannot be bound as parameters, so this is the one place names
/// reach SQL as text. Only lowercase ASCII letters, digits, and underscores
/// are accepted, starting with a letter or underscore. That is stricter than
/// Postgres, and it leaves nothing for an attacker to work with.
///
/// ```
/// assert_eq!(axa_postgres_sqlx::quote_identifier("users").as_deref(), Some("\"users\""));
/// assert_eq!(axa_postgres_sqlx::quote_identifier("users; DROP TABLE x"), None);
/// ```
#[must_use]
pub fn quote_identifier(name: &str) -> Option<String> {
    let mut chars = name.chars();
    let first = chars.next()?;
    let valid = (first.is_ascii_lowercase() || first == '_')
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    valid.then(|| format!("\"{name}\""))
}

/// Quote every name, failing on the first one [`quote_identifier`] refuses.
fn quote_all<S: AsRef<str>>(names: &[S]) -> Result<Vec<String>, sqlx::Error> {
    names
        .iter()
        .map(|name| {
            quote_identifier(name.as_ref()).ok_or_else(|| {
                sqlx::Error::Protocol(format!("invalid identifier: {}", name.as_ref()))
            })
        })
        .collect()
}

/// Whether `name` is a custom setting a service may set for row-level security: two or
/// more parts of lower-case ASCII letters, digits, and underscores, joined by dots, such
/// as `app.tenant`. A name with no dot is Postgres's own, such as `role` or
/// `search_path`, which this never sets.
///
/// ```
/// assert!(axa_postgres_sqlx::is_custom_setting("app.tenant"));
/// assert!(!axa_postgres_sqlx::is_custom_setting("search_path"));
/// ```
#[must_use]
pub fn is_custom_setting(name: &str) -> bool {
    let parts: Vec<&str> = name.split('.').collect();
    name.len() <= 63
        && parts.len() >= 2
        && parts.iter().all(|part| {
            part.chars()
                .next()
                .is_some_and(|first| first.is_ascii_lowercase() || first == '_')
                && part
                    .chars()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
        })
}

/// Open a transaction with each `(name, value)` set for its length only, such as
/// `("app.tenant", tenant.as_str())` for a row-level security policy that reads
/// `current_setting('app.tenant', true)`.
///
/// Each pair is set with `set_config($1, $2, true)`: bound, never formatted into the
/// SQL, and gone when the transaction commits or rolls back, so a pooled connection
/// never carries one request's tenant into the next. Run every query that needs the
/// setting on the transaction this returns, as a query on the pool may run on another
/// connection.
///
/// ```no_run
/// # async fn example(pool: &sqlx::PgPool) -> Result<(), sqlx::Error> {
/// let mut tx = axa_postgres_sqlx::begin_with(pool, &[("app.tenant", "acme")]).await?;
/// let count: i64 = sqlx::query_scalar("SELECT count(*) FROM todos")
///     .fetch_one(&mut *tx)
///     .await?;
/// tx.commit().await?;
/// # Ok(())
/// # }
/// ```
///
/// A policy sees nothing unless the role the service connects as is subject to it: not
/// a superuser, without `BYPASSRLS`, and, if it owns the table, with
/// `FORCE ROW LEVEL SECURITY` on it.
///
/// # Errors
///
/// [`sqlx::Error::InvalidArgument`] for a name [`is_custom_setting`] refuses, before
/// anything is sent, and any error from beginning the transaction or setting a value.
pub async fn begin_with(
    pool: &PgPool,
    settings: &[(&str, &str)],
) -> Result<sqlx::Transaction<'static, Postgres>, sqlx::Error> {
    if let Some((name, _)) = settings.iter().find(|(name, _)| !is_custom_setting(name)) {
        return Err(sqlx::Error::InvalidArgument(format!(
            "not a custom setting: {name}"
        )));
    }
    let mut tx = pool.begin().await?;
    for (name, value) in settings {
        sqlx::query("SELECT set_config($1, $2, true)")
            .bind(name)
            .bind(value)
            .execute(&mut *tx)
            .await?;
    }
    Ok(tx)
}

/// Whether row-level security can keep rows apart for the role a pool connects as.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RowSecurity {
    /// The role the pool connects as.
    pub role: String,
    /// Whether that role skips every policy: a superuser, or a role with `BYPASSRLS`.
    pub bypasses: bool,
    /// The tables asked about that do not exist, have no row-level security, or lack
    /// `FORCE ROW LEVEL SECURITY`, so that their owner skips the policies.
    pub unprotected: Vec<String>,
}

impl RowSecurity {
    /// Whether the policies on every table asked about apply to the role.
    #[must_use]
    pub fn holds(&self) -> bool {
        !self.bypasses && self.unprotected.is_empty()
    }
}

/// Ask Postgres whether row-level security can apply to `pool`'s role, and whether
/// each of `tables`, such as `todos` or `app.todos`, has it enabled and forced.
///
/// A policy does nothing for a superuser or a role with `BYPASSRLS`, and nothing for a
/// table's owner unless the table has `FORCE ROW LEVEL SECURITY`. Each failure is
/// silent: every query still answers, with every tenant's rows. Call this at boot, after
/// migrating, and refuse to serve when it does not hold.
///
/// # Errors
///
/// Any error from the queries.
pub async fn row_security<S: AsRef<str>>(
    pool: &PgPool,
    tables: &[S],
) -> Result<RowSecurity, sqlx::Error> {
    let role = sqlx::query(
        "SELECT current_user::text AS role, rolsuper OR rolbypassrls AS bypasses
         FROM pg_roles WHERE rolname = current_user",
    )
    .fetch_one(pool)
    .await?;
    let mut unprotected = Vec::new();
    for table in tables {
        let table = table.as_ref();
        // Bound, and looked up with to_regclass, which takes the name as text.
        let forced: Option<bool> = sqlx::query_scalar(
            "SELECT relrowsecurity AND relforcerowsecurity FROM pg_class
             WHERE oid = to_regclass($1)",
        )
        .bind(table)
        .fetch_optional(pool)
        .await?;
        if forced != Some(true) {
            unprotected.push(table.to_string());
        }
    }
    Ok(RowSecurity {
        role: role.get("role"),
        bypasses: role.get("bypasses"),
        unprotected,
    })
}

/// Apply pending migrations. Sqlx holds a lock while it does, so services
/// booting together take turns.
///
/// # Errors
///
/// Fails when a migration fails, or an applied one no longer matches.
pub async fn migrate(pool: &PgPool, migrator: &Migrator) -> Result<(), MigrateError> {
    migrator.run(pool).await
}

/// The newest applied versions, newest first. Empty on a database that has
/// never been migrated.
async fn applied_versions(pool: &PgPool) -> Result<Vec<i64>, sqlx::Error> {
    let exists: bool = sqlx::query("SELECT to_regclass('_sqlx_migrations') IS NOT NULL AS found")
        .fetch_one(pool)
        .await?
        .try_get("found")?;
    if !exists {
        return Ok(Vec::new());
    }
    let rows =
        sqlx::query("SELECT version FROM _sqlx_migrations WHERE success ORDER BY version DESC")
            .fetch_all(pool)
            .await?;
    rows.iter().map(|row| row.try_get("version")).collect()
}

/// Revert the newest `steps` migrations. Each needs a `.down.sql` file.
///
/// # Errors
///
/// Fails on a database error or a failed down migration.
pub async fn revert(pool: &PgPool, migrator: &Migrator, steps: u32) -> Result<(), MigrateError> {
    let applied = applied_versions(pool).await?;
    let steps = usize::try_from(steps).unwrap_or(usize::MAX);
    // `undo` reverts everything newer than its target, so the target is the
    // version just past the last one to revert, or 0 to revert them all.
    let target = applied.get(steps).copied().unwrap_or(0);
    migrator.undo(pool, target).await
}

/// One migration and whether it has run.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MigrationStatus {
    /// Its version.
    pub version: i64,
    /// Its description.
    pub description: String,
    /// Whether it has been applied.
    pub applied: bool,
}

/// Every migration in `migrator`, oldest first, with whether it has run.
///
/// # Errors
///
/// Fails on a database error.
pub async fn status(
    pool: &PgPool,
    migrator: &Migrator,
) -> Result<Vec<MigrationStatus>, sqlx::Error> {
    let applied = applied_versions(pool).await?;
    Ok(migrator
        .iter()
        .filter(|migration| !migration.migration_type.is_down_migration())
        .map(|migration| MigrationStatus {
            version: migration.version,
            description: migration.description.to_string(),
            applied: applied.contains(&migration.version),
        })
        .collect())
}

/// The names of the migrations in `migrator` not yet applied, in order, each as
/// `version_description`.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending(pool: &PgPool, migrator: &Migrator) -> Result<Vec<String>, sqlx::Error> {
    Ok(status(pool, migrator)
        .await?
        .into_iter()
        .filter(|migration| !migration.applied)
        .map(|migration| format!("{}_{}", migration.version, migration.description))
        .collect())
}

/// A migration of statements that cannot run in a transaction, such as
/// `CREATE INDEX CONCURRENTLY`, which sqlx's migrator runs each file in. Name each one
/// once and never change it: its name is what marks it done.
///
/// A statement that fails partway can leave something behind, as a failed
/// `CREATE INDEX CONCURRENTLY` leaves an invalid index, so begin with what clears it:
///
/// ```
/// use axa_postgres_sqlx::Background;
///
/// const NOTES_BY_ITEM: Background = Background {
///     name: "2026_11_notes_by_item",
///     statements: &[
///         "DROP INDEX CONCURRENTLY IF EXISTS notes_by_item",
///         "CREATE INDEX CONCURRENTLY notes_by_item ON notes (item_id)",
///     ],
/// };
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Background {
    /// Its name, 1 to 200 characters with no control characters, recorded once it has
    /// run.
    pub name: &'static str,
    /// Its statements, each run alone, outside any transaction, in order.
    pub statements: &'static [&'static str],
}

/// The table background migrations are recorded in.
pub const BACKGROUND_TABLE: &str = "axa_background_migrations";

/// The advisory lock one process holds while it runs background migrations.
pub const BACKGROUND_LOCK: i64 = 0x6178_615f_6267_6d00;

const BACKGROUND_SETUP: &str = "CREATE TABLE IF NOT EXISTS axa_background_migrations (
    name TEXT PRIMARY KEY,
    finished_at TIMESTAMPTZ NOT NULL DEFAULT now()
)";

fn check_background(migrations: &[Background]) -> Result<(), sqlx::Error> {
    let mut names = std::collections::HashSet::new();
    for migration in migrations {
        let name = migration.name;
        if name.is_empty() || name.chars().count() > 200 || name.chars().any(char::is_control) {
            return Err(sqlx::Error::Configuration(
                "a background migration's name must be 1 to 200 characters with no control characters".into(),
            ));
        }
        if !names.insert(name) {
            return Err(sqlx::Error::Configuration(
                format!("the background migration {name} is named twice").into(),
            ));
        }
    }
    Ok(())
}

async fn background_done(
    connection: &mut sqlx::PgConnection,
) -> Result<std::collections::HashSet<String>, sqlx::Error> {
    let exists: bool =
        sqlx::query_scalar("SELECT to_regclass('axa_background_migrations') IS NOT NULL")
            .fetch_one(&mut *connection)
            .await?;
    if !exists {
        return Ok(std::collections::HashSet::new());
    }
    let names: Vec<String> = sqlx::query_scalar("SELECT name FROM axa_background_migrations")
        .fetch_all(&mut *connection)
        .await?;
    Ok(names.into_iter().collect())
}

/// Run each of `migrations` not yet recorded, in order, outside any transaction,
/// recording each once all its statements have run. One process at a time holds
/// [`BACKGROUND_LOCK`], so replicas booting together do not run one twice: a process
/// that cannot take it answers `None` at once, and the one that holds it answers the
/// names it ran. A failure stops the run, leaves that migration unrecorded, so the next
/// run tries it again, and releases the lock.
///
/// # Errors
///
/// Fails on a name that is empty, too long, or used twice, on a database error, or on
/// a statement that fails.
pub async fn run_background(
    pool: &PgPool,
    migrations: &[Background],
) -> Result<Option<Vec<String>>, sqlx::Error> {
    check_background(migrations)?;
    let mut connection = pool.acquire().await?;
    let locked: bool = sqlx::query_scalar("SELECT pg_try_advisory_lock($1)")
        .bind(BACKGROUND_LOCK)
        .fetch_one(&mut *connection)
        .await?;
    if !locked {
        return Ok(None);
    }
    let ran = run_background_locked(&mut connection, migrations).await;
    let unlocked = sqlx::query("SELECT pg_advisory_unlock($1)")
        .bind(BACKGROUND_LOCK)
        .execute(&mut *connection)
        .await;
    if unlocked.is_err() {
        // The lock goes with the connection, so do not hand it back to the pool.
        connection.detach();
    }
    ran.map(Some)
}

async fn run_background_locked(
    connection: &mut sqlx::PgConnection,
    migrations: &[Background],
) -> Result<Vec<String>, sqlx::Error> {
    sqlx::query(BACKGROUND_SETUP)
        .execute(&mut *connection)
        .await?;
    let done = background_done(connection).await?;
    let mut ran = Vec::new();
    for migration in migrations.iter().filter(|m| !done.contains(m.name)) {
        for statement in migration.statements {
            // `&'static`, so written in the code and never built from input.
            sqlx::raw_sql(*statement).execute(&mut *connection).await?;
        }
        sqlx::query("INSERT INTO axa_background_migrations (name) VALUES ($1)")
            .bind(migration.name)
            .execute(&mut *connection)
            .await?;
        ran.push(migration.name.to_string());
    }
    Ok(ran)
}

/// The names of `migrations` not yet recorded, in order, for
/// `Checks::migrations`.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending_background(
    pool: &PgPool,
    migrations: &[Background],
) -> Result<Vec<String>, sqlx::Error> {
    let mut connection = pool.acquire().await?;
    let done = background_done(&mut connection).await?;
    Ok(migrations
        .iter()
        .filter(|migration| !done.contains(migration.name))
        .map(|migration| migration.name.to_string())
        .collect())
}

/// Empty `tables`, restarting their sequences. Each name goes through
/// [`quote_identifier`].
///
/// # Errors
///
/// Fails on an invalid name or a database error.
pub async fn truncate<S: AsRef<str>>(pool: &PgPool, tables: &[S]) -> Result<(), sqlx::Error> {
    if tables.is_empty() {
        return Ok(());
    }
    let tables = quote_all(tables)?.join(", ");
    let sql = format!("TRUNCATE {tables} RESTART IDENTITY CASCADE");
    sqlx::query(AssertSqlSafe(sql)).execute(pool).await?;
    Ok(())
}

/// Drop every table and enum type in `public`, then migrate from nothing.
/// This gives each test an empty schema, whatever tables it touched.
///
/// **This destroys all data.** It exists for tests, and a service must never
/// reach it outside the `test` environment.
///
/// It drops tables and types by name rather than dropping the schema, because
/// `DROP SCHEMA public CASCADE` would also remove the extensions a database
/// was prepared with, such as `citext`. Functions are left in place, so a
/// migration that creates one should use `CREATE OR REPLACE`.
///
/// # Errors
///
/// Fails on a database error, or a name [`quote_identifier`] refuses.
pub async fn dangerously_recreate(pool: &PgPool, migrator: &Migrator) -> Result<(), MigrateError> {
    let tables: Vec<String> =
        sqlx::query("SELECT tablename::text AS name FROM pg_tables WHERE schemaname = 'public'")
            .fetch_all(pool)
            .await?
            .iter()
            .map(|row| row.try_get("name"))
            .collect::<Result<_, _>>()?;
    // Types owned by an extension (`deptype = 'e'`) belong to that extension.
    let types: Vec<String> = sqlx::query(
        "SELECT t.typname::text AS name FROM pg_type t
         JOIN pg_namespace n ON n.oid = t.typnamespace
         WHERE t.typtype = 'e' AND n.nspname = 'public'
           AND NOT EXISTS (
               SELECT 1 FROM pg_depend d WHERE d.objid = t.oid AND d.deptype = 'e'
           )",
    )
    .fetch_all(pool)
    .await?
    .iter()
    .map(|row| row.try_get("name"))
    .collect::<Result<_, _>>()?;

    if !tables.is_empty() {
        let names = quote_all(&tables)?.join(", ");
        let sql = format!("DROP TABLE {names} CASCADE");
        sqlx::query(AssertSqlSafe(sql)).execute(pool).await?;
    }
    for name in quote_all(&types)? {
        let sql = format!("DROP TYPE {name} CASCADE");
        sqlx::query(AssertSqlSafe(sql)).execute(pool).await?;
    }
    migrate(pool, migrator).await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn debug_text_leaves_out_the_connection_string() {
        let text = format!("{:?}", PoolConfig::new("postgres://me:hunter2@db/app"));
        assert!(!text.contains("hunter2"), "{text}");
        assert!(text.contains("max_connections"), "{text}");
    }

    #[test]
    fn session_settings_become_connection_parameters() {
        let base = "postgres://app@db/app";
        assert_eq!(session_uri(base, 0, "", false).unwrap(), base);
        assert_eq!(
            session_uri(base, 5000, "orders", true).unwrap(),
            "postgres://app@db/app?options=-c%20statement_timeout%3D5000%20-c%20\
             default_transaction_read_only%3Don&application_name=orders"
        );
        assert_eq!(
            session_uri("postgres://db/app?sslmode=require", 0, "orders", false).unwrap(),
            "postgres://db/app?sslmode=require&application_name=orders"
        );
    }

    #[test]
    fn a_url_that_sets_them_already_is_kept_or_refused() {
        // Its own application name wins.
        let named = "postgres://db/app?application_name=mine";
        assert_eq!(session_uri(named, 0, "orders", false).unwrap(), named);
        // Its own options and a setting here would replace one another, so neither does.
        let with_options = "postgres://db/app?options=-c%20work_mem%3D64MB";
        assert!(session_uri(with_options, 5000, "", false).is_err());
        assert!(session_uri(with_options, 0, "", true).is_err());
        assert_eq!(
            session_uri(with_options, 0, "", false).unwrap(),
            with_options
        );
        for name in ["has space", "a&b=c", "é", &"a".repeat(64)] {
            assert!(
                session_uri("postgres://db/app", 0, name, false).is_err(),
                "{name}"
            );
        }
    }

    #[test]
    fn a_connection_is_retired_only_if_opened_by_the_last_stale_plan() {
        let second = Duration::from_secs(1);
        // Never a stale plan: nothing is retired.
        assert!(!opened_before(0, 10 * second, 9 * second));
        // A stale plan at 5s: a connection opened at 1s or 5s goes, one at 6s stays.
        let at_five = 5_000_000_000 + 1;
        assert!(opened_before(at_five, 10 * second, 9 * second));
        assert!(opened_before(at_five, 10 * second, 5 * second));
        assert!(!opened_before(at_five, 10 * second, 4 * second));
        // An age past the epoch is opened before anything.
        assert!(opened_before(at_five, second, 9 * second));
    }

    #[test]
    fn only_custom_settings_can_be_set() {
        for name in [
            "app.tenant",
            "app.user_id",
            "my_app.tenant_2",
            "a.b.c",
            "_x.y",
        ] {
            assert!(is_custom_setting(name), "{name}");
        }
        for name in [
            "role",
            "search_path",
            "session_authorization",
            "app.",
            ".tenant",
            "app..tenant",
            "App.Tenant",
            "app.tenant; RESET ROLE",
            "app.2fa",
            "",
        ] {
            assert!(!is_custom_setting(name), "{name}");
        }
        assert!(!is_custom_setting(&format!("app.{}", "a".repeat(60))));
    }

    #[tokio::test]
    async fn a_refused_setting_name_fails_before_anything_is_sent() {
        // This pool would fail to connect, so an error that is not InvalidArgument
        // would mean something was sent.
        let pool = PgPoolOptions::new()
            .connect_lazy("postgres://nobody@127.0.0.1:1/none")
            .unwrap();
        let error = begin_with(&pool, &[("app.tenant", "acme"), ("role", "postgres")])
            .await
            .unwrap_err();
        assert!(
            matches!(&error, sqlx::Error::InvalidArgument(text) if text.contains("role")),
            "{error:?}"
        );
    }

    #[test]
    fn identifiers_are_quoted() {
        assert_eq!(quote_identifier("users").as_deref(), Some("\"users\""));
        assert_eq!(quote_identifier("_a1").as_deref(), Some("\"_a1\""));
    }

    #[test]
    fn unsafe_identifiers_are_refused() {
        for name in [
            "", "1users", "Users", "a b", "a\"b", "a;b", "a.b", "users--", "é",
        ] {
            assert_eq!(quote_identifier(name), None, "{name:?}");
        }
    }

    #[test]
    fn quote_all_fails_on_any_bad_name() {
        assert!(quote_all(&["good", "also_good"]).is_ok());
        assert!(quote_all(&["good", "bad name"]).is_err());
    }

    #[test]
    fn pool_settings_reach_the_options() {
        let config = PoolConfig {
            min_connections: 2,
            max_connections: 7,
            connect_timeout_ms: 1_500,
            idle_timeout_ms: 9_000,
            ..PoolConfig::new("postgres://x")
        };
        let options = config.options();
        assert_eq!(options.get_min_connections(), 2);
        assert_eq!(options.get_max_connections(), 7);
        assert_eq!(options.get_acquire_timeout(), Duration::from_millis(1_500));
        assert_eq!(options.get_idle_timeout(), Some(Duration::from_secs(9)));
    }

    #[test]
    fn errors_that_are_not_from_the_database_are_not_unique_violations() {
        assert!(!is_unique_violation(&sqlx::Error::RowNotFound));
    }
}

/// `quote_identifier` over generated names: it quotes exactly the names of lowercase
/// letters, digits, and underscores that start with a letter or underscore, and nothing
/// else, so no name it passes can end the identifier or start another statement.
#[cfg(test)]
mod properties {
    use proptest::prelude::*;

    use super::quote_identifier;

    proptest! {
        #[test]
        fn a_safe_name_is_quoted_as_it_is(name in "[a-z_][a-z0-9_]{0,62}") {
            prop_assert_eq!(quote_identifier(&name), Some(format!("\"{name}\"")));
        }

        #[test]
        fn any_other_name_is_refused(name in "\\PC{0,40}") {
            let safe = name.chars().next().is_some_and(|c| c.is_ascii_lowercase() || c == '_')
                && name.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
            prop_assert_eq!(quote_identifier(&name).is_some(), safe);
            if let Some(quoted) = quote_identifier(&name) {
                prop_assert_eq!(quoted.matches('"').count(), 2);
            }
        }
    }
}

//! Toasty connections, migrations, and test resets for Axum services, on
//! PostgreSQL.
//!
//! This crate has the same shape as `axa-postgres-sqlx`, `axa-postgres-seaorm`, and `axa-postgres-diesel`: a
//! [`Pool`], a [`PoolConfig`], [`connect`], [`ping`], [`migrate`], [`pending`],
//! [`truncate`], [`dangerously_recreate`], [`is_unique_violation`], and
//! [`quote_identifier`]. `axa`'s `postgres-toasty` feature re-exports it as `axa::postgres_toasty`, and
//! makes [`Pool`] the service's `AppContext::db` when no other database feature is on.
//!
//! ```no_run
//! # async fn example() -> toasty::Result<()> {
//! #[derive(Debug, toasty::Model)]
//! struct User {
//!     #[key]
//!     #[auto]
//!     id: u64,
//!     name: String,
//! }
//!
//! let config = axa_postgres_toasty::PoolConfig::new("postgresql://localhost/app");
//! let db = axa_postgres_toasty::connect(&config, toasty::models!(User)).await?;
//! axa_postgres_toasty::ping(&db).await?;
//! # Ok(())
//! # }
//! ```
//!
//! Toasty migrations go forward only: a [`MigrationSet`] has no down steps, so there
//! is no `revert`. Generate migrations with `toasty-cli`, embed them with
//! [`toasty::embed_migrations!`], and apply them with [`migrate`].

use std::{
    borrow::Cow,
    future::Future,
    pin::Pin,
    sync::{
        Arc, OnceLock,
        atomic::{AtomicU64, Ordering},
    },
    time::{Duration, Instant},
};

pub use toasty;
use toasty::db::{Capability, ConnectContext, Driver};
use toasty::{Db, ModelSet, Transaction, migration::MigrationSet};
use toasty_core::{
    driver::{Connection, ExecResponse, Operation},
    schema::{
        Schema,
        db::{AppliedMigration, Migration},
        diff,
    },
    stmt::{Type, Value},
};

/// The handle a service holds: Toasty's [`Db`], which owns a connection pool.
pub type Pool = Db;

/// What this crate's functions return on failure.
pub type Error = toasty::Error;

/// The pool's settings. The URL is left out of its `Debug` text, as it may hold a
/// password.
#[derive(Clone, PartialEq, Eq)]
pub struct PoolConfig {
    /// The connection URL, such as `postgresql://user:password@host/database`.
    pub uri: String,
    /// The most connections the pool opens.
    pub max_connections: u32,
    /// How long to wait to open a connection, or for a free one, in milliseconds.
    pub connect_timeout_ms: u64,
    /// How long a connection may sit unused before it is closed, in milliseconds.
    pub idle_timeout_ms: u64,
    /// Postgres's `statement_timeout` on every connection, in milliseconds. `0` sets
    /// none.
    pub statement_timeout_ms: u64,
    /// Postgres's `application_name` on every connection, so `pg_stat_activity` says
    /// which service a query came from. Empty sets none.
    pub application_name: String,
    /// Open every transaction read-only, as for a read replica or a reporting
    /// service, so that a write is refused by the database.
    pub read_only: bool,
}

impl std::fmt::Debug for PoolConfig {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PoolConfig")
            .field("max_connections", &self.max_connections)
            .field("connect_timeout_ms", &self.connect_timeout_ms)
            .field("idle_timeout_ms", &self.idle_timeout_ms)
            .field("statement_timeout_ms", &self.statement_timeout_ms)
            .field("application_name", &self.application_name)
            .field("read_only", &self.read_only)
            .finish_non_exhaustive()
    }
}

impl PoolConfig {
    /// Settings for `uri`, with the same defaults as `axa-postgres-sqlx`: ten connections, a
    /// five-second wait, and ten minutes idle.
    #[must_use]
    pub fn new(uri: impl Into<String>) -> Self {
        Self {
            uri: uri.into(),
            max_connections: 10,
            connect_timeout_ms: 5_000,
            idle_timeout_ms: 600_000,
            statement_timeout_ms: 0,
            application_name: String::new(),
            read_only: false,
        }
    }

    /// A Toasty builder with these settings and `models`, ready to connect.
    #[must_use]
    pub fn builder(&self, models: ModelSet) -> toasty::db::Builder {
        let wait = Some(Duration::from_millis(self.connect_timeout_ms));
        let mut builder = Db::builder();
        builder
            .models(models)
            .max_pool_size(usize::try_from(self.max_connections).unwrap_or(usize::MAX))
            .pool_wait_timeout(wait)
            .pool_create_timeout(wait)
            .pool_max_connection_idle_time(Some(Duration::from_millis(self.idle_timeout_ms)));
        builder
    }
}

impl PoolConfig {
    /// The connection string with the session settings added, as every connection
    /// [`connect`] opens uses.
    ///
    /// # Errors
    ///
    /// When the URL sets `options` already and a statement timeout or read-only mode
    /// is set here too, or when the application name is not one Postgres keeps as it
    /// is.
    pub fn connection_uri(&self) -> Result<String, Error> {
        session_uri(
            &self.uri,
            self.statement_timeout_ms,
            &self.application_name,
            self.read_only,
        )
        .map_err(Error::invalid_connection_url)
    }
}

/// `uri` with each session setting added as a libpq connection parameter, so that
/// every connection the pool opens starts with them, at no extra round trip:
/// `statement_timeout` and `default_transaction_read_only` in `options`, and
/// `application_name`.
///
/// An `application_name` the URL already names is kept. `options` the URL already
/// names, with a setting here to add, is refused, rather than either one silently
/// replacing the other.
fn session_uri(
    uri: &str,
    statement_timeout_ms: u64,
    application_name: &str,
    read_only: bool,
) -> Result<String, String> {
    let mut options = Vec::new();
    if statement_timeout_ms > 0 {
        options.push(format!("-c statement_timeout={statement_timeout_ms}"));
    }
    if read_only {
        options.push("-c default_transaction_read_only=on".to_string());
    }
    let mut params = Vec::new();
    if !options.is_empty() {
        if has_param(uri, "options") {
            return Err(
                "the connection URL sets options already: set the statement timeout and \
                 read-only mode there, or here, not both"
                    .to_string(),
            );
        }
        params.push(("options", options.join(" ")));
    }
    if !application_name.is_empty() && !has_param(uri, "application_name") {
        if !is_application_name(application_name) {
            return Err(
                "an application name is ASCII letters, digits, `_`, `.`, and `-`, at most 63"
                    .to_string(),
            );
        }
        params.push(("application_name", application_name.to_string()));
    }
    if params.is_empty() {
        return Ok(uri.to_string());
    }
    let separator = if uri.contains('?') { '&' } else { '?' };
    let query: Vec<String> = params
        .iter()
        .map(|(name, value)| format!("{name}={}", percent_encode(value)))
        .collect();
    Ok(format!("{uri}{separator}{}", query.join("&")))
}

/// Whether the query of `uri` names `name`.
fn has_param(uri: &str, name: &str) -> bool {
    uri.split_once('?').is_some_and(|(_, query)| {
        query
            .split('&')
            .any(|pair| pair.split('=').next() == Some(name))
    })
}

/// Whether `name` is an application name Postgres keeps as it is: ASCII letters,
/// digits, `_`, `.`, and `-`, from 1 to 63 bytes.
fn is_application_name(name: &str) -> bool {
    (1..=63).contains(&name.len())
        && name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'.' | b'-'))
}

/// `value` with every byte but the unreserved ones percent-encoded.
fn percent_encode(value: &str) -> String {
    use std::fmt::Write as _;
    let mut encoded = String::new();
    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            encoded.push(char::from(byte));
        } else {
            let _ = write!(encoded, "%{byte:02X}");
        }
    }
    encoded
}

/// Connect to the database for `models`, and check that it answers.
///
/// # Errors
///
/// Fails when the URL is not one Toasty reads, or the database cannot be reached.
pub async fn connect(config: &PoolConfig, models: ModelSet) -> Result<Pool, Error> {
    let driver = Retiring(toasty::db::Connect::new(&config.connection_uri()?).await?);
    let db = config.builder(models).build(driver).await?;
    ping(&db).await?;
    Ok(db)
}

/// A future a driver returns, as `async_trait` writes it.
type Boxed<'a, T> = Pin<Box<dyn Future<Output = toasty::Result<T>> + Send + 'a>>;

/// Toasty's driver, with each connection retired once a stale plan is seen on it, or
/// when it was opened at or before the last stale plan.
#[derive(Debug)]
struct Retiring(toasty::db::Connect);

/// A connection, and when it was opened.
#[derive(Debug)]
struct RetiringConnection {
    inner: Box<dyn Connection>,
    opened: Instant,
}

impl Driver for Retiring {
    fn url(&self) -> Cow<'_, str> {
        self.0.url()
    }

    fn capability(&self) -> &'static Capability {
        self.0.capability()
    }

    fn connect<'a, 'b, 'c>(&'a self, cx: &'b ConnectContext) -> Boxed<'c, Box<dyn Connection>>
    where
        'a: 'c,
        'b: 'c,
        Self: 'c,
    {
        Box::pin(async move {
            let inner = self.0.connect(cx).await?;
            Ok(Box::new(RetiringConnection {
                inner,
                opened: Instant::now(),
            }) as Box<dyn Connection>)
        })
    }

    fn max_connections(&self) -> Option<usize> {
        self.0.max_connections()
    }

    fn generate_migration(&self, schema_diff: &diff::Schema<'_>) -> Migration {
        self.0.generate_migration(schema_diff)
    }

    fn reset_db<'a, 'c>(&'a self) -> Boxed<'c, ()>
    where
        'a: 'c,
        Self: 'c,
    {
        self.0.reset_db()
    }
}

impl Connection for RetiringConnection {
    fn exec<'a, 'b, 'c>(
        &'a mut self,
        schema: &'b Arc<Schema>,
        plan: Operation,
    ) -> Boxed<'c, ExecResponse>
    where
        'a: 'c,
        'b: 'c,
        Self: 'c,
    {
        Box::pin(async move {
            let response = self.inner.exec(schema, plan).await;
            // The pool asks `is_valid` after every operation, so this one goes now.
            if let Err(error) = &response {
                note_stale_plan(error);
            }
            response
        })
    }

    fn is_valid(&self) -> bool {
        self.inner.is_valid() && !opened_before_last_stale_plan(self.opened)
    }

    fn ping<'a, 'c>(&'a mut self) -> Boxed<'c, ()>
    where
        'a: 'c,
        Self: 'c,
    {
        if opened_before_last_stale_plan(self.opened) {
            return Box::pin(async {
                Err(toasty::Error::connection_lost(std::io::Error::other(
                    "opened before a stale plan",
                )))
            });
        }
        self.inner.ping()
    }

    fn push_schema<'a, 'b, 'c>(&'a mut self, schema: &'b Schema) -> Boxed<'c, ()>
    where
        'a: 'c,
        'b: 'c,
        Self: 'c,
    {
        self.inner.push_schema(schema)
    }

    fn applied_migrations<'a, 'c>(&'a mut self) -> Boxed<'c, Vec<AppliedMigration>>
    where
        'a: 'c,
        Self: 'c,
    {
        self.inner.applied_migrations()
    }

    fn apply_migration<'a, 'b, 'm, 'c>(
        &'a mut self,
        id: u64,
        name: &'b str,
        migration: &'m Migration,
    ) -> Boxed<'c, ()>
    where
        'a: 'c,
        'b: 'c,
        'm: 'c,
        Self: 'c,
    {
        self.inner.apply_migration(id, name, migration)
    }
}

/// When this process first needed a clock for stale plans.
static EPOCH: OnceLock<Instant> = OnceLock::new();

/// Nanoseconds after [`EPOCH`] that a stale plan was last seen, plus one, or `0` for
/// never.
static LAST_STALE_PLAN: AtomicU64 = AtomicU64::new(0);

fn epoch() -> Instant {
    *EPOCH.get_or_init(Instant::now)
}

/// Whether `error` is Postgres refusing a statement this connection prepared before a
/// migration changed what it returns: SQLSTATE `0A000` with "cached plan must not
/// change result type". Each pooled connection that cached the statement fails so
/// once, and a fresh connection does not.
#[must_use]
pub fn is_stale_plan(error: &Error) -> bool {
    let mut source: Option<&(dyn std::error::Error + 'static)> = Some(error);
    while let Some(current) = source {
        if let Some(postgres) = current.downcast_ref::<tokio_postgres::Error>() {
            return postgres.as_db_error().is_some_and(|error| {
                error.code().code() == "0A000"
                    && error
                        .message()
                        .contains("cached plan must not change result type")
            });
        }
        source = current.source();
    }
    false
}

/// Record `error` if it is a stale plan, so that every connection opened before now is
/// retired, from every pool [`connect`] opened in this process. Returns whether it
/// was. A pool from [`connect`] records each error itself, so a service needs nothing
/// more: the connection that failed goes at once, and each other one opened before
/// it goes when it is next pinged, or after its next operation.
pub fn note_stale_plan(error: &Error) -> bool {
    if !is_stale_plan(error) {
        return false;
    }
    let since = u64::try_from(epoch().elapsed().as_nanos()).unwrap_or(u64::MAX - 1);
    LAST_STALE_PLAN.fetch_max(since.saturating_add(1), Ordering::SeqCst);
    true
}

/// Whether a connection opened at `opened` was opened at or before the last stale
/// plan.
fn opened_before_last_stale_plan(opened: Instant) -> bool {
    opened_before(
        LAST_STALE_PLAN.load(Ordering::SeqCst),
        opened.saturating_duration_since(epoch()),
    )
}

/// Whether a connection opened at `opened` since [`EPOCH`] was opened at or before
/// `last`, as [`LAST_STALE_PLAN`] holds it. One opened before the epoch counts as
/// opened at it.
fn opened_before(last: u64, opened: Duration) -> bool {
    if last == 0 {
        return false;
    }
    opened <= Duration::from_nanos(last - 1)
}

/// Check the database connection.
///
/// # Errors
///
/// Fails when the database does not answer.
pub async fn ping(pool: &Pool) -> Result<(), Error> {
    let mut db = pool.clone();
    toasty::sql::query("SELECT 1").exec(&mut db).await?;
    Ok(())
}

/// Apply every migration in `migrations` not yet applied, in order, returning how
/// many were applied.
///
/// # Errors
///
/// Fails on a database error, and then no later migration is tried.
pub async fn migrate(pool: &Pool, migrations: &MigrationSet) -> Result<usize, Error> {
    Ok(migrations.apply(pool).await?.applied())
}

/// The ids Toasty has recorded as applied, from its `__toasty_migrations` table.
async fn applied_ids(pool: &Pool) -> Result<Vec<u64>, Error> {
    let mut db = pool.clone();
    let found = toasty::sql::query(
        "SELECT count(*) FROM pg_tables
         WHERE schemaname = current_schema() AND tablename = '__toasty_migrations'",
    )
    .column_types([Type::I64])
    .exec(&mut db)
    .await?;
    if first_i64(&found).unwrap_or(0) == 0 {
        return Ok(Vec::new());
    }
    let rows = toasty::sql::query("SELECT id FROM __toasty_migrations")
        .column_types([Type::I64])
        .exec(&mut db)
        .await?;
    Ok(rows
        .iter()
        .filter_map(|row| first_i64(std::slice::from_ref(row)))
        .filter_map(|id| u64::try_from(id).ok())
        .collect())
}

/// The first column of the first row, as an integer.
fn first_i64(rows: &[Value]) -> Option<i64> {
    match rows.first()? {
        Value::Record(record) => match record.fields.first()? {
            Value::I64(value) => Some(*value),
            _ => None,
        },
        _ => None,
    }
}

/// The names of the migrations in `migrations` not yet applied, in order.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending(pool: &Pool, migrations: &MigrationSet) -> Result<Vec<String>, Error> {
    let applied = applied_ids(pool).await?;
    Ok(migrations
        .migrations()
        .iter()
        .filter(|migration| !applied.contains(&migration.id()))
        .map(|migration| migration.name().to_string())
        .collect())
}

/// The `SQLSTATE` code Postgres answered with, such as `23505` for a unique
/// violation, when `error` came from the database. Toasty names only a few kinds of
/// database error itself, so the code is read from the driver's error.
#[must_use]
pub fn sql_state(error: &Error) -> Option<&str> {
    let mut source: Option<&(dyn std::error::Error + 'static)> = Some(error);
    while let Some(current) = source {
        if let Some(postgres) = current.downcast_ref::<tokio_postgres::Error>() {
            return postgres.code().map(tokio_postgres::error::SqlState::code);
        }
        source = current.source();
    }
    None
}

/// Whether `error` is the database refusing a duplicate under a unique constraint.
#[must_use]
pub fn is_unique_violation(error: &Error) -> bool {
    sql_state(error) == Some("23505")
}

/// `name` in double quotes, when it is a plain lower-case identifier: a letter or
/// `_`, then letters, digits, and `_`. Anything else is refused, so it cannot carry
/// SQL.
#[must_use]
pub fn quote_identifier(name: &str) -> Option<String> {
    let mut chars = name.chars();
    let first = chars.next()?;
    let valid = (first.is_ascii_lowercase() || first == '_')
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    valid.then(|| format!("\"{name}\""))
}

fn quote_all<S: AsRef<str>>(names: &[S]) -> Result<Vec<String>, Error> {
    names
        .iter()
        .map(|name| {
            quote_identifier(name.as_ref()).ok_or_else(|| {
                toasty::Error::invalid_statement(format!("invalid identifier: {}", name.as_ref()))
            })
        })
        .collect()
}

/// Whether `name` is a custom setting a service may set for row-level security: two or
/// more parts of lower-case ASCII letters, digits, and underscores, joined by dots, such
/// as `app.tenant`. A name with no dot is Postgres's own, such as `role` or
/// `search_path`, which this never sets.
///
/// ```
/// assert!(axa_postgres_toasty::is_custom_setting("app.tenant"));
/// assert!(!axa_postgres_toasty::is_custom_setting("search_path"));
/// ```
#[must_use]
pub fn is_custom_setting(name: &str) -> bool {
    let parts: Vec<&str> = name.split('.').collect();
    name.len() <= 63
        && parts.len() >= 2
        && parts.iter().all(|part| {
            part.chars()
                .next()
                .is_some_and(|first| first.is_ascii_lowercase() || first == '_')
                && part
                    .chars()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
        })
}

/// Open a transaction with each `(name, value)` set for its length only, such as
/// `("app.tenant", tenant.as_str())` for a row-level security policy that reads
/// `current_setting('app.tenant', true)`.
///
/// Each pair is set with `set_config($1, $2, true)`: bound, never formatted into the
/// SQL, and gone when the transaction commits or rolls back, so a pooled connection
/// never carries one request's tenant into the next. A Toasty transaction holds one
/// connection, so run every query that needs the setting on the transaction this
/// returns. Clone the `Db` first if a second handle is needed meanwhile.
///
/// A policy sees nothing unless the role the service connects as is subject to it: not
/// a superuser, without `BYPASSRLS`, and, if it owns the table, with
/// `FORCE ROW LEVEL SECURITY` on it. [`row_security`] checks.
///
/// # Errors
///
/// An invalid-statement error for a name [`is_custom_setting`] refuses, before
/// anything is sent, and any error from beginning the transaction or setting a value.
pub async fn begin_with<'a>(
    db: &'a mut Db,
    settings: &[(&str, &str)],
) -> Result<Transaction<'a>, Error> {
    if let Some((name, _)) = settings.iter().find(|(name, _)| !is_custom_setting(name)) {
        return Err(Error::invalid_statement(format!(
            "not a custom setting: {name}"
        )));
    }
    let mut tx = db.transaction().await?;
    for (name, value) in settings {
        toasty::sql::query("SELECT set_config($1, $2, true)")
            .bind(*name)
            .bind(*value)
            .exec(&mut tx)
            .await?;
    }
    Ok(tx)
}

/// Whether row-level security can keep rows apart for the role a pool connects as.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RowSecurity {
    /// The role the pool connects as.
    pub role: String,
    /// Whether that role skips every policy: a superuser, or a role with `BYPASSRLS`.
    pub bypasses: bool,
    /// The tables asked about that do not exist, have no row-level security, or lack
    /// `FORCE ROW LEVEL SECURITY`, so that their owner skips the policies.
    pub unprotected: Vec<String>,
}

impl RowSecurity {
    /// Whether the policies on every table asked about apply to the role.
    #[must_use]
    pub fn holds(&self) -> bool {
        !self.bypasses && self.unprotected.is_empty()
    }
}

/// The fields of the first row a query returned.
fn first_record(rows: &[Value]) -> Option<&[Value]> {
    match rows.first()? {
        Value::Record(record) => Some(&record.fields),
        _ => None,
    }
}

/// Ask Postgres whether row-level security can apply to `pool`'s role, and whether
/// each of `tables`, such as `todos` or `app.todos`, has it enabled and forced. Call it
/// at boot, after migrating, and refuse to serve when it does not hold.
///
/// # Errors
///
/// Any error from the queries.
pub async fn row_security<S: AsRef<str>>(pool: &Pool, tables: &[S]) -> Result<RowSecurity, Error> {
    let mut db = pool.clone();
    let rows = toasty::sql::query(
        "SELECT current_user::text AS role, rolsuper OR rolbypassrls AS bypasses
         FROM pg_roles WHERE rolname = current_user",
    )
    .column_types([Type::String, Type::Bool])
    .exec(&mut db)
    .await?;
    let (role, bypasses) = match first_record(&rows) {
        Some([Value::String(role), Value::Bool(bypasses)]) => (role.clone(), *bypasses),
        _ => return Err(Error::invalid_result("no row for the current role")),
    };
    let mut unprotected = Vec::new();
    for table in tables {
        let table = table.as_ref();
        let rows = toasty::sql::query(
            "SELECT relrowsecurity AND relforcerowsecurity AS forced FROM pg_class
             WHERE oid = to_regclass($1)",
        )
        .bind(table)
        .column_types([Type::Bool])
        .exec(&mut db)
        .await?;
        if !matches!(first_record(&rows), Some([Value::Bool(true)])) {
            unprotected.push(table.to_string());
        }
    }
    Ok(RowSecurity {
        role,
        bypasses,
        unprotected,
    })
}

/// Empty `tables` and restart their identities, for a test. Every name must be a
/// plain lower-case identifier.
///
/// # Errors
///
/// Fails on a database error, or a name that is not a plain identifier, before
/// anything is emptied.
pub async fn truncate<S: AsRef<str>>(pool: &Pool, tables: &[S]) -> Result<(), Error> {
    if tables.is_empty() {
        return Ok(());
    }
    let tables = quote_all(tables)?.join(", ");
    let mut db = pool.clone();
    toasty::sql::statement(format!("TRUNCATE {tables} RESTART IDENTITY CASCADE"))
        .exec(&mut db)
        .await?;
    Ok(())
}

/// Drop every table in the `public` schema, Toasty's record of migrations among
/// them, then apply `migrations` from the start. This destroys data: `axa::cli`
/// allows it only in development and test, and only when confirmed.
///
/// # Errors
///
/// Fails on a database error.
pub async fn dangerously_recreate(pool: &Pool, migrations: &MigrationSet) -> Result<(), Error> {
    let mut db = pool.clone();
    let rows =
        toasty::sql::query("SELECT tablename::text FROM pg_tables WHERE schemaname = 'public'")
            .column_types([Type::String])
            .exec(&mut db)
            .await?;
    let tables: Vec<String> = rows
        .iter()
        .filter_map(|row| match row {
            Value::Record(record) => match record.fields.first() {
                Some(Value::String(name)) => Some(name.clone()),
                _ => None,
            },
            _ => None,
        })
        .collect();
    if !tables.is_empty() {
        let names = quote_all(&tables)?.join(", ");
        toasty::sql::statement(format!("DROP TABLE {names} CASCADE"))
            .exec(&mut db)
            .await?;
    }
    migrate(pool, migrations).await?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_connection_is_retired_only_if_opened_by_the_last_stale_plan() {
        let second = Duration::from_secs(1);
        // Never a stale plan: nothing is retired.
        assert!(!opened_before(0, second));
        // A stale plan at 5s: a connection opened at 0s, 1s, or 5s goes, one at 6s
        // stays.
        let at_five = 5_000_000_000 + 1;
        assert!(opened_before(at_five, Duration::ZERO));
        assert!(opened_before(at_five, second));
        assert!(opened_before(at_five, 5 * second));
        assert!(!opened_before(at_five, 6 * second));
    }

    #[test]
    fn session_settings_become_connection_parameters() {
        let base = "postgres://app@db/app";
        assert_eq!(session_uri(base, 0, "", false).unwrap(), base);
        assert_eq!(
            session_uri(base, 5000, "orders", true).unwrap(),
            "postgres://app@db/app?options=-c%20statement_timeout%3D5000%20-c%20\
             default_transaction_read_only%3Don&application_name=orders"
        );
        assert_eq!(
            session_uri("postgres://db/app?sslmode=require", 0, "orders", false).unwrap(),
            "postgres://db/app?sslmode=require&application_name=orders"
        );
    }

    #[test]
    fn a_url_that_sets_them_already_is_kept_or_refused() {
        // Its own application name wins.
        let named = "postgres://db/app?application_name=mine";
        assert_eq!(session_uri(named, 0, "orders", false).unwrap(), named);
        // Its own options and a setting here would replace one another, so neither does.
        let with_options = "postgres://db/app?options=-c%20work_mem%3D64MB";
        assert!(session_uri(with_options, 5000, "", false).is_err());
        assert!(session_uri(with_options, 0, "", true).is_err());
        assert_eq!(
            session_uri(with_options, 0, "", false).unwrap(),
            with_options
        );
        for name in ["has space", "a&b=c", "é", &"a".repeat(64)] {
            assert!(
                session_uri("postgres://db/app", 0, name, false).is_err(),
                "{name}"
            );
        }
    }

    #[test]
    fn debug_text_leaves_out_the_connection_string() {
        let text = format!("{:?}", PoolConfig::new("postgresql://me:hunter2@db/app"));
        assert!(!text.contains("hunter2"), "{text}");
        assert!(text.contains("max_connections"), "{text}");
    }

    #[test]
    fn identifiers_are_quoted() {
        assert_eq!(quote_identifier("users").as_deref(), Some("\"users\""));
        assert_eq!(quote_identifier("_a1").as_deref(), Some("\"_a1\""));
    }

    #[test]
    fn unsafe_identifiers_are_refused() {
        for name in [
            "", "1users", "Users", "a b", "a\"b", "a;b", "a.b", "users--", "é",
        ] {
            assert_eq!(quote_identifier(name), None, "{name:?}");
        }
        assert!(quote_all(&["good", "bad name"]).is_err());
    }

    #[test]
    fn errors_that_are_not_from_the_database_are_not_unique_violations() {
        assert!(!is_unique_violation(&toasty::Error::record_not_found(
            "nothing"
        )));
    }
}

//! [RFC 9457](https://www.rfc-editor.org/rfc/rfc9457) problem details.
//!
//! An error response is a JSON object with the media type
//! `application/problem+json`:
//!
//! ```
//! use axa_problem::Problem;
//! use axum::http::StatusCode;
//!
//! let problem = Problem::new(StatusCode::NOT_FOUND)
//!     .with_detail("No folder has id 42.")
//!     .with_instance("/api/folders/42");
//! assert_eq!(problem.title, "Not Found");
//! assert_eq!(problem.status, 404);
//! ```

use std::collections::BTreeMap;

use axum::{
    Json,
    http::{HeaderValue, StatusCode, header::CONTENT_TYPE},
    response::{IntoResponse, Response},
};
use serde::{Deserialize, Serialize};

/// The media type of a problem response.
pub const PROBLEM_JSON: &str = "application/problem+json";

/// The default `type`, meaning the status code says everything needed.
pub const ABOUT_BLANK: &str = "about:blank";

/// Member names RFC 9457 defines, which an extension must not reuse.
const RESERVED: [&str; 5] = ["type", "title", "status", "detail", "instance"];

/// One problem, as RFC 9457 defines it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Problem {
    /// A URI identifying the problem type.
    #[serde(rename = "type")]
    pub problem_type: String,
    /// A short summary that does not change between occurrences.
    pub title: String,
    /// The HTTP status code.
    pub status: u16,
    /// An explanation specific to this occurrence.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
    /// A URI identifying this occurrence.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub instance: Option<String>,
    /// Extra members, written at the top level of the object.
    #[serde(flatten)]
    pub extensions: BTreeMap<String, serde_json::Value>,
}

impl Problem {
    /// A problem for `status`, titled with the status's standard reason.
    #[must_use]
    pub fn new(status: StatusCode) -> Self {
        Self {
            problem_type: ABOUT_BLANK.to_string(),
            title: status.canonical_reason().unwrap_or("Error").to_string(),
            status: status.as_u16(),
            detail: None,
            instance: None,
            extensions: BTreeMap::new(),
        }
    }

    /// Set the problem type URI.
    #[must_use]
    pub fn with_type(mut self, problem_type: impl Into<String>) -> Self {
        self.problem_type = problem_type.into();
        self
    }

    /// Set the title.
    #[must_use]
    pub fn with_title(mut self, title: impl Into<String>) -> Self {
        self.title = title.into();
        self
    }

    /// Set the occurrence-specific detail. Never put internal failure text
    /// here: it is sent to the client.
    #[must_use]
    pub fn with_detail(mut self, detail: impl Into<String>) -> Self {
        self.detail = Some(detail.into());
        self
    }

    /// Set the occurrence URI.
    #[must_use]
    pub fn with_instance(mut self, instance: impl Into<String>) -> Self {
        self.instance = Some(instance.into());
        self
    }

    /// Add an extension member. A name RFC 9457 reserves is ignored, because
    /// flattening it would corrupt the standard member.
    #[must_use]
    pub fn with_extension(mut self, name: &str, value: serde_json::Value) -> Self {
        if !RESERVED.contains(&name) {
            self.extensions.insert(name.to_string(), value);
        }
        self
    }

    /// The status as a [`StatusCode`], or `500` if it is not a valid one.
    #[must_use]
    pub fn status_code(&self) -> StatusCode {
        StatusCode::from_u16(self.status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR)
    }
}

impl IntoResponse for Problem {
    fn into_response(self) -> Response {
        let status = self.status_code();
        let mut response = (status, Json(self)).into_response();
        response
            .headers_mut()
            .insert(CONTENT_TYPE, HeaderValue::from_static(PROBLEM_JSON));
        response
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn defaults_follow_the_rfc() {
        let value = serde_json::to_value(Problem::new(StatusCode::NOT_FOUND)).unwrap();
        assert_eq!(
            value,
            json!({ "type": "about:blank", "title": "Not Found", "status": 404 })
        );
    }

    #[test]
    fn optional_members_and_extensions_are_top_level() {
        let problem = Problem::new(StatusCode::CONFLICT)
            .with_type("https://example.org/problems/duplicate")
            .with_title("Duplicate record")
            .with_detail("Two records match.")
            .with_instance("/api/items/1")
            .with_extension("candidates", json!([1, 2]));
        let value = serde_json::to_value(problem).unwrap();
        assert_eq!(value["type"], "https://example.org/problems/duplicate");
        assert_eq!(value["title"], "Duplicate record");
        assert_eq!(value["detail"], "Two records match.");
        assert_eq!(value["instance"], "/api/items/1");
        assert_eq!(value["candidates"], json!([1, 2]));
    }

    #[test]
    fn reserved_names_cannot_be_overwritten_by_extensions() {
        let problem = Problem::new(StatusCode::NOT_FOUND).with_extension("status", json!(200));
        let value = serde_json::to_value(problem).unwrap();
        assert_eq!(value["status"], 404);
    }

    #[test]
    fn unknown_members_round_trip_as_extensions() {
        let problem: Problem = serde_json::from_value(json!({
            "type": "about:blank", "title": "x", "status": 400, "balance": 30
        }))
        .unwrap();
        assert_eq!(problem.extensions["balance"], 30);
    }

    #[test]
    fn an_invalid_status_falls_back_to_500() {
        let mut problem = Problem::new(StatusCode::OK);
        problem.status = 9999;
        assert_eq!(problem.status_code(), StatusCode::INTERNAL_SERVER_ERROR);
    }

    #[tokio::test]
    async fn responses_use_the_problem_media_type() {
        let response = Problem::new(StatusCode::IM_A_TEAPOT).into_response();
        assert_eq!(response.status(), StatusCode::IM_A_TEAPOT);
        assert_eq!(response.headers()[CONTENT_TYPE], PROBLEM_JSON);
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let value: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(value["status"], 418);
    }
}

//! Prometheus text exposition.
//!
//! A service keeps its own [`Registry`] and domain counters, and uses this
//! crate to serve them at a scrape path.
//!
//! ```
//! use axa_prometheus_metrics::{IntCounter, Opts, Registry, render};
//!
//! let registry = Registry::new();
//! let jobs = IntCounter::with_opts(Opts::new("jobs_total", "Jobs run.")).unwrap();
//! registry.register(Box::new(jobs.clone())).unwrap();
//! jobs.inc();
//! assert!(render(&registry).contains("jobs_total 1"));
//! ```
//!
//! Mount [`DEFAULT_PATH`] at the root, outside `/api`, and keep it public so a
//! scraper needs no bearer token. Metric names and labels are then readable by
//! anyone who can reach the port, so they must never carry personal data.
//!
//! [`RequestMetrics`] measures every request by its route template, never its path:
//!
//! ```
//! use axa_prometheus_metrics::{Registry, RequestMetrics, record};
//! use axum::{Router, middleware::from_fn_with_state, routing::get};
//!
//! let registry = Registry::new();
//! let metrics = RequestMetrics::register(&registry).unwrap();
//! let router: Router = Router::new()
//!     .route("/places/{id}", get(|| async { "ok" }))
//!     .layer(from_fn_with_state(metrics, record));
//! # let _ = router;
//! ```
//!
//! Add the layer to the router before `axa::middleware::apply`, so that it sits inside
//! routing and sees the route template.
//!
//! The `tokio` feature adds [`runtime::TokioMetrics`]: the Tokio runtime's workers, queue,
//! and busy time, and the polls of each task a service names.

#[cfg(feature = "tokio")]
pub mod runtime;

use axum::{
    extract::{MatchedPath, Request, State},
    http::{Method, StatusCode, header::CONTENT_TYPE as CONTENT_TYPE_HEADER},
    middleware::Next,
    response::{IntoResponse, Response},
};
pub use prometheus::{
    Counter, CounterVec, Gauge, GaugeVec, Histogram, HistogramOpts, HistogramVec, IntCounter,
    IntCounterVec, IntGauge, IntGaugeVec, Opts, Registry,
};
use prometheus::{Encoder, TextEncoder};
use std::time::Instant;

/// The route label for a request that matched no route, so that a scanner's paths
/// share one label rather than making one each.
pub const UNMATCHED: &str = "unmatched";

/// Request durations, by method, route template, and status code.
#[derive(Clone, Debug)]
pub struct RequestMetrics {
    duration: HistogramVec,
}

impl RequestMetrics {
    /// Make the histogram `http_server_request_duration_seconds` in `registry`, labelled
    /// `method`, `route`, and `status`. Its `_count` is the number of requests.
    ///
    /// # Errors
    ///
    /// Fails when `registry` already holds a metric of that name.
    pub fn register(registry: &Registry) -> prometheus::Result<Self> {
        let duration = HistogramVec::new(
            HistogramOpts::new(
                "http_server_request_duration_seconds",
                "How long requests took to answer, by method, route template, and status.",
            ),
            &["method", "route", "status"],
        )?;
        registry.register(Box::new(duration.clone()))?;
        Ok(Self { duration })
    }

    /// Record one request.
    fn observe(&self, method: &Method, route: &str, status: StatusCode, seconds: f64) {
        self.duration
            .with_label_values(&[method_label(method), route, status.as_str()])
            .observe(seconds);
    }
}

/// A method's label: one of the standard methods, or `other`, so that a client cannot
/// make a label by sending a method of its own.
fn method_label(method: &Method) -> &'static str {
    match *method {
        Method::GET => "GET",
        Method::HEAD => "HEAD",
        Method::POST => "POST",
        Method::PUT => "PUT",
        Method::PATCH => "PATCH",
        Method::DELETE => "DELETE",
        Method::OPTIONS => "OPTIONS",
        _ => "other",
    }
}

/// Record how long each request took, for `axum::middleware::from_fn_with_state`. The
/// route is the template the request matched, or [`UNMATCHED`].
pub async fn record(
    State(metrics): State<RequestMetrics>,
    request: Request,
    next: Next,
) -> Response {
    let method = request.method().clone();
    let route = request
        .extensions()
        .get::<MatchedPath>()
        .map_or_else(|| UNMATCHED.to_string(), |route| route.as_str().to_string());
    let started = Instant::now();
    let response = next.run(request).await;
    metrics.observe(
        &method,
        &route,
        response.status(),
        started.elapsed().as_secs_f64(),
    );
    response
}

/// The Prometheus text exposition media type.
pub const CONTENT_TYPE: &str = "text/plain; version=0.0.4";

/// The scrape path the family's services use.
pub const DEFAULT_PATH: &str = "/metrics.prom";

/// Render every metric in `registry`.
///
/// Encoding failure gives a comment line rather than a panic, because a bad
/// metric must not take a scrape or a service down with it.
#[must_use]
pub fn render(registry: &Registry) -> String {
    let mut buffer = Vec::new();
    if let Err(error) = TextEncoder::new().encode(&registry.gather(), &mut buffer) {
        return format!("# metrics encoding failed: {error}\n");
    }
    String::from_utf8(buffer).unwrap_or_default()
}

/// A `200` carrying rendered metrics with the exposition media type.
#[must_use]
pub fn response(body: String) -> Response {
    (StatusCode::OK, [(CONTENT_TYPE_HEADER, CONTENT_TYPE)], body).into_response()
}

/// Render `registry` as a scrape response.
#[must_use]
pub fn scrape(registry: &Registry) -> Response {
    response(render(registry))
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::{Router, body::Body, http::Request, routing::get};
    use tower::ServiceExt;

    fn registry() -> (Registry, IntCounter) {
        let registry = Registry::new();
        let counter = IntCounter::with_opts(Opts::new("jobs_total", "Jobs run.")).unwrap();
        registry.register(Box::new(counter.clone())).unwrap();
        (registry, counter)
    }

    async fn call(router: &Router, method: &str, path: &str) {
        let request = Request::builder()
            .method(method)
            .uri(path)
            .body(Body::empty())
            .unwrap();
        let _ = router.clone().oneshot(request).await.unwrap();
    }

    #[tokio::test]
    async fn requests_are_measured_by_route_template_not_path() {
        let registry = Registry::new();
        let metrics = RequestMetrics::register(&registry).unwrap();
        let router = Router::new()
            .route("/places/{id}", get(|| async { "ok" }))
            .layer(axum::middleware::from_fn_with_state(metrics, record));
        call(&router, "GET", "/places/1").await;
        call(&router, "GET", "/places/2").await;
        call(&router, "GET", "/wp-admin/one").await;
        call(&router, "GET", "/wp-admin/two").await;
        call(&router, "BREW", "/places/3").await;
        let text = render(&registry);
        let count = |labels: &str| {
            let line = format!("http_server_request_duration_seconds_count{{{labels}}}");
            text.lines()
                .find(|row| row.starts_with(&line))
                .unwrap_or_else(|| panic!("no {line} in\n{text}"))
                .rsplit(' ')
                .next()
                .unwrap()
                .to_string()
        };
        assert_eq!(
            count(r#"method="GET",route="/places/{id}",status="200""#),
            "2"
        );
        // A scanner's paths share one label.
        assert_eq!(count(r#"method="GET",route="unmatched",status="404""#), "2");
        // So does a method a client made up.
        assert_eq!(
            count(r#"method="other",route="/places/{id}",status="405""#),
            "1"
        );
        assert!(!text.contains("wp-admin"), "{text}");
        assert!(!text.contains("/places/1"), "{text}");
    }

    #[test]
    fn registering_twice_in_one_registry_fails() {
        let registry = Registry::new();
        assert!(RequestMetrics::register(&registry).is_ok());
        assert!(RequestMetrics::register(&registry).is_err());
    }

    #[test]
    fn an_empty_registry_renders_nothing() {
        assert_eq!(render(&Registry::new()), "");
    }

    #[test]
    fn counters_render_in_the_exposition_format() {
        let (registry, counter) = registry();
        counter.inc_by(3);
        let text = render(&registry);
        assert!(text.contains("# HELP jobs_total Jobs run."), "{text}");
        assert!(text.contains("# TYPE jobs_total counter"), "{text}");
        assert!(text.contains("jobs_total 3"), "{text}");
    }

    #[test]
    fn labelled_counters_keep_their_labels() {
        let registry = Registry::new();
        let counter = IntCounterVec::new(Opts::new("hits_total", "Hits."), &["route"]).unwrap();
        registry.register(Box::new(counter.clone())).unwrap();
        counter.with_label_values(&["home"]).inc();
        assert!(render(&registry).contains("hits_total{route=\"home\"} 1"));
    }

    #[tokio::test]
    async fn the_response_uses_the_exposition_media_type() {
        let response = response("x 1\n".to_string());
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(response.headers()[CONTENT_TYPE_HEADER], CONTENT_TYPE);
    }

    #[tokio::test]
    async fn a_live_scrape_reflects_later_increments() {
        let (registry, counter) = registry();
        let app = Router::new().route(
            DEFAULT_PATH,
            get(move || {
                let registry = registry.clone();
                async move { scrape(&registry) }
            }),
        );
        counter.inc();
        let request = Request::builder()
            .uri(DEFAULT_PATH)
            .body(Body::empty())
            .unwrap();
        let response = app.oneshot(request).await.unwrap();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        assert!(String::from_utf8_lossy(&bytes).contains("jobs_total 1"));
    }
}

//! Tokio runtime and task metrics, behind the `tokio` feature.
//!
//! [`TokioMetrics`] reads the runtime at each scrape, and counts the polls of each task a
//! service instruments by name:
//!
//! ```
//! use axa_prometheus_metrics::{Registry, render, runtime::TokioMetrics};
//!
//! # #[tokio::main(flavor = "current_thread")]
//! # async fn main() {
//! let registry = Registry::new();
//! let tokio_metrics = TokioMetrics::register(&registry, &tokio::runtime::Handle::current()).unwrap();
//! let queue = tokio_metrics.task("queue");
//! tokio::spawn(queue.instrument(async { /* the queue's loop */ })).await.unwrap();
//! assert!(render(&registry).contains(r#"tokio_task_polls_total{task="queue"}"#));
//! # }
//! ```
//!
//! Only the runtime metrics that stable Tokio offers are read: a build with
//! `--cfg tokio_unstable` reports the same ones.

use prometheus::{
    Counter, CounterVec, IntCounter, IntCounterVec, IntGauge, Opts, Registry,
    core::{Collector, Desc},
    proto::MetricFamily,
};
use std::{
    collections::BTreeMap,
    sync::{Arc, Mutex, PoisonError},
    time::Duration,
};
pub use tokio_metrics::TaskMonitor;
use tokio_metrics::{RuntimeIntervals, RuntimeMonitor, TaskMetrics};

/// Tokio runtime metrics, and the metrics of each task instrumented through
/// [`TokioMetrics::task`]. It is one collector in the registry, read at each scrape.
///
/// | Metric | Type | What it is |
/// |---|---|---|
/// | `tokio_runtime_workers` | gauge | Worker threads |
/// | `tokio_runtime_alive_tasks` | gauge | Tasks spawned and not yet finished |
/// | `tokio_runtime_global_queue_depth` | gauge | Tasks waiting in the shared queue |
/// | `tokio_runtime_worker_parks_total` | counter | Times a worker parked, finding no work |
/// | `tokio_runtime_worker_busy_seconds_total` | counter | Time workers spent running tasks |
/// | `tokio_task_instrumented_total{task}` | counter | Tasks instrumented under the name |
/// | `tokio_task_dropped_total{task}` | counter | Those tasks finished or dropped |
/// | `tokio_task_polls_total{task}` | counter | Polls of those tasks |
/// | `tokio_task_slow_polls_total{task}` | counter | Polls that took 50 microseconds or more |
/// | `tokio_task_poll_seconds_total{task}` | counter | Time spent polling them |
/// | `tokio_task_scheduled_seconds_total{task}` | counter | Time they waited to run once woken |
/// | `tokio_task_idle_seconds_total{task}` | counter | Time they waited to be woken |
///
/// Time scheduled but not running is the sign of a starved runtime: a blocking call in
/// one task holds up every other task on its worker.
#[derive(Clone)]
pub struct TokioMetrics {
    inner: Arc<Inner>,
}

impl std::fmt::Debug for TokioMetrics {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let tasks = lock(&self.inner.tasks);
        formatter
            .debug_struct("TokioMetrics")
            .field("tasks", &tasks.keys().collect::<Vec<_>>())
            .finish_non_exhaustive()
    }
}

struct Inner {
    runtime: Mutex<RuntimeIntervals>,
    tasks: Mutex<BTreeMap<&'static str, Task>>,
    workers: IntGauge,
    alive_tasks: IntGauge,
    global_queue_depth: IntGauge,
    parks: IntCounter,
    busy: Counter,
    instrumented: IntCounterVec,
    dropped: IntCounterVec,
    polls: IntCounterVec,
    slow_polls: IntCounterVec,
    poll_seconds: CounterVec,
    scheduled_seconds: CounterVec,
    idle_seconds: CounterVec,
}

/// A task's monitor, and the totals already reported, since a counter only grows by
/// what changed.
struct Task {
    monitor: TaskMonitor,
    reported: TaskMetrics,
}

impl TokioMetrics {
    /// Make the collector for `runtime`, and register it in `registry`.
    ///
    /// # Errors
    ///
    /// Fails when `registry` already holds a metric of one of these names.
    pub fn register(
        registry: &Registry,
        runtime: &tokio::runtime::Handle,
    ) -> prometheus::Result<Self> {
        let task = |name: &str, help: &str| IntCounterVec::new(Opts::new(name, help), &["task"]);
        let task_seconds =
            |name: &str, help: &str| CounterVec::new(Opts::new(name, help), &["task"]);
        let inner = Inner {
            runtime: Mutex::new(RuntimeMonitor::new(runtime).intervals()),
            tasks: Mutex::new(BTreeMap::new()),
            workers: IntGauge::new("tokio_runtime_workers", "Tokio worker threads.")?,
            alive_tasks: IntGauge::new(
                "tokio_runtime_alive_tasks",
                "Tokio tasks spawned and not yet finished.",
            )?,
            global_queue_depth: IntGauge::new(
                "tokio_runtime_global_queue_depth",
                "Tokio tasks waiting in the shared queue.",
            )?,
            parks: IntCounter::new(
                "tokio_runtime_worker_parks_total",
                "Times a Tokio worker parked, finding no work.",
            )?,
            busy: Counter::new(
                "tokio_runtime_worker_busy_seconds_total",
                "Time Tokio workers spent running tasks.",
            )?,
            instrumented: task("tokio_task_instrumented_total", "Tasks instrumented.")?,
            dropped: task(
                "tokio_task_dropped_total",
                "Instrumented tasks finished or dropped.",
            )?,
            polls: task("tokio_task_polls_total", "Polls of instrumented tasks.")?,
            slow_polls: task(
                "tokio_task_slow_polls_total",
                "Polls of instrumented tasks that took 50 microseconds or more.",
            )?,
            poll_seconds: task_seconds(
                "tokio_task_poll_seconds_total",
                "Time spent polling instrumented tasks.",
            )?,
            scheduled_seconds: task_seconds(
                "tokio_task_scheduled_seconds_total",
                "Time instrumented tasks waited to run once woken.",
            )?,
            idle_seconds: task_seconds(
                "tokio_task_idle_seconds_total",
                "Time instrumented tasks waited to be woken.",
            )?,
        };
        let metrics = Self {
            inner: Arc::new(inner),
        };
        registry.register(Box::new(metrics.clone()))?;
        Ok(metrics)
    }

    /// The monitor for tasks named `name`: wrap a future in [`TaskMonitor::instrument`]
    /// before spawning it. The same name gives the same monitor, so its tasks add up.
    ///
    /// The name is a label, so it is `'static`, written in the code: never a value from a
    /// request, which would let a client make labels without end.
    #[must_use]
    pub fn task(&self, name: &'static str) -> TaskMonitor {
        let mut tasks = lock(&self.inner.tasks);
        tasks
            .entry(name)
            .or_insert_with(|| Task {
                monitor: TaskMonitor::new(),
                reported: TaskMetrics::default(),
            })
            .monitor
            .clone()
    }

    /// Bring every metric up to date.
    fn update(&self) {
        let inner = &self.inner;
        if let Some(runtime) = lock(&inner.runtime).next() {
            inner.workers.set(gauge(runtime.workers_count));
            inner.alive_tasks.set(gauge(runtime.live_tasks_count));
            inner
                .global_queue_depth
                .set(gauge(runtime.global_queue_depth));
            inner.parks.inc_by(runtime.total_park_count);
            inner.busy.inc_by(runtime.total_busy_duration.as_secs_f64());
        }
        for (name, task) in lock(&inner.tasks).iter_mut() {
            let now = task.monitor.cumulative();
            let was = &task.reported;
            let count = |metric: &IntCounterVec, now: u64, was: u64| {
                metric
                    .with_label_values(&[name])
                    .inc_by(now.saturating_sub(was));
            };
            let seconds = |metric: &CounterVec, now: Duration, was: Duration| {
                metric
                    .with_label_values(&[name])
                    .inc_by(now.saturating_sub(was).as_secs_f64());
            };
            count(
                &inner.instrumented,
                now.instrumented_count,
                was.instrumented_count,
            );
            count(&inner.dropped, now.dropped_count, was.dropped_count);
            count(&inner.polls, now.total_poll_count, was.total_poll_count);
            count(
                &inner.slow_polls,
                now.total_slow_poll_count,
                was.total_slow_poll_count,
            );
            seconds(
                &inner.poll_seconds,
                now.total_poll_duration,
                was.total_poll_duration,
            );
            seconds(
                &inner.scheduled_seconds,
                now.total_scheduled_duration,
                was.total_scheduled_duration,
            );
            seconds(
                &inner.idle_seconds,
                now.total_idle_duration,
                was.total_idle_duration,
            );
            task.reported = now;
        }
    }

    fn parts(&self) -> [&dyn Collector; 12] {
        let inner = &self.inner;
        [
            &inner.workers,
            &inner.alive_tasks,
            &inner.global_queue_depth,
            &inner.parks,
            &inner.busy,
            &inner.instrumented,
            &inner.dropped,
            &inner.polls,
            &inner.slow_polls,
            &inner.poll_seconds,
            &inner.scheduled_seconds,
            &inner.idle_seconds,
        ]
    }
}

impl Collector for TokioMetrics {
    fn desc(&self) -> Vec<&Desc> {
        self.parts().into_iter().flat_map(Collector::desc).collect()
    }

    fn collect(&self) -> Vec<MetricFamily> {
        self.update();
        self.parts()
            .into_iter()
            .flat_map(Collector::collect)
            .collect()
    }
}

/// A count as a gauge's value, saturating rather than wrapping.
fn gauge(count: usize) -> i64 {
    i64::try_from(count).unwrap_or(i64::MAX)
}

/// Lock, carrying on after a panic elsewhere: these are counts, and a scrape must not
/// fail for one.
fn lock<T>(mutex: &Mutex<T>) -> std::sync::MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(PoisonError::into_inner)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::render;

    /// The sample on the line that starts `line`.
    fn sample<'a>(text: &'a str, line: &str) -> &'a str {
        text.lines()
            .find(|row| row.starts_with(&format!("{line} ")))
            .unwrap_or_else(|| panic!("no {line} in\n{text}"))
            .rsplit(' ')
            .next()
            .unwrap()
    }

    fn seconds(text: &str, line: &str) -> f64 {
        sample(text, line).parse().unwrap()
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn the_runtime_is_read_at_each_scrape() {
        let registry = Registry::new();
        let _metrics =
            TokioMetrics::register(&registry, &tokio::runtime::Handle::current()).unwrap();
        let text = render(&registry);
        assert_eq!(sample(&text, "tokio_runtime_workers"), "2");
        assert!(
            sample(&text, "tokio_runtime_alive_tasks")
                .parse::<u64>()
                .is_ok()
        );
        assert!(
            sample(&text, "tokio_runtime_global_queue_depth")
                .parse::<u64>()
                .is_ok()
        );
        assert!(
            text.contains("# TYPE tokio_runtime_worker_parks_total counter"),
            "{text}"
        );
        assert!(text.contains("# TYPE tokio_runtime_worker_busy_seconds_total counter"));
        let busy = seconds(&text, "tokio_runtime_worker_busy_seconds_total");
        for _ in 0..10 {
            tokio::spawn(async { std::hint::black_box((0..10_000).sum::<u64>()) })
                .await
                .unwrap();
        }
        let later = render(&registry);
        assert!(seconds(&later, "tokio_runtime_worker_busy_seconds_total") >= busy);
    }

    #[tokio::test]
    async fn tasks_of_one_name_add_up_under_one_label() {
        let registry = Registry::new();
        let metrics =
            TokioMetrics::register(&registry, &tokio::runtime::Handle::current()).unwrap();
        for _ in 0..3 {
            let monitor = metrics.task("queue");
            tokio::spawn(monitor.instrument(async { tokio::task::yield_now().await }))
                .await
                .unwrap();
        }
        let text = render(&registry);
        let queue = |text, name| sample(text, &format!(r#"tokio_task_{name}{{task="queue"}}"#));
        assert_eq!(queue(&text, "instrumented_total"), "3");
        assert_eq!(queue(&text, "dropped_total"), "3");
        let polls = queue(&text, "polls_total");
        assert!(polls.parse::<u64>().unwrap() >= 6, "{text}");
        // A second scrape reports the same totals, not twice them.
        let again = render(&registry);
        assert_eq!(queue(&again, "polls_total"), polls);
        assert_eq!(queue(&again, "instrumented_total"), "3");
    }

    #[tokio::test]
    async fn registering_twice_in_one_registry_fails() {
        let registry = Registry::new();
        let runtime = tokio::runtime::Handle::current();
        assert!(TokioMetrics::register(&registry, &runtime).is_ok());
        assert!(TokioMetrics::register(&registry, &runtime).is_err());
    }
}

//! A Redis cache with mandatory expiry.
//!
//! Values are stored as JSON under a key prefix, so several services can share
//! one Redis without colliding. [`Cache::memory`] gives the same behaviour inside
//! one process, for tests and for development with no Redis.
//!
//! ```no_run
//! use axa_redis_cache::{Cache, CacheConfig};
//! use std::time::Duration;
//!
//! # async fn run() -> Result<(), axa_redis_cache::Error> {
//! let config = CacheConfig::new("redis://localhost", "my_service", Duration::from_secs(60));
//! let cache = Cache::connect(&config).await?;
//!
//! cache.set("greeting", &"hello").await?;
//! let greeting: Option<String> = cache.get("greeting").await?;
//!
//! // Falls back to the loader on a miss, and also if Redis is down.
//! let total: Result<u64, std::io::Error> =
//!     cache.get_or_load("total", || async { Ok(42) }).await;
//! # Ok(())
//! # }
//! ```
//!
//! # What this crate promises
//!
//! - **Every entry expires.** There is no way to store a value without a TTL,
//!   because an entry that never expires is data nobody remembers holding.
//! - **A cache failure is not a service failure.** `get_or_load` logs a Redis
//!   error and calls the loader. Every call has a time limit,
//!   [`CacheConfig::timeout`], so a Redis that is down or frozen costs a request
//!   that long at most, never the client's own retries.
//! - **An unreadable entry is a miss.** After a change to a cached type, old
//!   entries are skipped rather than failing every read until they expire.
//!
//! # What to keep out of it
//!
//! Redis keeps values in plain text. Do not cache secrets, session ids, or
//! tokens. Cached records can also outlive a change to them, so caching data
//! subject to masking or erasure needs its own decision: an entry written
//! before an erasure survives it until its TTL ends unless it is deleted too.

use std::{
    collections::HashMap,
    future::Future,
    sync::{Arc, Mutex, PoisonError},
    time::{Duration, Instant},
};

use redis::{AsyncCommands, aio::ConnectionManager};
use serde::{Serialize, de::DeserializeOwned};

/// A cache failure.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// Redis failed or could not be reached.
    #[error(transparent)]
    Redis(#[from] redis::RedisError),
    /// A value could not be encoded as JSON.
    #[error(transparent)]
    Encode(#[from] serde_json::Error),
    /// Redis did not answer within [`CacheConfig::timeout`].
    #[error("the cache did not answer in time")]
    Timeout,
    /// A TTL below one millisecond, which would store nothing useful.
    #[error("a cache entry needs a TTL of at least one millisecond")]
    InvalidTtl,
    /// [`Cache::for_tenant`] refused: the tenant is not a tenant id, the cache is
    /// already a tenant's, or it has no prefix to keep tenants' keys apart from the rest.
    #[error("no cache for this tenant: {0}")]
    TenantScope(&'static str),
}

/// Cache settings.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CacheConfig {
    /// Connection string. Use `rediss://` for TLS.
    pub url: String,
    /// Prefix on every key, usually the service name.
    pub prefix: String,
    /// How long entries live unless a call says otherwise.
    pub default_ttl: Duration,
    /// How long one call may wait for Redis.
    pub timeout: Duration,
}

/// How long one call waits for Redis unless [`CacheConfig::timeout`] says
/// otherwise. A cache is an optimisation, so it gets little of a request's time.
pub const DEFAULT_TIMEOUT: Duration = Duration::from_millis(500);

impl CacheConfig {
    /// Build settings, with [`DEFAULT_TIMEOUT`].
    #[must_use]
    pub fn new(url: impl Into<String>, prefix: impl Into<String>, default_ttl: Duration) -> Self {
        Self {
            url: url.into(),
            prefix: prefix.into(),
            default_ttl,
            timeout: DEFAULT_TIMEOUT,
        }
    }
}

/// Whether `id` is a tenant id, as the auth crates' `is_tenant_id` says: lower-case
/// ASCII letters, digits, and hyphens, 1 to 63 characters, not starting or ending with a
/// hyphen.
fn is_tenant_id(id: &str) -> bool {
    (1..=63).contains(&id.len())
        && !id.starts_with('-')
        && !id.ends_with('-')
        && id
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
}

/// Join a prefix and a key.
fn full_key(prefix: &str, key: &str) -> String {
    if prefix.is_empty() {
        key.to_string()
    } else {
        format!("{prefix}:{key}")
    }
}

/// A TTL in whole milliseconds, refusing one that rounds to nothing.
fn ttl_millis(ttl: Duration) -> Result<u64, Error> {
    match u64::try_from(ttl.as_millis()) {
        Ok(0) => Err(Error::InvalidTtl),
        Ok(millis) => Ok(millis),
        // A TTL past `u64` milliseconds is hundreds of millions of years.
        Err(_) => Ok(u64::MAX),
    }
}

/// Decode a stored value, treating anything unreadable as a miss.
fn decode<T: DeserializeOwned>(stored: Option<&str>) -> Option<T> {
    let stored = stored?;
    match serde_json::from_str(stored) {
        Ok(value) => Some(value),
        Err(error) => {
            // The error's text can quote the value, and a key can name a person.
            tracing::warn!(
                line = error.line(),
                "unreadable cache entry treated as a miss"
            );
            None
        }
    }
}

/// The longest an in-process entry lives, for a TTL too large for the clock.
const MEMORY_MAX_TTL: Duration = Duration::from_hours(24 * 365);

/// The most the in-process cache holds, in bytes of keys and values.
const MEMORY_LIMIT: usize = 32 * 1024 * 1024;

/// Entries in this process, each with the moment it expires.
#[derive(Debug, Default)]
struct Memory {
    entries: HashMap<String, (Instant, String)>,
    bytes: usize,
}

impl Memory {
    fn get(&mut self, key: &str, now: Instant) -> Option<String> {
        let (expires, value) = self.entries.get(key)?;
        if *expires > now {
            return Some(value.clone());
        }
        self.remove(key);
        None
    }

    fn remove(&mut self, key: &str) -> bool {
        match self.entries.remove(key) {
            Some((_, value)) => {
                self.bytes -= key.len() + value.len();
                true
            }
            None => false,
        }
    }

    fn insert(&mut self, key: &str, value: String, expires: Instant, now: Instant) {
        self.remove(key);
        let size = key.len() + value.len();
        if size > MEMORY_LIMIT {
            return;
        }
        if self.bytes + size > MEMORY_LIMIT {
            let stale: Vec<String> = self
                .entries
                .iter()
                .filter(|(_, (when, _))| *when <= now)
                .map(|(name, _)| name.clone())
                .collect();
            for name in stale {
                self.remove(&name);
            }
        }
        // A cache may lose anything, so when live entries fill it, it starts again.
        if self.bytes + size > MEMORY_LIMIT {
            self.entries.clear();
            self.bytes = 0;
        }
        self.bytes += size;
        self.entries.insert(key.to_string(), (expires, value));
    }
}

#[derive(Clone)]
enum Backend {
    Redis(ConnectionManager),
    Memory(Arc<Mutex<Memory>>),
}

impl Backend {
    fn with_memory<T>(memory: &Mutex<Memory>, use_it: impl FnOnce(&mut Memory) -> T) -> T {
        use_it(&mut memory.lock().unwrap_or_else(PoisonError::into_inner))
    }
}

/// A connection to the cache. Cheap to clone, and it reconnects by itself.
#[derive(Clone)]
pub struct Cache {
    backend: Backend,
    prefix: String,
    /// The tenant every key belongs to, for a cache from [`Cache::for_tenant`].
    tenant: Option<String>,
    default_ttl: Duration,
    timeout: Duration,
}

impl std::fmt::Debug for Cache {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // Not the connection: its address can carry a password.
        f.debug_struct("Cache")
            .field("prefix", &self.prefix)
            .field("tenant", &self.tenant)
            .field("default_ttl", &self.default_ttl)
            .finish_non_exhaustive()
    }
}

impl Cache {
    /// Connect.
    ///
    /// # Errors
    ///
    /// Fails when the URL is invalid or Redis cannot be reached, or when the
    /// default TTL is below one millisecond.
    pub async fn connect(config: &CacheConfig) -> Result<Self, Error> {
        ttl_millis(config.default_ttl)?;
        let client = redis::Client::open(config.url.as_str())?;
        Ok(Self {
            backend: Backend::Redis(ConnectionManager::new(client).await?),
            prefix: config.prefix.clone(),
            tenant: None,
            default_ttl: config.default_ttl,
            timeout: config.timeout,
        })
    }

    /// A cache held in this process, for tests and for development with no
    /// Redis. Replicas do not share it, so it does not belong in production. It
    /// holds at most 32 MB, and starts again when full.
    ///
    /// # Errors
    ///
    /// Fails when the default TTL is below one millisecond.
    pub fn memory(prefix: impl Into<String>, default_ttl: Duration) -> Result<Self, Error> {
        ttl_millis(default_ttl)?;
        Ok(Self {
            backend: Backend::Memory(Arc::default()),
            prefix: prefix.into(),
            tenant: None,
            default_ttl,
            timeout: DEFAULT_TIMEOUT,
        })
    }

    /// Run a Redis call under the time limit. The client retries a lost
    /// connection for seconds by itself, which a request must not wait for.
    async fn bounded<T>(
        &self,
        call: impl Future<Output = Result<T, redis::RedisError>>,
    ) -> Result<T, Error> {
        match tokio::time::timeout(self.timeout, call).await {
            Ok(result) => Ok(result?),
            Err(_) => Err(Error::Timeout),
        }
    }

    /// The full key for `key`: `prefix:key`, or `prefix#tenant:key` for a tenant's
    /// cache. The character after the prefix tells them apart, so no key of the
    /// service's own, whatever it holds, is ever a tenant's, and no tenant's is another's.
    fn key(&self, key: &str) -> String {
        match &self.tenant {
            Some(tenant) => format!("{}#{tenant}:{key}", self.prefix),
            None => full_key(&self.prefix, key),
        }
    }

    /// This cache for `tenant` alone: every key it reads, writes, or deletes is that
    /// tenant's, so one tenant's cached answer is never served to another. Make one
    /// per request from the verified tenant, such as `axa::paseto::Tenant`, and pass
    /// only it to code that serves the tenant:
    ///
    /// ```
    /// # async fn example() -> Result<(), axa_redis_cache::Error> {
    /// # use std::time::Duration;
    /// let cache = axa_redis_cache::Cache::memory("svc", Duration::from_mins(5))?;
    /// let acme = cache.for_tenant("acme")?;
    /// acme.set("report", &42).await?;
    /// assert_eq!(cache.for_tenant("globex")?.get::<i32>("report").await?, None);
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// A tenant's cache shares the connection, the default TTL, and the time limit.
    ///
    /// # Errors
    ///
    /// [`Error::TenantScope`] when `tenant` is not a tenant id (lower-case ASCII letters,
    /// digits, and hyphens, 1 to 63 characters, not starting or ending with a hyphen),
    /// when this cache is already a tenant's, or when it has no prefix.
    pub fn for_tenant(&self, tenant: &str) -> Result<Self, Error> {
        if self.tenant.is_some() {
            return Err(Error::TenantScope("this cache is already a tenant's"));
        }
        if self.prefix.is_empty() {
            return Err(Error::TenantScope(
                "a cache with no prefix cannot keep tenants apart",
            ));
        }
        if !is_tenant_id(tenant) {
            return Err(Error::TenantScope("not a tenant id"));
        }
        Ok(Self {
            tenant: Some(tenant.to_string()),
            ..self.clone()
        })
    }

    /// The tenant this cache belongs to, for a cache from [`Cache::for_tenant`].
    #[must_use]
    pub fn tenant(&self) -> Option<&str> {
        self.tenant.as_deref()
    }

    /// Check that Redis answers.
    ///
    /// # Errors
    ///
    /// Fails when it does not.
    pub async fn ping(&self) -> Result<(), Error> {
        if let Backend::Redis(connection) = &self.backend {
            let mut connection = connection.clone();
            let ping = redis::cmd("PING");
            let _: String = self.bounded(ping.query_async(&mut connection)).await?;
        }
        Ok(())
    }

    /// Read a value. A missing, expired, or unreadable entry is `None`.
    ///
    /// # Errors
    ///
    /// Fails when Redis does.
    pub async fn get<T: DeserializeOwned>(&self, key: &str) -> Result<Option<T>, Error> {
        let full = self.key(key);
        let stored: Option<String> = match &self.backend {
            Backend::Redis(connection) => {
                let mut connection = connection.clone();
                self.bounded(connection.get(&full)).await?
            }
            Backend::Memory(memory) => {
                Backend::with_memory(memory, |memory| memory.get(&full, Instant::now()))
            }
        };
        Ok(decode(stored.as_deref()))
    }

    /// Store a value for the default TTL.
    ///
    /// # Errors
    ///
    /// Fails when the value cannot be encoded or Redis fails.
    pub async fn set<T: Serialize + Sync>(&self, key: &str, value: &T) -> Result<(), Error> {
        self.set_with_ttl(key, value, self.default_ttl).await
    }

    /// Store a value for `ttl`.
    ///
    /// # Errors
    ///
    /// Fails on a TTL below one millisecond, when the value cannot be encoded,
    /// or when Redis fails.
    pub async fn set_with_ttl<T: Serialize + Sync>(
        &self,
        key: &str,
        value: &T,
        ttl: Duration,
    ) -> Result<(), Error> {
        let millis = ttl_millis(ttl)?;
        let encoded = serde_json::to_string(value)?;
        let full = self.key(key);
        match &self.backend {
            Backend::Redis(connection) => {
                let mut connection = connection.clone();
                let (): () = self
                    .bounded(connection.pset_ex(full, encoded, millis))
                    .await?;
            }
            Backend::Memory(memory) => {
                let now = Instant::now();
                let expires = now.checked_add(ttl).unwrap_or(now + MEMORY_MAX_TTL);
                Backend::with_memory(memory, |memory| {
                    memory.insert(&full, encoded, expires, now);
                });
            }
        }
        Ok(())
    }

    /// Remove an entry, returning whether it existed.
    ///
    /// # Errors
    ///
    /// Fails when Redis does.
    pub async fn delete(&self, key: &str) -> Result<bool, Error> {
        let full = self.key(key);
        match &self.backend {
            Backend::Redis(connection) => {
                let mut connection = connection.clone();
                let removed: usize = self.bounded(connection.del(full)).await?;
                Ok(removed > 0)
            }
            Backend::Memory(memory) => {
                Ok(Backend::with_memory(memory, |memory| memory.remove(&full)))
            }
        }
    }

    /// Whether an entry exists.
    ///
    /// # Errors
    ///
    /// Fails when Redis does.
    pub async fn exists(&self, key: &str) -> Result<bool, Error> {
        let full = self.key(key);
        match &self.backend {
            Backend::Redis(connection) => {
                let mut connection = connection.clone();
                self.bounded(connection.exists(full)).await
            }
            Backend::Memory(memory) => Ok(Backend::with_memory(memory, |memory| {
                memory.get(&full, Instant::now()).is_some()
            })),
        }
    }

    /// Read a value, or load and store it on a miss.
    ///
    /// A Redis failure is logged and the value is loaded anyway, so a cache
    /// outage slows a service down rather than breaking it. After a failed read
    /// it does not try to store the value, so an outage costs one time limit,
    /// not two. Only the loader's own error is returned, and a failed load stores
    /// nothing.
    ///
    /// # Errors
    ///
    /// Returns the loader's error.
    pub async fn get_or_load<T, E, F, Fut>(&self, key: &str, load: F) -> Result<T, E>
    where
        T: Serialize + DeserializeOwned + Sync,
        F: FnOnce() -> Fut,
        Fut: Future<Output = Result<T, E>>,
    {
        match self.get(key).await {
            Ok(Some(value)) => return Ok(value),
            Ok(None) => {}
            Err(error) => {
                tracing::warn!(%error, "cache read failed, loading instead");
                return load().await;
            }
        }
        let value = load().await?;
        if let Err(error) = self.set(key, &value).await {
            tracing::warn!(%error, "cache write failed");
        }
        Ok(value)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const LIVE: Duration = Duration::from_mins(1);

    fn memory() -> Cache {
        Cache::memory("svc", LIVE).unwrap()
    }

    #[tokio::test]
    async fn the_memory_cache_stores_like_redis() {
        let cache = memory();
        assert_eq!(cache.get::<u32>("a").await.unwrap(), None);
        cache.set("a", &7_u32).await.unwrap();
        assert_eq!(cache.get::<u32>("a").await.unwrap(), Some(7));
        assert!(cache.exists("a").await.unwrap());
        assert!(cache.delete("a").await.unwrap());
        assert!(!cache.delete("a").await.unwrap());
        assert!(!cache.exists("a").await.unwrap());
        cache.ping().await.unwrap();
    }

    #[tokio::test]
    async fn clones_of_a_memory_cache_share_it() {
        let cache = memory();
        cache.clone().set("a", &1_u32).await.unwrap();
        assert_eq!(cache.get::<u32>("a").await.unwrap(), Some(1));
    }

    #[tokio::test]
    async fn the_memory_cache_refuses_a_zero_ttl() {
        assert!(matches!(
            Cache::memory("svc", Duration::ZERO),
            Err(Error::InvalidTtl)
        ));
        assert!(matches!(
            memory().set_with_ttl("a", &1_u32, Duration::ZERO).await,
            Err(Error::InvalidTtl)
        ));
    }

    #[tokio::test]
    async fn the_memory_cache_loads_on_a_miss_only() {
        let cache = memory();
        let first: Result<u32, ()> = cache.get_or_load("a", || async { Ok(1) }).await;
        let second: Result<u32, ()> = cache.get_or_load("a", || async { Ok(2) }).await;
        assert_eq!((first, second), (Ok(1), Ok(1)));
    }

    #[test]
    fn an_expired_entry_is_gone_and_its_bytes_are_returned() {
        let mut memory = Memory::default();
        let now = Instant::now();
        memory.insert("k", "value".to_string(), now + LIVE, now);
        assert_eq!(memory.get("k", now).as_deref(), Some("value"));
        assert_eq!(memory.get("k", now + LIVE), None);
        assert_eq!(memory.bytes, 0);
    }

    #[test]
    fn replacing_an_entry_counts_only_the_new_one() {
        let mut memory = Memory::default();
        let now = Instant::now();
        memory.insert("k", "long value".to_string(), now + LIVE, now);
        memory.insert("k", "v".to_string(), now + LIVE, now);
        assert_eq!(memory.bytes, 2);
    }

    #[test]
    fn the_memory_cache_never_holds_more_than_its_limit() {
        let mut memory = Memory::default();
        let now = Instant::now();
        let half = "x".repeat(MEMORY_LIMIT / 2);
        for key in ["a", "b", "c", "d"] {
            memory.insert(key, half.clone(), now + LIVE, now);
            assert!(memory.bytes <= MEMORY_LIMIT);
        }
        assert_eq!(memory.get("d", now).as_deref(), Some(half.as_str()));
        memory.insert("big", "x".repeat(MEMORY_LIMIT + 1), now + LIVE, now);
        assert_eq!(memory.get("big", now), None);
    }

    #[test]
    fn stale_entries_go_before_live_ones() {
        let mut memory = Memory::default();
        let now = Instant::now();
        let later = now + Duration::from_secs(5);
        let half = "x".repeat(MEMORY_LIMIT / 2);
        memory.insert("stale", half.clone(), later, now);
        memory.insert("live", half, now + LIVE, now);
        memory.insert("new", "y".repeat(16), later + LIVE, later);
        assert!(memory.entries.contains_key("live"));
        assert!(!memory.entries.contains_key("stale"));
    }

    #[test]
    fn keys_carry_the_prefix() {
        assert_eq!(full_key("svc", "a"), "svc:a");
        assert_eq!(full_key("", "a"), "a");
    }

    #[test]
    fn a_zero_ttl_is_refused() {
        assert!(matches!(ttl_millis(Duration::ZERO), Err(Error::InvalidTtl)));
        assert!(matches!(
            ttl_millis(Duration::from_micros(999)),
            Err(Error::InvalidTtl)
        ));
    }

    #[test]
    fn ttls_are_in_milliseconds() {
        assert_eq!(ttl_millis(Duration::from_secs(2)).unwrap(), 2_000);
    }

    #[test]
    fn a_huge_ttl_saturates() {
        assert_eq!(ttl_millis(Duration::MAX).unwrap(), u64::MAX);
    }

    #[test]
    fn stored_values_decode() {
        assert_eq!(decode::<u32>(Some("7")), Some(7));
    }

    #[test]
    fn a_missing_value_is_a_miss() {
        assert_eq!(decode::<u32>(None), None);
    }

    #[test]
    fn an_unreadable_value_is_a_miss() {
        assert_eq!(decode::<u32>(Some("not json")), None);
    }

    thread_local! {
        /// What this thread has logged, as each event's message and fields.
        static LOGGED: std::cell::RefCell<Vec<String>> = const { std::cell::RefCell::new(Vec::new()) };
    }

    /// Record every event from here on into its thread's [`LOGGED`], and forget what
    /// this thread logged before. The recorder is the global default: one set only for
    /// a thread can miss an event, as `tracing` caches whether a call site is wanted
    /// for all threads at once, and another test can ask first.
    fn record_logs() {
        static SET: std::sync::Once = std::sync::Once::new();
        SET.call_once(|| {
            tracing::subscriber::set_global_default(Recorder).expect("no other recorder");
        });
        // A call site first reached before the recorder was set may still be cached as
        // wanted by no one.
        tracing::callsite::rebuild_interest_cache();
        LOGGED.with(|logged| logged.borrow_mut().clear());
    }

    fn logged() -> Vec<String> {
        LOGGED.with(|logged| logged.borrow().clone())
    }

    struct Recorder;

    struct Line<'a>(&'a mut String);

    impl tracing::field::Visit for Line<'_> {
        fn record_debug(&mut self, field: &tracing::field::Field, value: &dyn std::fmt::Debug) {
            use std::fmt::Write;
            let _ = write!(self.0, " {}={value:?}", field.name());
        }
    }

    impl tracing::Subscriber for Recorder {
        fn enabled(&self, _: &tracing::Metadata<'_>) -> bool {
            true
        }
        fn new_span(&self, _: &tracing::span::Attributes<'_>) -> tracing::span::Id {
            tracing::span::Id::from_u64(1)
        }
        fn record(&self, _: &tracing::span::Id, _: &tracing::span::Record<'_>) {}
        fn record_follows_from(&self, _: &tracing::span::Id, _: &tracing::span::Id) {}
        fn event(&self, event: &tracing::Event<'_>) {
            let mut line = String::new();
            event.record(&mut Line(&mut line));
            LOGGED.with(|logged| logged.borrow_mut().push(line));
        }
        fn enter(&self, _: &tracing::span::Id) {}
        fn exit(&self, _: &tracing::span::Id) {}
    }

    /// A key that names a person, and a value that only its owner should see.
    const PERSON: &str = "person:ana@example.com";
    const SECRET: &str = "s3cret-diagnosis";

    fn assert_named_neither(lines: &[String]) {
        assert!(!lines.is_empty(), "nothing was logged");
        for line in lines {
            assert!(
                !line.contains("ana@example.com"),
                "a key was logged: {line}"
            );
            assert!(!line.contains(SECRET), "a value was logged: {line}");
        }
    }

    #[tokio::test]
    async fn an_unreadable_entry_is_logged_without_its_key_or_value() {
        record_logs();
        let cache = memory();
        let Backend::Memory(held) = &cache.backend else {
            unreachable!("a memory cache")
        };
        let now = Instant::now();
        Backend::with_memory(held, |held| {
            held.insert(
                &cache.key(PERSON),
                format!("{{\"note\": \"{SECRET}\" unterminated"),
                now + LIVE,
                now,
            );
        });

        assert_eq!(cache.get::<serde_json::Value>(PERSON).await.unwrap(), None);
        let loaded: Result<u32, ()> = cache.get_or_load(PERSON, || async { Ok(1) }).await;
        assert_eq!(loaded, Ok(1));
        assert_named_neither(&logged());
    }

    #[tokio::test]
    async fn a_failed_cache_write_is_logged_without_its_key_or_value() {
        record_logs();
        // JSON has no key that is not text, so this cannot be stored.
        let unstorable = || async {
            Ok::<_, ()>(std::collections::HashMap::from([(
                (1_u8, 2_u8),
                SECRET.to_string(),
            )]))
        };

        let loaded = memory().get_or_load(PERSON, unstorable).await.unwrap();
        assert_eq!(loaded[&(1, 2)], SECRET);
        assert_named_neither(&logged());
    }

    #[tokio::test]
    async fn a_tenants_cache_sees_only_that_tenants_keys() {
        let cache = memory();
        let acme = cache.for_tenant("acme").unwrap();
        let globex = cache.for_tenant("globex").unwrap();
        acme.set("report", &1).await.unwrap();
        globex.set("report", &2).await.unwrap();
        cache.set("report", &3).await.unwrap();
        assert_eq!(acme.get::<i32>("report").await.unwrap(), Some(1));
        assert_eq!(globex.get::<i32>("report").await.unwrap(), Some(2));
        assert_eq!(cache.get::<i32>("report").await.unwrap(), Some(3));
        assert!(acme.delete("report").await.unwrap());
        assert_eq!(globex.get::<i32>("report").await.unwrap(), Some(2));
        assert_eq!(acme.tenant(), Some("acme"));
        assert_eq!(cache.tenant(), None);
    }

    #[test]
    fn no_key_of_the_service_is_ever_a_tenants() {
        let cache = memory();
        let acme = cache.for_tenant("acme").unwrap();
        assert_eq!(acme.key("x"), "svc#acme:x");
        // Whatever an unscoped key holds, it starts `svc:`, and a tenant's `svc#`.
        for key in ["#acme:x", "acme:x", ":x", "svc#acme:x"] {
            assert_ne!(cache.key(key), acme.key("x"), "{key}");
        }
        // Nor is one tenant's key another's, as a tenant id holds no `:`.
        let a = cache.for_tenant("a").unwrap();
        assert_ne!(a.key("b:x"), cache.for_tenant("a-b").unwrap().key("x"));
    }

    #[test]
    fn a_tenants_cache_needs_a_tenant_id_a_prefix_and_no_tenant_yet() {
        let cache = memory();
        for tenant in [
            "",
            "Acme",
            "-acme",
            "acme-",
            "acme:x",
            "acme#x",
            &"a".repeat(64),
        ] {
            assert!(
                matches!(cache.for_tenant(tenant), Err(Error::TenantScope(_))),
                "{tenant}"
            );
        }
        let acme = cache.for_tenant("acme").unwrap();
        assert!(matches!(
            acme.for_tenant("globex"),
            Err(Error::TenantScope(_))
        ));
        let bare = Cache::memory("", LIVE).unwrap();
        assert!(matches!(
            bare.for_tenant("acme"),
            Err(Error::TenantScope(_))
        ));
    }
}

//! In-process request limits and failed-login lockout.
//!
//! A [`Limiter`] counts requests per key in a fixed window. [`by_client`] is the common
//! case, one limit per client address. [`by_key`] counts by a key a service chooses,
//! such as the signed-in user. [`lock_out_failures`] counts only the `401`s a client
//! earns, so that guessing a password is slowed and ordinary use is not.
//!
//! ```no_run
//! use std::num::NonZeroU32;
//!
//! use axa_request_rate_limit::{Limiter, by_client, lock_out_failures};
//! use axum::{Router, middleware::from_fn_with_state};
//!
//! # fn router(routes: Router, requests: NonZeroU32, failures: NonZeroU32) -> Router {
//! routes
//!     .layer(from_fn_with_state(Limiter::new(failures, 900.try_into().unwrap()), lock_out_failures))
//!     .layer(from_fn_with_state(Limiter::new(requests, 60.try_into().unwrap()), by_client))
//! # }
//! ```
//!
//! # Where the layers go
//!
//! Add them inside `axa::middleware::apply`, which is where the client's address is
//! worked out and where a refusal gets its request id and security headers. Add them
//! after the authentication layer, so that they sit outside it and see its `401`s.
//!
//! Behind a proxy, `TRUSTED_PROXIES` has to list it. Without that every request seems
//! to come from the proxy, and all clients share one limit. [`by_client`] warns once,
//! with the address left out, when the first [`SHARED_ALLOWANCE_SAMPLE`] requests it
//! counts all came from one private or loopback address, which is how that looks.
//!
//! # The key
//!
//! [`client_key`] reads the address `axa` resolved, as a plain [`IpAddr`] request
//! extension. It never reads `X-Forwarded-For`, because a caller writes the first entry
//! of that and could buy a fresh limit with each request. An IPv6 address counts by its
//! `/64`, which is what one subscriber is usually given. A request with no address
//! shares one limit with every other such request.
//!
//! For a limit of your own, such as a tighter one on one route, call [`Limiter::check`]
//! with any key that implements [`Hash`], and answer with [`Verdict::refusal`] or
//! [`Verdict::stamp`].
//!
//! # Counting by user
//!
//! [`Limiter::key`] takes a function from the request to a key, and [`by_key`] counts
//! by it. A function that returns `None` leaves the request uncounted, so a limit that
//! counts only signed-in users stays true. For several limits, such as a tight one on
//! comparisons and a looser one on everything else, use one limiter for each class, or
//! one keyed by `(subject, class)`.
//!
//! ```no_run
//! use std::num::NonZeroU32;
//!
//! use axa_request_rate_limit::{Limiter, by_key};
//! use axum::{Router, extract::Request, middleware::from_fn_with_state};
//!
//! /// The signed-in user, as the service's authentication layer left it.
//! #[derive(Clone)]
//! struct Subject(String);
//!
//! # fn router(routes: Router, limit: NonZeroU32) -> Router {
//! let per_user = Limiter::new(limit, 60.try_into().unwrap())
//!     .key(|request: &Request| request.extensions().get::<Subject>().map(|s| s.0.clone()));
//! routes.layer(from_fn_with_state(per_user, by_key))
//! # }
//! ```
//!
//! # Counting by tenant
//!
//! Where tenants share a service, one tenant's burst should not use up another's
//! allowance. Key the limit by the tenant and a class of request, such as reads and
//! writes, with the auth crate's `Tenant::from_extensions`, beside the limit per client.
//! The tenant is there only once the guard has verified the token, so this layer goes
//! inside the guard, added to the router before the guard's layer, and a request
//! with no tenant is left to the guard and the handler to refuse. Never take the
//! tenant from a header or a path, which any caller can write.
//!
//! ```ignore
//! use axa_paseto_auth::Tenant;
//!
//! let per_tenant = Limiter::new(limit, 60.try_into().unwrap()).key(|request: &Request| {
//!     let tenant = Tenant::from_extensions(request.extensions()).ok()?;
//!     let class = if request.method().is_safe() { "read" } else { "write" };
//!     Some((tenant, class))
//! });
//! let router = routes
//!     .layer(from_fn_with_state(per_tenant, by_key))
//!     .layer(from_fn_with_state(Arc::new(guard), axa_paseto_auth::middleware));
//! ```
//!
//! # A full table
//!
//! Past [`MAX_KEYS`], a key not yet held has nowhere of its own to be counted.
//! [`WhenFull`] says what happens to it. The default, [`WhenFull::Share`], counts all
//! such keys against one shared limit. A service where a refusal can harm someone,
//! such as one that holds care records, should choose [`WhenFull::Allow`], and count
//! [`Verdict::overflowed`] in a metric, because an overflow that passes unseen hides
//! an attack.
//!
//! # Seeing a refusal
//!
//! Every response from [`by_client`], [`by_key`], and [`lock_out_failures`] carries
//! its [`Verdict`] as a response extension, refused or not. [`Verdict::first_refusal`]
//! is true once per key per window, so a service can write one audit row for a client
//! that went over, rather than one for every refused request. The service does that in
//! its own layer outside the limiter, which sees the request and the response:
//!
//! ```no_run
//! use axa_request_rate_limit::Verdict;
//! use axum::{extract::Request, middleware::Next, response::Response};
//!
//! async fn audit_refusals(request: Request, next: Next) -> Response {
//!     let path = request.uri().path().to_owned();
//!     let response = next.run(request).await;
//!     if response.extensions().get::<Verdict>().is_some_and(|v| v.first_refusal) {
//!         // Write the audit row for `path`, and count the refusal in a metric. If the
//!         // write fails, the service decides: log it and count it, or answer otherwise.
//!         let _ = path;
//!     }
//!     response
//! }
//! ```
//!
//! # Lifting one key's limit
//!
//! [`Limiter::set_limit_for`] gives one key its own limit, such as a higher one for an
//! integration, from the next request on, with no restart. [`Limiter::clear_limit_for`]
//! takes it back. A key with a limit of its own is always held, even when the table is
//! full, and at most [`MAX_OVERRIDES`] are kept. Past that, setting another is refused.
//!
//! # What is kept
//!
//! A key is held only as a keyed hash, and the first request after two windows drops
//! it. An address is personal data, so the limiter neither stores nor logs one. A key
//! with a limit of its own is held as a keyed hash too.
//!
//! # Limits
//!
//! Each process counts for itself, so with several replicas a client gets one limit
//! from each. A client can send up to twice the limit across the end of a window.
//! A limit protects a service from a noisy client. It does not stop a distributed attack.

#[cfg(any(feature = "postgres", feature = "redis"))]
pub mod shared;

use std::{
    collections::HashMap,
    fmt,
    hash::{BuildHasher, Hash, RandomState},
    net::{IpAddr, Ipv6Addr},
    num::NonZeroU32,
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};

use axa_problem::Problem;
use axum::{
    extract::{Request, State},
    http::{Extensions, HeaderName, HeaderValue, StatusCode, header},
    middleware::Next,
    response::{IntoResponse, Response},
};

/// Paths never limited. A refused probe would restart a healthy service.
pub const EXEMPT: [&str; 3] = ["/_health/live", "/_health/ready", "/_health/startup"];

/// The most keys held at once, so that many clients cost a bounded amount of memory.
pub const MAX_KEYS: usize = 100_000;

/// The most keys with a limit of their own held at once.
pub const MAX_OVERRIDES: usize = 10_000;

/// How many requests [`by_client`] looks at before it warns that every one came from
/// one private or loopback address.
pub const SHARED_ALLOWANCE_SAMPLE: u32 = 100;

const LIMIT: HeaderName = HeaderName::from_static("ratelimit-limit");
const REMAINING: HeaderName = HeaderName::from_static("ratelimit-remaining");
const RESET: HeaderName = HeaderName::from_static("ratelimit-reset");

/// What happens to a key not yet held once [`MAX_KEYS`] are.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum WhenFull {
    /// All such keys share one limit. This is the default.
    #[default]
    Share,
    /// Such a key goes ahead uncounted. Choose this where a refusal can harm someone.
    Allow,
    /// Such a key is refused until the table has room.
    Refuse,
}

/// One key's count in its window.
#[derive(Debug, Clone, Copy)]
struct Slot {
    start: Instant,
    count: u32,
    /// Whether a refusal has been answered in this window.
    refused: bool,
}

impl Slot {
    const fn new(start: Instant) -> Self {
        Self {
            start,
            count: 0,
            refused: false,
        }
    }
}

/// How one request is counted.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Mode {
    /// Count it if it goes ahead.
    Charge,
    /// Say what a count would, and change nothing.
    Peek,
    /// Count nothing, but a refusal is answered, so it is the window's refusal.
    Gate,
}

/// The counts. A sweep is at most once a window, so that a table full of live keys
/// does not make every new key scan it.
#[derive(Debug)]
struct Table {
    slots: HashMap<u64, Slot>,
    /// Shared by new keys once `slots` is full.
    overflow: Slot,
    next_sweep: Instant,
    /// Keys with a limit of their own.
    overrides: HashMap<u64, u32>,
    /// Whether every client so far looks like one proxy.
    shared: Shared,
}

/// What [`by_client`] has seen of where its requests come from. It holds the client
/// only as a keyed hash.
#[derive(Debug, Clone, Copy, Default)]
enum Shared {
    /// Every request so far came from this one private or loopback client.
    Watching { client: u64, requests: u32 },
    /// No request yet.
    #[default]
    Unseen,
    /// Warned, or seen more than one client, or a public one. Nothing more to say.
    Settled,
}

/// A limit on requests per key in a fixed window.
///
/// Clones share their counts and their per-key limits.
#[derive(Debug, Clone)]
pub struct Limiter {
    limit: u32,
    window: Duration,
    max_keys: usize,
    max_overrides: usize,
    when_full: WhenFull,
    hasher: RandomState,
    table: Arc<Mutex<Table>>,
}

/// What a limiter says about one request.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Verdict {
    /// Whether the request may go ahead.
    pub allowed: bool,
    /// The limit, which is the key's own when it has one.
    pub limit: u32,
    /// Requests left in this window.
    pub remaining: u32,
    /// Whole seconds until this window ends, rounded up, so never too few to wait.
    pub reset_seconds: u64,
    /// Whether the key was not held because the table was full, so [`WhenFull`]
    /// decided.
    pub overflowed: bool,
    /// Whether this is the first refusal for this key in this window. Under
    /// [`WhenFull::Share`] and [`WhenFull::Refuse`], the keys that overflowed count as
    /// one key.
    pub first_refusal: bool,
}

/// A limit of its own was refused, because [`MAX_OVERRIDES`] keys already have one.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TooManyOverrides;

impl fmt::Display for TooManyOverrides {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("too many keys with a limit of their own")
    }
}

impl std::error::Error for TooManyOverrides {}

impl Limiter {
    /// `limit` requests per key in each window of `window_seconds`.
    ///
    /// Neither can be zero, so a setting of `0` cannot quietly mean either "refuse
    /// everyone" or "no limit". A service with no limit leaves the layer out.
    #[must_use]
    pub fn new(limit: NonZeroU32, window_seconds: NonZeroU32) -> Self {
        let now = Instant::now();
        let window = Duration::from_secs(u64::from(window_seconds.get()));
        Self {
            limit: limit.get(),
            window,
            max_keys: MAX_KEYS,
            max_overrides: MAX_OVERRIDES,
            when_full: WhenFull::default(),
            hasher: RandomState::new(),
            table: Arc::new(Mutex::new(Table {
                slots: HashMap::new(),
                overflow: Slot::new(now),
                next_sweep: now + window,
                overrides: HashMap::new(),
                shared: Shared::Unseen,
            })),
        }
    }

    /// What happens to a key not yet held once [`MAX_KEYS`] are. The default is
    /// [`WhenFull::Share`].
    #[must_use]
    pub const fn when_full(mut self, when_full: WhenFull) -> Self {
        self.when_full = when_full;
        self
    }

    /// Count by a key taken from each request, for [`by_key`]. A request for which
    /// `key` returns `None` is not counted.
    #[must_use]
    pub fn key<K, F>(self, key: F) -> Keyed<K>
    where
        F: Fn(&Request) -> Option<K> + Send + Sync + 'static,
    {
        Keyed {
            limiter: self,
            key: Arc::new(key),
        }
    }

    /// Count one request by `key`.
    pub fn check(&self, key: impl Hash) -> Verdict {
        self.tally(self.hasher.hash_one(key), Mode::Charge, Instant::now())
    }

    /// What [`Self::check`] would say about `key`, counting nothing.
    pub fn peek(&self, key: impl Hash) -> Verdict {
        self.tally(self.hasher.hash_one(key), Mode::Peek, Instant::now())
    }

    /// Give `key` a limit of its own from its next request, in place of the limiter's.
    /// A key with one is always held, even when the table is full.
    ///
    /// # Errors
    ///
    /// [`TooManyOverrides`] when [`MAX_OVERRIDES`] other keys already have one. None
    /// is dropped to make room.
    pub fn set_limit_for(&self, key: impl Hash, limit: NonZeroU32) -> Result<(), TooManyOverrides> {
        let key = self.hasher.hash_one(key);
        let mut table = self.lock();
        let overrides = &mut table.overrides;
        if !overrides.contains_key(&key) && overrides.len() >= self.max_overrides {
            return Err(TooManyOverrides);
        }
        overrides.insert(key, limit.get());
        Ok(())
    }

    /// Take back `key`'s limit of its own, so the limiter's applies from its next
    /// request. Says whether it had one.
    pub fn clear_limit_for(&self, key: impl Hash) -> bool {
        let key = self.hasher.hash_one(key);
        self.lock().overrides.remove(&key).is_some()
    }

    /// Note one request [`by_client`] counted, from `client` at `address`, and say
    /// whether this is the moment to warn that all clients share one limit.
    fn one_proxy(&self, client: u64, address: Option<IpAddr>) -> bool {
        let private = address.is_some_and(|address| match address.to_canonical() {
            IpAddr::V4(v4) => v4.is_private() || v4.is_loopback(),
            IpAddr::V6(v6) => v6.is_loopback() || v6.is_unique_local(),
        });
        let mut table = self.lock();
        let next = match table.shared {
            Shared::Settled => return false,
            _ if !private => Shared::Settled,
            Shared::Unseen => Shared::Watching {
                client,
                requests: 1,
            },
            Shared::Watching {
                client: seen,
                requests,
            } if seen == client => Shared::Watching {
                client,
                requests: requests + 1,
            },
            Shared::Watching { .. } => Shared::Settled,
        };
        let warn = matches!(next, Shared::Watching { requests, .. } if requests >= SHARED_ALLOWANCE_SAMPLE);
        table.shared = if warn { Shared::Settled } else { next };
        warn
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, Table> {
        // A poisoned lock holds counts, which are safe to go on using.
        self.table
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }

    #[cfg(test)]
    fn count(&self, key: u64, charge: bool, now: Instant) -> Verdict {
        self.tally(key, if charge { Mode::Charge } else { Mode::Peek }, now)
    }

    fn tally(&self, key: u64, mode: Mode, now: Instant) -> Verdict {
        let window = self.window;
        let mut table = self.lock();
        let Table {
            slots,
            overflow,
            next_sweep,
            overrides,
            ..
        } = &mut *table;
        if now >= *next_sweep {
            slots.retain(|_, slot| now.saturating_duration_since(slot.start) < window);
            *next_sweep = now + window;
        }
        let own_limit = overrides.get(&key).copied();
        let limit = own_limit.unwrap_or(self.limit);
        let known = slots.contains_key(&key);
        let full = !known && own_limit.is_none() && slots.len() >= self.max_keys;
        let slot = if full {
            match self.when_full {
                WhenFull::Allow => {
                    let mut verdict = self.verdict(Slot::new(now), limit, true, now);
                    verdict.overflowed = true;
                    return verdict;
                }
                WhenFull::Refuse => {
                    if now.saturating_duration_since(overflow.start) >= window {
                        *overflow = Slot::new(now);
                    }
                    let mut verdict = self.verdict(*overflow, limit, false, now);
                    verdict.remaining = 0;
                    verdict.overflowed = true;
                    if mode != Mode::Peek {
                        verdict.first_refusal = !overflow.refused;
                        overflow.refused = true;
                    }
                    return verdict;
                }
                WhenFull::Share => overflow,
            }
        } else if !known && mode != Mode::Charge {
            return self.verdict(Slot::new(now), limit, true, now);
        } else {
            slots.entry(key).or_insert_with(|| Slot::new(now))
        };
        if now.saturating_duration_since(slot.start) >= window {
            *slot = Slot::new(now);
        }
        let allowed = slot.count < limit;
        if allowed && mode == Mode::Charge {
            slot.count += 1;
        }
        let mut verdict = self.verdict(*slot, limit, allowed, now);
        verdict.overflowed = full;
        if !allowed && mode != Mode::Peek {
            verdict.first_refusal = !slot.refused;
            slot.refused = true;
        }
        verdict
    }

    fn verdict(&self, slot: Slot, limit: u32, allowed: bool, now: Instant) -> Verdict {
        let left = (slot.start + self.window).saturating_duration_since(now);
        Verdict {
            allowed,
            limit,
            remaining: limit.saturating_sub(slot.count),
            reset_seconds: left.as_secs() + u64::from(left.subsec_nanos() > 0),
            overflowed: false,
            first_refusal: false,
        }
    }

    #[cfg(test)]
    fn held(&self) -> usize {
        self.table.lock().unwrap().slots.len()
    }
}

/// What [`Limiter::key`] takes: the key a request is counted by, if any.
type KeyOf<K> = dyn Fn(&Request) -> Option<K> + Send + Sync;

/// A [`Limiter`] that counts by a key taken from each request, for [`by_key`]. Made
/// with [`Limiter::key`].
///
/// Clones share their counts.
pub struct Keyed<K> {
    limiter: Limiter,
    key: Arc<KeyOf<K>>,
}

impl<K> Clone for Keyed<K> {
    fn clone(&self) -> Self {
        Self {
            limiter: self.limiter.clone(),
            key: Arc::clone(&self.key),
        }
    }
}

impl<K> fmt::Debug for Keyed<K> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Keyed")
            .field("limiter", &self.limiter)
            .finish_non_exhaustive()
    }
}

impl<K: Hash> Keyed<K> {
    /// The limiter underneath, which counts the same keys.
    #[must_use]
    pub const fn limiter(&self) -> &Limiter {
        &self.limiter
    }

    /// Give `key` a limit of its own. See [`Limiter::set_limit_for`].
    ///
    /// # Errors
    ///
    /// [`TooManyOverrides`] when [`MAX_OVERRIDES`] other keys already have one.
    pub fn set_limit_for(&self, key: &K, limit: NonZeroU32) -> Result<(), TooManyOverrides> {
        self.limiter.set_limit_for(key, limit)
    }

    /// Take back `key`'s limit of its own. See [`Limiter::clear_limit_for`].
    pub fn clear_limit_for(&self, key: &K) -> bool {
        self.limiter.clear_limit_for(key)
    }
}

impl Verdict {
    /// Add `RateLimit-Limit`, `RateLimit-Remaining`, and `RateLimit-Reset`, and the
    /// verdict itself as a response extension.
    pub fn stamp(&self, response: &mut Response) {
        let headers = response.headers_mut();
        headers.insert(LIMIT, HeaderValue::from(self.limit));
        headers.insert(REMAINING, HeaderValue::from(self.remaining));
        headers.insert(RESET, HeaderValue::from(self.reset_seconds));
        response.extensions_mut().insert(*self);
    }

    /// The `429`, with `Retry-After`, the `RateLimit-*` headers, and the verdict as a
    /// response extension.
    #[must_use]
    pub fn refusal(&self) -> Response {
        let mut response = Problem::new(StatusCode::TOO_MANY_REQUESTS)
            .with_extension("code", serde_json::json!("too_many_requests"))
            .into_response();
        self.stamp(&mut response);
        response
            .headers_mut()
            .insert(header::RETRY_AFTER, HeaderValue::from(self.reset_seconds));
        response
    }
}

/// The client a request is counted against: the address `axa` resolved, with an IPv6
/// address reduced to its `/64`, or `None` if there is none.
#[must_use]
pub fn client_key(extensions: &Extensions) -> Option<IpAddr> {
    let address = extensions.get::<IpAddr>()?.to_canonical();
    Some(match address {
        IpAddr::V4(_) => address,
        IpAddr::V6(address) => IpAddr::V6(Ipv6Addr::from_bits(address.to_bits() & (!0u128 << 64))),
    })
}

/// Answer `verdict`'s refusal, or run the request and stamp what it answers.
async fn limited(verdict: Verdict, request: Request, next: Next) -> Response {
    if !verdict.allowed {
        return verdict.refusal();
    }
    let mut response = next.run(request).await;
    verdict.stamp(&mut response);
    response
}

/// Limit each client. Every response gets the `RateLimit-*` headers and its
/// [`Verdict`], apart from the probes in [`EXEMPT`], which are not counted.
///
/// Once per limiter, it warns if the first [`SHARED_ALLOWANCE_SAMPLE`] requests it
/// counts all came from one private or loopback address, as they do from a proxy
/// that `TRUSTED_PROXIES` does not list. The warning never holds the address.
pub async fn by_client(State(limiter): State<Limiter>, request: Request, next: Next) -> Response {
    if EXEMPT.contains(&request.uri().path()) {
        return next.run(request).await;
    }
    let client = limiter.hasher.hash_one(client_key(request.extensions()));
    let verdict = limiter.tally(client, Mode::Charge, Instant::now());
    if limiter.one_proxy(client, request.extensions().get::<IpAddr>().copied()) {
        // Never the address: the crate neither stores nor logs one.
        tracing::warn!(
            requests = SHARED_ALLOWANCE_SAMPLE,
            "ratelimit_one_client: every request came from one private address. Behind a \
             proxy, list it in TRUSTED_PROXIES, or all clients share one limit"
        );
    }
    limited(verdict, request, next).await
}

/// Limit by the key [`Limiter::key`] takes from each request. A request with no key is
/// not counted and gets no `RateLimit-*` headers, and neither do the probes in
/// [`EXEMPT`]. Every other response gets them and its [`Verdict`].
pub async fn by_key<K: Hash + Send + 'static>(
    State(keyed): State<Keyed<K>>,
    request: Request,
    next: Next,
) -> Response {
    if EXEMPT.contains(&request.uri().path()) {
        return next.run(request).await;
    }
    let Some(key) = (keyed.key)(&request) else {
        return next.run(request).await;
    };
    let verdict = keyed.limiter.check(key);
    limited(verdict, request, next).await
}

/// Refuse a client that has earned the limit in `401`s, until the window ends. Only a
/// `401` counts, so a client that signs in correctly is never slowed. Every response
/// it counts gets its [`Verdict`].
///
/// A `401` is counted when it is answered, so guesses sent at once can pass the limit
/// by however many are in flight. [`by_client`] outside this layer caps that.
pub async fn lock_out_failures(
    State(limiter): State<Limiter>,
    request: Request,
    next: Next,
) -> Response {
    if EXEMPT.contains(&request.uri().path()) {
        return next.run(request).await;
    }
    let key = limiter.hasher.hash_one(client_key(request.extensions()));
    let verdict = limiter.tally(key, Mode::Gate, Instant::now());
    if !verdict.allowed {
        return verdict.refusal();
    }
    let mut response = next.run(request).await;
    let verdict = if response.status() == StatusCode::UNAUTHORIZED {
        limiter.tally(key, Mode::Charge, Instant::now())
    } else {
        verdict
    };
    response.extensions_mut().insert(verdict);
    response
}

#[cfg(test)]
mod tests {
    use axum::{Router, body::Body, http, middleware::from_fn_with_state, routing::get};
    use tower::ServiceExt;

    use super::*;

    fn limiter(limit: u32, window_seconds: u32) -> Limiter {
        Limiter::new(
            limit.try_into().unwrap(),
            window_seconds.try_into().unwrap(),
        )
    }

    const fn secs(n: u64) -> Duration {
        Duration::from_secs(n)
    }

    #[test]
    fn the_limit_is_exact_and_a_refusal_is_not_counted() {
        let limiter = limiter(2, 60);
        let now = Instant::now();
        assert!(limiter.count(1, true, now).allowed);
        let second = limiter.count(1, true, now);
        assert!(second.allowed);
        assert_eq!(second.remaining, 0);
        assert!(!limiter.count(1, true, now).allowed);
        assert!(!limiter.count(1, true, now).allowed);
        assert!(limiter.count(1, true, now + secs(60)).allowed);
    }

    #[test]
    fn keys_are_counted_apart() {
        let limiter = limiter(1, 60);
        assert!(limiter.check("a").allowed);
        assert!(!limiter.check("a").allowed);
        assert!(limiter.check("b").allowed);
    }

    #[test]
    fn clones_share_their_counts() {
        let first = limiter(1, 60);
        assert!(first.clone().check("a").allowed);
        assert!(!first.check("a").allowed);
    }

    #[test]
    fn the_wait_is_rounded_up_and_never_too_short() {
        let limiter = limiter(1, 60);
        let now = Instant::now();
        assert_eq!(limiter.count(1, true, now).reset_seconds, 60);
        let later = now + Duration::from_millis(59_001);
        assert_eq!(limiter.count(1, true, later).reset_seconds, 1);
    }

    #[test]
    fn a_peek_counts_nothing_and_stores_nothing() {
        let limiter = limiter(1, 60);
        assert!(limiter.peek("a").allowed);
        assert_eq!(limiter.held(), 0);
        limiter.check("a");
        assert!(!limiter.peek("a").allowed);
    }

    #[test]
    fn old_keys_are_dropped_within_two_windows() {
        let limiter = limiter(5, 60);
        let now = Instant::now();
        limiter.count(1, true, now);
        limiter.count(2, true, now + secs(30));
        limiter.count(3, true, now + secs(61));
        assert_eq!(limiter.held(), 2, "key 2 is still in its window");
        limiter.count(3, true, now + secs(121));
        assert_eq!(limiter.held(), 1);
    }

    #[test]
    fn a_key_goes_the_moment_its_window_ends() {
        let limiter = limiter(5, 60);
        let now = Instant::now();
        limiter.count(1, true, now);
        limiter.count(2, true, now + secs(60));
        assert_eq!(limiter.held(), 1);
    }

    #[test]
    fn a_full_table_shares_one_limit_and_never_grows() {
        let mut limiter = limiter(2, 60);
        limiter.max_keys = 2;
        let now = Instant::now();
        limiter.count(1, true, now);
        limiter.count(2, true, now);
        assert!(limiter.count(3, true, now).allowed);
        assert!(limiter.count(4, true, now).allowed);
        assert!(!limiter.count(5, true, now).allowed, "they share a limit");
        assert_eq!(limiter.held(), 2);
        assert!(
            limiter.count(1, true, now).allowed,
            "a held key keeps its own"
        );
    }

    #[test]
    fn a_table_full_of_live_keys_is_not_scanned_for_each_new_key() {
        let mut limiter = limiter(1, 60);
        limiter.max_keys = 1;
        let now = Instant::now();
        limiter.count(1, true, now + secs(1));
        // Past the first sweep, which moves the next one a whole window on.
        limiter.count(2, true, now + secs(60));
        let next_sweep = limiter.table.lock().unwrap().next_sweep;
        limiter.count(3, true, now + secs(61));
        assert_eq!(limiter.table.lock().unwrap().next_sweep, next_sweep);
    }

    #[test]
    fn a_key_is_held_only_as_a_hash() {
        let limiter = limiter(1, 60);
        limiter.check("203.0.113.9");
        assert!(!format!("{limiter:?}").contains("203.0.113.9"));
    }

    fn with_address(address: &str) -> Extensions {
        let mut extensions = Extensions::new();
        extensions.insert(address.parse::<IpAddr>().unwrap());
        extensions
    }

    #[test]
    fn one_ipv6_subscriber_counts_once() {
        let key = |address| client_key(&with_address(address));
        assert_eq!(key("2001:db8:1:2::1"), key("2001:db8:1:2:ffff::9"));
        assert_ne!(key("2001:db8:1:2::1"), key("2001:db8:1:3::1"));
    }

    #[test]
    fn an_ipv4_client_counts_the_same_however_it_arrives() {
        let key = |address| client_key(&with_address(address));
        assert_eq!(key("::ffff:203.0.113.9"), key("203.0.113.9"));
        assert_ne!(key("203.0.113.9"), key("203.0.113.10"));
    }

    fn request(path: &str, address: Option<&str>) -> Request {
        let mut request = http::Request::get(path).body(Body::empty()).unwrap();
        if let Some(address) = address {
            *request.extensions_mut() = with_address(address);
        }
        request
    }

    fn limited(limiter: Limiter) -> Router {
        Router::new()
            .route("/", get(|| async { "ok" }))
            .route("/_health/live", get(|| async { "ok" }))
            .layer(from_fn_with_state(limiter, by_client))
    }

    #[tokio::test]
    async fn a_refusal_says_how_long_to_wait() {
        let app = limited(limiter(1, 60));
        let first = app.clone().oneshot(request("/", Some("203.0.113.9"))).await;
        let first = first.unwrap();
        assert_eq!(first.status(), StatusCode::OK);
        assert_eq!(first.headers()["ratelimit-limit"], "1");
        assert_eq!(first.headers()["ratelimit-remaining"], "0");
        assert!(first.headers().get(header::RETRY_AFTER).is_none());

        let second = app
            .oneshot(request("/", Some("203.0.113.9")))
            .await
            .unwrap();
        assert_eq!(second.status(), StatusCode::TOO_MANY_REQUESTS);
        assert_eq!(second.headers()["ratelimit-remaining"], "0");
        let wait = second.headers()[header::RETRY_AFTER].to_str().unwrap();
        assert!((1..=60).contains(&wait.parse::<u64>().unwrap()));
        assert_eq!(
            second.headers()[header::CONTENT_TYPE],
            axa_problem::PROBLEM_JSON
        );
        let body = axum::body::to_bytes(second.into_body(), usize::MAX).await;
        let body: serde_json::Value = serde_json::from_slice(&body.unwrap()).unwrap();
        assert_eq!(body["status"], 429);
        assert_eq!(body["code"], "too_many_requests");
    }

    #[tokio::test]
    async fn the_probes_are_never_refused_or_counted() {
        let limiter = limiter(1, 60);
        let app = limited(limiter.clone());
        for _ in 0..3 {
            let response = app
                .clone()
                .oneshot(request("/_health/live", None))
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            assert!(response.headers().get("ratelimit-limit").is_none());
        }
        assert_eq!(limiter.held(), 0);
    }

    #[tokio::test]
    async fn requests_with_no_address_share_one_limit() {
        let app = limited(limiter(1, 60));
        let first = app.clone().oneshot(request("/", None)).await.unwrap();
        assert_eq!(first.status(), StatusCode::OK);
        let second = app.oneshot(request("/", None)).await.unwrap();
        assert_eq!(second.status(), StatusCode::TOO_MANY_REQUESTS);
    }

    fn guarded(limiter: Limiter) -> Router {
        Router::new()
            .route(
                "/",
                get(|headers: http::HeaderMap| async move {
                    if headers.contains_key(header::AUTHORIZATION) {
                        StatusCode::OK
                    } else {
                        StatusCode::UNAUTHORIZED
                    }
                }),
            )
            .layer(from_fn_with_state(limiter, lock_out_failures))
    }

    fn signed_in(address: &str) -> Request {
        let mut request = request("/", Some(address));
        request
            .headers_mut()
            .insert(header::AUTHORIZATION, HeaderValue::from_static("Bearer x"));
        request
    }

    #[tokio::test]
    async fn failures_lock_a_client_out_and_only_that_client() {
        let app = guarded(limiter(2, 60));
        for _ in 0..2 {
            let response = app.clone().oneshot(request("/", Some("203.0.113.9"))).await;
            assert_eq!(response.unwrap().status(), StatusCode::UNAUTHORIZED);
        }
        let locked = app.clone().oneshot(signed_in("203.0.113.9")).await.unwrap();
        assert_eq!(locked.status(), StatusCode::TOO_MANY_REQUESTS);
        assert!(locked.headers().contains_key(header::RETRY_AFTER));
        let other = app.oneshot(signed_in("203.0.113.10")).await.unwrap();
        assert_eq!(other.status(), StatusCode::OK);
    }

    #[tokio::test]
    async fn success_never_counts_towards_a_lockout() {
        let limiter = limiter(1, 60);
        let app = guarded(limiter.clone());
        for _ in 0..3 {
            let response = app.clone().oneshot(signed_in("203.0.113.9")).await.unwrap();
            assert_eq!(response.status(), StatusCode::OK);
        }
        assert_eq!(limiter.held(), 0);
    }

    // Keyed limits.

    #[derive(Clone)]
    struct Subject(&'static str);

    fn by_subject(limiter: Limiter) -> Router {
        let keyed =
            limiter.key(|request: &Request| request.extensions().get::<Subject>().map(|s| s.0));
        Router::new()
            .route("/", get(|| async { "ok" }))
            .route("/_health/live", get(|| async { "ok" }))
            .layer(from_fn_with_state(keyed, by_key))
    }

    fn as_subject(path: &str, subject: Option<&'static str>) -> Request {
        let mut request = request(path, Some("203.0.113.9"));
        if let Some(subject) = subject {
            request.extensions_mut().insert(Subject(subject));
        }
        request
    }

    #[tokio::test]
    async fn a_keyed_limit_counts_by_the_key_it_takes() {
        let app = by_subject(limiter(1, 60));
        let ana = app
            .clone()
            .oneshot(as_subject("/", Some("ana")))
            .await
            .unwrap();
        assert_eq!(ana.status(), StatusCode::OK);
        assert_eq!(ana.headers()["ratelimit-limit"], "1");
        let again = app
            .clone()
            .oneshot(as_subject("/", Some("ana")))
            .await
            .unwrap();
        assert_eq!(again.status(), StatusCode::TOO_MANY_REQUESTS);
        // The same address, another subject: counted apart.
        let bob = app.oneshot(as_subject("/", Some("bob"))).await.unwrap();
        assert_eq!(bob.status(), StatusCode::OK);
    }

    /// The tenant, as an auth crate's guard leaves it for `Tenant::from_extensions`.
    #[derive(Clone)]
    struct TenantOf(&'static str);

    #[tokio::test]
    async fn a_limit_per_tenant_and_class_keeps_tenants_and_classes_apart() {
        let keyed = limiter(2, 60).key(|request: &Request| {
            let tenant = request.extensions().get::<TenantOf>()?.0;
            let class = if request.method() == http::Method::GET {
                "read"
            } else {
                "write"
            };
            Some((tenant, class))
        });
        let app = Router::new()
            .route("/", get(|| async { "ok" }).post(|| async { "ok" }))
            .layer(from_fn_with_state(keyed, by_key));
        let send = |method: http::Method, tenant: &'static str| {
            let mut request = request("/", Some("203.0.113.9"));
            *request.method_mut() = method;
            request.extensions_mut().insert(TenantOf(tenant));
            let app = app.clone();
            async move { app.oneshot(request).await.unwrap().status() }
        };
        for _ in 0..2 {
            assert_eq!(send(http::Method::POST, "acme").await, StatusCode::OK);
        }
        assert_eq!(
            send(http::Method::POST, "acme").await,
            StatusCode::TOO_MANY_REQUESTS
        );
        // The same client and tenant, another class, and another tenant, from the same
        // address: each has its own limit.
        assert_eq!(send(http::Method::GET, "acme").await, StatusCode::OK);
        assert_eq!(send(http::Method::POST, "globex").await, StatusCode::OK);
    }

    #[tokio::test]
    async fn a_request_with_no_key_is_not_counted() {
        let limiter = limiter(1, 60);
        let app = by_subject(limiter.clone());
        for _ in 0..3 {
            let response = app.clone().oneshot(as_subject("/", None)).await.unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            assert!(response.headers().get("ratelimit-limit").is_none());
            assert!(response.extensions().get::<Verdict>().is_none());
        }
        assert_eq!(limiter.held(), 0);
    }

    #[tokio::test]
    async fn keyed_probes_are_never_refused_or_counted() {
        let limiter = limiter(1, 60);
        let app = by_subject(limiter.clone());
        for _ in 0..3 {
            let response = app
                .clone()
                .oneshot(as_subject("/_health/live", Some("ana")))
                .await;
            assert_eq!(response.unwrap().status(), StatusCode::OK);
        }
        assert_eq!(limiter.held(), 0);
    }

    // A full table.

    fn full(when_full: WhenFull) -> Limiter {
        let mut limiter = limiter(1, 60).when_full(when_full);
        limiter.max_keys = 1;
        limiter
    }

    #[test]
    fn a_full_table_shares_by_default_and_says_so() {
        let limiter = full(WhenFull::default());
        let now = Instant::now();
        assert!(!limiter.count(1, true, now).overflowed, "a held key");
        let shared = limiter.count(2, true, now);
        assert!(shared.allowed && shared.overflowed);
        assert!(!limiter.count(3, true, now).allowed, "they share a limit");
    }

    #[test]
    fn a_full_table_can_let_new_keys_through() {
        let limiter = full(WhenFull::Allow);
        let now = Instant::now();
        limiter.count(1, true, now);
        for key in 2..10 {
            let verdict = limiter.count(key, true, now);
            assert!(verdict.allowed && verdict.overflowed);
            assert!(!verdict.first_refusal);
        }
        assert_eq!(limiter.held(), 1);
        assert!(
            !limiter.count(1, true, now).allowed,
            "a held key keeps its own"
        );
    }

    #[test]
    fn a_full_table_can_refuse_new_keys() {
        let limiter = full(WhenFull::Refuse);
        let now = Instant::now();
        limiter.count(1, true, now);
        let first = limiter.count(2, true, now);
        assert!(!first.allowed && first.overflowed && first.first_refusal);
        assert_eq!(first.remaining, 0);
        let second = limiter.count(3, true, now);
        assert!(!second.allowed && !second.first_refusal);
        assert_eq!(limiter.held(), 1);
        assert!(limiter.count(2, true, now + secs(61)).allowed, "room again");
    }

    // The first refusal.

    #[test]
    fn the_first_refusal_in_a_window_is_marked_once() {
        let limiter = limiter(1, 60);
        let now = Instant::now();
        assert!(!limiter.count(1, true, now).first_refusal, "allowed");
        assert!(limiter.count(1, true, now).first_refusal);
        assert!(!limiter.count(1, true, now).first_refusal);
        assert!(!limiter.count(1, true, now + secs(30)).first_refusal);
        assert!(limiter.count(1, true, now + secs(60)).allowed);
        assert!(
            limiter.count(1, true, now + secs(61)).first_refusal,
            "a new window"
        );
    }

    #[test]
    fn a_window_that_ends_between_sweeps_clears_the_refusal() {
        let limiter = limiter(1, 60);
        let now = Instant::now();
        limiter.count(1, true, now + secs(1));
        assert!(limiter.count(1, true, now + secs(1)).first_refusal);
        // A sweep that leaves key 1 held, because its window has a second to go.
        limiter.count(2, true, now + secs(60));
        assert_eq!(limiter.held(), 2);
        // Key 1's window ends in its slot, so the slot itself must start afresh.
        assert!(limiter.count(1, true, now + secs(61)).allowed);
        assert!(limiter.count(1, true, now + secs(61)).first_refusal);
    }

    #[test]
    fn a_peek_never_takes_the_first_refusal() {
        let limiter = limiter(1, 60);
        let now = Instant::now();
        limiter.count(1, true, now);
        let peeked = limiter.count(1, false, now);
        assert!(!peeked.allowed && !peeked.first_refusal);
        assert!(limiter.count(1, true, now).first_refusal);
    }

    #[test]
    fn overflowed_keys_share_one_first_refusal() {
        let limiter = full(WhenFull::Share);
        let now = Instant::now();
        limiter.count(1, true, now);
        limiter.count(2, true, now);
        assert!(limiter.count(3, true, now).first_refusal);
        assert!(!limiter.count(4, true, now).first_refusal);
    }

    // The verdict on every response.

    #[tokio::test]
    async fn every_response_carries_its_verdict() {
        let app = limited(limiter(1, 60));
        let allowed = app
            .clone()
            .oneshot(request("/", Some("203.0.113.9")))
            .await
            .unwrap();
        let verdict = allowed.extensions().get::<Verdict>().copied().unwrap();
        assert!(verdict.allowed && !verdict.first_refusal);
        let refused = app
            .clone()
            .oneshot(request("/", Some("203.0.113.9")))
            .await
            .unwrap();
        let verdict = refused.extensions().get::<Verdict>().copied().unwrap();
        assert!(!verdict.allowed && verdict.first_refusal);
        let again = app
            .oneshot(request("/", Some("203.0.113.9")))
            .await
            .unwrap();
        assert!(!again.extensions().get::<Verdict>().unwrap().first_refusal);

        let keyed = by_subject(limiter(1, 60));
        let response = keyed.oneshot(as_subject("/", Some("ana"))).await.unwrap();
        assert!(response.extensions().get::<Verdict>().is_some());
    }

    #[tokio::test]
    async fn a_lockout_marks_its_first_refusal_and_carries_its_verdict() {
        let app = guarded(limiter(1, 60));
        let failed = app
            .clone()
            .oneshot(request("/", Some("203.0.113.9")))
            .await
            .unwrap();
        assert_eq!(failed.status(), StatusCode::UNAUTHORIZED);
        assert_eq!(failed.extensions().get::<Verdict>().unwrap().remaining, 0);
        let locked = app.clone().oneshot(signed_in("203.0.113.9")).await.unwrap();
        assert_eq!(locked.status(), StatusCode::TOO_MANY_REQUESTS);
        assert!(locked.extensions().get::<Verdict>().unwrap().first_refusal);
        let again = app.oneshot(signed_in("203.0.113.9")).await.unwrap();
        assert!(!again.extensions().get::<Verdict>().unwrap().first_refusal);
    }

    // A key's own limit.

    #[test]
    fn a_key_can_have_a_limit_of_its_own_with_no_restart() {
        let limiter = limiter(1, 60);
        assert!(limiter.check("integration").allowed);
        assert!(!limiter.check("integration").allowed);
        limiter
            .set_limit_for("integration", 3.try_into().unwrap())
            .unwrap();
        let lifted = limiter.check("integration");
        assert!(lifted.allowed);
        assert_eq!((lifted.limit, lifted.remaining), (3, 1));
        assert_eq!(limiter.check("other").limit, 1, "only that key");
        assert!(
            limiter.clone().clear_limit_for("integration"),
            "clones share them"
        );
        let back = limiter.check("integration");
        assert!(!back.allowed);
        assert_eq!((back.limit, back.remaining), (1, 0));
        assert!(!limiter.clear_limit_for("integration"));
    }

    #[test]
    fn a_key_with_its_own_limit_is_held_when_the_table_is_full() {
        let limiter = full(WhenFull::Refuse);
        let now = Instant::now();
        limiter.count(1, true, now);
        limiter.set_limit_for(2_u64, 5.try_into().unwrap()).unwrap();
        let key = limiter.hasher.hash_one(2_u64);
        let verdict = limiter.count(key, true, now);
        assert!(verdict.allowed && !verdict.overflowed);
        assert_eq!(verdict.limit, 5);
    }

    #[test]
    fn too_many_own_limits_are_refused_and_none_is_dropped() {
        let mut limiter = limiter(1, 60);
        limiter.max_overrides = 2;
        let five = 5.try_into().unwrap();
        limiter.set_limit_for("a", five).unwrap();
        limiter.set_limit_for("b", five).unwrap();
        assert_eq!(limiter.set_limit_for("c", five), Err(TooManyOverrides));
        assert_eq!(
            limiter.set_limit_for("a", 9.try_into().unwrap()),
            Ok(()),
            "a change"
        );
        assert_eq!(limiter.check("a").limit, 9);
        assert_eq!(limiter.check("b").limit, 5);
    }

    #[test]
    fn an_own_limit_is_held_only_as_a_hash() {
        let limiter = limiter(1, 60);
        limiter
            .set_limit_for("integration-7", 5.try_into().unwrap())
            .unwrap();
        assert!(!format!("{limiter:?}").contains("integration-7"));
        let keyed = limiter.key(|_: &Request| Some("x"));
        assert!(!format!("{keyed:?}").contains("integration-7"));
    }

    // The warning about one proxy.

    /// Every event logged, as `LEVEL field=value ...`, with no subscriber crate.
    #[derive(Clone, Default)]
    struct Captured(Arc<Mutex<Vec<String>>>);

    impl tracing::Subscriber for Captured {
        fn enabled(&self, _: &tracing::Metadata<'_>) -> bool {
            true
        }
        fn new_span(&self, _: &tracing::span::Attributes<'_>) -> tracing::span::Id {
            tracing::span::Id::from_u64(1)
        }
        fn record(&self, _: &tracing::span::Id, _: &tracing::span::Record<'_>) {}
        fn record_follows_from(&self, _: &tracing::span::Id, _: &tracing::span::Id) {}
        fn event(&self, event: &tracing::Event<'_>) {
            struct Text(String);
            impl tracing::field::Visit for Text {
                fn record_debug(&mut self, field: &tracing::field::Field, value: &dyn fmt::Debug) {
                    use fmt::Write;
                    let _ = write!(self.0, " {}={value:?}", field.name());
                }
            }
            let mut text = Text(event.metadata().level().to_string());
            event.record(&mut text);
            self.0.lock().unwrap().push(text.0);
        }
        fn enter(&self, _: &tracing::span::Id) {}
        fn exit(&self, _: &tracing::span::Id) {}
    }

    /// Send a request to `/` from each address in turn, and return what was logged.
    async fn logged_for(addresses: impl IntoIterator<Item = &'static str>) -> Vec<String> {
        let captured = Captured::default();
        let _guard = tracing::dispatcher::set_default(&tracing::Dispatch::new(captured.clone()));
        let app = limited(limiter(10_000, 60));
        for address in addresses {
            app.clone()
                .oneshot(request("/", Some(address)))
                .await
                .unwrap();
        }
        captured.0.lock().unwrap().clone()
    }

    fn warnings(logged: &[String]) -> Vec<&String> {
        logged
            .iter()
            .filter(|line| line.starts_with("WARN"))
            .collect()
    }

    #[tokio::test]
    async fn one_private_client_is_warned_about_once_and_never_named() {
        let logged = logged_for(std::iter::repeat_n("10.0.0.7", 99)).await;
        assert!(
            warnings(&logged).is_empty(),
            "not before the sample is full"
        );

        let logged = logged_for(std::iter::repeat_n("10.0.0.7", 250)).await;
        let warned = warnings(&logged);
        assert_eq!(warned.len(), 1, "{logged:?}");
        assert!(warned[0].contains("TRUSTED_PROXIES"), "{}", warned[0]);
        assert!(
            !logged.iter().any(|line| line.contains("10.0.0")),
            "{logged:?}"
        );
    }

    #[tokio::test]
    async fn a_loopback_client_is_warned_about_too() {
        let logged = logged_for(std::iter::repeat_n("::1", 100)).await;
        assert_eq!(warnings(&logged).len(), 1, "{logged:?}");
        assert!(
            !logged.iter().any(|line| line.contains("::1")),
            "{logged:?}"
        );
    }

    #[tokio::test]
    async fn mixed_clients_are_not_warned_about() {
        let addresses = std::iter::repeat_n("10.0.0.7", 99)
            .chain(["10.0.0.8"])
            .chain(std::iter::repeat_n("10.0.0.7", 200));
        assert_eq!(warnings(&logged_for(addresses).await).len(), 0);
    }

    #[tokio::test]
    async fn a_public_client_is_not_warned_about() {
        let logged = logged_for(std::iter::repeat_n("203.0.113.9", 150)).await;
        assert_eq!(warnings(&logged).len(), 0);
        let addresses = ["203.0.113.9"]
            .into_iter()
            .chain(std::iter::repeat_n("10.0.0.7", 150));
        assert_eq!(warnings(&logged_for(addresses).await).len(), 0);
    }
}

//! Limits shared across replicas, counted in Postgres or Redis rather than in each
//! process, so three replicas behind a load balancer give a client one limit, not
//! three.
//!
//! A [`SharedLimiter`] counts requests per key in a fixed window, in one statement per
//! request: an upsert on Postgres, and an atomic `INCR` with `EXPIRE NX` on Redis. A
//! service names what happens while the store cannot be reached, with [`WhenDown`],
//! because only it knows whether an outage should let requests through.
//!
//! ```ignore
//! use axa_request_rate_limit::shared::{SharedLimiter, Store, WhenDown, by_client_shared};
//!
//! let store = Store::postgres(pool.clone()).await?;
//! let limiter = SharedLimiter::new(store, "api", limit, window, &secret, WhenDown::Allow)?;
//! let router = routes.layer(from_fn_with_state(limiter, by_client_shared));
//! ```
//!
//! The store holds no address: a client is counted under a hash of its address keyed
//! by the service's secret, which every replica must share.

use std::{
    fmt::Write as _,
    hash::{Hash, Hasher},
    net::IpAddr,
    num::NonZeroU32,
    sync::Arc,
};

