/// The fewest bytes the secret that keys client hashes may have.
pub const MIN_SECRET_BYTES: usize = 32;

/// How long a client is told to wait when the store is down and requests are refused.
pub const DOWN_RETRY_SECONDS: u64 = 5;

/// What happens to a request while the store cannot be reached.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WhenDown {
    /// It goes ahead uncounted, and a warning is logged. Choose this where an outage
    /// of the store must not take the service down with it.
    Allow,
    /// It is refused with a `503` problem, code `rate_limit_unavailable`, and
    /// `Retry-After`. Choose this where the limit guards something that must not be
    /// flooded.
    Refuse,
}

/// A setting that cannot make a limiter.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum SetupError {
    /// The secret is under [`MIN_SECRET_BYTES`].
    #[error("the shared limit's secret needs at least {MIN_SECRET_BYTES} bytes")]
    ShortSecret,
    /// The name is not 1 to 64 ASCII letters, digits, `_`, or `-`.
    #[error("a shared limit's name must be 1 to 64 ASCII letters, digits, _ or -")]
    BadName,
}

/// Where the counts are kept.
#[derive(Clone)]
pub enum Store {
    /// An `axa_rate_limits` table.
    #[cfg(feature = "postgres")]
    Postgres(sqlx::PgPool),
    /// Keys under `axa:ratelimit:`.
    #[cfg(feature = "redis")]
    Redis(redis::aio::ConnectionManager),
}

impl std::fmt::Debug for Store {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match *self {
            #[cfg(feature = "postgres")]
            Self::Postgres(_) => f.write_str("Postgres"),
            #[cfg(feature = "redis")]
            Self::Redis(_) => f.write_str("Redis"),
        }
    }
}

#[cfg(feature = "postgres")]
const POSTGRES_SETUP: &str = "CREATE UNLOGGED TABLE IF NOT EXISTS axa_rate_limits (
    key TEXT PRIMARY KEY,
    window_index BIGINT NOT NULL,
    count BIGINT NOT NULL
)";

/// Each row's own window length, so [`Store::purge`] ends each limit's windows by
/// its own length. A table made before 0.3.3 gains it, empty until a row is counted.
#[cfg(feature = "postgres")]
const POSTGRES_WINDOW_COLUMN: &str =
    "ALTER TABLE axa_rate_limits ADD COLUMN IF NOT EXISTS window_seconds BIGINT";

/// Counts one request in the window the database's clock is in, and answers the count
/// and the seconds until that window ends.
#[cfg(feature = "postgres")]
const POSTGRES_COUNT: &str = "WITH now AS (
    SELECT floor(extract(epoch FROM clock_timestamp()))::bigint AS second
)
INSERT INTO axa_rate_limits AS held (key, window_index, count, window_seconds)
SELECT $1, now.second / $2, 1, $2 FROM now
ON CONFLICT (key) DO UPDATE SET
    count = CASE WHEN held.window_index = EXCLUDED.window_index THEN held.count + 1 ELSE 1 END,
    window_index = EXCLUDED.window_index,
    window_seconds = EXCLUDED.window_seconds
RETURNING count, $2 - (SELECT second FROM now) % $2 AS reset";

impl Store {
    /// A Postgres store on `pool`, making its table if needed. The table is
    /// `UNLOGGED`: counts are lost if Postgres crashes, which costs at most one window.
    ///
    /// # Errors
    ///
    /// Fails when the table cannot be made.
    #[cfg(feature = "postgres")]
    pub async fn postgres(pool: sqlx::PgPool) -> Result<Self, sqlx::Error> {
        sqlx::query(POSTGRES_SETUP).execute(&pool).await?;
        sqlx::query(POSTGRES_WINDOW_COLUMN).execute(&pool).await?;
        Ok(Self::Postgres(pool))
    }

    /// A Redis store over `connection`.
    #[cfg(feature = "redis")]
    #[must_use]
    pub const fn redis(connection: redis::aio::ConnectionManager) -> Self {
        Self::Redis(connection)
    }

    /// Count one request for `key` in a window of `window` seconds, answering the count
    /// so far and the seconds until the window ends.
    async fn count(&self, key: &str, window: u32) -> Result<(u64, u64), String> {
        match self {
            #[cfg(feature = "postgres")]
            Self::Postgres(pool) => {
                use sqlx::Row;
                let row = sqlx::query(POSTGRES_COUNT)
                    .bind(key)
                    .bind(i64::from(window))
                    .fetch_one(pool)
                    .await
                    .map_err(|error| error.to_string())?;
                let count: i64 = row.try_get("count").map_err(|error| error.to_string())?;
                let reset: i64 = row.try_get("reset").map_err(|error| error.to_string())?;
                Ok((
                    u64::try_from(count).unwrap_or(0),
                    u64::try_from(reset).unwrap_or(0),
                ))
            }
            #[cfg(feature = "redis")]
            Self::Redis(connection) => {
                let mut connection = connection.clone();
                let key = format!("axa:ratelimit:{key}");
                let (count, ttl): (u64, i64) = redis::pipe()
                    .atomic()
                    .incr(&key, 1_u64)
                    .cmd("EXPIRE")
                    .arg(&key)
                    .arg(window)
                    .arg("NX")
                    .ignore()
                    .ttl(&key)
                    .query_async(&mut connection)
                    .await
                    .map_err(|error| error.to_string())?;
                Ok((count, u64::try_from(ttl).unwrap_or(u64::from(window))))
            }
        }
    }

    /// Delete counts from windows that have ended, each by its own limit's window, so
    /// limits of different lengths can share one store. `window` is used only for a
    /// row counted before 0.3.3, which has no window of its own. Redis expires its own.
    /// Run this on a schedule, such as hourly.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    // With Redis alone, there is nothing to delete or wait for.
    #[cfg_attr(
        not(feature = "postgres"),
        allow(
            unknown_lints,
            unused_variables,
            clippy::unused_async,
            clippy::unused_async_trait_impl
        )
    )]
    pub async fn purge(&self, window: NonZeroU32) -> Result<u64, String> {
        match self {
            #[cfg(feature = "postgres")]
            Self::Postgres(pool) => sqlx::query(
                "DELETE FROM axa_rate_limits
                 WHERE (window_index + 1) * COALESCE(window_seconds, $1)
                     <= floor(extract(epoch FROM clock_timestamp()))::bigint",
            )
            .bind(i64::from(window.get()))
            .execute(pool)
            .await
            .map(|done| done.rows_affected())
            .map_err(|error| error.to_string()),
            #[cfg(feature = "redis")]
            Self::Redis(_) => Ok(0),
        }
    }
}

/// A limit on requests per key in a fixed window, counted in a [`Store`] that every
/// replica shares. Clones share everything.
#[derive(Clone)]
pub struct SharedLimiter {
    inner: Arc<Inner>,
}

struct Inner {
    store: Store,
    name: String,
    limit: u32,
    window: u32,
    secret: Vec<u8>,
    when_down: WhenDown,
}

impl std::fmt::Debug for SharedLimiter {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SharedLimiter")
            .field("store", &self.inner.store)
            .field("name", &self.inner.name)
            .field("limit", &self.inner.limit)
            .field("window", &self.inner.window)
            .field("when_down", &self.inner.when_down)
            .finish_non_exhaustive()
    }
}

/// Feeds what a key's `Hash` writes into HMAC-SHA256, with every integer as fixed-width
/// little-endian bytes, so replicas built by other Rust releases or for other machines
/// count a client under the same key, as `DefaultHasher`, whose algorithm may change,
/// and `usize`'s native width and order would not.
struct KeyHasher(Hmac<Sha256>);

impl Hasher for KeyHasher {
    fn finish(&self) -> u64 {
        let digest = self.0.clone().finalize().into_bytes();
        let mut first = [0; 8];
        first.copy_from_slice(&digest[..8]);
        u64::from_le_bytes(first)
    }

    fn write(&mut self, bytes: &[u8]) {
        self.0.update(bytes);
    }

    fn write_u8(&mut self, i: u8) {
        self.0.update(&[i]);
    }

    fn write_u16(&mut self, i: u16) {
        self.0.update(&i.to_le_bytes());
    }

    fn write_u32(&mut self, i: u32) {
        self.0.update(&i.to_le_bytes());
    }

    fn write_u64(&mut self, i: u64) {
        self.0.update(&i.to_le_bytes());
    }

    fn write_u128(&mut self, i: u128) {
        self.0.update(&i.to_le_bytes());
    }

    fn write_usize(&mut self, i: usize) {
        self.write_u64(i as u64);
    }

    fn write_i8(&mut self, i: i8) {
        self.0.update(&i.to_le_bytes());
    }

    fn write_i16(&mut self, i: i16) {
        self.0.update(&i.to_le_bytes());
    }

    fn write_i32(&mut self, i: i32) {
        self.0.update(&i.to_le_bytes());
    }

    fn write_i64(&mut self, i: i64) {
        self.0.update(&i.to_le_bytes());
    }

    fn write_i128(&mut self, i: i128) {
        self.0.update(&i.to_le_bytes());
    }

    fn write_isize(&mut self, i: isize) {
        self.write_i64(i as i64);
    }
}

/// The store could not be reached, and nothing was counted.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Down;

impl SharedLimiter {
    /// `limit` requests per key in each window of `window_seconds`, counted in `store`
    /// under `name`, so two limits can share one store. `secret` keys the hash a client
    /// is counted under, and must be the same on every replica.
    ///
    /// # Errors
    ///
    /// [`SetupError`] for a short secret or a bad name.
    pub fn new(
        store: Store,
        name: &str,
        limit: NonZeroU32,
        window_seconds: NonZeroU32,
        secret: &[u8],
        when_down: WhenDown,
    ) -> Result<Self, SetupError> {
        if secret.len() < MIN_SECRET_BYTES {
            return Err(SetupError::ShortSecret);
        }
        let fits = (1..=64).contains(&name.len())
            && name
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-');
        if !fits {
            return Err(SetupError::BadName);
        }
        Ok(Self {
            inner: Arc::new(Inner {
                store,
                name: name.to_string(),
                limit: limit.get(),
                window: window_seconds.get(),
                secret: secret.to_vec(),
                when_down,
            }),
        })
    }

    /// The hash `key` is counted under, keyed by the secret, so the store never holds
    /// the key itself.
    fn hashed(&self, key: impl Hash) -> String {
        let mut hasher = KeyHasher(
            // HMAC takes a key of any length, so this cannot fail.
            Hmac::<Sha256>::new_from_slice(&self.inner.secret)
                .expect("HMAC takes a key of any length"),
        );
        key.hash(&mut hasher);
        let digest = hasher.0.finalize().into_bytes();
        let mut stored = format!("{}:", self.inner.name);
        for byte in &digest[..16] {
            let _ = write!(stored, "{byte:02x}");
        }
        stored
    }

    /// Count one request for `key`.
    ///
    /// # Errors
    ///
    /// [`Down`] when the store cannot be reached. What then happens is the caller's,
    /// as [`WhenDown`] says for the middleware.
    pub async fn check(&self, key: impl Hash) -> Result<Verdict, Down> {
        let stored = self.hashed(key);
        let (count, reset) = self
            .inner
            .store
            .count(&stored, self.inner.window)
            .await
            .map_err(|error| {
                tracing::warn!(error.msg = %error, "ratelimit_store_down");
                Down
            })?;
        let limit = u64::from(self.inner.limit);
        Ok(Verdict {
            allowed: count <= limit,
            limit: self.inner.limit,
            remaining: u32::try_from(limit.saturating_sub(count)).unwrap_or(0),
            reset_seconds: reset.max(1),
            overflowed: false,
            first_refusal: count == limit + 1,
        })
    }

    /// What [`WhenDown`] says for a request the store could not count.
    fn when_down(&self) -> Option<Response> {
        match self.inner.when_down {
            WhenDown::Allow => None,
            WhenDown::Refuse => {
                let mut response = Problem::new(StatusCode::SERVICE_UNAVAILABLE)
                    .with_extension("code", serde_json::json!("rate_limit_unavailable"))
                    .into_response();
                response
                    .headers_mut()
                    .insert(header::RETRY_AFTER, HeaderValue::from(DOWN_RETRY_SECONDS));
                Some(response)
            }
        }
    }
}

async fn shared(
    verdict: Result<Verdict, Down>,
    limiter: &SharedLimiter,
    request: Request,
    next: Next,
) -> Response {
    match verdict {
        Ok(verdict) if !verdict.allowed => verdict.refusal(),
        Ok(verdict) => {
            let mut response = next.run(request).await;
            verdict.stamp(&mut response);
            response
        }
        Err(Down) => match limiter.when_down() {
            Some(refusal) => refusal,
            None => next.run(request).await,
        },
    }
}

/// Limit each client across replicas, as [`crate::by_client`] does in one process. The
/// probes in [`EXEMPT`] are not counted.
pub async fn by_client_shared(
    State(limiter): State<SharedLimiter>,
    request: Request,
    next: Next,
) -> Response {
    if EXEMPT.contains(&request.uri().path()) {
        return next.run(request).await;
    }
    let client: Option<IpAddr> = client_key(request.extensions());
    let verdict = limiter.check(client).await;
    shared(verdict, &limiter, request, next).await
}

#[cfg(all(test, feature = "postgres"))]
mod tests {
    use super::*;

    fn limiter() -> SharedLimiter {
        let pool = sqlx::PgPool::connect_lazy("postgres://localhost/none").unwrap();
        let one = NonZeroU32::new(1).unwrap();
        SharedLimiter::new(
            Store::Postgres(pool),
            "api",
            one,
            one,
            &[7; 32],
            WhenDown::Refuse,
        )
        .unwrap()
    }

    #[tokio::test]
    async fn a_key_is_counted_under_one_hash_on_every_build() {
        let limiter = limiter();
        // HMAC-SHA256 under the secret of what `"k"`'s `Hash` writes, `k` then `0xff`,
        // its first 16 bytes: computed apart from this crate, so a build whose hash
        // differs, from another Rust release or machine, fails here.
        assert_eq!(limiter.hashed("k"), "api:01754edd21ab0860ceee492554db4491");
        let client: Option<IpAddr> = Some("203.0.113.7".parse().unwrap());
        assert_eq!(limiter.hashed(client), limiter.hashed(client));
        assert_ne!(limiter.hashed(client), limiter.hashed(None::<IpAddr>));
        assert!(!limiter.hashed(client).contains("203"));
    }
}

//! Diesel pooling, migrations, and test resets, on SQLite.
//!
//! This has the same shape as `axa-postgres-diesel` and the other Axa database
//! crates, so a service can move between them by changing names: a [`Pool`], an
//! [`Error`], [`PoolConfig`], [`connect`], [`ping`], [`migrate`], [`pending`],
//! [`revert`], [`truncate`], [`dangerously_recreate`], [`is_unique_violation`],
//! and [`quote_identifier`]. A service writes its own queries with Diesel as
//! usual.
//!
//! ```ignore
//! use axa_sqlite_diesel::{PoolConfig, connect, migrate};
//! use diesel_migrations::{EmbeddedMigrations, embed_migrations};
//!
//! const MIGRATIONS: EmbeddedMigrations = embed_migrations!();
//!
//! let pool = connect(&PoolConfig::new("sqlite://data/app.db")).await?;
//! migrate(&pool, MIGRATIONS).await?;
//! ```
//!
//! # What differs for SQLite
//!
//! - **The driver blocks.** Diesel's `SqliteConnection` is synchronous, so each
//!   pooled connection is a `diesel-async` [`SyncConnectionWrapper`] around one,
//!   which runs every query on Tokio's blocking threads.
//! - **SQLite is C.** It is compiled from source into the binary through
//!   `libsqlite3-sys` with its `bundled` feature, at the version `sqlx` pins, so a
//!   service that also uses `sqlx` links one SQLite. Nothing is needed on the host.
//! - **URLs** are `sqlite://path` (`sqlite:///absolute/path` for an absolute one,
//!   or `sqlite:path`) or `sqlite::memory:`. Anything else is refused with
//!   [`Error::InvalidUri`]. The path is handed to SQLite as a `file:` URI, so query
//!   parameters such as `?mode=ro` reach it, and a `%`, `?`, or `#` in the path
//!   must be percent-encoded. A file that does not exist is created, unless the
//!   URL says `mode=ro` or `mode=rw`; a file in a directory that does not exist is
//!   an error.
//! - **In memory**, `sqlite::memory:` gives each pool its own database, shared by
//!   all of that pool's connections, as `sqlx` does. It lasts while the pool holds
//!   at least one connection, and is gone when the last one closes.
//! - **Every connection** is opened with `PRAGMA foreign_keys = ON`, `PRAGMA
//!   busy_timeout` set to [`PoolConfig::busy_timeout`], and, for a file, `PRAGMA
//!   journal_mode = WAL`. SQLite allows one writer at a time: a second waits up to
//!   the busy timeout, then fails with `database is locked`.
//! - **No TLS.** There is no network, so there is nothing like the Postgres
//!   crate's `web_tls` or `pool_with_tls`. [`pool`] builds a pool without
//!   connecting.
//! - **[`truncate`]** deletes every row of each table and resets its
//!   `AUTOINCREMENT` counter in `sqlite_sequence`, in one transaction. SQLite has
//!   no `TRUNCATE ... CASCADE`, so where Postgres also empties the tables that
//!   reference one, here foreign keys are checked at the end of the transaction:
//!   the tables named may be in any order, but a row elsewhere that still points
//!   at a deleted one makes the whole call fail, and nothing is deleted.
//! - **[`dangerously_recreate`]** drops every table and view in `sqlite_schema`
//!   other than SQLite's own (`sqlite_%`), with foreign keys off, in one
//!   transaction. SQLite has no enum types to drop.

use std::{
    process,
    sync::atomic::{AtomicU64, Ordering},
    time::Duration,
};

use deadpool::Runtime;
pub use diesel;
use diesel::{
    Connection as _, ConnectionError, ConnectionResult, QueryableByName, RunQueryDsl,
    SqliteConnection,
    connection::SimpleConnection,
    migration::MigrationSource,
    result::{DatabaseErrorKind, Error as QueryError},
    sql_types::{BigInt, Text},
    sqlite::Sqlite,
};
pub use diesel_async;
use diesel_async::{
    pooled_connection::{
        AsyncDieselConnectionManager, ManagerConfig,
        deadpool::{BuildError, Object, Pool as DeadPool, PoolError},
    },
    sync_connection_wrapper::SyncConnectionWrapper,
};
pub use diesel_migrations;
use diesel_migrations::MigrationHarness;

/// One SQLite connection, usable from async code.
pub type AsyncSqliteConnection = SyncConnectionWrapper<SqliteConnection>;

/// A connection pool.
pub type Pool = DeadPool<AsyncSqliteConnection>;

/// A pooled connection.
pub type Connection = Object<AsyncSqliteConnection>;

/// A failure in this crate.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// The pool could not be built.
    #[error(transparent)]
    Build(#[from] BuildError),
    /// No connection could be had.
    #[error(transparent)]
    Pool(#[from] PoolError),
    /// A query failed.
    #[error(transparent)]
    Query(#[from] QueryError),
    /// A migration failed.
    #[error("migration failed: {0}")]
    Migration(String),
    /// A table name was refused by [`quote_identifier`].
    #[error("invalid identifier: {0}")]
    InvalidIdentifier(String),
    /// The URL is neither `sqlite://path`, `sqlite:path`, nor `sqlite::memory:`.
    #[error("invalid SQLite URL: expected sqlite://path or sqlite::memory:")]
    InvalidUri,
}

/// Pool settings. The URL is left out of the `Debug` text, as it may name a
/// private path or, for other databases, hold a password.
#[derive(Clone, PartialEq, Eq)]
pub struct PoolConfig {
    /// URL, `sqlite://path` or `sqlite::memory:`.
    pub uri: String,
    /// Largest number of connections.
    pub max_connections: usize,
    /// How long a caller waits for a connection, whether a free one or a new one,
    /// before it gets an error.
    pub wait_timeout: Duration,
    /// How long a statement waits for another connection's lock on the database
    /// before it fails with `database is locked`.
    pub busy_timeout: Duration,
}

impl std::fmt::Debug for PoolConfig {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PoolConfig")
            .field("max_connections", &self.max_connections)
            .field("wait_timeout", &self.wait_timeout)
            .field("busy_timeout", &self.busy_timeout)
            .finish_non_exhaustive()
    }
}

impl PoolConfig {
    /// Settings for `uri` with a small pool.
    #[must_use]
    pub fn new(uri: impl Into<String>) -> Self {
        Self {
            uri: uri.into(),
            max_connections: 10,
            wait_timeout: Duration::from_secs(5),
            busy_timeout: Duration::from_secs(5),
        }
    }
}

/// What SQLite is asked to open.
#[derive(Debug, PartialEq, Eq)]
struct Target {
    /// A `file:` URI.
    uri: String,
    /// Whether it is a file, which gets WAL, rather than memory.
    file: bool,
}

/// Turn an `sqlite:` URL into what SQLite opens, or `None` for anything else.
fn target(uri: &str) -> Option<Target> {
    static MEMORY: AtomicU64 = AtomicU64::new(0);
    if uri == "sqlite::memory:" {
        let n = MEMORY.fetch_add(1, Ordering::Relaxed);
        let id = process::id();
        return Some(Target {
            uri: format!("file:axa-memory-{id}-{n}?mode=memory&cache=shared"),
            file: false,
        });
    }
    let rest = uri
        .strip_prefix("sqlite://")
        .or_else(|| uri.strip_prefix("sqlite:"))?;
    let path = rest.split(['?', '#']).next().unwrap_or_default();
    if path.is_empty() || path.starts_with(':') {
        return None;
    }
    let query = rest.split_once('?').map_or("", |(_, query)| query);
    let memory = query.split('&').any(|pair| pair == "mode=memory");
    Some(Target {
        uri: format!("file:{rest}"),
        file: !memory,
    })
}

/// The statements every new connection runs.
fn pragmas(file: bool, busy_timeout: Duration) -> String {
    let busy = i32::try_from(busy_timeout.as_millis()).unwrap_or(i32::MAX);
    let mut sql = format!("PRAGMA busy_timeout = {busy}; PRAGMA foreign_keys = ON;");
    if file {
        sql.push_str(" PRAGMA journal_mode = WAL;");
    }
    sql
}

/// Open one connection on a blocking thread and set it up.
async fn establish(uri: String, setup: String) -> ConnectionResult<AsyncSqliteConnection> {
    let connection = tokio::task::spawn_blocking(move || {
        let mut connection = SqliteConnection::establish(&uri)?;
        connection
            .batch_execute(&setup)
            .map_err(ConnectionError::CouldntSetupConfiguration)?;
        Ok::<_, ConnectionError>(connection)
    })
    .await
    .map_err(|error| ConnectionError::BadConnection(error.to_string()))??;
    Ok(SyncConnectionWrapper::new(connection))
}

/// Build a pool without connecting yet.
///
/// # Errors
///
/// Fails on a URL that is not `sqlite:`, or when the pool's settings are invalid.
pub fn pool(config: &PoolConfig) -> Result<Pool, Error> {
    let target = target(&config.uri).ok_or(Error::InvalidUri)?;
    let setup = pragmas(target.file, config.busy_timeout);
    let mut manager_config = ManagerConfig::default();
    manager_config.custom_setup =
        Box::new(move |uri| Box::pin(establish(uri.to_string(), setup.clone())));
    let manager = AsyncDieselConnectionManager::new_with_config(target.uri, manager_config);
    // With no limit, a caller waits for ever behind a pool that is all in use.
    Ok(Pool::builder(manager)
        .max_size(config.max_connections)
        .wait_timeout(Some(config.wait_timeout))
        .create_timeout(Some(config.wait_timeout))
        .runtime(Runtime::Tokio1)
        .build()?)
}

/// Open a pool and prove it works with one connection.
///
/// # Errors
///
/// Fails on a URL that is not `sqlite:`, or when the database cannot be opened.
pub async fn connect(config: &PoolConfig) -> Result<Pool, Error> {
    let pool = pool(config)?;
    ping(&pool).await?;
    Ok(pool)
}

/// Check that the database answers.
///
/// # Errors
///
/// Fails when it does not.
pub async fn ping(pool: &Pool) -> Result<(), Error> {
    blocking(pool, |connection| Ok(connection.batch_execute("SELECT 1")?)).await
}

/// Whether an error is a violated unique constraint, which a service usually
/// reports as `409` rather than `500`. A duplicate primary key counts too, as
/// Diesel reports both the same way.
#[must_use]
pub fn is_unique_violation(error: &QueryError) -> bool {
    matches!(
        error,
        QueryError::DatabaseError(DatabaseErrorKind::UniqueViolation, _)
    )
}

/// Quote a table name for use in SQL.
///
/// Identifiers cannot be bound as parameters, so this is the one place names
/// reach SQL as text. Only lowercase ASCII letters, digits, and underscores
/// are accepted, starting with a letter or underscore.
///
/// ```
/// assert_eq!(axa_sqlite_diesel::quote_identifier("users").as_deref(), Some("\"users\""));
/// assert_eq!(axa_sqlite_diesel::quote_identifier("users; DROP TABLE x"), None);
/// ```
#[must_use]
pub fn quote_identifier(name: &str) -> Option<String> {
    let mut chars = name.chars();
    let first = chars.next()?;
    let valid = (first.is_ascii_lowercase() || first == '_')
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    valid.then(|| format!("\"{name}\""))
}

/// Quote every name, failing on the first one [`quote_identifier`] refuses.
fn quote_all<S: AsRef<str>>(names: &[S]) -> Result<Vec<String>, Error> {
    names
        .iter()
        .map(|name| {
            quote_identifier(name.as_ref())
                .ok_or_else(|| Error::InvalidIdentifier(name.as_ref().to_string()))
        })
        .collect()
}

/// Run `work` on the synchronous connection inside a pooled one, on a blocking
/// thread.
async fn blocking<T, F>(pool: &Pool, work: F) -> Result<T, Error>
where
    T: Send + 'static,
    F: FnOnce(&mut SqliteConnection) -> Result<T, Error> + Send + 'static,
{
    let mut connection = pool.get().await?;
    connection
        .spawn_blocking(move |inner| Ok(work(inner)))
        .await?
}

/// Turn a migration error into this crate's.
#[expect(
    clippy::needless_pass_by_value,
    reason = "map_err hands it over by value"
)]
fn migration_error(error: Box<dyn std::error::Error + Send + Sync>) -> Error {
    Error::Migration(error.to_string())
}

/// Apply pending migrations, returning how many ran.
///
/// # Errors
///
/// Fails when a migration fails.
pub async fn migrate<M>(pool: &Pool, migrations: M) -> Result<usize, Error>
where
    M: MigrationSource<Sqlite> + Send + 'static,
{
    blocking(pool, move |connection| {
        connection
            .run_pending_migrations(migrations)
            .map(|applied| applied.len())
            .map_err(migration_error)
    })
    .await
}

/// Revert the newest `steps` migrations, returning how many were reverted.
///
/// # Errors
///
/// Fails when a down migration fails.
pub async fn revert<M>(pool: &Pool, migrations: M, steps: usize) -> Result<usize, Error>
where
    M: MigrationSource<Sqlite> + Clone + Send + 'static,
{
    blocking(pool, move |connection| {
        let mut reverted = 0;
        while reverted < steps {
            let applied = connection.applied_migrations().map_err(migration_error)?;
            if applied.is_empty() {
                break;
            }
            connection
                .revert_last_migration(migrations.clone())
                .map_err(migration_error)?;
            reverted += 1;
        }
        Ok(reverted)
    })
    .await
}

/// The names of migrations that have not run, in the order they would run.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending<M>(pool: &Pool, migrations: M) -> Result<Vec<String>, Error>
where
    M: MigrationSource<Sqlite> + Send + 'static,
{
    blocking(pool, move |connection| {
        let pending = connection
            .pending_migrations(migrations)
            .map_err(migration_error)?;
        Ok(pending
            .iter()
            .map(|migration| migration.name().to_string())
            .collect())
    })
    .await
}

/// One count from a catalog query.
#[derive(QueryableByName)]
struct Count {
    #[diesel(sql_type = BigInt)]
    n: i64,
}

/// One name from a catalog query.
#[derive(QueryableByName)]
struct Name {
    #[diesel(sql_type = Text)]
    kind: String,
    #[diesel(sql_type = Text)]
    name: String,
}

/// Empty `tables`, resetting their `AUTOINCREMENT` counters, in one
/// transaction. Each name goes through [`quote_identifier`] before anything is
/// deleted.
///
/// Foreign keys are checked when the transaction ends, so the tables may be
/// named in any order, but a row in a table left out that still references a
/// deleted row fails the call, and nothing is deleted.
///
/// # Errors
///
/// Fails on an invalid name, a foreign key left dangling, or a database error.
pub async fn truncate<S: AsRef<str>>(pool: &Pool, tables: &[S]) -> Result<(), Error> {
    if tables.is_empty() {
        return Ok(());
    }
    let quoted = quote_all(tables)?;
    let names: Vec<String> = tables
        .iter()
        .map(|name| name.as_ref().to_string())
        .collect();
    blocking(pool, move |connection| {
        connection
            .immediate_transaction(|connection| {
                connection.batch_execute("PRAGMA defer_foreign_keys = ON")?;
                for table in &quoted {
                    diesel::sql_query(format!("DELETE FROM {table}")).execute(connection)?;
                }
                let sequence: Count = diesel::sql_query(
                    "SELECT count(*) AS n FROM sqlite_schema WHERE name = 'sqlite_sequence'",
                )
                .get_result(connection)?;
                if sequence.n > 0 {
                    for name in &names {
                        diesel::sql_query("DELETE FROM sqlite_sequence WHERE name = ?")
                            .bind::<Text, _>(name)
                            .execute(connection)?;
                    }
                }
                Ok(())
            })
            .map_err(Error::Query)
    })
    .await
}

/// Drop every table and view, then migrate from nothing. This gives each test
/// an empty schema, whatever tables it touched.
///
/// **This destroys all data.** It exists for tests, and a service must never
/// reach it outside the `test` environment.
///
/// Every table and view in `sqlite_schema` is dropped other than SQLite's own
/// (`sqlite_%`), with foreign keys off, in one transaction, so a failure drops
/// nothing. Foreign keys are turned back on afterwards, whether or not it
/// worked.
///
/// # Errors
///
/// Fails on a database error, a failed migration, or a name
/// [`quote_identifier`] refuses.
pub async fn dangerously_recreate<M>(pool: &Pool, migrations: M) -> Result<(), Error>
where
    M: MigrationSource<Sqlite> + Send + 'static,
{
    blocking(pool, |connection| {
        connection.batch_execute("PRAGMA foreign_keys = OFF")?;
        let dropped = drop_everything(connection);
        let restored = connection.batch_execute("PRAGMA foreign_keys = ON");
        dropped?;
        restored?;
        Ok(())
    })
    .await?;
    migrate(pool, migrations).await?;
    Ok(())
}

/// Drop every table and view other than SQLite's own, views first.
fn drop_everything(connection: &mut SqliteConnection) -> Result<(), Error> {
    let objects: Vec<Name> = diesel::sql_query(
        "SELECT type AS kind, name FROM sqlite_schema
         WHERE type IN ('table', 'view') AND name NOT LIKE 'sqlite\\_%' ESCAPE '\\'
         ORDER BY type = 'table', name",
    )
    .load(connection)?;
    let names: Vec<&str> = objects.iter().map(|object| object.name.as_str()).collect();
    let quoted = quote_all(&names)?;
    connection.immediate_transaction(|connection| {
        for (object, name) in objects.iter().zip(&quoted) {
            let kind = if object.kind == "view" {
                "VIEW"
            } else {
                "TABLE"
            };
            // A virtual table's shadow tables go with it, so they may be gone.
            diesel::sql_query(format!("DROP {kind} IF EXISTS {name}")).execute(connection)?;
        }
        Ok::<_, Error>(())
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn debug_text_leaves_out_the_url() {
        let text = format!("{:?}", PoolConfig::new("sqlite:///srv/secret-name.db"));
        assert!(!text.contains("secret-name"), "{text}");
        assert!(text.contains("max_connections"), "{text}");
        assert!(text.contains("busy_timeout"), "{text}");
    }

    #[test]
    fn identifiers_are_quoted() {
        assert_eq!(quote_identifier("users").as_deref(), Some("\"users\""));
        assert_eq!(quote_identifier("_x1").as_deref(), Some("\"_x1\""));
    }

    #[test]
    fn unsafe_identifiers_are_refused() {
        for name in [
            "", "1users", "Users", "a b", "a\"b", "a;b", "a.b", "users--", "a`b",
        ] {
            assert_eq!(quote_identifier(name), None, "{name:?}");
        }
    }

    #[test]
    fn quote_all_fails_on_any_bad_name() {
        assert!(quote_all(&["good"]).is_ok());
        assert!(matches!(
            quote_all(&["good", "bad name"]),
            Err(Error::InvalidIdentifier(name)) if name == "bad name"
        ));
    }

    #[test]
    fn errors_that_are_not_from_the_database_are_not_unique_violations() {
        assert!(!is_unique_violation(&QueryError::NotFound));
    }

    #[test]
    fn sqlite_urls_become_file_uris() {
        assert_eq!(
            target("sqlite://data/app.db"),
            Some(Target {
                uri: "file:data/app.db".into(),
                file: true
            })
        );
        assert_eq!(
            target("sqlite:///srv/app.db?mode=ro"),
            Some(Target {
                uri: "file:/srv/app.db?mode=ro".into(),
                file: true
            })
        );
        assert_eq!(
            target("sqlite:app.db"),
            Some(Target {
                uri: "file:app.db".into(),
                file: true
            })
        );
        assert_eq!(
            target("sqlite://shared?mode=memory&cache=shared").map(|t| t.file),
            Some(false)
        );
    }

    #[test]
    fn each_memory_url_names_a_database_of_its_own() {
        let one = target("sqlite::memory:").unwrap();
        let two = target("sqlite::memory:").unwrap();
        assert!(!one.file);
        assert!(one.uri.contains("mode=memory&cache=shared"), "{}", one.uri);
        assert_ne!(one.uri, two.uri);
    }

    #[test]
    fn urls_that_are_not_sqlite_are_refused() {
        for uri in [
            "",
            "app.db",
            "postgres://localhost/app",
            "mysql://localhost/app",
            "sqlite:",
            "sqlite://",
            "sqlite://?mode=memory",
            "sqlite::nonsense:",
        ] {
            assert_eq!(target(uri), None, "{uri:?}");
        }
    }

    #[test]
    fn only_files_get_wal() {
        let file = pragmas(true, Duration::from_millis(1500));
        assert!(file.contains("busy_timeout = 1500"), "{file}");
        assert!(file.contains("foreign_keys = ON"), "{file}");
        assert!(file.contains("journal_mode = WAL"), "{file}");
        let memory = pragmas(false, Duration::from_secs(1));
        assert!(memory.contains("foreign_keys = ON"), "{memory}");
        assert!(!memory.contains("WAL"), "{memory}");
    }

    #[test]
    fn a_huge_busy_timeout_is_capped() {
        let sql = pragmas(false, Duration::from_secs(u64::MAX));
        assert!(
            sql.contains(&format!("busy_timeout = {}", i32::MAX)),
            "{sql}"
        );
    }
}

//! A SQLite job queue, worker pool, and recurring schedules: the SQLite twin of
//! `axa-postgres-job-queue`, with the same API and the same behaviour, for a service
//! on one machine.
//!
//! Jobs live in one `axa_queue` table. Each job loop claims the ready job with the
//! highest priority, oldest first, in a single `UPDATE ... RETURNING`. SQLite runs one
//! writer at a time, so two loops, or two processes on the same file, can never claim
//! the same row, and no broker is needed. The database is opened in WAL mode, with a
//! five-second wait for the write lock.
//!
//! Every time is kept as microseconds since the Unix epoch, in UTC, on the database's
//! clock. SQLite is a file: every process using a queue must be on the machine that
//! holds it.
//!
//! ```no_run
//! use std::time::Duration;
//! use axa_sqlite_job_queue::{NewJob, Queue, QueueOptions, Schedule};
//! use tokio::sync::watch;
//!
//! # async fn example(uri: &str) -> axa_sqlite_job_queue::Result<()> {
//! let mut queue = Queue::connect(uri, QueueOptions::default()).await?;
//! queue.handle("Report", |args| async move {
//!     let id = args["id"].as_i64().ok_or("no id")?;
//!     println!("report {id}");
//!     Ok::<(), &str>(())
//! });
//! queue.limit("Report", 1); // at most one at a time in this process
//! queue.schedule(Schedule::every(
//!     "nightly-report",
//!     Duration::from_hours(24),
//!     NewJob::new("Report", serde_json::json!({ "id": 0 })),
//! ));
//!
//! let id = queue
//!     .enqueue_job(&NewJob::new("Report", serde_json::json!({ "id": 7 })).run_in(Duration::from_mins(5)))
//!     .await?;
//! let queue = std::sync::Arc::new(queue);
//! let (stop, stopped) = watch::channel(false);
//! let jobs = tokio::spawn(queue.clone().run(stopped));
//! // ... serve until told to stop, then:
//! let _ = stop.send(true);
//! let _ = jobs.await;
//! # let _ = id;
//! # Ok(())
//! # }
//! ```
//!
//! A job moves from `queued` to `running` to `completed` or `failed`, with the
//! failure text kept on the row. A queued job can be `cancelled`.
//!
//! # A person's acts
//!
//! A job row is state: it changes as the job runs, and retention deletes it. What a
//! person does to a job is a record. [`cancel()`] stops a queued job, and [`retry()`]
//! queues a failed one again or releases one from review. Each takes the caller's
//! transaction and a `by` and `reason`, and appends the act to `axa_job_acts` in the
//! same statement as the change, so the act, the change, and the service's own audit
//! row commit together or not at all. There is no form that takes a pool. An act that
//! does not apply, such as cancelling a running job, changes nothing and writes no
//! act.
//!
//! ```no_run
//! # async fn example(queue: &axa_sqlite_job_queue::Queue, id: uuid::Uuid) -> axa_sqlite_job_queue::Result<()> {
//! let mut transaction = queue.pool().begin().await?;
//! let cancelled = axa_sqlite_job_queue::cancel(&mut transaction, id, "ops:alice", "customer_asked").await?;
//! // ... write the service's own audit row on the same transaction ...
//! transaction.commit().await?;
//! # let _ = cancelled;
//! # Ok(())
//! # }
//! ```
//!
//! `by` and `reason` are codes, not content: at most [`MAX_REASON_CHARS`] characters
//! with no line breaks, and the table refuses anything else. `axa_job_acts` is only
//! ever inserted into, and its triggers refuse `UPDATE` and `DELETE`, whoever sends
//! them. SQLite has no `TRUNCATE`. An act names its job by id, with no foreign key, so
//! it outlives the job's row. [`Queue::acts`] reads a job's acts.
//!
//! # Attempts
//!
//! A job gets [`QueueOptions::max_attempts`] tries, unless it was queued with its
//! own limit. The default is one, because a retry repeats the job's work, and only
//! its author knows that is safe. Each retry waits about twice as long as the last,
//! starting from [`QueueOptions::retry_backoff`], spread at random over the upper
//! half of that wait so jobs that failed together do not all come back at once. A
//! handler that knows better, such as from a receiver's `Retry-After`, returns
//! [`RetryAfter`] as its error. A job that panics counts as failed, and its loop
//! carries on.
//!
//! # Lost jobs
//!
//! A running job reports in every [`QueueOptions::heartbeat_interval`], so a job
//! may run for as long as it needs. One not heard from for
//! [`QueueOptions::stale_minutes`] is assumed lost with its worker. If it has
//! attempts left it is queued again, and otherwise it is marked failed, so a crash
//! can never loop for ever. Each claim is identified by its attempt, so a run that
//! was given up on cannot then overwrite the result of its replacement.
//!
//! # How many at once
//!
//! A process runs [`QueueOptions::workers`] job loops, so at most that many jobs at
//! once. [`Queue::limit`] caps one job type below that, in this process. A limit is
//! per process and not across replicas: three processes with a limit of one may run
//! three. Work that must never overlap anywhere needs a lock of its own.
//!
//! # When a job runs
//!
//! [`NewJob::run_in`] and [`NewJob::run_at`] delay a job, and [`NewJob::priority`]
//! puts it ahead of others that are ready. Delay is measured on the database's
//! clock. A delayed job is claimed only once it is due, and then about as soon as a
//! loop next polls.
//!
//! # Schedules
//!
//! A [`Schedule`] queues a job every interval. Each due time becomes one ordinary
//! job, so its retries, status, limit, and recovery are the queue's. The schedule's
//! row in `axa_schedule` is locked while its job is queued, in the same
//! transaction, so across any number of replicas each due time is queued once.
//!
//! - **No drift.** The next time is counted from when the last was due, not from
//!   when it ran.
//! - **Missed times run once.** After every process was down, one job is queued,
//!   and the schedule keeps its place: the next time is still a whole number of
//!   intervals from the first.
//! - **No stacking.** When the schedule's last job is still queued or running at a
//!   due time, that time is skipped.
//! - **The first time** is [`Schedule::first_at`], or as soon as the row is made.
//!   It applies only when the row is made, so a schedule every 24 hours first due
//!   at 02:00 runs at 02:00 each day, on the database's clock in UTC.
//!
//! [`Schedule::cron`] queues a job at the times a cron pattern names, such as
//! `"0 2 * * *"` for 02:00 each day, in UTC on the database's clock. Its due times
//! are the pattern's, so the same three rules hold: each due time is queued once, times
//! missed while every process was down queue one job and the next time is the
//! pattern's next after now, and a due time is skipped while the last job is queued or
//! running. Its first time is the pattern's next after the row is made, and a changed
//! pattern takes its next time from the new pattern.
//!
//! [`Queue::run`] ticks the schedules on every poll, and a service with no job
//! loops can call [`Queue::tick_schedules`] itself. A schedule's job type must be
//! handled by some worker, or its jobs wait. A schedule removed from code leaves a
//! row that nothing reads.
//!
//! # One job at a time per key
//!
//! [`NewJob::unique`] names a key, such as `"sync:42"`, and while a job of the same
//! name, tenant, and key is queued or running, queuing another adds nothing and
//! answers the id of the one there. The first job's arguments, priority, and time
//! stand. Once it completes, fails, is cancelled, or goes to review, the key is free
//! again. The table holds to this with a unique index, so it holds across
//! replicas and for a job queued in a transaction that has not yet committed: a
//! second enqueue of the key waits for that transaction, and then either finds its
//! job or queues its own. [`retry()`] leaves a failed job alone while another of its
//! key is queued or running.
//!
//! # Queuing inside a transaction
//!
//! [`enqueue_on`] takes the caller's transaction, so a job and the record it is
//! about commit together or not at all. [`Queue::enqueue`] uses its own
//! connection, so a job queued that way can outlive a rollback.
//!
//! # Personal data
//!
//! The `args` column is plain JSON text, and finished rows are deleted after
//! [`QueueOptions::retention_days`], so a job table does not become a second copy
//! of the data. Prefer an id to a snapshot, and never put a secret in arguments.
//! [`JobInfo`] leaves the arguments out. Its error text is whatever the job's
//! error said, so it is for operators, and is not to be sent to a client. An act
//! keeps no arguments either, and nothing logs its `by` or `reason`.

use std::{
    collections::{HashMap, HashSet},
    fmt,
    future::Future,
    pin::Pin,
    sync::Arc,
    time::Duration,
};

use sqlx::{
    AssertSqlSafe, Row, Sqlite, SqliteConnection, SqliteExecutor, SqlitePool, Transaction,
    sqlite::{SqliteConnectOptions, SqliteJournalMode, SqlitePoolOptions},
};
use tokio::sync::{OwnedSemaphorePermit, Semaphore, watch};
use uuid::Uuid;

/// An instant, in UTC: every time the queue keeps or takes. Re-exported from `jiff`, so
/// a service needs no dependency of its own to name one.
pub use jiff::Timestamp;

/// What this crate's functions return.
pub type Result<T, E = Error> = std::result::Result<T, E>;

/// What went wrong.
#[derive(Debug)]
#[non_exhaustive]
pub enum Error {
    /// The database refused or could not be reached.
    Database(sqlx::Error),
    /// A job's arguments could not be encoded.
    Encode(serde_json::Error),
    /// A job failed, or the queue met something it cannot read.
    Job(String),
    /// Who or why, given for a person's act, or a job's unique key, is empty,
    /// longer than [`MAX_REASON_CHARS`], or has a line break.
    NotACode {
        /// Which it was: `by`, `reason`, or `unique key`.
        what: &'static str,
    },
    /// A job's tenant is not a tenant id: see [`is_tenant_id`].
    NotATenant,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Database(error) => error.fmt(f),
            Self::Encode(error) => error.fmt(f),
            Self::Job(text) => write!(f, "worker error: {text}"),
            Self::NotACode { what } => write!(
                f,
                "`{what}` must be 1 to {MAX_REASON_CHARS} characters with no line breaks"
            ),
            Self::NotATenant => f.write_str(
                "a job's tenant must be 1 to 63 lower-case letters, digits, and hyphens, \
                 not starting or ending with a hyphen",
            ),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Database(error) => Some(error),
            Self::Encode(error) => Some(error),
            Self::Job(_) | Self::NotACode { .. } | Self::NotATenant => None,
        }
    }
}

impl From<sqlx::Error> for Error {
    fn from(error: sqlx::Error) -> Self {
        Self::Database(error)
    }
}

impl From<serde_json::Error> for Error {
    fn from(error: serde_json::Error) -> Self {
        Self::Encode(error)
    }
}

type JobFuture = Pin<Box<dyn Future<Output = Result<(), Failure>> + Send>>;
type Handler = Arc<dyn Fn(Option<String>, serde_json::Value) -> JobFuture + Send + Sync>;

/// What a job queued for a tenant fails with when its handler takes no tenant.
const NO_TENANT_HANDLER: &str =
    "the job has a tenant, and its handler takes none: register it with handle_with_tenant";

/// Now, as microseconds since the Unix epoch, on the database's clock. SQLite keeps
/// one `now` for a whole statement, so every use in a statement agrees.
macro_rules! now {
    () => {
        "CAST(unixepoch('subsec') * 1000000 AS INTEGER)"
    };
}

/// Times are microseconds since the Unix epoch, in UTC, so they compare exactly.
const SETUP: &str = "CREATE TABLE IF NOT EXISTS axa_queue (
    id BLOB PRIMARY KEY,
    name TEXT NOT NULL,
    args TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'queued',
    error TEXT,
    attempts INTEGER NOT NULL DEFAULT 0,
    max_attempts INTEGER,
    priority INTEGER NOT NULL DEFAULT 0,
    timeout_ms INTEGER,
    tenant TEXT CHECK (tenant IS NULL OR (length(tenant) BETWEEN 1 AND 63
        AND tenant NOT GLOB '*[^a-z0-9-]*' AND tenant NOT GLOB '-*' AND tenant NOT GLOB '*-')),
    unique_key TEXT CHECK (unique_key IS NULL OR (length(unique_key) BETWEEN 1 AND 200
        AND NOT unique_key GLOB ('*[' || char(1) || '-' || char(31) || char(127) || '-' || char(159) || ']*'))),
    run_at INTEGER NOT NULL,
    started_at INTEGER,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
) STRICT";
const SETUP_CLAIM_INDEX: &str = "CREATE INDEX IF NOT EXISTS axa_queue_claim
    ON axa_queue (priority DESC, run_at) WHERE status = 'queued'";
/// At most one job queued or running per name, tenant, and key.
const SETUP_UNIQUE_INDEX: &str = "CREATE UNIQUE INDEX IF NOT EXISTS axa_queue_unique
    ON axa_queue (name, coalesce(tenant, ''), unique_key)
    WHERE unique_key IS NOT NULL AND status IN ('queued', 'running')";
const SETUP_STALE_INDEX: &str = "CREATE INDEX IF NOT EXISTS axa_queue_stale
