mod tests {
    use super::*;

    #[test]
    fn each_retry_waits_twice_as_long_up_to_a_limit() {
        let base = Duration::from_secs(30);
        assert_eq!(backoff(base, 1), base);
        assert_eq!(backoff(base, 2), base * 2);
        assert_eq!(backoff(base, 3), base * 4);
        assert_eq!(backoff(base, 1_000), MAX_BACKOFF);
    }

    #[test]
    fn a_retry_waits_a_jittered_backoff_or_the_delay_the_job_chose() {
        let base = Duration::from_secs(30);
        for _ in 0..200 {
            let wait = retry_wait(base, 2, None);
            assert!(wait >= base && wait <= base * 2, "{wait:?}");
        }
        let waits: HashSet<_> = (0..20).map(|_| retry_wait(base, 1, None)).collect();
        assert!(waits.len() > 1, "the waits are spread");
        assert_eq!(retry_wait(Duration::ZERO, 3, None), Duration::ZERO);
        let chosen = Some(Duration::from_secs(90));
        assert_eq!(retry_wait(base, 1, chosen), Duration::from_secs(90));
        assert_eq!(retry_wait(base, 1, Some(Duration::ZERO)), MIN_RETRY_AFTER);
        assert_eq!(
            retry_wait(base, 1, Some(Duration::from_hours(9))),
            MAX_BACKOFF
        );
    }

    #[test]
    fn a_retry_after_error_carries_its_delay_and_others_none() {
        let chosen = Failure::from_error(RetryAfter::new(Duration::from_secs(7), "busy"));
        assert_eq!(
            (chosen.text.as_str(), chosen.retry_in),
            ("busy", Some(Duration::from_secs(7)))
        );
        let boxed: Box<dyn std::error::Error + Send + Sync> =
            Box::new(RetryAfter::new(Duration::from_secs(8), "boxed"));
        assert_eq!(
            Failure::from_error(boxed).retry_in,
            Some(Duration::from_secs(8))
        );
        let plain = Failure::from_error("broken".to_string());
        assert_eq!((plain.text.as_str(), plain.retry_in), ("broken", None));
    }

    #[test]
    fn the_debug_text_leaves_out_arguments() {
        let job = NewJob::new("Report", serde_json::json!({ "nhs": "943 476 5919" }));
        let schedule = Schedule::every("nightly", Duration::from_hours(1), job.clone());
        let cron = Schedule::cron("at-two", "0 2 * * *", job.clone());
        for text in [
            format!("{job:?}"),
            format!("{schedule:?}"),
            format!("{cron:?}"),
        ] {
            assert!(text.contains("Report"), "{text}");
            assert!(!text.contains("943"), "{text}");
        }
    }

    #[test]
    fn a_by_or_reason_that_is_not_a_code_is_refused() {
        assert!(check_code("ops:alice", "by").is_ok());
        assert!(check_code(&"é".repeat(MAX_REASON_CHARS), "reason").is_ok());
        for bad in [
            String::new(),
            "é".repeat(MAX_REASON_CHARS + 1),
            "two\nlines".to_string(),
            "a\ttab".to_string(),
        ] {
            let error = check_code(&bad, "reason").unwrap_err();
            assert!(matches!(error, Error::NotACode { what: "reason" }));
            assert!(!error.to_string().contains("lines"), "the text is left out");
        }
    }

    #[test]
    fn a_long_error_is_cut_on_a_character_boundary() {
        let text = "é".repeat(MAX_ERROR);
        let kept = cut(text);
        assert!(kept.len() <= MAX_ERROR);
        assert!(kept.chars().all(|c| c == 'é'));
        assert_eq!(cut("short".to_string()), "short");
    }

    #[test]
    #[should_panic(expected = "at least a second")]
    fn a_schedule_under_a_second_is_refused_at_boot() {
        let _ = Schedule::every(
            "fast",
            Duration::from_millis(10),
            NewJob::new("J", serde_json::Value::Null),
        );
    }

    #[test]
    #[should_panic(expected = "bad cron pattern")]
    fn a_bad_cron_pattern_is_refused_at_boot() {
        let _ = Schedule::cron(
            "bad",
            "61 * * * *",
            NewJob::new("J", serde_json::Value::Null),
        );
    }

    #[test]
    fn a_cron_schedule_names_its_next_times_in_utc() {
        let schedule = Schedule::cron(
            "weekdays",
            "0 9 * * MON-FRI",
            NewJob::new("J", serde_json::Value::Null),
        );
        assert_eq!(schedule.cron_pattern(), Some("0 9 * * MON-FRI"));
        assert_eq!(schedule.interval(), None);
        let Times::Cron(cron, _) = &schedule.times else {
            panic!("a cron schedule")
        };
        // Friday 2026-11-13 09:00 UTC is due, so the next after it is Monday's.
        let friday: Timestamp = "2026-11-13T09:00:00Z".parse().unwrap();
        let monday: Timestamp = "2026-11-16T09:00:00Z".parse().unwrap();
        assert_eq!(next_after(cron, friday).unwrap(), monday);
        assert_eq!(
            Schedule::every(
                "e",
                Duration::from_secs(5),
                NewJob::new("J", serde_json::Value::Null)
            )
            .interval(),
            Some(Duration::from_secs(5))
        );
    }

    #[test]
    fn a_cron_schedule_counts_in_utc_across_a_month_end_and_a_clock_change() {
        let next = |pattern: &str, after: &str| {
            let cron: croner::Cron = pattern.parse().unwrap();
            next_after(&cron, after.parse().unwrap())
                .unwrap()
                .to_string()
        };
        // The 31st skips a month of 30 days, and the year end is an ordinary midnight.
        assert_eq!(
            next("0 0 31 * *", "2026-11-15T00:00:00Z"),
            "2026-12-31T00:00:00Z"
        );
        assert_eq!(
            next("30 23 * * *", "2026-12-31T23:30:00Z"),
            "2027-01-01T23:30:00Z"
        );
        assert_eq!(
            next("0 12 29 2 *", "2026-03-01T00:00:00Z"),
            "2028-02-29T12:00:00Z"
        );
        // Clocks in Europe go forward at 01:00 UTC on 2026-03-29 and back at 01:00 UTC
        // on 2026-10-25, and in the US back on 2026-11-01. UTC has no such change, so
        // 01:30 comes once each day, 24 hours apart.
        assert_eq!(
            next("30 1 * * *", "2026-03-28T01:30:00Z"),
            "2026-03-29T01:30:00Z"
        );
        assert_eq!(
            next("30 1 * * *", "2026-10-25T01:30:00Z"),
            "2026-10-26T01:30:00Z"
        );
        assert_eq!(
            next("0 6 * * *", "2026-11-01T06:00:00Z"),
            "2026-11-02T06:00:00Z"
        );
        // A time part way through a second goes on to the next whole one.
        assert_eq!(
            next("* * * * * *", "2026-11-15T00:00:00.5Z"),
            "2026-11-15T00:00:01Z"
        );
    }

    #[test]
    #[should_panic(expected = "1 to 200 characters")]
    fn a_schedule_with_no_name_is_refused_at_boot() {
        let _ = Schedule::every(
            "",
            Duration::from_secs(1),
            NewJob::new("J", serde_json::Value::Null),
        );
    }

    #[tokio::test]
    #[should_panic(expected = "added twice")]
    async fn a_schedule_added_twice_is_refused_at_boot() {
        let pool = SqlitePoolOptions::new()
            .connect_lazy("sqlite::memory:")
            .unwrap();
        let mut queue = Queue::from_pool(pool, QueueOptions::default());
        let job = NewJob::new("J", serde_json::Value::Null);
        queue.schedule(Schedule::every("a", Duration::from_secs(5), job.clone()));
        queue.schedule(Schedule::every("a", Duration::from_secs(9), job));
    }

    #[test]
    fn a_schedule_ignores_a_delay_on_its_job() {
        let job = NewJob::new("J", serde_json::Value::Null).run_in(Duration::from_hours(1));
        let schedule = Schedule::every("s", Duration::from_secs(5), job);
        assert_eq!(schedule.job.when, When::Now);
    }
}

//! `SeaORM` connections, migrations, schema helpers, and test resets, on SQLite.
//!
//! This crate is the SQLite twin of `axa-postgres-seaorm`, and has the same shape as
//! the other Axa database crates: a [`Pool`], a [`PoolConfig`], [`connect`],
//! [`ping`], [`migrate`], [`revert`], [`pending`], [`truncate`],
//! [`dangerously_recreate`], [`is_unique_violation`], and [`quote_identifier`]. The
//! migration functions take the service's `Migrator` as a type, as
//! `sea-orm-migration` does.
//!
//! What differs for SQLite:
//!
//! - URLs are `sqlite://path` or `sqlite::memory:`. A file that does not exist is not
//!   made unless the URL asks for it with `?mode=rwc`. An in-memory database is shared
//!   by the pool's connections, and is gone when the last one closes.
//! - Every connection turns on foreign keys, waits up to
//!   [`PoolConfig::busy_timeout_ms`] for a lock, and, for a file, uses WAL.
//! - [`truncate`] is `DELETE FROM` each table, in one transaction with foreign key
//!   checks deferred to its commit, and clears the tables' rows in
//!   `sqlite_sequence`, so `AUTOINCREMENT` starts again at 1. SQLite has no
//!   `TRUNCATE` and no `CASCADE`: a table whose rows are still referenced from a table
//!   not in the list makes the whole call fail, and nothing is emptied.
//! - [`dangerously_recreate`] drops every table in `sqlite_schema` other than
//!   SQLite's own, on one connection with foreign keys off and in one transaction,
//!   then migrates from the start.
//! - [`schema::add_column`] can add only a column SQLite can add to a table that
//!   exists: one that is not unique or a primary key, and, once the table has rows,
//!   is nullable or has a default. SQLite refuses others with an error. No helper
//!   here changes a column's type or nullability, because SQLite's `ALTER TABLE`
//!   cannot. A foreign key that [`schema::create_table`] makes keeps no name.
//!
//! It also makes leaving Loco easy. A project keeps `SeaORM` and most of its code,
//! because the helpers Loco provided keep their names and behaviour:
//!
//! | Loco | Here |
//! |---|---|
//! | `loco_rs::model::{ModelError, ModelResult}` | `axa::model`, for every database |
//! | `loco_rs::model::query::condition()` | [`query::condition`] |
//! | `loco_rs::schema` | [`schema`] |
//! | `loco_rs::validation::Validatable` | `axa::validation`, for every database |
//! | `loco_rs::db::truncate_table` | [`truncate_table`] |
//!
//! ```no_run
//! use axa_sqlite_seaorm::{PoolConfig, connect};
//!
//! # async fn run() -> Result<(), axa_sqlite_seaorm::sea_orm::DbErr> {
//! let db = connect(&PoolConfig::new("sqlite://app.db?mode=rwc")).await?;
//! # Ok(())
//! # }
//! ```

use std::{sync::Arc, time::Duration};

pub use sea_orm;
use sea_orm::{
    ConnectOptions, ConnectionTrait, Database, DatabaseConnection, DbErr, EntityTrait, RuntimeErr,
    SqlErr, TransactionTrait,
    sqlx::{self, AssertSqlSafe, SqliteConnection, sqlite::SqliteJournalMode},
};
pub use sea_orm_migration;
use sea_orm_migration::MigratorTrait;

pub mod query;
pub mod schema;

/// The handle a service holds: `SeaORM`'s connection, which owns a pool.
pub type Pool = DatabaseConnection;

/// What this crate's functions return on failure.
pub type Error = DbErr;

/// Pool settings.
#[derive(Clone, PartialEq, Eq)]
pub struct PoolConfig {
    /// Connection string: `sqlite://path` or `sqlite::memory:`.
    pub uri: String,
    /// Connections kept open.
    pub min_connections: u32,
    /// Largest number of connections.
    pub max_connections: u32,
    /// How long to wait for a connection, in milliseconds.
    pub connect_timeout_ms: u64,
    /// How long an idle connection stays open, in milliseconds.
    pub idle_timeout_ms: u64,
    /// How long a statement waits for another connection's lock, in milliseconds.
    pub busy_timeout_ms: u64,
    /// Log every statement.
    pub enable_logging: bool,
}

impl std::fmt::Debug for PoolConfig {
    /// Leaves the connection string out, as every Axa database crate does, because
    /// for other databases it can carry a password.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PoolConfig")
            .field("min_connections", &self.min_connections)
            .field("max_connections", &self.max_connections)
            .field("connect_timeout_ms", &self.connect_timeout_ms)
            .field("idle_timeout_ms", &self.idle_timeout_ms)
            .field("busy_timeout_ms", &self.busy_timeout_ms)
            .field("enable_logging", &self.enable_logging)
            .finish_non_exhaustive()
    }
}

impl PoolConfig {
    /// Settings for `uri` with a small pool.
    #[must_use]
    pub fn new(uri: impl Into<String>) -> Self {
        Self {
            uri: uri.into(),
            min_connections: 1,
            max_connections: 10,
            connect_timeout_ms: 5_000,
            idle_timeout_ms: 600_000,
            busy_timeout_ms: 5_000,
            enable_logging: false,
        }
    }

    /// Whether the URL names an in-memory database rather than a file.
    fn is_memory(&self) -> bool {
        self.uri.contains(":memory:") || self.uri.contains("mode=memory")
    }

    /// The `SeaORM` options these settings describe, which also set every
    /// connection's foreign keys, busy timeout, and, for a file, WAL.
    #[must_use]
    pub fn options(&self) -> ConnectOptions {
        let busy_timeout = Duration::from_millis(self.busy_timeout_ms);
        let wal = !self.is_memory();
        let mut options = ConnectOptions::new(self.uri.clone());
        options
            .min_connections(self.min_connections)
            .max_connections(self.max_connections)
            .connect_timeout(Duration::from_millis(self.connect_timeout_ms))
            .idle_timeout(Duration::from_millis(self.idle_timeout_ms))
            .sqlx_logging(self.enable_logging)
            .map_sqlx_sqlite_opts(move |sqlite| {
                let sqlite = sqlite.foreign_keys(true).busy_timeout(busy_timeout);
                if wal {
                    sqlite.journal_mode(SqliteJournalMode::Wal)
                } else {
                    sqlite
                }
            });
        options
    }
}

/// Open a pool.
///
/// # Errors
///
/// Fails when the database cannot be opened, such as a file that does not exist
/// and a URL without `?mode=rwc`.
pub async fn connect(config: &PoolConfig) -> Result<DatabaseConnection, DbErr> {
    Database::connect(config.options()).await
}

/// Delete every row of one entity's table. Rows in other tables are left
/// alone, so a test that needs a truly empty database should use
/// [`dangerously_recreate`] instead.
///
/// # Errors
///
/// Propagates the database error.
pub async fn truncate_table<T: EntityTrait>(
    db: &DatabaseConnection,
    _entity: T,
) -> Result<(), DbErr> {
    T::delete_many().exec(db).await?;
    Ok(())
}

/// Check the database connection.
///
/// # Errors
///
/// Fails when the database does not answer.
pub async fn ping(pool: &Pool) -> Result<(), DbErr> {
    pool.ping().await
}

/// Apply every pending migration of `M`.
///
/// # Errors
///
/// Fails on a database error, and then no later migration is tried.
pub async fn migrate<M: MigratorTrait>(pool: &Pool) -> Result<(), DbErr> {
    M::up(pool, None).await
}

/// Revert the last `steps` applied migrations of `M`, newest first.
///
/// # Errors
///
/// Fails on a database error.
pub async fn revert<M: MigratorTrait>(pool: &Pool, steps: u32) -> Result<(), DbErr> {
    M::down(pool, Some(steps)).await
}

/// The names of the migrations of `M` not yet applied, in order.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending<M: MigratorTrait>(pool: &Pool) -> Result<Vec<String>, DbErr> {
    Ok(M::get_pending_migrations(pool)
        .await?
        .iter()
        .map(|migration| migration.name().to_string())
        .collect())
}

fn sqlx_error(error: sqlx::Error) -> DbErr {
    DbErr::Exec(RuntimeErr::SqlxError(Arc::new(error)))
}

/// Any table name in double quotes, with its own double quotes doubled. Used only
/// for names read from `sqlite_schema`, never for a caller's.
fn quote_any(name: &str) -> String {
    format!("\"{}\"", name.replace('"', "\"\""))
}

/// Drop every table other than SQLite's own, in one transaction on `conn`, which
/// must have foreign keys off.
async fn drop_every_table(conn: &mut SqliteConnection) -> Result<(), sqlx::Error> {
    sqlx::raw_sql("BEGIN IMMEDIATE").execute(&mut *conn).await?;
    let result = async {
        let tables: Vec<String> = sqlx::query_scalar(
            "SELECT name FROM sqlite_schema
             WHERE type = 'table' AND name NOT LIKE 'sqlite\\_%' ESCAPE '\\'",
        )
        .fetch_all(&mut *conn)
        .await?;
        for table in tables {
            let drop = format!("DROP TABLE {}", quote_any(&table));
            sqlx::raw_sql(AssertSqlSafe(drop))
                .execute(&mut *conn)
                .await?;
        }
        sqlx::raw_sql("COMMIT").execute(&mut *conn).await
    }
    .await;
    if result.is_err() {
        sqlx::raw_sql("ROLLBACK").execute(&mut *conn).await.ok();
    }
    result.map(|_| ())
}

/// Drop every table, then apply every migration of `M` from the start. This
/// destroys data: `axa::cli` allows it only in development and test, and only
/// when confirmed.
///
/// The tables are those in `sqlite_schema` other than SQLite's own, dropped on one
/// connection with foreign keys off, in one transaction, so a failure drops none.
/// That connection is closed rather than returned to the pool if anything fails.
///
/// # Errors
///
/// Fails on a database error.
pub async fn dangerously_recreate<M: MigratorTrait>(pool: &Pool) -> Result<(), DbErr> {
    let mut conn = pool
        .get_sqlite_connection_pool()
        .acquire()
        .await
        .map_err(sqlx_error)?;
    let dropped = async {
        sqlx::raw_sql("PRAGMA foreign_keys = OFF")
            .execute(&mut *conn)
            .await?;
        drop_every_table(&mut conn).await?;
        sqlx::raw_sql("PRAGMA foreign_keys = ON")
            .execute(&mut *conn)
            .await
            .map(|_| ())
    }
    .await;
    if let Err(error) = dropped {
        conn.close().await.ok();
        return Err(sqlx_error(error));
    }
    drop(conn);
    M::up(pool, None).await
}

/// Whether `error` is the database refusing a duplicate under a unique constraint,
/// a primary key's included.
#[must_use]
pub fn is_unique_violation(error: &DbErr) -> bool {
    matches!(error.sql_err(), Some(SqlErr::UniqueConstraintViolation(_)))
}

/// `name` in double quotes, when it is a plain lower-case identifier: a letter or
/// `_`, then letters, digits, and `_`. Anything else is refused, so it cannot carry
/// SQL.
#[must_use]
pub fn quote_identifier(name: &str) -> Option<String> {
    let mut chars = name.chars();
    let first = chars.next()?;
    let valid = (first.is_ascii_lowercase() || first == '_')
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    valid.then(|| format!("\"{name}\""))
}

/// Empty `tables` for a test, and start their `AUTOINCREMENT` again at 1. Every
/// name must be a plain lower-case identifier. [`truncate_table`] empties one
/// entity's table.
///
/// Each table is emptied with `DELETE FROM`, in one transaction, with foreign key
/// checks deferred to its commit, so the tables can be listed in any order. A row
/// left in another table that still refers to an emptied one fails the commit, and
/// then nothing is emptied.
///
/// # Errors
///
/// Fails on a database error, or a name that is not a plain identifier, before
/// anything is emptied.
pub async fn truncate<S: AsRef<str>>(pool: &Pool, tables: &[S]) -> Result<(), DbErr> {
    if tables.is_empty() {
        return Ok(());
    }
    let tables = tables
        .iter()
        .map(|name| {
            quote_identifier(name.as_ref())
                .ok_or_else(|| DbErr::Custom(format!("invalid identifier: {}", name.as_ref())))
        })
        .collect::<Result<Vec<_>, _>>()?;
    let txn = pool.begin().await?;
    txn.execute_unprepared("PRAGMA defer_foreign_keys = ON")
        .await?;
    for table in &tables {
        txn.execute_unprepared(&format!("DELETE FROM {table}"))
            .await?;
    }
    let has_sequence = txn
        .query_one_raw(sea_orm::Statement::from_string(
            sea_orm::DbBackend::Sqlite,
            "SELECT 1 FROM sqlite_schema WHERE type = 'table' AND name = 'sqlite_sequence'",
        ))
        .await?
        .is_some();
    if has_sequence {
        // A quoted plain identifier is also a safe string literal once its double
        // quotes become single ones.
        let names = tables
            .iter()
            .map(|table| table.replace('"', "'"))
            .collect::<Vec<_>>()
            .join(", ");
        txn.execute_unprepared(&format!(
            "DELETE FROM sqlite_sequence WHERE name IN ({names})"
        ))
        .await?;
    }
    txn.commit().await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn identifiers_are_quoted_and_unsafe_ones_refused() {
        assert_eq!(quote_identifier("users").as_deref(), Some("\"users\""));
        for name in ["", "1users", "Users", "a b", "a\"b", "a;b", "a.b", "a'b"] {
            assert_eq!(quote_identifier(name), None, "{name:?}");
        }
    }

    #[test]
    fn any_name_read_from_the_schema_is_quoted_safely() {
        assert_eq!(quote_any("odd \"name\""), "\"odd \"\"name\"\"\"");
    }

    #[test]
    fn errors_that_are_not_from_the_database_are_not_unique_violations() {
        assert!(!is_unique_violation(&DbErr::Custom("nothing".to_string())));
    }

    #[test]
    fn debug_text_leaves_out_the_connection_string() {
        let text = format!("{:?}", PoolConfig::new("sqlite:///srv/hunter2/app.db"));
        assert!(!text.contains("hunter2"), "{text}");
        assert!(text.contains("max_connections"), "{text}");
        assert!(text.contains("busy_timeout_ms"), "{text}");
    }

    #[test]
    fn the_default_timeouts_suit_a_real_database() {
        let config = PoolConfig::new("sqlite://x");
        assert_eq!(config.connect_timeout_ms, 5_000);
        assert_eq!(config.idle_timeout_ms, 600_000);
        assert_eq!(config.busy_timeout_ms, 5_000);
    }

    #[test]
    fn in_memory_urls_are_told_from_files() {
        assert!(PoolConfig::new("sqlite::memory:").is_memory());
        assert!(PoolConfig::new("sqlite://app.db?mode=memory").is_memory());
        assert!(!PoolConfig::new("sqlite://app.db?mode=rwc").is_memory());
    }

    #[test]
    fn pool_settings_reach_the_options() {
        let config = PoolConfig {
            min_connections: 2,
            max_connections: 7,
            connect_timeout_ms: 1_500,
            idle_timeout_ms: 9_500,
            ..PoolConfig::new("sqlite://x")
        };
        let options = config.options();
        assert_eq!(options.get_min_connections(), Some(2));
        assert_eq!(options.get_max_connections(), Some(7));
        assert_eq!(
            options.get_connect_timeout(),
            Some(Duration::from_millis(1_500))
        );
        assert_eq!(
            options.get_idle_timeout(),
            Some(Some(Duration::from_millis(9_500)))
        );
    }
}

//! A small condition builder.
//!
//! It has the shape of Loco's, so code using it moves across unchanged. New
//! code can use `SeaORM` directly, which is just as short:
//! `Column::Email.eq(email)`.
//!
//! ```
//! use axa_sqlite_seaorm::query::condition;
//! # use axa_sqlite_seaorm::sea_orm::{self, entity::prelude::*};
//! # mod users {
//! #     use axa_sqlite_seaorm::sea_orm::{self, entity::prelude::*};
//! #     #[derive(Clone, Debug, PartialEq, DeriveEntityModel)]
//! #     #[sea_orm(table_name = "users")]
//! #     pub struct Model {
//! #         #[sea_orm(primary_key)]
//! #         pub id: i32,
//! #         pub email: String,
//! #     }
//! #     #[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
//! #     pub enum Relation {}
//! #     impl ActiveModelBehavior for ActiveModel {}
//! # }
//! let filter = condition().eq(users::Column::Email, "a@example.org").build();
//! ```

use sea_orm::{ColumnTrait, Condition, Value};

/// A set of conditions, all of which must hold.
#[derive(Debug, Clone)]
pub struct ConditionBuilder {
    condition: Condition,
}

/// Start an empty condition.
#[must_use]
pub fn condition() -> ConditionBuilder {
    ConditionBuilder {
        condition: Condition::all(),
    }
}

impl ConditionBuilder {
    /// Add a column equality.
    #[must_use]
    pub fn eq<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.eq(value))
    }

    /// Add a column inequality.
    #[must_use]
    pub fn ne<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.ne(value))
    }

    /// Add a "greater than" comparison.
    #[must_use]
    pub fn gt<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.gt(value))
    }

    /// Add a "greater than or equal" comparison.
    #[must_use]
    pub fn gte<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.gte(value))
    }

    /// Add a "less than" comparison.
    #[must_use]
    pub fn lt<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.lt(value))
    }

    /// Add a "less than or equal" comparison.
    #[must_use]
    pub fn lte<T: ColumnTrait, V: Into<Value>>(self, col: T, value: V) -> Self {
        self.with(col.lte(value))
    }

    /// Require a column to be null.
    #[must_use]
    pub fn is_null<T: ColumnTrait>(self, col: T) -> Self {
        self.with(col.is_null())
    }

    /// Require a column not to be null.
    #[must_use]
    pub fn is_not_null<T: ColumnTrait>(self, col: T) -> Self {
        self.with(col.is_not_null())
    }

    /// Require a column to be one of `values`.
    #[must_use]
    pub fn is_in<T, V, I>(self, col: T, values: I) -> Self
    where
        T: ColumnTrait,
        V: Into<Value>,
        I: IntoIterator<Item = V>,
    {
        self.with(col.is_in(values))
    }

    /// Require a column to contain `text`. `%` and `_` in `text` act as `LIKE`
    /// wildcards, so escape text that came from a user.
    #[must_use]
    pub fn contains<T: ColumnTrait>(self, col: T, text: &str) -> Self {
        self.with(col.contains(text))
    }

    /// Add any `SeaORM` condition, for what this builder does not cover.
    #[must_use]
    pub fn with(mut self, condition: impl sea_orm::sea_query::IntoCondition) -> Self {
        self.condition = self.condition.add(condition.into_condition());
        self
    }

    /// Finish.
    #[must_use]
    pub fn build(&self) -> Condition {
        self.condition.clone()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use sea_orm::{DbBackend, QueryFilter, QueryTrait, entity::prelude::*};

    mod users {
        use sea_orm::entity::prelude::*;

        #[derive(Clone, Debug, PartialEq, DeriveEntityModel)]
        #[sea_orm(table_name = "users")]
        pub struct Model {
            #[sea_orm(primary_key)]
            pub id: i32,
            pub email: String,
            pub age: i32,
            pub deleted_at: Option<DateTimeWithTimeZone>,
        }

        #[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
        pub enum Relation {}

        impl ActiveModelBehavior for ActiveModel {}
    }

    use users::{Column, Entity};

    fn sql(builder: &ConditionBuilder) -> String {
        Entity::find()
            .filter(builder.build())
            .build(DbBackend::Sqlite)
            .to_string()
    }

    #[test]
    fn eq_and_ne_compare_values() {
        assert!(sql(&condition().eq(Column::Email, "a")).contains(r#""email" = 'a'"#));
        assert!(sql(&condition().ne(Column::Email, "a")).contains(r#""email" <> 'a'"#));
    }

    #[test]
    fn ordering_comparisons_use_their_operators() {
        assert!(sql(&condition().gt(Column::Age, 1)).contains(r#""age" > 1"#));
        assert!(sql(&condition().gte(Column::Age, 1)).contains(r#""age" >= 1"#));
        assert!(sql(&condition().lt(Column::Age, 1)).contains(r#""age" < 1"#));
        assert!(sql(&condition().lte(Column::Age, 1)).contains(r#""age" <= 1"#));
    }

    #[test]
    fn null_checks_use_is_null() {
        assert!(sql(&condition().is_null(Column::DeletedAt)).contains("IS NULL"));
        assert!(sql(&condition().is_not_null(Column::DeletedAt)).contains("IS NOT NULL"));
    }

    #[test]
    fn membership_lists_every_value() {
        assert!(sql(&condition().is_in(Column::Age, [1, 2])).contains("IN (1, 2)"));
    }

    #[test]
    fn contains_wraps_the_text_in_wildcards() {
        assert!(sql(&condition().contains(Column::Email, "ab")).contains("LIKE '%ab%'"));
    }

    #[test]
    fn several_conditions_must_all_hold() {
        let text = sql(&condition().eq(Column::Email, "a").gt(Column::Age, 1));
        assert!(text.contains(" AND "), "{text}");
    }

    #[test]
    fn an_empty_condition_filters_nothing() {
        // Rendered as `WHERE TRUE`, which matches every row.
        assert!(sql(&condition()).ends_with("WHERE TRUE"));
    }

    #[test]
    fn with_accepts_a_seaorm_condition() {
        let text = sql(&condition().with(Column::Email.eq("a")));
        assert!(text.contains(r#""email" = 'a'"#), "{text}");
    }
}

//! Migration helpers over `sea-orm-migration`, on SQLite.
//!
//! [`create_table`] adds `created_at` and `updated_at` with a
//! `CURRENT_TIMESTAMP` default, and table names are pluralised, so migrations
//! written against these helpers produce the schema they always have.
//!
//! What differs from Postgres:
//!
//! - Column types are sea-query's SQLite names, which SQLite stores by affinity:
//!   a timestamp, UUID, or JSON column holds text, a boolean holds 0 or 1, and
//!   [`ColType::PkAuto`] is `integer PRIMARY KEY AUTOINCREMENT`, a 64-bit rowid.
//!   `CURRENT_TIMESTAMP` is UTC text, `YYYY-MM-DD HH:MM:SS`.
//! - A foreign key keeps no name, because sea-query writes none for SQLite. Its
//!   column, parent, and actions are as on Postgres.
//! - [`add_column`] can add only what SQLite's `ALTER TABLE ADD COLUMN` can: a
//!   column that is not unique or a primary key, and, once the table has rows, is
//!   nullable or has a default. SQLite refuses the others with an error.
//! - [`remove_column`] needs SQLite 3.35 or later, which the bundled library is,
//!   and SQLite refuses to drop a column that is in an index, a key, or a
//!   constraint.
//! - There is no helper to change a column's type or nullability, on any database,
//!   and SQLite could not do it in place: it needs the table rebuilt.

use heck::ToSnakeCase;
use sea_orm::{ConnectionTrait, DbBackend, DbErr, Statement};
use sea_orm_migration::{
    prelude::*,
    schema::{
        big_integer, big_integer_null, big_pk_auto, boolean, boolean_null, date, date_null, double,
        double_null, integer, integer_null, pk_uuid, string, string_null, string_uniq, text,
        text_null, timestamp_with_time_zone, timestamp_with_time_zone_null, uuid, uuid_null,
        uuid_uniq,
    },
    sea_query::{ForeignKeyAction, Table},
};

/// A column type.
#[derive(Debug, Clone, PartialEq)]
#[non_exhaustive]
pub enum ColType {
    /// 64-bit auto-increment primary key.
    PkAuto,
    /// UUID primary key.
    PkUuid,
    /// Required string.
    String,
    /// Optional string.
    StringNull,
    /// Required unique string.
    StringUniq,
    /// Required text.
    Text,
    /// Optional text.
    TextNull,
    /// Required 32-bit integer.
    Integer,
    /// Optional 32-bit integer.
    IntegerNull,
    /// Required 64-bit integer.
    BigInteger,
    /// Optional 64-bit integer.
    BigIntegerNull,
    /// Required double.
    Double,
    /// Optional double.
    DoubleNull,
    /// Required boolean.
    Boolean,
    /// Optional boolean.
    BooleanNull,
    /// Required boolean with a default.
    BooleanWithDefault(bool),
    /// Required date.
    Date,
    /// Optional date.
    DateNull,
    /// Required timestamp with time zone.
    TimestampWithTimeZone,
    /// Optional timestamp with time zone.
    TimestampWithTimeZoneNull,
    /// Required UUID.
    Uuid,
    /// Optional UUID.
    UuidNull,
    /// Required unique UUID.
    UuidUniq,
    /// Required JSON, held as text on SQLite.
    JsonBinary,
    /// Optional JSON, held as text on SQLite.
    JsonBinaryNull,
}

impl ColType {
    fn to_def(&self, name: Alias) -> ColumnDef {
        match self {
            Self::PkAuto => big_pk_auto(name),
            Self::PkUuid => pk_uuid(name),
            Self::String => string(name),
            Self::StringNull => string_null(name),
            Self::StringUniq => string_uniq(name),
            Self::Text => text(name),
            Self::TextNull => text_null(name),
            Self::Integer => integer(name),
            Self::IntegerNull => integer_null(name),
            Self::BigInteger => big_integer(name),
            Self::BigIntegerNull => big_integer_null(name),
            Self::Double => double(name),
            Self::DoubleNull => double_null(name),
            Self::Boolean => boolean(name),
            Self::BooleanNull => boolean_null(name),
            Self::BooleanWithDefault(value) => boolean(name).default(*value).take(),
            Self::Date => date(name),
            Self::DateNull => date_null(name),
            Self::TimestampWithTimeZone => timestamp_with_time_zone(name),
            Self::TimestampWithTimeZoneNull => timestamp_with_time_zone_null(name),
            Self::Uuid => uuid(name),
            Self::UuidNull => uuid_null(name),
            Self::UuidUniq => uuid_uniq(name),
            Self::JsonBinary => ColumnDef::new(name).json_binary().not_null().take(),
            Self::JsonBinaryNull => ColumnDef::new(name).json_binary().null().take(),
        }
    }
}

fn normalize_table(table: &str) -> std::string::String {
    cruet::to_plural(table).to_snake_case()
}

fn reference_id(table: &str) -> std::string::String {
    format!("{}_id", cruet::to_singular(table).to_snake_case())
}

/// Create a table with `created_at` and `updated_at`.
///
/// `refs` lists `(parent_table, column)`. An empty column means
/// `<parent>_id`, and a `?` suffix on the parent makes the reference
/// optional.
///
/// # Errors
///
/// Propagates the database error.
pub async fn create_table(
    m: &SchemaManager<'_>,
    table: &str,
    cols: &[(&str, ColType)],
    refs: &[(&str, &str)],
) -> Result<(), DbErr> {
    let table = normalize_table(table);
    let mut stmt = Table::create()
        .table(Alias::new(&table))
        .if_not_exists()
        .take();
    stmt.col(timestamp_with_time_zone(Alias::new("created_at")).default(Expr::current_timestamp()));
    stmt.col(timestamp_with_time_zone(Alias::new("updated_at")).default(Expr::current_timestamp()));
    for (name, col) in cols {
        stmt.col(col.to_def(Alias::new(*name)));
    }
    for (parent, column) in refs {
        let (parent, nullable) = parent.strip_suffix('?').map_or_else(
            || (normalize_table(parent), false),
            |stripped| (normalize_table(stripped), true),
        );
        let column = if column.is_empty() {
            reference_id(&parent)
        } else {
            (*column).to_string()
        };
        if !cols.iter().any(|(name, _)| *name == column) {
            let col = if nullable {
                ColType::BigIntegerNull
            } else {
                ColType::BigInteger
            };
            stmt.col(col.to_def(Alias::new(&column)));
        }
        let mut fk = ForeignKey::create();
        fk.name(format!("fk-{table}-{column}-to-{parent}"));
        fk.from(Alias::new(&table), Alias::new(&column));
        fk.to(Alias::new(parent), Alias::new("id"));
        if nullable {
            fk.on_delete(ForeignKeyAction::SetNull);
            fk.on_update(ForeignKeyAction::NoAction);
        } else {
            fk.on_delete(ForeignKeyAction::Cascade);
            fk.on_update(ForeignKeyAction::Cascade);
        }
        stmt.foreign_key(&mut fk);
    }
    m.create_table(stmt).await
}

/// Drop a table.
///
/// # Errors
///
/// Propagates the database error.
pub async fn drop_table(m: &SchemaManager<'_>, table: &str) -> Result<(), DbErr> {
    m.drop_table(
        Table::drop()
            .table(Alias::new(normalize_table(table)))
            .to_owned(),
    )
    .await
}

/// Add a column. SQLite can add only one that is not unique or a primary key,
/// and, once the table has rows, is nullable or has a default, such as
/// [`ColType::TextNull`] or [`ColType::BooleanWithDefault`].
///
/// # Errors
///
/// Propagates the database error, which is SQLite refusing any other column.
pub async fn add_column(
    m: &SchemaManager<'_>,
    table: &str,
    name: &str,
    col: ColType,
) -> Result<(), DbErr> {
    m.alter_table(
        Table::alter()
            .table(Alias::new(normalize_table(table)))
            .add_column(col.to_def(Alias::new(name)))
            .to_owned(),
    )
    .await
}

/// Remove a column.
///
/// It runs in a transaction of its own, or a savepoint when `m` is already in one,
/// that reads the schema first. SQLite looks a dropped column up in the schema the
/// connection last read, and, unlike other statements, does not read it again when
/// the column is missing, so a column added on another of the pool's connections
/// would otherwise not be found.
///
/// # Errors
///
/// Propagates the database error, such as SQLite refusing a column in an index,
/// a key, or a constraint.
pub async fn remove_column(m: &SchemaManager<'_>, table: &str, name: &str) -> Result<(), DbErr> {
    let txn = m.begin().await?;
    txn.get_connection()
        .query_one_raw(Statement::from_string(
            DbBackend::Sqlite,
            "SELECT count(*) FROM sqlite_schema",
        ))
        .await?;
    txn.alter_table(
        Table::alter()
            .table(Alias::new(normalize_table(table)))
            .drop_column(Alias::new(name))
            .to_owned(),
    )
    .await?;
    txn.commit().await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_names_are_pluralised_snake_case() {
        assert_eq!(normalize_table("user"), "users");
        assert_eq!(normalize_table("users"), "users");
        assert_eq!(normalize_table("CarePathway"), "care_pathways");
    }

    #[test]
    fn reference_columns_are_singular() {
        assert_eq!(reference_id("users"), "user_id");
    }
}

//! `SQLite` pooling, migrations, and test resets over sqlx.
//!
//! This crate holds the operations every service repeats. It does not wrap
//! queries: a service writes its own SQL with `sqlx::query!`, so a reviewer
//! reads exactly what runs.
//!
//! It has the same shape as `axa-postgres-sqlx`, `axa-postgres-seaorm`,
//! `axa-postgres-diesel`, and `axa-postgres-toasty`: a [`Pool`], a
//! [`PoolConfig`], [`connect`], [`ping`], [`migrate`], [`revert`], [`pending`],
//! [`truncate`], [`dangerously_recreate`], [`is_unique_violation`], and
//! [`quote_identifier`], with [`status`] besides. What differs for `SQLite`:
//!
//! - A URL is `sqlite://path` or `sqlite::memory:`, and anything not
//!   starting with `sqlite:` is refused. A missing file is not
//!   created unless the URL asks with `?mode=rwc`, so a mistyped path fails
//!   rather than opening an empty database.
//! - Every connection is opened with `PRAGMA foreign_keys = ON`, a busy
//!   timeout ([`PoolConfig::busy_timeout_ms`], five seconds by default), and
//!   WAL. An in-memory database cannot use WAL, so `SQLite` keeps its own
//!   memory journal there. One `sqlite::memory:` pool is one database, shared
//!   by its connections, and it is gone when the pool closes.
//! - [`migrate`] takes no lock, because sqlx's `SQLite` migrator has none.
//!   Each migration runs in its own transaction, so a migration is never
//!   applied twice, but two processes migrating one file at the same moment
//!   can see one of them fail. Migrate from one process at a time.
//! - [`truncate`] is `DELETE FROM` each table, with autoincrement counters
//!   cleared, in one transaction. `SQLite` has no `TRUNCATE ... CASCADE`: a
//!   table still referenced from a table not listed, without `ON DELETE
//!   CASCADE`, makes the call fail and change nothing.
//! - [`dangerously_recreate`] drops every table and view in `sqlite_schema`
//!   other than `SQLite`'s own. There are no enum types or extensions to
//!   consider.
//! - There is no network, so no TLS.
//!
//! ```no_run
//! use axa_sqlite_sqlx::{PoolConfig, connect, migrate, sqlx};
//!
//! static MIGRATOR: sqlx::migrate::Migrator = sqlx::migrate::Migrator::DEFAULT;
//!
//! # async fn run() -> Result<(), Box<dyn std::error::Error>> {
//! let pool = connect(&PoolConfig::new("sqlite://app.db")).await?;
//! migrate(&pool, &MIGRATOR).await?;
//! # Ok(())
//! # }
//! ```

use std::{
    ops::{Deref, DerefMut},
    time::Duration,
};

pub use sqlx;
use sqlx::{
    AssertSqlSafe, Row, Sqlite, SqliteConnection, SqlitePool,
    migrate::{MigrateError, Migrator},
    pool::PoolConnection,
    sqlite::{SqliteConnectOptions, SqliteJournalMode, SqlitePoolOptions},
};

/// The handle a service holds: the pool.
pub type Pool = SqlitePool;

/// What this crate's connection and query functions return on failure.
pub type Error = sqlx::Error;

/// Pool settings.
#[derive(Clone, PartialEq, Eq)]
pub struct PoolConfig {
    /// Connection string: `sqlite://path` or `sqlite::memory:`.
    pub uri: String,
    /// Connections kept open.
    pub min_connections: u32,
    /// Largest number of connections.
    pub max_connections: u32,
    /// How long to wait for a connection, in milliseconds.
    pub connect_timeout_ms: u64,
    /// How long an idle connection stays open, in milliseconds.
    pub idle_timeout_ms: u64,
    /// How long a connection waits for another's write lock, in milliseconds.
    pub busy_timeout_ms: u64,
}

impl std::fmt::Debug for PoolConfig {
    /// Leaves the connection string out, as every crate of this shape does,
    /// because for other databases it can carry a password.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PoolConfig")
            .field("min_connections", &self.min_connections)
            .field("max_connections", &self.max_connections)
            .field("connect_timeout_ms", &self.connect_timeout_ms)
            .field("idle_timeout_ms", &self.idle_timeout_ms)
            .field("busy_timeout_ms", &self.busy_timeout_ms)
            .finish_non_exhaustive()
    }
}

impl PoolConfig {
    /// Settings for `uri` with a small pool and a five-second busy timeout.
    #[must_use]
    pub fn new(uri: impl Into<String>) -> Self {
        Self {
            uri: uri.into(),
            min_connections: 1,
            max_connections: 10,
            connect_timeout_ms: 5_000,
            idle_timeout_ms: 600_000,
            busy_timeout_ms: 5_000,
        }
    }

    /// The sqlx pool options these settings describe.
    #[must_use]
    pub fn options(&self) -> SqlitePoolOptions {
        SqlitePoolOptions::new()
            .min_connections(self.min_connections)
            .max_connections(self.max_connections)
            .acquire_timeout(Duration::from_millis(self.connect_timeout_ms))
            .idle_timeout(Duration::from_millis(self.idle_timeout_ms))
    }

    /// The options each connection is opened with: the URL, with foreign
    /// keys on, WAL, and the busy timeout.
    ///
    /// Each call to this for `sqlite::memory:` names a new in-memory database.
    ///
    /// # Errors
    ///
    /// Fails when the URL does not start with `sqlite:` or cannot be read.
    /// Sqlx alone would take any other text as a file name.
    pub fn connect_options(&self) -> Result<SqliteConnectOptions, sqlx::Error> {
        if !self.uri.starts_with("sqlite:") {
            return Err(sqlx::Error::Configuration(
                "a SQLite URL starts with `sqlite:`".into(),
            ));
        }
        Ok(self
            .uri
            .parse::<SqliteConnectOptions>()?
            .foreign_keys(true)
            .journal_mode(SqliteJournalMode::Wal)
            .busy_timeout(Duration::from_millis(self.busy_timeout_ms)))
    }
}

/// Open a pool and prove it works with one connection.
///
/// # Errors
///
/// Fails when the URL cannot be read or the database cannot be opened.
pub async fn connect(config: &PoolConfig) -> Result<SqlitePool, sqlx::Error> {
    config
        .options()
        .connect_with(config.connect_options()?)
        .await
}

/// Check that the database answers.
///
/// # Errors
///
/// Fails when it does not.
pub async fn ping(pool: &SqlitePool) -> Result<(), sqlx::Error> {
    sqlx::query("SELECT 1").execute(pool).await?;
    Ok(())
}

/// Where a function gets its connection: the pool, or a connection the caller
/// holds, usually an open transaction, so one function serves both.
///
/// `impl sqlx::Acquire` says the same, but its associated types stop the future
/// being `Send`, which Axum handlers and `tokio::spawn` need.
///
/// ```no_run
/// use axa_sqlite_sqlx::{Db, sqlx};
///
/// async fn count(db: impl Into<Db<'_>>) -> Result<i64, sqlx::Error> {
///     let mut conn = db.into().acquire().await?;
///     sqlx::query_scalar("SELECT count(*) FROM items")
///         .fetch_one(&mut *conn)
///         .await
/// }
/// ```
pub enum Db<'a> {
    /// Take a connection from the pool for the length of the call.
    Pool(&'a SqlitePool),
    /// Use the caller's connection.
    Conn(&'a mut SqliteConnection),
}

impl<'a> From<&'a SqlitePool> for Db<'a> {
    fn from(pool: &'a SqlitePool) -> Self {
        Self::Pool(pool)
    }
}

impl<'a> From<&'a mut SqliteConnection> for Db<'a> {
    fn from(conn: &'a mut SqliteConnection) -> Self {
        Self::Conn(conn)
    }
}

impl<'a> Db<'a> {
    /// The connection to use.
    ///
    /// # Errors
    ///
    /// Fails when the pool has none to give.
    pub async fn acquire(self) -> Result<Conn<'a>, sqlx::Error> {
        match self {
            Self::Pool(pool) => Ok(Conn::Pooled(pool.acquire().await?)),
            Self::Conn(conn) => Ok(Conn::Borrowed(conn)),
        }
    }
}

/// A connection for the length of one call. It derefs to [`SqliteConnection`].
pub enum Conn<'a> {
    /// Taken from the pool, and given back when dropped.
    Pooled(PoolConnection<Sqlite>),
    /// The caller's.
    Borrowed(&'a mut SqliteConnection),
}

impl Deref for Conn<'_> {
    type Target = SqliteConnection;

    fn deref(&self) -> &SqliteConnection {
        match self {
            Self::Pooled(conn) => conn,
            Self::Borrowed(conn) => conn,
        }
    }
}

impl DerefMut for Conn<'_> {
    fn deref_mut(&mut self) -> &mut SqliteConnection {
        match self {
            Self::Pooled(conn) => conn,
            Self::Borrowed(conn) => conn,
        }
    }
}

/// Whether an error is a violated unique constraint, including a duplicate
/// primary key, which a service usually reports as `409` rather than `500`.
#[must_use]
pub fn is_unique_violation(error: &sqlx::Error) -> bool {
    error
        .as_database_error()
        .is_some_and(sqlx::error::DatabaseError::is_unique_violation)
}

/// Quote a table name for use in SQL, in double quotes.
///
/// Identifiers cannot be bound as parameters, so this is the one place names
/// reach SQL as text. Only lowercase ASCII letters, digits, and underscores
/// are accepted, starting with a letter or underscore. That is stricter than
/// `SQLite`, and it leaves nothing for an attacker to work with.
///
/// ```
/// assert_eq!(axa_sqlite_sqlx::quote_identifier("users").as_deref(), Some("\"users\""));
/// assert_eq!(axa_sqlite_sqlx::quote_identifier("users; DROP TABLE x"), None);
/// ```
#[must_use]
pub fn quote_identifier(name: &str) -> Option<String> {
    let mut chars = name.chars();
    let first = chars.next()?;
    let valid = (first.is_ascii_lowercase() || first == '_')
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    valid.then(|| format!("\"{name}\""))
}

/// Quote every name, failing on the first one [`quote_identifier`] refuses.
fn quote_all<S: AsRef<str>>(names: &[S]) -> Result<Vec<String>, sqlx::Error> {
    names
        .iter()
        .map(|name| {
            quote_identifier(name.as_ref()).ok_or_else(|| {
                sqlx::Error::Protocol(format!("invalid identifier: {}", name.as_ref()))
            })
        })
        .collect()
}

/// Whether a table of this name exists.
async fn table_exists(conn: &mut SqliteConnection, name: &str) -> Result<bool, sqlx::Error> {
    sqlx::query_scalar(
        "SELECT EXISTS (SELECT 1 FROM sqlite_schema WHERE type = 'table' AND name = ?1)",
    )
    .bind(name)
    .fetch_one(conn)
    .await
}

/// Apply pending migrations, each in its own transaction.
///
/// Sqlx's `SQLite` migrator takes no lock, so unlike Postgres two processes
/// migrating one file at once do not take turns, and one of them can fail.
///
/// # Errors
///
/// Fails when a migration fails, or an applied one no longer matches.
pub async fn migrate(pool: &SqlitePool, migrator: &Migrator) -> Result<(), MigrateError> {
    migrator.run(pool).await
}

/// The applied versions, newest first. Empty on a database that has never
/// been migrated.
async fn applied_versions(pool: &SqlitePool) -> Result<Vec<i64>, sqlx::Error> {
    let mut conn = pool.acquire().await?;
    if !table_exists(&mut conn, "_sqlx_migrations").await? {
        return Ok(Vec::new());
    }
    let rows =
        sqlx::query("SELECT version FROM _sqlx_migrations WHERE success ORDER BY version DESC")
            .fetch_all(&mut *conn)
            .await?;
    rows.iter().map(|row| row.try_get("version")).collect()
}

/// Revert the newest `steps` migrations. Each needs a `.down.sql` file.
///
/// # Errors
///
/// Fails on a database error or a failed down migration.
pub async fn revert(
    pool: &SqlitePool,
    migrator: &Migrator,
    steps: u32,
) -> Result<(), MigrateError> {
    let applied = applied_versions(pool).await?;
    let steps = usize::try_from(steps).unwrap_or(usize::MAX);
    // `undo` reverts everything newer than its target, so the target is the
    // version just past the last one to revert, or 0 to revert them all.
    let target = applied.get(steps).copied().unwrap_or(0);
    migrator.undo(pool, target).await
}

/// One migration and whether it has run.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MigrationStatus {
    /// Its version.
    pub version: i64,
    /// Its description.
    pub description: String,
    /// Whether it has been applied.
    pub applied: bool,
}

/// Every migration in `migrator`, oldest first, with whether it has run.
///
/// # Errors
///
/// Fails on a database error.
pub async fn status(
    pool: &SqlitePool,
    migrator: &Migrator,
) -> Result<Vec<MigrationStatus>, sqlx::Error> {
    let applied = applied_versions(pool).await?;
    Ok(migrator
        .iter()
        .filter(|migration| !migration.migration_type.is_down_migration())
        .map(|migration| MigrationStatus {
            version: migration.version,
            description: migration.description.to_string(),
            applied: applied.contains(&migration.version),
        })
        .collect())
}

/// The names of the migrations in `migrator` not yet applied, in order, each as
/// `version_description`.
///
/// # Errors
///
/// Fails on a database error.
pub async fn pending(pool: &SqlitePool, migrator: &Migrator) -> Result<Vec<String>, sqlx::Error> {
    Ok(status(pool, migrator)
        .await?
        .into_iter()
        .filter(|migration| !migration.applied)
        .map(|migration| format!("{}_{}", migration.version, migration.description))
        .collect())
}

/// Empty `tables`, restarting their autoincrement counters. Each name goes
/// through [`quote_identifier`], and every name is checked before anything
/// is emptied.
///
/// It runs `DELETE FROM` each table, and clears their rows in
/// `sqlite_sequence` if that exists, in one transaction. Foreign keys are
/// checked when it commits, so the tables can be listed in any order. A table
/// still referenced from a table not listed makes the call fail and change
/// nothing, unless the reference says `ON DELETE CASCADE`.
///
/// # Errors
///
/// Fails on an invalid name, a foreign key left dangling, or a database error.
pub async fn truncate<S: AsRef<str>>(pool: &SqlitePool, tables: &[S]) -> Result<(), sqlx::Error> {
    if tables.is_empty() {
        return Ok(());
    }
    let quoted = quote_all(tables)?;
    let mut tx = pool.begin().await?;
    // Lasts until the transaction ends.
    sqlx::query("PRAGMA defer_foreign_keys = ON")
        .execute(&mut *tx)
        .await?;
    for table in &quoted {
        let sql = format!("DELETE FROM {table}");
        sqlx::query(AssertSqlSafe(sql)).execute(&mut *tx).await?;
    }
    if table_exists(&mut tx, "sqlite_sequence").await? {
        for table in tables {
            sqlx::query("DELETE FROM sqlite_sequence WHERE name = ?1")
                .bind(table.as_ref())
                .execute(&mut *tx)
                .await?;
        }
    }
    tx.commit().await
}

/// Drop every table and view other than `SQLite`'s own, with foreign keys
/// off, then migrate from nothing. This gives each test an empty schema,
/// whatever tables it touched.
///
/// **This destroys all data.** It exists for tests, and a service must never
/// reach it outside the `test` environment.
///
/// The drops run in one transaction on one connection, which has foreign keys
/// turned back on before it returns to the pool. Indexes and triggers go with
/// their tables.
///
/// # Errors
///
/// Fails on a database error, or a name [`quote_identifier`] refuses.
pub async fn dangerously_recreate(
    pool: &SqlitePool,
    migrator: &Migrator,
) -> Result<(), MigrateError> {
    let mut conn = pool.acquire().await?;
    // `foreign_keys` cannot change inside a transaction, so it is set first.
    sqlx::query("PRAGMA foreign_keys = OFF")
        .execute(&mut *conn)
        .await?;
    let dropped = drop_everything(&mut conn).await;
    let restored = sqlx::query("PRAGMA foreign_keys = ON")
        .execute(&mut *conn)
        .await;
    if let Err(error) = restored {
        // Never give the pool a connection that might not check foreign keys.
        drop(conn.detach());
        return Err(error.into());
    }
    drop(conn);
    dropped?;
    migrate(pool, migrator).await
}

/// Drop every view, then every table, that `SQLite` did not make.
async fn drop_everything(conn: &mut SqliteConnection) -> Result<(), sqlx::Error> {
    let objects: Vec<(String, String)> = sqlx::query_as(
        "SELECT type, name FROM sqlite_schema
         WHERE type IN ('view', 'table') AND name NOT LIKE 'sqlite\\_%' ESCAPE '\\'
         ORDER BY type DESC",
    )
    .fetch_all(&mut *conn)
    .await?;
    let names: Vec<&str> = objects.iter().map(|(_, name)| name.as_str()).collect();
    let quoted = quote_all(&names)?;
    let mut tx = sqlx::Connection::begin(&mut *conn).await?;
    for ((kind, _), name) in objects.iter().zip(quoted) {
        let sql = if kind == "view" {
            format!("DROP VIEW {name}")
        } else {
            format!("DROP TABLE {name}")
        };
        sqlx::query(AssertSqlSafe(sql)).execute(&mut *tx).await?;
    }
    tx.commit().await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn debug_text_leaves_out_the_connection_string() {
        let text = format!("{:?}", PoolConfig::new("sqlite:///srv/hunter2/app.db"));
        assert!(!text.contains("hunter2"), "{text}");
        assert!(text.contains("max_connections"), "{text}");
        assert!(text.contains("busy_timeout_ms"), "{text}");
    }

    #[test]
    fn identifiers_are_quoted() {
        assert_eq!(quote_identifier("users").as_deref(), Some("\"users\""));
        assert_eq!(quote_identifier("_a1").as_deref(), Some("\"_a1\""));
    }

    #[test]
    fn unsafe_identifiers_are_refused() {
        for name in [
            "", "1users", "Users", "a b", "a\"b", "a;b", "a.b", "users--", "é", "a`b", "[a]",
        ] {
            assert_eq!(quote_identifier(name), None, "{name:?}");
        }
    }

    #[test]
    fn quote_all_fails_on_any_bad_name() {
        assert!(quote_all(&["good", "also_good"]).is_ok());
        assert!(quote_all(&["good", "bad name"]).is_err());
    }

    #[test]
    fn pool_settings_reach_the_options() {
        let config = PoolConfig {
            min_connections: 2,
            max_connections: 7,
            connect_timeout_ms: 1_500,
            idle_timeout_ms: 9_000,
            ..PoolConfig::new("sqlite::memory:")
        };
        let options = config.options();
        assert_eq!(options.get_min_connections(), 2);
        assert_eq!(options.get_max_connections(), 7);
        assert_eq!(options.get_acquire_timeout(), Duration::from_millis(1_500));
        assert_eq!(options.get_idle_timeout(), Some(Duration::from_secs(9)));
    }

    #[test]
    fn a_url_that_is_not_sqlite_is_refused() {
        assert!(PoolConfig::new("postgres://x").connect_options().is_err());
    }

    #[test]
    fn errors_that_are_not_from_the_database_are_not_unique_violations() {
        assert!(!is_unique_violation(&sqlx::Error::RowNotFound));
    }
}

//! Object storage for Axum services, over Apache Arrow's [`object_store`]: local disk,
//! memory, or S3, chosen by a URL, with keys that cannot climb out of the store and
//! presigned URLs on S3.
//!
//! ```no_run
//! use axa_storage_with_apache_arrow_and_aws::{Key, Storage};
//!
//! # async fn example(url: &str) -> Result<(), axa_storage_with_apache_arrow_and_aws::Error> {
//! let storage = Storage::from_url(url, true)?;
//! let key = Key::new("avatars/42.png")?;
//! storage.put(&key, bytes::Bytes::from_static(b"...")).await?;
//! let back = storage.get_limited(&key, 1_000_000).await?;
//! let link = storage.presigned_get(&key, std::time::Duration::from_mins(5)).await?;
//! # let _ = (back, link);
//! # Ok(())
//! # }
//! ```
//!
//! # Stores
//!
//! | URL | Store |
//! |---|---|
//! | `s3://bucket` or `s3://bucket/prefix` | S3, configured from the `AWS_` variables `object_store` reads |
//! | `file:///var/lib/service/files` | A directory on local disk, which must exist |
//! | `memory:` | In memory, for tests |
//!
//! S3 credentials, region, and endpoint come from the environment, as
//! [`AmazonS3Builder::from_env`] reads them: `AWS_ACCESS_KEY_ID`,
//! `AWS_SECRET_ACCESS_KEY`, `AWS_REGION`, `AWS_ENDPOINT` for an S3-compatible store, and
//! the rest. In production, [`Storage::from_url`] refuses the memory store, from which
//! every file is gone at restart, and an S3 store reached over plain `http`.
//!
//! # TLS
//!
//! S3 is reached over rustls with ring, as the other axa crates reach their servers.
//! `reqwest` then needs rustls's process-wide provider installed before it builds a
//! client: [`Storage::from_url`] installs ring's when none is, and a service that builds
//! its own [`AmazonS3`] for [`Storage::s3`] calls [`install_ring_provider`] first. A
//! provider the service installed itself is kept.
//!
//! # Keys
//!
//! A [`Key`] is the only way to name an object, and it refuses what could reach outside
//! the store or mean two things: an empty key or segment, a `.` or `..` segment, a
//! leading or trailing `/`, a `\`, a control character, and more than
//! [`MAX_KEY_BYTES`]. Build a key from ids the service made, such as
//! `format!("avatars/{user_id}.png")`, never from a name someone sent: a file name to
//! show goes in the service's own table, beside the key.
//!
//! # Presigned URLs
//!
//! [`Storage::presigned_get`] and [`Storage::presigned_put`] give a URL that lets
//! whoever holds it read or write one object, for a time, without the service's
//! credentials, so a browser can download or upload straight to S3. Anyone holding the
//! URL can use it until it expires, so keep the time short, hand it only to the person
//! the object is for, and never log it. The local and memory stores cannot sign, and
//! answer [`Error::NotSupported`].

use std::{fmt, sync::Arc, time::Duration};

use bytes::Bytes;
pub use object_store;
use object_store::{
    ClientConfigKey, ObjectStore, ObjectStoreExt, PutPayload,
    aws::{AmazonS3, AmazonS3Builder, AmazonS3ConfigKey},
    local::LocalFileSystem,
    memory::InMemory,
    path::Path,
    prefix::PrefixStore,
    signer::{Method, Signer},
};

/// The longest key, in bytes, which S3 also allows.
pub const MAX_KEY_BYTES: usize = 1024;

/// Why storage could not be set up, or an object read or written.
#[derive(Debug)]
#[non_exhaustive]
pub enum Error {
    /// The URL names no store this crate has, or does not parse.
    Url,
    /// Production refuses this store: memory, or S3 over plain `http`.
    Refused(&'static str),
    /// The key could reach outside the store or mean two things: see [`Key`].
    BadKey,
    /// The object is larger than the limit it was read with.
    TooLarge {
        /// Its size, in bytes.
        size: u64,
    },
    /// This store cannot sign URLs.
    NotSupported,
    /// The store refused, or could not be reached.
    Store(object_store::Error),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Url => {
                f.write_str("the storage URL must be s3://bucket, file:///directory, or memory:")
            }
            Self::Refused(why) => write!(f, "production refuses this store: {why}"),
            Self::BadKey => write!(
                f,
                "a key must be 1 to {MAX_KEY_BYTES} bytes of segments joined by `/`, none \
                 empty, `.`, or `..`, with no `\\` or control character"
            ),
            Self::TooLarge { size } => write!(f, "the object is {size} bytes, over the limit"),
            Self::NotSupported => f.write_str("this store cannot sign URLs"),
            Self::Store(error) => write!(f, "the store: {error}"),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Store(error) => Some(error),
            _ => None,
        }
    }
}

impl From<object_store::Error> for Error {
    fn from(error: object_store::Error) -> Self {
        Self::Store(error)
    }
}

/// The name of one object: see [Keys](crate#keys).
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Key(String);

impl Key {
    /// A key, if `key` is one: segments joined by `/`, none empty, `.`, or `..`, with no
    /// leading or trailing `/`, no `\`, no control character, and at most
    /// [`MAX_KEY_BYTES`] bytes.
    ///
    /// # Errors
    ///
    /// Fails with [`Error::BadKey`] for anything else.
    pub fn new(key: impl Into<String>) -> Result<Self, Error> {
        let key = key.into();
        let good = !key.is_empty()
            && key.len() <= MAX_KEY_BYTES
            && !key.contains('\\')
            && !key.chars().any(char::is_control)
            && key
                .split('/')
                .all(|segment| !matches!(segment, "" | "." | ".."))
            && Path::parse(&key).is_ok_and(|path| path.as_ref() == key);
        if good {
            Ok(Self(key))
        } else {
            Err(Error::BadKey)
        }
    }

    /// The key as text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }

    fn path(&self) -> Path {
        Path::from(self.0.as_str())
    }
}

impl fmt::Display for Key {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

/// What is known of one object without reading it.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct Meta {
    /// Its size, in bytes.
    pub size: u64,
    /// When it was last written.
    pub modified: std::time::SystemTime,
}

/// Install ring as rustls's process-wide crypto provider, unless one is installed, so
/// that the S3 client can be built: see [TLS](crate#tls). Safe to call more than once.
pub fn install_ring_provider() {
    if rustls::crypto::CryptoProvider::get_default().is_none() {
        // Another thread may install one first, which is as good.
        let _ = rustls::crypto::ring::default_provider().install_default();
    }
}

/// Refuse an S3 store reached over plain `http`, by its endpoint or `allow_http`.
fn refuse_plain_http(builder: &AmazonS3Builder) -> Result<(), Error> {
    let endpoint = builder
        .get_config_value(&AmazonS3ConfigKey::Endpoint)
        .unwrap_or_default();
    let allow_http = builder
        .get_config_value(&AmazonS3ConfigKey::Client(ClientConfigKey::AllowHttp))
        .is_some_and(|value| value.eq_ignore_ascii_case("true"));
    if allow_http || endpoint.to_ascii_lowercase().starts_with("http://") {
        Err(Error::Refused("S3 must be reached over https"))
    } else {
        Ok(())
    }
}

/// An S3 store and the prefix this storage keeps its objects under, for signing.
#[derive(Clone)]
struct S3Signer {
    s3: Arc<AmazonS3>,
    prefix: Path,
}

/// Reads and writes objects in one store. Cheap to clone.
#[derive(Clone)]
pub struct Storage {
    store: Arc<dyn ObjectStore>,
    signer: Option<S3Signer>,
    kind: &'static str,
}

impl fmt::Debug for Storage {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Storage")
            .field("store", &self.kind)
            .finish_non_exhaustive()
    }
}

impl Storage {
    /// The store a URL names: see [Stores](crate#stores). With `production` set, the
    /// memory store and S3 over plain `http` are refused.
    ///
    /// # Errors
    ///
    /// Fails with [`Error::Url`] for a URL this crate cannot read, with
    /// [`Error::Refused`] for a store production refuses, and with [`Error::Store`] when
    /// the store cannot be built, such as a missing directory.
    pub fn from_url(url: &str, production: bool) -> Result<Self, Error> {
        if url == "memory:" {
            if production {
                return Err(Error::Refused(
                    "the memory store loses every file at restart",
                ));
            }
            return Ok(Self::memory());
        }
        if let Some(dir) = url.strip_prefix("file://") {
            if !dir.starts_with('/') {
                return Err(Error::Url);
            }
            return Self::local(dir);
        }
        let rest = url.strip_prefix("s3://").ok_or(Error::Url)?;
        let (bucket, prefix) = rest.split_once('/').unwrap_or((rest, ""));
        if bucket.is_empty() || bucket.contains(['?', '#', '@', ':']) {
            return Err(Error::Url);
        }
        let prefix = prefix.trim_end_matches('/');
        let prefix = if prefix.is_empty() {
            None
        } else {
            Some(Key::new(prefix).map_err(|_| Error::Url)?)
        };
        let builder = AmazonS3Builder::from_env().with_bucket_name(bucket);
        if production {
            refuse_plain_http(&builder)?;
        }
        install_ring_provider();
        Ok(Self::s3(builder.build()?, prefix.as_ref()))
    }

    /// A store in memory, for tests. Production refuses it from a URL.
    #[must_use]
    pub fn memory() -> Self {
        Self {
            store: Arc::new(InMemory::new()),
            signer: None,
            kind: "memory",
        }
    }

    /// A store in the directory `dir` on local disk, which must exist.
    ///
    /// # Errors
    ///
    /// Fails with [`Error::Store`] when the directory cannot be used.
    pub fn local(dir: impl AsRef<std::path::Path>) -> Result<Self, Error> {
        Ok(Self {
            store: Arc::new(LocalFileSystem::new_with_prefix(dir)?),
            signer: None,
            kind: "local",
        })
    }

    /// A store on `s3`, built as the service chooses, keeping its objects under `prefix`
    /// when there is one. Call [`install_ring_provider`] before building `s3`, unless
    /// the service installs a rustls provider of its own.
    #[must_use]
    pub fn s3(s3: AmazonS3, prefix: Option<&Key>) -> Self {
        let s3 = Arc::new(s3);
        let prefix = prefix.map_or_else(|| Path::from(""), Key::path);
        let store: Arc<dyn ObjectStore> = if prefix.as_ref().is_empty() {
            s3.clone()
        } else {
            let inner: Arc<dyn ObjectStore> = s3.clone();
            Arc::new(PrefixStore::new(inner, prefix.clone()))
        };
        Self {
            store,
            signer: Some(S3Signer { s3, prefix }),
            kind: "s3",
        }
    }

    /// The `object_store` store underneath, for what this crate does not cover, such as
    /// listing or multipart uploads. Its paths are not checked as a [`Key`] is.
    #[must_use]
    pub fn store(&self) -> &Arc<dyn ObjectStore> {
        &self.store
    }

    /// Write `bytes` to `key`, whole or not at all, replacing what was there.
    ///
    /// # Errors
    ///
    /// Fails with [`Error::Store`] when the store refuses or cannot be reached.
    pub async fn put(&self, key: &Key, bytes: Bytes) -> Result<(), Error> {
        self.store.put(&key.path(), PutPayload::from(bytes)).await?;
        Ok(())
    }

    /// Read `key` whole, or `None` when there is no such object, refusing one larger
    /// than `max_bytes` before reading it.
    ///
    /// # Errors
    ///
    /// Fails with [`Error::TooLarge`] for an object over the limit, and with
    /// [`Error::Store`] when the store refuses or cannot be reached.
    pub async fn get_limited(&self, key: &Key, max_bytes: u64) -> Result<Option<Bytes>, Error> {
        let result = match self.store.get(&key.path()).await {
            Ok(result) => result,
            Err(object_store::Error::NotFound { .. }) => return Ok(None),
            Err(error) => return Err(error.into()),
        };
        if result.meta.size > max_bytes {
            return Err(Error::TooLarge {
                size: result.meta.size,
            });
        }
        Ok(Some(result.bytes().await?))
    }

    /// The size and time of `key`, or `None` when there is no such object.
    ///
    /// # Errors
    ///
    /// Fails with [`Error::Store`] when the store refuses or cannot be reached.
    pub async fn head(&self, key: &Key) -> Result<Option<Meta>, Error> {
        match self.store.head(&key.path()).await {
            Ok(meta) => Ok(Some(Meta {
                size: meta.size,
                modified: meta.last_modified.into(),
            })),
            Err(object_store::Error::NotFound { .. }) => Ok(None),
            Err(error) => Err(error.into()),
        }
    }

    /// Delete `key`. Deleting an object that is not there is not an error.
    ///
    /// # Errors
    ///
    /// Fails with [`Error::Store`] when the store refuses or cannot be reached.
    pub async fn delete(&self, key: &Key) -> Result<(), Error> {
        match self.store.delete(&key.path()).await {
            Ok(()) | Err(object_store::Error::NotFound { .. }) => Ok(()),
            Err(error) => Err(error.into()),
        }
    }

    /// A URL that lets whoever holds it `GET` `key` for `expires_in`, on S3: see
    /// [Presigned URLs](crate#presigned-urls).
    ///
    /// # Errors
    ///
    /// Fails with [`Error::NotSupported`] on a store that cannot sign.
    pub async fn presigned_get(&self, key: &Key, expires_in: Duration) -> Result<String, Error> {
        self.presigned(Method::GET, key, expires_in).await
    }

    /// A URL that lets whoever holds it `PUT` `key` for `expires_in`, on S3, replacing
    /// what is there: see [Presigned URLs](crate#presigned-urls). It does not limit the
    /// size of what is sent.
    ///
    /// # Errors
    ///
    /// Fails with [`Error::NotSupported`] on a store that cannot sign.
    pub async fn presigned_put(&self, key: &Key, expires_in: Duration) -> Result<String, Error> {
        self.presigned(Method::PUT, key, expires_in).await
    }

    async fn presigned(
        &self,
        method: Method,
        key: &Key,
        expires_in: Duration,
    ) -> Result<String, Error> {
        let signer = self.signer.as_ref().ok_or(Error::NotSupported)?;
        let path = if signer.prefix.as_ref().is_empty() {
            key.path()
        } else {
            Path::from(format!("{}/{}", signer.prefix, key.as_str()))
        };
        Ok(signer
            .s3
            .signed_url(method, &path, expires_in)
            .await?
            .to_string())
    }
}

