//! Tera templates with safe escaping and generic errors.
//!
//! ```
//! use axa_tera_templates::Templates;
//! use serde_json::json;
//!
//! let templates =
//!     Templates::from_raw([("hello.html", "<p>Hello, {{ name }}!</p>")]).unwrap();
//!
//! let page = templates
//!     .render("hello.html", &json!({ "name": "<b>Alice</b>" }))
//!     .unwrap();
//! assert!(page.starts_with("<p>Hello, &lt;b&gt;Alice"));
//! ```
//!
//! # What this crate promises
//!
//! - **HTML is escaped by default.** Templates named `.html`, `.htm`, or `.xml`
//!   escape every value unless the template says `safe`. Only write `safe` on
//!   a value your own code produced, because it turns the protection off.
//! - **A failed render shows nothing.** The failure is logged and the visitor
//!   gets a generic `500`, because Tera's errors quote template source.
//! - **A page can load its own files.** `axa`'s production default,
//!   `default-src 'none'`, suits a JSON API and would block a page's stylesheets
//!   and images. [`Page`] sends [`PAGE_CSP`] in its place, and a handler or
//!   `HTTP_CONTENT_SECURITY_POLICY` can name another. It allows no inline
//!   script, and files only from the page's own origin.
//!
//! A template name without one of those extensions is not escaped, so never
//! render user input into a `.txt` template that ends up in a page.

use axum::{
    http::{StatusCode, header},
    response::{Html, IntoResponse, Response},
};
use serde::Serialize;
use tera::{Context, Tera};

/// The policy a [`Page`] sends: its own origin's files, and no inline script.
pub const PAGE_CSP: &str = "default-src 'self'; object-src 'none'; base-uri 'self'; \
     form-action 'self'; frame-ancestors 'none'";

/// A rendered HTML page, which answers with [`PAGE_CSP`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Page(pub String);

impl IntoResponse for Page {
    fn into_response(self) -> Response {
        ([(header::CONTENT_SECURITY_POLICY, PAGE_CSP)], Html(self.0)).into_response()
    }
}

/// A template failure.
#[derive(Debug)]
pub struct Error(tera::Error);

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.0.fmt(f)
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.0)
    }
}

impl From<tera::Error> for Error {
    fn from(error: tera::Error) -> Self {
        Self(error)
    }
}

impl IntoResponse for Error {
    fn into_response(self) -> Response {
        tracing::error!(error = %self, "template failed");
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Html("Internal Server Error"),
        )
            .into_response()
    }
}

/// A set of compiled templates. Build it once at boot and share it.
#[derive(Debug, Clone)]
pub struct Templates {
    tera: Tera,
}

impl Templates {
    /// Load every template matching `glob`, such as `templates/**/*.html`.
    ///
    /// # Errors
    ///
    /// Fails when a template does not parse.
    pub fn from_glob(glob: &str) -> Result<Self, Error> {
        let mut tera = Tera::new();
        tera.load_from_glob(glob)?;
        Ok(Self { tera })
    }

    /// Compile templates from `(name, source)` pairs, such as ones embedded
    /// with `include_str!`.
    ///
    /// # Errors
    ///
    /// Fails when a template does not parse.
    pub fn from_raw<'a>(
        templates: impl IntoIterator<Item = (&'a str, &'a str)>,
    ) -> Result<Self, Error> {
        let mut tera = Tera::new();
        tera.add_raw_templates(templates)?;
        Ok(Self { tera })
    }

    /// Whether a template exists.
    #[must_use]
    pub fn contains(&self, name: &str) -> bool {
        self.tera.contains_template(name)
    }

    /// Render a template to text. `data` must serialize to a JSON object.
    ///
    /// # Errors
    ///
    /// Fails when the template is missing, `data` is not an object, or the
    /// template fails, for example on an undefined variable.
    pub fn render<T: Serialize + ?Sized>(&self, name: &str, data: &T) -> Result<String, Error> {
        let context = Context::from_serialize(data)?;
        Ok(self.tera.render(name, &context)?)
    }

    /// Render a template as an HTML response with [`PAGE_CSP`].
    ///
    /// # Errors
    ///
    /// See [`Templates::render`].
    pub fn html<T: Serialize + ?Sized>(&self, name: &str, data: &T) -> Result<Page, Error> {
        self.render(name, data).map(Page)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn templates() -> Templates {
        Templates::from_raw([
            ("page.html", "<p>{{ name }}</p>"),
            ("trusted.html", "<p>{{ name | safe }}</p>"),
            ("note.txt", "{{ name }}"),
        ])
        .unwrap()
    }

    async fn body_text(response: Response) -> String {
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        String::from_utf8(bytes.to_vec()).unwrap()
    }

    #[test]
    fn values_render() {
        let page = templates().render("page.html", &json!({ "name": "Alice" }));
        assert_eq!(page.unwrap(), "<p>Alice</p>");
    }

    #[test]
    fn html_templates_escape_values() {
        let data = json!({ "name": "<script>alert(1)</script>" });
        let page = templates().render("page.html", &data).unwrap();
        assert!(!page.contains("<script>"), "{page}");
        assert!(page.contains("&lt;script&gt;"), "{page}");
    }

    #[test]
    fn safe_turns_escaping_off() {
        let page = templates().render("trusted.html", &json!({ "name": "<b>" }));
        assert_eq!(page.unwrap(), "<p><b></p>");
    }

    #[test]
    fn other_extensions_are_not_escaped() {
        let note = templates().render("note.txt", &json!({ "name": "<b>" }));
        assert_eq!(note.unwrap(), "<b>");
    }

    #[test]
    fn a_missing_variable_is_an_error_rather_than_blank() {
        assert!(templates().render("page.html", &json!({})).is_err());
    }

    #[test]
    fn a_missing_template_is_an_error() {
        assert!(templates().render("nope.html", &json!({})).is_err());
        assert!(!templates().contains("nope.html"));
        assert!(templates().contains("page.html"));
    }

    #[test]
    fn data_must_be_an_object() {
        assert!(templates().render("page.html", &json!(["list"])).is_err());
    }

    #[test]
    fn a_syntax_error_is_found_at_boot() {
        assert!(Templates::from_raw([("bad.html", "{{ unclosed")]).is_err());
    }

    #[tokio::test]
    async fn the_html_response_has_the_html_media_type() {
        let response = templates()
            .html("page.html", &json!({ "name": "Alice" }))
            .unwrap()
            .into_response();
        let content_type = response.headers()["content-type"].to_str().unwrap();
        assert!(content_type.starts_with("text/html"), "{content_type}");
    }

    #[tokio::test]
    async fn a_failed_render_shows_nothing_to_the_visitor() {
        let template = "<!-- secret-comment -->{{ missing }}";
        let templates = Templates::from_raw([("t.html", template)]).unwrap();
        let error = templates.html("t.html", &json!({})).unwrap_err();
        let response = error.into_response();
        assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(
            response.headers()[header::CONTENT_TYPE],
            "text/html; charset=utf-8"
        );
        assert_eq!(body_text(response).await, "Internal Server Error");
    }
}

//! Checks that one tenant cannot reach another's resources.
//!
//! A service that many tenants share keeps them apart in every route that takes an
//! id. The test that proves it creates a resource as one tenant, then tries every way
//! in as another: each must answer `404`, as a missing resource does, so that a caller
//! cannot learn which ids other tenants hold, and a list must not show it.
//!
//! ```ignore
//! use axa_test::isolation::{Probe, assert_hidden};
//!
//! let created = server.post("/api/todos").add_header("authorization", &acme).json(&todo).await;
//! let id = created.json::<serde_json::Value>()["id"].to_string();
//! let path = format!("/api/todos/{id}");
//! assert_hidden(
//!     &server,
//!     &[("authorization", globex.as_str())],
//!     &[
//!         Probe::get(&path),
//!         Probe::patch(&path, r#"{"completed":true}"#),
//!         Probe::delete(&path),
//!         Probe::list("/api/todos", "Acme's secret plan"),
//!     ],
//! )
//! .await;
//! ```

use axum_test::{
    TestServer,
    http::{Method, StatusCode},
};

/// One way in to a resource, tried as the other tenant.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Probe {
    method: Method,
    path: String,
    body: Option<String>,
    /// For a list: text the other tenant's answer must not hold.
    absent: Option<String>,
}

impl Probe {
    /// A `GET` of the resource, which must answer `404`.
    #[must_use]
    pub fn get(path: &str) -> Self {
        Self::one(Method::GET, path, None)
    }

    /// A `PATCH` of the resource with a JSON `body`, which must answer `404`.
    #[must_use]
    pub fn patch(path: &str, body: &str) -> Self {
        Self::one(Method::PATCH, path, Some(body))
    }

    /// A `PUT` of the resource with a JSON `body`, which must answer `404`.
    #[must_use]
    pub fn put(path: &str, body: &str) -> Self {
        Self::one(Method::PUT, path, Some(body))
    }

    /// A `DELETE` of the resource, which must answer `404`.
    #[must_use]
    pub fn delete(path: &str) -> Self {
        Self::one(Method::DELETE, path, None)
    }

    /// A `POST` to a route under the resource, such as `/api/todos/7/archive`, with a
    /// JSON `body`, which must answer `404`.
    #[must_use]
    pub fn post(path: &str, body: &str) -> Self {
        Self::one(Method::POST, path, Some(body))
    }

    /// A `GET` of a list, which must succeed and must not hold `absent`, such as the
    /// resource's id in its JSON form or a title only the owner wrote.
    #[must_use]
    pub fn list(path: &str, absent: &str) -> Self {
        Self {
            method: Method::GET,
            path: path.to_string(),
            body: None,
            absent: Some(absent.to_string()),
        }
    }

    fn one(method: Method, path: &str, body: Option<&str>) -> Self {
        Self {
            method,
            path: path.to_string(),
            body: body.map(str::to_string),
            absent: None,
        }
    }

    /// What is wrong with the answer to this probe, or `None` when it is right.
    fn fault(&self, status: StatusCode, body: &str) -> Option<String> {
        let name = format!("{} {}", self.method, self.path);
        match &self.absent {
            Some(absent) if !status.is_success() => Some(format!(
                "{name} answered {status}, where a list should succeed"
            )),
            Some(absent) if body.contains(absent.as_str()) => {
                Some(format!("{name} shows {absent:?} to another tenant"))
            }
            Some(_) => None,
            None if status == StatusCode::NOT_FOUND => None,
            None => Some(format!(
                "{name} answered {status} to another tenant, where it should be 404"
            )),
        }
    }
}

/// Send every probe to `server` with `headers`, the other tenant's credentials, and
/// panic naming each one that reached the resource, answered other than `404`, or
/// listed it. Other than `404` includes `403`, which tells a caller the id exists.
///
/// # Panics
///
/// When any probe's answer is wrong, listing every wrong one.
pub async fn assert_hidden(server: &TestServer, headers: &[(&str, &str)], probes: &[Probe]) {
    let mut faults = Vec::new();
    for probe in probes {
        let mut request = server.method(probe.method.clone(), &probe.path);
        for (name, value) in headers {
            request = request.add_header(*name, *value);
        }
        if let Some(body) = &probe.body {
            request = request.content_type("application/json").text(body.clone());
        }
        let response = request.await;
        if let Some(fault) = probe.fault(response.status_code(), &response.text()) {
            faults.push(fault);
        }
    }
    assert!(
        faults.is_empty(),
        "another tenant reached a resource:\n{}",
        faults.join("\n")
    );
}

//! Request-level test helpers for `axa` services, built on
//! [`axum-test`](https://docs.rs/axum-test).
//!
//! A service implements [`TestApp`] to say how it boots for tests, then sends real
//! requests to its full router, middleware and all, with no port opened:
//!
//! ```ignore
//! use axa_test::prelude::*;
//!
//! #[tokio::test]
//! async fn health_answers() {
//!     request::<App, _, _>(|server, _ctx| async move {
//!         assert_eq!(server.get("/_health/live").await.status_code(), 200);
//!     })
//!     .await;
//! }
//! ```
//!
//! Add it as a dev-dependency, so it never ships in a service's binary.

use std::{future::Future, net::SocketAddr};

pub mod isolation;
pub mod logs;
#[cfg(feature = "mail")]
pub mod mail;
#[cfg(feature = "openapi")]
pub mod openapi;
#[cfg(feature = "paseto")]
pub mod paseto;
#[cfg(feature = "postgres-sqlx")]
pub mod postgres;

pub use axa::boot::{BootResult, TestApp};
use axa::{AppContext, Result};
pub use axum_test::TestServer;

/// Boot `H` for tests.
///
/// # Errors
///
/// Propagates the boot failure.
pub async fn boot_test<H: TestApp>() -> Result<BootResult> {
    H::boot_test().await
}

/// Boot `H`, then run `callback` with a test client for its router and its context.
///
/// # Panics
///
/// If the service cannot boot, or boots with no router.
pub async fn request<H, F, Fut>(callback: F)
where
    H: TestApp,
    F: FnOnce(TestServer, AppContext) -> Fut,
    Fut: Future<Output = ()>,
{
    let boot = H::boot_test().await.expect("the service boots for tests");
    let router = boot.router.clone().expect("the service has a router");
    let server = TestServer::new(router.into_make_service_with_connect_info::<SocketAddr>());
    callback(server, boot.app_context).await;
}

/// Everything a request test needs.
pub mod prelude {
    pub use super::{BootResult, TestApp, TestServer, boot_test, request};
}

//! Logs captured for one test, so it can check what a request wrote, and that it
//! wrote no secret.
//!
//! ```
//! # #[tokio::main(flavor = "current_thread")]
//! # async fn main() {
//! let logs = axa_test::logs::capture();
//! tracing::warn!(user = "ada", "sign-in refused");
//! assert!(logs.contains("sign-in refused"));
//! assert_eq!(logs.lines()[0]["fields"]["user"], "ada");
//! logs.assert_absent("hunter2");
//! # }
//! ```
//!
//! Capture holds on the thread that called [`capture`], until the [`Logs`] is dropped,
//! and covers `DEBUG` and above. A `#[tokio::test]` runs on one thread unless told
//! otherwise, so a request sent through [`crate::TestServer`] is captured. A task a
//! multi-threaded runtime moves to another thread is not.

use std::{
    io::Write,
    sync::{Arc, Mutex, PoisonError},
};

use tracing::subscriber::DefaultGuard;
use tracing_subscriber::fmt::MakeWriter;

/// What has been logged since [`capture`], one JSON object per line.
pub struct Logs {
    buffer: Arc<Mutex<Vec<u8>>>,
    _guard: DefaultGuard,
}

impl std::fmt::Debug for Logs {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Logs")
            .field("lines", &self.lines().len())
            .finish()
    }
}

#[derive(Clone)]
struct Buffer(Arc<Mutex<Vec<u8>>>);

impl Write for Buffer {
    fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
        self.0
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .extend_from_slice(bytes);
        Ok(bytes.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

impl<'a> MakeWriter<'a> for Buffer {
    type Writer = Self;

    fn make_writer(&'a self) -> Self::Writer {
        self.clone()
    }
}

/// Start capturing this thread's logs, as JSON, until the answer is dropped.
#[must_use]
pub fn capture() -> Logs {
    let buffer = Arc::new(Mutex::new(Vec::new()));
    let subscriber = tracing_subscriber::fmt()
        .json()
        .with_max_level(tracing::Level::DEBUG)
        .with_current_span(true)
        .with_span_list(false)
        .with_writer(Buffer(buffer.clone()))
        .finish();
    Logs {
        buffer,
        _guard: tracing::subscriber::set_default(subscriber),
    }
}

impl Logs {
    /// Everything logged so far, as written.
    #[must_use]
    pub fn text(&self) -> String {
        let buffer = self.buffer.lock().unwrap_or_else(PoisonError::into_inner);
        String::from_utf8_lossy(&buffer).into_owned()
    }

    /// Each line logged so far, parsed: `level`, `fields` with `message`, `target`,
    /// and `span` when there was one.
    ///
    /// # Panics
    ///
    /// If a line is not JSON, which the capture never writes.
    #[must_use]
    pub fn lines(&self) -> Vec<serde_json::Value> {
        self.text()
            .lines()
            .map(|line| serde_json::from_str(line).expect("each captured line is JSON"))
            .collect()
    }

    /// Whether any line holds `text`.
    #[must_use]
    pub fn contains(&self, text: &str) -> bool {
        self.text().contains(text)
    }

    /// Fail the test if any line holds `secret`, naming the line but not repeating
    /// the secret.
    ///
    /// # Panics
    ///
    /// If a line holds it.
    pub fn assert_absent(&self, secret: &str) {
        let text = self.text();
        if let Some(line) = text.lines().position(|line| line.contains(secret)) {
            panic!(
                "captured log line {} holds what must not be logged",
                line + 1
            );
        }
    }

    /// Forget what has been logged so far.
    pub fn clear(&self) {
        self.buffer
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .clear();
    }
}

//! Mail a service sent, read from the memory mailer it built.
//!
//! In tests, give the service `memory:` as its mail URL, so it builds its
//! [`Mailer`] with [`Mailer::from_url`] as in production and keeps it in
//! `ctx.shared_store`. Then [`outbox`] finds what it sent:
//!
//! ```ignore
//! request::<App, _, _>(|server, ctx| async move {
//!     server.post("/sign-in/link").json(&json!({"email": "ada@example.org"})).await;
//!     let sent = axa_test::mail::outbox(&ctx.shared_store).take();
//!     assert_eq!(sent[0].to, ["ada@example.org"]);
//! })
//! .await;
//! ```

pub use axa::mail::{Mailer, Outbox, Sent};
use axa::store::Store;

/// The outbox of the memory [`Mailer`] in a service's store, `ctx.shared_store`.
///
/// # Panics
///
/// If there is no `Mailer` in the store, or it is not a memory mailer, so a test
/// that would send real mail fails instead.
#[must_use]
pub fn outbox(store: &Store) -> Outbox {
    let mailer = store
        .get_ref::<Mailer>()
        .expect("the service keeps its Mailer in ctx.shared_store");
    mailer
        .outbox()
        .expect("the service's Mailer is a memory mailer: give it memory: in tests")
}

/// The messages sent so far to `address`, leaving them in the outbox.
#[must_use]
pub fn sent_to(outbox: &Outbox, address: &str) -> Vec<Sent> {
    outbox
        .sent()
        .into_iter()
        .filter(|sent| sent.to.iter().any(|to| to.eq_ignore_ascii_case(address)))
        .collect()
}

//! Real responses checked against the `OpenAPI` document, with the `openapi` feature.
//!
//! A drift check, such as `axa_openapi_docs::drift`, says each route is documented. This
//! says each answer is: that its status is one the operation lists, its content type is
//! one that status lists, and a JSON body is valid against the schema documented for it.
//!
//! ```ignore
//! use axa_test::openapi::Conformance;
//!
//! request::<App, _, _>(|server, _ctx| async move {
//!     let conformance = Conformance::new(serde_json::to_value(ApiDoc::openapi()).unwrap());
//!     conformance.assert(&server.get("/api/places/1").await);
//!     conformance.assert(&server.get("/api/places/missing").await);
//! })
//! .await;
//! ```
//!
//! The document is `OpenAPI` 3.1, as `utoipa` writes, whose schemas are JSON Schema
//! 2020-12. A 3.0 document's schemas are another dialect, so it is refused rather than
//! checked wrongly. A `$ref` must point inside the document: nothing is fetched.

use std::fmt::Write as _;

use axum_test::TestResponse;
use serde_json::Value;

/// The most errors reported for one body, so that a long list stays readable.
const MAX_ERRORS: usize = 10;

/// How many `$ref`s are followed in a row before a loop is assumed.
const MAX_REFS: usize = 16;

/// An `OpenAPI` 3.1 document to check responses against.
#[derive(Clone, Debug)]
pub struct Conformance {
    document: Value,
}

impl Conformance {
    /// Check against `document`.
    ///
    /// # Panics
    ///
    /// If `document` is not `OpenAPI` 3.1.
    #[must_use]
    pub fn new(document: Value) -> Self {
        let version = document["openapi"].as_str().unwrap_or_default();
        assert!(
            version.starts_with("3.1."),
            "axa_test::openapi checks OpenAPI 3.1 documents, and this is {version:?}"
        );
        Self { document }
    }

    /// Panic, naming each mismatch, unless `response` is one its operation documents.
    ///
    /// # Panics
    ///
    /// When it is not.
    pub fn assert(&self, response: &TestResponse) {
        let method = response.request_method();
        let url = response.request_url();
        let status = response.status_code().as_u16();
        let content_type = response.maybe_content_type();
        if let Err(mismatches) = self.check(
            method.as_str(),
            url.path(),
            status,
            content_type.as_deref(),
            response.as_bytes(),
        ) {
            panic!(
                "{method} {} answered {status}, which the OpenAPI document does not allow:\n  {}",
                url.path(),
                mismatches.join("\n  ")
            );
        }
    }

    /// Whether a response to `method` on `path`, a request's path such as
    /// `/api/places/1`, with `status`, `content_type`, and `body`, is one the operation
    /// documents.
    ///
    /// # Errors
    ///
    /// Each way it is not.
    pub fn check(
        &self,
        method: &str,
        path: &str,
        status: u16,
        content_type: Option<&str>,
        body: &[u8],
    ) -> Result<(), Vec<String>> {
        let fail = |mismatch: String| Err(vec![mismatch]);
        let Some(template) = self.template(path) else {
            return fail(format!("no path in the document matches {path}"));
        };
        let mut at = format!("/paths/{}", escape(&template));
        let Some(operation) = self.follow(&mut at) else {
            return fail(format!("{template} cannot be read"));
        };
        let method = method.to_ascii_lowercase();
        if operation.get(&method).is_none() {
            return fail(format!("{template} documents no {method} operation"));
        }
        at = format!("{at}/{method}/responses");
        let Some(responses) = self.follow(&mut at) else {
            return fail(format!("{method} {template} documents no responses"));
        };
        let exact = status.to_string();
        let range = format!("{}XX", status / 100);
        let Some(key) = [exact.as_str(), range.as_str(), "default"]
            .into_iter()
            .find(|key| responses.get(key).is_some())
        else {
            return fail(format!("{method} {template} does not document {status}"));
        };
        at = format!("{at}/{key}");
        let Some(response) = self.follow(&mut at) else {
            return fail(format!("{method} {template} {key} cannot be read"));
        };
        let Some(content) = response.get("content").and_then(Value::as_object) else {
            return if body.is_empty() {
                Ok(())
            } else {
                fail(format!(
                    "{method} {template} {key} documents no body, and one was sent"
                ))
            };
        };
        let essence = content_type
            .and_then(|value| value.split(';').next())
            .map_or_default(|value| value.trim().to_ascii_lowercase());
        let Some(media) = media_key(content, &essence) else {
            let documented: Vec<&str> = content.keys().map(String::as_str).collect();
            return fail(format!(
                "{method} {template} {key} documents {documented:?}, and the answer was {essence:?}"
            ));
        };
        at = format!("{at}/content/{}", escape(media));
        if content[media].get("schema").is_none() || !is_json(&essence) {
            return Ok(());
        }
        let instance: Value = match serde_json::from_slice(body) {
            Ok(instance) => instance,
            Err(error) => return fail(format!("the body is not JSON: {error}")),
        };
        self.validate(&format!("{at}/schema"), &instance)
    }

    /// The documented path that `path` is, the one with the most literal segments when
    /// more than one matches, as `/places/new` is before `/places/{id}`.
    fn template(&self, path: &str) -> Option<String> {
        let wanted: Vec<&str> = path.split('/').collect();
        self.document["paths"]
            .as_object()?
            .keys()
            .filter_map(|template| {
                let parts: Vec<&str> = template.split('/').collect();
                if parts.len() != wanted.len() {
                    return None;
                }
                let mut literal = 0;
                for (part, segment) in parts.iter().zip(&wanted) {
                    if part.starts_with('{') && part.ends_with('}') {
                        if segment.is_empty() {
                            return None;
                        }
                    } else if part == segment {
                        literal += 1;
                    } else {
                        return None;
                    }
                }
                Some((literal, template))
            })
            .max_by_key(|(literal, _)| *literal)
            .map(|(_, template)| template.clone())
    }

    /// The value at the JSON pointer `at`, following any `$ref`s, which move `at` to
    /// where they point, so a schema inside is found where it really is.
    fn follow(&self, at: &mut String) -> Option<&Value> {
        let mut value = self.document.pointer(at)?;
        for _ in 0..MAX_REFS {
            let Some(target) = value.get("$ref").and_then(Value::as_str) else {
                return Some(value);
            };
            let pointer = decode(target.strip_prefix('#')?)?;
            value = self.document.pointer(&pointer)?;
            *at = pointer;
        }
        None
    }

    /// Validate `instance` against the schema at `at`. The schema is the whole document
    /// with a `$ref` to it, so its own `$ref`s into `#/components` resolve.
    fn validate(&self, at: &str, instance: &Value) -> Result<(), Vec<String>> {
        let mut root = self.document.clone();
        let Some(object) = root.as_object_mut() else {
            return Err(vec!["the document is not an object".to_string()]);
        };
        object.insert(
            "$ref".to_string(),
            Value::String(format!("#{}", fragment(at))),
        );
        let validator = jsonschema::options()
            .with_draft(jsonschema::Draft::Draft202012)
            .should_validate_formats(true)
            .build(&root)
            .map_err(|error| vec![format!("the schema at {at} cannot be used: {error}")])?;
        let errors: Vec<String> = validator
            .iter_errors(instance)
            .take(MAX_ERRORS)
            .map(|error| {
                let path = error.instance_path().to_string();
                let path = if path.is_empty() { "/" } else { &path };
                format!("{path}: {error}")
            })
            .collect();
        if errors.is_empty() {
            Ok(())
        } else {
            Err(errors)
        }
    }
}

/// The documented media type an answer of `essence` matches: itself, its type with `*`,
/// or `*/*`.
fn media_key<'a>(content: &'a serde_json::Map<String, Value>, essence: &str) -> Option<&'a str> {
    let wildcard = essence
        .split_once('/')
        .map_or_default(|(kind, _)| format!("{kind}/*"));
    [essence, wildcard.as_str(), "*/*"]
        .into_iter()
        .find_map(|wanted| {
            content
                .keys()
                .find(|key| key.eq_ignore_ascii_case(wanted))
                .map(String::as_str)
        })
}

/// Whether a media type is JSON: `application/json`, or a `+json` type such as
/// `application/problem+json`.
fn is_json(essence: &str) -> bool {
    essence == "application/json" || essence.ends_with("+json")
}

/// A JSON pointer as a URI fragment, with what a fragment cannot hold, such as the `{`
/// of a path template, percent-encoded.
fn fragment(pointer: &str) -> String {
    let mut encoded = String::with_capacity(pointer.len());
    for byte in pointer.bytes() {
        if byte.is_ascii_alphanumeric() || b"-._~/!$&'()*+,;=:@".contains(&byte) {
            encoded.push(char::from(byte));
        } else {
            let _ = write!(encoded, "%{byte:02X}");
        }
    }
    encoded
}

/// A URI fragment's percent-encoding undone, or `None` for a bad one.
fn decode(fragment: &str) -> Option<String> {
    let bytes = fragment.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] == b'%' {
            let hex = std::str::from_utf8(bytes.get(index + 1..index + 3)?).ok()?;
            decoded.push(u8::from_str_radix(hex, 16).ok()?);
            index += 3;
        } else {
            decoded.push(bytes[index]);
            index += 1;
        }
    }
    String::from_utf8(decoded).ok()
}

/// A JSON pointer segment.
fn escape(segment: &str) -> String {
    segment.replace('~', "~0").replace('/', "~1")
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn document() -> Value {
        json!({
            "openapi": "3.1.0",
            "info": { "title": "Places", "version": "1" },
            "paths": {
                "/api/places/{id}": {
                    "get": {
                        "responses": {
                            "200": {
                                "description": "A place",
                                "content": { "application/json": {
                                    "schema": { "$ref": "#/components/schemas/Place" }
                                } }
                            },
                            "404": { "$ref": "#/components/responses/Problem" }
                        }
                    },
                    "delete": { "responses": { "204": { "description": "Gone" } } }
                },
                "/api/places/new": {
                    "get": { "responses": { "2XX": {
                        "description": "A form",
                        "content": { "text/html": {} }
                    } } }
                }
            },
            "components": {
                "schemas": {
                    "Place": {
                        "type": "object",
                        "required": ["id", "name"],
                        "properties": {
                            "id": { "type": "string", "format": "uuid" },
                            "name": { "type": "string" },
                            "tags": { "type": "array", "items": { "type": "string" } }
                        },
                        "additionalProperties": false
                    }
                },
                "responses": {
                    "Problem": {
                        "description": "A problem",
                        "content": { "application/problem+json": { "schema": {
                            "type": "object",
                            "required": ["status"],
                            "properties": { "status": { "type": "integer" } }
                        } } }
                    }
                }
            }
        })
    }

    const ID: &str = "8f2b0c1e-4a0e-4a39-9a4b-2f1f7c2d9d10";

    fn check(
        method: &str,
        path: &str,
        status: u16,
        kind: Option<&str>,
        body: &Value,
    ) -> Result<(), Vec<String>> {
        let body = if body.is_null() {
            Vec::new()
        } else {
            serde_json::to_vec(body).unwrap()
        };
        Conformance::new(document()).check(method, path, status, kind, &body)
    }

    const JSON: Option<&str> = Some("application/json; charset=utf-8");

    #[test]
    fn a_documented_answer_conforms() {
        let place = json!({ "id": ID, "name": "Home", "tags": ["a"] });
        assert_eq!(check("GET", "/api/places/1", 200, JSON, &place), Ok(()));
        // Through a `$ref` to a shared response.
        let problem = json!({ "status": 404, "title": "Not Found" });
        let kind = Some("application/problem+json");
        assert_eq!(check("GET", "/api/places/1", 404, kind, &problem), Ok(()));
        assert_eq!(
            check("DELETE", "/api/places/1", 204, None, &Value::Null),
            Ok(())
        );
        // A literal path wins over a template, and a range covers its statuses.
        let html = Conformance::new(document()).check(
            "GET",
            "/api/places/new",
            201,
            Some("text/html"),
            b"<p>",
        );
        assert_eq!(html, Ok(()));
    }

    #[test]
    fn a_body_outside_its_schema_is_named_by_where_it_is_wrong() {
        let wrong = json!({ "id": "not-a-uuid", "tags": [1], "extra": true });
        let errors = check("GET", "/api/places/1", 200, JSON, &wrong).unwrap_err();
        let errors = errors.join("\n");
        for part in ["/id", "/tags/0", "name", "extra"] {
            assert!(errors.contains(part), "{part} in\n{errors}");
        }
    }

    #[test]
    fn an_undocumented_status_path_method_or_type_does_not_conform() {
        let place = json!({ "id": ID, "name": "Home" });
        let mismatch = |result: Result<(), Vec<String>>| result.unwrap_err().join("\n");
        assert!(
            mismatch(check("GET", "/api/places/1", 500, JSON, &place))
                .contains("does not document 500")
        );
        assert!(mismatch(check("GET", "/api/people/1", 200, JSON, &place)).contains("no path"));
        assert!(mismatch(check("PUT", "/api/places/1", 200, JSON, &place)).contains("no put"));
        assert!(
            mismatch(check(
                "GET",
                "/api/places/1",
                200,
                Some("text/plain"),
                &place
            ))
            .contains("text/plain")
        );
        assert!(mismatch(check("DELETE", "/api/places/1", 204, None, &place)).contains("no body"));
        let broken = Conformance::new(document()).check("GET", "/api/places/1", 200, JSON, b"{");
        assert!(mismatch(broken).contains("not JSON"));
    }

    fn server() -> axum_test::TestServer {
        use axum::{Json, Router, routing::get};
        let app = Router::new()
            .route(
                "/api/places/{id}",
                get(|| async { Json(json!({ "id": ID, "name": "Home" })) }),
            )
            .route(
                "/api/places/new",
                get(|| async { Json(json!({ "id": 1 })) }),
            );
        axum_test::TestServer::new(app)
    }

    #[tokio::test]
    async fn a_real_response_is_checked_by_its_request() {
        let server = server();
        Conformance::new(document()).assert(&server.get("/api/places/1").await);
    }

    #[tokio::test]
    #[should_panic(expected = "GET /api/places/new answered 200")]
    async fn a_real_response_that_does_not_conform_fails_the_test() {
        let server = server();
        Conformance::new(document()).assert(&server.get("/api/places/new").await);
    }

    #[test]
    #[should_panic(expected = "checks OpenAPI 3.1 documents")]
    fn an_openapi_3_0_document_is_refused() {
        let _ = Conformance::new(json!({ "openapi": "3.0.3", "paths": {} }));
    }
}

//! PASETO tokens for tests, signed under a throwaway key, for a service whose guard
//! is `axa-paseto-auth`.
//!
//! Build the guard's verifier from [`TestKeys::verifier`] in the service's test boot,
//! then mint a token per caller:
//!
//! ```
//! use axa_test::paseto::TestKeys;
//!
//! let keys = TestKeys::new();
//! let verifier = keys.verifier("authentication-service", "todo-service");
//! let acme = keys
//!     .token("authentication-service", "todo-service")
//!     .attr("tenant", ["acme"])
//!     .attr("access", ["write"])
//!     .sign();
//! assert!(verifier.verify(&acme).is_ok());
//! ```
//!
//! **Never use these keys outside tests.** The seed is in this source, so anyone could
//! mint a token they verify. A verifier from [`TestKeys`] trusts only its own key, so a
//! service built with a real verifier never accepts these tokens.

use std::collections::BTreeMap;

use authentication_verifier::Verifier;
use base64::{Engine, engine::general_purpose::URL_SAFE_NO_PAD};
use ed25519_dalek::SigningKey;
use rusty_paseto::core::{Footer, Key, Paseto, PasetoAsymmetricPrivateKey, Payload, Public, V4};
use serde_json::{Value, json};
use sha2::{Digest, Sha256};

/// The seed [`TestKeys::new`] signs with. It is public, and protects nothing.
const TEST_SEED: [u8; 32] = [42; 32];

/// `iat` for every test token: 14 November 2023.
const ISSUED_AT: i64 = 1_700_000_000;

/// `exp` for a token that does not expire within any test run.
const FAR_FUTURE: i64 = ISSUED_AT + 10_000_000_000;

/// A throwaway Ed25519 signing key, its key set, and tokens it signs.
#[derive(Clone)]
pub struct TestKeys {
    seed: [u8; 32],
}

impl std::fmt::Debug for TestKeys {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("TestKeys")
            .field("kid", &self.kid())
            .finish_non_exhaustive()
    }
}

impl Default for TestKeys {
    fn default() -> Self {
        Self::new()
    }
}

impl TestKeys {
    /// The test key every call shares.
    #[must_use]
    pub fn new() -> Self {
        Self { seed: TEST_SEED }
    }

    /// A key from `seed`, such as a second key to show that a token signed by another
    /// key is refused.
    #[must_use]
    pub fn from_seed(seed: [u8; 32]) -> Self {
        Self { seed }
    }

    fn signing_key(&self) -> SigningKey {
        SigningKey::from_bytes(&self.seed)
    }

    /// The key's id, as the auth service derives it: the SHA-256 of the public key,
    /// in unpadded URL-safe base64.
    #[must_use]
    pub fn kid(&self) -> String {
        let public = self.signing_key().verifying_key().to_bytes();
        URL_SAFE_NO_PAD.encode(Sha256::digest(public))
    }

    /// The public key set, as the auth service publishes it, with this one key.
    #[must_use]
    pub fn key_set(&self) -> Value {
        let public = self.signing_key().verifying_key().to_bytes();
        json!({
            "keys": [{
                "kty": "OKP", "crv": "Ed25519", "use": "sig",
                "kid": self.kid(), "x": URL_SAFE_NO_PAD.encode(public),
            }]
        })
    }

    /// A verifier that trusts this key only, for tokens from `issuer` to `audience`.
    ///
    /// # Panics
    ///
    /// Never, as the key set it builds is always well formed.
    #[must_use]
    pub fn verifier(&self, issuer: &str, audience: &str) -> Verifier {
        Verifier::from_paseto_keys_value(&self.key_set(), issuer, audience)
            .expect("a test key set is well formed")
    }

    /// A token from `issuer` to `audience`, signed by this key, for a caller with no
    /// attributes until [`TestToken::attr`] adds some.
    #[must_use]
    pub fn token(&self, issuer: &str, audience: &str) -> TestToken {
        TestToken {
            keys: self.clone(),
            sub: "11111111-1111-1111-1111-111111111111".to_string(),
            email: "test@example.com".to_string(),
            name: "Test Caller".to_string(),
            iss: issuer.to_string(),
            aud: audience.to_string(),
            exp: FAR_FUTURE,
            sid: "test-session".to_string(),
            attrs: BTreeMap::new(),
        }
    }
}

/// A token being built, signed by [`TestToken::sign`].
#[derive(Debug, Clone)]
pub struct TestToken {
    keys: TestKeys,
    sub: String,
    email: String,
    name: String,
    iss: String,
    aud: String,
    exp: i64,
    sid: String,
    attrs: BTreeMap<String, Vec<String>>,
}

impl TestToken {
    /// Set `name` in the caller's `attrs` to `values`, such as `("tenant", ["acme"])`
    /// or `("access", ["write"])`.
    #[must_use]
    pub fn attr<I, S>(mut self, name: &str, values: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        self.attrs.insert(
            name.to_string(),
            values.into_iter().map(Into::into).collect(),
        );
        self
    }

    /// The caller's subject, their stable id.
    #[must_use]
    pub fn subject(mut self, sub: &str) -> Self {
        self.sub = sub.to_string();
        self
    }

    /// The caller's email.
    #[must_use]
    pub fn email(mut self, email: &str) -> Self {
        self.email = email.to_string();
        self
    }

    /// Expire at `exp`, in Unix seconds, such as a time in the past to show that an
    /// expired token is refused.
    #[must_use]
    pub fn expires_at(mut self, exp: i64) -> Self {
        self.exp = exp;
        self
    }

    /// The signed token, to send as `authorization: Bearer <token>`.
    ///
    /// # Panics
    ///
    /// Never, as every claim is plain JSON and the key is always valid.
    #[must_use]
    pub fn sign(&self) -> String {
        let payload = json!({
            "sub": self.sub, "email": self.email, "name": self.name,
            "iss": self.iss, "aud": self.aud,
            "exp": self.exp, "iat": ISSUED_AT, "sid": self.sid,
            "attrs": self.attrs,
        })
        .to_string();
        let key = Key::<64>::from(self.keys.signing_key().to_keypair_bytes());
        let private = PasetoAsymmetricPrivateKey::<V4, Public>::from(&key);
        let footer = json!({ "kid": self.keys.kid() }).to_string();
        let mut builder = Paseto::<V4, Public>::builder();
        builder.set_payload(Payload::from(payload.as_str()));
        builder.set_footer(Footer::from(footer.as_str()));
        builder.try_sign(&private).expect("a test token signs")
    }

    /// The `authorization` header value for this token.
    #[must_use]
    pub fn bearer(&self) -> String {
        format!("Bearer {}", self.sign())
    }
}

//! A Postgres database of its own for each test, cloned from a template that is
//! migrated once.
//!
//! Migrating a fresh database for every test is slow, and sharing one database makes
//! tests wait for each other or see each other's rows. [`TestDatabase::new`] migrates a
//! template database once, named for the migrations it holds, and then clones it with
//! `CREATE DATABASE ... TEMPLATE`, which copies files rather than running SQL.
//!
//! [`TestDatabase::close`] drops the clone and waits. A guard dropped without it, as
//! when a test panics, hands its clone to a thread of its own that drops it, rather
//! than blocking the test's runtime: `DROP DATABASE` waits on every connection being
//! opened, and a blocked runtime would never finish opening its own. A clone left by a
//! process that ended first is swept by the next [`TestDatabase::new`], once no session
//! has used it for two minutes.
//!
//! ```ignore
//! use axa_test::postgres::TestDatabase;
//!
//! static MIGRATOR: sqlx::migrate::Migrator = sqlx::migrate!();
//!
//! #[tokio::test]
//! #[ignore = "needs AXA_TEST_DB_URL"]
//! async fn a_todo_is_saved() {
//!     let db = TestDatabase::new(&MIGRATOR).await.unwrap();
//!     sqlx::query("INSERT INTO todos (title) VALUES ('Milk')")
//!         .execute(&db.pool)
//!         .await
//!         .unwrap();
//! }
//! ```
//!
//! `AXA_TEST_DB_URL` names a server and a role that may create databases. Each
//! template is kept for the next run, as `axa_test_template_` and a hash of the
//! migrations, so a changed migration gets a template of its own. Drop old ones with
//! [`drop_templates`].

use std::{
    sync::{
        Mutex, OnceLock,
        atomic::{AtomicU64, Ordering},
        mpsc::{Sender, channel},
    },
    time::{Duration, SystemTime, UNIX_EPOCH},
};

use axa_postgres_sqlx::{
    quote_identifier,
    sqlx::{
        self, AssertSqlSafe, Connection, PgConnection, PgPool, Row,
        migrate::Migrator,
        postgres::{PgConnectOptions, PgPoolOptions},
    },
};

/// The variable that names the server tests may create databases on.
pub const URL_VAR: &str = "AXA_TEST_DB_URL";

/// What every template's name starts with.
const TEMPLATE_PREFIX: &str = "axa_test_template_";

/// What every clone's name starts with.
const CLONE_PREFIX: &str = "axa_test_";

/// The advisory lock a process holds while it builds a template, so that two test
/// binaries starting together build it once.
const TEMPLATE_LOCK: i64 = 0x0061_7861_7465_7374;

/// How many clones this process has made, to keep their names apart.
static CLONES: AtomicU64 = AtomicU64::new(0);

/// How old a clone no session is using must be before another process sweeps it.
const ABANDONED_SECONDS: u64 = 120;

/// Seconds since the Unix epoch.
fn now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |since| since.as_secs())
}

/// A database of a test's own, dropped when this is.
pub struct TestDatabase {
    /// A pool for the database.
    pub pool: PgPool,
    /// How to connect to the database, as for a service's own pool.
    pub options: PgConnectOptions,
    name: String,
    server: PgConnectOptions,
}

impl std::fmt::Debug for TestDatabase {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("TestDatabase")
            .field("name", &self.name)
            .finish_non_exhaustive()
    }
}

/// The template's name for `migrator`: a hash of each migration's version and
/// checksum, so that a changed migration names another template. It is FNV-1a, stable
/// across builds and Rust versions, so a template outlives the build that made it.
#[must_use]
pub fn template_name(migrator: &Migrator) -> String {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for migration in migrator.iter() {
        let version = migration.version.to_le_bytes();
        for byte in version.iter().chain(migration.checksum.iter()) {
            hash ^= u64::from(*byte);
            hash = hash.wrapping_mul(0x0100_0000_01b3);
        }
    }
    format!("{TEMPLATE_PREFIX}{hash:016x}")
}

/// A name no other clone has, in this process or another, that starts with when it
/// was made, for the sweep.
fn clone_name() -> String {
    format!(
        "{CLONE_PREFIX}{}_{}_{}",
        now(),
        std::process::id(),
        CLONES.fetch_add(1, Ordering::Relaxed)
    )
}

/// When the clone `name` was made, in seconds since the Unix epoch, or `None` for a
/// name that is not a clone's.
fn made_at(name: &str) -> Option<u64> {
    let rest = name.strip_prefix(CLONE_PREFIX)?;
    let mut parts = rest.split('_');
    let made = parts.next()?.parse().ok()?;
    (parts.count() == 2).then_some(made)
}

/// Drop every clone made over two minutes ago that no session is using. A clone in
/// use always has one, as its pool keeps a connection open.
async fn sweep(connection: &mut PgConnection) -> Result<(), sqlx::Error> {
    let names: Vec<String> = sqlx::query(
        "SELECT datname FROM pg_database AS d WHERE datname LIKE 'axa\\_test\\_%' \
         AND NOT EXISTS (SELECT FROM pg_stat_activity AS a WHERE a.datname = d.datname)",
    )
    .fetch_all(&mut *connection)
    .await?
    .iter()
    .map(|row| row.try_get("datname"))
    .collect::<Result<_, _>>()?;
    let cutoff = now().saturating_sub(ABANDONED_SECONDS);
    for name in names {
        if made_at(&name).is_some_and(|made| made < cutoff) {
            execute(
                connection,
                format!("DROP DATABASE IF EXISTS {} WITH (FORCE)", quoted(&name)?),
            )
            .await?;
        }
    }
    Ok(())
}

/// A clone for the cleaner to drop, and where to say it is gone.
type Job = (PgConnectOptions, String, Sender<()>);

/// How long a dropped guard waits for its clone to go. Its test's runtime is blocked
/// meanwhile, and a connection that runtime was opening holds up `DROP DATABASE`, so
/// the wait is short: past it, the clone still goes once the runtime moves on.
const DROP_WAIT: Duration = Duration::from_secs(2);

/// The thread that drops the clones of guards dropped without [`TestDatabase::close`].
fn cleaner() -> &'static Mutex<Sender<Job>> {
    static CLEANER: OnceLock<Mutex<Sender<Job>>> = OnceLock::new();
    CLEANER.get_or_init(|| {
        let (sender, receiver) = channel::<Job>();
        std::thread::spawn(move || {
            let runtime = match tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
            {
                Ok(runtime) => runtime,
                Err(error) => {
                    eprintln!("axa-test: cannot drop test databases: {error}");
                    return;
                }
            };
            for (server, name, done) in receiver {
                runtime.block_on(drop_database(&server, &name));
                let _ = done.send(());
            }
        });
        Mutex::new(sender)
    })
}

/// `name`, quoted, which every name here is safe to be.
fn quoted(name: &str) -> Result<String, sqlx::Error> {
    quote_identifier(name)
        .ok_or_else(|| sqlx::Error::Configuration(format!("{name} is not a safe name").into()))
}

async fn execute(connection: &mut PgConnection, sql: String) -> Result<(), sqlx::Error> {
    sqlx::query(AssertSqlSafe(sql))
        .execute(&mut *connection)
        .await
        .map(|_| ())
}

async fn database_exists(connection: &mut PgConnection, name: &str) -> Result<bool, sqlx::Error> {
    sqlx::query("SELECT EXISTS (SELECT FROM pg_database WHERE datname = $1) AS found")
        .bind(name)
        .fetch_one(&mut *connection)
        .await?
        .try_get("found")
}

/// Make the template for `migrator`, unless it is there. It is built under another
/// name and renamed when its migrations have run, so a run that dies halfway leaves no
/// template that looks finished.
async fn ensure_template(
    connection: &mut PgConnection,
    server: &PgConnectOptions,
    migrator: &Migrator,
    template: &str,
) -> Result<(), sqlx::Error> {
    if database_exists(connection, template).await? {
        return Ok(());
    }
    sqlx::query("SELECT pg_advisory_lock($1)")
        .bind(TEMPLATE_LOCK)
        .execute(&mut *connection)
        .await?;
    let built = build_template(connection, server, migrator, template).await;
    sqlx::query("SELECT pg_advisory_unlock($1)")
        .bind(TEMPLATE_LOCK)
        .execute(&mut *connection)
        .await?;
    built
}

async fn build_template(
    connection: &mut PgConnection,
    server: &PgConnectOptions,
    migrator: &Migrator,
    template: &str,
) -> Result<(), sqlx::Error> {
    // Another process may have built it while this one waited for the lock.
    if database_exists(connection, template).await? {
        return Ok(());
    }
    let partial = format!("{template}_partial");
    execute(
        connection,
        format!("DROP DATABASE IF EXISTS {} WITH (FORCE)", quoted(&partial)?),
    )
    .await?;
    execute(connection, format!("CREATE DATABASE {}", quoted(&partial)?)).await?;
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect_with(server.clone().database(&partial))
        .await?;
    let migrated = axa_postgres_sqlx::migrate(&pool, migrator).await;
    pool.close().await;
    if let Err(error) = migrated {
        drop_database(server, &partial).await;
        return Err(error.into());
    }
    execute(
        connection,
        format!(
            "ALTER DATABASE {} RENAME TO {}",
            quoted(&partial)?,
            quoted(template)?
        ),
    )
    .await
}

impl TestDatabase {
    /// A database migrated by `migrator`, on the server `AXA_TEST_DB_URL` names.
    ///
    /// # Errors
    ///
    /// Fails when `AXA_TEST_DB_URL` is unset or is not a Postgres URL, when the server
    /// cannot be reached or the role may not create databases, or when a migration
    /// fails.
    pub async fn new(migrator: &Migrator) -> Result<Self, sqlx::Error> {
        let url = std::env::var(URL_VAR)
            .map_err(|_| sqlx::Error::Configuration(format!("{URL_VAR} is not set").into()))?;
        Self::on(url.parse()?, migrator).await
    }

    /// A database migrated by `migrator`, on the server `server` reaches. The
    /// database `server` names is used only to create and drop the others.
    ///
    /// # Errors
    ///
    /// As [`TestDatabase::new`].
    pub async fn on(server: PgConnectOptions, migrator: &Migrator) -> Result<Self, sqlx::Error> {
        let template = template_name(migrator);
        let name = clone_name();
        let mut connection = PgConnection::connect_with(&server).await?;
        sweep(&mut connection).await?;
        ensure_template(&mut connection, &server, migrator, &template).await?;
        execute(
            &mut connection,
            format!(
                "CREATE DATABASE {} TEMPLATE {}",
                quoted(&name)?,
                quoted(&template)?
            ),
        )
        .await?;
        connection.close().await?;
        let options = server.clone().database(&name);
        // The connection kept open is what tells the sweep this clone is in use.
        let pool = match PgPoolOptions::new()
            .min_connections(1)
            .max_connections(5)
            .idle_timeout(None)
            .connect_with(options.clone())
            .await
        {
            Ok(pool) => pool,
            Err(error) => {
                drop_database(&server, &name).await;
                return Err(error);
            }
        };
        Ok(Self {
            pool,
            options,
            name,
            server,
        })
    }

    /// The database's name.
    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }

    /// Close the pool and drop the database, and wait for both.
    pub async fn close(mut self) {
        let name = std::mem::take(&mut self.name);
        self.pool.close().await;
        drop_database(&self.server, &name).await;
    }
}

/// Drop the database `name`, ending its sessions. A failure is printed, as there is
/// nothing a test could do about it.
async fn drop_database(server: &PgConnectOptions, name: &str) {
    let dropped = async {
        let mut connection = PgConnection::connect_with(server).await?;
        execute(
            &mut connection,
            format!("DROP DATABASE IF EXISTS {} WITH (FORCE)", quoted(name)?),
        )
        .await?;
        connection.close().await
    };
    if let Err(error) = dropped.await {
        eprintln!("axa-test: could not drop the test database {name}: {error}");
    }
}

impl Drop for TestDatabase {
    fn drop(&mut self) {
        if self.name.is_empty() {
            return;
        }
        // Calling it marks the pool closed at once, so it opens no more connections,
        // which `DROP DATABASE` would wait on. Its sessions end with `WITH (FORCE)`.
        drop(self.pool.close());
        let (done, gone) = channel();
        let job = (self.server.clone(), std::mem::take(&mut self.name), done);
        let sent = cleaner()
            .lock()
            .map_err(|_| ())
            .and_then(|sender| sender.send(job).map_err(|_| ()));
        if sent.is_err() {
            eprintln!("axa-test: a test database was left for the next run to sweep");
            return;
        }
        // Mostly this is quick, and so the clone is gone before a test binary exits.
        let _ = gone.recv_timeout(DROP_WAIT);
    }
}

/// Drop every template on the server `server` reaches but `keep`, as after a
/// migration changed. It answers how many it dropped.
///
/// # Errors
///
/// Fails when the server cannot be reached, or a template cannot be dropped.
pub async fn drop_templates(
    server: &PgConnectOptions,
    keep: &Migrator,
) -> Result<usize, sqlx::Error> {
    let keep = template_name(keep);
    let mut connection = PgConnection::connect_with(server).await?;
    let names: Vec<String> = sqlx::query("SELECT datname FROM pg_database WHERE datname LIKE $1")
        .bind(format!("{TEMPLATE_PREFIX}%"))
        .fetch_all(&mut connection)
        .await?
        .iter()
        .map(|row| row.try_get("datname"))
        .collect::<Result<_, _>>()?;
    let mut dropped = 0;
    for name in names.iter().filter(|name| **name != keep) {
        execute(
            &mut connection,
            format!("DROP DATABASE IF EXISTS {} WITH (FORCE)", quoted(name)?),
        )
        .await?;
        dropped += 1;
    }
    connection.close().await?;
    Ok(dropped)
}

