//! Finding what is wrong with asynchronous code while it runs.

use std::{
    future::Future,
    pin::Pin,
    task::{Context, Poll},
    time::{Duration, Instant},
};

use tokio::{runtime::Handle, task::JoinHandle};

/// A future being watched. See [`Watch::watch`].
#[must_use = "a future does nothing unless it is awaited"]
pub struct Watched<F> {
    future: Pin<Box<F>>,
    name: &'static str,
    threshold: Duration,
    started: Option<Instant>,
}

impl<F: Future> Future for Watched<F> {
    type Output = F::Output;

    fn poll(self: Pin<&mut Self>, context: &mut Context<'_>) -> Poll<F::Output> {
        let this = self.get_mut();
        let started = *this.started.get_or_insert_with(Instant::now);
        let polled = Instant::now();
        let result = this.future.as_mut().poll(context);
        let poll_time = polled.elapsed();
        if poll_time >= this.threshold {
            tracing::warn!(
                name = this.name,
                poll_ms = millis(poll_time),
                "future_blocked_runtime",
            );
        }
        if result.is_ready() {
            let total = started.elapsed();
            if total >= this.threshold {
                tracing::warn!(name = this.name, total_ms = millis(total), "future_slow",);
            }
        }
        result
    }
}

/// Watches a future for the two ways it can be slow.
pub trait Watch: Future + Sized {
    /// Logs a warning if this future takes `threshold` or longer.
    ///
    /// `future_blocked_runtime` means one poll took that long: it held a runtime
    /// thread, and other tasks waited behind it, which usually means blocking code
    /// that belongs in `spawn_blocking`. `future_slow` means it took that long in
    /// all, which is often only a slow peer.
    ///
    /// The future gets a little slower, by two clock reads each poll, and one
    /// allocation. `name` is fixed text, so that no value reaches the logs by way
    /// of it.
    fn watch(self, name: &'static str, threshold: Duration) -> Watched<Self> {
        Watched {
            future: Box::pin(self),
            name,
            threshold,
            started: None,
        }
    }
}

impl<F: Future> Watch for F {}

/// What the Tokio runtime is doing at one moment.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RuntimeSnapshot {
    /// Threads running tasks.
    pub workers: usize,
    /// Tasks not yet finished.
    pub alive_tasks: usize,
    /// Tasks waiting in the shared queue. A number that keeps growing means the
    /// runtime is falling behind.
    pub queue_depth: usize,
}

/// A snapshot of the current Tokio runtime.
///
/// # Panics
///
/// Outside a Tokio runtime.
#[must_use]
pub fn runtime_snapshot() -> RuntimeSnapshot {
    snapshot_of(&Handle::current())
}

fn snapshot_of(handle: &Handle) -> RuntimeSnapshot {
    let metrics = handle.metrics();
    RuntimeSnapshot {
        workers: metrics.num_workers(),
        alive_tasks: metrics.num_alive_tasks(),
        queue_depth: metrics.global_queue_depth(),
    }
}

/// Settings for [`monitor_runtime`].
#[derive(Debug, Clone, Copy)]
pub struct RuntimeMonitor {
    /// How often to check.
    pub interval: Duration,
    /// How late a check may wake before it counts as a stall.
    pub max_lag: Duration,
}

impl Default for RuntimeMonitor {
    /// Check each second, and allow a check to wake 100 ms late.
    fn default() -> Self {
        Self {
            interval: Duration::from_secs(1),
            max_lag: Duration::from_millis(100),
        }
    }
}

/// Starts a task that notices when the runtime stalls.
///
/// The task sleeps, and measures how late it wakes. A task that wakes late could not
/// get a thread, so neither could the service's other tasks. It then logs a warning,
/// `runtime_lagging`, with a [`RuntimeSnapshot`].
///
/// Dropping the handle leaves it running. Call `abort` on the handle to stop it, and
/// it stops with the runtime in any case.
///
/// # Panics
///
/// Outside a Tokio runtime.
#[must_use = "keep the handle to be able to stop the monitor"]
pub fn monitor_runtime(monitor: RuntimeMonitor) -> JoinHandle<()> {
    let handle = Handle::current();
    tokio::spawn(async move {
        loop {
            let expected = Instant::now() + monitor.interval;
            tokio::time::sleep(monitor.interval).await;
            let lag = Instant::now().saturating_duration_since(expected);
            if lag >= monitor.max_lag {
                let snapshot = snapshot_of(&handle);
                tracing::warn!(
                    lag_ms = millis(lag),
                    workers = snapshot.workers,
                    alive_tasks = snapshot.alive_tasks,
                    queue_depth = snapshot.queue_depth,
                    "runtime_lagging",
                );
            }
        }
    })
}

/// Logs panics as errors, replacing the panic hook that writes to stderr.
///
/// A panic in a spawned task otherwise reaches only stderr, outside the service's
/// log format and without its request id. The line names the source location and the
/// thread, and carries the span that panicked. The panic's own text is left out, as
/// it can quote anything, and so is a backtrace.
///
/// Call it once, from `main`. It replaces any earlier hook. Under `axa`, a panic in a
/// handler then leaves two lines: this one, which says where, and `handler_panicked`.
pub fn log_panics() {
    std::panic::set_hook(Box::new(|info| {
        let location = info
            .location()
            .map(|location| format!("{}:{}", location.file(), location.line()));
        tracing::error!(
            location = location.as_deref().unwrap_or("unknown"),
            thread = std::thread::current().name().unwrap_or("unnamed"),
            request_id = crate::current_request_id().as_deref().unwrap_or(""),
            "panicked",
        );
    }));
}

fn millis(duration: Duration) -> u64 {
    u64::try_from(duration.as_millis()).unwrap_or(u64::MAX)
}

#[cfg(test)]
mod tests {
    use std::sync::{Mutex, MutexGuard};

    use tracing_subscriber::layer::SubscriberExt;

    use super::*;
    use crate::test_support::Lines;

    fn capture() -> (Lines, tracing::subscriber::DefaultGuard) {
        let lines = Lines::default();
        let subscriber = tracing_subscriber::registry().with(lines.layer());
        let guard = tracing::subscriber::set_default(subscriber);
        (lines, guard)
    }

    /// A panic hook is process-wide, so its test must not race another panic.
    fn panic_hook_lock() -> MutexGuard<'static, ()> {
        static LOCK: Mutex<()> = Mutex::new(());
        LOCK.lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }

    #[tokio::test]
    async fn a_blocking_future_is_reported() {
        let (lines, _guard) = capture();
        let value = async {
            std::thread::sleep(Duration::from_millis(10));
            7
        }
        .watch("blocker", Duration::from_millis(5))
        .await;
        let text = lines.text();
        assert_eq!(value, 7);
        assert!(text.contains("future_blocked_runtime"), "{text}");
        assert!(text.contains("blocker"), "{text}");
    }

    #[tokio::test]
    async fn a_future_that_only_waits_is_slow_but_not_blocking() {
        let (lines, _guard) = capture();
        tokio::time::sleep(Duration::from_millis(30))
            .watch("waiter", Duration::from_millis(10))
            .await;
        let text = lines.text();
        assert!(text.contains("future_slow"), "{text}");
        assert!(!text.contains("future_blocked_runtime"), "{text}");
    }

    #[tokio::test]
    async fn a_quick_future_is_not_reported() {
        let (lines, _guard) = capture();
        async {}.watch("quick", Duration::from_hours(1)).await;
        assert_eq!(lines.text(), "");
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_snapshot_describes_the_runtime() {
        let snapshot = runtime_snapshot();
        assert_eq!(snapshot.workers, 2);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_stalled_runtime_is_reported() {
        let (lines, _guard) = capture();
        let monitor = monitor_runtime(RuntimeMonitor {
            interval: Duration::from_millis(5),
            max_lag: Duration::from_millis(10),
        });
        // Let the monitor start its sleep, then hold the only thread past it.
        tokio::time::sleep(Duration::from_millis(1)).await;
        std::thread::sleep(Duration::from_millis(30));
        // The monitor and this test wake together, in either order, so wait for the
        // warning rather than for a fixed time.
        let until = Instant::now() + Duration::from_secs(5);
        while !lines.text().contains("runtime_lagging") && Instant::now() < until {
            tokio::time::sleep(Duration::from_millis(1)).await;
        }
        monitor.abort();
        let text = lines.text();
        assert!(text.contains("runtime_lagging"), "{text}");
        assert!(text.contains("workers=1"), "{text}");
    }

    #[test]
    fn a_panic_is_logged_without_its_text() {
        let _lock = panic_hook_lock();
        let previous = std::panic::take_hook();
        log_panics();
        let (lines, guard) = capture();
        let result = std::panic::catch_unwind(|| panic!("the secret is hunter2"));
        drop(guard);
        std::panic::set_hook(previous);

        let text = lines.text();
        assert!(result.is_err());
        assert!(text.contains("panicked"), "{text}");
        assert!(text.contains("diagnostics.rs"), "{text}");
        assert!(!text.contains("hunter2"), "{text}");
    }
}

//! Redaction, request tracking, and asynchronous diagnostics over `tracing`.
//!
//! `axa` already logs: it installs the subscriber, opens a span for each request, and
//! puts the request id on every line written while serving it. This crate adds what
//! a service needs next, and what that span cannot reach by itself.
//!
//! | Need | Use |
//! |---|---|
//! | Keep a secret out of a log field | [`Redacted`] |
//! | Find the spans that took too long | [`SlowSpans`] |
//! | Read the request id deep in the code | [`track`], [`current_request_id`] |
//! | Send the request id to a peer service | [`propagate`] |
//! | Keep a request's id and span in a spawned task | [`spawn`] |
//! | Catch a future that blocks the runtime | [`Watch::watch`] |
//! | Notice a stalled runtime | [`monitor_runtime`] |
//! | Log panics, in spawned tasks too | [`log_panics`] |
//!
//! None of this needs `tokio_unstable`, which is why it reports less than
//! `tokio-console` does: a service can run it in production.
//!
//! # Use
//!
//! ```no_run
//! use std::time::Duration;
//!
//! use axa_tracing::{Redacted, SlowSpans, Watch, current_request_id, track};
//! use axum::{Router, middleware::from_fn, routing::get};
//!
//! async fn handler() -> String {
//!     tracing::info!(token = %Redacted("secret"), "signing in");
//!     load().watch("load", Duration::from_millis(100)).await;
//!     current_request_id().unwrap_or_default()
//! }
//!
//! async fn load() {}
//!
//! # fn example() {
//! axa_tracing::log_panics();
//! let app: Router = Router::new()
//!     .route("/", get(handler))
//!     .layer(from_fn(track));
//! let slow_spans = SlowSpans::new(Duration::from_secs(1));
//! # let _ = (app, slow_spans);
//! # }
//! ```
//!
//! Hand [`SlowSpans`] to `axa::logger::init_with`, so that it sits beside the
//! service's log format and filter.

mod diagnostics;
mod logging;
mod request;
#[cfg(test)]
mod test_support;

pub use diagnostics::{
    RuntimeMonitor, RuntimeSnapshot, Watch, Watched, log_panics, monitor_runtime, runtime_snapshot,
};
pub use logging::{Redacted, SlowSpans};
pub use request::{X_REQUEST_ID, current_request_id, propagate, spawn, track};

//! Log fields that hide their value, and a layer that reports slow spans.

use std::{
    fmt,
    time::{Duration, Instant},
};

use tracing::{Subscriber, span};
use tracing_subscriber::{Layer, layer::Context, registry::LookupSpan};

/// A log field that never prints its value, in `Display` or `Debug`.
///
/// Use it for a token, a key, or personal data, so that a later change to the log
/// format, or a derived `Debug` on the struct around it, cannot print the value.
///
/// ```
/// use axa_tracing::Redacted;
///
/// assert_eq!(format!("{}", Redacted("secret")), "[redacted]");
/// assert_eq!(format!("{:?}", Redacted("secret")), "[redacted]");
/// ```
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Redacted<T>(pub T);

impl<T> fmt::Display for Redacted<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("[redacted]")
    }
}

impl<T> fmt::Debug for Redacted<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("[redacted]")
    }
}

/// How one span spent its time so far.
struct Timing {
    created: Instant,
    entered: Option<Instant>,
    busy: Duration,
}

/// Logs a warning, `slow_span`, for each span that lasts `threshold` or longer.
///
/// The warning names the span and how long it took, split into `busy_ms`, while its
/// code was running, and `idle_ms`, while it was waiting. It is written inside the
/// closed span, so it carries that span's fields, including a request id.
///
/// A large `idle_ms` means something it awaited was slow. A large `busy_ms` in an
/// async span means it held a runtime thread for that long.
#[derive(Debug, Clone, Copy)]
pub struct SlowSpans {
    threshold: Duration,
}

impl SlowSpans {
    /// Report spans lasting `threshold` or longer.
    #[must_use]
    pub const fn new(threshold: Duration) -> Self {
        Self { threshold }
    }
}

impl<S> Layer<S> for SlowSpans
where
    S: Subscriber + for<'lookup> LookupSpan<'lookup>,
{
    fn on_new_span(&self, _attrs: &span::Attributes<'_>, id: &span::Id, ctx: Context<'_, S>) {
        if let Some(span) = ctx.span(id) {
            span.extensions_mut().insert(Timing {
                created: Instant::now(),
                entered: None,
                busy: Duration::ZERO,
            });
        }
    }

    fn on_enter(&self, id: &span::Id, ctx: Context<'_, S>) {
        if let Some(span) = ctx.span(id)
            && let Some(timing) = span.extensions_mut().get_mut::<Timing>()
        {
            // A span entered twice at once counts from its first entry.
            timing.entered.get_or_insert_with(Instant::now);
        }
    }

    fn on_exit(&self, id: &span::Id, ctx: Context<'_, S>) {
        if let Some(span) = ctx.span(id)
            && let Some(timing) = span.extensions_mut().get_mut::<Timing>()
            && let Some(entered) = timing.entered.take()
        {
            timing.busy += entered.elapsed();
        }
    }

    fn on_close(&self, id: span::Id, ctx: Context<'_, S>) {
        let Some(span) = ctx.span(&id) else {
            return;
        };
        let report = span.extensions().get::<Timing>().and_then(|timing| {
            let total = timing.created.elapsed();
            (total >= self.threshold).then_some((total, timing.busy))
        });
        if let Some((total, busy)) = report {
            tracing::warn!(
                parent: &id,
                span = span.name(),
                busy_ms = millis(busy),
                idle_ms = millis(total.saturating_sub(busy)),
                "slow_span",
            );
        }
    }
}

fn millis(duration: Duration) -> u64 {
    u64::try_from(duration.as_millis()).unwrap_or(u64::MAX)
}

#[cfg(test)]
mod tests {
    use std::thread::sleep;

    use tracing_subscriber::layer::SubscriberExt;

    use super::*;
    use crate::test_support::Lines;

    fn logged(threshold: Duration, body: impl FnOnce()) -> String {
        let lines = Lines::default();
        let subscriber = tracing_subscriber::registry()
            .with(SlowSpans::new(threshold))
            .with(lines.layer());
        tracing::subscriber::with_default(subscriber, body);
        lines.text()
    }

    #[test]
    fn redacted_hides_its_value_in_a_log_line() {
        let text = logged(Duration::from_hours(1), || {
            tracing::info!(token = %Redacted("hunter2"), other = ?Redacted("hunter3"), "signing in");
        });
        assert!(text.contains("[redacted]"), "{text}");
        assert!(!text.contains("hunter"), "{text}");
    }

    #[test]
    fn a_slow_span_is_reported_with_its_fields() {
        let text = logged(Duration::from_millis(5), || {
            let span = tracing::info_span!("load", request_id = "abc");
            let _entered = span.enter();
            sleep(Duration::from_millis(10));
        });
        assert!(text.contains("slow_span"), "{text}");
        assert!(text.contains("span=\"load\""), "{text}");
        assert!(text.contains("request_id"), "{text}");
    }

    #[test]
    fn a_quick_span_is_not_reported() {
        let text = logged(Duration::from_hours(1), || {
            let span = tracing::info_span!("load");
            let _entered = span.enter();
        });
        assert!(!text.contains("slow_span"), "{text}");
    }

    #[test]
    fn busy_and_idle_time_are_told_apart() {
        let text = logged(Duration::from_millis(30), || {
            let span = tracing::info_span!("load");
            {
                let _entered = span.enter();
                sleep(Duration::from_millis(5));
            }
            sleep(Duration::from_millis(40));
        });
        let number = |name: &str| -> u64 {
            let at = text.find(name).expect("field is logged") + name.len() + 1;
            let digits: String = text[at..]
                .chars()
                .take_while(char::is_ascii_digit)
                .collect();
            digits.parse().unwrap()
        };
        assert!(number("idle_ms") >= 30, "{text}");
        assert!(number("busy_ms") < number("idle_ms"), "{text}");
    }
}

//! Tracking a request through the code it runs, the tasks it spawns, and its peers.

use std::{future::Future, sync::Arc};

use axum::{
    extract::Request,
    http::{HeaderMap, HeaderName, HeaderValue},
    middleware::Next,
    response::Response,
};
use tokio::task::JoinHandle;
use tracing::Instrument;
use uuid::Uuid;

/// The header carrying a request's id.
pub const X_REQUEST_ID: HeaderName = HeaderName::from_static("x-request-id");

/// The longest id kept from a caller, as `axa` keeps.
const MAX_REQUEST_ID_LEN: usize = 255;

tokio::task_local! {
    static REQUEST_ID: Arc<str>;
}

/// Keep a caller's id only after removing unexpected characters, as `axa` does, or
/// mint one when nothing usable remains. Behind `axa`'s own middleware this changes
/// nothing, and on a router without it the header is still only caller input.
fn sanitize(headers: &HeaderMap) -> Arc<str> {
    headers
        .get(&X_REQUEST_ID)
        .and_then(|value| value.to_str().ok())
        .map(|value| {
            value
                .chars()
                .filter(|c| c.is_alphanumeric() || matches!(c, '-' | '_' | '@'))
                .take(MAX_REQUEST_ID_LEN)
                .collect::<String>()
        })
        .filter(|id| !id.is_empty())
        .map_or_else(|| Uuid::new_v4().to_string().into(), Into::into)
}

/// Middleware that makes the request id readable anywhere the request runs, through
/// [`current_request_id`], without passing it down. Layer it inside `axa`'s own, by
/// adding it to the router before `axa::middleware::apply`.
pub async fn track(request: Request, next: Next) -> Response {
    let id = sanitize(request.headers());
    REQUEST_ID.scope(id, next.run(request)).await
}

/// The id of the request this code is serving. `None` outside [`track`], and in a
/// task from `tokio::spawn`. Use [`spawn`] to keep it there.
#[must_use]
pub fn current_request_id() -> Option<String> {
    REQUEST_ID
        .try_with(|id| Some(id.to_string()))
        .ok()
        .flatten()
}

/// Add the current request's id to a call to a peer service, so that both services'
/// logs can be followed from one id. Outside a request this changes nothing, and a
/// value already there stays.
pub fn propagate(headers: &mut HeaderMap) {
    if headers.contains_key(&X_REQUEST_ID) {
        return;
    }
    if let Some(value) = current_request_id().and_then(|id| HeaderValue::from_str(&id).ok()) {
        headers.insert(X_REQUEST_ID, value);
    }
}

/// `tokio::spawn`, keeping the current span and request id in the new task.
///
/// A plain `tokio::spawn` loses both, so what the task logs cannot be tied to the
/// request that started it.
pub fn spawn<F>(future: F) -> JoinHandle<F::Output>
where
    F: Future + Send + 'static,
    F::Output: Send + 'static,
{
    let future = future.in_current_span();
    match REQUEST_ID.try_with(Arc::clone) {
        Ok(id) => tokio::spawn(REQUEST_ID.scope(id, future)),
        Err(_) => tokio::spawn(future),
    }
}

#[cfg(test)]
mod tests {
    use axum::{
        Router, body::Body, http::Request as HttpRequest, middleware::from_fn, routing::get,
    };
    use tower::ServiceExt;

    use super::*;

    async fn id_seen_by_a_handler(header: Option<&str>) -> String {
        async fn handler() -> String {
            current_request_id().unwrap_or_default()
        }
        let app = Router::new().route("/", get(handler)).layer(from_fn(track));
        let mut request = HttpRequest::builder().uri("/");
        if let Some(header) = header {
            request = request.header("x-request-id", header);
        }
        let response = app
            .oneshot(request.body(Body::empty()).unwrap())
            .await
            .unwrap();
        let body = axum::body::to_bytes(response.into_body(), 1024)
            .await
            .unwrap();
        String::from_utf8(body.to_vec()).unwrap()
    }

    #[tokio::test]
    async fn a_handler_can_read_the_request_id() {
        assert_eq!(id_seen_by_a_handler(Some("abc-123")).await, "abc-123");
    }

    #[tokio::test]
    async fn a_callers_id_is_cleaned_as_axa_cleans_it() {
        assert_eq!(
            id_seen_by_a_handler(Some("abc<>123_x@y")).await,
            "abc123_x@y"
        );
        let long = "a".repeat(400);
        assert_eq!(id_seen_by_a_handler(Some(&long)).await.len(), 255);
    }

    #[tokio::test]
    async fn an_id_is_minted_when_nothing_usable_remains() {
        assert_eq!(id_seen_by_a_handler(None).await.len(), 36);
        assert_eq!(id_seen_by_a_handler(Some("<>")).await.len(), 36);
    }

    #[test]
    fn there_is_no_request_id_outside_a_request() {
        assert_eq!(current_request_id(), None);
        let mut headers = HeaderMap::new();
        propagate(&mut headers);
        assert!(headers.is_empty());
    }

    #[tokio::test]
    async fn propagate_sends_the_id_and_keeps_one_already_set() {
        let id: Arc<str> = "abc".into();
        REQUEST_ID
            .scope(id, async {
                let mut headers = HeaderMap::new();
                propagate(&mut headers);
                assert_eq!(headers.get(&X_REQUEST_ID).unwrap(), "abc");

                let mut headers = HeaderMap::new();
                headers.insert(X_REQUEST_ID, HeaderValue::from_static("mine"));
                propagate(&mut headers);
                assert_eq!(headers.get(&X_REQUEST_ID).unwrap(), "mine");
            })
            .await;
    }

    #[tokio::test]
    async fn a_spawned_task_keeps_the_request_id() {
        let id: Arc<str> = "abc".into();
        let (kept, lost) = REQUEST_ID
            .scope(id, async {
                let kept = spawn(async { current_request_id() }).await.unwrap();
                let lost = tokio::spawn(async { current_request_id() }).await.unwrap();
                (kept, lost)
            })
            .await;
        assert_eq!(kept.as_deref(), Some("abc"));
        assert_eq!(lost, None);
    }

    #[tokio::test]
    async fn spawn_works_outside_a_request() {
        assert_eq!(spawn(async { 1 }).await.unwrap(), 1);
    }

    #[tokio::test]
    async fn a_spawned_task_keeps_the_span() {
        use tracing_subscriber::layer::SubscriberExt;

        let subscriber =
            tracing_subscriber::registry().with(crate::test_support::Lines::default().layer());
        let _guard = tracing::subscriber::set_default(subscriber);
        let span = tracing::info_span!("parent");
        let id = span.id();
        let seen = async {
            spawn(async { tracing::Span::current().id() })
                .await
                .unwrap()
        }
        .instrument(span)
        .await;
        assert!(id.is_some());
        assert_eq!(seen, id);
    }
}

//! Capturing log output in tests.

use std::{
    io::Write,
    sync::{Arc, Mutex},
};

use tracing_subscriber::fmt::{self, MakeWriter};

/// Collects what the formatter writes.
#[derive(Clone, Default)]
pub struct Lines(Arc<Mutex<Vec<u8>>>);

impl Lines {
    /// Everything written so far.
    pub fn text(&self) -> String {
        String::from_utf8_lossy(&self.0.lock().unwrap()).into_owned()
    }

    /// A plain formatting layer writing here.
    pub fn layer<S>(&self) -> fmt::Layer<S, fmt::format::DefaultFields, fmt::format::Format, Self> {
        fmt::layer().with_ansi(false).with_writer(self.clone())
    }
}

impl Write for Lines {
    fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
        self.0.lock().unwrap().extend_from_slice(bytes);
        Ok(bytes.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

impl<'writer> MakeWriter<'writer> for Lines {
    type Writer = Self;

    fn make_writer(&'writer self) -> Self {
        self.clone()
    }
}

//! An inbox for a consumer, so that it applies each event once.
//!
//! Delivery is at least once, so every consumer dedupes on the event's id. [`seen`]
//! does that in the consumer's own transaction: it notes the id, and says whether it
//! was noted before. The note commits or rolls back with what the consumer does with
//! the event, so an event whose handling failed is not taken as seen.
//!
//! ```no_run
//! # async fn example(pool: sqlx::PgPool, event_id: uuid::Uuid) -> Result<(), sqlx::Error> {
//! let mut transaction = pool.begin().await?;
//! if axa_transactional_outbox::inbox::seen(&mut transaction, event_id).await? {
//!     return Ok(()); // Applied before: acknowledge it and do nothing.
//! }
//! // ... apply the event in `transaction` ...
//! transaction.commit().await?;
//! # Ok(())
//! # }
//! ```
//!
//! `axa_inbox` is a record, so it is only ever inserted into, and its triggers refuse
//! every change. A consumer's migration runs [`SETUP_STATEMENTS`].

use sqlx::{Postgres, Transaction};
use uuid::Uuid;

const INBOX: &str = "CREATE TABLE IF NOT EXISTS axa_inbox (
    event_id UUID PRIMARY KEY,
    seen_at TIMESTAMPTZ NOT NULL DEFAULT now()
)";
const REFUSE: &str = "CREATE OR REPLACE FUNCTION axa_inbox_refuse() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% on axa_inbox is refused: the inbox is only ever added to', TG_OP;
END
$$";
const INBOX_REFUSE: &str = "CREATE OR REPLACE TRIGGER axa_inbox_refuse
    BEFORE UPDATE OR DELETE ON axa_inbox
    FOR EACH ROW EXECUTE FUNCTION axa_inbox_refuse()";
const INBOX_REFUSE_TRUNCATE: &str = "CREATE OR REPLACE TRIGGER axa_inbox_refuse_truncate
    BEFORE TRUNCATE ON axa_inbox
    FOR EACH STATEMENT EXECUTE FUNCTION axa_inbox_refuse()";
const ALWAYS: &str = "ALTER TABLE axa_inbox
    ENABLE ALWAYS TRIGGER axa_inbox_refuse,
    ENABLE ALWAYS TRIGGER axa_inbox_refuse_truncate";

/// The statements that make `axa_inbox` and its triggers, in order, each safe to repeat.
/// They need Postgres 14 or later.
pub const SETUP_STATEMENTS: [&str; 5] =
    [INBOX, REFUSE, INBOX_REFUSE, INBOX_REFUSE_TRUNCATE, ALWAYS];

/// Note `event_id` in the consumer's `transaction`, and say whether it had been noted
/// already, in which case the consumer skips the event. A second transaction noting the
/// same id waits for the first, and then sees it, unless the first rolled back.
///
/// # Errors
///
/// Fails on a database error, which includes a missing `axa_inbox`.
pub async fn seen(
    transaction: &mut Transaction<'_, Postgres>,
    event_id: Uuid,
) -> Result<bool, sqlx::Error> {
    let noted = sqlx::query(
        "INSERT INTO axa_inbox (event_id) VALUES ($1) ON CONFLICT (event_id) DO NOTHING",
    )
    .bind(event_id)
    .execute(&mut **transaction)
    .await?
    .rows_affected();
    Ok(noted == 0)
}

//! A transactional outbox and relay on Postgres, that keeps a record.
//!
//! A service that changes a row and then tells a broker can crash between the two,
//! and the event is gone. Here the event is a row, written with [`write()`] in the same
//! transaction as the change, so the two commit or roll back together. A relay then
//! decides whether each event may go, publishes it, and records what happened.
//!
//! ```no_run
//! use axa_transactional_outbox::{Event, Failure, Outbox, OutboxOptions, decide, record, write};
//! use tokio::sync::watch;
//!
//! # async fn example(pool: sqlx::PgPool, uri: &str) -> Result<(), sqlx::Error> {
//! // In a handler. The event is part of the transaction.
//! let mut transaction = pool.begin().await?;
//! sqlx::query("UPDATE people SET name = 'Ada' WHERE id = 7")
//!     .execute(&mut *transaction)
//!     .await?;
//! let payload = serde_json::json!({ "id": 7 });
//! write(&mut transaction, &Event::new("person", "updated", "7", payload)).await?;
//! transaction.commit().await?;
//!
//! // In `main`, beside the server. The broker client stays in the service.
//! let outbox = Outbox::connect(uri, OutboxOptions::default()).await?;
//! let (stop, stopped) = watch::channel(false);
//! let relay = tokio::spawn(outbox.run(
//!     // Whether each event may go, in the claim's transaction.
//!     decide::deliver_all,
//!     // Answer `Ok` only once the broker has acknowledged the event.
//!     |event| async move {
//!         publish_to_my_broker(&event.topic, &event.key, &event.payload)
//!             .await
//!             .map_err(|_| Failure::unavailable("broker_unreachable"))
//!     },
//!     // The service's audit row, in each outcome's transaction.
//!     record::nothing,
//!     stopped,
//! ));
//! // ... serve until told to stop, then:
//! let _ = stop.send(true);
//! let _ = relay.await;
//! # Ok(())
//! # }
//! # async fn publish_to_my_broker(
//! #     _topic: &str,
//! #     _key: &str,
//! #     _payload: &serde_json::Value,
//! # ) -> Result<(), std::io::Error> {
//! #     Ok(())
//! # }
//! ```
//!
//! # A record, not state
//!
//! An event and everything that happens to it are evidence of what a service disclosed
//! and what it refused, so they are only ever added to. `axa_outbox_events`,
//! `axa_outbox_attempts`, and `axa_outbox_payloads` have triggers that refuse `UPDATE`,
//! `DELETE`, and `TRUNCATE`, whoever sends them, and nothing is swept. The one change
//! allowed is [`erase()`], which blanks a payload once it has recorded who erased it and
//! why.
//!
//! An event's state is its latest attempt: `claimed`, `delivered`, `refused`,
//! `rejected` (to be tried again), `failed`, `lost`, `abandoned`, `returned`,
//! `released`, `erased`, or `imported`. Two small tables are working state, and do
//! change: `axa_outbox_owed`, which the database keeps in step with the attempts so that
//! finding work never reads what was delivered, and `axa_outbox_leases`, where a live
//! relay reports in. Their guards keep them honest: `axa_outbox_owed` changes only as
//! the record does, apart from a hold, and [`REBUILD_OWED_STATEMENTS`] make it again from
//! the record. A lease cannot be dated ahead, so changing one can at worst bring a
//! recovery early, and a recovery is recorded.
//!
//! # Deciding, publishing, recording
//!
//! [`Outbox::run`] takes three closures, and all three are required:
//!
//! - **decide**, run before the publisher in the claim's transaction, with the claimed
//!   rows locked. It answers [`Decision::Deliver`], [`Decision::Refuse`], or
//!   [`Decision::Hold`]. A refusal is final: the event is never claimed again, and
//!   [`release()`] refuses it. A hold writes nothing, charges nothing, and leaves the
//!   event to be decided again after [`OutboxOptions::hold_interval`], for as long as
//!   the service holds it. A service with no rule passes [`decide::deliver_all`].
//! - **publish**, as a broker client would, answering `Ok` only once the broker has
//!   acknowledged the event.
//! - **record**, run after each outcome is written, in that outcome's transaction,
//!   before it commits, so that the service's audit row and the outcome commit together
//!   or not at all. A service with nothing to audit passes [`record::nothing`].
//!
//! A closure that fails changes nothing: the decision or the outcome rolls back with it.
//!
//! # Delivery
//!
//! Delivery is at least once. Nothing committed is lost, and an event is `delivered`
//! only after the publisher answers `Ok`. Several relays can run at once, and in the
//! normal case each event is published once, because each claim locks its rows with
//! `FOR UPDATE SKIP LOCKED`.
//!
//! Duplicates remain, and a consumer must dedupe on [`Claimed::event_id`], which
//! [`inbox::seen`] does:
//!
//! - A relay that dies after the broker took an event and before it recorded so.
//! - A relay that stalls for longer than [`OutboxOptions::stale_minutes`]. Its events
//!   are claimed again while it may still be publishing them. If it then succeeds, its
//!   success is kept as an attempt of its own, so the duplicate is on record.
//! - A publish that runs out of [`OutboxOptions::publish_timeout`], or an error
//!   returned after the broker had in fact taken the event.
//! - An event that a person puts back with [`release()`].
//!
//! Every attempt names its relay and its claim, and an outcome must match the claim it
//! ends, so a relay given up on cannot write over the relay that took over.
//!
//! # Order
//!
//! Events with one topic and key go out in the order of [`Claimed::id`]: an event is
//! claimed only when no earlier event with its topic and key is still owed. So an event
//! waiting for a retry, or held, holds back its own key and no other. A `failed` event
//! frees its key, leaving a gap. A topic given [`Order::None`] in
//! [`OutboxOptions::topic_order`] has no order, so one stuck key holds back nothing.
//!
//! This holds when transactions on one key write in the order they commit, which they
//! do if each changes the same row before writing its event, as that row's lock then
//! makes the second wait.
//!
//! # Failures
//!
//! A publisher says which kind of failure it had, with a short code, because they want
//! opposite things:
//!
//! - [`Failure::Unavailable`]: the broker is down. No event is charged an attempt. The
//!   rest of the batch goes back, and the relay waits longer each time. The event it
//!   was trying waits [`OutboxOptions::retry_backoff`], so the next round tries another.
//! - [`Failure::Rejected`]: this event was refused by the broker. It is tried again
//!   after [`OutboxOptions::retry_backoff`], doubling each time, and after
//!   [`OutboxOptions::max_attempts`] it is `failed`, until a person calls [`release()`].
//!
//! A publisher that panics has rejected that event. One that runs past
//! [`OutboxOptions::publish_timeout`] is charged an attempt, and the round stops as in
//! an outage. A reason is a code of at most 200 characters with no line breaks, such
//! as `broker_rejected`. A longer one is kept as `reason_too_long`, and one with a line
//! break as `reason_not_a_code`. Free error text is never stored and never logged.
//!
//! # A changed row
//!
//! [`write()`] stores a SHA-256 fingerprint of the event's id, topic, kind, key, and
//! payload. Every claim checks it before the decision, and an event that no longer
//! matches is `failed` with the reason `tampered`, is never published, and is counted
//! in [`Stats::tampered`]. The triggers refuse a change from any role, including one
//! with `session_replication_role` set to `replica`, so this catches a change made by
//! someone who turned the triggers off.
//!
//! # A relay that died
//!
//! A relay reports in every [`OutboxOptions::heartbeat_interval`]. A claim not heard
//! from for [`OutboxOptions::stale_minutes`] is ended with a `lost` attempt and goes
//! back, charged an attempt, or with an `abandoned` one if it has no attempts left, so
//! an event that kills its relay cannot loop for ever. This happens at the start of
//! every [`Outbox::claim`], with nothing else to run.
//!
//! # Running a relay
//!
//! Nothing relays by itself. [`Outbox::run`] is the loop, and `main.rs` starts it and
//! stops it like any other task. There is no trait to implement and nothing here calls
//! into a service unasked.
//!
//! A service that needs more runs its own loop on [`Outbox::claim`], then
//! [`Outbox::delivered`], [`Outbox::failed`], [`Outbox::refused`], or
//! [`Outbox::returned`]. Each of those takes the service's transaction, so that its
//! audit row commits with the outcome, and there is no form that takes a pool.
//!
//! # Personal data
//!
//! Prefer an id to a snapshot where consumers can look the record up: a payload about
//! a person is a second copy of them, kept as long as the record is.
//!
//! - [`WriteOptions::max_payload_bytes`], 64 KiB by default, refuses a larger payload,
//!   so the caller's transaction fails rather than storing a large copy.
//! - [`WriteOptions::deny`] names fields that must never be in a payload, at any depth.
//!   It is empty by default.
//! - With the `encryption` feature, a [`Writer`] given keys seals each payload with
//!   XChaCha20-Poly1305, bound to its event, and a relay given the same keys opens it.
//! - [`erase()`] blanks one event's payload and records who and why. An erased event is
//!   never published. Its fingerprint stays, as the record of what was there, and on a
//!   plain payload it can confirm a guess of what was erased. A sealed payload's
//!   fingerprint covers only the ciphertext.
//!
//! No log line here holds a payload, a key, or a reason, and the `Debug` text of
//! [`Event`], [`Claimed`], and [`Attempt`] leaves out the payload and the key.
//!
//! # The tables
//!
//! [`Outbox::connect`] creates them. Where a service's role may not change the schema,
//! a migration runs [`SETUP_STATEMENTS`] and the service calls
//! [`Outbox::connect_existing`], which refuses to start unless every table, index, and
//! trigger is there. A service moving from 0.1.0 runs [`IMPORT_STATEMENTS`] too.

use std::{collections::HashMap, fmt, time::Duration};

use serde_json::Value;
use sqlx::{PgConnection, Postgres, Transaction};
use uuid::Uuid;

pub mod inbox;
mod relay;
mod schema;
#[cfg(feature = "encryption")]
mod seal;

pub use relay::Outbox;
pub use schema::{IMPORT_STATEMENTS, REBUILD_OWED_STATEMENTS, SETUP_STATEMENTS};
#[cfg(feature = "encryption")]
pub use seal::{Key, KeyTooShort, Keys, MIN_KEY_LEN};

/// The largest payload [`WriteOptions::default`] allows, in bytes of JSON.
pub const DEFAULT_MAX_PAYLOAD_BYTES: usize = 64 * 1024;

/// The longest reason or name kept on an attempt, in characters.
pub const MAX_REASON_CHARS: usize = 200;

/// An event to write.
#[derive(Clone, PartialEq)]
pub struct Event {
    /// What a consumer dedupes on. [`Event::new`] makes one, and a service whose
    /// envelope already has an id sets it here. A repeat fails the write.
    pub event_id: Uuid,
    /// What the event is about, which usually chooses the broker's topic.
    pub topic: String,
    /// What happened, such as `created`.
    pub kind: String,
    /// What keeps events in order, usually the record's public id. Events with one
    /// topic and key go out in order, and a broker's partition key is usually this.
    pub key: String,
    /// The tenant the event is for, if any, as an auth crate's `Tenant` names it. Events
    /// keep their order per tenant, topic, and key, so one tenant's stuck event never
    /// holds back another's, and a relay can route by it. The fingerprint covers it.
    pub tenant: Option<String>,
    /// The event itself. Stored as JSONB, so it comes back with its keys reordered.
    pub payload: Value,
}

impl Event {
    /// An event with a new id.
    #[must_use]
    pub fn new(
        topic: impl Into<String>,
        kind: impl Into<String>,
        key: impl Into<String>,
        payload: Value,
    ) -> Self {
        Self {
            event_id: Uuid::new_v4(),
            topic: topic.into(),
            kind: kind.into(),
            key: key.into(),
            tenant: None,
            payload,
        }
    }

    /// The event, for `tenant`. Take it from the verified token, as `tenant.as_str()`,
    /// never from what a caller sent. Writing refuses one that is not a tenant id.
    #[must_use]
    pub fn for_tenant(mut self, tenant: impl Into<String>) -> Self {
        self.tenant = Some(tenant.into());
        self
    }
}

impl fmt::Debug for Event {
    /// Leaves out the payload and the key, which can name a person.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Event")
            .field("event_id", &self.event_id)
            .field("topic", &self.topic)
            .field("kind", &self.kind)
            .field("tenant", &self.tenant)
            .finish_non_exhaustive()
    }
}

/// What [`Writer`] refuses to write. It reaches the caller as `sqlx::Error::Encode`,
/// so the caller's transaction fails, and it can be had back with `downcast_ref`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Refused {
    /// The payload's JSON is larger than [`WriteOptions::max_payload_bytes`].
    TooLarge {
        /// Its size, in bytes.
        bytes: usize,
        /// The limit, in bytes.
        limit: usize,
    },
    /// The payload has a field named in [`WriteOptions::deny`].
    Denied {
        /// The name, as the deny list has it.
        field: String,
    },
    /// Who or why, given to [`release()`] or [`erase()`], is empty, longer than
    /// [`MAX_REASON_CHARS`], or has a line break.
    NotACode {
        /// Which it was: `by` or `reason`.
        what: &'static str,
    },
    /// The event's tenant is not a tenant id: 1 to 63 lower-case letters, digits, and
    /// hyphens, not starting or ending with a hyphen.
    NotATenant,
}

impl fmt::Display for Refused {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::TooLarge { bytes, limit } => write!(
                f,
                "the outbox payload is {bytes} bytes, over the limit of {limit}"
            ),
            Self::Denied { field } => {
                write!(f, "the outbox payload has the denied field `{field}`")
            }
            Self::NotACode { what } => write!(
                f,
                "`{what}` must be 1 to {MAX_REASON_CHARS} characters with no line breaks"
            ),
            Self::NotATenant => f.write_str("the outbox event's tenant is not a tenant id"),
        }
    }
}

impl std::error::Error for Refused {}

/// Whether `id` is a tenant id, as the auth crates' `Tenant` and the table's check hold
/// it.
fn is_tenant_id(id: &str) -> bool {
    (1..=63).contains(&id.len())
        && !id.starts_with('-')
        && !id.ends_with('-')
        && id
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
}

impl From<Refused> for sqlx::Error {
    fn from(refused: Refused) -> Self {
        Self::Encode(Box::new(refused))
    }
}

/// What [`Writer`] checks before it writes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WriteOptions {
    /// The largest payload, in bytes of JSON. A larger one fails the write.
    pub max_payload_bytes: usize,
    /// Field names a payload must not have, as an object key at any depth, such as
    /// `nhs_number`. Empty by default.
    pub deny: Vec<String>,
}

impl Default for WriteOptions {
    fn default() -> Self {
        Self {
            max_payload_bytes: DEFAULT_MAX_PAYLOAD_BYTES,
            deny: Vec::new(),
        }
    }
}

/// Writes events, checking each against its [`WriteOptions`] and, with the
/// `encryption` feature and keys, sealing its payload. Build one at boot and share it.
/// [`write()`] is a writer with the default options.
#[derive(Debug, Clone, Default)]
pub struct Writer {
    options: WriteOptions,
    #[cfg(feature = "encryption")]
    keys: Option<Keys>,
}

/// A payload ready to bind: plain JSON, or sealed bytes as hex, so that one statement
/// serves both drivers.
struct Stored {
    plain: Option<String>,
    sealed: Option<String>,
}

/// One text for both drivers, so that `SeaORM` can bind plain strings. The fingerprint
/// is made by the database from what it stores.
const WRITE: &str = "WITH event AS (
        INSERT INTO axa_outbox_events (event_id, topic, kind, key, tenant, fingerprint)
        VALUES ($1::uuid, $2, $3, $4, $7::text, axa_outbox_fingerprint(
            $1::uuid, $2, $3, $4, $7::text, $5::jsonb, decode($6, 'hex')))
        RETURNING event_id
    )
    INSERT INTO axa_outbox_payloads (event_id, payload, sealed)
    SELECT event_id, $5::jsonb, decode($6, 'hex') FROM event";

impl Writer {
    /// A writer that checks `options`.
    ///
    /// # Errors
    ///
    /// `sqlx::Error::Configuration` when `max_payload_bytes` is zero or a denied name
    /// is empty.
    pub fn new(options: WriteOptions) -> Result<Self, sqlx::Error> {
        if options.max_payload_bytes == 0 {
            return Err(sqlx::Error::Configuration(
                "max_payload_bytes must be at least 1".into(),
            ));
        }
        if options.deny.iter().any(String::is_empty) {
            return Err(sqlx::Error::Configuration(
                "a denied field name must not be empty".into(),
            ));
        }
        Ok(Self {
            options,
            #[cfg(feature = "encryption")]
            keys: None,
        })
    }

    /// Seal every payload with `keys`, so that it is stored encrypted. The relay needs
    /// the same keys, through [`Outbox::opening`].
    #[cfg(feature = "encryption")]
    #[must_use]
    pub fn sealing(mut self, keys: Keys) -> Self {
        self.keys = Some(keys);
        self
    }

    /// Check `event` and make what is stored.
    fn prepare(&self, event: &Event) -> Result<Stored, sqlx::Error> {
        if event
            .tenant
            .as_deref()
            .is_some_and(|tenant| !is_tenant_id(tenant))
        {
            return Err(Refused::NotATenant.into());
        }
        let json = serde_json::to_string(&event.payload)
            .map_err(|error| sqlx::Error::Encode(Box::new(error)))?;
        if json.len() > self.options.max_payload_bytes {
            return Err(Refused::TooLarge {
                bytes: json.len(),
                limit: self.options.max_payload_bytes,
            }
            .into());
        }
        if let Some(field) = denied(&event.payload, &self.options.deny) {
            return Err(Refused::Denied {
                field: field.to_string(),
            }
            .into());
        }
        #[cfg(feature = "encryption")]
        if let Some(keys) = &self.keys {
            let sealed = keys.seal(event.event_id, json.as_bytes())?;
            return Ok(Stored {
                plain: None,
                sealed: Some(hex(&sealed)),
            });
        }
        Ok(Stored {
            plain: Some(json),
            sealed: None,
        })
    }

    /// Write `event` on the caller's transaction, so that it commits or rolls back
    /// with the change it describes. It takes a transaction and not a pool, as an event
    /// written outside the transaction is the bug this crate exists to prevent.
    ///
    /// # Errors
    ///
    /// Fails on a database error, which includes a repeated `event_id`, and with
    /// [`Refused`] inside `sqlx::Error::Encode` for a payload too large or with a
    /// denied field. Either way the caller's transaction should not commit.
    pub async fn write(
        &self,
        transaction: &mut Transaction<'_, Postgres>,
        event: &Event,
    ) -> Result<(), sqlx::Error> {
        let stored = self.prepare(event)?;
        sqlx::query(WRITE)
            .bind(event.event_id.to_string())
            .bind(&event.topic)
            .bind(&event.kind)
            .bind(&event.key)
            .bind(stored.plain)
            .bind(stored.sealed)
            .bind(event.tenant.as_deref())
            .execute(&mut **transaction)
            .await?;
        Ok(())
    }

    /// [`Writer::write`], for a transaction of `SeaORM`'s.
    ///
    /// # Errors
    ///
    /// As [`Writer::write`], with a refusal as `DbErr::Custom`.
    #[cfg(feature = "seaorm")]
    pub async fn write_seaorm(
        &self,
        transaction: &sea_orm::DatabaseTransaction,
        event: &Event,
    ) -> Result<(), sea_orm::DbErr> {
        use sea_orm::{ConnectionTrait, DatabaseBackend, Statement};
        let stored = self
            .prepare(event)
            .map_err(|error| sea_orm::DbErr::Custom(error.to_string()))?;
        let values = [
            event.event_id.to_string().into(),
            event.topic.clone().into(),
            event.kind.clone().into(),
            event.key.clone().into(),
            stored.plain.into(),
            stored.sealed.into(),
            event.tenant.clone().into(),
        ];
        transaction
            .execute_raw(Statement::from_sql_and_values(
                DatabaseBackend::Postgres,
                WRITE,
                values,
            ))
            .await?;
        Ok(())
    }
}

/// Write `event` on the caller's transaction, with the default [`WriteOptions`]: a
/// payload of at most 64 KiB, no denied fields, and no sealing. A service with options
/// of its own builds a [`Writer`].
///
/// # Errors
///
/// As [`Writer::write`].
pub async fn write(
    transaction: &mut Transaction<'_, Postgres>,
    event: &Event,
) -> Result<(), sqlx::Error> {
    Writer::default().write(transaction, event).await
}

/// [`write()`], for a transaction of `SeaORM`'s.
///
/// # Errors
///
/// As [`Writer::write_seaorm`].
#[cfg(feature = "seaorm")]
pub async fn write_seaorm(
    transaction: &sea_orm::DatabaseTransaction,
    event: &Event,
) -> Result<(), sea_orm::DbErr> {
    Writer::default().write_seaorm(transaction, event).await
}

/// The first name in `deny` that `value` has as an object key, at any depth.
fn denied<'a>(value: &Value, deny: &'a [String]) -> Option<&'a str> {
    if deny.is_empty() {
        return None;
    }
    match value {
        Value::Object(fields) => fields.iter().find_map(|(name, inner)| {
            deny.iter()
                .find(|denied| *denied == name)
                .map(String::as_str)
                .or_else(|| denied(inner, deny))
        }),
        Value::Array(items) => items.iter().find_map(|inner| denied(inner, deny)),
        _ => None,
    }
}

#[cfg(feature = "encryption")]
fn hex(bytes: &[u8]) -> String {
    use std::fmt::Write;
    bytes.iter().fold(String::new(), |mut text, byte| {
        let _ = write!(text, "{byte:02x}");
        text
    })
}

/// A reason as kept: itself if it is a code, and otherwise a code saying why not.
fn code(reason: &str) -> String {
    if reason.chars().count() > MAX_REASON_CHARS {
        tracing::warn!("outbox reason was too long, and is kept as reason_too_long");
        "reason_too_long".to_string()
    } else if reason.chars().any(char::is_control) {
        tracing::warn!("outbox reason had a line break, and is kept as reason_not_a_code");
        "reason_not_a_code".to_string()
    } else {
        reason.to_string()
    }
}

/// Refuse who or why for a person's act unless it is a code.
fn check_code(text: &str, what: &'static str) -> Result<(), Refused> {
    if text.is_empty()
        || text.chars().count() > MAX_REASON_CHARS
        || text.chars().any(char::is_control)
    {
        Err(Refused::NotACode { what })
    } else {
        Ok(())
    }
}

/// An event a relay has claimed.
#[derive(Clone, PartialEq)]
pub struct Claimed {
    /// The event's row. It rises with each event for a key, with gaps, so a consumer
    /// can refuse an event older than one it has applied.
    pub id: i64,
    /// Tries so far, including this one, since the event was written or released.
    pub attempts: i32,
    /// What a consumer dedupes on.
    pub event_id: Uuid,
    /// What the event is about.
    pub topic: String,
    /// What happened.
    pub kind: String,
    /// What keeps events in order.
    pub key: String,
    /// The tenant it is for, if any, to route by.
    pub tenant: Option<String>,
    /// The event itself, opened if it was sealed.
    pub payload: Value,
    /// The relay that claimed it.
    pub relay: Uuid,
    /// This claim, which every outcome for it must name.
    pub claim: Uuid,
}

impl fmt::Debug for Claimed {
    /// Leaves out the payload and the key, which can name a person.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Claimed")
            .field("id", &self.id)
            .field("attempts", &self.attempts)
            .field("event_id", &self.event_id)
            .field("topic", &self.topic)
            .field("kind", &self.kind)
            .field("tenant", &self.tenant)
            .field("claim", &self.claim)
            .finish_non_exhaustive()
    }
}

/// What a service's decision says about one event, before it is published.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Decision {
    /// Publish it.
    Deliver,
    /// Never publish it. Final: nothing puts it back. The reason is a code, such as
    /// `no_consent`.
    Refuse(String),
    /// Not now. Nothing is written or charged, and it is decided again after
    /// [`OutboxOptions::hold_interval`]. It holds back its own key and no other.
    Hold,
}

impl Decision {
    /// Never publish it, for `reason`.
    pub fn refuse(reason: impl Into<String>) -> Self {
        Self::Refuse(reason.into())
    }
}

/// What an attempt recorded, as a record closure is told it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Outcome {
    /// The broker has it.
    Delivered,
    /// The service's decision refused it, for good.
    Refused,
    /// The broker refused it, and it will be tried again.
    Rejected,
    /// It will not be tried again until a person releases it: out of attempts, or
    /// `tampered`.
    Failed,
    /// Its relay went quiet, and it goes back, charged an attempt.
    Lost,
    /// Its relay went quiet with no attempts left, and it is failed.
    Abandoned,
}

impl Outcome {
    /// The outcome as the attempts table has it.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Delivered => "delivered",
            Self::Refused => "refused",
            Self::Rejected => "rejected",
            Self::Failed => "failed",
            Self::Lost => "lost",
            Self::Abandoned => "abandoned",
        }
    }

    fn parse(text: &str) -> Option<Self> {
        Some(match text {
            "delivered" => Self::Delivered,
            "refused" => Self::Refused,
            "rejected" => Self::Rejected,
            "failed" => Self::Failed,
            "lost" => Self::Lost,
            "abandoned" => Self::Abandoned,
            _ => return None,
        })
    }
}

impl fmt::Display for Outcome {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// One outcome as written, for a service's audit row.
#[derive(Clone, PartialEq, Eq)]
pub struct Attempt {
    /// The attempt's row.
    pub id: i64,
    /// The event's id.
    pub event_id: Uuid,
    /// What the event is about.
    pub topic: String,
    /// What happened.
    pub kind: String,
    /// What keeps events in order.
    pub key: String,
    /// What this attempt recorded.
    pub outcome: Outcome,
    /// Why, as a code, where there is one.
    pub reason: Option<String>,
    /// The relay that wrote it.
    pub relay: Uuid,
    /// The claim it ends.
    pub claim: Uuid,
}

impl fmt::Debug for Attempt {
    /// Leaves out the key, which can name a person.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Attempt")
            .field("id", &self.id)
            .field("event_id", &self.event_id)
            .field("topic", &self.topic)
            .field("kind", &self.kind)
            .field("outcome", &self.outcome)
            .field("reason", &self.reason)
            .field("claim", &self.claim)
            .finish_non_exhaustive()
    }
}

/// Decisions for a service with no rule of its own.
pub mod decide {
    use super::{Claimed, Decision, PgConnection};

    /// Deliver every event. Passing this says, in the service's own code, that it
    /// has no policy to apply before an event goes.
    ///
    /// # Errors
    ///
    /// None.
    #[allow(clippy::unused_async, reason = "the relay awaits every decision")]
    pub async fn deliver_all(
        _event: &Claimed,
        _transaction: &mut PgConnection,
    ) -> Result<Decision, sqlx::Error> {
        Ok(Decision::Deliver)
    }
}

/// Records for a service with nothing to audit.
pub mod record {
    use super::{Attempt, PgConnection};

    /// Record nothing. Passing this says, in the service's own code, that it keeps no
    /// audit of what it disclosed or refused.
    ///
    /// # Errors
    ///
    /// None.
    #[allow(clippy::unused_async, reason = "the relay awaits every record")]
    pub async fn nothing(
        _attempt: &Attempt,
        _transaction: &mut PgConnection,
    ) -> Result<(), sqlx::Error> {
        Ok(())
    }
}

/// Why a publisher could not publish an event, as a short code that goes on the
/// attempt. Free error text belongs in the service's own log, never here, as a
/// broker's error can quote what it was sent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Failure {
    /// The broker cannot take anything now. No event is charged an attempt, the rest
    /// of the batch goes back, and the relay waits before trying again.
    Unavailable(String),
    /// This event was refused by the broker. It is charged an attempt, and the relay
    /// moves on to the next.
    Rejected(String),
}

impl Failure {
    /// The broker cannot take anything now, for `reason`, such as `broker_down`.
    pub fn unavailable(reason: impl Into<String>) -> Self {
        Self::Unavailable(reason.into())
    }

    /// This event was refused, for `reason`, such as `broker_rejected`.
    pub fn rejected(reason: impl Into<String>) -> Self {
        Self::Rejected(reason.into())
    }
}

/// Whether a topic's events keep their order per key.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Order {
    /// Events with one topic and key go out in order, so one stuck event holds back
    /// its key.
    #[default]
    PerKey,
    /// No order, so a stuck event holds back nothing.
    None,
}

/// Outbox tuning.
#[derive(Debug, Clone)]
pub struct OutboxOptions {
    /// Events one claim holds. A relay publishes them in turn.
    pub batch_size: i64,
    /// Sleep between polls of an empty outbox.
    pub poll_interval: Duration,
    /// A claim not heard from for this many minutes is assumed lost with its relay.
    pub stale_minutes: i32,
    /// How often a relay reports in. At most half of `stale_minutes`.
    pub heartbeat_interval: Duration,
    /// The longest one publish may take. A broker client can hang, and that must not
    /// hold a relay.
    pub publish_timeout: Duration,
    /// Tries an event gets, including the first, before it is `failed`.
    pub max_attempts: i32,
    /// The wait before the first retry of an event.
    pub retry_backoff: Duration,
    /// How long a held event waits before it is decided again. At most a day, which is
    /// as far ahead as `axa_outbox_owed` lets a hold be set.
    pub hold_interval: Duration,
    /// Topics whose order is not [`Order::PerKey`]. Any topic not named keeps its order.
    pub topic_order: HashMap<String, Order>,
}

impl Default for OutboxOptions {
    fn default() -> Self {
        Self {
            batch_size: 100,
            poll_interval: Duration::from_secs(1),
            stale_minutes: 5,
            heartbeat_interval: Duration::from_secs(30),
            publish_timeout: Duration::from_secs(30),
            max_attempts: 10,
            retry_backoff: Duration::from_secs(5),
            hold_interval: Duration::from_secs(10),
            topic_order: HashMap::new(),
        }
    }
}

impl OutboxOptions {
    /// Refuse settings that cannot work, rather than start a relay that repeats
    /// everything or spins.
    fn validate(&self) -> Result<(), sqlx::Error> {
        let stale = Duration::from_mins(u64::try_from(self.stale_minutes).unwrap_or(0));
        let problem = if self.batch_size < 1 {
            Some("batch_size must be at least 1")
        } else if self.stale_minutes < 1 {
            Some("stale_minutes must be at least 1")
        } else if self.heartbeat_interval.is_zero() || self.heartbeat_interval * 2 > stale {
            Some("heartbeat_interval must be above zero and at most half of stale_minutes")
        } else if self.publish_timeout.is_zero() {
            Some("publish_timeout must be above zero")
        } else if self.poll_interval.is_zero() {
            Some("poll_interval must be above zero")
        } else if self.max_attempts < 1 {
            Some("max_attempts must be at least 1")
        } else if self.hold_interval.is_zero() || self.hold_interval > Duration::from_hours(24) {
            Some("hold_interval must be above zero and at most a day")
        } else {
            None
        };
        match problem {
            Some(problem) => Err(sqlx::Error::Configuration(problem.into())),
            None => Ok(()),
        }
    }

    /// The topics with no order.
    fn unordered(&self) -> Vec<String> {
        let mut topics: Vec<String> = self
            .topic_order
            .iter()
            .filter(|(_, order)| **order == Order::None)
            .map(|(topic, _)| topic.clone())
            .collect();
        topics.sort();
        topics
    }
}

/// What an outbox owes, and what it did lately, for a metric or an alert. A count that
/// grows, or an age that keeps rising, means events are not going out.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Stats {
    /// Events waiting for a relay, not held.
    pub pending: i64,
    /// Events a relay is working on.
    pub claimed: i64,
    /// Events the service's decision is holding.
    pub held: i64,
    /// Events no relay will touch until a person calls [`release()`], `tampered` ones
    /// included.
    pub failed: i64,
    /// Failed events whose fingerprint no longer matched.
    pub tampered: i64,
    /// Events delivered in the last hour.
    pub delivered: i64,
    /// Events refused in the last hour.
    pub refused: i64,
    /// How long the oldest pending or claimed event has waited.
    pub oldest: Option<Duration>,
    /// How long the longest hold has lasted.
    pub oldest_held: Option<Duration>,
    /// How long the oldest failed event has waited since it was written.
    pub oldest_failed: Option<Duration>,
}

const RELEASE: &str = "WITH failed AS (
        SELECT event_id FROM axa_outbox_owed
        WHERE event_id = $1 AND state = 'failed'
        FOR UPDATE
    )
    INSERT INTO axa_outbox_attempts (event_id, outcome, relay, claim, reason, by)
    SELECT event_id, 'released', $2, $3, $4, $5 FROM failed";

/// Put a `failed` event back to be tried again with its attempts cleared, as an act of
/// `by`, for `reason`, kept as a `released` attempt in the caller's transaction, so
/// that the caller's audit row commits with it. Answers whether it went back. Nothing
/// else can be released: a refused, delivered, or erased event is final, and one still
/// owed needs nothing. Later events for its key may already have gone out, so it can
/// arrive out of order.
///
/// # Errors
///
/// Fails on a database error, and with [`Refused::NotACode`] when `by` or `reason` is
/// empty, longer than [`MAX_REASON_CHARS`], or has a line break.
pub async fn release(
    transaction: &mut Transaction<'_, Postgres>,
    event_id: Uuid,
    by: &str,
    reason: &str,
) -> Result<bool, sqlx::Error> {
    check_code(by, "by")?;
    check_code(reason, "reason")?;
    let released = sqlx::query(RELEASE)
        .bind(event_id)
        .bind(Uuid::nil())
        .bind(Uuid::new_v4())
        .bind(reason)
        .bind(by)
        .execute(&mut **transaction)
        .await?
        .rows_affected();
    Ok(released > 0)
}

/// Blank the payload of `event_id`, as an act of `by`, for `reason`, in the caller's
/// transaction. It appends an `erased` attempt, then sets the payload to null, which
/// the triggers allow only after that attempt, changing nothing else. An erased event
/// is never published, and is no longer owed. Answers whether there was a payload to
/// erase.
///
/// # Errors
///
/// Fails on a database error, and with [`Refused::NotACode`] when `by` or `reason` is
/// empty, longer than [`MAX_REASON_CHARS`], or has a line break.
pub async fn erase(
    transaction: &mut Transaction<'_, Postgres>,
    event_id: Uuid,
    by: &str,
    reason: &str,
) -> Result<bool, sqlx::Error> {
    check_code(by, "by")?;
    check_code(reason, "reason")?;
    let held = sqlx::query(
        "SELECT 1 FROM axa_outbox_payloads
         WHERE event_id = $1 AND (payload IS NOT NULL OR sealed IS NOT NULL)
         FOR UPDATE",
    )
    .bind(event_id)
    .fetch_optional(&mut **transaction)
    .await?;
    if held.is_none() {
        return Ok(false);
    }
    sqlx::query(
        "INSERT INTO axa_outbox_attempts (event_id, outcome, relay, claim, reason, by)
         VALUES ($1, 'erased', $2, $3, $4, $5)",
    )
    .bind(event_id)
    .bind(Uuid::nil())
    .bind(Uuid::new_v4())
    .bind(reason)
    .bind(by)
    .execute(&mut **transaction)
    .await?;
    sqlx::query("UPDATE axa_outbox_payloads SET payload = NULL, sealed = NULL WHERE event_id = $1")
        .bind(event_id)
        .execute(&mut **transaction)
        .await?;
    Ok(true)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn fine() -> OutboxOptions {
        OutboxOptions::default()
    }

    #[test]
    fn the_default_options_are_valid() {
        assert!(fine().validate().is_ok());
        assert!(Writer::new(WriteOptions::default()).is_ok());
        assert_eq!(WriteOptions::default().max_payload_bytes, 64 * 1024);
        assert_eq!(WriteOptions::default().deny, Vec::<String>::new());
    }

    #[test]
    fn options_that_cannot_work_are_refused() {
        let bad = [
            OutboxOptions {
                batch_size: 0,
                ..fine()
            },
            OutboxOptions {
                stale_minutes: 0,
                ..fine()
            },
            OutboxOptions {
                heartbeat_interval: Duration::ZERO,
                ..fine()
            },
            OutboxOptions {
                heartbeat_interval: Duration::from_mins(3),
                ..fine()
            },
            OutboxOptions {
                publish_timeout: Duration::ZERO,
                ..fine()
            },
            OutboxOptions {
                poll_interval: Duration::ZERO,
                ..fine()
            },
            OutboxOptions {
                max_attempts: 0,
                ..fine()
            },
            OutboxOptions {
                hold_interval: Duration::ZERO,
                ..fine()
            },
            OutboxOptions {
                hold_interval: Duration::from_hours(25),
                ..fine()
            },
        ];
        for options in bad {
            assert!(options.validate().is_err(), "{options:?}");
        }
        assert!(
            Writer::new(WriteOptions {
                max_payload_bytes: 0,
                ..WriteOptions::default()
            })
            .is_err()
        );
        assert!(
            Writer::new(WriteOptions {
                deny: vec![String::new()],
                ..WriteOptions::default()
            })
            .is_err()
        );
    }

    #[test]
    fn debug_text_leaves_out_the_payload_and_the_key() {
        let payload = json!({ "name": "Ada Lovelace" });
        let event = Event::new("person", "updated", "ada@example.com", payload.clone());
        let claimed = Claimed {
            id: 1,
            attempts: 1,
            event_id: event.event_id,
            topic: event.topic.clone(),
            kind: event.kind.clone(),
            key: event.key.clone(),
            tenant: None,
            payload,
            relay: Uuid::new_v4(),
            claim: Uuid::new_v4(),
        };
        let attempt = Attempt {
            id: 1,
            event_id: event.event_id,
            topic: event.topic.clone(),
            kind: event.kind.clone(),
            key: event.key.clone(),
            outcome: Outcome::Delivered,
            reason: None,
            relay: Uuid::new_v4(),
            claim: Uuid::new_v4(),
        };
        for text in [
            format!("{event:?}"),
            format!("{claimed:?}"),
            format!("{attempt:?}"),
        ] {
            assert!(!text.contains("Ada"), "{text}");
            assert!(!text.contains("ada@example.com"), "{text}");
            assert!(text.contains("updated"), "{text}");
        }
    }

    #[test]
    fn each_event_gets_its_own_id() {
        let one = Event::new("t", "k", "1", Value::Null);
        let two = Event::new("t", "k", "1", Value::Null);
        assert_ne!(one.event_id, two.event_id);
    }

    #[test]
    fn this_crate_depends_on_no_broker_client() {
        let manifest = include_str!("../Cargo.toml");
        for broker in ["fluvio", "rdkafka", "kafka", "lapin", "nats", "pulsar"] {
            assert!(!manifest.contains(broker), "{broker}");
        }
    }

    #[test]
    fn a_reason_is_a_short_code() {
        assert_eq!(code("broker_rejected"), "broker_rejected");
        assert_eq!(code(&"é".repeat(200)), "é".repeat(200));
        assert_eq!(code(&"é".repeat(201)), "reason_too_long");
        assert_eq!(code("two\nlines"), "reason_not_a_code");
        assert_eq!(code("a\rb"), "reason_not_a_code");
        assert!(check_code("ops@example.com", "by").is_ok());
        assert!(check_code("", "by").is_err());
        assert!(check_code("a\nb", "reason").is_err());
        assert!(check_code(&"x".repeat(201), "reason").is_err());
    }

    #[test]
    fn a_denied_field_is_found_at_any_depth() {
        let deny = vec!["nhs_number".to_string(), "password".to_string()];
        assert_eq!(denied(&json!({ "id": 7 }), &deny), None);
        assert_eq!(
            denied(&json!({ "nhs_number": "1" }), &deny),
            Some("nhs_number")
        );
        assert_eq!(
            denied(&json!({ "a": [{ "b": { "password": "x" } }] }), &deny),
            Some("password")
        );
        // A value is not a field name.
        assert_eq!(denied(&json!({ "note": "password" }), &deny), None);
        assert_eq!(denied(&json!(["password"]), &deny), None);
        assert_eq!(denied(&json!({ "password": 1 }), &[]), None);
    }

    #[test]
    fn a_large_payload_or_a_denied_field_is_refused_before_any_write() {
        let writer = Writer::new(WriteOptions {
            max_payload_bytes: 16,
            deny: vec!["secret".to_string()],
        })
        .unwrap();
        let large = Event::new("t", "k", "1", json!({ "text": "x".repeat(20) }));
        let refused = writer.prepare(&large).err().unwrap();
        let sqlx::Error::Encode(inner) = refused else {
            panic!("{refused:?}")
        };
        assert!(matches!(
            inner.downcast_ref::<Refused>(),
            Some(Refused::TooLarge { limit: 16, .. })
        ));
        let secret = Event::new("t", "k", "1", json!({ "secret": 1 }));
        let refused = writer.prepare(&secret).err().unwrap();
        assert!(refused.to_string().contains("secret"), "{refused}");
        assert!(
            writer
                .prepare(&Event::new("t", "k", "1", json!({})))
                .is_ok()
        );
        // Exactly at the limit is allowed.
        let at = Event::new("t", "k", "1", json!("x".repeat(14)));
        assert!(writer.prepare(&at).is_ok());
    }

    #[test]
    fn the_unordered_topics_are_those_given_none() {
        let mut options = fine();
        options.topic_order.insert("audit".into(), Order::None);
        options.topic_order.insert("person".into(), Order::PerKey);
        assert_eq!(options.unordered(), ["audit"]);
    }

    #[tokio::test]
    async fn refused_options_stop_a_connect_before_it_reaches_the_network() {
        let options = OutboxOptions {
            batch_size: 0,
            ..fine()
        };
        let refused = Outbox::connect("postgres://nobody@127.0.0.1:1/none", options)
            .await
            .unwrap_err();
        assert!(matches!(refused, sqlx::Error::Configuration(_)));
    }

    #[test]
    fn an_outcome_reads_back_as_itself() {
        for outcome in [
            Outcome::Delivered,
            Outcome::Refused,
            Outcome::Rejected,
            Outcome::Failed,
            Outcome::Lost,
            Outcome::Abandoned,
        ] {
            assert_eq!(Outcome::parse(outcome.as_str()), Some(outcome));
        }
        assert_eq!(Outcome::parse("claimed"), None);
    }
}

//! The relay: claiming, deciding, publishing, and recording.

use std::{fmt, future::Future, time::Duration};

use serde_json::Value;
use sqlx::{
    Acquire, PgConnection, PgPool, Postgres, Row, Transaction,
    postgres::{PgPoolOptions, PgRow},
};
use tokio::{
    sync::watch,
    time::{Instant, Interval, MissedTickBehavior},
};
use uuid::Uuid;

use crate::{
    Attempt, Claimed, Decision, Failure, OutboxOptions, Outcome, SETUP_STATEMENTS, Stats, code,
    schema::{INDEXES, TRIGGERS},
};
#[cfg(feature = "encryption")]
use crate::{Keys, seal::Unopened};

/// Advisory lock key for table setup: `axa_o` as bytes.
const SETUP_LOCK: i64 = 0x0061_7861_5F6F;

/// Connections one [`Outbox`] holds: it works in sequence, and a heartbeat can
/// overlap a publish. Each `connect` gets its own, so a relay cannot take connections
/// from requests.
const CONNECTIONS: u32 = 2;

/// The longest wait before an event is tried again.
const MAX_BACKOFF: Duration = Duration::from_hours(1);

/// The longest wait while the broker is down, which is also how long a relay can lag
/// once it is back.
const MAX_PAUSE: Duration = Duration::from_mins(1);

/// Each column a relay reads, so that a table out of date fails at boot.
const PROBES: [&str; 5] = [
    "SELECT id, event_id, topic, kind, key, tenant, fingerprint, created_at
     FROM axa_outbox_events LIMIT 0",
    "SELECT event_id, payload, sealed FROM axa_outbox_payloads LIMIT 0",
    "SELECT id, event_id, outcome, relay, claim, reason, by, retry_at, at
     FROM axa_outbox_attempts LIMIT 0",
    "SELECT event_id, id, topic, key, tenant, state, claim, charges, reason, retry_at,
            held_since, recheck_at
     FROM axa_outbox_owed LIMIT 0",
    "SELECT claim, relay, heard_at FROM axa_outbox_leases LIMIT 0",
];

const MISSING_TRIGGERS: &str = "SELECT want.name
    FROM unnest($1::text[], $2::text[], $3::bool[]) AS want(tbl, name, always)
    WHERE NOT EXISTS (
        SELECT 1 FROM pg_trigger t
        WHERE t.tgrelid = to_regclass(want.tbl) AND t.tgname = want.name
          AND (t.tgenabled::text = 'A' OR (NOT want.always AND t.tgenabled::text = 'O'))
    )";
const MISSING_INDEXES: &str =
    "SELECT name FROM unnest($1::text[]) AS name WHERE to_regclass(name) IS NULL";
const MISSING_FINGERPRINT: &str = "SELECT to_regprocedure(
        'axa_outbox_fingerprint(uuid, text, text, text, jsonb, bytea)') IS NULL
    OR to_regprocedure(
        'axa_outbox_fingerprint(uuid, text, text, text, text, jsonb, bytea)') IS NULL";

/// The events a claim may take, oldest first, locked for this claim alone. An earlier
/// event still owed for the same tenant, topic, and key holds one back, unless its topic
/// has no order. `FOR UPDATE SKIP LOCKED` is what stops two relays taking one event, and the
/// state is checked again once the lock is had, because the claim changes the row.
const CANDIDATES: &str = "SELECT o.event_id, o.id, o.charges, e.topic, e.kind, e.key,
        e.tenant, p.payload, p.sealed,
        e.fingerprint IS NOT DISTINCT FROM axa_outbox_fingerprint(
            e.event_id, e.topic, e.kind, e.key, e.tenant, p.payload, p.sealed) AS intact
    FROM axa_outbox_owed o
    JOIN axa_outbox_events e ON e.event_id = o.event_id
    LEFT JOIN axa_outbox_payloads p ON p.event_id = o.event_id
    WHERE o.state = 'pending' AND o.retry_at <= now()
      AND (o.recheck_at IS NULL OR o.recheck_at <= now())
      AND (o.topic = ANY($2) OR NOT EXISTS (
          SELECT 1 FROM axa_outbox_owed earlier
          WHERE earlier.topic = o.topic AND earlier.key = o.key
            AND earlier.tenant IS NOT DISTINCT FROM o.tenant
            AND earlier.id < o.id AND earlier.state <> 'failed'
      ))
    ORDER BY o.id
    LIMIT $1
    FOR UPDATE OF o SKIP LOCKED";
const CLAIMED: &str = "INSERT INTO axa_outbox_attempts (event_id, outcome, relay, claim)
    SELECT event_id, 'claimed', $2, $3
    FROM unnest($1::uuid[]) WITH ORDINALITY AS taken(event_id, place)
    ORDER BY place";
const LEASE: &str = "INSERT INTO axa_outbox_leases (claim, relay) VALUES ($1, $2)";
/// An outcome reached in the claim itself, on a row the claim has locked.
const DECIDED: &str = "INSERT INTO axa_outbox_attempts (event_id, outcome, relay, claim, reason)
    VALUES ($1, $2, $3, $4, $5)
    RETURNING id";
const HOLD: &str = "UPDATE axa_outbox_owed
    SET held_since = coalesce(held_since, now()), recheck_at = now() + make_interval(secs => $2)
    WHERE event_id = $1";
const DEFER: &str = "UPDATE axa_outbox_owed
    SET recheck_at = now() + make_interval(secs => $2)
    WHERE event_id = $1";
/// Ends a live claim, only if it is still the event's latest: a refusal by the service,
/// or a failure charged an attempt, which is final once none are left.
const ENDED: &str = "WITH current AS (
        SELECT event_id, charges FROM axa_outbox_owed
        WHERE event_id = $1 AND state = 'claimed' AND claim = $3
        FOR UPDATE
    )
    INSERT INTO axa_outbox_attempts (event_id, outcome, relay, claim, reason, retry_at)
    SELECT event_id,
        CASE WHEN $4 THEN 'refused' WHEN charges + 1 >= $5 THEN 'failed' ELSE 'rejected' END,
        $2, $3, $6,
        CASE WHEN NOT $4 AND charges + 1 < $5 THEN now() + make_interval(secs => $7) END
    FROM current
    RETURNING id, outcome";
const LOCK_OWED: &str = "SELECT 1 FROM axa_outbox_owed WHERE event_id = $1 FOR UPDATE";
/// A success from a claim of this relay's that has not ended. The claim need not be
/// the latest: a late success is kept as its own attempt, as the broker has the event
/// whoever says so, and believing it spares a duplicate.
const DELIVERED: &str = "INSERT INTO axa_outbox_attempts (event_id, outcome, relay, claim)
    SELECT $1, 'delivered', $2, $3
    WHERE EXISTS (
        SELECT 1 FROM axa_outbox_attempts took
        WHERE took.event_id = $1 AND took.claim = $3 AND took.relay = $2
          AND took.outcome = 'claimed'
    )
    AND NOT EXISTS (
        SELECT 1 FROM axa_outbox_attempts ended
        WHERE ended.event_id = $1 AND ended.claim = $3
          AND ended.outcome NOT IN ('claimed', 'lost', 'abandoned')
    )
    RETURNING id";
/// Gives back events a live claim holds, charging nothing.
const RETURNED: &str = "WITH given AS (
        SELECT * FROM unnest($1::uuid[], $2::uuid[]) AS given(event_id, claim)
    ), current AS (
        SELECT o.event_id, o.claim FROM axa_outbox_owed o
        JOIN given ON given.event_id = o.event_id AND given.claim = o.claim
        WHERE o.state = 'claimed'
        FOR UPDATE OF o
    )
    INSERT INTO axa_outbox_attempts (event_id, outcome, relay, claim, reason, retry_at)
    SELECT event_id, 'returned', $3, claim, $4, now() + make_interval(secs => $5)
    FROM current";
const HEARTBEAT: &str = "UPDATE axa_outbox_leases SET heard_at = now() WHERE claim = ANY($1)";
const END_LEASE: &str = "DELETE FROM axa_outbox_leases WHERE claim = $1";
/// Ends every claim not heard from: `lost` with attempts left, and `abandoned` without.
const RECOVER: &str = "WITH stale AS (
        SELECT o.event_id, o.claim, o.charges FROM axa_outbox_owed o
        WHERE o.state = 'claimed' AND NOT EXISTS (
            SELECT 1 FROM axa_outbox_leases l
            WHERE l.claim = o.claim AND l.heard_at >= now() - make_interval(mins => $1)
        )
        FOR UPDATE OF o SKIP LOCKED
    ), ended AS (
        INSERT INTO axa_outbox_attempts (event_id, outcome, relay, claim)
        SELECT event_id, CASE WHEN charges + 1 >= $2 THEN 'abandoned' ELSE 'lost' END, $3, claim
        FROM stale
        RETURNING id, event_id, outcome, claim
    )
    SELECT ended.id, ended.event_id, ended.outcome, ended.claim, e.topic, e.kind, e.key
    FROM ended JOIN axa_outbox_events e ON e.event_id = ended.event_id
    ORDER BY ended.id";
const DROP_LEASES: &str = "DELETE FROM axa_outbox_leases l
    WHERE l.heard_at < now() - make_interval(mins => $1)
      AND NOT EXISTS (
          SELECT 1 FROM axa_outbox_owed o WHERE o.claim = l.claim AND o.state = 'claimed'
      )";
/// Reads only what is owed, and the last hour of outcomes.
const STATS: &str = "SELECT
        count(*) FILTER (WHERE o.state = 'pending' AND o.held_since IS NULL) AS pending,
        count(*) FILTER (WHERE o.state = 'claimed') AS claimed,
        count(*) FILTER (WHERE o.state = 'pending' AND o.held_since IS NOT NULL) AS held,
        count(*) FILTER (WHERE o.state = 'failed') AS failed,
        count(*) FILTER (WHERE o.state = 'failed' AND o.reason = 'tampered') AS tampered,
        EXTRACT(EPOCH FROM now() - min(e.created_at)
            FILTER (WHERE o.state <> 'failed' AND o.held_since IS NULL))::float8 AS oldest,
        EXTRACT(EPOCH FROM now() - min(o.held_since)
            FILTER (WHERE o.state = 'pending'))::float8 AS oldest_held,
        EXTRACT(EPOCH FROM now() - min(e.created_at)
            FILTER (WHERE o.state = 'failed'))::float8 AS oldest_failed,
        (SELECT count(*) FROM axa_outbox_attempts a
         WHERE a.outcome = 'delivered' AND a.at > now() - interval '1 hour') AS delivered,
        (SELECT count(*) FROM axa_outbox_attempts a
         WHERE a.outcome = 'refused' AND a.at > now() - interval '1 hour') AS refused
    FROM axa_outbox_owed o JOIN axa_outbox_events e ON e.event_id = o.event_id";

/// How long to wait before the try after `attempts`, doubling each time up to `limit`.
pub(crate) fn backoff(base: Duration, attempts: i32, limit: Duration) -> Duration {
    let doublings = u32::try_from(attempts.saturating_sub(1))
        .unwrap_or(0)
        .min(16);
    base.saturating_mul(1 << doublings).min(limit)
}

/// How one round of a relay ended.
enum Round {
    /// It claimed or decided something.
    Worked,
    /// There was nothing to claim.
    Empty,
    /// The broker is not taking events, or no key here opens what is owed.
    Stalled,
}

/// How one publish ended.
enum Published {
    Sent,
    Failed(Failure),
    TimedOut,
}

/// What one claim took.
#[derive(Default)]
struct Taken {
    batch: Vec<Claimed>,
    /// Events refused, held, or failed in the claim itself.
    decided: usize,
    /// Sealed events no key here opens, left as they were.
    unopened: usize,
}

/// What the claim did with one event.
enum Decided {
    Deliver,
    Refused,
    Held,
}

/// Why a payload could not be read for publishing.
enum Unread {
    /// No key here opens it. Nothing is written, and the event waits.
    NoKey,
    /// It does not match what was written.
    Tampered,
}

/// A connection to the outbox, and the relay that drains it. Clones share a pool and
/// are the same relay.
#[derive(Clone)]
pub struct Outbox {
    pool: PgPool,
    options: OutboxOptions,
    relay: Uuid,
    unordered: Vec<String>,
    #[cfg(feature = "encryption")]
    keys: Option<Keys>,
}

impl fmt::Debug for Outbox {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Outbox")
            .field("relay", &self.relay)
            .field("options", &self.options)
            .finish_non_exhaustive()
    }
}

impl Outbox {
    /// Open the pool, without touching the schema.
    async fn open(uri: &str, options: OutboxOptions) -> Result<Self, sqlx::Error> {
        options.validate()?;
        let pool = PgPoolOptions::new()
            .max_connections(CONNECTIONS)
            .connect(uri)
            .await?;
        Ok(Self {
            pool,
            unordered: options.unordered(),
            options,
            relay: Uuid::new_v4(),
            #[cfg(feature = "encryption")]
            keys: None,
        })
    }

    /// Connect to outbox tables that a migration made, and change no schema, for a
    /// database role that may not. A migration runs [`SETUP_STATEMENTS`].
    ///
    /// # Errors
    ///
    /// Fails on options that cannot work, when the database cannot be reached, or when
    /// a table, an index, or a trigger is missing or turned off, so a service finds
    /// out at boot. There is no way to run without the triggers.
    pub async fn connect_existing(uri: &str, options: OutboxOptions) -> Result<Self, sqlx::Error> {
        let outbox = Self::open(uri, options).await?;
        outbox.check_schema().await?;
        Ok(outbox)
    }

    /// Connect and create the outbox tables if needed, which runs DDL at boot. Use
    /// [`Outbox::connect_existing`] where a service's role may not.
    ///
    /// # Errors
    ///
    /// Fails on options that cannot work, when the database cannot be reached, or when
    /// the tables cannot be created.
    pub async fn connect(uri: &str, options: OutboxOptions) -> Result<Self, sqlx::Error> {
        let outbox = Self::open(uri, options).await?;
        // `CREATE ... IF NOT EXISTS` is not safe against itself, so setup runs one at
        // a time. The lock ends with the transaction.
        let mut setup = outbox.pool.begin().await?;
        sqlx::query("SELECT pg_advisory_xact_lock($1)")
            .bind(SETUP_LOCK)
            .execute(&mut *setup)
            .await?;
        for statement in SETUP_STATEMENTS {
            sqlx::query(statement).execute(&mut *setup).await?;
        }
        setup.commit().await?;
        Ok(outbox)
    }

    /// Refuse to run on tables without their triggers, indexes, or fingerprint.
    async fn check_schema(&self) -> Result<(), sqlx::Error> {
        for probe in PROBES {
            sqlx::query(probe).execute(&self.pool).await?;
        }
        let tables: Vec<&str> = TRIGGERS.iter().map(|(table, _, _)| *table).collect();
        let names: Vec<&str> = TRIGGERS.iter().map(|(_, name, _)| *name).collect();
        let always: Vec<bool> = TRIGGERS.iter().map(|(_, _, always)| *always).collect();
        let mut missing: Vec<String> = sqlx::query_scalar(MISSING_TRIGGERS)
            .bind(tables)
            .bind(names)
            .bind(always)
            .fetch_all(&self.pool)
            .await?;
        missing.extend(
            sqlx::query_scalar::<_, String>(MISSING_INDEXES)
                .bind(INDEXES.to_vec())
                .fetch_all(&self.pool)
                .await?,
        );
        if sqlx::query_scalar::<_, bool>(MISSING_FINGERPRINT)
            .fetch_one(&self.pool)
            .await?
        {
            missing.push("axa_outbox_fingerprint".to_string());
        }
        if missing.is_empty() {
            Ok(())
        } else {
            Err(sqlx::Error::Configuration(
                format!(
                    "the outbox is missing, or has turned off, {}: run SETUP_STATEMENTS",
                    missing.join(", ")
                )
                .into(),
            ))
        }
    }

    /// Open sealed payloads with `keys`, the same keys the service's [`Writer`] seals
    /// with. A sealed payload that no key here opens is left as it was, and the relay
    /// logs that it is stuck.
    ///
    /// [`Writer`]: crate::Writer
    #[cfg(feature = "encryption")]
    #[must_use]
    pub fn opening(mut self, keys: Keys) -> Self {
        self.keys = Some(keys);
        self
    }

    /// The id this relay writes on its attempts.
    #[must_use]
    pub fn relay(&self) -> Uuid {
        self.relay
    }

    /// Check the database connection.
    ///
    /// # Errors
    ///
    /// Fails when the database does not answer.
    pub async fn ping(&self) -> Result<(), sqlx::Error> {
        sqlx::query("SELECT 1").execute(&self.pool).await?;
        Ok(())
    }

    /// Take up to [`OutboxOptions::batch_size`] events, oldest first, for this caller
    /// alone, having first recovered what a dead relay left. Each is decided with
    /// `decide`, in the claim's transaction: a refusal is recorded there, with
    /// `record`, and a hold writes nothing. What comes back is to be delivered, and
    /// each must then be passed to [`Outbox::delivered`], [`Outbox::failed`],
    /// [`Outbox::refused`], or [`Outbox::returned`], within
    /// [`OutboxOptions::stale_minutes`], or with [`Outbox::heartbeat`] along the way.
    ///
    /// # Errors
    ///
    /// Fails on a database error, or when `record` fails for a recovered claim. A
    /// decision or record that fails for one event leaves that event as it was, to be
    /// decided again after [`OutboxOptions::hold_interval`], and is logged.
    pub async fn claim<D, R>(&self, decide: D, record: R) -> Result<Vec<Claimed>, sqlx::Error>
    where
        D: AsyncFn(&Claimed, &mut PgConnection) -> Result<Decision, sqlx::Error>,
        R: AsyncFn(&Attempt, &mut PgConnection) -> Result<(), sqlx::Error>,
    {
        Ok(self.take(&decide, &record).await?.batch)
    }

    async fn take<D, R>(&self, decide: &D, record: &R) -> Result<Taken, sqlx::Error>
    where
        D: AsyncFn(&Claimed, &mut PgConnection) -> Result<Decision, sqlx::Error>,
        R: AsyncFn(&Attempt, &mut PgConnection) -> Result<(), sqlx::Error>,
    {
        self.recover_with(record).await?;
        let claim = Uuid::new_v4();
        let mut transaction = self.pool.begin().await?;
        let rows = sqlx::query(CANDIDATES)
            .bind(self.options.batch_size)
            .bind(&self.unordered)
            .fetch_all(&mut *transaction)
            .await?;
        let mut taken = Taken::default();
        for row in &rows {
            let charges: i32 = row.try_get("charges")?;
            let mut event = Claimed {
                id: row.try_get("id")?,
                attempts: charges.saturating_add(1),
                event_id: row.try_get("event_id")?,
                topic: row.try_get("topic")?,
                kind: row.try_get("kind")?,
                key: row.try_get("key")?,
                tenant: row.try_get("tenant")?,
                payload: Value::Null,
                relay: self.relay,
                claim,
            };
            match self.payload_of(&event, row)? {
                Ok(payload) => event.payload = payload,
                Err(Unread::NoKey) => {
                    taken.unopened += 1;
                    continue;
                }
                Err(Unread::Tampered) => {
                    taken.decided += 1;
                    let mut point = (&mut transaction).begin().await?;
                    match self.tampered(record, &event, &mut point).await {
                        Ok(()) => {
                            point.commit().await?;
                            tracing::error!(
                                id = event.id,
                                topic = event.topic,
                                kind = event.kind,
                                "outbox event no longer matches what was written, and is not published"
                            );
                        }
                        Err(error) => {
                            point.rollback().await?;
                            self.defer(&mut transaction, &event, &error).await?;
                        }
                    }
                    continue;
                }
            }
            let mut point = (&mut transaction).begin().await?;
            match self.decide_one(decide, record, &event, &mut point).await {
                Ok(Decided::Deliver) => {
                    point.commit().await?;
                    taken.batch.push(event);
                }
                Ok(decided) => {
                    point.commit().await?;
                    taken.decided += 1;
                    if matches!(decided, Decided::Refused) {
                        tracing::info!(
                            id = event.id,
                            topic = event.topic,
                            kind = event.kind,
                            "outbox event refused by the service's decision"
                        );
                    }
                }
                Err(error) => {
                    point.rollback().await?;
                    taken.decided += 1;
                    self.defer(&mut transaction, &event, &error).await?;
                }
            }
        }
        if !taken.batch.is_empty() {
            let event_ids: Vec<Uuid> = taken.batch.iter().map(|event| event.event_id).collect();
            sqlx::query(LEASE)
                .bind(claim)
                .bind(self.relay)
                .execute(&mut *transaction)
                .await?;
            sqlx::query(CLAIMED)
                .bind(event_ids)
                .bind(self.relay)
                .bind(claim)
                .execute(&mut *transaction)
                .await?;
        }
        transaction.commit().await?;
        Ok(taken)
    }

    /// The payload of a candidate row, opened if it was sealed.
    fn payload_of(
        &self,
        event: &Claimed,
        row: &PgRow,
    ) -> Result<Result<Value, Unread>, sqlx::Error> {
        if !row.try_get::<bool, _>("intact")? {
            return Ok(Err(Unread::Tampered));
        }
        if let Some(payload) = row.try_get::<Option<Value>, _>("payload")? {
            return Ok(Ok(payload));
        }
        let Some(sealed) = row.try_get::<Option<Vec<u8>>, _>("sealed")? else {
            return Ok(Err(Unread::Tampered));
        };
        Ok(self.open_sealed(event.event_id, &sealed))
    }

    #[cfg(feature = "encryption")]
    fn open_sealed(&self, event_id: Uuid, sealed: &[u8]) -> Result<Value, Unread> {
        let Some(keys) = &self.keys else {
            return Err(Unread::NoKey);
        };
        match keys.open(event_id, sealed) {
            Ok(plain) => serde_json::from_slice(&plain).map_err(|_| Unread::Tampered),
            Err(Unopened::NoKey) => Err(Unread::NoKey),
            Err(Unopened::Tampered) => Err(Unread::Tampered),
        }
    }

    #[cfg(not(feature = "encryption"))]
    #[allow(clippy::unused_self, reason = "the same call as with the feature")]
    fn open_sealed(&self, _event_id: Uuid, _sealed: &[u8]) -> Result<Value, Unread> {
        Err(Unread::NoKey)
    }

    /// Fail a changed event for good, and record it, in the claim's transaction.
    async fn tampered<R>(
        &self,
        record: &R,
        event: &Claimed,
        point: &mut Transaction<'_, Postgres>,
    ) -> Result<(), sqlx::Error>
    where
        R: AsyncFn(&Attempt, &mut PgConnection) -> Result<(), sqlx::Error>,
    {
        let attempt = self
            .decided(point, event, Outcome::Failed, "tampered")
            .await?;
        record(&attempt, &mut **point).await
    }

    /// Ask the service about one event, and act on its answer, in a savepoint of the
    /// claim's transaction.
    async fn decide_one<D, R>(
        &self,
        decide: &D,
        record: &R,
        event: &Claimed,
        point: &mut Transaction<'_, Postgres>,
    ) -> Result<Decided, sqlx::Error>
    where
        D: AsyncFn(&Claimed, &mut PgConnection) -> Result<Decision, sqlx::Error>,
        R: AsyncFn(&Attempt, &mut PgConnection) -> Result<(), sqlx::Error>,
    {
        match decide(event, &mut **point).await? {
            Decision::Deliver => Ok(Decided::Deliver),
            Decision::Refuse(reason) => {
                let attempt = self
                    .decided(point, event, Outcome::Refused, &code(&reason))
                    .await?;
                record(&attempt, &mut **point).await?;
                Ok(Decided::Refused)
            }
            Decision::Hold => {
                sqlx::query(HOLD)
                    .bind(event.event_id)
                    .bind(self.options.hold_interval.as_secs_f64())
                    .execute(&mut **point)
                    .await?;
                Ok(Decided::Held)
            }
        }
    }

    /// Write an outcome reached in the claim, on a row the claim holds.
    async fn decided(
        &self,
        point: &mut Transaction<'_, Postgres>,
        event: &Claimed,
        outcome: Outcome,
        reason: &str,
    ) -> Result<Attempt, sqlx::Error> {
        let id: i64 = sqlx::query_scalar(DECIDED)
            .bind(event.event_id)
            .bind(outcome.as_str())
            .bind(self.relay)
            .bind(event.claim)
            .bind(reason)
            .fetch_one(&mut **point)
            .await?;
        Ok(attempt_of(event, id, outcome, Some(reason.to_string())))
    }

    /// Leave an event whose decision or record failed as it was, to be decided again
    /// after a hold's wait rather than at once.
    async fn defer(
        &self,
        transaction: &mut Transaction<'_, Postgres>,
        event: &Claimed,
        error: &sqlx::Error,
    ) -> Result<(), sqlx::Error> {
        tracing::error!(
            id = event.id,
            topic = event.topic,
            kind = event.kind,
            %error,
            "outbox decision or record failed, and the event waits"
        );
        sqlx::query(DEFER)
            .bind(event.event_id)
            .bind(self.options.hold_interval.as_secs_f64())
            .execute(&mut **transaction)
            .await?;
        Ok(())
    }

    /// Say, in the caller's `transaction`, that the broker has `events`, returning the
    /// attempts written, for the caller's audit. Call this only once the broker has
    /// acknowledged them. A claim given up on still counts, as an attempt of its own,
    /// because the broker has the event whoever says so. A claim already ended, or not
    /// this relay's, writes nothing.
    ///
    /// # Errors
    ///
    /// Fails on a database error. The events then count as lost, and are published
    /// again.
    pub async fn delivered(
        &self,
        transaction: &mut Transaction<'_, Postgres>,
        events: &[Claimed],
    ) -> Result<Vec<Attempt>, sqlx::Error> {
        let mut written = Vec::new();
        for event in events {
            sqlx::query(LOCK_OWED)
                .bind(event.event_id)
                .execute(&mut **transaction)
                .await?;
            let id: Option<i64> = sqlx::query_scalar(DELIVERED)
                .bind(event.event_id)
                .bind(event.relay)
                .bind(event.claim)
                .fetch_optional(&mut **transaction)
                .await?;
            if let Some(id) = id {
                written.push(attempt_of(event, id, Outcome::Delivered, None));
            }
        }
        Ok(written)
    }

    /// Charge `event` an attempt, for the broker's `reason`, in the caller's
    /// `transaction`. It is tried again after a wait, as `rejected`, or with no
    /// attempts left is `failed`. Answers the attempt written, or `None` when the claim
    /// was given up on or already ended, which changes nothing.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn failed(
        &self,
        transaction: &mut Transaction<'_, Postgres>,
        event: &Claimed,
        reason: &str,
    ) -> Result<Option<Attempt>, sqlx::Error> {
        let wait = backoff(self.options.retry_backoff, event.attempts, MAX_BACKOFF);
        self.ended(transaction, event, false, &code(reason), wait)
            .await
    }

    /// Refuse `event` for good, for `reason`, in the caller's `transaction`, as a
    /// decision made after the claim. Nothing puts it back. Answers the attempt
    /// written, or `None` when the claim was given up on or already ended.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn refused(
        &self,
        transaction: &mut Transaction<'_, Postgres>,
        event: &Claimed,
        reason: &str,
    ) -> Result<Option<Attempt>, sqlx::Error> {
        self.ended(transaction, event, true, &code(reason), Duration::ZERO)
            .await
    }

    async fn ended(
        &self,
        transaction: &mut Transaction<'_, Postgres>,
        event: &Claimed,
        refuse: bool,
        reason: &str,
        wait: Duration,
    ) -> Result<Option<Attempt>, sqlx::Error> {
        let row = sqlx::query(ENDED)
            .bind(event.event_id)
            .bind(self.relay)
            .bind(event.claim)
            .bind(refuse)
            .bind(self.options.max_attempts)
            .bind(reason)
            .bind(wait.as_secs_f64())
            .fetch_optional(&mut **transaction)
            .await?;
        let Some(row) = row else {
            return Ok(None);
        };
        let outcome: String = row.try_get("outcome")?;
        let outcome = Outcome::parse(&outcome).unwrap_or(Outcome::Failed);
        Ok(Some(attempt_of(
            event,
            row.try_get("id")?,
            outcome,
            Some(reason.to_string()),
        )))
    }

    /// Give `events` back untouched, in the caller's `transaction`, charging nothing,
    /// for events not published. Answers how many went back: a claim given up on gives
    /// back nothing.
    ///
    /// # Errors
    ///
    /// Fails on a database error. The events then wait to be recovered as lost.
    pub async fn returned(
        &self,
        transaction: &mut Transaction<'_, Postgres>,
        events: &[Claimed],
    ) -> Result<u64, sqlx::Error> {
        self.give_back(transaction, events, None, Duration::ZERO)
            .await
    }

    async fn give_back(
        &self,
        transaction: &mut Transaction<'_, Postgres>,
        events: &[Claimed],
        reason: Option<&str>,
        wait: Duration,
    ) -> Result<u64, sqlx::Error> {
        if events.is_empty() {
            return Ok(0);
        }
        let event_ids: Vec<Uuid> = events.iter().map(|event| event.event_id).collect();
        let claims: Vec<Uuid> = events.iter().map(|event| event.claim).collect();
        let result = sqlx::query(RETURNED)
            .bind(event_ids)
            .bind(claims)
            .bind(self.relay)
            .bind(reason.map(code))
            .bind(wait.as_secs_f64())
            .execute(&mut **transaction)
            .await?;
        Ok(result.rows_affected())
    }

    /// Report in for the claims of `events`, so a batch can take longer than
    /// [`OutboxOptions::stale_minutes`]. [`Outbox::run`] does this by itself. Answers
    /// how many claims were heard from.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn heartbeat(&self, events: &[Claimed]) -> Result<u64, sqlx::Error> {
        let mut claims: Vec<Uuid> = events.iter().map(|event| event.claim).collect();
        claims.sort_unstable();
        claims.dedup();
        let result = sqlx::query(HEARTBEAT)
            .bind(claims)
            .execute(&self.pool)
            .await?;
        Ok(result.rows_affected())
    }

    /// End every claim not heard from for [`OutboxOptions::stale_minutes`], with a
    /// `lost` attempt if the event has attempts left and an `abandoned` one if not,
    /// recording each with `record`, and editing nothing. Answers how many went back.
    /// [`Outbox::claim`] does this first.
    ///
    /// # Errors
    ///
    /// Fails on a database error, or when `record` fails, and then nothing is ended.
    pub async fn recover<R>(&self, record: R) -> Result<u64, sqlx::Error>
    where
        R: AsyncFn(&Attempt, &mut PgConnection) -> Result<(), sqlx::Error>,
    {
        self.recover_with(&record).await
    }

    async fn recover_with<R>(&self, record: &R) -> Result<u64, sqlx::Error>
    where
        R: AsyncFn(&Attempt, &mut PgConnection) -> Result<(), sqlx::Error>,
    {
        let mut transaction = self.pool.begin().await?;
        let rows = sqlx::query(RECOVER)
            .bind(self.options.stale_minutes)
            .bind(self.options.max_attempts)
            .bind(self.relay)
            .fetch_all(&mut *transaction)
            .await?;
        let (mut lost, mut abandoned) = (0_u64, 0_u64);
        for row in &rows {
            let outcome: String = row.try_get("outcome")?;
            let outcome = Outcome::parse(&outcome).unwrap_or(Outcome::Lost);
            if outcome == Outcome::Abandoned {
                abandoned += 1;
            } else {
                lost += 1;
            }
            let attempt = Attempt {
                id: row.try_get("id")?,
                event_id: row.try_get("event_id")?,
                topic: row.try_get("topic")?,
                kind: row.try_get("kind")?,
                key: row.try_get("key")?,
                outcome,
                reason: None,
                relay: self.relay,
                claim: row.try_get("claim")?,
            };
            record(&attempt, &mut *transaction).await?;
        }
        sqlx::query(DROP_LEASES)
            .bind(self.options.stale_minutes)
            .execute(&mut *transaction)
            .await?;
        transaction.commit().await?;
        if abandoned > 0 {
            tracing::error!(
                abandoned,
                "outbox events failed for good, abandoned by relays"
            );
        }
        if lost > 0 {
            tracing::warn!(lost, "outbox events recovered from a lost relay");
        }
        Ok(lost)
    }

    /// Say what is owed, and what went out or was refused in the last hour. This reads
    /// only what is owed, and the last hour's outcomes.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn stats(&self) -> Result<Stats, sqlx::Error> {
        let row = sqlx::query(STATS).fetch_one(&self.pool).await?;
        let age = |column: &str| -> Result<Option<Duration>, sqlx::Error> {
            let seconds: Option<f64> = row.try_get(column)?;
            Ok(seconds.map(|seconds| Duration::from_secs_f64(seconds.max(0.0))))
        };
        Ok(Stats {
            pending: row.try_get("pending")?,
            claimed: row.try_get("claimed")?,
            held: row.try_get("held")?,
            failed: row.try_get("failed")?,
            tampered: row.try_get("tampered")?,
            delivered: row.try_get("delivered")?,
            refused: row.try_get("refused")?,
            oldest: age("oldest")?,
            oldest_held: age("oldest_held")?,
            oldest_failed: age("oldest_failed")?,
        })
    }

    /// Relay until `shutdown` changes to `true`.
    ///
    /// Each event is first decided with `decide`, in the claim's transaction. Those
    /// to deliver are published with `publish`, which answers `Ok` only once the broker
    /// has acknowledged the event, and a [`Failure`] otherwise. A publisher that says
    /// `Ok` without doing that, as one that only logs does, records deliveries nobody
    /// received. It runs in its own task, so a panic stops only that publish. Each
    /// outcome is then written, and `record` runs in its transaction before it commits.
    /// If `record` fails, the outcome rolls back, the event stays claimed to be
    /// recovered, and the rest of the batch goes back.
    ///
    /// On shutdown a publish in progress finishes, within
    /// [`OutboxOptions::publish_timeout`], and the rest of the batch goes back. Run
    /// more than one by connecting more than once, or from more than one process.
    ///
    /// The decision and the record are required, as there is no form of `run` without
    /// them. A service with no rule and no audit says so with [`decide::deliver_all`] and
    /// [`record::nothing`]. This does not compile:
    ///
    /// ```compile_fail,E0061
    /// # async fn example(outbox: axa_transactional_outbox::Outbox, stopped: tokio::sync::watch::Receiver<bool>) {
    /// outbox
    ///     .run(|_event| async { Ok::<(), axa_transactional_outbox::Failure>(()) }, stopped)
    ///     .await;
    /// # }
    /// ```
    ///
    /// [`decide::deliver_all`]: crate::decide::deliver_all
    /// [`record::nothing`]: crate::record::nothing
    pub async fn run<D, P, F, R>(
        self,
        decide: D,
        publish: P,
        record: R,
        mut shutdown: watch::Receiver<bool>,
    ) where
        D: AsyncFn(&Claimed, &mut PgConnection) -> Result<Decision, sqlx::Error> + Send + Sync,
        P: Fn(Claimed) -> F + Send + Sync + 'static,
        F: Future<Output = Result<(), Failure>> + Send + 'static,
        R: AsyncFn(&Attempt, &mut PgConnection) -> Result<(), sqlx::Error> + Send + Sync,
    {
        let mut pauses = 0;
        while !*shutdown.borrow() {
            let wait = match self.round(&decide, &publish, &record, &shutdown).await {
                Ok(Round::Worked) => {
                    pauses = 0;
                    continue;
                }
                Ok(Round::Empty) => {
                    pauses = 0;
                    self.options.poll_interval
                }
                Ok(Round::Stalled) => {
                    pauses += 1;
                    backoff(self.options.poll_interval, pauses, MAX_PAUSE)
                }
                Err(error) => {
                    tracing::error!(%error, "outbox relay error");
                    pauses += 1;
                    backoff(self.options.poll_interval, pauses, MAX_PAUSE)
                }
            };
            tokio::select! {
                () = tokio::time::sleep(wait) => {},
                changed = shutdown.changed() => {
                    // With no sender left, nothing could ever stop this loop.
                    if changed.is_err() {
                        break;
                    }
                },
            }
        }
    }

    /// Claim a batch and publish it in turn, recording each event as it goes, so that a
    /// crash repeats as few as it can.
    async fn round<D, P, F, R>(
        &self,
        decide: &D,
        publish: &P,
        record: &R,
        shutdown: &watch::Receiver<bool>,
    ) -> Result<Round, sqlx::Error>
    where
        D: AsyncFn(&Claimed, &mut PgConnection) -> Result<Decision, sqlx::Error>,
        P: Fn(Claimed) -> F,
        F: Future<Output = Result<(), Failure>> + Send + 'static,
        R: AsyncFn(&Attempt, &mut PgConnection) -> Result<(), sqlx::Error>,
    {
        let taken = self.take(decide, record).await?;
        if taken.unopened > 0 {
            tracing::error!(
                unopened = taken.unopened,
                "outbox holds sealed payloads that no key here opens"
            );
        }
        let batch = taken.batch;
        let Some(claim) = batch.first().map(|event| event.claim) else {
            return Ok(if taken.decided > 0 {
                Round::Worked
            } else if taken.unopened > 0 {
                Round::Stalled
            } else {
                Round::Empty
            });
        };
        let every = self.options.heartbeat_interval;
        let mut beat = tokio::time::interval_at(Instant::now() + every, every);
        beat.set_missed_tick_behavior(MissedTickBehavior::Delay);
        let mut round = Round::Worked;
        for (place, event) in batch.iter().enumerate() {
            let held = &batch[place..];
            if *shutdown.borrow() {
                self.hand_back(held, None, Duration::ZERO).await?;
                break;
            }
            let outcome = match self.attend(publish(event.clone()), claim, &mut beat).await {
                Published::Sent => self.settle(record, event, None).await,
                Published::Failed(Failure::Rejected(reason)) => {
                    self.settle(record, event, Some(&reason)).await
                }
                Published::Failed(Failure::Unavailable(reason)) => {
                    tracing::warn!(id = event.id, "outbox publisher is unavailable");
                    self.hold_back(held, &reason).await?;
                    round = Round::Stalled;
                    break;
                }
                Published::TimedOut => {
                    tracing::warn!(id = event.id, "outbox publish timed out");
                    round = Round::Stalled;
                    self.settle(record, event, Some("timed_out")).await
                }
            };
            if let Err(error) = outcome {
                // The event stays claimed, to be recovered. The rest go back now.
                if let Err(also) = self.hand_back(&held[1..], None, Duration::ZERO).await {
                    tracing::error!(error = %also, "outbox could not give back a batch");
                }
                return Err(error);
            }
            if matches!(round, Round::Stalled) {
                self.hand_back(&held[1..], None, Duration::ZERO).await?;
                break;
            }
        }
        sqlx::query(END_LEASE)
            .bind(claim)
            .execute(&self.pool)
            .await?;
        Ok(round)
    }

    /// Write one event's outcome, delivered or charged for `failure`, and record it, in
    /// one transaction.
    async fn settle<R>(
        &self,
        record: &R,
        event: &Claimed,
        failure: Option<&str>,
    ) -> Result<(), sqlx::Error>
    where
        R: AsyncFn(&Attempt, &mut PgConnection) -> Result<(), sqlx::Error>,
    {
        let mut transaction = self.pool.begin().await?;
        let attempt = match failure {
            None => self
                .delivered(&mut transaction, std::slice::from_ref(event))
                .await?
                .pop(),
            Some(reason) => self.failed(&mut transaction, event, reason).await?,
        };
        if let Some(attempt) = &attempt {
            record(attempt, &mut *transaction).await?;
        }
        transaction.commit().await?;
        let (id, topic, kind, attempts) = (event.id, &event.topic, &event.kind, event.attempts);
        match attempt.map(|attempt| attempt.outcome) {
            Some(Outcome::Failed) => {
                tracing::error!(id, topic, kind, attempts, "outbox event failed for good");
            }
            Some(Outcome::Rejected) => {
                tracing::warn!(id, topic, kind, attempts, "outbox event will be retried");
            }
            Some(_) => {}
            None => tracing::warn!(id, topic, kind, attempts, "outbox claim was given up on"),
        }
        Ok(())
    }

    /// Give `events` back in a transaction of the relay's own.
    async fn hand_back(
        &self,
        events: &[Claimed],
        reason: Option<&str>,
        wait: Duration,
    ) -> Result<(), sqlx::Error> {
        if events.is_empty() {
            return Ok(());
        }
        let mut transaction = self.pool.begin().await?;
        self.give_back(&mut transaction, events, reason, wait)
            .await?;
        transaction.commit().await
    }

    /// Give `held` back after an outage, charging nothing. The first keeps the reason,
    /// and waits [`OutboxOptions::retry_backoff`], so that one event a publisher wrongly
    /// calls an outage holds up its own key and no other.
    async fn hold_back(&self, held: &[Claimed], reason: &str) -> Result<(), sqlx::Error> {
        let mut transaction = self.pool.begin().await?;
        self.give_back(
            &mut transaction,
            &held[..1],
            Some(reason),
            self.options.retry_backoff,
        )
        .await?;
        self.give_back(&mut transaction, &held[1..], None, Duration::ZERO)
            .await?;
        transaction.commit().await
    }

    /// Run one publish to its end in its own task, keeping the claim alive meanwhile,
    /// so that a panic or a hang stops only the publish.
    async fn attend<F>(&self, work: F, claim: Uuid, beat: &mut Interval) -> Published
    where
        F: Future<Output = Result<(), Failure>> + Send + 'static,
    {
        let mut job = tokio::spawn(work);
        let limit = tokio::time::sleep(self.options.publish_timeout);
        tokio::pin!(limit);
        loop {
            tokio::select! {
                finished = &mut job => {
                    return match finished {
                        Ok(Ok(())) => Published::Sent,
                        Ok(Err(failure)) => Published::Failed(failure),
                        Err(_) => Published::Failed(Failure::rejected("publisher_panicked")),
                    };
                }
                () = &mut limit => {
                    job.abort();
                    return Published::TimedOut;
                }
                _ = beat.tick() => {
                    let heard = sqlx::query(HEARTBEAT)
                        .bind(vec![claim])
                        .execute(&self.pool)
                        .await;
                    if let Err(error) = heard {
                        tracing::warn!(%error, "outbox heartbeat failed");
                    }
                }
            }
        }
    }
}

/// The attempt an outcome for `event` wrote.
fn attempt_of(event: &Claimed, id: i64, outcome: Outcome, reason: Option<String>) -> Attempt {
    Attempt {
        id,
        event_id: event.event_id,
        topic: event.topic.clone(),
        kind: event.kind.clone(),
        key: event.key.clone(),
        outcome,
        reason,
        relay: event.relay,
        claim: event.claim,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn each_retry_waits_twice_as_long_up_to_a_limit() {
        let base = Duration::from_secs(5);
        assert_eq!(backoff(base, 1, MAX_BACKOFF), base);
        assert_eq!(backoff(base, 2, MAX_BACKOFF), base * 2);
        assert_eq!(backoff(base, 3, MAX_BACKOFF), base * 4);
        assert_eq!(backoff(base, 1_000, MAX_BACKOFF), MAX_BACKOFF);
    }

    #[test]
    fn an_outage_waits_longer_each_time_up_to_a_minute() {
        let base = Duration::from_secs(1);
        assert_eq!(backoff(base, 1, MAX_PAUSE), base);
        assert_eq!(backoff(base, 3, MAX_PAUSE), base * 4);
        assert_eq!(backoff(base, 1_000, MAX_PAUSE), MAX_PAUSE);
    }
}

//! The tables, their triggers, and the import from 0.1.0. Every statement here is safe
//! to repeat.
//!
//! Three tables are the record, and are only ever inserted into: `axa_outbox_events`,
//! `axa_outbox_attempts`, and `axa_outbox_payloads`, whose one allowed change is the
//! blanking of an erased payload. Two are working state, and change: `axa_outbox_owed`,
//! which the database derives from the attempts, and `axa_outbox_leases`, which says
//! which relays are still alive.

/// The record of each event, without its payload.
const EVENTS: &str = "CREATE TABLE IF NOT EXISTS axa_outbox_events (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    event_id UUID NOT NULL UNIQUE,
    topic TEXT NOT NULL,
    kind TEXT NOT NULL,
    key TEXT NOT NULL,
    fingerprint TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
)";

/// Each payload, in its own table so that an erasure can blank it and touch nothing else.
/// `payload` is plain JSON, and `sealed` is the encrypted form. Both are null only once
/// the event is erased.
const PAYLOADS: &str = "CREATE TABLE IF NOT EXISTS axa_outbox_payloads (
    event_id UUID PRIMARY KEY REFERENCES axa_outbox_events (event_id),
    payload JSONB,
    sealed BYTEA,
    CHECK (payload IS NULL OR sealed IS NULL)
)";

/// Everything that happened to each event. An event's state is its latest attempt.
const ATTEMPTS: &str = "CREATE TABLE IF NOT EXISTS axa_outbox_attempts (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    event_id UUID NOT NULL REFERENCES axa_outbox_events (event_id),
    outcome TEXT NOT NULL CHECK (outcome IN ('claimed', 'returned', 'delivered', 'refused',
        'rejected', 'failed', 'lost', 'abandoned', 'released', 'erased', 'imported')),
    relay UUID NOT NULL,
    claim UUID NOT NULL,
    reason TEXT CHECK (length(reason) <= 200 AND reason !~ '[[:cntrl:]]'),
    by TEXT CHECK (length(by) <= 200 AND by !~ '[[:cntrl:]]'),
    retry_at TIMESTAMPTZ,
    at TIMESTAMPTZ NOT NULL DEFAULT now()
)";

/// Working state: the events still owed, derived from the attempts by
/// `axa_outbox_follow`, so that finding work never reads what was delivered. A hold is
/// kept here too, as it writes no attempt.
const OWED: &str = "CREATE TABLE IF NOT EXISTS axa_outbox_owed (
    event_id UUID PRIMARY KEY REFERENCES axa_outbox_events (event_id),
    id BIGINT NOT NULL,
    topic TEXT NOT NULL,
    key TEXT NOT NULL,
    state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'claimed', 'failed')),
    claim UUID,
    charges INTEGER NOT NULL DEFAULT 0,
    reason TEXT,
    retry_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    held_since TIMESTAMPTZ,
    recheck_at TIMESTAMPTZ
)";

/// Working state: when each live claim last reported in.
const LEASES: &str = "CREATE TABLE IF NOT EXISTS axa_outbox_leases (
    claim UUID PRIMARY KEY,
    relay UUID NOT NULL,
    heard_at TIMESTAMPTZ NOT NULL DEFAULT now()
)";

/// The tenant an event is for, when it has one, as an auth crate's `Tenant` names it.
/// Added to a table that may already hold events, each of which then has none.
const EVENTS_TENANT: &str = "ALTER TABLE axa_outbox_events ADD COLUMN IF NOT EXISTS tenant TEXT
    CONSTRAINT axa_outbox_events_tenant_id
    CHECK (tenant ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$')";
/// The tenant of each event owed, so that events keep their order per tenant, topic,
/// and key, and one tenant's event never holds back another's.
const OWED_TENANT: &str = "ALTER TABLE axa_outbox_owed ADD COLUMN IF NOT EXISTS tenant TEXT";

/// What a claim walks, oldest first.
const OWED_READY: &str = "CREATE INDEX IF NOT EXISTS axa_outbox_owed_ready
    ON axa_outbox_owed (id) WHERE state = 'pending'";
/// Finds an earlier event for a key. A failed one frees its key.
const OWED_LINE: &str = "CREATE INDEX IF NOT EXISTS axa_outbox_owed_line
    ON axa_outbox_owed (topic, key, id) WHERE state <> 'failed'";
/// What recovery looks at, on every claim.
const OWED_CLAIMED: &str = "CREATE INDEX IF NOT EXISTS axa_outbox_owed_claimed
    ON axa_outbox_owed (claim) WHERE state = 'claimed'";
/// An event's attempts in order, for matching an outcome to its claim.
const ATTEMPTS_EVENT: &str = "CREATE INDEX IF NOT EXISTS axa_outbox_attempts_event
    ON axa_outbox_attempts (event_id, id)";
/// Recent outcomes, for `stats`, without reading old ones.
const ATTEMPTS_RECENT: &str = "CREATE INDEX IF NOT EXISTS axa_outbox_attempts_recent
    ON axa_outbox_attempts (outcome, at) WHERE outcome IN ('delivered', 'refused')";

/// SHA-256 over an event's id, topic, kind, key, and stored payload. A text column
/// cannot hold a zero byte, so the zero bytes between fields cannot be confused with
/// them, and the payload is last.
const FINGERPRINT: &str = r"CREATE OR REPLACE FUNCTION axa_outbox_fingerprint(
    event_id UUID, topic TEXT, kind TEXT, key TEXT, payload JSONB, sealed BYTEA)
RETURNS TEXT LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    SELECT encode(sha256(
        uuid_send(event_id)
        || convert_to(topic, 'UTF8') || '\x00'::bytea
        || convert_to(kind, 'UTF8') || '\x00'::bytea
        || convert_to(key, 'UTF8') || '\x00'::bytea
        || CASE WHEN sealed IS NOT NULL THEN '\x73'::bytea || sealed
                ELSE '\x6a'::bytea || convert_to(payload::text, 'UTF8') END
    ), 'hex')
$$";

/// SHA-256 over an event's id, topic, kind, key, tenant, and stored payload. With no
/// tenant it is the fingerprint above, byte for byte, so every event written before
/// tenants keeps its fingerprint. A tenant is marked by `t`, which neither payload mark
/// is, and ends with a zero byte, which a tenant id cannot hold.
const FINGERPRINT_TENANT: &str = r"CREATE OR REPLACE FUNCTION axa_outbox_fingerprint(
    event_id UUID, topic TEXT, kind TEXT, key TEXT, tenant TEXT, payload JSONB, sealed BYTEA)
RETURNS TEXT LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    SELECT encode(sha256(
        uuid_send(event_id)
        || convert_to(topic, 'UTF8') || '\x00'::bytea
        || convert_to(kind, 'UTF8') || '\x00'::bytea
        || convert_to(key, 'UTF8') || '\x00'::bytea
        || CASE WHEN tenant IS NULL THEN ''::bytea
                ELSE '\x74'::bytea || convert_to(tenant, 'UTF8') || '\x00'::bytea END
        || CASE WHEN sealed IS NOT NULL THEN '\x73'::bytea || sealed
                ELSE '\x6a'::bytea || convert_to(payload::text, 'UTF8') END
    ), 'hex')
$$";

/// Refuses whatever fired it, whoever sent it.
const REFUSE: &str = "CREATE OR REPLACE FUNCTION axa_outbox_refuse() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% on % is refused: the outbox record is only ever added to',
        TG_OP, TG_TABLE_NAME;
END
$$";

/// Allows one change to a payload: blanking it, and nothing else, once the event has an
/// `erased` attempt.
const GUARD: &str = "CREATE OR REPLACE FUNCTION axa_outbox_payloads_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'UPDATE'
        AND NEW.payload IS NULL AND NEW.sealed IS NULL
        AND (OLD.payload IS NOT NULL OR OLD.sealed IS NOT NULL)
        AND to_jsonb(NEW) - 'payload' - 'sealed' = to_jsonb(OLD) - 'payload' - 'sealed'
        AND EXISTS (
            SELECT 1 FROM axa_outbox_attempts erased
            WHERE erased.event_id = OLD.event_id AND erased.outcome = 'erased'
        )
    THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION '% on axa_outbox_payloads is refused: a payload is only blanked, once erased',
        TG_OP;
END
$$";

/// A new event is owed.
const OWE: &str = "CREATE OR REPLACE FUNCTION axa_outbox_owe() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO axa_outbox_owed (event_id, id, topic, key, tenant)
    VALUES (NEW.event_id, NEW.id, NEW.topic, NEW.key, NEW.tenant);
    RETURN NULL;
END
$$";

/// Keeps `axa_outbox_owed` in step with each new attempt, so that the working state is
/// always what the record says.
const FOLLOW: &str = "CREATE OR REPLACE FUNCTION axa_outbox_follow() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.outcome = 'claimed' THEN
        UPDATE axa_outbox_owed
        SET state = 'claimed', claim = NEW.claim, reason = NULL,
            held_since = NULL, recheck_at = NULL
        WHERE event_id = NEW.event_id;
    ELSIF NEW.outcome IN ('returned', 'imported') THEN
        UPDATE axa_outbox_owed
        SET state = 'pending', claim = NULL, reason = NEW.reason,
            retry_at = coalesce(NEW.retry_at, NEW.at)
        WHERE event_id = NEW.event_id;
    ELSIF NEW.outcome IN ('rejected', 'lost') THEN
        UPDATE axa_outbox_owed
        SET state = 'pending', claim = NULL, reason = NEW.reason, charges = charges + 1,
            retry_at = coalesce(NEW.retry_at, NEW.at)
        WHERE event_id = NEW.event_id;
    ELSIF NEW.outcome IN ('failed', 'abandoned') THEN
        UPDATE axa_outbox_owed
        SET state = 'failed', claim = NULL, reason = NEW.reason, charges = charges + 1,
            held_since = NULL, recheck_at = NULL
        WHERE event_id = NEW.event_id;
    ELSIF NEW.outcome = 'released' THEN
        UPDATE axa_outbox_owed
        SET state = 'pending', claim = NULL, reason = NULL, charges = 0, retry_at = NEW.at
        WHERE event_id = NEW.event_id;
    ELSE
        -- delivered, refused, and erased: nothing more is owed.
        DELETE FROM axa_outbox_owed WHERE event_id = NEW.event_id;
    END IF;
    RETURN NULL;
END
$$";

/// Keeps `axa_outbox_owed` what the record says. Only the record's own triggers, which
/// run one level down, may add, remove, or change its rows. From outside them an update
/// may change only a hold, `held_since` and `recheck_at`, and only to a time no later
/// than a day ahead, so that a hold set by hand cannot stop an event for good.
/// `pg_trigger_depth()` is 1 for a statement sent directly, and 2 for one sent by
/// `axa_outbox_owe` or `axa_outbox_follow`.
const OWED_GUARD: &str = "CREATE OR REPLACE FUNCTION axa_outbox_owed_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'TRUNCATE' THEN
        RAISE EXCEPTION 'TRUNCATE on axa_outbox_owed is refused: it is derived from the record';
    END IF;
    IF pg_trigger_depth() > 1 THEN
        RETURN coalesce(NEW, OLD);
    END IF;
    IF TG_OP = 'UPDATE'
        AND to_jsonb(NEW) - 'held_since' - 'recheck_at'
            = to_jsonb(OLD) - 'held_since' - 'recheck_at'
        AND (NEW.held_since IS NULL OR NEW.held_since <= now())
        AND (NEW.recheck_at IS NULL OR NEW.recheck_at <= now() + interval '1 day')
    THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION '% on axa_outbox_owed is refused: it changes only as the record does',
        TG_OP;
END
$$";

/// Keeps a lease from being dated ahead, which would keep a dead relay's claim alive
/// for good, or moved to another claim or relay. Deleting a lease is allowed: its claim
/// is then recovered, and the recovery is recorded.
const LEASES_GUARD: &str = "CREATE OR REPLACE FUNCTION axa_outbox_leases_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.heard_at > now() THEN
        RAISE EXCEPTION 'a lease in axa_outbox_leases cannot be heard from in the future';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.claim <> OLD.claim OR NEW.relay <> OLD.relay) THEN
        RAISE EXCEPTION 'a lease in axa_outbox_leases cannot change its claim or relay';
    END IF;
    RETURN NEW;
END
$$";

const EVENTS_REFUSE: &str = "CREATE OR REPLACE TRIGGER axa_outbox_events_refuse
    BEFORE UPDATE OR DELETE ON axa_outbox_events
    FOR EACH ROW EXECUTE FUNCTION axa_outbox_refuse()";
const EVENTS_REFUSE_TRUNCATE: &str = "CREATE OR REPLACE TRIGGER axa_outbox_events_refuse_truncate
