        (event_id, topic, kind, key, fingerprint, created_at)
    SELECT old.event_id, old.topic, old.kind, old.key,
        axa_outbox_fingerprint(old.event_id, old.topic, old.kind, old.key, old.payload, NULL),
        old.created_at
    FROM axa_outbox old
    WHERE NOT EXISTS (SELECT 1 FROM axa_outbox_events e WHERE e.event_id = old.event_id)
    ORDER BY old.id";
const IMPORT_PAYLOADS: &str = "INSERT INTO axa_outbox_payloads (event_id, payload)
    SELECT old.event_id, old.payload FROM axa_outbox old
    WHERE NOT EXISTS (SELECT 1 FROM axa_outbox_payloads p WHERE p.event_id = old.event_id)
    ORDER BY old.id";
const IMPORT_ATTEMPTS: &str = "INSERT INTO axa_outbox_attempts
        (event_id, outcome, relay, claim, reason, by, retry_at, at)
    SELECT old.event_id,
        CASE old.status WHEN 'sent' THEN 'delivered' WHEN 'failed' THEN 'failed'
            ELSE 'imported' END,
        '00000000-0000-0000-0000-000000000000', '00000000-0000-0000-0000-000000000000',
        'imported: ' || CASE old.status WHEN 'claimed' THEN 'pending' ELSE old.status END
            || ', ' || old.attempts || ' attempts',
        'axa-transactional-outbox 0.1.0',
        CASE WHEN old.status IN ('pending', 'claimed') THEN old.run_at END,
        coalesce(old.sent_at, old.updated_at)
    FROM axa_outbox old
    WHERE NOT EXISTS (SELECT 1 FROM axa_outbox_attempts a WHERE a.event_id = old.event_id)
    ORDER BY old.id";

/// The statements that copy each row of the 0.1.0 table `axa_outbox` into the record, in
/// order, each safe to repeat. Run them in a migration after [`SETUP_STATEMENTS`], with
/// every relay stopped. Each row keeps its id's order, its payload, and its time, and
/// gets one attempt for its state: `delivered` for a sent row, `failed` for a failed
/// one, and `imported` for one still owed, which a relay then sends. Its count of
/// attempts goes in the reason, and its error text does not, as it is not a code.
/// `axa_outbox` is left as it was, for a later migration of the service's own to drop.
pub const IMPORT_STATEMENTS: [&str; 3] = [IMPORT_EVENTS, IMPORT_PAYLOADS, IMPORT_ATTEMPTS];

const REBUILD_OFF: &str = "ALTER TABLE axa_outbox_owed DISABLE TRIGGER axa_outbox_owed_guard";
const REBUILD_EMPTY: &str = "DELETE FROM axa_outbox_owed";
/// What `axa_outbox_owe` and `axa_outbox_follow` would have made: an event is owed
/// unless it was ever delivered, refused, or erased, and its latest attempt says the
/// rest. Holds are not kept, so a held event is decided again.
const REBUILD_FILL: &str = "INSERT INTO axa_outbox_owed
        (event_id, id, topic, key, tenant, state, claim, charges, reason, retry_at)
    SELECT e.event_id, e.id, e.topic, e.key, e.tenant,
        CASE WHEN latest.outcome = 'claimed' THEN 'claimed'
             WHEN latest.outcome IN ('failed', 'abandoned') THEN 'failed'
             ELSE 'pending' END,
        CASE WHEN latest.outcome = 'claimed' THEN latest.claim END,
        (SELECT count(*) FROM axa_outbox_attempts charged
         WHERE charged.event_id = e.event_id
           AND charged.outcome IN ('rejected', 'lost', 'failed', 'abandoned')
           AND charged.id > coalesce((
               SELECT max(released.id) FROM axa_outbox_attempts released
               WHERE released.event_id = e.event_id AND released.outcome = 'released'
           ), 0))::integer,
        CASE WHEN latest.outcome IN ('claimed', 'released') THEN NULL ELSE latest.reason END,
        coalesce(latest.retry_at, latest.at, e.created_at)
    FROM axa_outbox_events e
    LEFT JOIN LATERAL (
        SELECT a.outcome, a.claim, a.reason, a.retry_at, a.at FROM axa_outbox_attempts a
        WHERE a.event_id = e.event_id ORDER BY a.id DESC LIMIT 1
    ) latest ON true
    WHERE NOT EXISTS (
        SELECT 1 FROM axa_outbox_attempts ended
        WHERE ended.event_id = e.event_id
          AND ended.outcome IN ('delivered', 'refused', 'erased')
    )";
const REBUILD_ON: &str = "ALTER TABLE axa_outbox_owed ENABLE ALWAYS TRIGGER axa_outbox_owed_guard";

/// The statements that make `axa_outbox_owed` again from the record, for when it no
/// longer matches, as after someone with the schema changed it. Run them in order, in
/// one transaction, as the tables' owner, with every relay stopped. They read the whole
/// record, and touch nothing in it. Holds are not kept, so a held event is decided again.
pub const REBUILD_OWED_STATEMENTS: [&str; 4] =
    [REBUILD_OFF, REBUILD_EMPTY, REBUILD_FILL, REBUILD_ON];

//! Payloads sealed at rest with XChaCha20-Poly1305, behind the `encryption` feature.
//!
//! A sealed payload is a version byte, the key's id, a random 24-byte nonce, and the
//! ciphertext with its tag. The version, the key id, and the event's id are the
//! associated data, so a sealed payload moved to another event does not open.

use std::fmt;

use chacha20poly1305::{
    XChaCha20Poly1305, XNonce,
    aead::{Aead, Generate, KeyInit, Payload},
};
use sha2::{Digest, Sha256};
use uuid::Uuid;
use zeroize::Zeroize;

/// The shortest secret [`Key::new`] accepts, in bytes.
pub const MIN_KEY_LEN: usize = 32;

/// The first byte of every sealed payload, so that the format can change.
const VERSION: u8 = 1;
const NONCE_LEN: usize = 24;
const HEADER_LEN: usize = 2 + NONCE_LEN;

/// Keeps a key made for this from being the same as one made for something else from
/// the same secret.
const CONTEXT: &[u8] = b"axa-transactional-outbox payload key, version 1\0";

/// One key for sealing payloads, with the id a sealed payload names it by. Its `Debug`
/// shows the id and never the key, and its key material is wiped when it is dropped.
#[derive(Clone)]
pub struct Key {
    id: u8,
    cipher: XChaCha20Poly1305,
}

impl fmt::Debug for Key {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Key")
            .field("id", &self.id)
            .finish_non_exhaustive()
    }
}

/// A secret shorter than [`MIN_KEY_LEN`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct KeyTooShort {
    /// The length given, in bytes.
    pub len: usize,
}

impl fmt::Display for KeyTooShort {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "an outbox key needs at least {MIN_KEY_LEN} bytes, and this has {}",
            self.len
        )
    }
}

impl std::error::Error for KeyTooShort {}

impl Key {
    /// A key named `id` from `secret`, which must be at least [`MIN_KEY_LEN`] random
    /// bytes. Give each new secret a new id, so that payloads sealed under the old one
    /// still open while it is kept in [`Keys`].
    ///
    /// # Errors
    ///
    /// [`KeyTooShort`] when `secret` is shorter than [`MIN_KEY_LEN`].
    pub fn new(id: u8, secret: &[u8]) -> Result<Self, KeyTooShort> {
        if secret.len() < MIN_KEY_LEN {
            return Err(KeyTooShort { len: secret.len() });
        }
        // The hasher writes the key straight into one buffer, wiped once the cipher has
        // it. The hasher wipes itself, and the cipher wipes its own copy when dropped.
        let mut derived = chacha20poly1305::Key::default();
        Sha256::new()
            .chain_update(CONTEXT)
            .chain_update(secret)
            .finalize_into(&mut derived);
        let cipher = XChaCha20Poly1305::new(&derived);
        derived.as_mut_slice().zeroize();
        Ok(Self { id, cipher })
    }

    /// The id a sealed payload names this key by.
    #[must_use]
    pub fn id(&self) -> u8 {
        self.id
    }
}

/// The keys a service holds: one it seals with, and older ones it still opens with,
/// so that a key can be replaced without a payload becoming unreadable. Its `Debug`
/// shows the ids and never a key.
#[derive(Clone)]
pub struct Keys {
    current: Key,
    older: Vec<Key>,
}

impl fmt::Debug for Keys {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let older: Vec<u8> = self.older.iter().map(Key::id).collect();
        f.debug_struct("Keys")
            .field("current", &self.current.id)
            .field("older", &older)
            .finish()
    }
}

/// Why a sealed payload did not open.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Unopened {
    /// No key held has the id it names, or its format is newer than this crate.
    NoKey,
    /// It does not open under the key it names, so it was changed.
    Tampered,
}

impl Keys {
    /// Seal with `current`.
    #[must_use]
    pub fn new(current: Key) -> Self {
        Self {
            current,
            older: Vec::new(),
        }
    }

    /// Also open payloads sealed with `key`. A key with the id of one already held
    /// is ignored.
    #[must_use]
    pub fn and_open_with(mut self, key: Key) -> Self {
        if key.id != self.current.id && self.older.iter().all(|held| held.id != key.id) {
            self.older.push(key);
        }
        self
    }

    /// Seal `plain` for the event `event_id`.
    pub(crate) fn seal(&self, event_id: Uuid, plain: &[u8]) -> Result<Vec<u8>, sqlx::Error> {
        let key = &self.current;
        let nonce = XNonce::try_generate().map_err(|error| sqlx::Error::Encode(error.into()))?;
        let aad = associated(key.id, event_id);
        let sealed = key
            .cipher
            .encrypt(
                &nonce,
                Payload {
                    msg: plain,
                    aad: &aad,
                },
            )
            .map_err(|_| sqlx::Error::Encode("the payload could not be sealed".into()))?;
        let mut out = Vec::with_capacity(HEADER_LEN + sealed.len());
        out.push(VERSION);
        out.push(key.id);
        out.extend_from_slice(&nonce);
        out.extend_from_slice(&sealed);
        Ok(out)
    }

    /// Open `sealed`, which was sealed for `event_id`.
    pub(crate) fn open(&self, event_id: Uuid, sealed: &[u8]) -> Result<Vec<u8>, Unopened> {
        if sealed.len() < HEADER_LEN || sealed[0] != VERSION {
            return Err(Unopened::NoKey);
        }
        let id = sealed[1];
        let key = std::iter::once(&self.current)
            .chain(&self.older)
            .find(|key| key.id == id)
            .ok_or(Unopened::NoKey)?;
        let nonce = XNonce::try_from(&sealed[2..HEADER_LEN]).map_err(|_| Unopened::Tampered)?;
        let aad = associated(id, event_id);
        key.cipher
            .decrypt(
                &nonce,
                Payload {
                    msg: &sealed[HEADER_LEN..],
                    aad: &aad,
                },
            )
            .map_err(|_| Unopened::Tampered)
    }
}

/// The associated data: what a sealed payload is bound to.
fn associated(key_id: u8, event_id: Uuid) -> [u8; 18] {
    let mut aad = [0; 18];
    aad[0] = VERSION;
    aad[1] = key_id;
    aad[2..].copy_from_slice(event_id.as_bytes());
    aad
}

#[cfg(test)]
mod tests {
    use super::*;

    fn key(id: u8, byte: u8) -> Key {
        Key::new(id, &[byte; 32]).unwrap()
    }

    #[test]
    fn a_short_secret_is_refused() {
        assert_eq!(Key::new(1, &[7; 31]).unwrap_err(), KeyTooShort { len: 31 });
        assert!(Key::new(1, &[7; 32]).is_ok());
        assert!(Key::new(1, &[7; 64]).is_ok());
    }

    #[test]
    fn a_sealed_payload_opens_only_for_its_event_and_with_its_key() {
        let keys = Keys::new(key(1, 7));
        let event = Uuid::new_v4();
        let sealed = keys.seal(event, b"{\"name\":\"Ada\"}").unwrap();
        assert!(!sealed.windows(3).any(|part| part == b"Ada"));
        assert_eq!(keys.open(event, &sealed).unwrap(), b"{\"name\":\"Ada\"}");
        // Moved to another event.
        assert_eq!(keys.open(Uuid::new_v4(), &sealed), Err(Unopened::Tampered));
        // Changed by one bit.
        let mut changed = sealed.clone();
        *changed.last_mut().unwrap() ^= 1;
        assert_eq!(keys.open(event, &changed), Err(Unopened::Tampered));
        // A different secret under the same id.
        assert_eq!(
            Keys::new(key(1, 8)).open(event, &sealed),
            Err(Unopened::Tampered)
        );
        // An id no key has.
        assert_eq!(
            Keys::new(key(2, 7)).open(event, &sealed),
            Err(Unopened::NoKey)
        );
    }

    #[test]
    fn each_seal_has_its_own_nonce() {
        let keys = Keys::new(key(1, 7));
        let event = Uuid::new_v4();
        assert_ne!(
            keys.seal(event, b"x").unwrap(),
            keys.seal(event, b"x").unwrap()
        );
    }

    #[test]
    fn an_older_key_still_opens_what_it_sealed() {
        let event = Uuid::new_v4();
        let old = Keys::new(key(1, 7));
        let sealed = old.seal(event, b"kept").unwrap();
        let rotated = Keys::new(key(2, 9)).and_open_with(key(1, 7));
        assert_eq!(rotated.open(event, &sealed).unwrap(), b"kept");
        assert_eq!(rotated.seal(event, b"new").unwrap()[1], 2);
    }

    #[test]
    fn debug_text_leaves_out_the_key() {
        let keys = Keys::new(Key::new(3, b"a service secret of thirty-two b").unwrap());
        for text in [format!("{keys:?}"), format!("{:?}", keys.current)] {
            assert!(text.contains('3'), "{text}");
            assert!(!text.contains("secret"), "{text}");
            assert!(!text.contains("cipher"), "{text}");
        }
    }
}

//! Web sessions for Axum services, over [`axum_session`], with safe defaults.
//!
//! `axum_session` does the work. This crate decides what a service gets if it
//! says nothing, because a session that fails open gives no sign of it:
//!
//! | Setting | `axum_session` alone | [`SessionOptions::production`] |
//! |---|---|---|
//! | Cookie signing | Off until a key is set | Required |
//! | Data in the database | Plain text until a key is set | Encrypted, key required |
//! | `Secure` cookie | Off | On |
//! | `SameSite` | `Lax` | `Lax` |
//! | Session lifetime | 6 hours | 8 hours |
//! | Cookie lifetime | 100 days | 7 days |
//! | Ended a fixed time after sign-in, however busy | No | Yes, 7 days |
//! | Bound to the client's IP | Yes, when signed | No: phones change networks |
//! | Stored for an anonymous visitor | Yes | No, until [`sign_in`] |
//!
//! Unsigned cookies are possible only through [`SessionOptions::development`].
//!
//! ```
//! use axa_web_session::{Session, SessionNullPool, SessionOptions, layer, memory_store};
//! use axum::{Router, routing::get};
//!
//! async fn sign_in(session: Session<SessionNullPool>) -> &'static str {
//!     axa_web_session::sign_in(&session);
//!     session.set("user", "ada");
//!     "signed in"
//! }
//!
//! # async fn run() -> Result<(), axa_web_session::Error> {
//! let options = SessionOptions::development();
//! let store = memory_store(&options).await?;
//! let app: Router = Router::new().route("/", get(sign_in)).layer(layer(store, &options));
//! # Ok(())
//! # }
//! ```
//!
//! # Keys
//!
//! Give a production service two different keys of at least [`MIN_KEY_BYTES`]
//! bytes, from a secret store. They must stay the same across restarts and
//! replicas: a new signing key signs everyone out.
//!
//! # Signing in
//!
//! **Nothing is stored for a visitor until a service says so.** A visitor keeps no
//! cookie, as they are sent only a deletion, and has no stored session, so bots and
//! health probes cost no row, and nobody is tracked before they have agreed to
//! anything. So `session.set` on an
//! anonymous visitor is forgotten at the end of the request.
//!
//! - Call [`sign_in`] when someone signs in. It starts storing the session and
//!   gives it a new identifier, so one planted beforehand is worthless.
//! - Call [`sign_out`] when someone signs out.
//! - A session in use stays alive past its [`SessionOptions::lifetime`], as each
//!   request extends it. [`layer`] ends one at [`SessionOptions::sign_in_lifetime`]
//!   after [`sign_in`], however busy, so a stolen cookie stops working in time. The
//!   next request after that is an anonymous visitor's.
//! - [`Session::set_store`] stores a session for any other reason, such as a
//!   basket. [`SessionOptions::store_every_visitor`] stores them all.
//!
//! # Forms
//!
//! A browser sends the session cookie with a form posted from another site unless
//! `SameSite` stops it, and `Lax` does not cover every case. So put
//! [`csrf_token`] in each form, and check it with [`csrf_verify`] before acting on
//! the post. Asking for a token stores the session, because the token lives there.
//!
//! Serve the application with connection information, as `axa`'s `server` module
//! does: `into_make_service_with_connect_info`.

use std::{
    fmt,
    marker::PhantomData,
    task::{Context, Poll},
    time::{Duration, SystemTime, UNIX_EPOCH},
};

use axum_session::DatabasePool;
pub use axum_session::{
    Key, ReadOnlySession, SameSite, Session, SessionConfig, SessionError, SessionLayer,
    SessionMode, SessionNullPool, SessionStore,
};
#[cfg(feature = "postgres")]
pub use axum_session_sqlx::{SessionPgPool, SessionPgSession, SessionPgSessionStore};
use tower_layer::{Layer, Stack};
use tower_service::Service;
use uuid::Uuid;

/// The fewest bytes a key may have. `axum_session` panics on a shorter one, so
/// this crate refuses it first.
pub const MIN_KEY_BYTES: usize = 64;

/// How long a session lasts without being used, by default.
pub const DEFAULT_LIFETIME: Duration = Duration::from_hours(8);

/// How long a long-term session and its cookie last, by default.
pub const DEFAULT_MAX_LIFETIME: Duration = Duration::from_hours(24 * 7);

/// How long a session lasts after [`sign_in`], however busy, by default.
pub const DEFAULT_SIGN_IN_LIFETIME: Duration = DEFAULT_MAX_LIFETIME;

/// A session failure.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// A key is too short.
    #[error("the session {name} key has {length} bytes and needs at least {MIN_KEY_BYTES}")]
    KeyTooShort {
        /// Which key.
        name: &'static str,
        /// How many bytes it has.
        length: usize,
    },
    /// The signing and database keys are the same.
    #[error("the session signing and database keys must differ")]
    SameKey,
    /// A lifetime that does not fit.
    #[error("the session lifetime is too long")]
    LifetimeTooLong,
    /// The store failed.
    #[error(transparent)]
    Store(#[from] SessionError),
}

/// How a service's sessions behave.
#[derive(Clone)]
pub struct SessionOptions {
    cookie_name: String,
    table_name: String,
    lifetime: Duration,
    max_lifetime: Duration,
    sign_in_lifetime: Duration,
    secure: bool,
    store_every_visitor: bool,
    create_table: bool,
    signing_key: Option<Key>,
    database_key: Option<Key>,
}

impl fmt::Debug for SessionOptions {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Whether the keys are there, and never what they are.
        f.debug_struct("SessionOptions")
            .field("cookie_name", &self.cookie_name)
            .field("table_name", &self.table_name)
            .field("lifetime", &self.lifetime)
            .field("max_lifetime", &self.max_lifetime)
            .field("sign_in_lifetime", &self.sign_in_lifetime)
            .field("secure", &self.secure)
            .field("store_every_visitor", &self.store_every_visitor)
            .field("create_table", &self.create_table)
            .field("signed", &self.signing_key.is_some())
            .field("encrypted", &self.database_key.is_some())
            .finish()
    }
}

fn key(name: &'static str, bytes: &[u8]) -> Result<Key, Error> {
    if bytes.len() < MIN_KEY_BYTES {
        return Err(Error::KeyTooShort {
            name,
            length: bytes.len(),
        });
    }
    Ok(Key::from(bytes))
}

impl SessionOptions {
    /// Signed cookies over HTTPS, with session data encrypted in the database.
    ///
    /// # Errors
    ///
    /// Fails when a key is under [`MIN_KEY_BYTES`], or the two are the same.
    pub fn production(signing_key: &[u8], database_key: &[u8]) -> Result<Self, Error> {
        let signing = key("signing", signing_key)?;
        let database = key("database", database_key)?;
        if signing_key == database_key {
            return Err(Error::SameKey);
        }
        Ok(Self {
            secure: true,
            signing_key: Some(signing),
            database_key: Some(database),
            ..Self::development()
        })
    }

    /// Unsigned cookies over plain HTTP, for a developer's machine and for tests.
    /// Anyone can forge these, so it does not belong in production.
    #[must_use]
    pub fn development() -> Self {
        Self {
            cookie_name: "session".to_string(),
            table_name: "sessions".to_string(),
            lifetime: DEFAULT_LIFETIME,
            max_lifetime: DEFAULT_MAX_LIFETIME,
            sign_in_lifetime: DEFAULT_SIGN_IN_LIFETIME,
            secure: false,
            store_every_visitor: false,
            create_table: true,
            signing_key: None,
            database_key: None,
        }
    }

    /// Name the cookie.
    #[must_use]
    pub fn cookie_name(mut self, name: impl Into<String>) -> Self {
        self.cookie_name = name.into();
        self
    }

    /// Name the Postgres table.
    #[must_use]
    pub fn table_name(mut self, name: impl Into<String>) -> Self {
        self.table_name = name.into();
        self
    }

    /// How long a session lasts without being used.
    #[must_use]
    pub fn lifetime(mut self, lifetime: Duration) -> Self {
        self.lifetime = lifetime;
        self
    }

    /// How long a long-term session and its cookie last.
    #[must_use]
    pub fn max_lifetime(mut self, max_lifetime: Duration) -> Self {
        self.max_lifetime = max_lifetime;
        self
    }

    /// How long a session lasts after [`sign_in`], however busy. [`layer`] ends it
    /// then, and the visitor signs in again.
    #[must_use]
    pub fn sign_in_lifetime(mut self, sign_in_lifetime: Duration) -> Self {
        self.sign_in_lifetime = sign_in_lifetime;
        self
    }

    /// Store a session for every visitor, including one who has agreed to
    /// nothing. Each new visitor then costs memory, and a database row, for as
    /// long as the session lasts, so mount the layer only on routes that need it.
    #[must_use]
    pub fn store_every_visitor(mut self) -> Self {
        self.store_every_visitor = true;
        self
    }

    /// Whether starting a store creates its table, if it is not there. It does
    /// unless this says otherwise. Say `false` when the database role may not create
    /// tables, or when every change to the schema goes through the service's own
    /// migrations: make the table there, as [`postgres_table_sql`] gives it.
    #[must_use]
    pub fn create_table(mut self, create: bool) -> Self {
        self.create_table = create;
        self
    }

    /// The `axum_session` settings these options describe.
    ///
    /// # Errors
    ///
    /// Fails when a lifetime does not fit `axum_session`'s duration type.
    pub fn config(&self) -> Result<SessionConfig, Error> {
        let duration =
            |value: Duration| time::Duration::try_from(value).map_err(|_| Error::LifetimeTooLong);
        let max_lifetime = duration(self.max_lifetime)?;
        let mut config = SessionConfig::default()
            .with_session_name(self.cookie_name.clone())
            .with_table_name(self.table_name.clone())
            // `axum_session` 0.23 no longer makes the table unless asked, and this
            // crate's stores do unless a service says otherwise.
            .with_database_initiation(self.create_table)
            .with_lifetime(duration(self.lifetime)?)
            .with_max_lifetime(max_lifetime)
            .with_max_age(Some(max_lifetime))
            .with_secure(self.secure)
            .with_http_only(true)
            .with_cookie_same_site(SameSite::Lax)
            .with_hashed_ip(false);
        if !self.store_every_visitor {
            config = config.with_mode(SessionMode::OptIn);
        }
        if let Some(key) = &self.signing_key {
            config = config.with_key(key.clone());
        }
        if let Some(key) = &self.database_key {
            config = config.with_database_key(key.clone());
        }
        Ok(config)
    }
}

/// Where a form's token lives in the session.
const CSRF_KEY: &str = "axa.csrf";

/// Where the time of sign-in lives in the session, in milliseconds since 1970.
const SIGNED_IN_KEY: &str = "axa.signed_in_at";

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |since| {
            u64::try_from(since.as_millis()).unwrap_or(u64::MAX)
        })
}

/// Start storing `session`, and give it a new identifier, so one planted before
/// sign-in is worthless. Any form token from before is dropped too.
pub fn sign_in<T>(session: &Session<T>)
where
    T: DatabasePool + Clone + fmt::Debug + Sync + Send + 'static,
{
    session.set_store(true);
    session.remove(CSRF_KEY);
    session.set(SIGNED_IN_KEY, now_ms());
    session.renew();
}

/// End `session`, here and in the store.
pub fn sign_out<T>(session: &Session<T>)
where
    T: DatabasePool + Clone + fmt::Debug + Sync + Send + 'static,
{
    session.destroy();
}

/// The session's form token, made if it has none. This stores the session.
#[must_use]
pub fn csrf_token<T>(session: &Session<T>) -> String
where
    T: DatabasePool + Clone + fmt::Debug + Sync + Send + 'static,
{
    if let Some(token) = session.get::<String>(CSRF_KEY) {
        return token;
    }
    let token = format!("{}{}", Uuid::new_v4().simple(), Uuid::new_v4().simple());
    session.set_store(true);
    session.set(CSRF_KEY, &token);
    token
}

/// Whether `submitted` is the session's form token. Refuses a session with none.
#[must_use]
pub fn csrf_verify<T>(session: &Session<T>, submitted: &str) -> bool
where
    T: DatabasePool + Clone + fmt::Debug + Sync + Send + 'static,
{
    session
        .get::<String>(CSRF_KEY)
        .is_some_and(|token| same_text(&token, submitted))
}

/// Compare without stopping at the first difference, so timing shows nothing.
fn same_text(a: &str, b: &str) -> bool {
    a.len() == b.len()
        && a.bytes()
            .zip(b.bytes())
            .fold(0_u8, |seen, (x, y)| seen | (x ^ y))
            == 0
}

/// A store over `client`.
///
/// # Errors
///
/// Fails when the options do not fit, or the store cannot start.
pub async fn store<T>(client: Option<T>, options: &SessionOptions) -> Result<SessionStore<T>, Error>
where
    T: DatabasePool + Clone + fmt::Debug + Sync + Send + 'static,
{
    Ok(SessionStore::new(client, options.config()?).await?)
}

/// A store held in this process. Replicas do not share it, and a restart loses it.
///
/// # Errors
///
/// Fails when the options do not fit.
pub async fn memory_store(
    options: &SessionOptions,
) -> Result<SessionStore<SessionNullPool>, Error> {
    store(None, options).await
}

/// A store in Postgres, creating its table if needed, unless
/// [`SessionOptions::create_table`] says not to.
///
/// # Errors
///
/// Fails when the options do not fit, or the table cannot be created.
#[cfg(feature = "postgres")]
pub async fn postgres_store(
    pool: sqlx::PgPool,
    options: &SessionOptions,
) -> Result<SessionPgSessionStore, Error> {
    store(Some(pool.into()), options).await
}

/// The statement that makes the Postgres table named `table_name`, as the store
/// makes it, for a service's own migration when [`SessionOptions::create_table`] is
/// `false`. It is the table of `axum_session_sqlx` 0.13. The name is written as
/// given, unquoted, so it must be a plain identifier the service chose.
#[cfg(feature = "postgres")]
#[must_use]
pub fn postgres_table_sql(table_name: &str) -> String {
    format!(
        "CREATE TABLE IF NOT EXISTS {table_name} (\n    \"id\" VARCHAR(128) NOT NULL PRIMARY KEY,\n    \"expires\" BIGINT NULL,\n    \"session\" TEXT NOT NULL\n)"
    )
}

/// The layer that gives handlers a [`Session`], ending each at the options'
/// [`SessionOptions::sign_in_lifetime`] after [`sign_in`].
#[must_use]
pub fn layer<T>(
    store: SessionStore<T>,
    options: &SessionOptions,
) -> Stack<SignInDeadline<T>, SessionLayer<T>>
where
    T: DatabasePool + Clone + fmt::Debug + Sync + Send + 'static,
{
    let deadline = SignInDeadline {
        lifetime_ms: u64::try_from(options.sign_in_lifetime.as_millis()).unwrap_or(u64::MAX),
        pool: PhantomData,
    };
    Stack::new(deadline, SessionLayer::new(store))
}

/// The part of [`layer`] that ends a session at its time after sign-in. It runs
/// inside the session layer, before the handler.
pub struct SignInDeadline<T> {
    lifetime_ms: u64,
    pool: PhantomData<fn() -> T>,
}

impl<T> Clone for SignInDeadline<T> {
    fn clone(&self) -> Self {
        Self {
            lifetime_ms: self.lifetime_ms,
            pool: PhantomData,
        }
    }
}

impl<T> fmt::Debug for SignInDeadline<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("SignInDeadline")
            .field("lifetime_ms", &self.lifetime_ms)
            .finish()
    }
}

impl<S, T> Layer<S> for SignInDeadline<T> {
    type Service = SignInDeadlineService<S, T>;

    fn layer(&self, inner: S) -> Self::Service {
        SignInDeadlineService {
            inner,
            deadline: self.clone(),
        }
    }
}

/// The service [`SignInDeadline`] makes.
pub struct SignInDeadlineService<S, T> {
    inner: S,
    deadline: SignInDeadline<T>,
}

impl<S: Clone, T> Clone for SignInDeadlineService<S, T> {
    fn clone(&self) -> Self {
        Self {
            inner: self.inner.clone(),
            deadline: self.deadline.clone(),
        }
    }
}

impl<S, T> fmt::Debug for SignInDeadlineService<S, T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("SignInDeadlineService")
            .field("deadline", &self.deadline)
            .finish_non_exhaustive()
    }
}

impl<S, T, B> Service<http::Request<B>> for SignInDeadlineService<S, T>
where
    S: Service<http::Request<B>>,
    T: DatabasePool + Clone + fmt::Debug + Sync + Send + 'static,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = S::Future;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, request: http::Request<B>) -> Self::Future {
        if let Some(session) = request.extensions().get::<Session<T>>()
            && let Some(at) = session.get::<u64>(SIGNED_IN_KEY)
            && now_ms().saturating_sub(at) >= self.deadline.lifetime_ms
        {
            session.clear();
            session.destroy();
        }
        self.inner.call(request)
    }
}

#[cfg(test)]
mod tests {
    use super::same_text;

    #[test]
    fn only_the_same_text_is_the_same() {
        assert!(same_text("abc", "abc"));
        assert!(!same_text("abc", "abd"));
        assert!(!same_text("abc", "ab"));
        assert!(!same_text("", "a"));
    }
}

//! Webhook signing and verifying, to the [Standard Webhooks] scheme.
//!
//! A sender signs `{id}.{timestamp}.{body}` and sends three headers: `webhook-id`,
//! `webhook-timestamp` in Unix seconds, and `webhook-signature`, which lists one
//! signature for each key it signs with, separated by spaces: `v1,` and base64 for
//! HMAC-SHA256, and `v1a,` and base64 for Ed25519. While a key rotates, the sender signs
//! with the old key and the new, and a receiver that knows either accepts it.
//!
//! ```
//! use axa_webhooks::{Signer, SigningKey, Verifier};
//!
//! let key: SigningKey = "whsec_MfKQ9r8GKYqrTwjUPD8ILPZIo2LaLaSw".parse().unwrap();
//! let signer = Signer::new(key.clone());
//! let headers = signer.headers("msg_1", 1_700_000_000, br#"{"ok":true}"#).unwrap();
//!
//! let verifier = Verifier::new(key.verifying_key());
//! let delivery = verifier
//!     .verify_at(&headers, br#"{"ok":true}"#, 1_700_000_010)
//!     .unwrap();
//! assert_eq!(delivery.id, "msg_1");
//! assert!(verifier.verify_at(&headers, b"{}", 1_700_000_010).is_err());
//! ```
//!
//! A receiver takes [`Verified`] as an extractor, with the [`Verifier`] in its state,
//! and the handler runs only for a delivery signed by a key it knows, inside the
//! timestamp window. The window stops an old delivery being sent again later, but not
//! within it: a receiver that must act once per delivery keeps the ids it has seen for
//! as long as the window, as [`Delivery::id`] is the same on every retry.
//!
//! [Standard Webhooks]: https://www.standardwebhooks.com/

use std::{
    fmt,
    str::FromStr,
    time::{Duration, SystemTime, UNIX_EPOCH},
};

use axa_problem::Problem;
use axum::{
    body::Bytes,
    extract::{FromRef, FromRequest, Request},
    http::{HeaderMap, HeaderValue, StatusCode},
    response::{IntoResponse, Response},
};
use base64::{Engine, engine::general_purpose::STANDARD};
use ed25519_dalek::Signer as _;
use hmac::{Hmac, KeyInit, Mac};
use sha2::Sha256;

/// The header naming the delivery, the same on every retry.
pub const ID_HEADER: &str = "webhook-id";

/// The header holding when the delivery was signed, in Unix seconds.
pub const TIMESTAMP_HEADER: &str = "webhook-timestamp";

/// The header listing the signatures.
pub const SIGNATURE_HEADER: &str = "webhook-signature";

/// How far a delivery's timestamp may be from now, either way, unless a verifier says
/// otherwise: five minutes, as Standard Webhooks suggests.
pub const DEFAULT_TOLERANCE: Duration = Duration::from_mins(5);

/// The most signatures a delivery may list, so that one cannot make a receiver check
/// any number.
pub const MAX_SIGNATURES: usize = 16;

/// The longest id, in bytes.
pub const MAX_ID_BYTES: usize = 256;

/// The shortest and longest HMAC secret Standard Webhooks allows, in bytes.
const HMAC_KEY_BYTES: std::ops::RangeInclusive<usize> = 24..=64;

const HMAC_PREFIX: &str = "whsec_";
const SECRET_KEY_PREFIX: &str = "whsk_";
const PUBLIC_KEY_PREFIX: &str = "whpk_";

/// Why a key did not parse. It never quotes the key.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum KeyError {
    /// It does not start with a prefix this kind of key may have.
    Prefix,
    /// What follows the prefix is not base64.
    Base64,
    /// It is not a length this kind of key has.
    Length,
    /// It is not an Ed25519 key, or a secret key's public half does not match it.
    Ed25519,
}

impl fmt::Display for KeyError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Prefix => "a webhook key starts with whsec_, whsk_, or whpk_",
            Self::Base64 => "a webhook key is base64 after its prefix",
            Self::Length => {
                "a whsec_ key holds 24 to 64 bytes, a whsk_ key 32 or 64, and a whpk_ key 32"
            }
            Self::Ed25519 => "a whsk_ or whpk_ key is not a valid Ed25519 key",
        })
    }
}

impl std::error::Error for KeyError {}

fn decode(text: &str) -> Result<Vec<u8>, KeyError> {
    STANDARD.decode(text.trim()).map_err(|_| KeyError::Base64)
}

fn hmac_key(text: &str) -> Result<Vec<u8>, KeyError> {
    let bytes = decode(text)?;
    if HMAC_KEY_BYTES.contains(&bytes.len()) {
        Ok(bytes)
    } else {
        Err(KeyError::Length)
    }
}

/// A key a sender signs with: an HMAC secret, `whsec_` and base64, or an Ed25519
/// secret key, `whsk_` and the base64 of its 32-byte seed, or of the seed and the public
/// key, 64 bytes.
#[derive(Clone)]
pub struct SigningKey(Signing);

#[derive(Clone)]
enum Signing {
    Hmac(Vec<u8>),
    Ed25519(ed25519_dalek::SigningKey),
}

impl fmt::Debug for SigningKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self.0 {
            Signing::Hmac(_) => "SigningKey(hmac)",
            Signing::Ed25519(_) => "SigningKey(ed25519)",
        })
    }
}

impl FromStr for SigningKey {
    type Err = KeyError;

    fn from_str(text: &str) -> Result<Self, KeyError> {
        let text = text.trim();
        if let Some(rest) = text.strip_prefix(HMAC_PREFIX) {
            return Ok(Self(Signing::Hmac(hmac_key(rest)?)));
        }
        let rest = text
            .strip_prefix(SECRET_KEY_PREFIX)
            .ok_or(KeyError::Prefix)?;
        let bytes = decode(rest)?;
        let seed: [u8; 32] = bytes
            .get(..32)
            .filter(|_| matches!(bytes.len(), 32 | 64))
            .and_then(|seed| seed.try_into().ok())
            .ok_or(KeyError::Length)?;
        let key = ed25519_dalek::SigningKey::from_bytes(&seed);
        if bytes.len() == 64 && bytes[32..] != key.verifying_key().to_bytes() {
            return Err(KeyError::Ed25519);
        }
        Ok(Self(Signing::Ed25519(key)))
    }
}

impl SigningKey {
    /// The key a receiver verifies with: the same secret for HMAC, and the public key
    /// for Ed25519.
    #[must_use]
    pub fn verifying_key(&self) -> VerifyingKey {
        VerifyingKey(match &self.0 {
            Signing::Hmac(secret) => Verifying::Hmac(secret.clone()),
            Signing::Ed25519(key) => Verifying::Ed25519(key.verifying_key()),
        })
    }

    /// The Ed25519 public key as `whpk_` and base64, to hand to receivers, or `None`
    /// for an HMAC secret, which has no public half.
    #[must_use]
    pub fn public_key(&self) -> Option<String> {
        match &self.0 {
            Signing::Hmac(_) => None,
            Signing::Ed25519(key) => Some(format!(
                "{PUBLIC_KEY_PREFIX}{}",
                STANDARD.encode(key.verifying_key().to_bytes())
            )),
        }
    }

    /// This key's signature of `content`, as it is listed in the header.
    fn sign(&self, content: &[u8]) -> String {
        match &self.0 {
            Signing::Hmac(secret) => format!("v1,{}", STANDARD.encode(hmac(secret, content))),
            Signing::Ed25519(key) => {
                format!("v1a,{}", STANDARD.encode(key.sign(content).to_bytes()))
            }
        }
    }
}

/// A key a receiver verifies with: an HMAC secret, `whsec_` and base64, or an Ed25519
/// public key, `whpk_` and base64.
#[derive(Clone)]
pub struct VerifyingKey(Verifying);

#[derive(Clone)]
enum Verifying {
    Hmac(Vec<u8>),
    Ed25519(ed25519_dalek::VerifyingKey),
}

impl fmt::Debug for VerifyingKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self.0 {
            Verifying::Hmac(_) => "VerifyingKey(hmac)",
            Verifying::Ed25519(_) => "VerifyingKey(ed25519)",
        })
    }
}

impl FromStr for VerifyingKey {
    type Err = KeyError;

    fn from_str(text: &str) -> Result<Self, KeyError> {
        let text = text.trim();
        if let Some(rest) = text.strip_prefix(HMAC_PREFIX) {
            return Ok(Self(Verifying::Hmac(hmac_key(rest)?)));
        }
        let rest = text
            .strip_prefix(PUBLIC_KEY_PREFIX)
            .ok_or(KeyError::Prefix)?;
        let bytes: [u8; 32] = decode(rest)?.try_into().map_err(|_| KeyError::Length)?;
        let key = ed25519_dalek::VerifyingKey::from_bytes(&bytes).map_err(|_| KeyError::Ed25519)?;
        Ok(Self(Verifying::Ed25519(key)))
    }
}

impl VerifyingKey {
    /// Whether `signature`, of the version it names, is this key's of `content`. An
    /// HMAC is compared in constant time.
    fn verifies(&self, version: &str, signature: &[u8], content: &[u8]) -> bool {
        match (&self.0, version) {
            (Verifying::Hmac(secret), "v1") => Hmac::<Sha256>::new_from_slice(secret)
                .is_ok_and(|mac| mac.chain_update(content).verify_slice(signature).is_ok()),
            (Verifying::Ed25519(key), "v1a") => ed25519_dalek::Signature::from_slice(signature)
                .is_ok_and(|signature| key.verify_strict(content, &signature).is_ok()),
            _ => false,
        }
    }
}

fn hmac(secret: &[u8], content: &[u8]) -> Vec<u8> {
    // Every key length is valid for HMAC, so this cannot fail.
    let mac = Hmac::<Sha256>::new_from_slice(secret).expect("HMAC takes a key of any length");
    mac.chain_update(content).finalize().into_bytes().to_vec()
}

/// What is signed: `{id}.{timestamp}.{body}`.
fn content(id: &str, timestamp: u64, body: &[u8]) -> Vec<u8> {
    let mut content = format!("{id}.{timestamp}.").into_bytes();
    content.extend_from_slice(body);
    content
}

/// Whether `id` may name a delivery: 1 to 256 bytes of visible ASCII.
fn is_id(id: &str) -> bool {
    (1..=MAX_ID_BYTES).contains(&id.len()) && id.bytes().all(|byte| byte.is_ascii_graphic())
}

/// Seconds since the Unix epoch.
fn now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |since| since.as_secs())
}

/// Why a delivery could not be signed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum SignError {
    /// The id is not 1 to 256 bytes of visible ASCII.
    InvalidId,
}

impl fmt::Display for SignError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("a webhook id is 1 to 256 bytes of visible ASCII")
    }
}

impl std::error::Error for SignError {}

/// Signs deliveries with one key or more.
#[derive(Debug, Clone)]
pub struct Signer {
    keys: Vec<SigningKey>,
}

impl Signer {
    /// A signer with `key`.
    #[must_use]
    pub fn new(key: SigningKey) -> Self {
        Self { keys: vec![key] }
    }

    /// Sign with `key` as well, as while a key rotates.
    #[must_use]
    pub fn and(mut self, key: SigningKey) -> Self {
        self.keys.push(key);
        self
    }

    /// The `webhook-signature` value for the delivery `id` of `body` at `timestamp`.
    ///
    /// # Errors
    ///
    /// Fails when `id` is not 1 to 256 bytes of visible ASCII.
    pub fn signature(&self, id: &str, timestamp: u64, body: &[u8]) -> Result<String, SignError> {
        if !is_id(id) {
            return Err(SignError::InvalidId);
        }
        let content = content(id, timestamp, body);
        let signatures: Vec<String> = self.keys.iter().map(|key| key.sign(&content)).collect();
        Ok(signatures.join(" "))
    }

    /// The three headers for the delivery `id` of `body` at `timestamp`.
    ///
    /// # Errors
    ///
    /// As [`Signer::signature`].
    pub fn headers(&self, id: &str, timestamp: u64, body: &[u8]) -> Result<HeaderMap, SignError> {
        let signature = self.signature(id, timestamp, body)?;
        let value = |text: &str| HeaderValue::from_str(text).map_err(|_| SignError::InvalidId);
        let mut headers = HeaderMap::new();
        headers.insert(ID_HEADER, value(id)?);
        headers.insert(TIMESTAMP_HEADER, HeaderValue::from(timestamp));
        headers.insert(SIGNATURE_HEADER, value(&signature)?);
        Ok(headers)
    }

    /// [`Signer::headers`] at this moment.
    ///
    /// # Errors
    ///
    /// As [`Signer::signature`].
    pub fn headers_now(&self, id: &str, body: &[u8]) -> Result<HeaderMap, SignError> {
        self.headers(id, now(), body)
    }
}

/// A delivery that verified.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Delivery {
    /// Its id, the same on every retry of it.
    pub id: String,
    /// When it was signed, in Unix seconds.
    pub timestamp: u64,
}

/// Why a delivery was refused. As a response it is a problem: `400`, code
/// `webhook_headers_invalid`, for a header that is missing or malformed, and `401` for
/// the rest, with a `detail` that quotes nothing sent.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum Refusal {
    /// A header is missing.
    MissingHeader(&'static str),
    /// A header is not what Standard Webhooks says it is.
    MalformedHeader(&'static str),
    /// The timestamp is further from now than the verifier's tolerance. Code
    /// `webhook_timestamp_out_of_range`.
    OutOfWindow,
    /// No signature listed is one of the verifier's keys' for this delivery. Code
    /// `webhook_signature_invalid`.
    NoValidSignature,
    /// The verifier has no key, as when the service set none, so nothing can verify.
    /// A `500`, code `webhook_verifier_missing`, as the fault is the service's.
    NoKey,
}

impl fmt::Display for Refusal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MissingHeader(name) => write!(f, "the {name} header is missing"),
            Self::MalformedHeader(name) => write!(f, "the {name} header is malformed"),
            Self::OutOfWindow => f.write_str("the webhook timestamp is too far from now"),
            Self::NoValidSignature => f.write_str("no webhook signature is valid"),
            Self::NoKey => f.write_str("no webhook verifying key is set"),
        }
    }
}

impl std::error::Error for Refusal {}

impl Refusal {
    /// The status it answers with.
    #[must_use]
    pub fn status(&self) -> StatusCode {
        match self {
            Self::MissingHeader(_) | Self::MalformedHeader(_) => StatusCode::BAD_REQUEST,
            Self::OutOfWindow | Self::NoValidSignature => StatusCode::UNAUTHORIZED,
            Self::NoKey => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }

    /// The problem's `code`.
    #[must_use]
    pub fn code(&self) -> &'static str {
        match self {
            Self::MissingHeader(_) | Self::MalformedHeader(_) => "webhook_headers_invalid",
            Self::OutOfWindow => "webhook_timestamp_out_of_range",
            Self::NoValidSignature => "webhook_signature_invalid",
            Self::NoKey => "webhook_verifier_missing",
        }
    }
}

impl IntoResponse for Refusal {
    fn into_response(self) -> Response {
        Problem::new(self.status())
            .with_detail(self.to_string())
            .with_extension("code", self.code().into())
            .into_response()
    }
}

/// Verifies deliveries against one key or more.
#[derive(Debug, Clone)]
pub struct Verifier {
    keys: Vec<VerifyingKey>,
    tolerance: Duration,
}

impl Verifier {
    /// A verifier with `key`, and the [`DEFAULT_TOLERANCE`].
    #[must_use]
    pub fn new(key: VerifyingKey) -> Self {
        Self {
            keys: vec![key],
            tolerance: DEFAULT_TOLERANCE,
        }
    }

    /// A verifier with no key, which refuses every delivery with [`Refusal::NoKey`]: what
    /// a state hands [`Verified`] when the service set no verifier, so that a missing key
    /// fails closed. [`Verifier::and`] adds a key to it.
    #[must_use]
    pub fn without_keys() -> Self {
        Self {
            keys: Vec::new(),
            tolerance: DEFAULT_TOLERANCE,
        }
    }

    /// Whether it has a key, and so can verify anything.
    #[must_use]
    pub fn has_keys(&self) -> bool {
        !self.keys.is_empty()
    }

    /// Accept a signature by `key` as well, as while a key rotates.
    #[must_use]
    pub fn and(mut self, key: VerifyingKey) -> Self {
        self.keys.push(key);
        self
    }

    /// How far a timestamp may be from now, either way.
    #[must_use]
    pub fn tolerance(mut self, tolerance: Duration) -> Self {
        self.tolerance = tolerance;
        self
    }

    /// Verify the delivery in `headers` of `body`, now.
    ///
    /// # Errors
    ///
    /// As [`Verifier::verify_at`].
    pub fn verify(&self, headers: &HeaderMap, body: &[u8]) -> Result<Delivery, Refusal> {
        self.verify_at(headers, body, now())
    }

    /// Verify the delivery in `headers` of `body`, as at `now`, in Unix seconds.
    ///
    /// # Errors
    ///
    /// Refuses every delivery when it has no key. Otherwise refuses a missing or
    /// malformed header, a timestamp further from `now` than the
    /// tolerance, and a delivery where no signature listed, of up to
    /// [`MAX_SIGNATURES`], is one of this verifier's keys'. A signature of a version it
    /// does not know is passed over, as Standard Webhooks says.
    pub fn verify_at(
        &self,
        headers: &HeaderMap,
        body: &[u8],
        now: u64,
    ) -> Result<Delivery, Refusal> {
        if self.keys.is_empty() {
            return Err(Refusal::NoKey);
        }
        let header = |name: &'static str| {
            headers
                .get(name)
                .ok_or(Refusal::MissingHeader(name))?
                .to_str()
                .map_err(|_| Refusal::MalformedHeader(name))
        };
        let id = header(ID_HEADER)?;
        if !is_id(id) {
            return Err(Refusal::MalformedHeader(ID_HEADER));
        }
        let timestamp = header(TIMESTAMP_HEADER)?;
        let timestamp: u64 = timestamp
            .bytes()
            .all(|byte| byte.is_ascii_digit())
            .then(|| timestamp.parse().ok())
            .flatten()
            .ok_or(Refusal::MalformedHeader(TIMESTAMP_HEADER))?;
        if timestamp.abs_diff(now) > self.tolerance.as_secs() {
            return Err(Refusal::OutOfWindow);
        }
        let listed: Vec<&str> = header(SIGNATURE_HEADER)?.split_ascii_whitespace().collect();
        if listed.is_empty() || listed.len() > MAX_SIGNATURES {
            return Err(Refusal::MalformedHeader(SIGNATURE_HEADER));
        }
        let content = content(id, timestamp, body);
        let verified = listed.iter().any(|entry| {
            let Some((version, encoded)) = entry.split_once(',') else {
                return false;
            };
            let Ok(signature) = STANDARD.decode(encoded) else {
                return false;
            };
            self.keys
                .iter()
                .any(|key| key.verifies(version, &signature, &content))
        });
        if !verified {
            return Err(Refusal::NoValidSignature);
        }
        Ok(Delivery {
            id: id.to_string(),
            timestamp,
        })
    }
}

/// An extractor for a verified delivery: the handler runs only when the [`Verifier`]
/// in the state verifies the request's headers and body, which it holds as bytes for
/// the handler to read, as with `serde_json::from_slice`. A refusal answers as
/// [`Refusal`] does, and the service's body limit applies as ever.
#[derive(Debug, Clone)]
pub struct Verified {
    /// The delivery.
    pub delivery: Delivery,
    /// The body, exactly as it was signed.
    pub body: Bytes,
}

impl<S> FromRequest<S> for Verified
where
    Verifier: FromRef<S>,
    S: Send + Sync,
{
    type Rejection = Response;

    async fn from_request(request: Request, state: &S) -> Result<Self, Response> {
        let verifier = Verifier::from_ref(state);
        let headers = request.headers().clone();
        let body = Bytes::from_request(request, state)
            .await
            .map_err(IntoResponse::into_response)?;
        let delivery = verifier
            .verify(&headers, &body)
            .map_err(IntoResponse::into_response)?;
        Ok(Self { delivery, body })
    }
}

#[cfg(test)]
mod tests {
    use axum::{Router, body::Body, routing::post};
    use tower::ServiceExt;

    use super::*;

    /// The secret from Standard Webhooks' own test vector.
    const SECRET: &str = "whsec_MfKQ9r8GKYqrTwjUPD8ILPZIo2LaLaSw";

    fn key(text: &str) -> SigningKey {
        text.parse().unwrap()
    }

    fn ed25519(seed: u8) -> SigningKey {
        key(&format!(
            "{SECRET_KEY_PREFIX}{}",
            STANDARD.encode([seed; 32])
        ))
    }

    #[test]
    fn it_matches_the_standard_webhooks_test_vector() {
        let signer = Signer::new(key(SECRET));
        let signature = signer
            .signature(
                "msg_p5jXN8AQM9LWM0D4loKWxJek",
                1_614_265_330,
                br#"{"test": 2432232314}"#,
            )
            .unwrap();
        assert_eq!(signature, "v1,g0hM9SsE+OTPJTGt/tmIKtSyZlE3uFJELVlNIOLJ1OE=");
    }

    #[test]
    fn a_delivery_verifies_with_either_kind_of_key() {
        for key in [key(SECRET), ed25519(7)] {
            let headers = Signer::new(key.clone())
                .headers("msg_1", 1_000, b"body")
                .unwrap();
            let verifier = Verifier::new(key.verifying_key());
            let delivery = verifier.verify_at(&headers, b"body", 1_000).unwrap();
            assert_eq!(
                delivery,
                Delivery {
                    id: "msg_1".into(),
                    timestamp: 1_000
                }
            );
            let public = key
                .public_key()
                .map(|text| text.parse::<VerifyingKey>().unwrap());
            if let Some(public) = public {
                assert!(
                    Verifier::new(public)
                        .verify_at(&headers, b"body", 1_000)
                        .is_ok()
                );
            }
        }
    }

    #[test]
    fn any_change_to_what_was_signed_is_refused() {
        let signer = Signer::new(key(SECRET));
        let verifier = Verifier::new(key(SECRET).verifying_key());
        let headers = signer.headers("msg_1", 1_000, b"body").unwrap();
        assert_eq!(
            verifier.verify_at(&headers, b"bodY", 1_000),
            Err(Refusal::NoValidSignature)
        );
        for (name, value) in [(ID_HEADER, "msg_2"), (TIMESTAMP_HEADER, "1001")] {
            let mut changed = headers.clone();
            changed.insert(name, HeaderValue::from_static(value));
            assert_eq!(
                verifier.verify_at(&changed, b"body", 1_000),
                Err(Refusal::NoValidSignature),
                "{name}"
            );
        }
        let other = Verifier::new(ed25519(1).verifying_key());
        assert_eq!(
            other.verify_at(&headers, b"body", 1_000),
            Err(Refusal::NoValidSignature)
        );
    }

    #[test]
    fn while_a_key_rotates_either_key_verifies() {
        let (old, new) = (key(SECRET), ed25519(9));
        let headers = Signer::new(old.clone())
            .and(new.clone())
            .headers("msg_1", 1_000, b"body")
            .unwrap();
        let listed = headers[SIGNATURE_HEADER].to_str().unwrap();
        assert!(
            listed.starts_with("v1,") && listed.contains(" v1a,"),
            "{listed}"
        );
        for key in [&old, &new] {
            let verifier = Verifier::new(key.verifying_key());
            assert!(verifier.verify_at(&headers, b"body", 1_000).is_ok());
        }
        let only_old = Signer::new(old).headers("msg_1", 1_000, b"body").unwrap();
        let both = Verifier::new(new.verifying_key()).and(key(SECRET).verifying_key());
        assert!(both.verify_at(&only_old, b"body", 1_000).is_ok());
    }

    #[test]
    fn a_timestamp_outside_the_window_is_refused_either_way() {
        let headers = Signer::new(key(SECRET))
            .headers("msg_1", 1_000, b"")
            .unwrap();
        let verifier = Verifier::new(key(SECRET).verifying_key()).tolerance(Duration::from_mins(1));
        assert!(verifier.verify_at(&headers, b"", 1_060).is_ok());
        assert!(verifier.verify_at(&headers, b"", 940).is_ok());
        for now in [1_061, 939] {
            assert_eq!(
                verifier.verify_at(&headers, b"", now),
                Err(Refusal::OutOfWindow)
            );
        }
    }

    #[test]
    fn malformed_headers_are_refused_before_any_signature_is_checked() {
        let verifier = Verifier::new(key(SECRET).verifying_key());
        let good = Signer::new(key(SECRET))
            .headers("msg_1", 1_000, b"")
            .unwrap();
        let too_many = vec!["v1,AAAA"; MAX_SIGNATURES + 1].join(" ");
        let cases = [
            (ID_HEADER, None, Refusal::MissingHeader(ID_HEADER)),
            (
                ID_HEADER,
                Some("has space"),
                Refusal::MalformedHeader(ID_HEADER),
            ),
            (
                TIMESTAMP_HEADER,
                None,
                Refusal::MissingHeader(TIMESTAMP_HEADER),
            ),
            (
                TIMESTAMP_HEADER,
                Some("+1000"),
                Refusal::MalformedHeader(TIMESTAMP_HEADER),
            ),
            (
                TIMESTAMP_HEADER,
                Some("1e3"),
                Refusal::MalformedHeader(TIMESTAMP_HEADER),
            ),
            (
                SIGNATURE_HEADER,
                None,
                Refusal::MissingHeader(SIGNATURE_HEADER),
            ),
            (
                SIGNATURE_HEADER,
                Some("  "),
                Refusal::MalformedHeader(SIGNATURE_HEADER),
            ),
            (
                SIGNATURE_HEADER,
                Some(too_many.as_str()),
                Refusal::MalformedHeader(SIGNATURE_HEADER),
            ),
        ];
        for (name, value, refusal) in cases {
            let mut headers = good.clone();
            match value {
                Some(value) => headers.insert(name, HeaderValue::from_str(value).unwrap()),
                None => headers.remove(name),
            };
            assert_eq!(
                verifier.verify_at(&headers, b"", 1_000),
                Err(refusal),
                "{name} {value:?}"
            );
        }
    }

    #[test]
    fn an_unknown_version_or_undecodable_signature_is_passed_over() {
        let verifier = Verifier::new(key(SECRET).verifying_key());
        let mut headers = Signer::new(key(SECRET))
            .headers("msg_1", 1_000, b"")
            .unwrap();
        let real = headers[SIGNATURE_HEADER].to_str().unwrap().to_string();
        let listed = format!("v2,AAAA v1,!!! nonsense v1a,AAAA {real}");
        headers.insert(SIGNATURE_HEADER, HeaderValue::from_str(&listed).unwrap());
        assert!(verifier.verify_at(&headers, b"", 1_000).is_ok());
        // An HMAC signature listed as Ed25519 is not accepted.
        let swapped = real.replacen("v1,", "v1a,", 1);
        headers.insert(SIGNATURE_HEADER, HeaderValue::from_str(&swapped).unwrap());
        assert_eq!(
            verifier.verify_at(&headers, b"", 1_000),
            Err(Refusal::NoValidSignature)
        );
    }

    #[test]
    fn keys_parse_strictly_and_never_print() {
        let secret_bytes = STANDARD.encode([1; 20]);
        for (text, error) in [
            ("MfKQ9r8GKYqrTwjUPD8ILPZIo2LaLaSw", KeyError::Prefix),
            ("whsec_!!!", KeyError::Base64),
            (&format!("whsec_{secret_bytes}") as &str, KeyError::Length),
            (
                &format!("whsk_{}", STANDARD.encode([1; 31])),
                KeyError::Length,
            ),
            (
                &format!("whsk_{}", STANDARD.encode([1; 64])),
                KeyError::Ed25519,
            ),
        ] {
            assert_eq!(text.parse::<SigningKey>().unwrap_err(), error, "{text}");
        }
        let whole = ed25519(3);
        let Signing::Ed25519(inner) = &whole.0 else {
            unreachable!()
        };
        let mut both = inner.to_bytes().to_vec();
        both.extend_from_slice(&inner.verifying_key().to_bytes());
        assert!(
            format!("whsk_{}", STANDARD.encode(&both))
                .parse::<SigningKey>()
                .is_ok()
        );
        assert_eq!(
            format!("whpk_{}", STANDARD.encode([1; 31]))
                .parse::<VerifyingKey>()
                .unwrap_err(),
            KeyError::Length
        );
        assert_eq!(key(SECRET).public_key(), None);
        let shown = format!("{:?} {:?} {:?}", key(SECRET), whole, whole.verifying_key());
        assert_eq!(
            shown,
            "SigningKey(hmac) SigningKey(ed25519) VerifyingKey(ed25519)"
        );
    }

    #[test]
    fn an_id_that_is_not_visible_ascii_cannot_be_signed() {
        let signer = Signer::new(key(SECRET));
        for id in ["", "a b", "naïve", &"x".repeat(MAX_ID_BYTES + 1)] {
            assert_eq!(
                signer.signature(id, 1, b""),
                Err(SignError::InvalidId),
                "{id}"
            );
        }
        assert!(signer.signature(&"x".repeat(MAX_ID_BYTES), 1, b"").is_ok());
    }

    fn receiver() -> Router {
        Router::new()
            .route(
                "/hooks",
                post(|Verified { delivery, body }: Verified| async move {
                    format!("{} {}", delivery.id, String::from_utf8_lossy(&body))
                }),
            )
            .with_state(Verifier::new(key(SECRET).verifying_key()))
    }

    async fn deliver(headers: HeaderMap, body: &'static str) -> (StatusCode, String) {
        let mut request = Request::post("/hooks").body(Body::from(body)).unwrap();
        *request.headers_mut() = headers;
        let response = receiver().oneshot(request).await.unwrap();
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        (status, String::from_utf8(bytes.to_vec()).unwrap())
    }

    #[tokio::test]
    async fn the_extractor_runs_the_handler_only_for_a_verified_delivery() {
        let signer = Signer::new(key(SECRET));
        let headers = signer.headers_now("msg_1", br#"{"a":1}"#).unwrap();
        assert_eq!(
            deliver(headers.clone(), r#"{"a":1}"#).await,
            (StatusCode::OK, r#"msg_1 {"a":1}"#.to_string())
        );

        let (status, body) = deliver(headers, r#"{"a":"secret"}"#).await;
        assert_eq!(status, StatusCode::UNAUTHORIZED);
        assert!(
            body.contains(r#""code":"webhook_signature_invalid""#),
            "{body}"
        );
        assert!(!body.contains("secret"), "{body}");

        let (status, body) = deliver(HeaderMap::new(), "{}").await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert!(
            body.contains(r#""code":"webhook_headers_invalid""#),
            "{body}"
        );

        let old = signer.headers("msg_1", now() - DEFAULT_TOLERANCE.as_secs() - 1, b"{}");
        let (status, body) = deliver(old.unwrap(), "{}").await;
        assert_eq!(status, StatusCode::UNAUTHORIZED);
        assert!(
            body.contains(r#""code":"webhook_timestamp_out_of_range""#),
            "{body}"
        );
    }

    #[test]
    fn a_verifier_without_keys_refuses_every_delivery() {
        let verifier = Verifier::without_keys();
        assert!(!verifier.has_keys());
        let headers = Signer::new(key(SECRET))
            .headers_now("msg_1", b"{}")
            .unwrap();
        let refusal = verifier.verify(&headers, b"{}").unwrap_err();
        assert_eq!(refusal, Refusal::NoKey);
        assert_eq!(refusal.status(), StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(refusal.code(), "webhook_verifier_missing");
        assert_eq!(
            verifier.verify(&HeaderMap::new(), b"").unwrap_err(),
            Refusal::NoKey
        );
        let verifier = Verifier::without_keys().and(key(SECRET).verifying_key());
        assert!(verifier.has_keys());
        assert!(verifier.verify(&headers, b"{}").is_ok());
    }
}

/// Properties over generated deliveries: what a key signs, that key verifies, inside the
/// window and to its edge; any other body, id, or time is refused; and no header a
/// sender makes up panics.
#[cfg(test)]
mod properties {
    use proptest::prelude::*;

    use super::*;

    const SECRET: &str = "whsec_MfKQ9r8GKYqrTwjUPD8ILPZIo2LaLaSw";

    /// An HMAC key, or an Ed25519 one from `seed`.
    fn any_key() -> impl Strategy<Value = SigningKey> {
        prop_oneof![
            Just(SECRET.parse::<SigningKey>().unwrap()),
            any::<[u8; 32]>().prop_map(|seed| {
                format!("{SECRET_KEY_PREFIX}{}", STANDARD.encode(seed))
                    .parse::<SigningKey>()
                    .unwrap()
            }),
        ]
    }

    fn id() -> impl Strategy<Value = String> {
        "[!-~]{1,64}"
    }

    proptest! {
        #[test]
        fn a_delivery_verifies_anywhere_inside_the_window_and_nowhere_past_it(
            key in any_key(),
            id in id(),
            body in prop::collection::vec(any::<u8>(), 0..256),
            timestamp in 1_000_000_u64..4_000_000_000,
            drift in 0_u64..=600,
            later in any::<bool>(),
        ) {
            let headers = Signer::new(key.clone()).headers(&id, timestamp, &body).unwrap();
            let verifier = Verifier::new(key.verifying_key());
            let now = if later { timestamp + drift } else { timestamp - drift };
            let result = verifier.verify_at(&headers, &body, now);
            if drift <= DEFAULT_TOLERANCE.as_secs() {
                prop_assert_eq!(result, Ok(Delivery { id, timestamp }));
            } else {
                prop_assert_eq!(result, Err(Refusal::OutOfWindow));
            }
        }

        #[test]
        fn another_body_or_key_is_refused(
            key in any_key(),
            other in any_key(),
            id in id(),
            body in prop::collection::vec(any::<u8>(), 1..256),
            flip in any::<prop::sample::Index>(),
            bit in 0_u8..8,
        ) {
            let headers = Signer::new(key.clone()).headers(&id, 1_000_000, &body).unwrap();
            let mut changed = body.clone();
            let at = flip.index(changed.len());
            changed[at] ^= 1 << bit;
            let verifier = Verifier::new(key.verifying_key());
            prop_assert_eq!(
                verifier.verify_at(&headers, &changed, 1_000_000),
                Err(Refusal::NoValidSignature)
            );
            // Two HMAC keys here are the one secret, so only keys that differ are tried.
            if other.public_key() != key.public_key() {
                prop_assert_eq!(
                    Verifier::new(other.verifying_key()).verify_at(&headers, &body, 1_000_000),
                    Err(Refusal::NoValidSignature)
                );
            }
        }

        #[test]
        fn any_headers_a_sender_makes_up_are_a_delivery_or_a_refusal(
            id in "[ -~]{0,300}",
            timestamp in "[ -~]{0,24}",
            signature in "[ -~]{0,400}",
            body in prop::collection::vec(any::<u8>(), 0..64),
        ) {
            let mut headers = HeaderMap::new();
            for (name, value) in [(ID_HEADER, &id), (TIMESTAMP_HEADER, &timestamp), (SIGNATURE_HEADER, &signature)] {
                if let Ok(value) = HeaderValue::from_str(value) {
                    headers.insert(name, value);
                }
            }
            let verifier = Verifier::new(SECRET.parse::<SigningKey>().unwrap().verifying_key());
            if let Err(refusal) = verifier.verify_at(&headers, &body, 1_000_000) {
                prop_assert!(refusal.status().is_client_error());
                prop_assert!(!refusal.to_string().is_empty());
            }
        }
    }

    #[test]
    fn the_most_signatures_a_delivery_may_list_are_checked_and_one_more_is_refused() {
        let key: SigningKey = SECRET.parse().unwrap();
        let mut headers = Signer::new(key.clone())
            .headers("msg_1", 1_000, b"body")
            .unwrap();
        let real = headers[SIGNATURE_HEADER].to_str().unwrap().to_string();
        let listed = |count: usize| {
            let mut entries = vec!["v1,AAAA"; count - 1];
            entries.push(real.as_str());
            HeaderValue::from_str(&entries.join(" ")).unwrap()
        };
        let verifier = Verifier::new(key.verifying_key());
        headers.insert(SIGNATURE_HEADER, listed(MAX_SIGNATURES));
        assert!(verifier.verify_at(&headers, b"body", 1_000).is_ok());
        headers.insert(SIGNATURE_HEADER, listed(MAX_SIGNATURES + 1));
        assert_eq!(
            verifier.verify_at(&headers, b"body", 1_000),
            Err(Refusal::MalformedHeader(SIGNATURE_HEADER))
        );
    }

    #[test]
    fn an_ed25519_key_has_a_public_half_that_verifies_and_hmac_has_none() {
        let key: SigningKey = format!("{SECRET_KEY_PREFIX}{}", STANDARD.encode([7; 32]))
            .parse()
            .unwrap();
        let public = key.public_key().expect("an Ed25519 key has a public half");
        assert!(public.starts_with(PUBLIC_KEY_PREFIX));
        let headers = Signer::new(key).headers("msg_1", 1_000, b"body").unwrap();
        let verifier = Verifier::new(public.parse().unwrap());
        assert!(verifier.verify_at(&headers, b"body", 1_000).is_ok());
    }

    #[test]
    fn every_error_says_what_was_wrong_in_words_of_its_own() {
        let texts = [
            KeyError::Prefix.to_string(),
            KeyError::Base64.to_string(),
            KeyError::Length.to_string(),
            KeyError::Ed25519.to_string(),
            SignError::InvalidId.to_string(),
            Refusal::MissingHeader(ID_HEADER).to_string(),
            Refusal::MalformedHeader(SIGNATURE_HEADER).to_string(),
            Refusal::OutOfWindow.to_string(),
            Refusal::NoValidSignature.to_string(),
            Refusal::NoKey.to_string(),
        ];
        let distinct: std::collections::HashSet<&String> = texts.iter().collect();
        assert_eq!(
            distinct.len(),
            texts.len(),
            "each error says something of its own"
        );
        assert!(texts.iter().all(|text| !text.is_empty()));
        assert!(texts[5].contains(ID_HEADER));
        assert!(texts[6].contains(SIGNATURE_HEADER));
    }
}

//! `client::resolve` with any `X-Forwarded-For` headers: an untrusted peer is always the
//! answer, and the walk never reaches past an address that is not trusted.

#![no_main]

use std::net::{IpAddr, Ipv4Addr};

use arbitrary::Arbitrary;
use axa::client::{ProxyNet, resolve};
use axum::http::{HeaderMap, HeaderValue};
use libfuzzer_sys::fuzz_target;

#[derive(Arbitrary, Debug)]
struct Input {
    peer: [u8; 4],
    trust_peer: bool,
    headers: Vec<Vec<u8>>,
}

fuzz_target!(|input: Input| {
    let peer = IpAddr::V4(Ipv4Addr::from(input.peer));
    let trusted: Vec<ProxyNet> = if input.trust_peer {
        vec![format!("{peer}/32").parse().unwrap()]
    } else {
        Vec::new()
    };
    let mut headers = HeaderMap::new();
    for value in input.headers.iter().take(8) {
        if let Ok(value) = HeaderValue::from_bytes(value) {
            headers.append("x-forwarded-for", value);
        }
    }
    let client = resolve(peer, &headers, &trusted);
    if !input.trust_peer {
        assert_eq!(client, peer, "an untrusted peer is the client");
    }
});

//! `CursorPage::new` with any query a caller sends: a page within the limits, or a
//! refusal, and only a cursor this key signed moves the offset.

#![no_main]

use axa_cursor_pagination::{CursorKey, CursorLimits, CursorPage};
use axum::http::Uri;
use libfuzzer_sys::fuzz_target;

const LIMITS: CursorLimits = CursorLimits {
    default_limit: 10,
    max_limit: 100,
};

fuzz_target!(|query: &str| {
    let Ok(uri) = format!("/things?{query}").parse::<Uri>() else {
        return;
    };
    let key = CursorKey::new(&[7; 32]).unwrap();
    if let Ok(page) = CursorPage::new(&key, LIMITS, &uri) {
        assert!((1..=LIMITS.max_limit).contains(&page.limit()));
        assert!(page.offset() == 0 || query.contains("cursor="));
        let _ = page.next_link();
    }
});

//! `format::clean_file_name` and `content_disposition` with any name a caller uploads:
//! the clean name has no path, quote, backslash, or control character, holds 1 to 255
//! bytes, and always makes a valid header.

#![no_main]

use axa::format::{clean_file_name, content_disposition};
use libfuzzer_sys::fuzz_target;

fuzz_target!(|input: (&str, &str)| {
    let (media_type, name) = input;
    let clean = clean_file_name(name);
    assert!(!clean.is_empty() && clean.len() <= 255, "{clean:?}");
    assert!(!clean.contains(['/', '\\', '"']), "{clean:?}");
    assert!(!clean.chars().any(char::is_control), "{clean:?}");
    assert!(!clean.starts_with('.'), "{clean:?}");
    let _ = content_disposition(media_type, name);
});

//! `conditional::if_match_holds` with any `If-Match` headers: an answer, never a panic,
//! and none at all when no header was sent.

#![no_main]

use axa::conditional::{ETag, if_match_holds};
use axum::http::{HeaderMap, HeaderValue, header};
use libfuzzer_sys::fuzz_target;

fuzz_target!(|values: Vec<Vec<u8>>| {
    let current = ETag::strong("v1").unwrap();
    let mut headers = HeaderMap::new();
    for value in values.iter().take(8) {
        if let Ok(value) = HeaderValue::from_bytes(value) {
            headers.append(header::IF_MATCH, value);
        }
    }
    let held = if_match_holds(&headers, &current);
    assert_eq!(held.is_none(), headers.is_empty());
});

//! `Verifier::verify_at` with any headers and body a sender makes up: a refusal a
//! client caused, never a panic, and never a delivery without a valid signature.

#![no_main]

use arbitrary::Arbitrary;
use axa_webhooks::{ID_HEADER, SIGNATURE_HEADER, Signer, SigningKey, TIMESTAMP_HEADER, Verifier};
use axum::http::{HeaderMap, HeaderValue};
use libfuzzer_sys::fuzz_target;

const SECRET: &str = "whsec_MfKQ9r8GKYqrTwjUPD8ILPZIo2LaLaSw";

#[derive(Arbitrary, Debug)]
struct Input<'a> {
    id: &'a [u8],
    timestamp: &'a [u8],
    signature: &'a [u8],
    body: &'a [u8],
    now: u32,
}

fuzz_target!(|input: Input| {
    let key: SigningKey = SECRET.parse().unwrap();
    let mut headers = HeaderMap::new();
    for (name, value) in [
        (ID_HEADER, input.id),
        (TIMESTAMP_HEADER, input.timestamp),
        (SIGNATURE_HEADER, input.signature),
    ] {
        if let Ok(value) = HeaderValue::from_bytes(value) {
            headers.insert(name, value);
        }
    }
    let now = u64::from(input.now);
    match Verifier::new(key.verifying_key()).verify_at(&headers, input.body, now) {
        Ok(delivery) => {
            // Accepted, so the signature must be the one this key makes.
            let made = Signer::new(key)
                .signature(&delivery.id, delivery.timestamp, input.body)
                .unwrap();
            let listed = headers[SIGNATURE_HEADER].to_str().unwrap();
            assert!(listed.split_ascii_whitespace().any(|entry| entry == made));
        }
        Err(refusal) => assert!(refusal.status().is_client_error()),
    }
});

