    }

    #[test]
    fn check_refuses_what_a_start_would_refuse() {
        let error = report(&[], &Environment::Production).unwrap_err();
        assert!(error.to_string().contains("DB_URL"));
        let pairs = [("DB_URL", "postgres://localhost/db"), ("HTTP_HSTS", "tru")];
        let error = report(&pairs, &Environment::Production).unwrap_err();
        assert!(error.to_string().contains("HTTP_HSTS"));
    }

    #[test]
    fn check_shows_warnings_outside_production() {
        let text = report(&[("HTTP_HSTS", "tru")], &Environment::Development).unwrap();
        assert!(text.contains("warning: HTTP_HSTS"), "{text}");
    }

    #[test]
    fn command_line_is_well_formed() {
        Cli::command().debug_assert();
    }

    #[test]
    fn help_and_version_speak_for_the_service() {
        let mut command = command("case-folder", "7.8.9", "Holds case folders.");
        assert_eq!(command.render_version(), "case-folder 7.8.9\n");
        let help = command.render_long_help().to_string();
        assert!(help.contains("Holds case folders."), "{help}");
        assert!(!help.contains("Axum"), "{help}");
    }

    #[test]
    fn only_down_reset_and_truncate_destroy_data() {
        assert!(DbCommand::Down { steps: 1 }.destroys_data());
        assert!(DbCommand::Reset.destroys_data());
        assert!(DbCommand::Truncate.destroys_data());
        assert!(!DbCommand::Migrate.destroys_data());
        assert!(!DbCommand::Status.destroys_data());
    }

    #[test]
    fn a_destructive_command_is_refused_outside_development_and_test() {
        for process in [
            Environment::Production,
            Environment::Other("staging".to_string()),
        ] {
            for command in ["reset", "truncate", "down"] {
                let cli = parse(&["svc", "db", command]);
                assert!(refusal(&cli, &process, Some("true")).is_some(), "{command}");
            }
        }
    }

    #[test]
    fn a_destructive_command_needs_confirming() {
        let cli = parse(&["svc", "db", "truncate"]);
        assert!(refusal(&cli, &Environment::Development, None).is_some());
        assert!(refusal(&cli, &Environment::Test, Some("yes")).is_some());
        assert!(refusal(&cli, &Environment::Development, Some("true")).is_none());
        assert!(refusal(&cli, &Environment::Test, Some("true")).is_none());
    }

    #[test]
    fn the_environment_flag_cannot_lift_the_refusal() {
        let cli = parse(&["svc", "db", "reset", "--environment", "test"]);
        let refused = refusal(&cli, &Environment::Production, Some("true"));
        assert!(refused.is_some());
        // It can only add to it.
        let cli = parse(&["svc", "db", "reset", "--environment", "production"]);
        let refused = refusal(&cli, &Environment::Development, Some("true"));
        assert!(refused.is_some());
    }

    #[test]
    fn other_commands_are_never_refused() {
        for args in [
            &["svc", "db", "migrate"][..],
            &["svc", "db", "status"],
            &["svc", "check"],
            &["svc", "start"],
        ] {
            let cli = parse(args);
            assert_eq!(refusal(&cli, &Environment::Production, None), None);
        }
    }

    #[test]
    fn nothing_says_this_crate_is_the_service() {
        let help = Cli::command().render_long_help().to_string();
        assert!(!help.contains("Axum"), "{help}");
        assert!(Cli::try_parse_from(["svc", "--version"]).is_err());
    }

    #[test]
    fn the_written_out_parser_reads_what_the_derived_one_did() {
        let cli = parse(&["svc", "--environment", "test", "db", "reset"]);
        assert_eq!(cli.environment.as_deref(), Some("test"));
        assert!(matches!(
            cli.command,
            Command::Db {
                command: DbCommand::Reset
            }
        ));
        assert!(Cli::try_parse_from(["svc"]).is_err());
        assert!(Cli::command().get_about().is_none());
    }
}

//! The address of the client behind a request.
//!
//! `X-Forwarded-For` is only what the caller and each proxy wrote. Its first entry is
//! whatever the caller chose, so reading it records a forged address as evidence.
//! Each proxy appends what it saw, so the entries can be trusted from the right, for
//! as long as the machine that wrote each one is a proxy this service trusts.
//!
//! List those proxies in `TRUSTED_PROXIES`. With none listed, the header is ignored.
//!
//! [`crate::middleware::apply`] resolves the address for each request served by
//! [`crate::server`], and a handler reads it with [`ClientAddr`]. It is also a plain
//! [`IpAddr`] request extension, for a layer that does not depend on this crate.
//!
//! It stays out of the request span on purpose. An address is personal data, so it
//! is recorded where a service chooses to, such as an audit row.

use std::{
    convert::Infallible,
    fmt,
    net::{IpAddr, SocketAddr},
    str::FromStr,
};

use axum::{
    extract::{ConnectInfo, FromRequestParts, Request, State},
    http::{HeaderMap, HeaderName, request::Parts},
    middleware::Next,
    response::Response,
};

/// The header proxies record addresses in.
const X_FORWARDED_FOR: HeaderName = HeaderName::from_static("x-forwarded-for");

/// The most entries read, so that a long header costs a bounded amount of work.
const MAX_HOPS: usize = 32;

/// A proxy's address, or a range of them, as in `10.0.0.1` or `10.0.0.0/8`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ProxyNet {
    network: IpAddr,
    prefix: u8,
}

impl ProxyNet {
    /// Whether `address` is in this range.
    #[must_use]
    pub fn contains(&self, address: IpAddr) -> bool {
        match (self.network, address.to_canonical()) {
            (IpAddr::V4(network), IpAddr::V4(address)) => {
                masked(u128::from(network.to_bits()), 32, self.prefix)
                    == masked(u128::from(address.to_bits()), 32, self.prefix)
            }
            (IpAddr::V6(network), IpAddr::V6(address)) => {
                masked(network.to_bits(), 128, self.prefix)
                    == masked(address.to_bits(), 128, self.prefix)
            }
            _ => false,
        }
    }
}

/// `bits` of `width`, keeping the leading `prefix`.
const fn masked(bits: u128, width: u8, prefix: u8) -> u128 {
    if prefix == 0 {
        0
    } else {
        bits >> (width - prefix)
    }
}

/// Why a [`ProxyNet`] could not be read.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InvalidProxyNet;

impl fmt::Display for InvalidProxyNet {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("not an address or CIDR range")
    }
}

impl std::error::Error for InvalidProxyNet {}

impl FromStr for ProxyNet {
    type Err = InvalidProxyNet;

    fn from_str(text: &str) -> Result<Self, InvalidProxyNet> {
        let (address, prefix) = text
            .split_once('/')
            .map_or((text, None), |(a, p)| (a, Some(p)));
        let network = address
            .parse::<IpAddr>()
            .map_err(|_| InvalidProxyNet)?
            .to_canonical();
        let width = if network.is_ipv4() { 32 } else { 128 };
        let prefix = match prefix {
            Some(prefix) => prefix.parse::<u8>().map_err(|_| InvalidProxyNet)?,
            None => width,
        };
        if prefix > width {
            return Err(InvalidProxyNet);
        }
        Ok(Self { network, prefix })
    }
}

impl fmt::Display for ProxyNet {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}/{}", self.network, self.prefix)
    }
}

/// The client's address, given the machine that connected.
///
/// An untrusted `peer` is the answer, whatever its headers say. A trusted one vouches
/// for the rightmost entry, and so on leftwards while each entry is trusted. An entry
/// that cannot be read ends the walk at the last address known to be good.
#[must_use]
pub fn resolve(peer: IpAddr, headers: &HeaderMap, trusted: &[ProxyNet]) -> IpAddr {
    let is_trusted = |address: IpAddr| trusted.iter().any(|net| net.contains(address));
    let mut client = peer.to_canonical();
    if !is_trusted(client) {
        return client;
    }
    // Several headers read as one list, in order, so the last header's last entry is
    // the nearest. Reading newest first stops a long header at the near end.
    let values = headers.get_all(&X_FORWARDED_FOR);
    let entries = values
        .iter()
        .rev()
        .map(|value| value.to_str().unwrap_or(""))
        .flat_map(|value| value.rsplit(','));
    for entry in entries.take(MAX_HOPS) {
        let Ok(address) = entry.trim().parse::<IpAddr>() else {
            break;
        };
        client = address.to_canonical();
        if !is_trusted(client) {
            break;
        }
    }
    client
}

/// The client's address, from the connection and any trusted proxies.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ClientAddr(pub Option<IpAddr>);

impl<S: Send + Sync> FromRequestParts<S> for ClientAddr {
    type Rejection = Infallible;

    #[allow(unknown_lints, clippy::unused_async_trait_impl)]
    async fn from_request_parts(parts: &mut Parts, _state: &S) -> Result<Self, Infallible> {
        Ok(Self(parts.extensions.get::<IpAddr>().copied()))
    }
}

/// Puts the client's address on the request. Without `ConnectInfo`, as in a test that
/// calls the router directly, there is no address to put.
pub(crate) async fn record(
    State(trusted): State<std::sync::Arc<Vec<ProxyNet>>>,
    mut request: Request,
    next: Next,
) -> Response {
    let peer = request
        .extensions()
        .get::<ConnectInfo<SocketAddr>>()
        .map(|info| info.0.ip());
    if let Some(peer) = peer {
        let client = resolve(peer, request.headers(), &trusted);
        request.extensions_mut().insert(client);
    }
    next.run(request).await
}

#[cfg(test)]
mod tests {
    use axum::http::HeaderValue;

    use super::*;

    const PEER: &str = "10.0.0.1";

    fn trusted() -> Vec<ProxyNet> {
        ["10.0.0.0/8", "fd00::/8"]
            .iter()
            .map(|net| net.parse().unwrap())
            .collect()
    }

    fn resolved(peer: &str, forwarded: &[&str]) -> String {
        let mut headers = HeaderMap::new();
        for value in forwarded {
            headers.append(&X_FORWARDED_FOR, HeaderValue::from_str(value).unwrap());
        }
        resolve(peer.parse().unwrap(), &headers, &trusted()).to_string()
    }

    #[test]
    fn with_no_proxies_the_header_is_ignored() {
        let mut headers = HeaderMap::new();
        headers.insert(&X_FORWARDED_FOR, HeaderValue::from_static("1.2.3.4"));
        let peer = PEER.parse().unwrap();
        assert_eq!(resolve(peer, &headers, &[]).to_string(), PEER);
    }

    #[test]
    fn a_caller_that_is_no_proxy_cannot_name_an_address() {
        assert_eq!(resolved("203.0.113.9", &["1.2.3.4"]), "203.0.113.9");
    }

    #[test]
    fn the_rightmost_untrusted_entry_is_the_client() {
        assert_eq!(resolved(PEER, &["198.51.100.7"]), "198.51.100.7");
        assert_eq!(resolved(PEER, &["198.51.100.7, 10.0.0.2"]), "198.51.100.7");
    }

    #[test]
    fn an_entry_the_caller_wrote_is_not_believed() {
        // The caller sent 1.2.3.4, and the proxy appended the caller's real address.
        assert_eq!(resolved(PEER, &["1.2.3.4, 198.51.100.7"]), "198.51.100.7");
    }

    #[test]
    fn repeated_headers_read_as_one_list() {
        assert_eq!(resolved(PEER, &["1.2.3.4", "198.51.100.7"]), "198.51.100.7");
    }

    #[test]
    fn an_unreadable_entry_ends_the_walk() {
        assert_eq!(resolved(PEER, &["1.2.3.4, junk, 10.0.0.2"]), "10.0.0.2");
        assert_eq!(resolved(PEER, &["junk"]), PEER);
        assert_eq!(resolved(PEER, &[""]), PEER);
    }

    #[test]
    fn with_only_proxies_the_leftmost_is_the_client() {
        assert_eq!(resolved(PEER, &["10.0.0.3, 10.0.0.2"]), "10.0.0.3");
    }

    #[test]
    fn a_long_header_stops_at_the_limit() {
        let long = vec!["10.0.0.2"; 100].join(",");
        assert_eq!(resolved(PEER, &[&format!("1.2.3.4,{long}")]), "10.0.0.2");
    }

    #[test]
    fn an_ipv4_address_inside_ipv6_is_the_same_address() {
        assert_eq!(
            resolved("::ffff:10.0.0.1", &["198.51.100.7"]),
            "198.51.100.7"
        );
        assert_eq!(resolved("::ffff:203.0.113.9", &[]), "203.0.113.9");
    }

    #[test]
    fn ranges_read_and_match() {
        let net: ProxyNet = "192.168.1.0/24".parse().unwrap();
        assert!(net.contains("192.168.1.200".parse().unwrap()));
        assert!(!net.contains("192.168.2.1".parse().unwrap()));
        assert!(!net.contains("fd00::1".parse().unwrap()));
        let all: ProxyNet = "0.0.0.0/0".parse().unwrap();
        assert!(all.contains("8.8.8.8".parse().unwrap()));
        let one: ProxyNet = "2001:db8::1".parse().unwrap();
        assert!(one.contains("2001:db8::1".parse().unwrap()));
        assert!(!one.contains("2001:db8::2".parse().unwrap()));
        assert_eq!(one.to_string(), "2001:db8::1/128");
    }

    #[test]
    fn a_bad_range_is_refused() {
        for text in ["", "junk", "10.0.0.0/33", "fd00::/129", "10.0.0.0/x", "/8"] {
            assert_eq!(text.parse::<ProxyNet>(), Err(InvalidProxyNet), "{text}");
        }
    }
}

//! Conditional requests: `ETag`, `If-None-Match`, and `If-Match`, as RFC 9110 has them.
//!
//! There are three parts, because they cost different things.
//!
//! **Answering `304`** needs nothing from a service. [`not_modified`] is part of the
//! standard stack. When a `GET` or `HEAD` answers with an `ETag` that the caller holds,
//! the body is dropped and the answer becomes a `304`, however the tag got there.
//!
//! **Tagging an answer** is the handler's choice, as only it knows what the tag should
//! cover. An [`ETag`] goes on a response like any other header. This one leaves out a
//! timestamp, so the tag stands still until the data moves:
//!
//! ```
//! use axa::{Result, conditional::ETag, prelude::*};
//! use serde_json::{Value, json};
//!
//! async fn dashboard() -> Result<Response> {
//!     let payload = json!({ "open": 3 });
//!     let tag = ETag::weak_of(&payload)?;
//!     let mut body = payload;
//!     body["as_of"] = Value::from("2026-11-07T09:00:00Z");
//!     Ok((tag, format::json(body)?).into_response())
//! }
//! ```
//!
//! [`etag`] tags answers by hashing their bodies, for a route or router that opts in:
//!
//! ```
//! use axa::conditional;
//! use axum::{Router, middleware::from_fn, routing::get};
//!
//! # async fn list() -> &'static str { "[]" }
//! let routes: Router = Router::new()
//!     .route("/catalogue", get(list))
//!     .layer(from_fn(conditional::etag));
//! ```
//!
//! **Refusing a stale write** needs the record's current tag, so a handler asks, after
//! it has authorised the caller and loaded the record. A record that is not there is
//! a `404` before this is asked:
//!
//! ```
//! use axa::{Result, conditional::{self, ETag}, prelude::*};
//! use axum::http::HeaderMap;
//!
//! async fn rename(headers: HeaderMap) -> Result<Response> {
//!     # let version = 7;
//!     conditional::if_match(&headers, &ETag::strong(&format!("v{version}"))?)?;
//!     format::empty()
//! }
//! ```
//!
//! The check and the write are two steps. To close the gap, make them one, with a lock
//! on the row or `UPDATE ... WHERE version = $1`.
//!
//! # What this saves
//!
//! The handler has run by the time an answer can be compared, so a `304` saves the
//! bytes and not the query. A handler that wants to skip its work can return early.
//!
//! # Who can learn what
//!
//! A `304` is made from the answer the caller was about to get. Nothing is stored and
//! nothing short-circuits the request, so a caller who is refused gets the refusal
//! whatever they hold, and a tag covers what this caller may see. That holds wherever
//! the authentication layer sits.
//!
//! # Weak and strong tags
//!
//! A strong tag says two answers are the same bytes, and a compressed answer is not the
//! same bytes as a plain one. [`etag`] sits inside compression, where it reads the plain
//! body, so it makes a weak tag, which says only that the answers mean the same.
//! `If-None-Match` compares weakly, so a tag held from a compressed answer still matches.
//!
//! `If-Match` compares strongly, as RFC 9110 requires, so a weak tag never passes it. A
//! tag meant for `If-Match` is a strong one, such as a version. A handler's strong tag
//! is left alone when its answer is compressed, so an encoded answer shares a tag with a
//! plain one. It does no harm here, as no route of `axa`'s answers a `Range`, but
//! a service answering ranges should use a tag that differs by encoding.
//!
//! # Hashing
//!
//! The hash is std's `DefaultHasher`, so no dependency is needed. It gives every replica
//! the same tag, and a new Rust toolchain may change it, which costs each caller one
//! full answer. It catches accidents and not an adversary, so a tag defending against
//! someone who writes the data should be a version counter, or a real digest passed to
//! [`ETag::strong`].

use std::{
    convert::Infallible,
    fmt,
    hash::{DefaultHasher, Hasher},
    pin::Pin,
    task::{Context, Poll},
};

use axum::{
    body::{Body, Bytes, HttpBody, to_bytes},
    extract::Request,
    http::{HeaderMap, HeaderName, HeaderValue, Method, StatusCode, header},
    middleware::Next,
    response::{IntoResponseParts, Response, ResponseParts},
};
use hyper::body::Frame;
use serde::Serialize;

use crate::{Error, Result, error::ErrorDetail};

/// The largest body [`etag`] hashes, in bytes. A larger one passes through untagged.
pub const MAX_BODY: usize = 8 * 1024 * 1024;

/// What describes a body, which a `304` has none of. Everything else stays, as a
/// header that would have been on the `200` still says what it said.
const CONTENT_HEADERS: [HeaderName; 8] = [
    header::CONTENT_TYPE,
    header::CONTENT_LENGTH,
    header::CONTENT_ENCODING,
    header::CONTENT_LANGUAGE,
    header::CONTENT_RANGE,
    header::CONTENT_DISPOSITION,
    header::TRANSFER_ENCODING,
    header::TRAILER,
];

/// An entity tag, ready to go on a response.
///
/// It goes in a tuple before the response, as any header does, and its [`Display`] text
/// is what a caller sends back, for a preview that puts the tag in its body.
///
/// [`Display`]: fmt::Display
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ETag(HeaderValue);

impl ETag {
    /// A tag saying two answers mean the same, for `If-None-Match`.
    ///
    /// # Errors
    ///
    /// Fails when `text` has a character a tag cannot hold: a space, a double quote, or
    /// anything outside visible ASCII. That is the service's mistake, so it is a `500`.
    pub fn weak(text: &str) -> Result<Self> {
        Self::new("W/", text)
    }

    /// A tag saying two answers are the same, for `If-Match`. A version or a digest
    /// of the record is usual.
    ///
    /// # Errors
    ///
    /// As for [`ETag::weak`].
    pub fn strong(text: &str) -> Result<Self> {
        Self::new("", text)
    }

    /// The weak tag of `value`'s JSON, which is the tag [`etag`] gives `Json(value)`.
    ///
    /// # Errors
    ///
    /// Fails when `value` does not serialize.
    pub fn weak_of<T: Serialize>(value: &T) -> Result<Self> {
        Self::weak(&digest(&serde_json::to_vec(value)?))
    }

    /// The strong tag of `value`'s JSON, for an `If-Match` on a record with no version.
    /// `value` is what must not change, and it need not be what the answer holds.
    ///
    /// # Errors
    ///
    /// Fails when `value` does not serialize.
    pub fn strong_of<T: Serialize>(value: &T) -> Result<Self> {
        Self::strong(&digest(&serde_json::to_vec(value)?))
    }

    fn new(prefix: &str, text: &str) -> Result<Self> {
        if !text
            .bytes()
            .all(|byte| byte.is_ascii() && is_tag_byte(byte))
        {
            return Err(Error::string(
                "an entity tag has a character it cannot hold",
            ));
        }
        HeaderValue::from_str(&format!("{prefix}\"{text}\""))
            .map(Self)
            .map_err(Error::wrap)
    }

    fn parsed(&self) -> Option<Tag<'_>> {
        tag_alone(self.0.as_bytes())
    }
}

impl fmt::Display for ETag {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.0.to_str().unwrap_or_default())
    }
}

impl IntoResponseParts for ETag {
    type Error = Infallible;

    fn into_response_parts(
        self,
        mut parts: ResponseParts,
    ) -> std::result::Result<ResponseParts, Self::Error> {
        parts.headers_mut().insert(header::ETAG, self.0);
        Ok(parts)
    }
}

/// The opaque text of a generated tag: the length, then a hash of the bytes.
fn digest(bytes: &[u8]) -> String {
    let mut hasher = DefaultHasher::new();
    hasher.write(bytes);
    format!("{:x}-{:016x}", bytes.len(), hasher.finish())
}

/// One tag as it was written, borrowing from the header.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Tag<'a> {
    weak: bool,
    opaque: &'a [u8],
}

/// `If-None-Match`'s test: the same text, whichever is weak.
fn weak_match(sent: Tag<'_>, current: Tag<'_>) -> bool {
    sent.opaque == current.opaque
}

/// `If-Match`'s test: the same text, and neither weak.
fn strong_match(sent: Tag<'_>, current: Tag<'_>) -> bool {
    !sent.weak && !current.weak && sent.opaque == current.opaque
}

/// `etagc` in RFC 9110: what may sit between the quotes.
const fn is_tag_byte(byte: u8) -> bool {
    matches!(byte, 0x21 | 0x23..=0x7e | 0x80..=0xff)
}

/// Read one tag from the start of `bytes`, and give back what follows it.
fn read_tag(bytes: &[u8]) -> Option<(Tag<'_>, &[u8])> {
    let (weak, rest) = match bytes.strip_prefix(b"W/") {
        Some(rest) => (true, rest),
        None => (false, bytes),
    };
    let rest = rest.strip_prefix(b"\"")?;
    let end = rest.iter().position(|byte| !is_tag_byte(*byte))?;
    (rest[end] == b'"').then_some((
        Tag {
            weak,
            opaque: &rest[..end],
        },
        &rest[end + 1..],
    ))
}

/// A header holding exactly one tag, as `ETag` does.
fn tag_alone(bytes: &[u8]) -> Option<Tag<'_>> {
    let (tag, rest) = read_tag(bytes.trim_ascii())?;
    rest.is_empty().then_some(tag)
}

/// Read a list of tags, which may run over several header lines. Commas are read
/// as separators only outside the quotes, as a tag can hold one, and RFC 9110 has a
/// reader accept empty members. `None` means it is not a list of tags.
fn read_tags<'a>(values: &[&'a HeaderValue], tags: &mut Vec<Tag<'a>>) -> Option<()> {
    for value in values {
        let mut rest = value.as_bytes().trim_ascii();
        while !rest.is_empty() {
            if let Some(after) = rest.strip_prefix(b",") {
                rest = after.trim_ascii_start();
                continue;
            }
            let (tag, after) = read_tag(rest)?;
            tags.push(tag);
            rest = after.trim_ascii_start();
            if !rest.is_empty() && !rest.starts_with(b",") {
                return None;
            }
        }
    }
    Some(())
}

/// Whether a condition header is satisfied by the answer tagged `current`.
/// `*` stands for any answer at all, and must stand alone. Anything unreadable holds
/// nothing, so a bad `If-None-Match` gets the whole answer and a bad `If-Match` is refused.
fn holds(
    values: &[&HeaderValue],
    current: Option<Tag<'_>>,
    compare: fn(Tag<'_>, Tag<'_>) -> bool,
) -> bool {
    if let [value] = values
        && value.as_bytes().trim_ascii() == b"*"
    {
        return true;
    }
    let mut tags = Vec::new();
    read_tags(values, &mut tags).is_some()
        && current.is_some_and(|current| tags.iter().any(|tag| compare(*tag, current)))
}

/// The body of a `304`. An empty `Body` says its size is zero, and Axum then writes
/// `content-length: 0`, which RFC 9110 forbids here: on a `304` that header can only state
/// the length of the `200`. This one does not say, so nothing is written.
struct NoBody;

impl HttpBody for NoBody {
    type Data = Bytes;
    type Error = Infallible;

    fn poll_frame(
        self: Pin<&mut Self>,
        _: &mut Context<'_>,
    ) -> Poll<Option<std::result::Result<Frame<Bytes>, Infallible>>> {
        Poll::Ready(None)
    }

    fn is_end_stream(&self) -> bool {
        true
    }
}

/// The `304` for an answer: its headers and no body. The body was never read, so a
/// compressed one was never compressed.
fn unchanged(response: Response) -> Response {
    let (mut parts, _) = response.into_parts();
    parts.status = StatusCode::NOT_MODIFIED;
    for name in CONTENT_HEADERS {
        parts.headers.remove(name);
    }
    Response::from_parts(parts, Body::new(NoBody))
}

/// Answer `304` to a `GET` or `HEAD` that holds the `ETag` of its answer.
///
/// This is part of the standard stack, outside compression, so that a `304` has the
/// `vary` the `200` would have had. A service with a stack of its own can use it alone:
/// `.layer(axum::middleware::from_fn(axa::conditional::not_modified))`.
///
/// Only a `2xx` is compared, as RFC 9110 says of every precondition, so a refusal stays
/// a refusal. Another method has already done its work by the time an answer is here,
/// so it is never touched. `If-None-Match: *` matches any `2xx`, tagged or not.
pub async fn not_modified(request: Request, next: Next) -> Response {
    let conditional = matches!(*request.method(), Method::GET | Method::HEAD);
    let held: Vec<HeaderValue> = if conditional {
        let values = request.headers().get_all(header::IF_NONE_MATCH);
        values.iter().cloned().collect()
    } else {
        Vec::new()
    };
    let response = next.run(request).await;
    if held.is_empty() || !response.status().is_success() {
        return response;
    }
    let current = response
        .headers()
        .get(header::ETAG)
        .and_then(|value| tag_alone(value.as_bytes()));
    let held: Vec<&HeaderValue> = held.iter().collect();
    if holds(&held, current, weak_match) {
        unchanged(response)
    } else {
        response
    }
}

/// Whether `Cache-Control` says this answer must not be kept.
fn is_no_store(headers: &HeaderMap) -> bool {
    headers
        .get_all(header::CACHE_CONTROL)
        .iter()
        .filter_map(|value| value.to_str().ok())
        .flat_map(|value| value.split(','))
        .any(|directive| directive.trim().eq_ignore_ascii_case("no-store"))
}

/// Whether [`etag`] should hash this answer. A body with no exact size is a stream, and
/// one with an exact size is nearly always in memory already, so this is what keeps
/// streams and server-sent events unbuffered, however large or long they are.
fn should_tag(response: &Response) -> bool {
    response.status() == StatusCode::OK
        && !response.headers().contains_key(header::ETAG)
        && !response.headers().contains_key(header::CONTENT_ENCODING)
        && !is_no_store(response.headers())
        && response
            .body()
            .size_hint()
            .exact()
            .is_some_and(|size| size > 0 && size <= MAX_BODY as u64)
}

/// Give a `GET`'s `200` a weak `ETag` from a hash of its body.
///
/// Add it to a router, a `Routes` handler, or a single route, before
/// [`middleware::apply`](crate::middleware::apply), as with any other layer. Keep it
/// outside what shapes the body, such as paging, so that the tag covers what is sent,
/// and outside whatever sets `Cache-Control`, so that it can see `no-store`.
///
/// An answer is left alone when any of these is true:
///
/// - It already has an `ETag`, as a handler's own tag knows better than a hash.
/// - It says `no-store`, as nothing will revalidate it, and a hash of personal data
///   should not go out for no gain.
/// - It is empty, or over [`MAX_BODY`], or a stream of no known size.
/// - It is already encoded, because then this layer is outside compression.
///
/// `HEAD` gets no generated tag, because Axum has dropped the body before this sees it.
/// RFC 9110 lets a `HEAD` leave out what only the body can tell.
///
/// A body with a timestamp or a request id in it gets a new tag each time. That gains
/// nothing, as a caller never matches, and harms nothing, as a caller gets the whole
/// answer. Such a route wants [`ETag::weak_of`] over the part that matters.
pub async fn etag(request: Request, next: Next) -> Response {
    let is_get = request.method() == Method::GET;
    let response = next.run(request).await;
    if !is_get || !should_tag(&response) {
        return response;
    }
    let (mut parts, body) = response.into_parts();
    let Ok(bytes) = to_bytes(body, MAX_BODY).await else {
        // The headers have not gone yet, so a body that failed can still be an honest
        // error. Its text is not logged, as it can quote anything.
        tracing::error!("response_body_failed");
        return crate::error::internal_response();
    };
    if let Ok(tag) = ETag::weak(&digest(&bytes)) {
        parts.headers.insert(header::ETAG, tag.0);
    }
    Response::from_parts(parts, Body::from(bytes))
}

/// Whether the caller's `If-Match` holds for a record tagged `current`, or `None` if
/// they sent none. For a service with its own answer to a stale write.
///
/// It compares strongly, so a weak tag on either side does not hold. `*` does.
#[must_use]
pub fn if_match_holds(headers: &HeaderMap, current: &ETag) -> Option<bool> {
    let values: Vec<&HeaderValue> = headers.get_all(header::IF_MATCH).iter().collect();
    (!values.is_empty()).then(|| holds(&values, current.parsed(), strong_match))
}

fn precondition_failed() -> Error {
    Error::CustomError(
        StatusCode::PRECONDITION_FAILED,
        ErrorDetail::new(
            "precondition_failed",
            "this changed since it was read; read it again, then retry",
        ),
    )
}

/// Refuse a write whose `If-Match` is out of date, and let through one with none, for
/// a route where callers are not yet made to send it.
///
/// # Errors
///
/// A `412` problem with the `code` `precondition_failed`.
pub fn if_match(headers: &HeaderMap, current: &ETag) -> Result<()> {
    if if_match_holds(headers, current) == Some(false) {
        return Err(precondition_failed());
    }
    Ok(())
}

/// Refuse a write whose `If-Match` is out of date or missing.
///
/// # Errors
///
/// A `428` problem with the `code` `precondition_required` when there is no `If-Match`,
/// and otherwise as for [`if_match`].
pub fn require_if_match(headers: &HeaderMap, current: &ETag) -> Result<()> {
    match if_match_holds(headers, current) {
        Some(true) => Ok(()),
        Some(false) => Err(precondition_failed()),
        None => Err(Error::CustomError(
            StatusCode::PRECONDITION_REQUIRED,
            ErrorDetail::new(
                "precondition_required",
                "send If-Match with the tag from your last read",
            ),
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn value(text: &'static str) -> HeaderValue {
        HeaderValue::from_static(text)
    }

    fn weakly(sent: &[&'static str], current: &'static str) -> bool {
        let values: Vec<HeaderValue> = sent.iter().map(|text| value(text)).collect();
        let values: Vec<&HeaderValue> = values.iter().collect();
        holds(&values, tag_alone(current.as_bytes()), weak_match)
    }

    fn strongly(sent: &'static str, current: &'static str) -> bool {
        let sent = value(sent);
        holds(&[&sent], tag_alone(current.as_bytes()), strong_match)
    }

    #[test]
    fn weak_comparison_ignores_who_is_weak() {
        assert!(weakly(&["\"a\""], "\"a\""));
        assert!(weakly(&["W/\"a\""], "\"a\""));
        assert!(weakly(&["\"a\""], "W/\"a\""));
        assert!(weakly(&["W/\"a\""], "W/\"a\""));
        assert!(!weakly(&["W/\"a\""], "W/\"b\""));
    }

    #[test]
    fn strong_comparison_refuses_any_weak_tag() {
        assert!(strongly("\"a\"", "\"a\""));
        assert!(!strongly("W/\"a\"", "\"a\""));
        assert!(!strongly("\"a\"", "W/\"a\""));
        assert!(!strongly("W/\"a\"", "W/\"a\""));
        assert!(!strongly("\"a\"", "\"b\""));
    }

    #[test]
    fn a_list_is_read_with_commas_inside_tags_and_empty_members() {
        assert!(weakly(&["\"a\", W/\"b\" ,\"c\""], "\"b\""));
        assert!(weakly(&["\"x,y\""], "\"x,y\""));
        assert!(!weakly(&["\"x,y\""], "\"x\""));
        assert!(!weakly(&["\"x,y\""], "\"y\""));
        assert!(weakly(&[", \"a\",, \"b\","], "\"b\""));
    }

    #[test]
    fn a_list_can_run_over_several_header_lines() {
        assert!(weakly(&["\"a\"", "\"b\""], "\"b\""));
    }

    #[test]
    fn a_star_stands_for_anything_but_only_alone() {
        assert!(weakly(&["*"], "\"a\""));
        assert!(weakly(&[" * "], "\"a\""));
        assert!(!weakly(&["*, \"b\""], "\"a\""));
        assert!(!weakly(&["\"b\"", "*"], "\"a\""));
        let star = value("*");
        assert!(holds(&[&star], None, weak_match));
    }

    #[test]
    fn what_is_not_a_tag_matches_nothing() {
        for sent in [
            "a",
            "w/\"a\"",
            "\"a",
            "W/ \"a\"",
            "\"a\" \"a\"",
            "\"a\" junk",
            "\"a b\"",
            "\"a\", *",
        ] {
            assert!(!weakly(&[sent], "\"a\""), "{sent}");
        }
        assert!(!weakly(&["\"a\""], "a"));
    }

    #[test]
    fn bytes_outside_ascii_are_compared_as_bytes() {
        let sent = HeaderValue::from_bytes(b"\"\xE9\"").unwrap();
        assert!(holds(&[&sent], tag_alone(b"\"\xE9\""), weak_match));
    }

    #[test]
    fn no_store_is_read_as_a_directive() {
        let with = |text: &'static str| {
            let mut headers = HeaderMap::new();
            headers.insert(header::CACHE_CONTROL, value(text));
            is_no_store(&headers)
        };
        assert!(with("no-store"));
        assert!(with("private, No-Store"));
        assert!(!with("no-cache"));
        assert!(!with("private, max-age=60"));
        let mut headers = HeaderMap::new();
        headers.append(header::CACHE_CONTROL, value("private"));
        headers.append(header::CACHE_CONTROL, value("no-store"));
        assert!(is_no_store(&headers));
    }

    #[test]
    fn a_tag_holds_only_what_a_tag_can_hold() {
        assert_eq!(ETag::strong("v7").unwrap().to_string(), "\"v7\"");
        assert_eq!(ETag::weak("v7").unwrap().to_string(), "W/\"v7\"");
        assert_eq!(ETag::strong("").unwrap().to_string(), "\"\"");
        for text in ["a b", "a\"b", "a\nb", "é"] {
            assert!(ETag::strong(text).is_err(), "{text}");
            assert!(ETag::weak(text).is_err(), "{text}");
        }
    }

    #[test]
    fn a_digest_is_the_same_each_time_and_differs_by_content() {
        assert_eq!(digest(b"a"), digest(b"a"));
        assert_ne!(digest(b"a"), digest(b"b"));
        assert!(digest(b"abc").starts_with("3-"));
    }
}

//! Service configuration, from the process environment.
//!
//! There are no config files. A service states its defaults in code with
//! [`Defaults`], and the environment overrides them. Production has no
//! default database, so a missing `DB_URL` fails at boot.
//!
//! A setting that is set but makes no sense is a mistake, and a silent default
//! would hide it: `HTTP_HSTS=tru` must not turn HSTS off. So in a
//! production-like environment it stops the boot, with an error naming the
//! variable. Elsewhere the default applies, and the problem is kept in
//! [`Logger::warnings`] for [`logger::init`] to write out. A blank value counts
//! as unset, because that is what a compose file sends for an unset variable.

use std::{cell::RefCell, fmt};

use crate::{
    Environment, Error, Result,
    cli::{Cli, Command},
    client::ProxyNet,
    logger,
    worker::WorkerMode,
};

/// The default port: a=1, x=24, a=1.
pub const DEFAULT_PORT: u16 = 1241;

/// How long browsers keep to HTTPS unless `HSTS_MAX_AGE_SECONDS` says otherwise: one year.
pub const DEFAULT_HSTS_MAX_AGE: u64 = 31_536_000;

/// Production's policy unless `HTTP_CONTENT_SECURITY_POLICY` says otherwise. It suits a JSON API: a service that
/// serves pages must name what they load.
pub const DEFAULT_CSP: &str = "default-src 'none'; frame-ancestors 'none'";

/// The `permissions-policy` unless `HTTP_PERMISSIONS_POLICY` says otherwise: no camera,
/// microphone, location, payment, USB, sensors, or ad topics, for any origin.
pub const DEFAULT_PERMISSIONS_POLICY: &str = "accelerometer=(), browsing-topics=(), camera=(), \
     geolocation=(), gyroscope=(), magnetometer=(), microphone=(), payment=(), usb=()";

/// How long to wait for a database connection, unless a service or
/// `DB_CONNECT_TIMEOUT` says otherwise: five seconds, in milliseconds.
pub const DEFAULT_CONNECT_TIMEOUT: u64 = 5_000;

/// How long an idle database connection stays open, unless a service or
/// `DB_IDLE_TIMEOUT` says otherwise: ten minutes, in milliseconds.
pub const DEFAULT_IDLE_TIMEOUT: u64 = 600_000;

/// One megabyte, as a body limit.
pub const MB: usize = 1_000_000;

/// A service's own defaults.
#[derive(Debug, Clone)]
pub struct Defaults {
    /// Database name stem: `person_service` gives `person_service_test`.
    pub database: &'static str,
    /// Port when `PORT` is unset.
    pub port: u16,
    /// Port when `PORT` is unset in production, if different.
    pub production_port: Option<u16>,
    /// Largest accepted request body, in bytes.
    pub body_limit: usize,
    /// Pool size outside production.
    pub max_connections: u32,
    /// Database connection timeout, in milliseconds.
    pub connect_timeout: u64,
    /// Database idle timeout, in milliseconds.
    pub idle_timeout: u64,
    /// Whether to migrate at boot outside production. Turn this off for a
    /// service that shares a database it does not own. Production never does
    /// unless `DB_AUTO_MIGRATE` says so.
    pub auto_migrate: bool,
}

impl Default for Defaults {
    fn default() -> Self {
        Self {
            database: "app",
            port: DEFAULT_PORT,
            production_port: None,
            body_limit: 2 * MB,
            max_connections: 10,
            connect_timeout: DEFAULT_CONNECT_TIMEOUT,
            idle_timeout: DEFAULT_IDLE_TIMEOUT,
            auto_migrate: true,
        }
    }
}

/// HTTP server settings.
#[derive(Debug, Clone)]
pub struct Server {
    /// Listening port.
    pub port: u16,
    /// Listening address.
    pub binding: String,
    /// Public base URL.
    pub host: String,
    /// How long, once told to stop, to wait for requests and jobs to finish. `0`
    /// waits for as long as they take. For requests, it counts from the end of the
    /// drain.
    pub shutdown_timeout_seconds: u64,
    /// How long, once told to stop, to keep accepting connections while
    /// `/_health/ready` answers `503`, so that an orchestrator takes the service out of
    /// rotation before it stops listening. `0`, the default, stops listening at once.
    pub shutdown_drain_seconds: u64,
    /// How long a client has to send a request's headers. `0` allows for ever.
    pub header_read_timeout_seconds: u64,
    /// How long an idle connection is kept for a next request. Keep this longer than
    /// the idle timeout of any load balancer in front. `0` keeps it for ever.
    pub keep_alive_timeout_seconds: u64,
    /// How long a client that has stopped reading may hold up a response, counted from
    /// the first write it blocks. Any write that goes through starts this again, so a
    /// slow client is not cut off, and a handler with nothing to send is not affected.
    /// `0` waits for ever.
    pub send_stall_timeout_seconds: u64,
    /// The most connections open at once on each listener, the internal port having
    /// its own. More wait to be accepted.
    pub max_connections: usize,
    /// A second port, `INTERNAL_PORT`, for the health routes and metrics alone, which
    /// the main port then refuses. `None`, the default, serves them on the main port.
    pub internal_port: Option<u16>,
    /// Load balancers, from `PROXY_PROTOCOL_FROM`, whose connections start with a PROXY
    /// protocol header, version 1 or 2, naming the client. A connection from one of these
    /// without a header is closed, and one from anywhere else is served without reading
    /// one. Empty, the default, reads none.
    pub proxy_protocol_from: Vec<ProxyNet>,
}

/// How long a client has to send a request's headers unless
/// `HTTP_REQUEST_HEADER_READ_TIMEOUT_SECONDS` says otherwise.
pub const DEFAULT_HEADER_READ_TIMEOUT_SECONDS: u64 = 30;

/// How long an idle connection is kept unless `KEEP_ALIVE_TIMEOUT_SECONDS` says
/// otherwise. It beats the 60 seconds many load balancers keep a connection idle.
pub const DEFAULT_KEEP_ALIVE_TIMEOUT_SECONDS: u64 = 75;

/// How long a client that has stopped reading may hold up a response unless
/// `SEND_STALL_TIMEOUT_SECONDS` says otherwise.
pub const DEFAULT_SEND_STALL_TIMEOUT_SECONDS: u64 = 60;

/// How long shutdown waits unless `SHUTDOWN_TIMEOUT_SECONDS` says otherwise. It
/// sits under an orchestrator's usual 30 seconds before it kills a process.
pub const DEFAULT_SHUTDOWN_TIMEOUT_SECONDS: u64 = 25;

/// Logging settings.
#[derive(Debug, Clone)]
pub struct Logger {
    /// Whether to log to stdout.
    pub enable: bool,
    /// Minimum level.
    pub level: logger::LogLevel,
    /// Output format.
    pub format: logger::Format,
    /// A full `EnvFilter` string that replaces the default filter.
    pub override_filter: Option<String>,
    /// Problems found while reading the settings. Always empty in a
    /// production-like environment, where a problem stops the boot.
    pub warnings: Vec<String>,
}

/// Database settings. `Debug` hides any password in the connection string.
#[allow(
    clippy::struct_excessive_bools,
    reason = "each is a switch of its own, read from a variable of its own"
)]
#[derive(Clone)]
pub struct Database {
    /// Connection string. Empty for a service with no database.
    pub uri: String,
    /// Smallest pool size.
    pub min_connections: u32,
    /// Largest pool size.
    pub max_connections: u32,
    /// Connection timeout, in milliseconds.
    pub connect_timeout: u64,
    /// Idle timeout, in milliseconds.
    pub idle_timeout: u64,
    /// Log every statement.
    pub enable_logging: bool,
    /// Run migrations at boot. Off in production.
    pub auto_migrate: bool,
    /// Empty the tables at boot. Only ever on under `test`.
    pub dangerously_truncate: bool,
    /// A statement timeout on every connection, in milliseconds, from
    /// `DB_STATEMENT_TIMEOUT_MS`: Postgres's `statement_timeout`, or `MySQL`'s
    /// `max_execution_time`, which stops only a read-only `SELECT`. `0`, the default,
    /// sets none.
    pub statement_timeout_ms: u64,
    /// Postgres's `application_name` on every connection, from `DB_APPLICATION_NAME`,
    /// or the database name stem in [`Defaults`]. Empty sets none. `MySQL` has no
    /// session setting for it, and none of its drivers here sends the
    /// `program_name` connection attribute, so `MySQL` connections go without.
    pub application_name: String,
    /// Open every transaction read-only, from `DB_READ_ONLY`, as for a read replica:
    /// Postgres's `default_transaction_read_only`, or `MySQL`'s
    /// `transaction_read_only`.
    pub read_only: bool,
}

/// A timeout for the routes ending in one path suffix.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TimeoutOverride {
    /// The path suffix, such as `/import`.
    pub path_suffix: String,
    /// The timeout, in seconds. `0` turns it off for these routes.
    pub seconds: u64,
}

/// HTTP middleware settings.
#[derive(Debug, Clone)]
pub struct Http {
    /// Largest accepted request body, in bytes.
    pub body_limit: usize,
    /// Gzip, Brotli, and deflate response compression, and Zstd with the `zstd` feature.
    pub compression: bool,
    /// Per-request timeout, in seconds. `0` turns it off.
    pub timeout_seconds: u64,
    /// Routes with their own timeout, checked in order. Set these in code,
    /// for a route such as a large upload that legitimately takes longer.
    pub timeout_overrides: Vec<TimeoutOverride>,
    /// Paths, matched exactly, where the cross-site write guard lets a cross-site
    /// request through, such as an identity provider's `form_post` callback. Set these
    /// in code, and only for a route that checks the request some other way.
    pub cross_site_paths: Vec<String>,
    /// Origins allowed by CORS. `["*"]` allows any and is refused in
    /// production-like environments. Empty sends no CORS headers.
    pub cors_origins: Vec<String>,
    /// Send `Strict-Transport-Security`.
    pub hsts: bool,
    /// How long browsers keep to HTTPS, in seconds.
    pub hsts_max_age: u64,
    /// The `content-security-policy`, if any.
    pub csp: Option<String>,
    /// The `permissions-policy`, if any.
    pub permissions_policy: Option<String>,
    /// Put the caller's tenant on the request span, so every log line for the request
    /// carries it, from `HTTP_LOG_TENANT`, off unless set. The auth crates' guards
    /// record the tenant they verified, and nothing else does. It is never a metrics
    /// label, as every new tenant would be a new series.
    pub log_tenant: bool,
    /// Proxies whose `X-Forwarded-For` entries are believed. Empty ignores the header.
    pub trusted_proxies: Vec<ProxyNet>,
}

impl fmt::Debug for Database {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Named one by one, so that a new field cannot print without a decision.
        let Self {
            uri,
            min_connections,
            max_connections,
            connect_timeout,
            idle_timeout,
            enable_logging,
            auto_migrate,
            dangerously_truncate,
            statement_timeout_ms,
            application_name,
            read_only,
        } = self;
        f.debug_struct("Database")
            .field("uri", &redact("DB_URL", uri))
            .field("min_connections", min_connections)
            .field("max_connections", max_connections)
            .field("connect_timeout", connect_timeout)
            .field("idle_timeout", idle_timeout)
            .field("enable_logging", enable_logging)
            .field("auto_migrate", auto_migrate)
            .field("dangerously_truncate", dangerously_truncate)
            .field("statement_timeout_ms", statement_timeout_ms)
            .field("application_name", application_name)
            .field("read_only", read_only)
            .finish()
    }
}

/// All service configuration.
#[derive(Debug, Clone)]
pub struct Config {
    /// HTTP server.
    pub server: Server,
    /// Logging.
    pub logger: Logger,
    /// Database.
    pub database: Database,
    /// HTTP middleware.
    pub http: Http,
    /// How background jobs run.
    pub workers: WorkerMode,
}

/// What stands in for a secret in anything printed.
pub const REDACTED: &str = "[redacted]";

/// Words that make a name secret-shaped.
const SECRET_WORDS: [&str; 11] = [
    "SECRET",
    "PASS",
    "PWD",
    "TOKEN",
    "KEY",
    "CREDENTIAL",
    "PRIVATE",
    "AUTH",
    "COOKIE",
    "SALT",
    "SIGNATURE",
];

/// Whether `name` looks like it holds a secret. It errs towards yes, because
/// the cost of a wrong yes is one hidden value.
fn secret_shaped(name: &str) -> bool {
    let name = name.to_ascii_uppercase();
    SECRET_WORDS.iter().any(|word| name.contains(word))
}

/// Hide the password in `scheme://user:password@host`, or the whole of
/// `scheme://token@host`. It takes the last `@`, because a password may hold
/// `/` or `@` unescaped.
fn redact_userinfo(value: &str) -> String {
    let Some((scheme, rest)) = value.split_once("://") else {
        return value.to_string();
    };
    let Some(at) = rest.rfind('@') else {
        return value.to_string();
    };
    let (userinfo, host) = rest.split_at(at);
    match userinfo.split_once(':') {
        Some((user, _)) => format!("{scheme}://{user}:{REDACTED}{host}"),
        None => format!("{scheme}://{REDACTED}{host}"),
    }
}

/// Hide the value of any secret-shaped `key=value` pair, as in a URL's query
/// or a keyword connection string.
fn redact_pairs(value: &str) -> String {
    let mut out = String::new();
    let mut rest = value;
    loop {
        let end = rest.find(['?', '&', ';', ',', ' ']).unwrap_or(rest.len());
        let (piece, tail) = rest.split_at(end);
        match piece.split_once('=') {
            Some((key, _)) if secret_shaped(key) => {
                out.push_str(key);
                out.push('=');
                out.push_str(REDACTED);
            }
            _ => out.push_str(piece),
        }
        let Some(separator) = tail.chars().next() else {
            return out;
        };
        out.push(separator);
        rest = &tail[separator.len_utf8()..];
    }
}

/// `value` as it is safe to print for the setting `name`. A secret-shaped name
/// hides the whole value. Otherwise a password in a URL, and any secret-shaped
/// `key=value` pair, are hidden. A quoted value could hold a separator, so one
/// that mentions a secret at all is hidden whole.
///
/// # Examples
///
/// ```
/// use axa::config::redact;
///
/// assert_eq!(redact("API_TOKEN", "abc"), "[redacted]");
/// assert_eq!(
///     redact("DB_URL", "postgres://me:hunter2@db/app"),
///     "postgres://me:[redacted]@db/app"
/// );
/// assert_eq!(redact("PORT", "8000"), "8000");
/// ```
#[must_use]
pub fn redact(name: &str, value: &str) -> String {
    if secret_shaped(name) || (value.contains(['\'', '"']) && secret_shaped(value)) {
        return REDACTED.to_string();
    }
    redact_pairs(&redact_userinfo(value))
}

/// The database settings, from `DB_` variables.
fn database<F: Fn(&str) -> Option<String>>(
    vars: &Settings<F>,
    defaults: &Defaults,
    environment: &Environment,
    uri: String,
) -> Database {
    let production = environment.is_production_like();
    let test = *environment == Environment::Test;
    let (min_connections, max_connections) = pool_size(vars, defaults, production);
    Database {
        uri,
        min_connections,
        max_connections,
        connect_timeout: vars.parsed("DB_CONNECT_TIMEOUT", defaults.connect_timeout),
        idle_timeout: vars.parsed("DB_IDLE_TIMEOUT", defaults.idle_timeout),
        enable_logging: vars.flag("DB_LOGGING", false),
        auto_migrate: vars.flag("DB_AUTO_MIGRATE", defaults.auto_migrate && !production),
        dangerously_truncate: test,
        statement_timeout_ms: vars.parsed("DB_STATEMENT_TIMEOUT_MS", 0),
        application_name: application_name(vars, defaults.database),
        read_only: vars.flag("DB_READ_ONLY", false),
    }
}

/// Whether `name` is an application name Postgres keeps as it is: ASCII letters,
/// digits, `_`, `.`, and `-`, from 1 to 63 bytes.
fn is_application_name(name: &str) -> bool {
    (1..=63).contains(&name.len())
        && name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'.' | b'-'))
}

/// `DB_APPLICATION_NAME`, or the database name stem, which names the service, when it
/// is one Postgres keeps as it is. A set name that is not is a problem.
fn application_name<F: Fn(&str) -> Option<String>>(vars: &Settings<F>, stem: &str) -> String {
    match vars.optional("DB_APPLICATION_NAME") {
        Some(name) if is_application_name(name.trim()) => name.trim().to_string(),
        Some(name) => {
            vars.invalid(
                "DB_APPLICATION_NAME",
                &name,
                "ASCII letters, digits, `_`, `.`, and `-`, at most 63",
            );
            String::new()
        }
        None if is_application_name(stem) => stem.to_string(),
        None => String::new(),
    }
}

/// A statement timeout or read-only mode works only on Postgres and `MySQL`, so asking
/// for either with `SQLite` is a problem, rather than a setting silently ignored.
fn session_settings_need_postgres_or_mysql<F: Fn(&str) -> Option<String>>(
    vars: &Settings<F>,
    database: &Database,
) {
    let sqlite = cfg!(any(
        axa_db = "sqlite_sqlx",
        axa_db = "sqlite_seaorm",
        axa_db = "sqlite_diesel"
    ));
    if sqlite && (database.statement_timeout_ms > 0 || database.read_only) {
        vars.problem(
            "DB_STATEMENT_TIMEOUT_MS and DB_READ_ONLY work only with a Postgres or MySQL \
             database"
                .to_string(),
        );
    }
}

/// Typed reads of a service's settings, with Axa's rules: a blank value counts as
/// unset, a value that is set but invalid is a problem, the problems are named all at
/// once, and no secret is ever quoted.
///
/// [`Config`] reads Axa's own settings with it, and a service reads its own the same
/// way. [`Settings::finish`] then refuses to boot a production-like environment with
/// any problem, and elsewhere hands the problems back as warnings.
///
/// # Examples
///
/// ```
/// use axa::{Environment, config::Settings};
///
/// let settings = Settings::from_lookup(&Environment::Production, |name| match name {
///     "UPSTREAM_URL" => Some("https://upstream.example".to_string()),
///     "UPSTREAM_RETRIES" => Some("three".to_string()),
///     _ => None,
/// });
/// let url = settings.required("UPSTREAM_URL");
/// let retries: u32 = settings.parsed("UPSTREAM_RETRIES", 3);
/// let token = settings.secret("UPSTREAM_TOKEN");
/// assert_eq!(url.as_deref(), Some("https://upstream.example"));
/// assert_eq!((retries, token), (3, None));
///
/// let error = settings.finish().unwrap_err();
/// assert!(error.to_string().contains("UPSTREAM_RETRIES"));
/// ```
pub struct Settings<F> {
    lookup: F,
    production: bool,
    problems: RefCell<Vec<String>>,
}

impl Settings<fn(&str) -> Option<String>> {
    /// Read settings for `environment` from the process environment.
    #[must_use]
    pub fn from_env(environment: &Environment) -> Self {
        fn var(name: &str) -> Option<String> {
            std::env::var(name).ok()
        }
        Settings::from_lookup(environment, var)
    }
}

impl<F: Fn(&str) -> Option<String>> fmt::Debug for Settings<F> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Settings")
            .field("production", &self.production)
            .field("problems", &self.problems.borrow())
            .finish_non_exhaustive()
    }
}

impl<F: Fn(&str) -> Option<String>> Settings<F> {
    /// Read settings for `environment` through `lookup`, which gives the value of a
    /// variable, or `None` when it is unset.
    pub fn from_lookup(environment: &Environment, lookup: F) -> Self {
        Self {
            lookup,
            production: environment.is_production_like(),
            problems: RefCell::new(Vec::new()),
        }
    }

    /// The value of `name`, when it is set to something other than blanks.
    pub fn optional(&self, name: &str) -> Option<String> {
        (self.lookup)(name).filter(|value| !value.trim().is_empty())
    }

    /// The value of `name`. An unset one is a problem.
    pub fn required(&self, name: &str) -> Option<String> {
        let value = self.optional(name);
        if value.is_none() {
            self.problem(format!("{name} is required"));
        }
        value
    }

    /// The value of `name`, or of the file `{name}_FILE` names, so that a secret can be
    /// mounted as a file rather than set in the environment. The file's last line ending
    /// is dropped, and a file of blanks counts as unset. Both set, or a file that cannot
    /// be read, is a problem, and gives `None`.
    pub fn secret(&self, name: &str) -> Option<String> {
        let file_name = format!("{name}_FILE");
        match (self.optional(name), self.optional(&file_name)) {
            (Some(_), Some(_)) => {
                self.problem(format!("{name} and {file_name} are both set: set one"));
                None
            }
            (Some(value), None) => Some(value),
            (None, Some(path)) => match std::fs::read_to_string(path.trim()) {
                Ok(text) => {
                    let text = text.strip_suffix('\n').unwrap_or(&text);
                    let text = text.strip_suffix('\r').unwrap_or(text);
                    (!text.trim().is_empty()).then(|| text.to_string())
                }
                Err(error) => {
                    self.problem(format!("{file_name}={path:?} cannot be read: {error}"));
                    None
                }
            },
            (None, None) => None,
        }
    }

    /// [`Settings::secret`], and an unset one is a problem.
    pub fn required_secret(&self, name: &str) -> Option<String> {
        let before = self.problems.borrow().len();
        let value = self.secret(name);
        // A secret refused for being set twice, or unreadable, is a problem already.
        if value.is_none() && self.problems.borrow().len() == before {
            self.problem(format!("{name} or {name}_FILE is required"));
        }
        value
    }

    /// Note that `name` holds an invalid `value`, which is shown through [`redact`].
    /// `expected` says what it should be, as in "a port number".
    pub fn invalid(&self, name: &str, value: &str, expected: &str) {
        let shown = redact(name, value);
        self.problem(format!("{name}={shown:?} is not {expected}"));
    }

    /// Note a problem with the settings. It must quote no secret.
    pub fn problem(&self, problem: impl Into<String>) {
        self.problems.borrow_mut().push(problem.into());
    }

    /// The value of `name`, or `default` when unset. A blank value is kept.
    pub fn text(&self, name: &str, default: &str) -> String {
        (self.lookup)(name).unwrap_or_else(|| default.to_string())
    }

    /// The parsed value of `name`, or `default` when unset. An unparsable
    /// value also gives `default`, and is a problem.
    pub fn parsed<T: std::str::FromStr>(&self, name: &str, default: T) -> T {
        let Some(value) = self.optional(name) else {
            return default;
        };
        value.trim().parse().unwrap_or_else(|_| {
            self.invalid(name, &value, "a valid number");
            default
        })
    }

    /// The boolean value of `name`, or `default` when unset. `1`, `true`,
    /// `yes`, and `on` mean true, and `0`, `false`, `no`, and `off` mean false.
    /// Anything else also gives `default`, and is a problem: a typo for "on" must
    /// not read as "off".
    pub fn flag(&self, name: &str, default: bool) -> bool {
        let Some(value) = self.optional(name) else {
            return default;
        };
        match value.trim().to_ascii_lowercase().as_str() {
            "1" | "true" | "yes" | "on" => true,
            "0" | "false" | "no" | "off" => false,
            _ => {
                self.invalid(name, &value, "one of 1, true, yes, on, 0, false, no, off");
                default
            }
        }
    }

    /// The value of `name` as read by `from_name`, or `default` when unset. A
    /// name it does not know also gives `default`, and is a problem.
    pub fn named<T>(&self, name: &str, default: T, from_name: impl Fn(&str) -> Option<T>) -> T {
        let Some(value) = self.optional(name) else {
            return default;
        };
        from_name(&value).unwrap_or_else(|| {
            self.invalid(name, &value, "a name this setting knows");
            default
        })
    }

    /// The problems so far.
    pub fn problems(&self) -> Vec<String> {
        self.problems.borrow().clone()
    }

    /// End the reading. Fail closed: a production service that misread a setting would
    /// run with something nobody chose, and a warning there is read too late.
    ///
    /// # Errors
    ///
    /// Fails in a production-like environment when there is any problem, naming them
    /// all. Elsewhere it gives the problems back, for the service to log as warnings.
    pub fn finish(self) -> Result<Vec<String>> {
        let problems = self.problems.into_inner();
        if self.production && !problems.is_empty() {
            return Err(Error::string(&format!(
                "invalid settings: {}",
                problems.join("; ")
            )));
        }
        Ok(problems)
    }

    /// The log filter from `LOG_FILTER`. One that does not parse is noted and
    /// dropped, because [`logger::init_env_filter`] would panic on it.
    fn log_filter(&self) -> Option<String> {
        let filter = self.optional("LOG_FILTER")?;
        if tracing_subscriber::EnvFilter::try_new(&filter).is_err() {
            self.invalid("LOG_FILTER", &filter, "a valid log filter");
            return None;
        }
        Some(filter)
    }
}

/// The worker mode with this name, if there is one.
fn worker_mode(name: &str) -> Option<WorkerMode> {
    match name.trim() {
        "ForegroundBlocking" => Some(WorkerMode::ForegroundBlocking),
        "BackgroundAsync" => Some(WorkerMode::BackgroundAsync),
        "BackgroundQueue" => Some(WorkerMode::BackgroundQueue),
        _ => None,
    }
}

/// Whether a connection string keeps its traffic private: it demands TLS, or it goes
/// no further than this machine. An address that cannot be read, or a database this
/// does not know, counts as neither, so it fails closed.
///
/// Postgres demands TLS with `sslmode` of `require`, `verify-ca`, or `verify-full`, and
/// MySQL and MariaDB with `ssl-mode` of `REQUIRED`, `VERIFY_CA`, or `VERIFY_IDENTITY`.
/// `require` and `REQUIRED` count, though they encrypt without checking who answers:
/// only `verify-full` and `VERIFY_IDENTITY` check that. A SQLite database is a file on
/// this machine, so it always stays private.
fn stays_private(uri: &str) -> bool {
    if uri
        .get(..7)
        .is_some_and(|scheme| scheme.eq_ignore_ascii_case("sqlite:"))
    {
        return true;
    }
    let Some((scheme, rest)) = uri.split_once("://") else {
        return false;
    };
    let demanding: &[&str] = match scheme.to_ascii_lowercase().as_str() {
        "postgres" | "postgresql" => &["require", "verify-ca", "verify-full"],
        "mysql" | "mariadb" => &["required", "verify_ca", "verify_identity"],
        _ => return false,
    };
    let (location, query) = rest.split_once('?').unwrap_or((rest, ""));
    // The last of a repeated parameter wins, as it does in the driver.
    let parameter = |names: &[&str]| {
        query
            .split('&')
            .filter_map(|pair| pair.split_once('='))
            .filter(|(name, _)| names.contains(name))
            .map(|(_, value)| value)
            .next_back()
    };
    if parameter(&["sslmode", "ssl-mode"])
        .is_some_and(|mode| demanding.iter().any(|safe| mode.eq_ignore_ascii_case(safe)))
    {
        return true;
    }
    let authority = location.split('/').next().unwrap_or_default();
    let address = authority.rsplit('@').next().unwrap_or_default();
    let host = match address.strip_prefix('[') {
        Some(bracketed) => bracketed.split(']').next().unwrap_or_default(),
        None => address.split(':').next().unwrap_or_default(),
    };
    let host = parameter(&["host", "hostaddr"]).unwrap_or(host);
    host.starts_with('/')
        || host.starts_with("%2F")
        || matches!(host, "localhost" | "127.0.0.1" | "::1")
}

/// The connection string. Fail closed: a production service must never fall
/// back to a guessed local database.
fn database_uri<F: Fn(&str) -> Option<String>>(
    vars: &Settings<F>,
    environment: &Environment,
    defaults: &Defaults,
) -> Result<String> {
    let noted = vars.problems.borrow().len();
    let uri = vars.secret("DB_URL");
    // Both DB_URL and DB_URL_FILE set, or a file that cannot be read: guessing a local
    // database instead would hide the mistake anywhere.
    if let Some(problem) = vars.problems.borrow().get(noted) {
        return Err(Error::string(problem));
    }
    match uri {
        Some(uri)
            if environment.is_production_like()
                && !stays_private(&uri)
                && !vars.flag("DB_ALLOW_INSECURE", false) =>
        {
            Err(Error::string(
                "DB_URL must demand TLS in production, with sslmode set to require, \
                 verify-ca, or verify-full for Postgres, or ssl-mode set to REQUIRED, \
                 VERIFY_CA, or VERIFY_IDENTITY for MySQL, unless DB_ALLOW_INSECURE is set",
            ))
        }
        Some(uri) => Ok(uri),
        None if defaults.database.is_empty() => Ok(String::new()),
        None if environment.is_production_like() => {
            Err(Error::string("DB_URL is required in production"))
        }
        None => Ok(local_database_uri(defaults.database, environment)),
    }
}

/// The database a development or test build uses when `DB_URL` is unset: one on this
/// machine, for the database `AppContext::db` holds.
fn local_database_uri(database: &str, environment: &Environment) -> String {
    if cfg!(any(
        axa_db = "mysql_sqlx",
        axa_db = "mysql_seaorm",
        axa_db = "mysql_diesel",
        axa_db = "mysql_toasty"
    )) {
        format!("mysql://root@localhost:3306/{database}_{environment}")
    } else if cfg!(any(
        axa_db = "sqlite_sqlx",
        axa_db = "sqlite_seaorm",
        axa_db = "sqlite_diesel"
    )) {
        format!("sqlite://{database}_{environment}.sqlite3?mode=rwc")
    } else {
        format!("postgres://postgres:postgres@localhost:5432/{database}_{environment}")
    }
}

/// The allowed origins. Development serves browser dev servers on other ports,
/// so it allows any. Production sends no CORS headers until origins are listed.
/// `MAX_CONNECTIONS`, which must leave room for at least one.
fn connection_limit<F: Fn(&str) -> Option<String>>(vars: &Settings<F>) -> usize {
    let max = vars.parsed("MAX_CONNECTIONS", crate::server::MAX_CONNECTIONS);
    if max == 0 {
        vars.invalid("MAX_CONNECTIONS", "0", "at least 1");
        return crate::server::MAX_CONNECTIONS;
    }
    max
}

/// Ranges as the comma-separated list they are read from.
fn joined(nets: &[ProxyNet]) -> String {
    nets.iter()
        .map(ToString::to_string)
        .collect::<Vec<_>>()
        .join(",")
}

/// `TRUSTED_PROXIES` or `PROXY_PROTOCOL_FROM`, as a comma-separated list. A list with
/// any bad entry is noted, and none are trusted, which is the side to fail on.
fn proxy_nets<F: Fn(&str) -> Option<String>>(vars: &Settings<F>, name: &str) -> Vec<ProxyNet> {
    let Some(list) = vars.optional(name) else {
        return Vec::new();
    };
    list.split(',')
        .map(|net| net.trim().parse())
        .collect::<std::result::Result<_, _>>()
        .unwrap_or_else(|_| {
            vars.invalid(name, &list, "addresses or CIDR ranges");
            Vec::new()
        })
}

fn cors_origins<F: Fn(&str) -> Option<String>>(
    vars: &Settings<F>,
    production: bool,
) -> Result<Vec<String>> {
    let origins: Vec<String> = match (vars.lookup)("CORS_ALLOWED_ORIGINS") {
        Some(list) => list
            .split(',')
            .map(str::trim)
            .filter(|origin| !origin.is_empty())
            .map(str::to_string)
            .collect(),
        None if production => Vec::new(),
        None => vec!["*".to_string()],
    };
    if production && origins.iter().any(|origin| origin == "*") {
        return Err(Error::string(
            "CORS_ALLOWED_ORIGINS must list origins in production, not *",
        ));
    }
    Ok(origins)
}

/// `INTERNAL_PORT`, unless unset or `0`. One that is the main port is a problem, and
/// unset.
fn internal_port<F: Fn(&str) -> Option<String>>(vars: &Settings<F>, port: u16) -> Option<u16> {
    let internal = vars.parsed("INTERNAL_PORT", 0_u16);
    if internal != 0 && internal == port {
        vars.problem(format!("INTERNAL_PORT={internal} is the same as PORT"));
        return None;
    }
    (internal != 0).then_some(internal)
}

/// The smallest and largest pool sizes. An unset smallest size follows a small
/// largest one, so `DB_MAX_CONNECTIONS=1` works alone. A pool that cannot exist is
/// noted, and the default applies.
fn pool_size<F: Fn(&str) -> Option<String>>(
    vars: &Settings<F>,
    defaults: &Defaults,
    production: bool,
) -> (u32, u32) {
    let default_max = if production {
        20
    } else {
        defaults.max_connections
    };
    let mut max = vars.parsed("DB_MAX_CONNECTIONS", default_max);
    if max == 0 {
        vars.invalid("DB_MAX_CONNECTIONS", "0", "at least 1");
        max = default_max;
    }
    let default_min = u32::from(production).saturating_add(1).min(max);
    let min = vars.parsed("DB_MIN_CONNECTIONS", default_min);
    if min > max {
        let shown = min.to_string();
        vars.invalid("DB_MIN_CONNECTIONS", &shown, "at most DB_MAX_CONNECTIONS");
        return (default_min, max);
    }
    (min, max)
}

/// The policy from `HTTP_CONTENT_SECURITY_POLICY`, where blank means none, or production's default when unset.
fn content_security_policy<F: Fn(&str) -> Option<String>>(
    vars: &Settings<F>,
    production: bool,
) -> Option<String> {
    match (vars.lookup)("HTTP_CONTENT_SECURITY_POLICY") {
        Some(policy) if policy.trim().is_empty() => None,
        Some(policy) => Some(policy),
        None if production => Some(DEFAULT_CSP.to_string()),
        None => None,
    }
}

/// The policy from `HTTP_PERMISSIONS_POLICY`, where blank means none, or the deny-list
/// when unset.
fn permissions_policy<F: Fn(&str) -> Option<String>>(vars: &Settings<F>) -> Option<String> {
    match (vars.lookup)("HTTP_PERMISSIONS_POLICY") {
        Some(policy) if policy.trim().is_empty() => None,
        Some(policy) => Some(policy),
        None => Some(DEFAULT_PERMISSIONS_POLICY.to_string()),
    }
}

impl Config {
    /// Build configuration for `environment`, reading overrides from the
    /// process environment. See [`Config::from_lookup`].
    ///
    /// # Errors
    ///
    /// Fails in production as [`Config::from_lookup`] does.
    pub fn from_env(environment: &Environment, defaults: &Defaults) -> Result<Self> {
        Self::from_lookup(environment, defaults, |name| std::env::var(name).ok())
    }

    /// Build configuration for `environment`, reading overrides through
    /// `lookup`.
    ///
    /// # Examples
    ///
    /// ```
    /// use axa::config::{Config, Defaults};
    /// use axa::Environment;
    ///
    /// let config = Config::from_lookup(
    ///     &Environment::Development,
    ///     &Defaults::default(),
    ///     |name| (name == "PORT").then(|| "8000".to_string()),
    /// )
    /// .unwrap();
    /// assert_eq!(config.server.port, 8000);
    /// ```
    ///
    /// # Errors
    ///
    /// Fails in a production-like environment when there is no `DB_URL`
    /// and the service has a database, when `*` is given as a CORS origin, or
    /// when any setting is set but invalid. The error names the variable and
    /// its value, unless the name is secret-shaped.
    pub fn from_lookup(
        environment: &Environment,
        defaults: &Defaults,
        lookup: impl Fn(&str) -> Option<String>,
    ) -> Result<Self> {
        let vars = Settings::from_lookup(environment, lookup);
        let production = environment.is_production_like();
        let test = *environment == Environment::Test;

        let uri = database_uri(&vars, environment, defaults)?;
        let cors_origins = cors_origins(&vars, production)?;

        let level = if test {
            logger::LogLevel::Warn
        } else if production {
            logger::LogLevel::Info
        } else {
            logger::LogLevel::Debug
        };
        let workers = if test {
            WorkerMode::ForegroundBlocking
        } else {
            WorkerMode::BackgroundQueue
        };

        let mut config = Self {
            server: Server {
                port: vars.parsed(
                    "PORT",
                    defaults
                        .production_port
                        .filter(|_| production)
                        .unwrap_or(defaults.port),
                ),
                binding: vars.text("BINDING", if production { "0.0.0.0" } else { "localhost" }),
                host: vars.text("HOST", "http://localhost"),
                shutdown_timeout_seconds: vars
                    .parsed("SHUTDOWN_TIMEOUT_SECONDS", DEFAULT_SHUTDOWN_TIMEOUT_SECONDS),
                shutdown_drain_seconds: vars.parsed("SHUTDOWN_DRAIN_SECONDS", 0),
                header_read_timeout_seconds: vars.parsed(
                    "HTTP_REQUEST_HEADER_READ_TIMEOUT_SECONDS",
                    DEFAULT_HEADER_READ_TIMEOUT_SECONDS,
                ),
                keep_alive_timeout_seconds: vars.parsed(
                    "KEEP_ALIVE_TIMEOUT_SECONDS",
                    DEFAULT_KEEP_ALIVE_TIMEOUT_SECONDS,
                ),
                send_stall_timeout_seconds: vars.parsed(
                    "SEND_STALL_TIMEOUT_SECONDS",
                    DEFAULT_SEND_STALL_TIMEOUT_SECONDS,
                ),
                max_connections: connection_limit(&vars),
                internal_port: None,
                proxy_protocol_from: proxy_nets(&vars, "PROXY_PROTOCOL_FROM"),
            },
            logger: Logger {
                enable: vars.flag("LOG_ENABLE", !test),
                level: vars.named("LOG_LEVEL", level, logger::LogLevel::from_name),
                format: vars.named(
                    "LOG_FORMAT",
                    if production {
                        logger::Format::Json
                    } else {
                        logger::Format::Compact
                    },
                    logger::Format::from_name,
                ),
                override_filter: vars.log_filter(),
                warnings: Vec::new(),
            },
            database: database(&vars, defaults, environment, uri),
            http: Http {
                body_limit: vars.parsed("HTTP_REQUEST_BODY_LIMIT_BYTE_COUNT", defaults.body_limit),
                compression: vars.flag("HTTP_COMPRESSION", production),
                timeout_seconds: vars
                    .parsed("REQUEST_TIMEOUT_SECONDS", if production { 60 } else { 0 }),
                timeout_overrides: Vec::new(),
                cross_site_paths: Vec::new(),
                cors_origins,
                trusted_proxies: proxy_nets(&vars, "TRUSTED_PROXIES"),
                hsts: vars.flag("HTTP_HSTS", production),
                hsts_max_age: vars.parsed("HSTS_MAX_AGE_SECONDS", DEFAULT_HSTS_MAX_AGE),
                csp: content_security_policy(&vars, production),
                permissions_policy: permissions_policy(&vars),
                log_tenant: vars.flag("HTTP_LOG_TENANT", false),
            },
            workers: vars.named("WORKER_MODE", workers, worker_mode),
        };

        session_settings_need_postgres_or_mysql(&vars, &config.database);
        config.server.internal_port = internal_port(&vars, config.server.port);

        // Fail closed: a production service that misread a setting would run
        // with something nobody chose, and a warning there is read too late.
        let problems = vars.problems.into_inner();
        if production && !problems.is_empty() {
            return Err(Error::string(&format!(
                "invalid settings: {}",
                problems.join("; ")
            )));
        }
        config.logger.warnings = problems;
        Ok(config)
    }

    /// Apply the command line's overrides. Only `start` has any: `--binding`
    /// and `--port`.
    pub fn apply_cli(&mut self, cli: &Cli) {
        match &cli.command {
            Command::Start { binding, port, .. } => {
                if let Some(binding) = binding {
                    self.server.binding.clone_from(binding);
                }
                if let Some(port) = port {
                    self.server.port = *port;
                }
            }
            Command::Health {
                port: Some(port), ..
            } => self.server.port = *port,
            _ => {}
        }
    }

    /// The effective settings as `(variable, value)`, safe to print: every
    /// value has been through [`redact`]. The three lower-case names,
    /// `dangerously_truncate`, `timeout_overrides`, and `cross_site_paths`, are
    /// not variables, because no variable sets them.
    #[must_use]
    pub fn settings(&self) -> Vec<(&'static str, String)> {
        let Self {
            server,
            logger,
            database,
            http,
            workers,
        } = self;
        let internal_port = server
            .internal_port
            .map_or_else(String::new, |p| p.to_string());
        [
            ("PORT", server.port.to_string()),
            ("BINDING", server.binding.clone()),
            ("HOST", server.host.clone()),
            (
                "HTTP_REQUEST_HEADER_READ_TIMEOUT_SECONDS",
                self.server.header_read_timeout_seconds.to_string(),
            ),
            ("INTERNAL_PORT", internal_port),
            ("PROXY_PROTOCOL_FROM", joined(&server.proxy_protocol_from)),
            (
                "KEEP_ALIVE_TIMEOUT_SECONDS",
                server.keep_alive_timeout_seconds.to_string(),
            ),
            (
                "SEND_STALL_TIMEOUT_SECONDS",
                server.send_stall_timeout_seconds.to_string(),
            ),
            ("MAX_CONNECTIONS", server.max_connections.to_string()),
            (
                "SHUTDOWN_TIMEOUT_SECONDS",
                server.shutdown_timeout_seconds.to_string(),
            ),
            (
                "SHUTDOWN_DRAIN_SECONDS",
                server.shutdown_drain_seconds.to_string(),
            ),
            ("LOG_ENABLE", logger.enable.to_string()),
            ("LOG_LEVEL", logger.level.to_string()),
            ("LOG_FORMAT", logger.format.to_string()),
            (
                "LOG_FILTER",
                logger.override_filter.clone().unwrap_or_default(),
            ),
            ("DB_URL", database.uri.clone()),
            ("DB_MIN_CONNECTIONS", database.min_connections.to_string()),
            ("DB_MAX_CONNECTIONS", database.max_connections.to_string()),
            ("DB_CONNECT_TIMEOUT", database.connect_timeout.to_string()),
            ("DB_IDLE_TIMEOUT", database.idle_timeout.to_string()),
            ("DB_LOGGING", database.enable_logging.to_string()),
            ("DB_AUTO_MIGRATE", database.auto_migrate.to_string()),
            (
                "DB_STATEMENT_TIMEOUT_MS",
                database.statement_timeout_ms.to_string(),
            ),
            ("DB_APPLICATION_NAME", database.application_name.clone()),
            ("DB_READ_ONLY", database.read_only.to_string()),
            (
                "dangerously_truncate",
                database.dangerously_truncate.to_string(),
            ),
            (
                "HTTP_REQUEST_BODY_LIMIT_BYTE_COUNT",
                http.body_limit.to_string(),
            ),
            ("HTTP_COMPRESSION", http.compression.to_string()),
            ("REQUEST_TIMEOUT_SECONDS", http.timeout_seconds.to_string()),
            (
                "timeout_overrides",
                http.timeout_overrides
                    .iter()
                    .map(|limit| format!("{}:{}", limit.path_suffix, limit.seconds))
                    .collect::<Vec<_>>()
                    .join(","),
            ),
            ("cross_site_paths", http.cross_site_paths.join(",")),
            ("CORS_ALLOWED_ORIGINS", http.cors_origins.join(",")),
            ("TRUSTED_PROXIES", joined(&http.trusted_proxies)),
            ("HTTP_HSTS", http.hsts.to_string()),
            ("HSTS_MAX_AGE_SECONDS", http.hsts_max_age.to_string()),
            (
                "HTTP_CONTENT_SECURITY_POLICY",
                http.csp.clone().unwrap_or_default(),
            ),
            (
                "HTTP_PERMISSIONS_POLICY",
                http.permissions_policy.clone().unwrap_or_default(),
            ),
            ("HTTP_LOG_TENANT", http.log_tenant.to_string()),
            ("WORKER_MODE", format!("{workers:?}")),
        ]
        .map(|(name, value)| (name, redact(name, &value)))
        .to_vec()
    }
}

