        let tables = ["todos".to_string(), "notes".to_string()];
        let text = super::row_security_problem("app", true, &tables);
        assert!(
            text.contains("role app is a superuser or has BYPASSRLS"),
            "{text}"
        );
        assert!(text.contains("todos, notes"), "{text}");
