    async fn a_sea_orm_pool_with_no_connection_is_unavailable() {
        let error = sea_orm::DbErr::ConnectionAcquire(sea_orm::error::ConnAcquireErr::Timeout);
        assert_unavailable(error.into()).await;
    }

