//! The PROXY protocol, versions 1 and 2, which a layer-4 load balancer sends at the start
//! of each connection to say whom the connection is from.
//!
//! [`crate::server`] reads it only from the ranges in `PROXY_PROTOCOL_FROM`, since anyone
//! else could write one. A connection from those ranges must start with a header, and one
//! that does not is closed. A connection from anywhere else is served as it is.

use std::{io, net::SocketAddr};

use ppp::{v1, v2};
use tokio::io::{AsyncRead, AsyncReadExt};

/// The longest version 1 header, as the protocol sets it.
const V1_MAX: usize = 107;

/// The fixed part of a version 2 header: the prefix, version and command, family, and
/// length.
const V2_FIXED: usize = 16;

/// The most bytes of addresses and extensions read after a version 2 header's fixed part.
/// Load balancers send a few dozen, so a longer one is refused rather than read.
pub(crate) const V2_MAX_REST: usize = 4096;

/// Read a PROXY header from the start of `stream`, and answer the client's address. A
/// header that names no client, as for a load balancer's own health check, answers
/// `peer`, the address that connected.
///
/// It reads exactly the header, so the bytes after it are left for HTTP.
///
/// # Errors
///
/// The connection ended, or did not start with a header this can read.
pub(crate) async fn read_header<S: AsyncRead + Unpin>(
    stream: &mut S,
    peer: SocketAddr,
) -> io::Result<SocketAddr> {
    // Both versions' headers are at least this long, and it is all of version 2's prefix.
    let mut start = [0_u8; 12];
    stream.read_exact(&mut start).await?;
    if start == v2::PROTOCOL_PREFIX {
        let mut header = Vec::from(start);
        header.resize(V2_FIXED, 0);
        stream.read_exact(&mut header[start.len()..]).await?;
        let rest = usize::from(u16::from_be_bytes([header[14], header[15]]));
        if rest > V2_MAX_REST {
            return Err(invalid(format!(
                "a PROXY v2 header of more than {V2_MAX_REST} bytes"
            )));
        }
        header.resize(V2_FIXED + rest, 0);
        stream.read_exact(&mut header[V2_FIXED..]).await?;
        let header = v2::Header::try_from(header.as_slice())
            .map_err(|error| invalid(format!("a bad PROXY v2 header: {error}")))?;
        return Ok(match (header.command, header.addresses) {
            (v2::Command::Proxy, v2::Addresses::IPv4(addresses)) => {
                SocketAddr::from((addresses.source_address, addresses.source_port))
            }
            (v2::Command::Proxy, v2::Addresses::IPv6(addresses)) => {
                SocketAddr::from((addresses.source_address, addresses.source_port))
            }
            // `LOCAL` is the balancer speaking for itself, and an unspecified or Unix
            // address names no client.
            _ => peer,
        });
    }
    if !start.starts_with(b"PROXY ") {
        return Err(invalid("no PROXY header".to_string()));
    }
    // A byte at a time, so as not to read past the line into the request.
    let mut header = Vec::from(start);
    while !header.ends_with(b"\r\n") {
        if header.len() >= V1_MAX {
            return Err(invalid(format!(
                "a PROXY v1 header of more than {V1_MAX} bytes"
            )));
        }
        header.push(stream.read_u8().await?);
    }
    let header = v1::Header::try_from(header.as_slice())
        .map_err(|error| invalid(format!("a bad PROXY v1 header: {error}")))?;
    Ok(match header.addresses {
        v1::Addresses::Tcp4(addresses) => {
            SocketAddr::from((addresses.source_address, addresses.source_port))
        }
        v1::Addresses::Tcp6(addresses) => {
            SocketAddr::from((addresses.source_address, addresses.source_port))
        }
        v1::Addresses::Unknown => peer,
    })
}

fn invalid(message: String) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, message)
}

#[cfg(test)]
mod tests {
    use super::*;

    const PEER: &str = "10.0.0.9:40000";

    async fn read(bytes: &[u8]) -> (io::Result<SocketAddr>, Vec<u8>) {
        let mut stream = bytes;
        let read = read_header(&mut stream, PEER.parse().unwrap()).await;
        (read, stream.to_vec())
    }

    fn v2(command: u8, family: u8, rest: &[u8]) -> Vec<u8> {
        let mut header = Vec::from(v2::PROTOCOL_PREFIX);
        header.push(0x20 | command);
        header.push(family);
        header.extend(u16::try_from(rest.len()).unwrap().to_be_bytes());
        header.extend(rest);
        header
    }

    #[tokio::test]
    async fn a_v1_header_names_the_client_and_leaves_the_request() {
        let (client, left) =
            read(b"PROXY TCP4 192.0.2.7 10.0.0.1 51000 1241\r\nGET / HTTP/1.1\r\n").await;
        assert_eq!(client.unwrap(), "192.0.2.7:51000".parse().unwrap());
        assert_eq!(left, b"GET / HTTP/1.1\r\n");
        let (client, _) = read(b"PROXY TCP6 2001:db8::7 2001:db8::1 51000 1241\r\n").await;
        assert_eq!(client.unwrap(), "[2001:db8::7]:51000".parse().unwrap());
    }

    #[tokio::test]
    async fn a_v2_header_names_the_client_and_leaves_the_request() {
        let mut bytes = v2(
            1,
            0x11,
            &[
                192, 0, 2, 7, 10, 0, 0, 1, 0xc7, 0x38, 0x04, 0xd9, 0x04, 0, 1, 42,
            ],
        );
        bytes.extend(b"GET / HTTP/1.1\r\n");
        let (client, left) = read(&bytes).await;
        assert_eq!(client.unwrap(), "192.0.2.7:51000".parse().unwrap());
        assert_eq!(left, b"GET / HTTP/1.1\r\n");
    }

    #[tokio::test]
    async fn a_header_that_names_no_client_keeps_the_peer() {
        let peer: SocketAddr = PEER.parse().unwrap();
        assert_eq!(read(b"PROXY UNKNOWN\r\n").await.0.unwrap(), peer);
        // The balancer's own health check.
        assert_eq!(read(&v2(0, 0, &[])).await.0.unwrap(), peer);
    }

    #[tokio::test]
    async fn a_missing_long_or_bad_header_is_refused() {
        assert!(read(b"GET / HTTP/1.1\r\nHost: x\r\n\r\n").await.0.is_err());
        assert!(read(b"PROXY TCP4 192.0.2.7").await.0.is_err());
        let long = format!("PROXY UNKNOWN {}\r\n", "x".repeat(V1_MAX));
        assert!(read(long.as_bytes()).await.0.is_err());
        assert!(
            read(b"PROXY TCP4 not-an-address 10.0.0.1 1 2\r\n")
                .await
                .0
                .is_err()
        );
        let mut long = Vec::from(v2::PROTOCOL_PREFIX);
        long.extend([0x21, 0x11]);
        long.extend(u16::try_from(V2_MAX_REST + 1).unwrap().to_be_bytes());
        long.extend(vec![0; V2_MAX_REST + 1]);
        assert!(read(&long).await.0.is_err());
    }
}

//! The Postgres job queue, from [`axa_postgres_job_queue`], with [`BackgroundWorker`] jobs.
//!
//! The engine is `axa-postgres-job-queue`: the `axa_queue` table, claims with `FOR UPDATE SKIP
//! LOCKED`, retries, stale recovery, retention, the pool of job loops, delayed jobs,
//! priorities, job status, and recurring schedules. Its crate documentation says how
//! each behaves. This module puts the [`BackgroundWorker`] trait over it, so a job
//! type is registered by its type and queued by [`BackgroundWorker::perform_later`],
//! and its errors are [`crate::Error`].
//!
//! # Running it
//!
//! Nothing runs jobs by itself. A service needs a process calling [`Queue::run`],
//! usually through `start --all` or `start --worker`, and [`warn_if_unserved`] says
//! so at boot when it has none. Several processes may run at once.

use std::{sync::Arc, time::Duration};

use serde::{Serialize, de::DeserializeOwned};
use sqlx::{PgConnection, PgExecutor, PgPool, Postgres, Transaction};
use tokio::sync::watch;
use uuid::Uuid;

pub use axa_postgres_job_queue::{
    Act, ActKind, Counts, JobInfo, JobState, MAX_REASON_CHARS, NewJob, QueueOptions, RetryAfter,
    SETUP_STATEMENTS, Schedule, ScheduleInfo, Timestamp,
};

use crate::{AppContext, Error, Result, worker::BackgroundWorker};

impl From<axa_postgres_job_queue::Error> for Error {
    fn from(error: axa_postgres_job_queue::Error) -> Self {
        match error {
            axa_postgres_job_queue::Error::Database(error) => Self::Sqlx(error),
            axa_postgres_job_queue::Error::Encode(error) => Self::JSON(error),
            axa_postgres_job_queue::Error::Job(text) => Self::Worker(text),
            error @ (axa_postgres_job_queue::Error::NotACode { .. }
            | axa_postgres_job_queue::Error::NotATenant) => Self::BadRequest(error.to_string()),
            other => Self::Worker(other.to_string()),
        }
    }
}

/// Warn when a service queues jobs and nothing here will run them, returning
/// whether it warned.
///
/// Queued jobs then wait forever, and nothing else says so: the request that
/// queued the job has already succeeded.
pub fn warn_if_unserved(ctx: &AppContext, worker_running: bool) -> bool {
    let unserved = ctx.queue_provider.is_some() && !worker_running;
    if unserved {
        tracing::warn!(
            "jobs are queued but this process runs no worker: use `start --all`, \
             or run `start --worker` separately"
        );
    }
    unserved
}

/// A job for worker `W` with `args`, with `W`'s name and limit on tries, to delay,
/// prioritise, or queue in a batch.
///
/// ```ignore
/// let later = queue::job::<ReportWorker, _>(&Args { id })?.run_in(Duration::from_mins(5));
/// queue::enqueue_job_on(&mut *transaction, &later).await?;
/// ```
///
/// # Errors
///
/// Fails when the arguments cannot be encoded.
pub fn job<W, A>(args: &A) -> Result<NewJob>
where
    W: BackgroundWorker<A>,
    A: Serialize + DeserializeOwned + Send + Sync + 'static,
{
    let job =
        NewJob::new(W::class_name(), serde_json::to_value(args)?).max_attempts(W::max_attempts());
    Ok(match W::timeout() {
        Some(limit) => job.timeout(limit),
        None => job,
    })
}

/// Add a job for worker `W` on `executor`, usually the caller's transaction, and
/// return its id. The job then commits or rolls back with the transaction.
///
/// ```ignore
/// let mut transaction = pool.begin().await?;
/// sqlx::query("INSERT INTO reports (id) VALUES ($1)")
///     .bind(id)
///     .execute(&mut *transaction)
///     .await?;
/// enqueue_on::<ReportWorker, _, _>(&mut *transaction, &Args { id }).await?;
/// transaction.commit().await?;
/// ```
///
/// # Errors
///
/// Fails when the arguments cannot be encoded, or on a database error.
pub async fn enqueue_on<'e, W, A, E>(executor: E, args: &A) -> Result<String>
where
    W: BackgroundWorker<A>,
    A: Serialize + DeserializeOwned + Send + Sync + 'static,
    E: PgExecutor<'e>,
{
    enqueue_job_on(executor, &job::<W, A>(args)?).await
}

/// Add `job` on `executor`, usually the caller's transaction, and return its id.
/// Build `job` with [`job`] to delay it or give it a priority.
///
/// # Errors
///
/// Fails on a database error.
pub async fn enqueue_job_on<'e, E: PgExecutor<'e>>(executor: E, job: &NewJob) -> Result<String> {
    Ok(axa_postgres_job_queue::enqueue_on(executor, job)
        .await?
        .to_string())
}

/// Add every job in `jobs` on `connection`, returning their ids in order. On a
/// transaction they commit or roll back together.
///
/// # Errors
///
/// Fails on a database error.
pub async fn enqueue_all_on(connection: &mut PgConnection, jobs: &[NewJob]) -> Result<Vec<String>> {
    let ids = axa_postgres_job_queue::enqueue_all_on(connection, jobs).await?;
    Ok(ids.iter().map(Uuid::to_string).collect())
}

/// An id that is not one matches no job, and `by` and `reason` are still checked.
fn job_id(id: &str) -> Uuid {
    Uuid::parse_str(id).unwrap_or_else(|_| Uuid::nil())
}

/// Cancel the job `id` if it is still queued, as an act of `by`, for `reason`, kept in
/// the caller's transaction with the service's own audit row. Answers whether it was
/// cancelled. A job in any other state, or no such job, writes no act. See
/// [`axa_postgres_job_queue::cancel`].
///
/// # Errors
///
/// Fails on a database error, and with [`Error::BadRequest`] when `by` or `reason` is
/// empty, longer than [`MAX_REASON_CHARS`], or has a line break.
pub async fn cancel(
    transaction: &mut Transaction<'_, Postgres>,
    id: &str,
    by: &str,
    reason: &str,
) -> Result<bool> {
    Ok(axa_postgres_job_queue::cancel(transaction, job_id(id), by, reason).await?)
}

/// Queue the job `id` again for one more try, if it failed or waits for review, as an
/// act of `by`, for `reason`, kept in the caller's transaction with the service's own
/// audit row. Answers whether it was queued again. A job in any other state, or no
/// such job, writes no act. See [`axa_postgres_job_queue::retry`].
///
/// # Errors
///
/// Fails on a database error, and with [`Error::BadRequest`] when `by` or `reason` is
/// empty, longer than [`MAX_REASON_CHARS`], or has a line break.
pub async fn retry(
    transaction: &mut Transaction<'_, Postgres>,
    id: &str,
    by: &str,
    reason: &str,
) -> Result<bool> {
    Ok(axa_postgres_job_queue::retry(transaction, job_id(id), by, reason).await?)
}

/// A Postgres-backed job queue whose jobs are [`BackgroundWorker`]s.
#[derive(Debug)]
pub struct Queue {
    /// Shared only once [`Queue::run`] starts, which takes the queue whole, so
    /// registering through `&mut self` always has it alone.
    engine: Arc<axa_postgres_job_queue::Queue>,
}

impl Queue {
    fn wrap(engine: axa_postgres_job_queue::Queue) -> Self {
        Self {
            engine: Arc::new(engine),
        }
    }

    fn engine_mut(&mut self) -> &mut axa_postgres_job_queue::Queue {
        Arc::get_mut(&mut self.engine).expect("a queue is shared only once it runs")
    }

    /// Connect to tables that a migration made, and change no schema, for a database
    /// role that may not. A migration runs [`SETUP_STATEMENTS`].
    ///
    /// # Errors
    ///
    /// Fails when the database cannot be reached, or a table is missing or out of
    /// date, so a service finds out at boot rather than at its first job.
    pub async fn connect_existing(uri: &str, options: QueueOptions) -> Result<Self> {
        Ok(Self::wrap(
            axa_postgres_job_queue::Queue::connect_existing(uri, options).await?,
        ))
    }

    /// Connect and create the tables if needed, which runs DDL at boot. Use
    /// [`Queue::connect_existing`] where a service's role may not.
    ///
    /// # Errors
    ///
    /// Fails when the database cannot be reached or the tables not created.
    pub async fn connect(uri: &str, options: QueueOptions) -> Result<Self> {
        Ok(Self::wrap(
            axa_postgres_job_queue::Queue::connect(uri, options).await?,
        ))
    }

    /// The engine, for what this module does not wrap.
    #[must_use]
    pub fn engine(&self) -> &axa_postgres_job_queue::Queue {
        &self.engine
    }

    /// The pool, for a service's own queries.
    #[must_use]
    pub fn pool(&self) -> &PgPool {
        self.engine.pool()
    }

    /// Register a worker to handle its jobs. A job queued for a tenant goes to the
    /// worker's [`BackgroundWorker::perform_for`], which refuses it unless the worker
    /// takes a tenant.
    pub fn register<A, W>(&mut self, worker: W)
    where
        A: Serialize + DeserializeOwned + Send + Sync + 'static,
        W: BackgroundWorker<A> + 'static,
    {
        let worker = Arc::new(worker);
        self.engine_mut()
            .handle_with_tenant(W::class_name(), move |tenant, args| {
                let worker = worker.clone();
                async move {
                    let args: A = serde_json::from_value(args).map_err(Error::from)?;
                    // Boxed, so the queue finds a `RetryAfter` inside.
                    worker.perform_for(tenant, args).await.map_err(|error| {
                        let boxed: Box<dyn std::error::Error + Send + Sync> = match error {
                            Error::RetryAfter(retry) => Box::new(retry),
                            other => Box::new(other),
                        };
                        boxed
                    })
                }
            });
    }

    /// Run at most `jobs` of worker `W`'s jobs at once in this process, and at least
    /// one. The limit is per process, not across replicas.
    pub fn limit<A, W>(&mut self, jobs: usize)
    where
        A: Serialize + DeserializeOwned + Send + Sync + 'static,
        W: BackgroundWorker<A>,
    {
        self.engine_mut().limit(W::class_name(), jobs);
    }

    /// Queue a job of worker `W` with `args` every `interval`, under the schedule
    /// name `name`. See [`Schedule`] for the first time and what happens to missed
    /// and overlapping times.
    ///
    /// # Errors
    ///
    /// Fails when the arguments cannot be encoded.
    ///
    /// # Panics
    ///
    /// When the name is empty, over 200 characters, or used twice, or the interval
    /// is under a second.
    pub fn every<A, W>(&mut self, name: &str, interval: Duration, args: &A) -> Result<()>
    where
        A: Serialize + DeserializeOwned + Send + Sync + 'static,
        W: BackgroundWorker<A>,
    {
        let job = job::<W, A>(args)?;
        self.engine_mut()
            .schedule(Schedule::every(name, interval, job));
        Ok(())
    }

    /// Queue a job of worker `W` with `args` at each time the cron `pattern` names, in
    /// UTC, under the schedule name `name`, such as `"0 2 * * *"` for 02:00 each day.
    /// See [`Schedule::cron`].
    ///
    /// # Errors
    ///
    /// Fails when the arguments cannot be encoded.
    ///
    /// # Panics
    ///
    /// When the name is empty, over 200 characters, or used twice, or the pattern
    /// does not parse or names no time to come.
    pub fn cron<A, W>(&mut self, name: &str, pattern: &str, args: &A) -> Result<()>
    where
        A: Serialize + DeserializeOwned + Send + Sync + 'static,
        W: BackgroundWorker<A>,
    {
        let job = job::<W, A>(args)?;
        self.engine_mut()
            .schedule(Schedule::cron(name, pattern, job));
        Ok(())
    }

    /// Add a schedule built with [`Schedule::every`] or [`Schedule::cron`], as for a
    /// first time.
    ///
    /// # Panics
    ///
    /// When a schedule of that name was added already.
    pub fn schedule(&mut self, schedule: Schedule) {
        self.engine_mut().schedule(schedule);
    }

    /// Add a job and return its id.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn enqueue(&self, name: &str, args: serde_json::Value) -> Result<String> {
        Ok(self.engine.enqueue(name, args).await?.to_string())
    }

    /// Add a job with its own limit on tries, or the queue's when `None`.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn enqueue_limited(
        &self,
        name: &str,
        args: serde_json::Value,
        max_attempts: Option<i32>,
    ) -> Result<String> {
        Ok(self
            .engine
            .enqueue_limited(name, args, max_attempts)
            .await?
            .to_string())
    }

    /// Add `job` and return its id.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn enqueue_job(&self, job: &NewJob) -> Result<String> {
        Ok(self.engine.enqueue_job(job).await?.to_string())
    }

    /// Add every job in `jobs` in one transaction, so all are queued or none.
    ///
    /// # Errors
    ///
    /// Fails on a database error, and then none was queued.
    pub async fn enqueue_all(&self, jobs: &[NewJob]) -> Result<Vec<String>> {
        let ids = self.engine.enqueue_all(jobs).await?;
        Ok(ids.iter().map(Uuid::to_string).collect())
    }

    /// What the queue knows of the job `id`, or `None` when there is no such job,
    /// including when `id` is not one.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn job(&self, id: &str) -> Result<Option<JobInfo>> {
        let Ok(id) = Uuid::parse_str(id) else {
            return Ok(None);
        };
        Ok(self.engine.job(id).await?)
    }

    /// Every act a person did to the job `id`, oldest first, kept after retention
    /// deletes the job's row. None when `id` is not one.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn acts(&self, id: &str) -> Result<Vec<Act>> {
        let Ok(id) = Uuid::parse_str(id) else {
            return Ok(Vec::new());
        };
        Ok(self.engine.acts(id).await?)
    }

    /// How many jobs are in each state, for metrics.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn counts(&self) -> Result<Counts> {
        Ok(self.engine.counts().await?)
    }

    /// A queue on a pool nothing listens to, for testing what depends on it.
    #[cfg(all(test, axa_db = "none"))]
    pub(crate) fn unreachable() -> Self {
        let pool = sqlx::postgres::PgPoolOptions::new()
            .acquire_timeout(Duration::from_millis(50))
            .connect_lazy("postgres://axa:axa@127.0.0.1:1/axa")
            .unwrap();
        Self::wrap(axa_postgres_job_queue::Queue::from_pool(
            pool,
            QueueOptions::default(),
        ))
    }

    /// Check the database connection.
    ///
    /// # Errors
    ///
    /// Fails when the database does not answer.
    pub async fn ping(&self) -> Result<()> {
        Ok(self.engine.ping().await?)
    }

    /// Recover jobs abandoned by a worker that died: queue again those with
    /// attempts left and fail the rest, returning how many were queued again.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn requeue_stale(&self) -> Result<u64> {
        Ok(self.engine.requeue_stale().await?)
    }

    /// Delete finished and cancelled rows older than the retention period,
    /// returning how many went.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn purge_finished(&self) -> Result<u64> {
        Ok(self.engine.purge_finished().await?)
    }

    /// Queue a job for each schedule that is due, returning how many were queued.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn tick_schedules(&self) -> Result<usize> {
        Ok(self.engine.tick_schedules().await?)
    }

    /// Every schedule the table holds, archived or not, with its last job's state.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn schedules(&self) -> Result<Vec<ScheduleInfo>> {
        Ok(self.engine.schedules().await?)
    }

    /// Archive the schedules no live process has in code, returning how many.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn archive_schedules(&self) -> Result<u64> {
        Ok(self.engine.archive_schedules().await?)
    }

    /// Claim and run one job, returning whether there was one. A job's own
    /// failure is recorded on its row, not returned.
    ///
    /// # Errors
    ///
    /// Fails on a database error.
    pub async fn run_one(&self) -> Result<bool> {
        Ok(self.engine.run_one().await?)
    }

    /// Run job loops, housekeeping, and schedules until `shutdown` changes to
    /// `true`. Jobs in progress finish first. `start` bounds that wait by the
    /// shutdown time limit, and stops the jobs still running at it.
    pub async fn run(self: Arc<Self>, shutdown: watch::Receiver<bool>) {
        self.engine.clone().run(shutdown).await;
    }
}

/// These need a real Postgres, so they are ignored by default. Run them with
/// `AXA_TEST_DB_URL=postgres://... cargo test --all-features -- --ignored`.
#[cfg(all(
    test,
    not(any(
        axa_db = "postgres_seaorm",
        axa_db = "mysql_seaorm",
        axa_db = "sqlite_seaorm",
        axa_db = "postgres_toasty",
        axa_db = "mysql_toasty"
    ))
))]
mod tests {
    use super::*;
    use crate::{
        AppContext, Environment,
        config::{Config, Defaults},
    };
    use async_trait::async_trait;
    use serde::Deserialize;
    use sqlx::{Row, postgres::PgPoolOptions};
    use std::sync::atomic::{AtomicUsize, Ordering};

    static COUNT: AtomicUsize = AtomicUsize::new(0);

    /// Held for a whole test: these tests share one table, and each one
    /// starts by emptying or dropping it.
    static TABLE: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());

    #[derive(Serialize, Deserialize)]
    struct Args {
        fail: bool,
    }

    struct CountWorker;

    #[async_trait]
    impl BackgroundWorker<Args> for CountWorker {
        fn build(_ctx: &AppContext) -> Self {
            Self
        }

        async fn perform(&self, args: Args) -> Result<()> {
            if args.fail {
                return Err(Error::Worker("told to fail".to_string()));
            }
            COUNT.fetch_add(1, Ordering::SeqCst);
            Ok(())
        }
    }

    struct PanicWorker;

    #[async_trait]
    impl BackgroundWorker<()> for PanicWorker {
        fn build(_ctx: &AppContext) -> Self {
            Self
        }

        async fn perform(&self, (): ()) -> Result<()> {
            panic!("the job's own bug");
        }
    }

    /// Works for as long as its argument says.
    struct SlowWorker;

    #[async_trait]
    impl BackgroundWorker<u64> for SlowWorker {
        fn build(_ctx: &AppContext) -> Self {
            Self
        }

        async fn perform(&self, millis: u64) -> Result<()> {
            tokio::time::sleep(Duration::from_millis(millis)).await;
            Ok(())
        }
    }

    /// Always fails, and may be tried three times.
    struct RetryingWorker;

    #[async_trait]
    impl BackgroundWorker<()> for RetryingWorker {
        fn build(_ctx: &AppContext) -> Self {
