    static TENANTS: std::sync::Mutex<Vec<Option<String>>> = std::sync::Mutex::new(Vec::new());

    #[async_trait]
    impl BackgroundWorker<()> for TenantWorker {
        fn build(_ctx: &AppContext) -> Self {
