//! Serving a router until the process is asked to stop.

#[cfg(feature = "queue")]
use std::sync::OnceLock;
use std::{
    convert::Infallible,
    future::Future,
    io,
    net::SocketAddr,
    pin::{Pin, pin},
    sync::Arc,
    task::{Context, Poll},
    time::Duration,
};

use axum::{
    Router,
    body::Body,
    extract::{ConnectInfo, FromRequestParts},
    http::{Request, request::Parts},
    middleware::{self, Next},
    response::{IntoResponse, Response},
};
use hyper::{
    body::{Body as HttpBody, Bytes, Frame, Incoming, SizeHint},
    server::conn::http1,
    service::{Service, service_fn},
};
use hyper_util::{rt::TokioIo, service::TowerToHyperService};
use tokio::{
    io::{AsyncRead, AsyncWrite, ReadBuf},
    net::{TcpListener, TcpStream},
    sync::{Notify, OwnedSemaphorePermit, Semaphore, watch},
    time::Instant,
};

#[cfg(feature = "queue")]
use crate::{Error, queue::Queue};
use crate::{
    Result,
    client::ProxyNet,
    config::{
        DEFAULT_HEADER_READ_TIMEOUT_SECONDS, DEFAULT_KEEP_ALIVE_TIMEOUT_SECONDS,
        DEFAULT_SEND_STALL_TIMEOUT_SECONDS, Server,
    },
};

/// The most connections a server holds open at once unless `MAX_CONNECTIONS` says
/// otherwise. More wait to be accepted.
pub const MAX_CONNECTIONS: usize = 10_000;

/// Whether the server serving this request has begun to shut down, for a handler to
/// take as an extractor. A long-lived response, such as a WebSocket or a stream of
/// server-sent events, waits on [`Shutdown::begun`] and ends itself, rather than being
/// cut off at the shutdown time limit. A request served other than by this module's
/// server, as in a test, gets one that never begins.
///
/// ```
/// use axa::server::Shutdown;
///
/// async fn events(shutdown: Shutdown) -> &'static str {
///     tokio::select! {
///         () = shutdown.begun() => "shutting down",
///         () = std::future::pending::<()>() => unreachable!(),
///     }
/// }
/// # let _ = events;
/// ```
#[derive(Clone, Debug)]
pub struct Shutdown(watch::Receiver<bool>);

impl Shutdown {
    /// One that never begins. Every one shares a single sender that lives as long
    /// as the process, so calling this for each request costs no memory that stays.
    #[must_use]
    pub fn never() -> Self {
        static NEVER: std::sync::OnceLock<watch::Sender<bool>> = std::sync::OnceLock::new();
        Self(NEVER.get_or_init(|| watch::channel(false).0).subscribe())
    }

    /// One that begins when `begun` turns `true`, for a test.
    #[cfg(all(test, axa_db = "none"))]
    pub(crate) const fn from_receiver(begun: watch::Receiver<bool>) -> Self {
        Self(begun)
    }

    /// Whether shutdown has begun.
    #[must_use]
    pub fn has_begun(&self) -> bool {
        *self.0.borrow()
    }

    /// Wait until shutdown begins.
    pub async fn begun(&self) {
        let mut begun = self.0.clone();
        // A sender dropped is a server gone, which is a shutdown too.
        let _ = begun.wait_for(|begun| *begun).await;
    }
}

impl<S: Send + Sync> FromRequestParts<S> for Shutdown {
    type Rejection = Infallible;

    fn from_request_parts(
        parts: &mut Parts,
        _state: &S,
    ) -> impl Future<Output = Result<Self, Self::Rejection>> + Send {
        let shutdown = parts
            .extensions
            .get::<Self>()
            .cloned()
            .unwrap_or_else(Self::never);
        std::future::ready(Ok(shutdown))
    }
}

/// Resolve when the process receives `SIGTERM` or Ctrl-C.
///
/// # Panics
///
/// If the signal handlers cannot be installed.
pub async fn shutdown_signal() {
    let ctrl_c = async {
        tokio::signal::ctrl_c()
            .await
            .expect("install Ctrl-C handler");
    };
    #[cfg(unix)]
    let terminate = async {
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .expect("install SIGTERM handler")
            .recv()
            .await;
    };
    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();
    tokio::select! {
        () = ctrl_c => {},
        () = terminate => {},
    }
}

/// Serve `router` until [`shutdown_signal`], letting in-flight requests
/// finish.
///
/// # Errors
///
/// Fails when the address cannot be bound.
pub async fn serve(router: Router, config: &Server) -> Result<()> {
    bind_and_serve(router, config, shutdown_signal()).await
}

/// Serve `router` on `listener` until `shutdown` resolves, letting in-flight
/// requests finish. The limits on connections are the defaults: see [`Server`].
///
/// # Errors
///
/// Fails when the server fails.
pub async fn serve_until(
    router: Router,
    listener: TcpListener,
    shutdown: impl Future<Output = ()> + Send + 'static,
) -> Result<()> {
    let limits = Limits::new(
        DEFAULT_HEADER_READ_TIMEOUT_SECONDS,
        DEFAULT_KEEP_ALIVE_TIMEOUT_SECONDS,
        DEFAULT_SEND_STALL_TIMEOUT_SECONDS,
        MAX_CONNECTIONS,
    );
    accept_until(router, listener, limits, shutdown).await
}

/// What one connection is allowed.
#[derive(Clone, Copy)]
struct Limits {
    /// From the start of a connection or a request, to the end of its headers.
    header_read: Option<Duration>,
    /// From the end of a response, to the start of the next request.
    keep_alive: Option<Duration>,
    /// From a write the client's socket cannot take, to the next that it can.
    send_stall: Option<Duration>,
    /// Connections open at once.
    max_connections: usize,
    /// How long to keep accepting once told to stop.
    drain: Duration,
}

impl Limits {
    /// Limits from settings, where a time of `0` means no limit. There is always a
    /// connection limit, as `Semaphore` with no places would never accept one.
    fn new(
        header_read_seconds: u64,
        keep_alive_seconds: u64,
        send_stall_seconds: u64,
        max_connections: usize,
    ) -> Self {
        let seconds = |seconds| (seconds > 0).then(|| Duration::from_secs(seconds));
        Self {
            header_read: seconds(header_read_seconds),
            keep_alive: seconds(keep_alive_seconds),
            send_stall: seconds(send_stall_seconds),
            max_connections: max_connections.clamp(1, Semaphore::MAX_PERMITS),
            drain: Duration::ZERO,
        }
    }
}

impl From<&Server> for Limits {
    fn from(config: &Server) -> Self {
        Self {
            drain: Duration::from_secs(config.shutdown_drain_seconds),
            ..Self::new(
                config.header_read_timeout_seconds,
                config.keep_alive_timeout_seconds,
                config.send_stall_timeout_seconds,
                config.max_connections,
            )
        }
    }
}

/// What a connection is waiting for, and until when.
#[derive(Clone, Copy)]
enum Phase {
    /// The rest of a request's headers.
    Head(Option<Instant>),
    /// A next request. A client or a load balancer may keep this connection for one.
    Idle(Option<Instant>),
    /// The service, which has its own limits, so this one is set only while a client
    /// that has stopped reading holds up the response.
    Serving(Option<Instant>),
}

/// Moves a connection between its phases. `hyper` has one timer, which runs across
/// both a request's headers and the wait between requests, and these need different
/// limits: a short one for a client that stalls, and for an idle connection one longer
/// than the load balancer in front, which would otherwise reuse a connection as it
/// closes. So `hyper`'s timer stays off and this does both.
#[derive(Clone)]
struct Tracker {
    phase: watch::Sender<Phase>,
    limits: Limits,
}

impl Tracker {
    fn new(limits: Limits) -> Self {
        let deadline = limits.header_read.and_then(from_now);
        Self {
            phase: watch::Sender::new(Phase::Head(deadline)),
            limits,
        }
    }

    /// The first bytes of the next request started its header limit.
    fn received(&self) {
        self.phase.send_if_modified(|phase| {
            let idle = matches!(phase, Phase::Idle(_));
            if idle {
                *phase = Phase::Head(self.limits.header_read.and_then(from_now));
            }
            idle
        });
    }

    fn serving(&self) {
        self.phase.send_replace(Phase::Serving(None));
    }

    fn finished(&self) {
        let deadline = self.limits.keep_alive.and_then(from_now);
        self.phase.send_replace(Phase::Idle(deadline));
    }

    /// Bytes reached the socket, so a response is still going out, and the connection
    /// is not yet idle. A client that stops reading stops this, and is dropped.
    fn sent(&self) {
        self.phase.send_if_modified(|phase| match phase {
            Phase::Idle(deadline) => {
                *deadline = self.limits.keep_alive.and_then(from_now);
                true
            }
            Phase::Serving(deadline) => deadline.take().is_some(),
            Phase::Head(_) => false,
        });
    }

    /// What a write to the socket came to.
    fn wrote(&self, polled: &Poll<io::Result<usize>>) {
        match polled {
            Poll::Ready(Ok(written)) if *written > 0 => self.sent(),
            Poll::Pending => self.blocked(),
            Poll::Ready(_) => {}
        }
    }

    /// The socket can take no more, which is the only sign of a client that has stopped
    /// reading. A handler with nothing to send never gets here. Waiting does not move a
    /// deadline already set, so only a write that goes through buys more time.
    fn blocked(&self) {
        let Some(limit) = self.limits.send_stall.and_then(from_now) else {
            return;
        };
        self.phase.send_if_modified(|phase| match phase {
            Phase::Serving(deadline) | Phase::Idle(deadline) => {
                let earliest = deadline.map_or(limit, |deadline| deadline.min(limit));
                deadline.replace(earliest) != Some(earliest)
            }
            Phase::Head(_) => false,
        });
    }
}

/// When a limit ends, or `None` for one too long for the clock to hold, which is no
/// limit: `Instant` panics on adding it, and any such limit is meant as for ever.
fn from_now(limit: Duration) -> Option<Instant> {
    Instant::now().checked_add(limit)
}

/// Resolve once a connection is past its deadline.
async fn overdue(mut phase: watch::Receiver<Phase>) {
    loop {
        let deadline = match *phase.borrow_and_update() {
            Phase::Head(deadline) | Phase::Idle(deadline) | Phase::Serving(deadline) => deadline,
        };
        let expires = async {
            match deadline {
                Some(deadline) => tokio::time::sleep_until(deadline).await,
                None => std::future::pending().await,
            }
        };
        tokio::select! {
            () = expires => return,
            changed = phase.changed() => {
                if changed.is_err() {
                    return std::future::pending().await;
                }
            }
        }
    }
}

/// A connection that tells its [`Tracker`] when bytes move. It holds the connection's
/// slot, because an upgrade outlives the task that serves the connection, and only the
/// stream lasts as long as the socket.
struct Tracked {
    stream: TcpStream,
    tracker: Tracker,
    _slot: OwnedSemaphorePermit,
}

impl AsyncRead for Tracked {
    fn poll_read(
        self: Pin<&mut Self>,
        context: &mut Context<'_>,
        buffer: &mut ReadBuf<'_>,
    ) -> Poll<io::Result<()>> {
        let this = self.get_mut();
        let before = buffer.filled().len();
        let polled = Pin::new(&mut this.stream).poll_read(context, buffer);
        if buffer.filled().len() > before {
            this.tracker.received();
        }
        polled
    }
}

impl AsyncWrite for Tracked {
    fn poll_write(
        self: Pin<&mut Self>,
        context: &mut Context<'_>,
        bytes: &[u8],
    ) -> Poll<io::Result<usize>> {
        let this = self.get_mut();
        let polled = Pin::new(&mut this.stream).poll_write(context, bytes);
        this.tracker.wrote(&polled);
        polled
    }

    fn poll_flush(self: Pin<&mut Self>, context: &mut Context<'_>) -> Poll<io::Result<()>> {
        Pin::new(&mut self.get_mut().stream).poll_flush(context)
    }

    fn poll_shutdown(self: Pin<&mut Self>, context: &mut Context<'_>) -> Poll<io::Result<()>> {
        Pin::new(&mut self.get_mut().stream).poll_shutdown(context)
    }

    fn poll_write_vectored(
        self: Pin<&mut Self>,
        context: &mut Context<'_>,
        buffers: &[io::IoSlice<'_>],
    ) -> Poll<io::Result<usize>> {
        let this = self.get_mut();
        let polled = Pin::new(&mut this.stream).poll_write_vectored(context, buffers);
        this.tracker.wrote(&polled);
        polled
    }

    fn is_write_vectored(&self) -> bool {
        self.stream.is_write_vectored()
    }
}

/// Tells a [`Tracker`] the service has finished its response. `hyper` drops the body
/// when it holds the last of it, which can be long before that reaches the client, so
/// [`Tracker::sent`] keeps the connection from being taken for idle until then.
struct Finished(Tracker);

impl Drop for Finished {
    fn drop(&mut self) {
        self.0.finished();
    }
}

/// A response body that reports its end.
struct TrackedBody {
    body: Body,
    _finished: Finished,
}

impl HttpBody for TrackedBody {
    type Data = Bytes;
    type Error = axum::Error;

    fn poll_frame(
        self: Pin<&mut Self>,
        context: &mut Context<'_>,
    ) -> Poll<Option<std::result::Result<Frame<Bytes>, axum::Error>>> {
        Pin::new(&mut self.get_mut().body).poll_frame(context)
    }

    fn is_end_stream(&self) -> bool {
        self.body.is_end_stream()
    }

    fn size_hint(&self) -> SizeHint {
        self.body.size_hint()
    }
}

/// Take a slot, then the next connection. Each is safe to cancel, so shutdown can
/// interrupt this at any point.
async fn next_connection(
    listener: &TcpListener,
    slots: &Arc<Semaphore>,
) -> (TcpStream, SocketAddr, OwnedSemaphorePermit) {
    let slot = if let Ok(slot) = slots.clone().try_acquire_owned() {
        slot
    } else {
        tracing::warn!("at the connection limit, so new connections wait");
        slots
            .clone()
            .acquire_owned()
            .await
            .expect("the slots are never closed")
    };
    loop {
        match listener.accept().await {
            Ok((stream, address)) => return (stream, address, slot),
            // Running out of file descriptors, say. It passes, and a tight loop would
            // not help it to.
            Err(error) => {
                tracing::warn!(%error, "could not accept a connection");
                tokio::time::sleep(Duration::from_secs(1)).await;
            }
        }
    }
}

/// The connection loop. This is `axum::serve` plus the limits in [`Limits`], which
/// `axum::serve` cannot set: without them, a client that sends nothing, or trickles out
/// its headers, holds a connection and a task for as long as it likes, and enough of
/// them use up the process's file descriptors.
///
/// It speaks HTTP/1 only, as this crate has always been built to. The limits count a
/// connection as one request at a time, and detecting the protocol first would wait,
/// with no limit, for a client's first bytes. A proxy in front can offer HTTP/2.
///
/// Past its limit it stops accepting, so a connection waits in the listen queue for a
/// place rather than being refused.
async fn accept_until(
    router: Router,
    listener: TcpListener,
    limits: Limits,
    shutdown: impl Future<Output = ()> + Send + 'static,
) -> Result<()> {
    accept_with(router, listener, limits, Arc::from([]), shutdown).await
}

/// [`accept_until`], reading a PROXY protocol header first from each connection that
/// comes from `proxy_from`.
async fn accept_with(
    router: Router,
    listener: TcpListener,
    limits: Limits,
    proxy_from: Arc<[ProxyNet]>,
    shutdown: impl Future<Output = ()> + Send + 'static,
) -> Result<()> {
    let mut builder = http1::Builder::new();
    // `Tracker` does this, as it says.
    builder.header_read_timeout(None);
    let slots = Arc::new(Semaphore::new(limits.max_connections));
    // Each connection holds a receiver, so the sender sees when the last has gone.
    let (stop, stopping) = watch::channel(false);
    // Every request holds one, so a handler and readiness can see shutdown begin.
    let (announce, announced) = watch::channel(false);
    let accept = |(stream, address, slot)| {
        spawn_connection(
            &builder,
            &router,
            limits,
            Shutdown(announced.clone()),
            stopping.clone(),
            &proxy_from,
            (stream, address, slot),
        );
    };
    let mut shutdown = pin!(shutdown);
    loop {
        tokio::select! {
            next = next_connection(&listener, &slots) => accept(next),
            () = &mut shutdown => break,
        }
    }
    // Readiness answers `503` from here, while the drain keeps accepting, so that an
    // orchestrator takes the service out of rotation before it stops listening.
    let _ = announce.send(true);
    let drain = tokio::time::sleep(limits.drain);
    let mut drain = pin!(drain);
    loop {
        tokio::select! {
            next = next_connection(&listener, &slots) => accept(next),
            () = &mut drain => break,
        }
    }
    drop(listener);
    drop(stopping);
    let _ = stop.send(true);
    stop.closed().await;
    Ok(())
}

/// Serve one connection in a task of its own, until it ends, goes quiet past its
/// limits, or is told to stop and finishes what it is doing. A connection from
/// `proxy_from` first sends a PROXY header, within the header limit, and the client it
/// names is the address a handler sees. Without one, the connection is closed.
fn spawn_connection(
    builder: &http1::Builder,
    router: &Router,
    limits: Limits,
    shutdown: Shutdown,
    mut stopping: watch::Receiver<bool>,
    proxy_from: &[ProxyNet],
    (mut stream, mut address, slot): (TcpStream, SocketAddr, OwnedSemaphorePermit),
) {
    let builder = builder.clone();
    let router = TowerToHyperService::new(router.clone());
    let proxied = proxy_from.iter().any(|net| net.contains(address.ip()));
    tokio::spawn(async move {
        if proxied {
            let read = crate::proxy_protocol::read_header(&mut stream, address);
            let read = async {
                match limits.header_read {
                    Some(limit) => tokio::time::timeout(limit, read)
                        .await
                        .unwrap_or_else(|_| Err(io::ErrorKind::TimedOut.into())),
                    None => read.await,
                }
            };
            tokio::select! {
                read = read => match read {
                    Ok(client) => address = client,
                    Err(error) => {
                        tracing::debug!(%error, "closed a connection with no PROXY header");
                        return;
                    }
                },
                _ = stopping.wait_for(|stop| *stop) => return,
            }
        }
        let tracker = Tracker::new(limits);
        let phase = tracker.phase.subscribe();
        let serving = tracker.clone();
        let service = service_fn(move |mut request: Request<Incoming>| {
            request
                .extensions_mut()
                .insert(ConnectInfo::<SocketAddr>(address));
            request.extensions_mut().insert(shutdown.clone());
            serving.serving();
            let tracker = serving.clone();
            let response = router.call(request);
            async move {
                let response = response.await?;
                Ok::<_, Infallible>(response.map(|body| TrackedBody {
                    body,
                    _finished: Finished(tracker),
                }))
            }
        });
        let stream = TokioIo::new(Tracked {
            stream,
            tracker,
            _slot: slot,
        });
        let connection = builder.serve_connection(stream, service).with_upgrades();
        let mut connection = pin!(connection);
        let stop = async {
            // A sender dropped is a server gone, and it is told first.
            let _ = stopping.wait_for(|stop| *stop).await;
        };
        tokio::select! {
            ended = connection.as_mut() => log_end(ended),
            () = overdue(phase.clone()) => {
                tracing::debug!("dropped a quiet connection");
            }
            () = stop => {
                connection.as_mut().graceful_shutdown();
                tokio::select! {
                    ended = connection => log_end(ended),
                    () = overdue(phase) => {}
                }
            }
        }
    });
}

/// A connection ending badly is the client's business, so it is only worth a trace.
fn log_end(ended: std::result::Result<(), hyper::Error>) {
    if let Err(error) = ended {
        tracing::trace!(%error, "connection ended");
    }
}

/// Wait until the shutdown time limit has passed since `told`, or for ever when
/// it is zero.
async fn grace(config: &Server, told: Instant) {
    if config.shutdown_timeout_seconds == 0 {
        std::future::pending::<()>().await;
    }
    match told.checked_add(Duration::from_secs(config.shutdown_timeout_seconds)) {
        Some(deadline) => tokio::time::sleep_until(deadline).await,
        None => std::future::pending().await,
    }
}

/// The metrics route the internal port serves, `axa-prometheus-metrics`' default.
pub const METRICS_PATH: &str = "/metrics.prom";

/// Whether `path` is one the internal port serves: a health route or the metrics.
#[must_use]
pub fn is_internal_path(path: &str) -> bool {
    path == "/_health" || path.starts_with("/_health/") || path == METRICS_PATH
}

/// The `404` the main port gives an internal path, and the internal port any other.
async fn only(internal: bool, request: Request<Body>, next: Next) -> Response {
    if is_internal_path(request.uri().path()) == internal {
        next.run(request).await
    } else {
        crate::Error::NotFound.into_response()
    }
}

/// A task aborted when dropped, so a server that ends does not leave its stop waiting.
struct AbortOnDrop(tokio::task::JoinHandle<()>);

impl Drop for AbortOnDrop {
    fn drop(&mut self) {
        self.0.abort();
    }
}

async fn bind_and_serve(
    router: Router,
    config: &Server,
    stop: impl Future<Output = ()> + Send + 'static,
) -> Result<()> {
    let address = format!("{}:{}", config.binding, config.port);
    let listener = TcpListener::bind(&address).await?;
    tracing::info!(address, "listening");
    let internal = match config.internal_port {
        Some(port) => {
            let address = format!("{}:{port}", config.binding);
            let internal = TcpListener::bind(&address).await?;
            tracing::info!(address, "listening for health and metrics");
            Some(internal)
        }
        None => None,
    };
    let stopping = Arc::new(Notify::new());
    let told = stopping.clone();
    let (tell, stop_told) = watch::channel(false);
    let signal = AbortOnDrop(tokio::spawn(async move {
        stop.await;
        let _ = tell.send(true);
        told.notify_one();
    }));
    let told = |mut told: watch::Receiver<bool>| async move {
        let _ = told.wait_for(|told| *told).await;
    };
    let limits = Limits::from(config);
    let proxy_from: Arc<[ProxyNet]> = Arc::from(config.proxy_protocol_from.as_slice());
    let served = async {
        match internal {
            None => accept_with(router, listener, limits, proxy_from, told(stop_told)).await,
            Some(internal) => {
                let main = router.clone().layer(middleware::from_fn(
                    |request: Request<Body>, next: Next| only(false, request, next),
                ));
                let health =
                    router.layer(middleware::from_fn(|request: Request<Body>, next: Next| {
                        only(true, request, next)
                    }));
                tokio::try_join!(
                    accept_with(
                        main,
                        listener,
                        limits,
                        proxy_from.clone(),
                        told(stop_told.clone())
                    ),
                    // Probes and scrapes reach the internal port directly, never through
                    // the balancer, so it takes no PROXY header from anyone.
                    accept_with(health, internal, limits, Arc::from([]), told(stop_told)),
                )
                .map(|_| ())
            }
        }
    };
    let _signal = signal;
    tokio::select! {
        served = served => served,
        () = async {
            stopping.notified().await;
            // A drain too long to add to now is one for ever, not a panic.
            match Instant::now().checked_add(Duration::from_secs(config.shutdown_drain_seconds)) {
                Some(drained) => grace(config, drained).await,
                None => std::future::pending().await,
            }
        } => {
            tracing::warn!("requests were still running at the shutdown time limit");
            Ok(())
        }
    }
}

/// Serve `router`, run `queue`, or both, until [`shutdown_signal`]: what `start`, `start --worker`,
/// and `start --all` do. Requests in flight and jobs in progress finish first.
///
/// # Errors
///
/// Fails when there is nothing to run, when the address cannot be bound, or when the job loops
/// panicked. The job loops are stopped either way.
#[cfg(feature = "queue")]
pub async fn run(router: Option<Router>, queue: Option<Arc<Queue>>, config: &Server) -> Result<()> {
    run_until(router, queue, config, shutdown_signal()).await
}

/// [`run`], with the job loops held back until no migration is pending, as
/// [`crate::health::Checks::migrations`] says. The server answers at once, so its probes
/// can say it is not ready yet, and shutdown while waiting stops the wait.
///
/// ```ignore
/// server::run_once_migrated(router, queue, &config.server, &ctx.health_checks).await
/// ```
///
/// # Errors
///
/// As [`run`].
#[cfg(feature = "queue")]
pub async fn run_once_migrated(
    router: Option<Router>,
    queue: Option<Arc<Queue>>,
    config: &Server,
    checks: &crate::health::Checks,
) -> Result<()> {
    let checks = checks.clone();
    run_after(router, queue, config, shutdown_signal(), async move {
        checks.migrated().await;
    })
    .await
}

#[cfg(feature = "queue")]
pub(crate) async fn run_until(
    router: Option<Router>,
    queue: Option<Arc<Queue>>,
    config: &Server,
    stop: impl Future<Output = ()> + Send + 'static,
) -> Result<()> {
    run_after(router, queue, config, stop, std::future::ready(())).await
}

/// [`run_until`], with the job loops started only once `start_jobs` resolves, or not at
/// all if the stop comes first.
#[cfg(feature = "queue")]
pub(crate) async fn run_after(
    router: Option<Router>,
    queue: Option<Arc<Queue>>,
    config: &Server,
    stop: impl Future<Output = ()> + Send + 'static,
    start_jobs: impl Future<Output = ()> + Send + 'static,
) -> Result<()> {
    let modes = match (&router, &queue) {
        (Some(_), Some(_)) => "server, worker",
        (Some(_), None) => "server",
        (None, Some(_)) => "worker",
        (None, None) => return Err(Error::string("neither a server nor a worker to run")),
    };
    tracing::info!("modes: {modes}");
    let (stop_jobs, stopped) = watch::channel(false);
    let jobs = queue.map(|queue| {
        let mut waiting = stopped.clone();
        tokio::spawn(async move {
            tokio::select! {
                () = start_jobs => queue.run(stopped).await,
                // Stopped before the jobs could start: nothing was claimed.
                () = async {
                    // The guard it gives back is dropped here, before anything awaits.
                    let _ = waiting.wait_for(|stop| *stop).await;
                } => {}
            }
        })
    });
    // Requests and jobs hear at once, and share one time limit, so that no job
    // is claimed during the wait and the whole of shutdown stays under it.
    let stop_jobs = Arc::new(stop_jobs);
    let told = Arc::new(OnceLock::new());
    let stop = {
        let (stop_jobs, told) = (stop_jobs.clone(), told.clone());
        async move {
            stop.await;
            told.get_or_init(Instant::now);
            let _ = stop_jobs.send(true);
        }
    };
    let served = if let Some(router) = router {
        bind_and_serve(router, config, stop).await
    } else {
        stop.await;
        Ok(())
    };
    // A server that could not start was never told to stop.
    let told = *told.get_or_init(Instant::now);
    let _ = stop_jobs.send(true);
    if let Some(mut jobs) = jobs {
        tokio::select! {
            finished = &mut jobs => {
                finished.map_err(|error| Error::string(&format!("job loops failed: {error}")))?;
            }
            // Stopped, not left running detached: dropping the handle alone would not.
            // A job cut off is recovered as lost by the next worker.
            () = grace(config, told) => {
                tracing::warn!("jobs were still running at the shutdown time limit");
                jobs.abort();
                let _ = jobs.await;
            }
        }
    }
    served
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::routing::get;
    use std::time::Duration;
    use tokio::{
        io::{AsyncReadExt, AsyncWriteExt},
        net::TcpStream,
        sync::oneshot,
    };

    #[tokio::test]
    async fn shutdown_lets_a_request_in_flight_finish() {
        let (started_tx, started_rx) = oneshot::channel::<()>();
        let started = std::sync::Arc::new(std::sync::Mutex::new(Some(started_tx)));
        let app = Router::new().route(
            "/slow",
            get(move || {
                let started = started.lock().unwrap().take();
                async move {
                    if let Some(started) = started {
                        let _ = started.send(());
                    }
                    tokio::time::sleep(Duration::from_millis(100)).await;
                    "finished"
                }
            }),
        );
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let (stop_tx, stop_rx) = oneshot::channel::<()>();
        let server = tokio::spawn(serve_until(app, listener, async {
            let _ = stop_rx.await;
        }));

        let mut stream = TcpStream::connect(address).await.unwrap();
        stream
            .write_all(b"GET /slow HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n")
            .await
            .unwrap();
        // Ask the server to stop only once the handler is really running.
        started_rx.await.unwrap();
        stop_tx.send(()).unwrap();

        let mut response = String::new();
        stream.read_to_string(&mut response).await.unwrap();
        assert!(response.contains("200 OK"), "{response}");
        assert!(response.ends_with("finished"), "{response}");
        server.await.unwrap().unwrap();
    }

    /// One request on a new connection, and the response, or `None` when nothing
    /// accepts the connection.
    async fn ask(address: SocketAddr, path: &str) -> Option<String> {
        let mut stream = TcpStream::connect(address).await.ok()?;
        let request = format!("GET {path} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n");
        stream.write_all(request.as_bytes()).await.ok()?;
        let mut response = String::new();
        stream.read_to_string(&mut response).await.ok()?;
        Some(response)
    }

    /// A router that says whether shutdown has begun.
    fn begun() -> Router {
        Router::new().route(
            "/begun",
            get(|shutdown: Shutdown| async move { shutdown.has_begun().to_string() }),
        )
    }

    #[tokio::test]
    async fn the_drain_keeps_accepting_and_tells_handlers_shutdown_has_begun() {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let limits = Limits {
            drain: Duration::from_millis(400),
            ..Limits::new(0, 0, 0, 16)
        };
        let (stop_tx, stop_rx) = oneshot::channel::<()>();
        let server = tokio::spawn(accept_until(begun(), listener, limits, async {
            let _ = stop_rx.await;
        }));
        assert!(ask(address, "/begun").await.unwrap().ends_with("false"));
        stop_tx.send(()).unwrap();
        tokio::time::sleep(Duration::from_millis(50)).await;
        // Still accepting, and a handler sees shutdown has begun.
        let during = ask(address, "/begun")
            .await
            .expect("accepted during the drain");
        assert!(during.ends_with("true"), "{during}");
        server.await.unwrap().unwrap();
        // Once drained, nothing listens.
        assert!(ask(address, "/begun").await.is_none());
    }

    #[tokio::test]
    async fn with_no_drain_the_listener_closes_at_once() {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let (stop_tx, stop_rx) = oneshot::channel::<()>();
        let server = tokio::spawn(serve_until(begun(), listener, async {
            let _ = stop_rx.await;
        }));
        stop_tx.send(()).unwrap();
        server.await.unwrap().unwrap();
        assert!(ask(address, "/begun").await.is_none());
    }

    #[tokio::test]
    async fn a_stream_waiting_on_shutdown_ends_itself() {
        let app = Router::new().route(
            "/events",
            get(|shutdown: Shutdown| async move {
                shutdown.begun().await;
                "stream ended"
            }),
        );
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let (stop_tx, stop_rx) = oneshot::channel::<()>();
        let server = tokio::spawn(serve_until(app, listener, async {
            let _ = stop_rx.await;
        }));
        let response = tokio::spawn(ask(address, "/events"));
        tokio::time::sleep(Duration::from_millis(100)).await;
        stop_tx.send(()).unwrap();
        let response = tokio::time::timeout(Duration::from_secs(5), response)
            .await
            .expect("the stream ended at shutdown")
            .unwrap()
            .unwrap();
        assert!(response.ends_with("stream ended"), "{response}");
        server.await.unwrap().unwrap();
    }

    #[tokio::test]
    async fn a_request_outside_this_server_never_sees_shutdown() {
        use tower::ServiceExt;
        let response = begun()
            .oneshot(Request::get("/begun").body(Body::empty()).unwrap())
            .await
            .unwrap();
        let body = axum::body::to_bytes(response.into_body(), 64)
            .await
            .unwrap();
        assert_eq!(&body[..], b"false");
    }

    #[tokio::test]
    async fn every_never_shares_one_sender_and_none_begins() {
        let (first, second) = (Shutdown::never(), Shutdown::never());
        assert!(first.0.same_channel(&second.0));
        assert!(!first.has_begun());
        let waited = tokio::time::timeout(Duration::from_millis(20), first.begun()).await;
        assert!(
            waited.is_err(),
            "a shutdown that never begins was seen to begin"
        );
    }

    /// Whether a server closes on a client that starts its headers and stalls.
    async fn drops_a_stalled_client(header_read_timeout_seconds: u64) -> bool {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        tokio::spawn(accept_until(
            Router::new(),
            listener,
            Limits::new(header_read_timeout_seconds, 0, 0, 0),
            std::future::pending(),
        ));
        let mut stream = TcpStream::connect(address).await.unwrap();
        stream.write_all(b"GET / HTTP/1.1\r\nHost:").await.unwrap();
        let mut response = Vec::new();
        tokio::time::timeout(Duration::from_secs(3), stream.read_to_end(&mut response))
            .await
            .is_ok()
    }

    #[tokio::test]
    async fn a_client_that_stalls_in_its_headers_is_dropped() {
        assert!(drops_a_stalled_client(1).await);
    }

    /// Whether a server closes on a client that sends only `opening`.
    async fn drops_a_client_sending(opening: &[u8]) -> bool {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        tokio::spawn(accept_until(
            Router::new(),
            listener,
            Limits::new(1, 0, 0, 0),
            std::future::pending(),
        ));
        let mut stream = TcpStream::connect(address).await.unwrap();
        stream.write_all(opening).await.unwrap();
