        assert!(!Count.development_only());
        assert!(Fixtures.development_only());
    }

    #[test]
    fn a_development_task_needs_both_environments_to_allow_it() {
        use Environment::{Development, Production, Test};
        assert!(may_run_development_task(&Development, &Test));
        assert!(!may_run_development_task(&Production, &Test));
        assert!(!may_run_development_task(&Development, &Production));
        let staging = Environment::parse("staging");
        assert!(!may_run_development_task(&Development, &staging));
    }

    #[tokio::test]
    async fn a_development_task_is_refused_in_production() {
        let mut tasks = Tasks::default();
        tasks.register(Fixtures);
        let mut ctx = context();
        ctx.environment = Environment::Production;
        let error = tasks.run("fixtures", &ctx, &Vars::default()).await;
        assert!(error.unwrap_err().to_string().contains("refused"));
    }
}

//! Bounded multipart uploads, with files written to temporary files.
//!
//! Axum's [`Multipart`] reads parts as they arrive and leaves the limits to the
//! service. [`read`] holds every part to [`Limits`]: how many parts, how large each
//! text field and each file, how much text is held in memory, and how large all of it.
//! Text fields are kept in memory, and each file goes to a temporary file that is
//! deleted when its [`File`] is dropped, so a large upload costs disk, not memory.
//!
//! ```no_run
//! use axa::{Result, format, upload::{self, Limits}};
//! use axum::extract::Multipart;
//!
//! async fn avatar(multipart: Multipart) -> Result<axum::response::Response> {
//!     let limits = Limits {
//!         file_bytes: 2_000_000,
//!         files: 1,
//!         accept: Some(vec!["image/png", "image/jpeg"]),
//!         ..Limits::default()
//!     };
//!     let upload = upload::read(multipart, &limits).await?;
//!     let Some(file) = upload.files.first() else {
//!         return axa::prelude::bad_request("send one image");
//!     };
//!     // `file.path()` is the temporary file, which is deleted when `upload` drops:
//!     // copy or persist it first.
//!     format::json(serde_json::json!({ "name": file.file_name, "bytes": file.size }))
//! }
//! ```
//!
//! A part's names and content type are the caller's text, and no problem quotes them.
//! A file name is cleaned with [`format::clean_file_name`](crate::format::clean_file_name)
//! before anything sees it.

use std::path::Path;

use axum::{
    extract::{Multipart, multipart::Field},
    http::StatusCode,
};
use tokio::io::AsyncWriteExt;

use crate::{Error, Result, error::ErrorDetail, format::clean_file_name};

/// The longest field name a part may have.
const MAX_FIELD_NAME_BYTES: usize = 128;

/// How much an upload may hold. Every limit counts bytes as they arrive, so a caller
/// that sends more is refused when it passes the limit, not after.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Limits {
    /// All the parts together, 20 MB by default. The standard stack's body limit,
    /// `HTTP_REQUEST_BODY_LIMIT_BYTE_COUNT`, applies as well, so raise both for larger
    /// uploads.
    pub total_bytes: u64,
    /// One file, 10 MB by default.
    pub file_bytes: u64,
    /// One text field, 64 KB by default.
    pub field_bytes: usize,
    /// All the text fields together, which are held in memory, 1 MB by default.
    pub memory_bytes: usize,
    /// How many parts, 32 by default.
    pub parts: usize,
    /// How many of them may be files, 8 by default.
    pub files: usize,
    /// The media types a file may declare, as `image/png`, compared without
    /// parameters and case. `None`, the default, takes any. A file that declares none
    /// counts as `application/octet-stream`.
    pub accept: Option<Vec<&'static str>>,
}

impl Default for Limits {
    fn default() -> Self {
        Self {
            total_bytes: 20_000_000,
            file_bytes: 10_000_000,
            field_bytes: 64_000,
            memory_bytes: 1_000_000,
            parts: 32,
            files: 8,
            accept: None,
        }
    }
}

/// A text field.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Text {
    /// The part's field name.
    pub name: String,
    /// What it held, as UTF-8.
    pub value: String,
}

/// A file, in a temporary file deleted when this drops.
#[derive(Debug)]
pub struct File {
    /// The part's field name.
    pub name: String,
    /// The name the caller gave the file, cleaned, or `download` when it gave none.
    pub file_name: String,
    /// The media type the caller declared, lower case and without parameters, or
    /// `application/octet-stream`. It is the caller's word, not a check of the bytes.
    pub content_type: String,
    /// How many bytes it holds.
    pub size: u64,
    temp: tempfile::NamedTempFile,
}

impl File {
    /// Where the temporary file is. It is deleted when this drops.
    #[must_use]
    pub fn path(&self) -> &Path {
        self.temp.path()
    }

    /// Keep the file at `path`, on the same file system as the temporary directory, so
    /// that it is not deleted when this drops.
    ///
    /// # Errors
    ///
    /// Fails when the file cannot be moved there.
    pub fn persist(self, path: impl AsRef<Path>) -> Result<()> {
        self.temp
            .persist(path)
            .map(|_| ())
            .map_err(|error| Error::IO(error.error))
    }
}

/// An upload's parts, in the order they came.
#[derive(Debug, Default)]
pub struct Upload {
    /// The text fields.
    pub fields: Vec<Text>,
    /// The files.
    pub files: Vec<File>,
}

impl Upload {
    /// The value of the first text field named `name`.
    #[must_use]
    pub fn field(&self, name: &str) -> Option<&str> {
        self.fields
            .iter()
            .find(|field| field.name == name)
            .map(|field| field.value.as_str())
    }

    /// The first file in the part named `name`.
    #[must_use]
    pub fn file(&self, name: &str) -> Option<&File> {
        self.files.iter().find(|file| file.name == name)
    }
}

/// A refusal with `status`, whose `detail` names a limit and nothing the caller sent.
fn refuse(status: StatusCode, code: &str, detail: impl Into<String>) -> Error {
    Error::CustomError(status, ErrorDetail::new(code, detail.into()))
}

fn too_large(detail: impl Into<String>) -> Error {
    refuse(StatusCode::PAYLOAD_TOO_LARGE, "payload_too_large", detail)
}

/// A failure reading the body, which keeps its status, such as `413` from the body
/// limit, and says nothing of what was read.
fn unreadable(error: &axum::extract::multipart::MultipartError) -> Error {
    let status = error.status();
    if status == StatusCode::PAYLOAD_TOO_LARGE {
        return too_large("The request body is too large");
    }
    if status.is_server_error() {
        return Error::InternalServerError;
    }
    refuse(
        StatusCode::BAD_REQUEST,
        "bad_request",
        "The request body is not valid multipart/form-data",
    )
}

/// The declared media type, lower case and without parameters.
fn media_type(field: &Field<'_>) -> String {
    field
        .content_type()
        .and_then(|value| value.split(';').next())
        .map(|value| value.trim().to_ascii_lowercase())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "application/octet-stream".to_string())
}

/// How many bytes have arrived so far, against `Limits::total_bytes`.
struct Tally<'a> {
    limits: &'a Limits,
    total: u64,
    memory: usize,
}

impl Tally<'_> {
    fn add(&mut self, bytes: usize) -> Result<()> {
        self.total = self.total.saturating_add(bytes as u64);
        if self.total > self.limits.total_bytes {
            return Err(too_large(format!(
                "The upload is larger than {} bytes",
                self.limits.total_bytes
            )));
        }
        Ok(())
    }
}

/// Read every part of `multipart`, holding each to `limits`.
///
/// # Errors
///
/// Answers `413`, code `payload_too_large`, for an upload past any limit, `415`, code
/// `unsupported_media_type`, for a file whose media type `accept` does not list, and
/// `400`, code `bad_request`, for a body that is not valid multipart, a part with no
/// name or one longer than 128 bytes, or a text field that is not UTF-8. A temporary
/// file that cannot be written is a `500`. What was read so far is dropped, and its
/// temporary files deleted.
pub async fn read(mut multipart: Multipart, limits: &Limits) -> Result<Upload> {
    let mut upload = Upload::default();
    let mut tally = Tally {
        limits,
        total: 0,
        memory: 0,
    };
    let mut parts = 0;
    while let Some(field) = multipart.next_field().await.map_err(|e| unreadable(&e))? {
        parts += 1;
        if parts > limits.parts {
            return Err(too_large(format!(
                "The upload has more than {} parts",
                limits.parts
            )));
        }
        let name = match field.name() {
            Some(name) if !name.is_empty() && name.len() <= MAX_FIELD_NAME_BYTES => {
                name.to_string()
            }
            _ => {
                return Err(refuse(
                    StatusCode::BAD_REQUEST,
                    "bad_request",
                    "Every part needs a name of at most 128 bytes",
                ));
            }
        };
        if field.file_name().is_some() {
            if upload.files.len() >= limits.files {
                return Err(too_large(format!(
                    "The upload has more than {} files",
                    limits.files
                )));
            }
            upload.files.push(read_file(field, name, &mut tally).await?);
        } else {
            upload
                .fields
                .push(read_text(field, name, &mut tally).await?);
        }
    }
    Ok(upload)
}

async fn read_text(mut field: Field<'_>, name: String, tally: &mut Tally<'_>) -> Result<Text> {
    let limits = tally.limits;
    let mut bytes = Vec::new();
    while let Some(chunk) = field.chunk().await.map_err(|e| unreadable(&e))? {
        tally.add(chunk.len())?;
        tally.memory = tally.memory.saturating_add(chunk.len());
        if bytes.len() + chunk.len() > limits.field_bytes {
            return Err(too_large(format!(
                "A text field is larger than {} bytes",
                limits.field_bytes
            )));
        }
        if tally.memory > limits.memory_bytes {
            return Err(too_large(format!(
                "The text fields are larger than {} bytes together",
                limits.memory_bytes
            )));
        }
        bytes.extend_from_slice(&chunk);
    }
    let value = String::from_utf8(bytes).map_err(|_| {
        refuse(
            StatusCode::BAD_REQUEST,
            "bad_request",
            "A text field is not UTF-8",
        )
    })?;
    Ok(Text { name, value })
}

async fn read_file(mut field: Field<'_>, name: String, tally: &mut Tally<'_>) -> Result<File> {
    let limits = tally.limits;
    let content_type = media_type(&field);
    if let Some(accept) = &limits.accept
        && !accept
            .iter()
            .any(|accepted| accepted.eq_ignore_ascii_case(&content_type))
    {
        return Err(refuse(
            StatusCode::UNSUPPORTED_MEDIA_TYPE,
            "unsupported_media_type",
            format!("A file must be one of {}", accept.join(", ")),
        ));
    }
    let file_name = clean_file_name(field.file_name().unwrap_or_default());
    let temp = tempfile::NamedTempFile::new().map_err(Error::IO)?;
    let mut writer = tokio::fs::File::from_std(temp.reopen().map_err(Error::IO)?);
    let mut size: u64 = 0;
    while let Some(chunk) = field.chunk().await.map_err(|e| unreadable(&e))? {
        tally.add(chunk.len())?;
        size = size.saturating_add(chunk.len() as u64);
        if size > limits.file_bytes {
            return Err(too_large(format!(
                "A file is larger than {} bytes",
                limits.file_bytes
            )));
        }
        writer.write_all(&chunk).await.map_err(Error::IO)?;
    }
    writer.flush().await.map_err(Error::IO)?;
    Ok(File {
        name,
        file_name,
        content_type,
        size,
        temp,
    })
}

#[cfg(test)]
mod tests {
    use axum::{
        Router,
        body::{Body, to_bytes},
        http::{Request, header::CONTENT_TYPE},
        response::IntoResponse,
        routing::post,
    };
    use serde_json::{Value, json};
    use tower::ServiceExt;

    use super::*;

    const BOUNDARY: &str = "axa-boundary";

    /// A part: its name, file name, content type, and contents.
    type Part<'a> = (&'a str, Option<&'a str>, Option<&'a str>, &'a [u8]);

    fn body(parts: &[Part<'_>]) -> Vec<u8> {
        let mut body = Vec::new();
        for (name, file_name, content_type, contents) in parts {
            body.extend_from_slice(format!("--{BOUNDARY}\r\n").as_bytes());
            let disposition = match file_name {
                Some(file_name) => format!(
                    "Content-Disposition: form-data; name=\"{name}\"; filename=\"{file_name}\""
                ),
                None => format!("Content-Disposition: form-data; name=\"{name}\""),
            };
            body.extend_from_slice(disposition.as_bytes());
            body.extend_from_slice(b"\r\n");
            if let Some(content_type) = content_type {
                body.extend_from_slice(format!("Content-Type: {content_type}\r\n").as_bytes());
            }
            body.extend_from_slice(b"\r\n");
            body.extend_from_slice(contents);
            body.extend_from_slice(b"\r\n");
        }
        body.extend_from_slice(format!("--{BOUNDARY}--\r\n").as_bytes());
        body
    }

    /// Send `parts` to a route that reads them under `limits`, and answers with what
    /// it read, checking each file's contents and that the file goes when it drops.
    async fn send(limits: Limits, parts: &[Part<'_>]) -> (StatusCode, Value) {
        let app = Router::new().route(
            "/",
            post(move |multipart: Multipart| async move {
                let upload = match read(multipart, &limits).await {
                    Ok(upload) => upload,
                    Err(error) => return error.into_response(),
                };
                let mut files = Vec::new();
                let mut paths = Vec::new();
                for file in &upload.files {
                    let contents = std::fs::read(file.path()).unwrap();
                    assert_eq!(contents.len() as u64, file.size);
                    paths.push(file.path().to_path_buf());
                    files.push(json!({
                        "name": file.name,
                        "file_name": file.file_name,
                        "content_type": file.content_type,
                        "contents": String::from_utf8_lossy(&contents),
                    }));
                }
                let fields: Vec<Value> = upload
                    .fields
                    .iter()
                    .map(|field| json!([field.name, field.value]))
                    .collect();
                drop(upload);
                for path in paths {
                    assert!(!path.exists(), "{}", path.display());
                }
                axum::Json(json!({ "fields": fields, "files": files })).into_response()
            }),
        );
        let request = Request::post("/")
            .header(
                CONTENT_TYPE,
                format!("multipart/form-data; boundary={BOUNDARY}"),
            )
            .body(Body::from(body(parts)))
            .unwrap();
        let response = app.oneshot(request).await.unwrap();
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        (status, serde_json::from_slice(&bytes).unwrap())
    }

    #[tokio::test]
    async fn fields_are_kept_and_files_spooled_to_temporary_files() {
        let parts: [Part<'_>; 3] = [
            ("title", None, None, b"Holiday"),
            (
                "photo",
                Some("../../etc/\u{202e}gpj.exe"),
                Some("Image/PNG; charset=x"),
                b"\x89PNG data",
            ),
            ("notes", Some("notes.txt"), None, b"hello"),
        ];
        let (status, body) = send(Limits::default(), &parts).await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["fields"], json!([["title", "Holiday"]]));
        assert_eq!(body["files"][0]["name"], "photo");
        assert_eq!(body["files"][0]["file_name"], "gpj.exe");
        assert_eq!(body["files"][0]["content_type"], "image/png");
        assert_eq!(body["files"][1]["file_name"], "notes.txt");
        assert_eq!(body["files"][1]["content_type"], "application/octet-stream");
        assert_eq!(body["files"][1]["contents"], "hello");
    }

    #[tokio::test]
    async fn each_limit_is_a_413_that_names_the_limit_and_quotes_nothing() {
        let secret = b"secret".repeat(4);
        let cases: Vec<(Limits, Vec<Part<'_>>, &str)> = vec![
            (
                Limits {
                    file_bytes: 10,
                    ..Limits::default()
                },
                vec![("f", Some("secret.txt"), None, &secret)],
                "A file is larger than 10 bytes",
            ),
            (
                Limits {
                    field_bytes: 10,
                    ..Limits::default()
                },
                vec![("secret", None, None, &secret)],
                "A text field is larger than 10 bytes",
            ),
            (
                Limits {
                    memory_bytes: 30,
                    ..Limits::default()
                },
                vec![("a", None, None, &secret), ("b", None, None, &secret)],
                "The text fields are larger than 30 bytes together",
            ),
            (
                Limits {
                    total_bytes: 30,
                    ..Limits::default()
                },
                vec![("a", None, None, &secret), ("f", Some("f"), None, &secret)],
                "The upload is larger than 30 bytes",
            ),
            (
                Limits {
                    parts: 1,
                    ..Limits::default()
                },
                vec![("a", None, None, b"1"), ("b", None, None, b"2")],
                "The upload has more than 1 parts",
            ),
            (
                Limits {
                    files: 1,
                    ..Limits::default()
                },
                vec![("a", Some("a"), None, b"1"), ("b", Some("b"), None, b"2")],
                "The upload has more than 1 files",
            ),
        ];
        for (limits, parts, detail) in cases {
            let (status, body) = send(limits, &parts).await;
            assert_eq!(status, StatusCode::PAYLOAD_TOO_LARGE, "{body}");
            assert_eq!(body["code"], "payload_too_large");
            assert_eq!(body["detail"], detail);
            assert!(!body.to_string().contains("secret"), "{body}");
        }
    }

    #[tokio::test]
    async fn a_file_of_a_type_not_accepted_is_a_415() {
        let limits = Limits {
            accept: Some(vec!["image/png"]),
            ..Limits::default()
        };
        let (status, body) = send(
            limits.clone(),
            &[("f", Some("a.png"), Some("IMAGE/png"), b"x")],
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        for content_type in [Some("text/html; secret"), None] {
            let (status, body) =
                send(limits.clone(), &[("f", Some("a.png"), content_type, b"x")]).await;
            assert_eq!(status, StatusCode::UNSUPPORTED_MEDIA_TYPE, "{body}");
            assert_eq!(body["code"], "unsupported_media_type");
            assert_eq!(body["detail"], "A file must be one of image/png");
            assert!(!body.to_string().contains("secret"), "{body}");
        }
    }

    #[tokio::test]
    async fn a_part_with_no_usable_name_or_text_that_is_not_utf8_is_a_400() {
        let long = "n".repeat(129);
        for parts in [
            vec![("", None, None, &b"x"[..])],
            vec![(long.as_str(), None, None, &b"x"[..])],
            vec![("a", None, None, &b"\xff\xfe"[..])],
        ] {
            let (status, body) = send(Limits::default(), &parts).await;
            assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
            assert_eq!(body["code"], "bad_request");
            assert!(!body.to_string().contains(&long), "{body}");
        }
    }

    #[tokio::test]
    async fn the_body_limit_still_applies_and_a_broken_body_is_a_400() {
        let app = |limit| {
            Router::new()
                .route(
                    "/",
                    post(|multipart: Multipart| async move {
                        read(multipart, &Limits::default())
                            .await
                            .map(|_| "ok")
                            .into_response()
                    }),
                )
                .layer(axum::extract::DefaultBodyLimit::max(limit))
        };
        let request = |body: Vec<u8>| {
            Request::post("/")
                .header(
                    CONTENT_TYPE,
                    format!("multipart/form-data; boundary={BOUNDARY}"),
                )
                .body(Body::from(body))
                .unwrap()
        };
        let big = body(&[("f", Some("f"), None, &[b'x'; 2_000])]);
        let response = app(1_000).oneshot(request(big)).await.unwrap();
        assert_eq!(response.status(), StatusCode::PAYLOAD_TOO_LARGE);

        let broken =
            format!("--{BOUNDARY}\r\nContent-Disposition: form-data; name=\"a\"\r\n\r\nno end");
        let response = app(1_000)
            .oneshot(request(broken.into_bytes()))
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    }
}

//! Model validation, the same for every database, with the shape of Loco's.
//!
//! Implement [`Validatable`] on a model, or on the struct a handler builds from a
//! request, then call `validate()?`. A failure is [`ModelValidationErrors`], which
//! becomes `400` with each field's failures through [`crate::model::ModelError`].
//!
//! With `SeaORM`, implement it on an `ActiveModel` and call `self.validate()?` in
//! `before_save`: there a failure becomes a `DbErr::Custom` whose text is a JSON map
//! of field name to error list.

use std::collections::{BTreeMap, HashMap};

use serde::{Deserialize, Serialize};
use validator::{Validate, ValidationErrors};

/// One failure on one field.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ValidationError {
    /// The rule that failed, such as `email` or `length`.
    pub code: String,
    /// The message, if the rule has one.
    pub message: Option<String>,
    /// The rule's parameters.
    #[serde(skip_serializing_if = "HashMap::is_empty", default)]
    pub params: HashMap<String, serde_json::Value>,
}

/// Validation failures by field name.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, thiserror::Error)]
#[error("Model validation failed")]
pub struct ModelValidationErrors {
    /// The failures.
    pub errors: BTreeMap<String, Vec<ValidationError>>,
}

impl From<ValidationErrors> for ModelValidationErrors {
    fn from(value: ValidationErrors) -> Self {
        let errors = value
            .field_errors()
            .iter()
            .map(|(field, failures)| {
                let failures = failures
                    .iter()
                    .map(|failure| ValidationError {
                        code: failure.code.to_string(),
                        message: failure.message.as_ref().map(ToString::to_string),
                        params: failure
                            .params
                            .iter()
                            .map(|(name, value)| (name.to_string(), value.clone()))
                            .collect(),
                    })
                    .collect();
                ((*field).to_string(), failures)
            })
            .collect();
        Self { errors }
    }
}

#[cfg(has_seaorm)]
impl From<ModelValidationErrors> for sea_orm::DbErr {
    fn from(errors: ModelValidationErrors) -> Self {
        // Compact on purpose: `code` and `message` only, which is the text
        // Loco produced, so snapshots of these errors do not change.
        let compact: BTreeMap<&String, Vec<_>> = errors
            .errors
            .iter()
            .map(|(field, failures)| {
                let failures = failures
                    .iter()
                    .map(|failure| {
                        serde_json::json!({ "code": failure.code, "message": failure.message })
                    })
                    .collect();
                (field, failures)
            })
            .collect();
        match serde_json::to_string(&compact) {
            Ok(text) => Self::Custom(text),
            Err(error) => Self::Custom(format!("could not encode validation errors: {error}")),
        }
    }
}

/// A model that can validate itself.
pub trait Validatable {
    /// The value to validate, usually a small struct built from this model.
    fn validator(&self) -> Box<dyn Validate>;

    /// Run the validation.
    ///
    /// # Errors
    ///
    /// Returns the failures by field.
    fn validate(&self) -> Result<(), ModelValidationErrors> {
        self.validator()
            .validate()
            .map_err(ModelValidationErrors::from)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[derive(Validate)]
    struct Fields {
        #[validate(length(min = 2, message = "Name is too short."))]
        name: String,
        #[validate(email(message = "invalid email"))]
        email: String,
    }

    struct Model {
        name: String,
        email: String,
    }

    impl Validatable for Model {
        fn validator(&self) -> Box<dyn Validate> {
            Box::new(Fields {
                name: self.name.clone(),
                email: self.email.clone(),
            })
        }
    }

    fn model(name: &str, email: &str) -> Model {
        Model {
            name: name.to_string(),
            email: email.to_string(),
        }
    }

    #[test]
    fn a_valid_model_passes() {
        assert!(model("Alice", "a@example.org").validate().is_ok());
    }

    #[test]
    fn failures_are_reported_by_field() {
        let errors = model("A", "nope").validate().unwrap_err();
        assert_eq!(errors.errors["email"][0].code, "email");
        assert_eq!(
            errors.errors["name"][0].message.as_deref(),
            Some("Name is too short.")
        );
    }

    #[test]
    fn a_rules_parameters_are_kept() {
        let errors = model("A", "a@example.org").validate().unwrap_err();
        assert_eq!(errors.errors["name"][0].params["min"], 2);
    }

    #[cfg(has_seaorm)]
    #[test]
    fn the_database_error_is_compact_json() {
        use sea_orm::DbErr;

        let errors = model("Alice", "nope").validate().unwrap_err();
        let DbErr::Custom(text) = DbErr::from(errors) else {
            panic!("expected a custom error");
        };
        assert_eq!(
            text,
            r#"{"email":[{"code":"email","message":"invalid email"}]}"#
        );
    }
}

//! Background jobs.

use std::time::Duration;

use async_trait::async_trait;
use serde::{Serialize, de::DeserializeOwned};
use uuid::Uuid;

use crate::{AppContext, Error, Result};

/// How [`BackgroundWorker::perform_later`] runs a job.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WorkerMode {
    /// Enqueue on the Postgres queue for a worker process.
    BackgroundQueue,
    /// Run inside the request. Used by tests.
    ForegroundBlocking,
    /// Spawn on the current runtime.
    BackgroundAsync,
}

/// A job type. `A` is its serializable argument.
#[async_trait]
pub trait BackgroundWorker<A>: Send + Sync
where
    A: Serialize + DeserializeOwned + Send + Sync + 'static,
{
    /// Build the worker.
    fn build(ctx: &AppContext) -> Self;

    /// Name recorded on queued jobs.
    #[must_use]
    fn class_name() -> String
    where
        Self: Sized,
    {
        let name = std::any::type_name::<Self>();
        name.rsplit("::").next().unwrap_or(name).to_string()
    }

    /// Run or enqueue a job, per [`WorkerMode`], and return its id.
    ///
    /// # Errors
    ///
    /// Fails when queueing fails, no queue is configured, or a foreground
    /// job fails.
    async fn perform_later(ctx: &AppContext, args: A) -> Result<String>
    where
        Self: Sized + 'static,
    {
        Self::perform_in(ctx, args, Duration::ZERO).await
    }

    /// Run or enqueue a job no sooner than `delay` from now, per [`WorkerMode`], and
    /// return its id. On the queue the delay is kept on the job's row.
    /// `BackgroundAsync` sleeps for it in this process, so a restart loses that job,
    /// and `ForegroundBlocking` runs the job straight away, as tests want.
    ///
    /// # Errors
    ///
    /// Fails when queueing fails, no queue is configured, or a foreground
    /// job fails.
    async fn perform_in(ctx: &AppContext, args: A, delay: Duration) -> Result<String>
    where
        Self: Sized + 'static,
    {
        match ctx.config.workers {
            WorkerMode::BackgroundQueue => {
                #[cfg(feature = "queue")]
                {
                    let job = crate::queue::job::<Self, A>(&args)?.run_in(delay);
                    enqueue(ctx, &job).await
                }
                #[cfg(not(feature = "queue"))]
                {
                    let _ = (args, delay);
                    no_queue()
                }
            }
            WorkerMode::ForegroundBlocking => {
                Self::build(ctx).perform(args).await?;
                Ok(Uuid::new_v4().to_string())
            }
            WorkerMode::BackgroundAsync => {
                let worker = Self::build(ctx);
                tokio::spawn(async move {
                    if !delay.is_zero() {
                        tokio::time::sleep(delay).await;
                    }
                    if let Err(error) = worker.perform(args).await {
                        tracing::error!(%error, "background job failed");
                    }
                });
                Ok(Uuid::new_v4().to_string())
            }
        }
    }

    /// Run or enqueue a job for `tenant`, per [`WorkerMode`], and return its id. The
    /// job runs in [`BackgroundWorker::perform_for`], which this worker must
    /// implement to take a tenant: a job runs outside any request, so its tenant is
    /// lost unless the job carries it. Take `tenant` from the auth crate's `Tenant`,
    /// as `tenant.as_str()`, never from what a caller sent.
    ///
    /// # Errors
    ///
    /// Fails for a tenant that is not a tenant id, when queueing fails, no queue is
    /// configured, or a foreground job fails.
    async fn perform_later_for(ctx: &AppContext, tenant: &str, args: A) -> Result<String>
    where
        Self: Sized + 'static,
    {
        if !is_tenant_id(tenant) {
            return Err(Error::BadRequest(
                "a job's tenant must be a tenant id".to_string(),
            ));
        }
        let tenant = tenant.to_string();
        match ctx.config.workers {
            WorkerMode::BackgroundQueue => {
                #[cfg(feature = "queue")]
                {
                    let job = crate::queue::job::<Self, A>(&args)?.tenant(tenant);
                    enqueue(ctx, &job).await
                }
                #[cfg(not(feature = "queue"))]
                {
                    let _ = (args, tenant);
                    no_queue()
                }
            }
            WorkerMode::ForegroundBlocking => {
                Self::build(ctx).perform_for(Some(tenant), args).await?;
                Ok(Uuid::new_v4().to_string())
            }
            WorkerMode::BackgroundAsync => {
                let worker = Self::build(ctx);
                tokio::spawn(async move {
                    if let Err(error) = worker.perform_for(Some(tenant), args).await {
                        tracing::error!(%error, "background job failed");
                    }
                });
                Ok(Uuid::new_v4().to_string())
            }
        }
    }

    /// Tries a job of this worker gets with the queue, including the first.
    /// `None` uses `QueueOptions::max_attempts`. Set it only for work that is
    /// safe to repeat.
    #[must_use]
    fn max_attempts() -> Option<i32>
    where
        Self: Sized,
    {
        None
    }

    /// How long a run of this worker's job may take before it is stopped and
    /// counted as failed. `None`, the default, sets no limit: a job has one only
    /// when its worker says so.
    #[must_use]
    fn timeout() -> Option<Duration>
    where
        Self: Sized,
    {
        None
    }

    /// The job's work.
    async fn perform(&self, args: A) -> Result<()>;

    /// The job's work for `tenant`, the tenant it was queued for, or `None`. A worker
    /// whose jobs run for a tenant implements this, and opens its own tenant
    /// transaction with it. By default a job with no tenant goes to
    /// [`BackgroundWorker::perform`], and a job with one is refused, as `perform`
    /// would run it with no tenant.
    ///
    /// # Errors
    ///
    /// By default, for a job with a tenant, and otherwise as `perform`.
    async fn perform_for(&self, tenant: Option<String>, args: A) -> Result<()> {
        match tenant {
            None => self.perform(args).await,
            Some(_) => Err(Error::Worker(
                "the job has a tenant, and its worker takes none: implement perform_for"
                    .to_string(),
            )),
        }
    }
}

/// Whether `id` is a tenant id, as the auth crates' `Tenant` and the job queue hold
/// it: 1 to 63 lower-case letters, digits, and hyphens, not starting or ending with a
/// hyphen.
fn is_tenant_id(id: &str) -> bool {
    (1..=63).contains(&id.len())
        && !id.starts_with('-')
        && !id.ends_with('-')
        && id
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
}

/// Add a job to the context's queue.
#[cfg(feature = "queue")]
async fn enqueue(ctx: &AppContext, job: &crate::queue::NewJob) -> Result<String> {
    let queue = ctx
        .queue_provider
        .as_ref()
        .ok_or_else(|| Error::Worker("no job queue configured".to_string()))?;
    queue.enqueue_job(job).await
}

/// Without the `queue` feature there is nowhere to put a job.
#[cfg(not(feature = "queue"))]
fn no_queue() -> Result<String> {
    Err(Error::Worker("no job queue configured".to_string()))
}

#[cfg(all(
    test,
    not(any(
        axa_db = "postgres_seaorm",
        axa_db = "mysql_seaorm",
        axa_db = "sqlite_seaorm",
        axa_db = "postgres_toasty",
        axa_db = "mysql_toasty"
    )),
    not(feature = "queue")
))]
mod tests {
    use super::*;
    use crate::{
        Environment,
        config::{Config, Defaults},
    };
    use serde::Deserialize;
    use std::sync::atomic::{AtomicUsize, Ordering};

    static DONE: AtomicUsize = AtomicUsize::new(0);

    #[derive(Serialize, Deserialize)]
    struct Args {
        amount: usize,
        fail: bool,
    }

    struct AddWorker;

    #[async_trait]
    impl BackgroundWorker<Args> for AddWorker {
        fn build(_ctx: &AppContext) -> Self {
            Self
        }

        async fn perform(&self, args: Args) -> Result<()> {
            if args.fail {
                return Err(Error::Worker("told to fail".to_string()));
            }
            DONE.fetch_add(args.amount, Ordering::SeqCst);
            Ok(())
        }
    }

    fn context(mode: &str) -> AppContext {
        let defaults = Defaults {
            database: "",
            ..Defaults::default()
        };
        let config = Config::from_lookup(&Environment::Test, &defaults, |name| {
            (name == "WORKER_MODE").then(|| mode.to_string())
        })
        .unwrap();
        AppContext::for_test(Environment::Test, config)
    }

    #[test]
    fn class_name_is_the_bare_type_name() {
        assert_eq!(AddWorker::class_name(), "AddWorker");
    }

    #[tokio::test]
    async fn foreground_jobs_run_before_returning_and_report_failure() {
        let ctx = context("ForegroundBlocking");
        let before = DONE.load(Ordering::SeqCst);
        AddWorker::perform_later(
            &ctx,
            Args {
                amount: 3,
                fail: false,
            },
        )
        .await
        .unwrap();
        assert!(DONE.load(Ordering::SeqCst) >= before + 3);
        assert!(
            AddWorker::perform_later(
                &ctx,
                Args {
                    amount: 0,
                    fail: true
                }
            )
            .await
            .is_err()
        );
    }

    struct TenantWorker;

    static TENANTS: std::sync::Mutex<Vec<Option<String>>> = std::sync::Mutex::new(Vec::new());

    #[async_trait]
    impl BackgroundWorker<()> for TenantWorker {
        fn build(_ctx: &AppContext) -> Self {
            Self
        }

        async fn perform(&self, (): ()) -> Result<()> {
            Err(Error::Worker("needs a tenant".to_string()))
        }

        async fn perform_for(&self, tenant: Option<String>, (): ()) -> Result<()> {
            TENANTS.lock().unwrap().push(tenant);
            Ok(())
        }
    }

    #[tokio::test]
    async fn a_job_for_a_tenant_reaches_perform_for_and_a_worker_that_takes_none_refuses_it() {
        let ctx = context("ForegroundBlocking");
        TenantWorker::perform_later_for(&ctx, "acme", ())
            .await
            .unwrap();
        assert_eq!(*TENANTS.lock().unwrap(), vec![Some("acme".to_string())]);
        let args = Args {
            amount: 1,
            fail: false,
        };
        let error = AddWorker::perform_later_for(&ctx, "acme", args)
            .await
            .unwrap_err();
        assert!(error.to_string().contains("perform_for"), "{error}");
        for bad in ["", "Acme", "acme-", &"a".repeat(64)] {
            let error = TenantWorker::perform_later_for(&ctx, bad, ())
                .await
                .unwrap_err();
            assert!(matches!(error, Error::BadRequest(_)), "{bad:?}");
        }
        assert_eq!(TENANTS.lock().unwrap().len(), 1);
    }

    #[tokio::test]
    async fn queued_jobs_fail_without_a_queue() {
        let ctx = context("BackgroundQueue");
        let error = AddWorker::perform_later(
            &ctx,
            Args {
                amount: 1,
                fail: false,
            },
        )
        .await
        .unwrap_err();
        assert!(error.to_string().contains("no job queue"));
    }
}
